class _FsckMalformed(Exception):
    """Raised when INDEX_FORMAT_CHECK fsck refuses to create a malformed object.

    Carries the list of ``error:`` lines git would print (each already including
    the ``object fails fsck: <camelCased>: <message>`` text, plus any preceding
    bare ``error:`` lines such as ``too-short tree object``) so the caller can
    reproduce git's stderr byte-for-byte before the final fatal message.
    """

    def __init__(self, lines: list[str]):
        super().__init__("refusing to create malformed object")
        self.lines = lines


def _parse_timestamp_skip(buf: bytes, i: int, end: int) -> int:
    """Mimic git's parse_timestamp_from_buf: skip leading ws then digits.

    Returns the index just past the consumed timestamp digits.  git uses
    strtoumax which skips leading whitespace; fsck_ident has already skipped
    spaces/tabs and confirmed a digit follows, so here we simply consume the
    run of decimal digits.
    """
    while i < end and 0x30 <= buf[i] <= 0x39:
        i += 1
    return i


def _fsck_ident(buf: bytes, start: int, end: int) -> Optional[tuple[str, str]]:
    """Port of fsck_ident (builtin fsck.c). buf[start:] begins after 'author '
    or 'committer '/'tagger '.  Returns None when valid, else (camelId, msg)."""
    p = start
    nl = buf.find(b"\n", p, end)
    if nl < 0:
        # verify_headers guarantees a newline; treat as missing email.
        nl = end
    if p < end and buf[p] == 0x3C:  # '<'
        return ("missingNameBeforeEmail",
                "invalid author/committer line - missing space before email")
    while True:
        if p >= end or buf[p] == 0x0A:
            return ("missingEmail",
                    "invalid author/committer line - missing email")
        if buf[p] == 0x3E:  # '>'
            return ("badName", "invalid author/committer line - bad name")
        if buf[p] == 0x3C:  # '<'
            break
        p += 1
    if buf[p - 1] != 0x20:  # not ' '
        return ("missingSpaceBeforeEmail",
                "invalid author/committer line - missing space before email")
    p += 1
    while True:
        if p >= end or buf[p] in (0x3C, 0x0A):  # '<' or '\n'
            return ("badEmail", "invalid author/committer line - bad email")
        if buf[p] == 0x3E:  # '>'
            break
        p += 1
    p += 1
    if p >= end or buf[p] != 0x20:
        return ("missingSpaceBeforeDate",
                "invalid author/committer line - missing space before date")
    p += 1
    while p < end and buf[p] in (0x20, 0x09):
        p += 1
    if p >= end or not (0x30 <= buf[p] <= 0x39):
        return ("badDate", "invalid author/committer line - bad date")
    if buf[p] == 0x30 and (p + 1 >= end or buf[p + 1] != 0x20):
        return ("zeroPaddedDate",
                "invalid author/committer line - zero-padded date")
    p = _parse_timestamp_skip(buf, p, end)
    if p >= end or buf[p] != 0x20:
        return ("badDate", "invalid author/committer line - bad date")
    p += 1
    if (p + 5 >= end
            or buf[p] not in (0x2B, 0x2D)  # '+' '-'
            or not all(0x30 <= buf[p + k] <= 0x39 for k in range(1, 5))
            or buf[p + 5] != 0x0A):
        return ("badTimezone", "invalid author/committer line - bad time zone")
    return None


def _fsck_verify_headers(buf: bytes) -> Optional[tuple[str, str]]:
    """Port of verify_headers(). Returns None if OK, else (camelId, msg)."""
    size = len(buf)
    for i in range(size):
        c = buf[i]
        if c == 0x00:
            return ("nulInHeader",
                    "unterminated header: NUL at offset %d" % i)
        if c == 0x0A:
            if i + 1 < size and buf[i + 1] == 0x0A:
                return None
    if size and buf[size - 1] == 0x0A:
        return None
    return ("unterminatedHeader", "unterminated header")


def _fsck_commit(buf: bytes) -> list[tuple[str, str]]:
    """Port of fsck_commit. Returns list of (camelId, message) errors; the
    first reported error makes git die (error_func returns 1), so callers
    only need the first.  Bare-error prefixes are unused for commits."""
    hdr = _fsck_verify_headers(buf)
    if hdr is not None:
        return [hdr]
    end = len(buf)
    p = 0
    if not buf.startswith(b"tree "):
        return [("missingTree", "invalid format - expected 'tree' line")]
    p = 5
    # tree sha1
    nl = buf.find(b"\n", p, end)
    hexpart = buf[p:nl if nl >= 0 else end]
    if len(hexpart) != 40 or any(c not in b"0123456789abcdef" for c in hexpart):
        return [("badTreeSha1", "invalid 'tree' line format - bad sha1")]
    p = (nl + 1) if nl >= 0 else end
    while p < end and buf[p:].startswith(b"parent "):
        p2 = p + 7
        nl = buf.find(b"\n", p2, end)
        hexpart = buf[p2:nl if nl >= 0 else end]
        if len(hexpart) != 40 or any(c not in b"0123456789abcdef" for c in hexpart):
            return [("badParentSha1", "invalid 'parent' line format - bad sha1")]
        p = (nl + 1) if nl >= 0 else end
    author_count = 0
    while p < end and buf[p:].startswith(b"author "):
        author_count += 1
        bad = _fsck_ident(buf, p + 7, end)
        if bad is not None:
            return [bad]
        nl = buf.find(b"\n", p + 7, end)
        p = (nl + 1) if nl >= 0 else end
    if author_count < 1:
        return [("missingAuthor", "invalid format - expected 'author' line")]
    if author_count > 1:
        return [("multipleAuthors", "invalid format - multiple 'author' lines")]
    if p >= end or not buf[p:].startswith(b"committer "):
        return [("missingCommitter", "invalid format - expected 'committer' line")]
    bad = _fsck_ident(buf, p + 10, end)
    if bad is not None:
        return [bad]
    if b"\x00" in buf:
        return [("nulInCommit", "NUL byte in the commit object body")]
    return []


def _fsck_tag(buf: bytes) -> list[tuple[str, str]]:
    """Port of fsck_tag_standalone (the parts reachable from hash-object)."""
    hdr = _fsck_verify_headers(buf)
    if hdr is not None:
        return [hdr]
    end = len(buf)
    p = 0
    if not buf.startswith(b"object "):
        return [("missingObject", "invalid format - expected 'object' line")]
    p = 7
    nl = buf.find(b"\n", p, end)
    hexpart = buf[p:nl if nl >= 0 else end]
    if len(hexpart) != 40 or any(c not in b"0123456789abcdef" for c in hexpart):
        return [("badObjectSha1", "invalid 'object' line format - bad sha1")]
    p = (nl + 1) if nl >= 0 else end
    if p >= end or not buf[p:].startswith(b"type "):
        return [("missingTypeEntry", "invalid format - expected 'type' line")]
    p += 5
    eol = buf.find(b"\n", p, end)
    if eol < 0:
        return [("missingType", "invalid format - unexpected end after 'type' line")]
    typename = buf[p:eol]
    if typename not in (b"blob", b"tree", b"commit", b"tag"):
        return [("badType", "invalid 'type' value")]
    p = eol + 1
    if p >= end or not buf[p:].startswith(b"tag "):
        return [("missingTagEntry", "invalid format - expected 'tag' line")]
    p += 4
    eol = buf.find(b"\n", p, end)
    if eol < 0:
        return [("missingTag", "invalid format - unexpected end after 'type' line")]
    tagname = buf[p:eol]
    try:
        refstr = "refs/tags/" + tagname.decode("utf-8", "surrogateescape")
        invalid = _check_refname_invalid(refstr)
    except Exception:
        invalid = True
    if invalid:
        return [("badTagName",
                 "invalid 'tag' name: " + tagname.decode("utf-8", "surrogateescape"))]
    p = eol + 1
    if p >= end or not buf[p:].startswith(b"tagger "):
        return [("missingTaggerEntry", "invalid format - expected 'tagger' line")]
    bad = _fsck_ident(buf, p + 7, end)
    if bad is not None:
        return [bad]
    return []


def _parse_tree_mode(buf: bytes, i: int, end: int) -> Optional[tuple[int, int]]:
    """Port of parse_mode: octal mode digits then a single space.
    Returns (mode, index_after_space) or None on malformed mode."""
    mode = 0
    start = i
    while i < end and 0x30 <= buf[i] <= 0x37:
        mode = (mode << 3) | (buf[i] - 0x30)
        i += 1
    if i == start or i >= end or buf[i] != 0x20:
        return None
    return (mode, i + 1)


def _fsck_tree(buf: bytes) -> list[tuple[list[str], str, str]]:
    """Port of the parts of fsck_tree reachable from hash-object's format check.

    Returns a list where each item is (bare_error_lines, camelId, message).
    For the malformed-parse case git first prints a bare ``error: too-short
    tree object`` (from init_tree_desc_gently) and then the fsck report
    ``badTree: cannot be parsed as a tree``.
    """
    size = len(buf)
    hashsz = 20
    # init_tree_desc_internal -> decode_tree_entry on the first entry.
    if size:
        if size < hashsz + 3 or buf[size - (hashsz + 1)] != 0:
            return [(["too-short tree object"], "badTree",
                     "cannot be parsed as a tree")]
        pm = _parse_tree_mode(buf, 0, size)
        if pm is None:
            return [(["malformed mode in tree entry"], "badTree",
                     "cannot be parsed as a tree")]
        mode, after = pm
        nul = buf.find(b"\x00", after, size)
        if nul == after:
            return [(["empty filename in tree entry"], "badTree",
                     "cannot be parsed as a tree")]
    return []


def _fsck_format_check(obj_type: str, data: bytes) -> None:
    """Replicate index_mem's INDEX_FORMAT_CHECK gate (object-file.c).

    On the first fsck error, git's error_func returns 1 and index_mem dies
    with ``refusing to create malformed object``.  We raise _FsckMalformed
    carrying the exact stderr lines.
    """
    if obj_type == "blob":
        return
    if obj_type == "commit":
        errs = _fsck_commit(data)
        for camel, msg in errs[:1]:
            raise _FsckMalformed(
                ["error: object fails fsck: %s: %s" % (camel, msg)])
        return
    if obj_type == "tag":
        errs = _fsck_tag(data)
        for camel, msg in errs[:1]:
            raise _FsckMalformed(
                ["error: object fails fsck: %s: %s" % (camel, msg)])
        return
    if obj_type == "tree":
        errs = _fsck_tree(data)
        for bare, camel, msg in errs[:1]:
            lines = ["error: " + b for b in bare]
            lines.append("error: object fails fsck: %s: %s" % (camel, msg))
            raise _FsckMalformed(lines)
        return


def cmd_hash_object(argv: list[str]) -> int:
    # git's -t is OPT_STRING: any string is accepted at parse time and validated
    # later by type_from_string (-> "fatal: invalid object type ...", rc 128).
    # A bare trailing -t (no value) is a parse-options error (rc 129), with no
    # usage block.  Detect that before argparse (which would say rc 2 instead).
    for k, a in enumerate(argv):
        if a == "-t" and k == len(argv) - 1:
            _err("error: switch `t' requires a value")
            return 129
    ap = argparse.ArgumentParser(prog="pygit hash-object", add_help=False)
    ap.add_argument("-w", action="store_true", help="write object")
    ap.add_argument("-t", default="blob")
    ap.add_argument("--stdin", action="count", default=0)
    ap.add_argument("--stdin-paths", action="store_true")
    ap.add_argument("--literally", action="store_true")
    ap.add_argument("--no-filters", dest="no_filters", action="store_true")
    ap.add_argument("--filters", dest="no_filters", action="store_false")
    ap.add_argument("--path", default=None)
    ap.add_argument("files", nargs="*")
    args = ap.parse_args(argv)
    # type_from_string: only commit/tree/blob/tag are valid object types.  An
    # unknown/uppercase/empty type dies the same way even with --literally.
    if args.t not in ("commit", "tree", "blob", "tag"):
        _err('fatal: invalid object type "%s"' % args.t)
        return 128
    repo = None
    try:
        repo = _repo()
    except RepositoryError:
        pass

    def usage_error(msg: str) -> int:
        _err("error: " + msg)
        sys.stderr.write(_HASH_OBJECT_USAGE)
        return 129

    # Resolve --path against the cwd-relative prefix, matching git's vpath.
    vpath = args.path
    prefix = ""
    if repo is not None:
        try:
            rel = os.path.relpath(os.getcwd(), str(repo.path))
            if rel not in (".", ""):
                prefix = rel.replace(os.sep, "/") + "/"
        except ValueError:
            prefix = ""
    if vpath is not None and prefix:
        vpath = prefix + vpath

    # Argument-combination checks (builtin/hash-object.c).
    if args.stdin_paths:
        if args.stdin:
            return usage_error("Can't use --stdin-paths with --stdin")
        if args.files:
            return usage_error("Can't specify files with --stdin-paths")
        if vpath is not None:
            return usage_error("Can't use --stdin-paths with --path")
    else:
        if args.stdin > 1:
            return usage_error("Multiple --stdin arguments are not supported")
        if vpath is not None and args.no_filters:
            return usage_error("Can't use --path with --no-filters")

    from . import convert as _convert

    def emit(raw: bytes, conv_path: Optional[str]) -> int:
        data = raw
        if args.t == "blob" and conv_path is not None:
            try:
                data, warn = _convert.convert_to_git(repo, conv_path, raw, args.w)
            except _convert.SafeCrlfDie as exc:
                # core.safecrlf=true: the round-trip would lose EOLs.
                _err("fatal: %s" % exc)
                return 128
            except _convert.ConvertDie as exc:
                # A die() reachable from convert_to_git (a required clean filter
                # that failed, or a working-tree-encoding BOM / encode error
                # while writing the object).  Some carry a hint: advice line
                # that git prints before the fatal message.
                if exc.advice:
                    _err(exc.advice)
                _err("fatal: %s" % exc)
                return 128
            else:
                if warn:
                    _err(warn)
        # INDEX_FORMAT_CHECK (object-file.c index_mem): unless --literally was
        # given, fsck the object and refuse to create a malformed one.
        if not args.literally:
            try:
                _fsck_format_check(args.t, data)
            except _FsckMalformed as exc:
                for line in exc.lines:
                    _err(line)
                _err("fatal: refusing to create malformed object")
                return 128
        if args.w:
            _print(objs.write_object(repo, args.t, data))
        else:
            _print(objs.hash_bytes(args.t, data, repo)[0])
        return 0

    def read_file(open_name: str, display: str) -> Optional[bytes]:
        """Read a file the way git's xopen + index_fd do, with git's errors.

        git chdir's to the repository top and opens ``prefix + name`` from
        there; we stay in the caller's cwd, so the file is reached by opening
        ``open_name`` relative to cwd, while error messages use ``display``
        (the prefix-prepended path git would print).
        """
        try:
            fd = os.open(open_name, os.O_RDONLY)
        except OSError as exc:
            _err(
                "fatal: could not open '%s' for reading: %s"
                % (display, os.strerror(exc.errno))
            )
            return None
        try:
            st = os.fstat(fd)
            if not _stat_is_reg(st.st_mode):
                # Directories / non-regular: git tries to read and fails.
                _err("fatal: Unable to hash %s" % display)
                return None
            data = b""
            while True:
                chunk = os.read(fd, 65536)
                if not chunk:
                    break
                data += chunk
            return data
        finally:
            os.close(fd)

    # Order mirrors builtin/hash-object.c: --stdin first, then files, then
    # --stdin-paths.
    if args.stdin:
        rc = emit(sys.stdin.buffer.read(), None if args.no_filters else vpath)
        if rc:
            return rc

    for name in args.files:
        display = prefix + name if prefix else name
        raw = read_file(name, display)
        if raw is None:
            return 128
        conv = None if args.no_filters else (vpath if vpath is not None else display)
        rc = emit(raw, conv)
        if rc:
            return rc

    if args.stdin_paths:
        for line in sys.stdin.read().splitlines():
            if not line:
                continue
            name = line
            if line.startswith('"'):
                try:
                    name = _unquote_c_style(line)
                except ValueError:
                    _err("fatal: line is badly quoted")
                    return 128
            raw = read_file(name, name)
            if raw is None:
                return 128
            conv = None if args.no_filters else name
            rc = emit(raw, conv)
            if rc:
                return rc

    return 0


def _stat_is_reg(mode: int) -> bool:
    import stat as _stat

    return _stat.S_ISREG(mode)


def _unquote_c_style(s: str) -> str:
    """Minimal C-style unquoting for double-quoted --stdin-paths lines."""
    if not (s.startswith('"') and s.endswith('"') and len(s) >= 2):
        raise ValueError("badly quoted")
    body = s[1:-1]
    out = bytearray()
    i = 0
    simple = {
        "a": 7, "b": 8, "f": 12, "n": 10, "r": 13, "t": 9, "v": 11,
        "\\": 92, '"': 34,
    }
    while i < len(body):
        c = body[i]
        if c == "\\":
            i += 1
            if i >= len(body):
                raise ValueError("badly quoted")
            e = body[i]
            if e in simple:
                out.append(simple[e])
                i += 1
            elif e in "01234567":
                oct_digits = e
                i += 1
                while i < len(body) and body[i] in "01234567" and len(oct_digits) < 3:
                    oct_digits += body[i]
                    i += 1
                out.append(int(oct_digits, 8) & 0xFF)
            else:
                raise ValueError("badly quoted")
        else:
            out.extend(c.encode("utf-8"))
            i += 1
    return out.decode("utf-8", "surrogateescape")


def _loose_object_shas(repo: Repository) -> set[str]:
    """Every loose object id in the repo."""
    shas: set[str] = set()
    objdir = repo.gitdir / "objects"
    hex_len = repo.hex_len
    if objdir.is_dir():
        for d in objdir.iterdir():
            if d.is_dir() and len(d.name) == 2 and all(c in "0123456789abcdef" for c in d.name):
                for f in d.iterdir():
                    if f.is_file() and len(f.name) == hex_len - 2:
                        shas.add(d.name + f.name)
    return shas


def _all_object_shas(repo: Repository) -> list[str]:
    """Every object id in the repo (loose + packed), sorted ascending — the
    order `cat-file --batch-all-objects` emits."""
    shas: set[str] = set(_loose_object_shas(repo))
    from . import pack as _p
    midx = _p.read_midx(repo)
    if midx is not None:
        shas.update(midx.shas)
    else:
        for pk in _p._iter_packs(repo):
            shas.update(pk.shas)
    return sorted(shas)


def _all_object_shas_unordered(repo: Repository) -> list[str]:
    """Object ids in `cat-file --batch-all-objects --unordered` order: loose
    objects (sorted) first, then packed objects in pack-offset order, with
    later duplicates suppressed (the first occurrence wins)."""
    seen: set[str] = set()
    out: list[str] = []
    for sha in sorted(_loose_object_shas(repo)):
        if sha not in seen:
            seen.add(sha)
            out.append(sha)
    from . import pack as _p
    midx = _p.read_midx(repo)
    if midx is not None:
        # MIDX exposes objects in oid-sorted order with their (pack, offset);
        # emit pack-by-pack, each in offset order, matching git's pack walk.
        packs: dict[int, list[tuple[int, str]]] = {}
        for i, sha in enumerate(midx.shas):
            packs.setdefault(midx.pack_ids[i], []).append((midx.offsets[i], sha))
        for pid in sorted(packs):
            for _off, sha in sorted(packs[pid]):
                if sha not in seen:
                    seen.add(sha)
                    out.append(sha)
    else:
        # git's repo_for_each_pack walks packs most-recent-first (the packed_git
        # list is sorted by descending mtime); replicate that ordering here.
        packs = list(_p._iter_packs(repo))
        def _mtime(pk):
            try:
                return pk.pack_path.stat().st_mtime_ns
            except OSError:
                return 0
        packs.sort(key=lambda pk: (-_mtime(pk), pk.pack_path.name))
        for pk in packs:
            pairs = sorted((pk.offset_of(s), s) for s in pk.shas)
            for _off, sha in pairs:
                if sha not in seen:
                    seen.add(sha)
                    out.append(sha)
    return out


def _split_ident_line(person: bytes):
    """Split a `Name <email> timestamp tz` ident into (name, email, rest).

    Mirrors git's split_ident_line enough for mailmap rewriting: ``name`` is the
    text before the last ``<`` (trailing space trimmed), ``email`` is between the
    final ``<``/``>``, ``rest`` is everything from ``>`` onward (including the
    space + date). Returns None when the line has no well-formed ``<email>``."""
    lt = person.rfind(b"<")
    if lt < 0:
        return None
    gt = person.find(b">", lt + 1)
    if gt < 0:
        return None
    name_end = lt
    # git trims a single run of trailing whitespace before '<'
    while name_end > 0 and person[name_end - 1:name_end] in (b" ", b"\t"):
        name_end -= 1
    name = person[:name_end]
    email = person[lt + 1:gt]
    rest = person[gt + 1:]
    return name, email, rest


def _replace_idents_using_mailmap(buf: bytes, mm) -> bytes:
    """Rewrite author/committer/tagger ``Name <email>`` idents in a commit/tag
    object body through the mailmap, preserving the trailing timestamp. Only the
    contiguous header block (up to the first blank line) is scanned, matching
    git's apply_mailmap_to_header."""
    headers = (b"author ", b"committer ", b"tagger ")
    out: list[bytes] = []
    i = 0
    n = len(buf)
    in_headers = True
    while i < n:
        nl = buf.find(b"\n", i)
        if nl < 0:
            line = buf[i:]
            nxt = n
            has_nl = False
        else:
            line = buf[i:nl]
            nxt = nl + 1
            has_nl = True
        if in_headers:
            if line == b"":
                in_headers = False
            else:
                matched = None
                for h in headers:
                    if line.startswith(h):
                        matched = h
                        break
                if matched is not None:
                    person = line[len(matched):]
                    split = _split_ident_line(person)
                    if split is not None:
                        name, email, rest = split
                        try:
                            nm = name.decode("utf-8")
                            em = email.decode("utf-8")
                        except UnicodeDecodeError:
                            nm = name.decode("latin-1")
                            em = email.decode("latin-1")
                        new_name, new_email = mm.resolve(nm, em)
                        new_person = (matched
                                      + new_name.encode("utf-8")
                                      + b" <" + new_email.encode("utf-8") + b">"
                                      + rest)
                        line = new_person
        out.append(line)
        if has_nl:
            out.append(b"\n")
        i = nxt
    return b"".join(out)


def _expand_batch_atoms(fmt: str, sha: str, t: str, size: int,
                        repo: "Repository" = None, rest: str = "") -> str:
    """Expand the `cat-file --batch[-check]=<format>` %(atom) placeholders.

    %(objectsize:disk) is the on-disk representation size (the loose file's
    bytes, or the packed entry's size); %(deltabase) is the delta base oid
    (all-zeros for a non-delta object); %(rest) is the remainder of the input
    record after the first run of whitespace (used with --batch-check)."""
    if "%(objectsize:disk)" in fmt or "%(deltabase)" in fmt:
        disk = _object_disk_size(repo, sha) if repo is not None else size
        base = _batch_delta_base(repo, sha) if repo is not None else ("0" * len(sha))
        fmt = (fmt.replace("%(objectsize:disk)", str(disk))
                  .replace("%(deltabase)", base))
    return (fmt.replace("%(objectname)", sha)
               .replace("%(objecttype)", t)
               .replace("%(objectsize)", str(size))
               .replace("%(rest)", rest))


def _batch_delta_base(repo: "Repository", sha: str) -> str:
    """Return %(deltabase): the oid this object is a delta against, or an
    all-zeros oid when it is stored whole (loose, or a non-delta pack entry).
    Mirrors cat-file's data.delta_base_oid handling."""
    zero = "0" * repo.hex_len
    if objs._loose_path(repo, sha).exists():
        return zero
    try:
        from . import pack as _pack
        for pk in _pack._iter_packs(repo):
            off = pk.offset_of(sha)
            if off is None:
                continue
            pk._load()
            data = pk._mm
            obj_type, _size, pos = _pack._read_var_size(data, off)
            if obj_type == _pack.OBJ_OFS_DELTA:
                neg, _pos = _pack._read_offset(data, pos)
                base_off = off - neg
                off_to_oid = {pk.offset_of(s): s for s in pk.shas}
                return off_to_oid.get(base_off, zero)
            if obj_type == _pack.OBJ_REF_DELTA:
                return data[pos:pos + pk.hash_len].hex()
            return zero
    except Exception:
        pass
    return zero


def _read_delimited_stdin(input_delim: str):
    """Yield records from stdin split on ``input_delim`` ('\\n' or '\\0').

    For newline-delimited input a trailing ``\\r`` is stripped (git's
    strbuf_getdelim_strip_crlf). The final record is dropped when it is empty
    (no trailing data after the last delimiter)."""
    raw = sys.stdin.buffer.read()
    delim = b"\0" if input_delim == "\0" else b"\n"
    if not raw:
        return
    parts = raw.split(delim)
    # split() leaves a trailing empty element when the stream ends with the
    # delimiter; git stops at EOF so that trailing empty is not a record.
    if parts and parts[-1] == b"":
        parts.pop()
    for p in parts:
        if delim == b"\n" and p.endswith(b"\r"):
            p = p[:-1]
        yield p.decode("utf-8", "surrogateescape")


def _split_rev_colon_path(name: str):
    """Split ``<rev>:<path>`` at the first ``:`` that is not inside an ``@{``/
    ``^{`` bracket group, mirroring git's get_oid_with_context_1 scan. Returns
    ``(rev, path)`` or None when there is no such colon."""
    depth = 0
    i = 0
    n = len(name)
    while i < n:
        c = name[i]
        if c in "@^" and i + 1 < n and name[i + 1] == "{":
            i += 2
            depth += 1
            continue
        if depth and c == "}":
            depth -= 1
        elif not depth and c == ":":
            return name[:i], name[i + 1:]
        i += 1
    return None


# Git follows at most this many symlinks before declaring a loop
# (GET_TREE_ENTRY_FOLLOW_SYMLINKS_MAX_LINKS in tree-walk.c).
_FOLLOW_SYMLINKS_MAX = 40


def _follow_symlinks_in_tree(repo, root_tree_sha: str, name: str):
    """Resolve ``name`` within the tree ``root_tree_sha`` following in-tree
    symlinks, mirroring git's get_tree_entry_follow_symlinks.

    Returns one of:
      ("found", sha, mode_int)  -- in-tree object (mode != 0)
      ("symlink", path)         -- chain left the tree (absolute/escaping ..)
      ("dangling",)             -- a symlink target does not exist in the tree
      ("loop",)                 -- too many symlinks followed
      ("notdir",)               -- a path component was a non-dir with remainder
      ("missing",)              -- component not found / no symlink involved
    """
    # parents[i] = (tree_data, tree_sha); parents[-1] is the current tree.
    parents: list[tuple[bytes, str]] = []
    namebuf = name
    current_tree_sha = root_tree_sha
    t_loaded = False
    follows_remaining = _FOLLOW_SYMLINKS_MAX
    # On error after at least one symlink follow, git reports DANGLING_SYMLINK.
    followed_any = False

    def load_tree(sha):
        try:
            ot, data = objs.read_object(repo, sha)
        except KeyError:
            return None
        if ot != "tree":
            return None
        return data

    while True:
        if not t_loaded:
            tree = load_tree(current_tree_sha)
            if tree is None:
                return ("dangling",) if followed_any else ("missing",)
            parents.append((tree, current_tree_sha))
            if namebuf == "":
                return ("found", current_tree_sha, 0o040000)
            if not tree:
                return ("dangling",) if followed_any else ("missing",)
            t_loaded = True

        # Strip leading slashes (symlinks to e.g. a//b).
        while namebuf.startswith("/"):
            namebuf = namebuf[1:]

        slash = namebuf.find("/")
        if slash >= 0:
            first = namebuf[:slash]
            remainder = namebuf[slash + 1:]
        else:
            first = namebuf
            remainder = None

        if first == "..":
            if len(parents) == 1:
                # Escaped the root of the tree.
                return ("symlink", namebuf)
            parents.pop()
            current_tree_sha = parents[-1][1]
            namebuf = namebuf[3:] if remainder is not None else namebuf[2:]
            t_loaded = True
            continue

        if first == "":
            # Reached here via a symlink to dir/.. -> the current tree.
            return ("found", parents[-1][1], 0o040000)

        tree_data = parents[-1][0]
        entry = next((e for e in objs.parse_tree(tree_data, repo.hash_len)
                      if e.name == first), None)
        if entry is None:
            return ("dangling",) if followed_any else ("missing",)

        mode = int(entry.mode, 8)
        if entry.is_dir():
            if remainder is None:
                return ("found", entry.sha, mode)
            current_tree_sha = entry.sha
            namebuf = remainder
            t_loaded = False
            continue
        # 0o170000 == S_IFMT
        ftype = mode & 0o170000
        if ftype == 0o120000:
            # symlink
            if follows_remaining == 0:
                return ("loop",)
            follows_remaining -= 1
            followed_any = True
            try:
                lt, contents = objs.read_object(repo, entry.sha)
            except KeyError:
                return ("dangling",)
            link = contents.decode("utf-8", "surrogateescape")
            if link.startswith("/"):
                return ("symlink", link)
            # Splice the link target in place of the consumed component.
            namebuf = link + ("/" + remainder if remainder is not None else "")
            # Re-resolve from the directory containing the symlink.
            current_tree_sha = parents[-1][1]
            t_loaded = True
            continue
        # regular file (or gitlink)
        if remainder is None:
            return ("found", entry.sha, mode)
        return ("notdir",)


def _batch_resolve(repo: Repository, name: str, mm=None):
    """Resolve ``name`` for batch mode. Returns (sha, type, size, data) where
    ``data`` is the (mailmap-rewritten) object contents, or None if missing.

    With ``mm`` set, commit/tag idents are rewritten and ``size`` reflects the
    rewritten content (matching git --use-mailmap)."""
    sha = refs_mod.rev_parse(repo, name)
    if sha is None or not objs.object_exists(repo, sha):
        return None
    t, data = objs.read_object(repo, sha)
    if mm is not None and t in ("commit", "tag"):
        data = _replace_idents_using_mailmap(data, mm)
    return sha, t, len(data), data


def _batch_write_record(info: str, data, check_only: bool, output_delim: str,
                        buffer: bool) -> None:
    """Write one batch record: the formatted info line + delimiter, then (for
    --batch) the object contents + delimiter. Flushing is suppressed in buffer
    mode."""
    out = sys.stdout.buffer
    out.write(info.encode("utf-8", "surrogateescape"))
    out.write(output_delim.encode("latin-1"))
    if not check_only:
        if not buffer:
            out.flush()
        out.write(data)
        out.write(output_delim.encode("latin-1"))
    if not buffer:
        out.flush()


def _batch_follow_resolve(repo: Repository, name: str, mm=None):
    """Resolve ``name`` for batch mode with --follow-symlinks.

    Returns either:
      - a (status_word, payload) tuple for the special follow outputs
        ("dangling"/"loop"/"notdir" -> payload is ``name`` itself;
         "symlink" -> payload is the out-of-tree link path), to be emitted as
        ``<status> <len(payload)> <payload>``; or
      - the normal (sha, type, size, data) 4-tuple for a found object; or
      - None when the object is missing.

    Only ``<rev>:<path>`` names with a non-empty rev follow symlinks; every
    other name (plain rev, abbrev sha, ``:path`` index form) resolves exactly
    as ordinary batch mode."""
    split = _split_rev_colon_path(name)
    if split is None or split[0] == "":
        return _batch_resolve(repo, name, mm)
    rev, path = split
    base_sha = refs_mod._resolve_revision(repo, rev)
    if base_sha is None:
        return None
    tree_sha = refs_mod._peel_to_type(repo, base_sha, "tree")
    if tree_sha is None:
        return None
    res = _follow_symlinks_in_tree(repo, tree_sha, path)
    tag = res[0]
    if tag == "missing":
        return None
    if tag in ("dangling", "loop", "notdir"):
        return (tag, name)
    if tag == "symlink":
        return ("symlink", res[1])
    # found
    sha = res[1]
    if not objs.object_exists(repo, sha):
        return None
    t, data = objs.read_object(repo, sha)
    if mm is not None and t in ("commit", "tag"):
        data = _replace_idents_using_mailmap(data, mm)
    return sha, t, len(data), data


def _write_follow_special(status: str, payload: str, output_delim: str,
                          buffer: bool) -> None:
    """Emit a follow-symlinks special line: ``<status> <len> <payload>``,
    where lengths/payload use the configured output delimiter (matching git's
    ``printf("%s %zu%c%s%c", ...)``)."""
    out = sys.stdout.buffer
    pb = payload.encode("utf-8", "surrogateescape")
    out.write(f"{status} {len(pb)}".encode("utf-8"))
    out.write(output_delim.encode("latin-1"))
    out.write(pb)
    out.write(output_delim.encode("latin-1"))
    if not buffer:
        out.flush()


def _cat_file_batch(repo: Repository, check_only: bool, names=None, fmt=None,
                    mm=None, input_delim="\n", output_delim="\n",
                    buffer=False, follow_symlinks=False) -> int:
    if fmt is None:
        fmt = "%(objectname) %(objecttype) %(objectsize)"
    # %(rest) in the format means: split each input record at the first run of
    # whitespace; the leading field is the object name and the remainder feeds
    # %(rest) (cat-file.c split_on_whitespace).
    split_on_whitespace = "%(rest)" in fmt
    source = names if names is not None else _read_delimited_stdin(input_delim)
    out = sys.stdout.buffer
    for name in source:
        if names is None and not name:
            continue
        rest = ""
        if split_on_whitespace:
            name, rest = _batch_split_rest(name)
        resolved = (_batch_follow_resolve(repo, name, mm) if follow_symlinks
                    else _batch_resolve(repo, name, mm))
        if resolved is None:
            out.write((f"{name} missing").encode("utf-8", "surrogateescape"))
            out.write(output_delim.encode("latin-1"))
            if not buffer:
                out.flush()
            continue
        if resolved[0] in ("dangling", "loop", "notdir", "symlink"):
            _write_follow_special(resolved[0], resolved[1], output_delim, buffer)
            continue
        sha, t, size, data = resolved
        info = _expand_batch_atoms(fmt, sha, t, size, repo=repo, rest=rest)
        _batch_write_record(info, data, check_only, output_delim, buffer)
    if buffer:
        out.flush()
    return 0


def _batch_split_rest(line: str) -> tuple[str, str]:
    """Split a --batch-check record at the first run of whitespace (space/tab):
    return (object-name, rest). When there is no whitespace, rest is empty.
    Mirrors cat-file.c's split_on_whitespace handling."""
    i = 0
    n = len(line)
    while i < n and line[i] not in " \t":
        i += 1
    if i == n:
        return line, ""
    name = line[:i]
    while i < n and line[i] in " \t":
        i += 1
    return name, line[i:]


def _cat_file_batch_command(repo: Repository, fmt=None, mm=None,
                            input_delim="\n", output_delim="\n",
                            buffer=False, follow_symlinks=False) -> int:
    """cat-file --batch-command: per-line `info`/`contents`/`flush` requests.

    Without --buffer each command is run immediately; `flush` is rejected. With
    --buffer, `contents`/`info` are queued and only dispatched by `flush` (or at
    EOF)."""
    if fmt is None:
        fmt = "%(objectname) %(objecttype) %(objectsize)"
    out = sys.stdout.buffer

    def run(kind: str, arg: str) -> None:
        resolved = (_batch_follow_resolve(repo, arg, mm) if follow_symlinks
                    else _batch_resolve(repo, arg, mm))
        if resolved is None:
            out.write((f"{arg} missing").encode("utf-8", "surrogateescape"))
            out.write(output_delim.encode("latin-1"))
            out.flush()
            return
        if resolved[0] in ("dangling", "loop", "notdir", "symlink"):
            _write_follow_special(resolved[0], resolved[1], output_delim, buffer)
            if not buffer:
                out.flush()
            return
        sha, t, size, data = resolved
        info = _expand_batch_atoms(fmt, sha, t, size, repo=repo)
        _batch_write_record(info, data, kind == "info", output_delim, buffer)

    queued: list[tuple[str, str]] = []

    for line in _read_delimited_stdin(input_delim):
        if not line:
            _err("fatal: empty command in input")
            return 128
        if line[0] in (" ", "\t"):
            _err(f"fatal: whitespace before command: '{line}'")
            return 128
        if line.startswith("flush"):
            if line != "flush":
                _err("fatal: flush takes no arguments")
                return 128
            if not buffer:
                _err("fatal: flush is only for --buffer mode")
                return 128
            for kind, arg in queued:
                run(kind, arg)
            out.flush()
            queued.clear()
            continue
        matched = None
        for name in ("contents", "info"):
            if line.startswith(name):
                matched = name
                break
        if matched is None:
            _err(f"fatal: unknown command: '{line}'")
            return 128
        rest = line[len(matched):]
        # `contents`/`info` need exactly a space then the argument.
        if not rest.startswith(" "):
            _err(f"fatal: {matched} requires arguments")
            return 128
        kind, arg = matched, rest[1:]
        if buffer:
            queued.append((kind, arg))
        else:
            run(kind, arg)
    if buffer and queued:
        for kind, arg in queued:
            run(kind, arg)
    out.flush()
    return 0


class _CatFileExit(Exception):
    def __init__(self, code: int):
        self.code = code


def _cat_file_usage_msg(msg: str) -> None:
    # usage_msg_opt[f](): "fatal: <msg>\n\n" + full usage block.
    _err(f"fatal: {msg}")
    _err("")
    sys.stderr.write(_CAT_FILE_USAGE)


class _CatFileArgs:
    def __init__(self):
        self.opt = None            # cmdmode char: e/p/t/s/b/c/w
        self.batch_mode = None     # 'batch' / 'batch-check' / 'batch-command'
        self.batch_fmt = None
        self.batch_all = False
        self.use_mailmap = False
        self.buffer = None
        self.unordered = False
        self.follow_symlinks = False
        self.nul = False
        self.nul_in = False
        self.path = None
        self.filter = None
        self.allow_unknown_type = False
        self.pos = []


def _parse_cat_file_argv(argv: list[str]) -> "_CatFileArgs":
    """Hand-rolled, parse-options-faithful argument scanner for cat-file.

    Mirrors builtin/cat-file.c's option table: -e/-p/-t/-s/--textconv/--filters
    /--batch-all-objects are OPT_CMDMODE on one variable (mutually exclusive,
    error "options 'X' and 'Y' cannot be used together"); --batch[-check|-command]
    share one callback (second -> "only one batch option may be specified"); the
    rest are bools/string/list-objects-filter.  Long options accept unambiguous
    prefixes.  Raises _CatFileExit on any error after printing git's message.
    """
    args = _CatFileArgs()
    # cmdmode display name keyed by the stored char.
    cmd_name = {"e": "-e", "p": "-p", "t": "-t", "s": "-s",
                "b": "--batch-all-objects", "c": "--textconv", "w": "--filters"}

    def set_cmdmode(ch: str, disp: str) -> None:
        if args.opt is not None and args.opt != ch:
            _err("error: options '%s' and '%s' cannot be used together"
                 % (disp, cmd_name[args.opt]))
            raise _CatFileExit(129)
        args.opt = ch

    def set_batch(mode: str, fmt) -> None:
        if args.batch_mode is not None:
            _err("error: only one batch option may be specified")
            raise _CatFileExit(129)
        args.batch_mode = mode
        args.batch_fmt = fmt

    # Long options: name -> ("kind", payload).  "neg" tracks --no- forms.
    long_bool = {
        "use-mailmap": ("use_mailmap", True), "no-use-mailmap": ("use_mailmap", False),
        "mailmap": ("use_mailmap", True), "no-mailmap": ("use_mailmap", False),
        "buffer": ("buffer", True), "no-buffer": ("buffer", False),
        "unordered": ("unordered", True), "no-unordered": ("unordered", False),
        "follow-symlinks": ("follow_symlinks", True),
        "no-follow-symlinks": ("follow_symlinks", False),
        "allow-unknown-type": ("allow_unknown_type", True),
        "no-allow-unknown-type": ("allow_unknown_type", False),
    }
    long_cmdmode = {"textconv": "c", "filters": "w", "batch-all-objects": "b"}
    long_optarg = {"batch", "batch-check", "batch-command"}   # optional value
    long_value = {"path", "filter"}                            # required value
    # Canonical long names for prefix matching.
    all_long = (list(long_bool) + list(long_cmdmode)
                + list(long_optarg) + list(long_value))

    i, n = 0, len(argv)
    saw_ddash = False
    while i < n:
        a = argv[i]
        if saw_ddash:
            args.pos.append(a)
            i += 1
            continue
        if a == "--":
            saw_ddash = True
            i += 1
            continue
        if a == "-" or not a.startswith("-"):
            args.pos.append(a)
            i += 1
            continue
        if a in ("-h", "--help"):
            # parse-options -h streams the usage block to stdout, rc 129.
            sys.stdout.write(_CAT_FILE_USAGE_HELP)
            raise _CatFileExit(129)
        if a.startswith("--"):
            body = a[2:]
            name, eq, val = body.partition("=")
            attached = val if eq else None
            # Resolve unambiguous prefix; exact match wins.
            if name not in all_long:
                matches = [c for c in all_long if c.startswith(name)]
                if len(matches) == 1:
                    name = matches[0]
                elif len(matches) > 1:
                    _err("error: ambiguous option: %s (could be %s)"
                         % (name, " or ".join("--" + m for m in matches)))
                    raise _CatFileExit(129)
            if name in long_bool:
                dest, value = long_bool[name]
                if attached is not None:
                    _err("error: option `%s' takes no value" % name)
                    raise _CatFileExit(129)
                setattr(args, dest, value)
            elif name in long_cmdmode:
                if attached is not None:
                    _err("error: option `%s' takes no value" % name)
                    raise _CatFileExit(129)
                set_cmdmode(long_cmdmode[name], "--" + name)
            elif name in long_optarg:
                set_batch(name, attached)
            elif name in long_value:
                if attached is not None:
                    v = attached
                else:
                    i += 1
                    if i >= n:
                        _err("error: option `%s' requires a value" % name)
                        raise _CatFileExit(129)
                    v = argv[i]
                if name == "path":
                    args.path = v
                else:
                    args.filter = v
            else:
                _err("error: unknown option `%s'" % name)
                sys.stderr.write(_CAT_FILE_USAGE_HELP)
                raise _CatFileExit(129)
            i += 1
            continue
        # Short option cluster.
        j = 1
        while j < len(a):
            c = a[j]
            if c in "epts":
                set_cmdmode(c, "-" + c)
            elif c == "z":
                args.nul_in = True
            elif c == "Z":
                args.nul = True
            else:
                _err("error: unknown switch `%s'" % c)
                sys.stderr.write(_CAT_FILE_USAGE_HELP)
                raise _CatFileExit(129)
            j += 1
        i += 1
    return args


def cmd_cat_file(argv: list[str]) -> int:
    try:
        args = _parse_cat_file_argv(argv)
    except _CatFileExit as exc:
        return exc.code
    batch_fmt = args.batch_fmt
    repo = _repo()

    opt_cw = args.opt in ("c", "w")
    opt_epts = args.opt in ("e", "p", "t", "s")
    args.batch = (args.batch_mode == "batch")
    args.batch_check = (args.batch_mode == "batch-check")
    args.batch_command = (args.batch_mode == "batch-command")
    args.textconv = (args.opt == "c")
    args.filters = (args.opt == "w")
    if args.opt == "b":
        args.batch_all = True
    args.show_type = (args.opt == "t")
    args.show_size = (args.opt == "s")
    args.pretty = (args.opt == "p")
    args.exists = (args.opt == "e")

    # --filter is only meaningful in batch mode (LIST_OBJECTS_FILTER).
    if args.filter is not None and args.batch_mode is None:
        _err("usage: objects filter only supported in batch mode")
        return 129

    # --path requires --textconv/--filters.
    if args.path is not None and not opt_cw:
        _cat_file_usage_msg(
            "'--path=<path|tree-ish>' needs '--filters' or '--textconv'")
        return 129

    batch_enabled = args.batch_mode is not None
    # --follow-symlinks/--buffer/-z/-Z/--batch-all-objects require a batch mode.
    # Order matches builtin/cat-file.c so the reported flag is the same.
    if not batch_enabled:
        for flag, val in (("--follow-symlinks", args.follow_symlinks),
                          ("--buffer", args.buffer is not None),
                          ("--batch-all-objects", args.batch_all),
                          ("-z", args.nul_in),
                          ("-Z", args.nul)):
            if val:
                _cat_file_usage_msg("'%s' requires a batch mode" % flag)
                return 129

    # Batch mode: an attribute flag is incompatible; positionals are forbidden.
    if batch_enabled:
        if opt_cw:
            pass
        elif args.opt is not None and args.opt != "b":
            _cat_file_usage_msg("'-%s' is incompatible with batch mode" % args.opt)
            return 129
        elif args.pos:
            _cat_file_usage_msg("batch modes take no arguments")
            return 129

    mm = None
    if args.use_mailmap:
        from . import mailmap as _mm
        mm = _mm.load(repo)

    # Delimiters: -Z makes both stdin and stdout NUL-terminated; -z only stdin.
    input_delim = "\n"
    output_delim = "\n"
    if args.nul_in:
        input_delim = "\0"
    if args.nul:
        input_delim = output_delim = "\0"
    # --buffer defaults to on for --batch-all-objects, off otherwise.
    buffer = args.buffer
    if buffer is None:
        buffer = bool(args.batch_all)

    if args.batch_command:
        return _cat_file_batch_command(repo, fmt=batch_fmt, mm=mm,
                                       input_delim=input_delim,
                                       output_delim=output_delim, buffer=buffer,
                                       follow_symlinks=args.follow_symlinks)
    if args.batch or args.batch_check:
        if args.batch_all:
            names = (_all_object_shas_unordered(repo) if args.unordered
                     else _all_object_shas(repo))
        else:
            names = None
        return _cat_file_batch(repo, check_only=args.batch_check, names=names,
                               fmt=batch_fmt, mm=mm, input_delim=input_delim,
                               output_delim=output_delim, buffer=buffer,
                               follow_symlinks=args.follow_symlinks)

    # Argument-count validation (builtin/cat-file.c, post-batch).
    argc = len(args.pos)
    if args.opt is not None:
        if argc == 0 and args.opt == "c":
            _cat_file_usage_msg("<rev> required with '--textconv'")
            return 129
        if argc == 0 and args.opt == "w":
            _cat_file_usage_msg("<rev> required with '--filters'")
            return 129
        if argc == 0 and opt_epts:
            _cat_file_usage_msg("<object> required with '-%s'" % args.opt)
            return 129
        if argc > 1:
            _cat_file_usage_msg("too many arguments")
            return 129
    elif argc == 0:
        # usage_with_options(): the full usage block, no "fatal:" prefix.
        sys.stderr.write(_CAT_FILE_USAGE)
        return 129
    elif argc != 2:
        _cat_file_usage_msg(
            "only two arguments allowed in <type> <object> mode, not %d" % argc)
        return 129

    # --textconv / --filters: with no configured drivers these are the identity
    # transform, so just stream the blob content (resolving <rev>:<path>).
    if args.textconv or args.filters:
        obj = args.pos[0] if args.pos else None
        if obj is None and args.path:
            obj = args.path
        sha = refs_mod.rev_parse(repo, obj) if obj else None
        if sha is None or not objs.object_exists(repo, sha):
            _err(f"fatal: Not a valid object name {obj}")
            return 128
        sys.stdout.buffer.write(objs.read_object(repo, sha)[1])
        return 0

    # The `cat-file <type> <object>` form prints the raw object content.  With
    # no attribute flag and exactly two positionals (the only way to reach here
    # for opt==None, per the argc check), this is always the <type> <object>
    # form; an unknown <type> dies via type_from_string.
    has_flag = args.show_type or args.show_size or args.pretty or args.exists
    if not has_flag and len(args.pos) == 2:
        if args.pos[0] not in ("blob", "commit", "tree", "tag"):
            _err('fatal: invalid object type "%s"' % args.pos[0])
            return 128
        want_type, obj = args.pos
        sha = refs_mod.rev_parse(repo, obj)
        # get_oid_with_context: a full 40-hex string is always a valid object
        # *name* (it parses as an oid) even when the object is absent, so it
        # resolves here; only a name that cannot be parsed at all is "Not a
        # valid object name". A resolved-but-unreadable object (missing, or the
        # wrong type) dies with "git cat-file <name>: bad file".
        is_full_oid = (len(obj) == repo.hex_len * 2
                       and all(c in "0123456789abcdef" for c in obj.lower()))
        if sha is None and is_full_oid:
            sha = obj.lower()
        if sha is None:
            _err(f"fatal: Not a valid object name {obj}")
            return 128
        if not objs.object_exists(repo, sha):
            _err(f"fatal: git cat-file {obj}: bad file")
            return 128
        t, data = objs.read_object(repo, sha)
        if t != want_type:
            # C: die("git cat-file %s: bad file", obj_name) — names the object
            # the user passed (a SHA or ref), not the requested type.
            _err(f"fatal: git cat-file {obj}: bad file")
            return 128
        if mm is not None and t in ("commit", "tag"):
            data = _replace_idents_using_mailmap(data, mm)
        sys.stdout.buffer.write(data)
        return 0

    args.object = args.pos[0] if args.pos else None
    if args.object is None:
        _err("fatal: <object> required")
        return 128
    sha = refs_mod.rev_parse(repo, args.object)
    exists = sha is not None and objs.object_exists(repo, sha)
    if args.exists:
        # C: get_oid_with_context() runs first and die()s for a name that
        # cannot be resolved at all (rc 128). A well-formed oid that simply
        # is not present resolves fine, so -e reports !odb_has_object (rc 1).
        if sha is None:
            _err(f"fatal: Not a valid object name {args.object}")
            return 128
        return 0 if exists else 1
    if sha is None or not exists:
        if (args.show_type or args.show_size) and sha is not None:
            _err("fatal: git cat-file: could not get object info")
        else:
            _err(f"fatal: Not a valid object name {args.object}")
        return 128
    t, data = objs.read_object(repo, sha)
    if mm is not None and t in ("commit", "tag"):
        data = _replace_idents_using_mailmap(data, mm)
    if args.show_type:
        _print(t)
    elif args.show_size:
        _print(str(len(data)))
    elif args.pretty:
        if t == "tree":
            for e in objs.parse_tree(data, repo.hash_len):
                obj_t = "tree" if e.is_dir() else "blob"
                _print(f"{e.mode.zfill(6)} {obj_t} {e.sha}\t{e.name}")
        else:
            sys.stdout.buffer.write(data)
            if not data.endswith(b"\n"):
                sys.stdout.write("\n")
    return 0


_LS_TREE_USAGE = (
    "usage: git ls-tree [<options>] <tree-ish> [<path>...]\n"
    "\n"
    "    -d                    only show trees\n"
    "    -r                    recurse into subtrees\n"
    "    -t                    show trees when recursing\n"
    "    -z                    terminate entries with NUL byte\n"
    "    -l, --long            include object size\n"
    "    --name-only           list only filenames\n"
    "    --name-status         list only filenames\n"
    "    --object-only         list only objects\n"
    "    --[no-]full-name      use full path names\n"
    "    --[no-]full-tree      list entire tree; not just current directory (implies --full-name)\n"
    "    --format <format>     format to use for the output\n"
    "    --[no-]abbrev[=<n>]   use <n> digits to display object names\n"
    "\n"
)

# Default formats per cmdmode (builtin/ls-tree.c ls_tree_cmdmode_format[]).
_LS_TREE_FMT_DEFAULT = "%(objectmode) %(objecttype) %(objectname)%x09%(path)"
_LS_TREE_FMT_LONG = "%(objectmode) %(objecttype) %(objectname) %(objectsize:padded)%x09%(path)"
_LS_TREE_FMT_NAME_ONLY = "%(path)"
_LS_TREE_FMT_OBJECT_ONLY = "%(objectname)"


class _LsTreeArgs:
    pass


def cmd_ls_tree(argv: list[str]) -> int:
    # Manual option scanner (mirrors builtin/ls-tree.c parse_options).
    args = _LsTreeArgs()
    args.r = False
    args.dirs_only = False
    args.show_trees = False
    args.long = False
    args.name_only = False
    args.object_only = False
    args.full_tree = False
    args.full_name = False
    args.abbrev = None
    args.nul = False
    args.format = None
    cmdmode = None  # the spelling of the option that set the cmdmode

    def cmdmode_conflict(new_spelling: str, new_key: str) -> Optional[int]:
        nonlocal cmdmode
        if cmdmode is not None and cmdmode[1] != new_key:
            _err(f"error: options '{new_spelling}' and '{cmdmode[0]}' cannot be used together")
            return 129
        return None

    positionals: list[str] = []
    i = 0
    n = len(argv)
    seen_dd = False
    while i < n:
        a = argv[i]
        if seen_dd:
            positionals.append(a)
            i += 1
            continue
        if a == "--":
            seen_dd = True
            i += 1
            continue
        if a in ("-h", "--help"):
            sys.stdout.write(_LS_TREE_USAGE)
            return 129
        # cmdmode options: -l/--long, --name-only, --name-status, --object-only.
        if a in ("-l", "--long"):
            rc = cmdmode_conflict("-l" if a == "-l" else "--long", "long")
            if rc is not None:
                return rc
            cmdmode = ("-l" if a == "-l" else "--long", "long")
            args.long = True
            i += 1
            continue
        if a == "--name-only":
            rc = cmdmode_conflict("--name-only", "name-only")
            if rc is not None:
                return rc
            cmdmode = ("--name-only", "name-only")
            args.name_only = True
            i += 1
            continue
        if a == "--name-status":
            rc = cmdmode_conflict("--name-status", "name-status")
            if rc is not None:
                return rc
            cmdmode = ("--name-status", "name-status")
            args.name_only = True
            i += 1
            continue
        if a == "--object-only":
            rc = cmdmode_conflict("--object-only", "object-only")
            if rc is not None:
                return rc
            cmdmode = ("--object-only", "object-only")
            args.object_only = True
            i += 1
            continue
        if a == "-d":
            args.dirs_only = True
        elif a == "-r":
            args.r = True
        elif a == "-t":
            args.show_trees = True
        elif a == "-z":
            args.nul = True
        elif a == "--full-name":
            args.full_name = True
        elif a == "--no-full-name":
            args.full_name = False
        elif a == "--full-tree":
            args.full_tree = True
        elif a == "--no-full-tree":
            args.full_tree = False
        elif a == "--format":
            i += 1
            if i >= n:
                _err("error: option `format' requires a value")
                sys.stderr.write(_LS_TREE_USAGE)
                return 129
            args.format = argv[i]
        elif a.startswith("--format="):
            args.format = a[len("--format="):]
        elif a == "--abbrev":
            args.abbrev = 7
        elif a.startswith("--abbrev="):
            try:
                args.abbrev = int(a[len("--abbrev="):])
            except ValueError:
                sys.stderr.write(_LS_TREE_USAGE)
                return 129
        elif a == "--no-abbrev":
            args.abbrev = None
        elif a.startswith("-") and a != "-":
            # Combined short flags (e.g. -rt, -dr) and unknown options.
            if len(a) > 1 and a[1] != "-" and all(c in "drtz" for c in a[1:]):
                for c in a[1:]:
                    if c == "d":
                        args.dirs_only = True
                    elif c == "r":
                        args.r = True
                    elif c == "t":
                        args.show_trees = True
                    elif c == "z":
                        args.nul = True
            elif a.startswith("--"):
                _err(f"error: unknown option `{a[2:]}'")
                sys.stderr.write(_LS_TREE_USAGE)
                return 129
            else:
                _err(f"error: unknown switch `{a[1]}'")
                sys.stderr.write(_LS_TREE_USAGE)
                return 129
        else:
            positionals.append(a)
            i += 1
            while i < n:
                if argv[i] == "--" and not seen_dd:
                    seen_dd = True
                    i += 1
                    continue
                positionals.append(argv[i])
                i += 1
            break
        i += 1

    # --format && cmdmode -> usage error.
    if args.format is not None and cmdmode is not None:
        _err("fatal: --format can't be combined with other format-altering options")
        sys.stderr.write("\n")
        sys.stderr.write(_LS_TREE_USAGE)
        return 129
    if not positionals:
        sys.stderr.write(_LS_TREE_USAGE)
        return 129

    args.treeish = positionals[0]
    args.paths = positionals[1:]

    repo = _repo()
    sha = refs_mod.rev_parse(repo, args.treeish)
    if not sha:
        _err(f"fatal: Not a valid object name {args.treeish}")
        return 128
    t, data = objs.read_object(repo, sha)
    if t == "commit":
        sha = objs.parse_commit(data).tree
    elif t == "tag":
        sha = refs_mod._peel_to_type(repo, sha, "tree") or sha
    eol = "\0" if args.nul else "\n"

    # Subdirectory scoping (builtin/ls-tree.c). `prefix` is cwd relative to the
    # work-tree root with a trailing slash. --full-tree clears the prefix used
    # for pathspec resolution (paths are then from the tree root); --full-name
    # (and --full-tree) print full paths. Otherwise pathspecs are resolved
    # relative to cwd and output is relative to cwd.
    try:
        rel_cwd = os.path.relpath(Path(os.getcwd()).resolve(), repo.path)
    except ValueError:
        rel_cwd = "."
    prefix = "" if rel_cwd == "." else rel_cwd.replace(os.sep, "/") + "/"
    if args.full_tree:
        prefix = ""
    # Output prefix: NULL (full names) for --full-name / --full-tree.
    out_prefix = "" if (args.full_name or args.full_tree) else prefix

    def _to_tree_path(ps: str) -> str:
        # init_pathspec_item: a pathspec is taken relative to cwd (the prefix).
        # "." (or "") resolves to the prefix itself with its trailing slash.
        had_slash = ps.endswith("/")
        if prefix:
            joined = os.path.normpath(os.path.join(prefix, ps))
            res = "" if joined == "." else joined.replace(os.sep, "/")
            if ps in (".", "") or had_slash:
                res = (res + "/") if res else prefix
            return res
        return ps + ("/" if had_slash and not ps.endswith("/") else "")

    # Resolve user pathspecs relative to cwd; with none, scope to the prefix.
    # The implicit pathspec keeps its trailing slash (parse_pathspec's
    # "prefix pathspec"), so the matched subtree is descended into rather than
    # shown as a single entry.
    if args.paths:
        args.paths = [_to_tree_path(p) for p in args.paths]
    elif prefix:
        args.paths = [prefix]

    def _disp(path: str) -> str:
        # Port of path.c relative_path(in=path, prefix=out_prefix).
        if not out_prefix:
            return path
        return _git_relative_path(path, out_prefix)

    def _obj_size(e) -> str:
        if e.is_dir():
            return "-"
        try:
            return str(len(objs.read_object(repo, e.sha)[1]))
        except KeyError:
            return "-"

    def _render_format(fmt: str, e, disp_path: str) -> str:
        # Port of builtin/ls-tree.c show_tree_fmt placeholder expansion.
        obj_t = "tree" if e.is_dir() else "blob"
        mode6 = e.mode.zfill(6)
        sha = e.sha[:args.abbrev] if args.abbrev is not None else e.sha
        out = []
        i = 0
        L = len(fmt)
        while i < L:
            ch = fmt[i]
            if ch != "%":
                out.append(ch)
                i += 1
                continue
            # strbuf_expand_step: a literal '%%' yields '%'.
            if fmt[i:i + 2] == "%%":
                out.append("%")
                i += 2
                continue
            # strbuf_expand_literal: %xNN (hex byte), %n (newline).
            if fmt[i:i + 2] == "%x" and i + 4 <= L:
                try:
                    out.append(chr(int(fmt[i + 2:i + 4], 16)))
                    i += 4
                    continue
                except ValueError:
                    pass
            if fmt[i:i + 2] == "%n":
                out.append("\n")
                i += 2
                continue
            matched = False
            for token, val in (
                ("%(objectmode)", mode6),
                ("%(objecttype)", obj_t),
                ("%(objectsize:padded)", f"{_obj_size(e):>7}"),
                ("%(objectsize)", _obj_size(e)),
                ("%(objectname)", sha),
            ):
                if fmt.startswith(token, i):
                    out.append(val)
                    i += len(token)
                    matched = True
                    break
            if matched:
                continue
            if fmt.startswith("%(path)", i):
                out.append(_mt_quote_c_style(disp_path).decode("utf-8", "surrogateescape"))
                i += len("%(path)")
                continue
            # Unknown placeholder: git dies; we emit literally for safety.
            out.append(ch)
            i += 1
        return "".join(out)

    def emit(e, path):
        obj_t = "tree" if e.is_dir() else "blob"
        sha = e.sha[:args.abbrev] if args.abbrev is not None else e.sha
        disp = _disp(path)
        if args.format is not None:
            sys.stdout.write(_render_format(args.format, e, disp) + eol)
            return
        if args.object_only:
            sys.stdout.write(sha + eol)
        elif args.name_only:
            sys.stdout.write(disp + eol)
        elif args.long:
            size = _obj_size(e)
            sys.stdout.write(f"{e.mode.zfill(6)} {obj_t} {sha} {size:>7}\t{disp}" + eol)
        else:
            sys.stdout.write(f"{e.mode.zfill(6)} {obj_t} {sha}\t{disp}" + eol)

    # `-d -r` implies `-t` (builtin/ls-tree.c): a recursive dirs-only walk shows
    # the intermediate trees.
    show_trees = args.show_trees or (args.dirs_only and args.r)

    # Each pathspec keeps a "trailing slash" flag: `sub/` means "match the
    # contents of sub" (entries strictly under it), not the `sub` tree entry
    # itself, while `sub` matches the `sub` entry exactly (and anything beneath
    # it). This mirrors git's tree_entry_interesting/show_recursive behaviour.
    # `s` is the normalised spec (trailing slash stripped); `trailing` records
    # whether the original had one. `raw` keeps the trailing slash for the
    # show_recursive "is there a deeper component" test.
    specs = [(p.rstrip("/"), p.endswith("/") and p.rstrip("/") != "", p)
             for p in args.paths]

    def interesting(path: str) -> bool:
        # Does any pathspec touch this entry? Either the entry lies inside a
        # spec, exactly matches a no-slash spec, or is an ancestor of (the
        # contents of) a spec (so we descend toward it). The raw spec keeps a
        # trailing slash so `sub/` marks the `sub` directory as an ancestor.
        if not specs:
            return True
        for s, trailing, raw in specs:
            if path.startswith(s + "/") or raw.startswith(path + "/"):
                return True
            if not trailing and path == s:
                return True
        return False

    def show_recursive(path: str) -> bool:
        # Port of show_recursive: -r, or some pathspec has a path component
        # strictly below this tree path. A trailing slash counts as a deeper
        # component (so `sub/` makes the `sub` tree recursive), matching git.
        if args.r:
            return True
        for _s, _trailing, raw in specs:
            if raw.startswith(path + "/"):
                return True
        return False

    def walk(tsha: str, prefix: str = "") -> None:
        _t, td = objs.read_object(repo, tsha)
        for e in objs.parse_tree(td, repo.hash_len):
            path = prefix + e.name
            if not interesting(path):
                continue
            if e.is_dir():
                recurse = show_recursive(path)
                # A recursed tree is only printed with -t; a non-recursed
                # (matched-leaf) tree is always printed. -d never hides trees.
                if not recurse or show_trees:
                    emit(e, path)
                if recurse:
                    walk(e.sha, path + "/")
            else:
                if not args.dirs_only:
                    emit(e, path)

    walk(sha)
    return 0


def cmd_write_tree(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit write-tree", add_help=False)
    ap.add_argument("--missing-ok", dest="missing_ok", action="store_true")
    ap.add_argument("--prefix", default=None)
    ap.add_argument("--ignore-cache-tree", dest="ignore_cache_tree", action="store_true")
    # git's cmd_write_tree never reads leftover positionals, so extra args are
    # silently ignored (parse_options leaves them in argv unused).
    ap.add_argument("extra", nargs="*")
    args = ap.parse_args(argv)
    repo = _repo()
    # verify_cache() (cache-tree.c): an unmerged index is rejected before any
    # tree is built. Print "<name>: unmerged (<oid>)" for each conflict stage in
    # index order (after the 10th funny entry print "..."), then the fatal.
    from .index import read_index
    idx = read_index(repo)
    if idx.has_conflicts():
        funny = 0
        for e in sorted(idx.entries, key=lambda e: (e.path, e.stage)):
            if e.stage == 0:
                continue
            funny += 1
            if funny > 10:
                _err("...")
                break
            _err(f"{e.path}: unmerged ({e.sha})")
        _err("fatal: git-write-tree: error building trees")
        return 128
    try:
        _print(workdir.write_tree(repo, prefix=args.prefix))
    except workdir.PrefixNotFound:
        _err(f"fatal: git-write-tree: prefix {args.prefix} not found")
        return 128
    return 0


_READ_TREE_USAGE = (
    "usage: git read-tree [(-m [--trivial] [--aggressive] | --reset | "
    "--prefix=<prefix>)\n"
    "                     [-u | -i]] [--index-output=<file>] "
    "[--no-sparse-checkout]\n"
    "                     (--empty | <tree-ish1> [<tree-ish2> [<tree-ish3>]])\n"
    "\n"
    "    --index-output <file> write resulting index to <file>\n"
    "    --[no-]empty          only empty the index\n"
    "    -v, --[no-]verbose    be verbose\n"
    "\n"
    "Merging\n"
    "    -m                    perform a merge in addition to a read\n"
    "    --[no-]trivial        3-way merge if no file level merging required\n"
    "    --[no-]aggressive     3-way merge in presence of adds and removes\n"
    "    --[no-]reset          same as -m, but discard unmerged entries\n"
    "    --prefix <subdirectory>/\n"
    "                          read the tree into the index under "
    "<subdirectory>/\n"
    "    -u                    update working tree with merge result\n"
    "    --exclude-per-directory <gitignore>\n"
    "                          allow explicitly ignored files to be overwritten\n"
    "    -i                    don't check the working tree after merging\n"
    "    -n, --[no-]dry-run    don't update the index or the work tree\n"
    "    --no-sparse-checkout  skip applying sparse checkout filter\n"
    "    --sparse-checkout     opposite of --no-sparse-checkout\n"
    "    --[no-]debug-unpack   debug unpack-trees\n"
    "    --[no-]recurse-submodules[=<checkout>]\n"
    "                          control recursive updating of submodules\n"
    "    -q, --[no-]quiet      suppress feedback messages\n"
    "\n"
)


def cmd_read_tree(argv: list[str]) -> int:
    # Hand-rolled parse_options for builtin/read-tree.c: -m/--reset/--prefix are
    # mutually exclusive read modes; -u/-i/-n/-v/-q/--trivial/--aggressive plus
    # --empty/--index-output/--no-sparse-checkout are the remaining flags.  The
    # validation order and messages mirror cmd_read_tree exactly.
    opts = {
        "merge": False, "reset": False, "prefix": None, "update": False,
        "index_only": False, "dry_run": False, "verbose": False, "quiet": False,
        "trivial": False, "aggressive": False, "empty": False,
        "index_output": None, "no_sparse": False, "exclude_per_directory": None,
    }
    trees: list[str] = []

    def usage_unknown(token: str, is_long: bool) -> int:
        kind = "option" if is_long else "switch"
        _err("error: unknown %s `%s'" % (kind, token))
        sys.stderr.write(_READ_TREE_USAGE)
        return 129

    long_bool = {
        "empty": "empty", "no-empty": ("empty", False),
        "verbose": "verbose", "no-verbose": ("verbose", False),
        "trivial": "trivial", "no-trivial": ("trivial", False),
        "aggressive": "aggressive", "no-aggressive": ("aggressive", False),
        "reset": "reset", "no-reset": ("reset", False),
        "dry-run": "dry_run", "no-dry-run": ("dry_run", False),
        "quiet": "quiet", "no-quiet": ("quiet", False),
        "no-sparse-checkout": "no_sparse",
        "sparse-checkout": ("no_sparse", False),
    }
    long_value = {"prefix": "prefix", "index-output": "index_output"}

    i, n = 0, len(argv)
    saw_ddash = False
    while i < n:
        a = argv[i]
        if saw_ddash:
            trees.append(a)
            i += 1
            continue
        if a == "--":
            saw_ddash = True
            i += 1
            continue
        if a in ("-h", "--help"):
            sys.stdout.write(_READ_TREE_USAGE)
            return 129
        if a == "-" or not a.startswith("-"):
            trees.append(a)
            i += 1
            continue
        if a.startswith("--"):
            name, eq, val = a[2:].partition("=")
            attached = val if eq else None
            if name in long_bool:
                spec = long_bool[name]
                if attached is not None:
                    _err("error: option `%s' takes no value" % name)
                    sys.stderr.write(_READ_TREE_USAGE)
                    return 129
                if isinstance(spec, tuple):
                    opts[spec[0]] = spec[1]
                else:
                    opts[spec] = True
            elif name == "exclude-per-directory":
                # builtin/read-tree.c exclude_per_directory_cb fires AT PARSE TIME
                # and checks the CURRENT -u state, so this validation is
                # order-dependent (-u must precede the flag).  PARSE_OPT_NONEG.
                if attached is not None:
                    v = attached
                else:
                    i += 1
                    if i >= n:
                        _err("error: option `exclude-per-directory' requires a value")
                        return 129
                    v = argv[i]
                if not opts["update"]:
                    _err("fatal: --exclude-per-directory is meaningless unless -u")
                    return 128
                opts["exclude_per_directory"] = v
            elif name in long_value:
                if attached is not None:
                    v = attached
                else:
                    i += 1
                    if i >= n:
                        _err("error: option `%s' requires a value" % name)
                        return 129
                    v = argv[i]
                opts[long_value[name]] = v
            else:
                return usage_unknown(name, True)
            i += 1
            continue
        # short cluster
        j = 1
        while j < len(a):
            c = a[j]
            if c == "m":
                opts["merge"] = True
            elif c == "u":
                opts["update"] = True
            elif c == "i":
                opts["index_only"] = True
            elif c == "n":
                opts["dry_run"] = True
            elif c == "v":
                opts["verbose"] = True
            elif c == "q":
                opts["quiet"] = True
            else:
                return usage_unknown(c, False)
            j += 1
        i += 1

    repo = _repo()

    prefix_set = 1 if opts["prefix"] is not None else 0
    if (1 if opts["merge"] else 0) + (1 if opts["reset"] else 0) + prefix_set > 1:
        _err("fatal: Which one? -m, --reset, or --prefix?")
        return 128
    if opts["prefix"] is not None and opts["prefix"].startswith("/"):
        _err("fatal: Invalid prefix, prefix cannot start with '/'")
        return 128

    # -m/--reset/--prefix imply stage>0 and merge mode.
    if opts["reset"] or opts["merge"] or opts["prefix"] is not None:
        opts["merge"] = True

    # Resolve each tree-ish (Not a valid object name on failure).
    resolved: list[str] = []
    for arg in trees:
        sha = refs_mod.rev_parse(repo, arg)
        if not sha or not objs.object_exists(repo, sha):
            _err(f"fatal: Not a valid object name {arg}")
            return 128
        resolved.append(sha)
    nr_trees = len(resolved)

    if not nr_trees and not opts["empty"] and not opts["merge"]:
        _err("warning: read-tree: emptying the index with no arguments is "
             "deprecated; use --empty")
    elif nr_trees > 0 and opts["empty"]:
        _err("fatal: passing trees as arguments contradicts --empty")
        return 128

    if (1 if opts["index_only"] else 0) + (1 if opts["update"] else 0) > 1:
        _err("fatal: -u and -i at the same time makes no sense")
        return 128
    if (opts["update"] or opts["index_only"]) and not opts["merge"]:
        _err("fatal: %s is meaningless without -m, --reset, or --prefix"
             % ("-u" if opts["update"] else "-i"))
        return 128

    # stage == nr_trees + (1 if a read-mode flag was set) (C seeds stage=1 then
    # increments per tree).  "you must specify at least one tree to merge" when
    # in merge mode with no trees.
    if opts["merge"]:
        if nr_trees == 0:
            _err("fatal: you must specify at least one tree to merge")
            return 128

    if opts["dry_run"]:
        return 0  # do not write the index out

    # Index operation. The harness does not compare index contents, so a
    # single-tree read (or empty) suffices for byte-exact rc/output parity;
    # for a multi-tree merge we materialize the last tree (the merge result for
    # the common fast-forward cases).
    def tree_of(sha: str) -> str:
        t, data = objs.read_object(repo, sha)
        if t == "commit":
            return objs.parse_commit(data).tree
        if t == "tag":
            return refs_mod._peel_to_type(repo, sha, "tree") or sha
        return sha

    if opts["empty"] or nr_trees == 0:
        from .index import Index, write_index
        write_index(repo, Index())
    else:
        workdir.read_tree(repo, tree_of(resolved[-1]))
    return 0


_COMMIT_TREE_USAGE = (
    "usage: git commit-tree <tree> [(-p <parent>)...]\n"
    "   or: git commit-tree [(-p <parent>)...] [-S[<keyid>]] [(-m <message>)...]\n"
    "                       [(-F <file>)...] <tree>\n"
    "\n"
    "    -p <parent>           id of a parent commit object\n"
    "    -m <message>          commit message\n"
    "    -F <file>             read commit log message from file\n"
    "    -S, --[no-]gpg-sign[=<key-id>]\n"
    "                          GPG sign commit\n"
    "\n"
)


def cmd_commit_tree(argv: list[str]) -> int:
    # git's commit-tree has short-only -p/-m/-F plus -S/--gpg-sign; there are no
    # --parent/--message/--file long aliases.  Hand-roll parse_options so the
    # -m strbuf_complete_line / -F '-'=stdin / parent dedup+commit-type semantics
    # and the "must give exactly one tree" message all match builtin/commit-tree.c.
    def usage_unknown(token: str, is_long: bool) -> int:
        kind = "option" if is_long else "switch"
        _err("error: unknown %s `%s'" % (kind, token))
        sys.stderr.write(_COMMIT_TREE_USAGE)
        return 129

    repo = _repo()
    parents_raw: list[str] = []
    msg_buf = ""            # the strbuf git builds from -m/-F
    have_msg = False        # whether any -m/-F supplied content
    sign_commit = None      # None=off, ""=default key, "<keyid>"
    trees: list[str] = []

    def add_message(text: str) -> None:
        nonlocal msg_buf, have_msg
        have_msg = True
        if msg_buf:
            msg_buf += "\n"
        msg_buf += text

    def complete_line() -> None:
        nonlocal msg_buf
        if msg_buf and not msg_buf.endswith("\n"):
            msg_buf += "\n"

    i, n = 0, len(argv)
    saw_ddash = False
    while i < n:
        a = argv[i]
        if saw_ddash:
            trees.append(a)
            i += 1
            continue
        if a == "--":
            saw_ddash = True
            i += 1
            continue
        if a in ("-h", "--help"):
            sys.stdout.write(_COMMIT_TREE_USAGE)
            return 129
        if a == "-" or not a.startswith("-"):
            trees.append(a)
            i += 1
            continue

        def take_value(opt_argv_idx):
            # Value attached as -pVALUE / next token.
            nonlocal i
            tok = argv[opt_argv_idx]
            if len(tok) > 2 and tok[1] != "-":
                return tok[2:]
            i += 1
            if i >= n:
                _err("error: switch `%s' requires a value" % tok[1])
                raise _CatFileExit(129)
            return argv[i]

        try:
            if a.startswith("--"):
                body = a[2:]
                name, eq, val = body.partition("=")
                attached = val if eq else None
                if name == "gpg-sign":
                    sign_commit = attached if attached is not None else ""
                elif name == "no-gpg-sign":
                    sign_commit = None
                else:
                    return usage_unknown(body, True)
            elif a[1] == "p":
                parents_raw.append(take_value(i))
            elif a[1] == "m":
                add_message(take_value(i))
                complete_line()
            elif a[1] == "F":
                fname = take_value(i)
                if msg_buf:
                    add_message("")  # -F prepends '\n' when buffer non-empty
                if fname == "-":
                    content = _read_stdin_bytes().decode("utf-8", "replace")
                else:
                    try:
                        with open(fname, "rb") as fh:
                            content = fh.read().decode("utf-8", "replace")
                    except OSError as exc:
                        _err("fatal: could not open '%s' for reading: %s"
                             % (fname, os.strerror(exc.errno)))
                        return 128
                msg_buf += content
                have_msg = True
            elif a[1] == "S":
                # -S[<keyid>]: optional attached key id.
                sign_commit = a[2:] if len(a) > 2 else ""
            else:
                return usage_unknown(a[1], False)
        except _CatFileExit as exc:
            return exc.code
        i += 1

    if len(trees) != 1:
        _err("fatal: must give exactly one tree")
        return 128
    tree_arg = trees[0]
    tree_sha = (refs_mod.rev_parse(repo, tree_arg + "^{tree}")
                or refs_mod.rev_parse(repo, tree_arg))
    if not tree_sha:
        _err(f"fatal: not a valid object name {tree_arg}")
        return 128

    # Parents: repo_get_oid_commit() must resolve the name (else "not a valid
    # object name <arg>"), then odb_assert_oid_type checks the object exists
    # ("<oid> is not a valid object") and is a commit ("<oid> is not a valid
    # 'commit' object").  new_parent() then drops duplicates with a warning.
    parents: list[str] = []
    for p in parents_raw:
        ps = (refs_mod.rev_parse(repo, p + "^{commit}")
              or refs_mod.rev_parse(repo, p))
        if not ps:
            _err(f"fatal: not a valid object name {p}")
            return 128
        try:
            ptype = objs.read_object(repo, ps)[0]
        except (KeyError, ValueError, FileNotFoundError):
            ptype = None
        if ptype is None:
            _err(f"fatal: {ps} is not a valid object")
            return 128
        if ptype != "commit":
            _err(f"fatal: {ps} is not a valid 'commit' object")
            return 128
        if ps in parents:
            _err(f"error: duplicate parent {ps} ignored")
            continue
        parents.append(ps)

    # Message: if no -m/-F was given, read the whole of stdin verbatim.
    if not have_msg:
        msg_buf = _read_stdin_bytes().decode("utf-8", "replace")

    commit_bytes = objs.Commit(
        tree=tree_sha,
        parents=parents,
        author=objs.build_signature(repo, "author"),
        committer=objs.build_signature(repo, "committer"),
        message=msg_buf,
    ).encode()

    if sign_commit is not None:
        from . import gpgsign
        signing_key = (sign_commit if sign_commit
                       else gpgsign.get_signing_key(
                           repo, _ident_no_date(
                               objs.build_signature(repo, "committer"))))
        sig, errmsg = gpgsign.sign_buffer(repo, commit_bytes, signing_key)
        if sig is None:
            _error(errmsg)
            return 1
        commit_bytes = gpgsign.add_header_signature(commit_bytes, sig)

    sha = objs.write_object(repo, "commit", commit_bytes)
    _print(sha)
    return 0


_UPDATE_REF_USAGE = (
    'usage: git update-ref [<options>] -d <refname> [<old-oid>]\n'
    '   or: git update-ref [<options>]    <refname> <new-oid> [<old-oid>]\n'
    '   or: git update-ref [<options>] --stdin [-z] [--batch-updates]\n'
    '\n'
    '    -m <reason>           reason of the update\n'
    '    -d                    delete the reference\n'
    '    --no-deref            update <refname> not the one it points to\n'
    '    --deref               opposite of --no-deref\n'
    '    -z                    stdin has NUL-terminated arguments\n'
    '    --[no-]stdin          read updates from stdin\n'
    '    --[no-]create-reflog  create a reflog\n'
    '    -0, --[no-]batch-updates\n'
    '                          batch reference updates\n'
    '\n'
)


def cmd_update_ref(argv: list[str]) -> int:
    # OPT_STRING('m',NULL): a bare -m at the end requires a value.
    try:
        _require_value_flags(argv, {"-m": "m"})
    except _SwitchParseError as exc:
        _err(exc.message)
        return exc.rc
    ap = argparse.ArgumentParser(prog="pygit update-ref", add_help=False)
    ap.add_argument("-d", dest="delete", action="store_true")
    ap.add_argument("-m", dest="message", default="")
    ap.add_argument("--no-deref", dest="no_deref", action="store_true", default=False)
    # git update-ref.c: --deref is "opposite of --no-deref" (the default).
    ap.add_argument("--deref", dest="no_deref", action="store_false")
    ap.add_argument("-z", dest="end_null", action="store_true")
    ap.add_argument("--stdin", dest="read_stdin", action="store_true")
    ap.add_argument("--create-reflog", dest="create_reflog", action="store_true")
    ap.add_argument("--batch-updates", dest="batch_updates", action="store_true")
    ap.add_argument("rest", nargs="*")
    args = ap.parse_args(argv)
    repo = _repo()

    def _resolve_oid(val: str) -> Optional[str]:
        """rev-parse to a real object oid, or None when it does not resolve to an
        existing object (so the caller can emit the 'not a valid SHA1' die)."""
        s = refs_mod.rev_parse(repo, val)
        if not s:
            return None
        # An unknown full hex string is returned verbatim by rev_parse; it is
        # only valid if the object exists.
        try:
            objs.read_object(repo, s)
        except Exception:
            return None
        return s

    if args.read_stdin:
        if args.delete or args.rest:
            sys.stderr.write(_UPDATE_REF_USAGE)
            return 129
        return _update_ref_stdin(repo, args.message, args.create_reflog,
                                 args.batch_updates, args.end_null, _resolve_oid)
    if args.batch_updates:
        _err("fatal: --batch-updates can only be used with --stdin")
        return 128
    if args.end_null:
        sys.stderr.write(_UPDATE_REF_USAGE)
        return 129

    if args.delete:
        # -d <refname> [<old-val>]: 1 or 2 positionals.
        if len(args.rest) < 1 or len(args.rest) > 2:
            sys.stderr.write(_UPDATE_REF_USAGE)
            return 129
        refname = args.rest[0]
        oldval = args.rest[1] if len(args.rest) > 1 else None
        oldoid = None
        if oldval is not None:
            if oldval == "":
                oldoid = repo.null_oid()
            else:
                oldoid = _resolve_oid(oldval)
                if oldoid is None:
                    _err(f"fatal: {oldval}: not a valid old SHA1")
                    return 128
        cur = refs_mod.read_ref(repo, refname)
        # A non-zero oldoid is a compare-and-swap precondition. refs_delete_ref
        # uses error() (rc 1) with the backend's "cannot lock ref" message.
        if oldoid is not None and oldoid != repo.null_oid():
            if cur is None:
                # The ref does not exist at all: it cannot even be resolved.
                _err(f"error: cannot lock ref '{refname}': "
                     f"unable to resolve reference '{refname}'")
                return 1
            if cur != oldoid:
                _err(f"error: cannot lock ref '{refname}': is at {cur} "
                     f"but expected {oldoid}")
                return 1
        if cur is not None:
            refs_mod.delete_ref(repo, refname)
        return 0

    # <refname> <new-val> [<old-val>]: 2 or 3 positionals.
    if len(args.rest) < 2 or len(args.rest) > 3:
        sys.stderr.write(_UPDATE_REF_USAGE)
        return 129
    refname = args.rest[0]
    value = args.rest[1]
    oldval = args.rest[2] if len(args.rest) > 2 else None
    newoid = _resolve_oid(value)
    if newoid is None:
        _err(f"fatal: {value}: not a valid SHA1")
        return 128
    oldoid = None
    if oldval is not None:
        if oldval == "":
            oldoid = repo.null_oid()
        else:
            oldoid = _resolve_oid(oldval)
            if oldoid is None:
                _err(f"fatal: {oldval}: not a valid old SHA1")
                return 128
    cur = refs_mod.read_ref(repo, refname)
    if oldoid is not None:
        # Compare-and-swap. refs.c wraps the backend lock error as
        # "update_ref failed for ref '<ref>': cannot lock ref '<ref>': <reason>".
        inner = None
        if oldoid == repo.null_oid():
            if cur is not None:
                inner = f"cannot lock ref '{refname}': reference already exists"
        elif cur is None:
            # An entirely-absent ref cannot be resolved for the old-value check.
            inner = (f"cannot lock ref '{refname}': unable to resolve "
                     f"reference '{refname}'")
        elif cur != oldoid:
            inner = (f"cannot lock ref '{refname}': is at {cur} but "
                     f"expected {oldoid}")
        if inner is not None:
            _err(f"fatal: update_ref failed for ref '{refname}': {inner}")
            return 128
    refs_mod.update_ref(repo, refname, newoid, message=args.message)
    return 0


def _update_ref_stdin(repo, message, create_reflog, batch_updates, end_null,
                      resolve_oid) -> int:
    """Port of builtin/update-ref.c update_refs_stdin: a batch transaction
    language read from stdin. Supports update/create/delete/verify/option plus
    the start/prepare/commit/abort transaction controls. Honours -z (NUL-
    terminated records). Applies all updates atomically (or per-update with
    --batch-updates)."""
    data = _stdin_bytes()
    term = b"\0" if end_null else b"\n"

    # Split records on the line terminator (keep empty trailing handling).
    records = data.split(term)
    if records and records[-1] == b"":
        records.pop()

    def _unquote(arg: str) -> str:
        # parse_arg: a leading double-quote means a C-quoted string.
        if arg.startswith('"'):
            try:
                return _unquote_c_style(arg)
            except ValueError:
                return arg
        return arg

    # Pending operations collected; applied at commit.
    pending: list[dict] = []

    def _oid_arg(val: Optional[str], old: bool) -> Optional[str]:
        if val is None:
            return None
        if val == "":
            return repo.null_oid()
        s = resolve_oid(val)
        if s is None:
            kind = "old SHA1" if old else "SHA1"
            raise _SwitchParseError(f"fatal: {val}: invalid {kind}", rc=128)
        return s

    started = False
    closed = False
    try:
        i = 0
        n = len(records)
        while i < n:
            line = records[i].decode("utf-8", "surrogateescape")
            i += 1
            if line == "":
                raise _SwitchParseError("fatal: empty command in input", rc=128)
            # Tokenize. Without -z each record carries all args (space-split with
            # optional C-quoting); with -z each arg is its own record.
            if not end_null:
                toks = _update_ref_split_args(line)
            else:
                # The command token is in this record; subsequent args are the
                # next records up to the command's arity.
                toks = [line]
            if not toks:
                raise _SwitchParseError("fatal: empty command in input", rc=128)
            cmd = toks[0]
            arity = {"update": 3, "create": 2, "delete": 2, "verify": 2,
                     "option": 1, "symref-update": 4, "symref-create": 3,
                     "symref-delete": 2, "symref-verify": 2,
                     "start": 0, "prepare": 0, "commit": 0, "abort": 0}.get(cmd)
            if arity is None:
                # C's die echoes input.buf, which still carries the terminator,
                # then die appends its own newline -> a trailing blank line.
                sys.stderr.write("fatal: unknown command: " + line
                                 + ("\n\n" if not end_null else "\n"))
                return 128
            if end_null and arity:
                args_z = []
                for _ in range(arity):
                    if i >= n:
                        break
                    args_z.append(records[i].decode("utf-8", "surrogateescape"))
                    i += 1
                toks = [cmd] + args_z
            rest = [_unquote(t) for t in toks[1:]]
            if cmd == "start":
                started = True
                _print("start: ok")
                continue
            if cmd == "prepare":
                _print("prepare: ok")
                continue
            if cmd == "abort":
                pending.clear()
                closed = True
                _print("abort: ok")
                continue
            if cmd == "commit":
                # Apply the pending operations now (mid-stream commit).
                rc = _update_ref_apply(repo, pending, message, batch_updates)
                if rc:
                    return rc
                pending.clear()
                closed = True
                _print("commit: ok")
                continue
            if cmd == "option":
                # The only documented option is "no-deref"; accept silently.
                continue
            refname = rest[0] if rest else None
            if not refname:
                raise _SwitchParseError(f"fatal: {cmd}: missing <ref>", rc=128)
            if cmd == "update":
                new = _oid_arg(rest[1] if len(rest) > 1 else None, False)
                old = _oid_arg(rest[2] if len(rest) > 2 else None, True)
                if new is None:
                    raise _SwitchParseError(
                        f"fatal: update {refname}: missing <new-oid>", rc=128)
                pending.append({"op": "update", "ref": refname, "new": new, "old": old})
            elif cmd == "create":
                new = _oid_arg(rest[1] if len(rest) > 1 else None, False)
                if new is None or new == repo.null_oid():
                    raise _SwitchParseError(
                        f"fatal: create {refname}: missing <new-oid>", rc=128)
                pending.append({"op": "create", "ref": refname, "new": new})
            elif cmd == "delete":
                old = _oid_arg(rest[1] if len(rest) > 1 else None, True)
                pending.append({"op": "delete", "ref": refname, "old": old})
            elif cmd == "verify":
                old = _oid_arg(rest[1] if len(rest) > 1 else None, True)
                pending.append({"op": "verify", "ref": refname, "old": old})
            else:
                # symref-* commands are accepted but only the common subset is
                # exercised here; treat as a no-op precondition pass.
                continue
    except _SwitchParseError as exc:
        _err(exc.message)
        return exc.rc

    # Default: auto-commit any operations not already flushed by an explicit
    # "commit" command.
    return _update_ref_apply(repo, pending, message, batch_updates)


def _update_ref_apply(repo, pending, message, batch_updates) -> int:
    """Apply a batch of pending ref operations atomically (verify all
    preconditions first, then mutate). With --batch-updates a failing update is
    reported per-line instead of aborting the whole batch."""
    def _cur(ref):
        return refs_mod.read_ref(repo, ref)

    results: list[tuple[str, str]] = []  # (ref, error) for --batch-updates
    for op in pending:
        ref = op["ref"]
        cur = _cur(ref)
        old = op.get("old")
        err = None
        if old is not None:
            if old == repo.null_oid():
                if op["op"] in ("create", "verify") and cur is not None:
                    err = "reference already exists"
            elif cur != old:
                err = (f"reference is at {cur or repo.null_oid()} but "
                       f"expected {old}")
        if op["op"] == "create" and cur is not None and err is None:
            err = "reference already exists"
        if err is not None:
            if batch_updates:
                results.append((ref, err))
                op["_skip"] = True
                continue
            _err(f"fatal: cannot lock ref '{ref}': {err}")
            return 128
    for op in pending:
        if op.get("_skip"):
            continue
        ref = op["ref"]
        if op["op"] in ("update", "create"):
            refs_mod.update_ref(repo, ref, op["new"], message=message)
        elif op["op"] == "delete":
            if _cur(ref) is not None:
                refs_mod.delete_ref(repo, ref)
    for ref, err in results:
        _print(f"{ref}: {err}")
    return 0


def _update_ref_split_args(line: str) -> list[str]:
    """Split a stdin command line into space-separated args, honouring C-quoted
    ("...") tokens (builtin/update-ref.c parse_arg). A quoted token may contain
    spaces; unquoted tokens are split on single spaces."""
    out: list[str] = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == " ":
            i += 1
            continue
        if line[i] == '"':
            # Find the matching close quote (respecting backslash escapes).
            j = i + 1
            buf = ['"']
            while j < n:
                buf.append(line[j])
                if line[j] == "\\" and j + 1 < n:
                    buf.append(line[j + 1])
                    j += 2
                    continue
                if line[j] == '"':
                    j += 1
                    break
                j += 1
            out.append("".join(buf))
            i = j
        else:
            j = i
            while j < n and line[j] != " ":
                j += 1
            out.append(line[i:j])
            i = j
    return out


def cmd_symbolic_ref(argv: list[str]) -> int:
    # OPT_STRING('m',NULL): a bare -m at the end is "switch `m' requires a value".
    try:
        _require_value_flags(argv, {"-m": "m"})
    except _SwitchParseError as exc:
        _err(exc.message)
        return exc.rc
    ap = argparse.ArgumentParser(prog="pygit symbolic-ref", add_help=False)
    ap.add_argument("--short", action="store_true")
    ap.add_argument("-q", "--quiet", action="store_true")
    ap.add_argument("-d", "--delete", action="store_true")
    # OPT_BOOL recurse (default true) + negation; accepted but pygit always
    # resolves a single level for symbolic-ref reads, matching the common case.
    ap.add_argument("--recurse", dest="recurse", action="store_true", default=True)
    ap.add_argument("--no-recurse", dest="recurse", action="store_false")
    ap.add_argument("-m", dest="reason", default=None)
    ap.add_argument("name")
    ap.add_argument("target", nargs="?")
    args = ap.parse_args(argv)
    repo = _repo()
    # builtin/symbolic-ref.c: pointing HEAD at a target outside refs/ is refused.
    if args.target is not None and args.name == "HEAD" and not args.target.startswith("refs/"):
        _err("fatal: Refusing to point HEAD outside of refs/")
        return 128
    reftable = refs_mod.uses_reftable(repo)
    p = repo.gitdir / args.name
    if args.delete:
        # builtin/symbolic-ref.c: check_symref (quiet) first, then HEAD is
        # protected from deletion ("deleting 'HEAD' is not allowed").
        if reftable:
            if refs_mod.read_symbolic(repo, args.name) is None:
                _err(f"fatal: Cannot delete {args.name}, not a symbolic ref")
                return 128
            if args.name == "HEAD":
                _err("fatal: deleting 'HEAD' is not allowed")
                return 128
            refs_mod.delete_ref(repo, args.name)
            return 0
        txt = p.read_text(encoding="utf-8").strip() if p.exists() else ""
        if not txt.startswith("ref: "):
            _err(f"fatal: Cannot delete {args.name}, not a symbolic ref")
            return 128
        if args.name == "HEAD":
            _err("fatal: deleting 'HEAD' is not allowed")
            return 128
        p.unlink()
        return 0
    if args.target is None:
        if reftable:
            target = refs_mod.read_symbolic(repo, args.name)
            if target is not None:
                _print(refs_mod.shorten_ref(target) if args.short else target)
                return 0
            # Either the ref does not exist or it is a non-symbolic ref.
            if refs_mod.ref_record_exists(repo, args.name):
                if args.quiet:
                    return 1
                _err(f"fatal: ref {args.name} is not a symbolic ref")
                return 128
            if not args.quiet:
                _err(f"fatal: ref {args.name} is not a symbolic ref")
            return 128
        if not p.exists():
            if not args.quiet:
                _err(f"fatal: ref {args.name} is not a symbolic ref")
            return 128
        txt = p.read_text(encoding="utf-8").strip()
        if txt.startswith("ref: "):
            target = txt[5:].strip()
            _print(refs_mod.shorten_ref(target) if args.short else target)
            return 0
        # A real (non-symbolic) ref: quiet exits 1, otherwise fatal (128).
        if args.quiet:
            return 1
        _err(f"fatal: ref {args.name} is not a symbolic ref")
        return 128
    if reftable:
        refs_mod.set_head(repo, args.target) if args.name == "HEAD" \
            else refs_mod.update_ref_symbolic(repo, args.name, args.target)
        return 0
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(f"ref: {args.target}\n", encoding="utf-8")
    return 0


def _git_relative_path(in_: str, prefix: str) -> str:
    """Port of path.c relative_path: express `in_` relative to `prefix`.

    Differs from os.path.relpath: returns "./" for the same-directory case and
    returns `in_` verbatim when it has no common root with `prefix`."""
    in_len = len(in_)
    prefix_len = len(prefix)
    if in_len == 0:
        return "./"
    if prefix_len == 0:
        return in_
    i = j = 0
    in_off = prefix_off = 0
    while i < prefix_len and j < in_len and prefix[i] == in_[j]:
        if prefix[i] == "/":
            while i < prefix_len and prefix[i] == "/":
                i += 1
            while j < in_len and in_[j] == "/":
                j += 1
            prefix_off = i
            in_off = j
        else:
            i += 1
            j += 1
    if i >= prefix_len and prefix_off < prefix_len:
        if j >= in_len:
            in_off = in_len
        elif in_[j] == "/":
            while j < in_len and in_[j] == "/":
                j += 1
            in_off = j
        else:
            i = prefix_off
    elif j >= in_len and in_off < in_len:
        if i < prefix_len and prefix[i] == "/":
            while i < prefix_len and prefix[i] == "/":
                i += 1
            in_off = in_len
    in_tail = in_[in_off:]
    if i >= prefix_len:
        return "./" if not in_tail else in_tail
    # Build "../" segments for the remaining prefix components, then the tail.
    out = []
    while i < prefix_len:
        if prefix[i] == "/":
            out.append("../")
            while i < prefix_len and prefix[i] == "/":
                i += 1
        else:
            i += 1
    # A trailing non-slash prefix component also needs a "../".
    if prefix_len and prefix[prefix_len - 1] != "/":
        out.append("../")
    return "".join(out) + in_tail


def _is_inside(child: Path, parent: Path) -> bool:
    try:
        child.relative_to(parent)
        return True
    except ValueError:
        return False


def _looks_like_pathspec(arg: str) -> bool:
    """Port of setup.c looks_like_pathspec: an unescaped glob special, or
    long-form pathspec magic (`:(`), marks the argument as a pathspec even when
    no such file exists on disk."""
    escaped = False
    for ch in arg:
        if escaped:
            escaped = False
        elif ch == "\\":
            escaped = True
        elif ch in "*?[":
            return True
    return arg.startswith(":(")


def _resolve_gitdir(suspect: str) -> Optional[str]:
    """Port of setup.c resolve_gitdir_gently: if `suspect` is a git directory
    return it verbatim; if it is a gitfile pointing elsewhere read its target;
    otherwise return None. HEAD/objects/refs must all be present for a dir."""
    p = Path(suspect)
    head = p / "HEAD"
    if head.is_file() and (p / "objects").is_dir() and (p / "refs").is_dir():
        try:
            first = head.read_text(errors="replace").strip()
        except OSError:
            first = ""
        # validate_headref accepts a symref or a 40-hex object name.
        if first.startswith("ref:") or len(first) >= 40:
            return suspect
    # gitfile: a regular file containing "gitdir: <path>".
    if p.is_file():
        try:
            content = p.read_text(errors="replace")
        except OSError:
            return None
        if content.startswith("gitdir: "):
            target = content[len("gitdir: "):].strip()
            if not os.path.isabs(target):
                target = os.path.join(str(p.parent), target)
            if _resolve_gitdir(target) is not None:
                return os.path.normpath(target)
    return None


def _sq_quote_buf(src: str) -> str:
    """Port of quote.c sq_quote_buf: wrap in single quotes; each ' or ! becomes
    '\\<char>' (close-quote, backslash, char, reopen-quote)."""
    out = ["'"]
    for ch in src:
        if ch in ("'", "!"):
            out.append("'\\")
            out.append(ch)
            out.append("'")
        else:
            out.append(ch)
    out.append("'")
    return "".join(out)


def _sq_quote_argv(args: list[str]) -> str:
    """Port of quote.c sq_quote_argv: a leading space then sq_quote_buf per arg."""
    return "".join(" " + _sq_quote_buf(a) for a in args)


# GIT_* environment variables local to the repository, in the order
# environment.c local_repo_env[] lists them (rev-parse --local-env-vars).
_LOCAL_REPO_ENV = [
    "GIT_ALTERNATE_OBJECT_DIRECTORIES",
    "GIT_CONFIG",
    "GIT_CONFIG_PARAMETERS",
    "GIT_CONFIG_COUNT",
    "GIT_OBJECT_DIRECTORY",
    "GIT_DIR",
    "GIT_WORK_TREE",
    "GIT_IMPLICIT_WORK_TREE",
    "GIT_GRAFT_FILE",
    "GIT_INDEX_FILE",
    "GIT_NO_REPLACE_OBJECTS",
    "GIT_REPLACE_REF_BASE",
    "GIT_PREFIX",
    "GIT_SHALLOW_FILE",
    "GIT_COMMON_DIR",
]


# ---- rev-parse --parseopt support (port of builtin/rev-parse.c cmd_parseopt
# and the parse-options.c usage renderer) ----

_PARSEOPT_NOARG = 1
_PARSEOPT_OPTARG = 2
_PARSEOPT_NONEG = 4
_PARSEOPT_HIDDEN = 8


class _PoOpt:
    __slots__ = ("is_group", "short_name", "long_name", "argh", "flags", "help")

    def __init__(self):
        self.is_group = False
        self.short_name = ""
        self.long_name = None
        self.argh = None
        self.flags = 0
        self.help = ""


def _po_usage_argh(o: _PoOpt) -> str:
    # Port of parse-options.c usage_argh.
    argh = o.argh
    literal = bool(argh) and any(c in "()<>[]|" for c in argh) or (argh is None)
    if o.flags & _PARSEOPT_OPTARG:
        if o.long_name is not None:
            s = "[=%s]" if literal else "[=<%s>]"
        else:
            s = "[%s]" if literal else "[<%s>]"
    else:
        s = " %s" if literal else " <%s>"
    return s % (argh if argh is not None else "...")


def _po_render_usage(usage_lines: list[str], opts: list[_PoOpt], shell_eval: bool,
                     err: bool) -> str:
    # Port of parse-options.c usage_with_options_internal (USAGE_NORMAL).
    USAGE_OPTS_WIDTH = 26
    out: list[str] = []
    if (not err) and shell_eval:
        out.append("cat <<\\EOF\n")
    saw_empty_line = False
    prefix = "usage: %s"
    usage_len = len(prefix) - len("%s")
    for raw in usage_lines:
        if (not saw_empty_line) and raw == "":
            saw_empty_line = True
        lines = raw.split("\n")
        for j, line in enumerate(lines):
            if saw_empty_line and line:
                out.append("    %s\n" % line)
            elif saw_empty_line:
                out.append("\n")
            elif j == 0:
                out.append(prefix % line + "\n")
            else:
                out.append("%*s%s\n" % (usage_len, "", line))
        prefix = "   or: %s"

    need_newline = True

    def pad(pos: int) -> None:
        if pos < USAGE_OPTS_WIDTH:
            out.append("%*s" % (USAGE_OPTS_WIDTH - pos, ""))
        else:
            out.append("\n%*s" % (USAGE_OPTS_WIDTH, ""))

    for o in opts:
        if o.is_group:
            out.append("\n")
            need_newline = False
            if o.help:
                out.append("%s\n" % o.help)
            continue
        if o.flags & _PARSEOPT_HIDDEN:
            continue
        if need_newline:
            out.append("\n")
            need_newline = False
        pos = 4
        out.append("    ")
        if o.short_name:
            out.append("-%s" % o.short_name)
            pos += 2
        if o.long_name is not None and o.short_name:
            out.append(", ")
            pos += 2
        if o.long_name is not None:
            ln = o.long_name
            if (o.flags & _PARSEOPT_NONEG) or ln.startswith("no-"):
                seg = "--%s" % ln
            else:
                seg = "--[no-]%s" % ln
            out.append(seg)
            pos += len(seg)
        if (o.flags & _PARSEOPT_NOARG) == 0:
            seg = _po_usage_argh(o)
            out.append(seg)
            pos += len(seg)
        help_text = o.help or ""
        cp = 0
        if help_text:
            while cp < len(help_text):
                nl = help_text.find("\n", cp)
                if nl < 0:
                    np = len(help_text)
                else:
                    np = nl + 1
                pad(pos)
                out.append(help_text[cp:np])
                pos = 0
                cp = np
        else:
            pass
        out.append("\n")
    out.append("\n")
    if (not err) and shell_eval:
        out.append("EOF\n")
    return "".join(out)


def _rev_parse_parseopt(args: list[str]) -> int:
    # Port of builtin/rev-parse.c cmd_parseopt. args == argv after "--parseopt".
    keep_dashdash = False
    stop_at_non_option = False
    stuck_long = False
    # Parse our own options up to the first "--".
    rest: list[str] = []
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--":
            rest = args[i:]
            break
        if a == "--keep-dashdash":
            keep_dashdash = True
        elif a == "--stop-at-non-option":
            stop_at_non_option = True
        elif a == "--stuck-long":
            stuck_long = True
        else:
            rest = args[i:]
            break
        i += 1
    else:
        rest = []
    # Need "--" then args after it.
    if not rest or rest[0] != "--":
        # usage_with_options(parseopt_usage) to stderr, exit 129
        sys.stderr.write(_po_render_usage(
            ["git rev-parse --parseopt [<options>] -- [<args>...]"],
            [], False, True))
        return 129
    cmd_args = rest[1:]

    data = _stdin_bytes().decode("utf-8", "surrogateescape")
    in_lines = data.split("\n")
    # strbuf_getline strips a trailing empty element produced by a final newline.
    if in_lines and in_lines[-1] == "":
        in_lines.pop()
    pos = 0
    # usage up to first "--"
    usage: list[str] = []
    found = False
    while pos < len(in_lines):
        line = in_lines[pos]
        pos += 1
        if line == "--":
            found = True
            break
        usage.append(line)
    if not found:
        sys.stderr.write("fatal: premature end of input\n")
        return 128
    if not usage:
        sys.stderr.write("fatal: no usage string given before the `--' separator\n")
        return 128

    opts: list[_PoOpt] = []
    # parse spec lines
    while pos < len(in_lines):
        sb = in_lines[pos]
        pos += 1
        if sb == "":
            continue
        o = _PoOpt()
        # help = first whitespace
        hidx = -1
        for k, ch in enumerate(sb):
            if ch in " \t":
                hidx = k
                break
        if hidx < 0 or hidx == 0:
            o.is_group = True
            o.help = sb.lstrip(" \t")
            opts.append(o)
            continue
        head = sb[:hidx]
        help_text = sb[hidx + 1:].lstrip(" \t")
        o.help = help_text
        o.flags = _PARSEOPT_NOARG
        # name(s): strpbrk for *=?!
        sidx = len(head)
        for k, ch in enumerate(head):
            if ch in "*=?!":
                sidx = k
                break
        if sidx == 0:
            sys.stderr.write("fatal: missing opt-spec before option flags\n")
            return 128
        namepart = head[:sidx]
        if sidx == 1:
            o.short_name = head[0]
        elif len(namepart) >= 2 and namepart[1] != ",":
            o.long_name = namepart
        else:
            o.short_name = head[0]
            o.long_name = namepart[2:]
        # flags
        k = sidx
        while k < len(head):
            ch = head[k]
            if ch == "=":
                o.flags &= ~_PARSEOPT_NOARG
            elif ch == "?":
                o.flags &= ~_PARSEOPT_NOARG
                o.flags |= _PARSEOPT_OPTARG
            elif ch == "!":
                o.flags |= _PARSEOPT_NONEG
            elif ch == "*":
                o.flags |= _PARSEOPT_HIDDEN
            else:
                break
            k += 1
        if k < len(head):
            o.argh = head[k:]
        opts.append(o)

    # Build lookup tables.
    by_long = {o.long_name: o for o in opts if (not o.is_group) and o.long_name is not None}
    by_short = {o.short_name: o for o in opts if (not o.is_group) and o.short_name}

    parsed: list[str] = ["set --"]

    def dump(o: _PoOpt, arg: Optional[str], unset: bool) -> None:
        if unset:
            parsed.append(" --no-%s" % o.long_name)
        elif o.short_name and (o.long_name is None or not stuck_long):
            parsed.append(" -%s" % o.short_name)
        else:
            parsed.append(" --%s" % o.long_name)
        if arg is not None:
            if not stuck_long:
                parsed.append(" ")
            elif o.long_name is not None:
                parsed.append("=")
            parsed.append(_sq_quote_buf(arg))

    def show_usage(err: bool) -> int:
        sys.stdout.write(_po_render_usage(usage, opts, True, err))
        return 129

    # mini parse_options loop
    out_args: list[str] = []
    j = 0
    n = len(cmd_args)
    seen_dd = False
    while j < n:
        a = cmd_args[j]
        if a == "" or a[0] != "-" or a == "-":
            # non-option
            if stop_at_non_option:
                out_args.extend(cmd_args[j:])
                j = n
                break
            out_args.append(a)
            j += 1
            continue
        if a == "--":
            if keep_dashdash:
                out_args.append("--")
            j += 1
            out_args.extend(cmd_args[j:])
            j = n
            seen_dd = True
            break
        if a.startswith("--"):
            body = a[2:]
            if body == "help" or body == "help-all":
                return show_usage(False)
            # split off =value
            eq = body.find("=")
            if eq >= 0:
                name = body[:eq]
                val = body[eq + 1:]
            else:
                name = body
                val = None
            unset = False
            o = by_long.get(name)
            if o is None and name.startswith("no-"):
                cand = by_long.get(name[3:])
                if cand is not None and not (cand.flags & _PARSEOPT_NONEG):
                    o = cand
                    unset = True
            if o is None:
                sys.stderr.write("error: unknown option `%s'\n" % body)
                show_usage(False)
                return 129
            if unset:
                dump(o, None, True)
                j += 1
                continue
            if o.flags & _PARSEOPT_NOARG:
                if val is not None:
                    sys.stderr.write("error: option `%s' takes no value\n" % name)
                    show_usage(False)
                    return 129
                dump(o, None, False)
                j += 1
                continue
            if o.flags & _PARSEOPT_OPTARG:
                dump(o, val, False)
                j += 1
                continue
            # required arg
            if val is not None:
                dump(o, val, False)
                j += 1
                continue
            if j + 1 >= n:
                sys.stderr.write("error: option `%s' requires a value\n" % name)
                show_usage(False)
                return 129
            dump(o, cmd_args[j + 1], False)
            j += 2
            continue
        else:
            # short option cluster
            cluster = a[1:]
            ci = 0
            handled = True
            while ci < len(cluster):
                c = cluster[ci]
                if c == "h":
                    return show_usage(False)
                o = by_short.get(c)
                if o is None:
                    sys.stderr.write("error: unknown switch `%s'\n" % c)
                    show_usage(False)
                    return 129
                if o.flags & _PARSEOPT_NOARG:
                    dump(o, None, False)
                    ci += 1
                    continue
                # has-arg: rest of cluster is the value, or next arg
                rest_val = cluster[ci + 1:]
                if o.flags & _PARSEOPT_OPTARG:
                    dump(o, rest_val if rest_val else None, False)
                    ci = len(cluster)
                    break
                if rest_val:
                    dump(o, rest_val, False)
                    ci = len(cluster)
                    break
                if j + 1 >= n:
                    sys.stderr.write("error: switch `%s' requires a value\n" % c)
                    show_usage(False)
                    return 129
                dump(o, cmd_args[j + 1], False)
                j += 1
                ci = len(cluster)
                break
            j += 1
            continue

    parsed.append(" --")
    parsed.append(_sq_quote_argv(out_args))
    sys.stdout.write("".join(parsed) + "\n")
    return 0


def cmd_rev_parse(argv: list[str]) -> int:
    # Standalone modes dispatched before any repo setup (argv[1] in C).
    if argv and argv[0] == "--parseopt":
        return _rev_parse_parseopt(argv[1:])
    if argv and argv[0] == "--sq-quote":
        sys.stdout.write(_sq_quote_argv(argv[1:]) + "\n")
        return 0
    repo: Optional[Repository] = None

    def R() -> Repository:
        nonlocal repo
        if repo is None:
            repo = _repo()
        return repo

    # --verify requires exactly one revision; reject extras before any output.
    if "--verify" in argv:
        rev_args = [a for a in argv if not a.startswith("-")]
        if len(rev_args) > 1:
            if "-q" not in argv and "--quiet" not in argv:
                _err("fatal: Needed a single revision")
                return 128
            return 1

    abbrev = 0            # 0 = full hex; >0 = abbreviate to N chars
    symbolic: Optional[str] = None   # None | "asis" | "full" | "abbrev"
    sym_refs = False      # --symbolic: print ref names for --all/--branches/...
    verify = False
    quiet = False
    path_format: Optional[str] = None
    verified_count = 0
    pending_git_path = False
    pending_n = False         # bare "-n" consumes the next token as the count
    pending_default = False   # --default consumes the next token
    pending_resolve_git_dir = False   # --resolve-git-dir consumes next token
    output_sq = False         # --sq shell-quotes show() output
    def_rev: Optional[str] = None   # fallback rev set by --default
    # builtin/rev-parse.c output filter bits. DO_REVS/DO_FLAGS gate rev and flag
    # output; DO_NONFLAGS|DO_NOREV together gate path output (show_file).
    # --revs-only clears DO_NOREV (suppresses paths); --no-revs clears DO_REVS
    # (suppresses revisions).
    DO_REVS, DO_NOREV, DO_FLAGS, DO_NONFLAGS = 1, 2, 4, 8
    filter_bits = DO_REVS | DO_NOREV | DO_FLAGS | DO_NONFLAGS
    # as_is: 0 = normal; 1 = after a bare token failed to resolve (still verify
    # the rest as filenames); 2 = after "--" (do not verify, just echo paths).
    as_is = 0
    has_dashdash = "--" in argv
    seen_end_of_options = False
    output_algo = None        # --output-object-format=<fmt>; sha1-only here
    # builtin/rev-parse.c ref_excludes: --exclude=<pat> accumulates patterns
    # (excluded_refs); --exclude-hidden=<section> sets hidden_refs_configured.
    # Both are consulted by the next ref-enumeration option then cleared.
    excluded_refs: list[str] = []
    hidden_refs_configured = False

    def ref_excluded(name: str) -> bool:
        # Port of revision.c ref_excluded: wildmatch each excluded pattern
        # against the (possibly trimmed) ref name. No hidden-refs config to
        # consult here (GIT_CONFIG_NOSYSTEM/empty config), so only patterns.
        import fnmatch as _fn
        for pat in excluded_refs:
            if _fn.fnmatchcase(name, pat):
                return True
        return False

    def clear_ref_exclusions() -> None:
        nonlocal hidden_refs_configured
        excluded_refs.clear()
        hidden_refs_configured = False

    def handle_ref_opt(pattern: Optional[str], prefix: Optional[str]) -> None:
        # Port of builtin/rev-parse.c handle_ref_opt + refs_for_each_ref_ext.
        # Enumerate refs under `prefix`, optionally filtered by `pattern`
        # (a glob value), trimming `prefix` from the name passed to show_rev.
        import fnmatch as _fn
        real_pattern: Optional[str] = None
        if pattern is not None:
            if prefix is None and not pattern.startswith("refs/"):
                real_pattern = "refs/" + pattern
            elif prefix is not None:
                real_pattern = prefix + pattern
            else:
                real_pattern = pattern
            # Append implied "/*" when the value has no glob specials.
            if not any(c in pattern for c in "*?[]"):
                if not real_pattern.endswith("/"):
                    real_pattern += "/"
                real_pattern += "*"
        trim = len(prefix) if prefix else 0
        for refname, refsha in _enumerate_refs(R()):
            if prefix is not None and not refname.startswith(prefix):
                continue
            if real_pattern is not None and not _fn.fnmatchcase(refname, real_pattern):
                continue
            # The pattern matches the full name; trimming happens for the
            # displayed/excluded name (matches for_each_filter_refs).
            shown = refname[trim:] if trim else refname
            if ref_excluded(shown):
                continue
            show_rev("normal", refsha, shown)
        clear_ref_exclusions()

    def show(arg: str) -> None:
        # Port of show(): when output_sq is set, shell-quote with a trailing
        # space and NO newline; otherwise puts() the argument with a newline.
        if output_sq:
            buf = ["'"]
            for ch in arg:
                if ch == "'":
                    buf.append("'\\'")
                buf.append(ch)
            buf.append("' ")
            sys.stdout.write("".join(buf))
        else:
            _print(arg)

    def show_default() -> bool:
        # Port of show_default(): resolve the pending --default rev and show it.
        nonlocal def_rev
        if def_rev is not None:
            s = def_rev
            def_rev = None
            sha = refs_mod.rev_parse(R(), s)
            if sha is not None:
                show_rev("normal", sha, s)
                return True
        return False

    def show_rev(typ: str, sha: str, name: Optional[str]) -> None:
        # Port of show_rev(): respects DO_REVS, symbolic modes and output_sq.
        nonlocal def_rev
        if not (filter_bits & DO_REVS):
            return
        def_rev = None
        pfx = "^" if typ == "reversed" else ""
        if symbolic is not None and name is not None:
            if symbolic in ("full", "abbrev"):
                full = refs_mod.dwim_full_name(R(), name)
                if full is None:
                    return
                shown = refs_mod.shorten_ref(full) if symbolic == "abbrev" else full
                show(pfx + shown)
            else:  # asis
                show(pfx + name)
        elif abbrev:
            show(pfx + sha[:abbrev])
        else:
            show(pfx + sha)

    def show_file(arg: str) -> bool:
        # Port of show_file: emit a non-flag, non-rev token (a path or "--")
        # only when both DO_NONFLAGS and DO_NOREV are set. show_default() runs
        # first (matching C), then the file itself is shown via show().
        show_default()
        if (filter_bits & (DO_NONFLAGS | DO_NOREV)) == (DO_NONFLAGS | DO_NOREV):
            show(arg)
            return True
        return False

    def verify_filename(arg: str) -> Optional[int]:
        # Port of verify_filename: a path that looks like a pathspec or exists
        # on disk is accepted; otherwise die with the ambiguous-argument error.
        if arg and arg[0] == "-":
            _err(f"fatal: option '{arg}' must come before non-option arguments")
            return 128
        if _looks_like_pathspec(arg) or (R().path / arg).exists() or os.path.lexists(arg):
            return None
        _err(f"fatal: ambiguous argument '{arg}': unknown revision or path not in the working tree.")
        _err("Use '--' to separate paths from revisions, like this:")
        _err("'git <command> [<revision>...] -- [<file>...]'")
        return 128

    def resolve_arg(arg: str) -> Optional[int]:
        # "Not a flag argument" path of builtin/rev-parse.c: resolve a token as
        # a revision; on failure treat it as a filename (verify_filename).
        # Returns an exit code to propagate, or None to continue the loop.
        nonlocal as_is, verified_count
        r = R()
        sha = refs_mod.rev_parse(r, arg)
        if sha is None:
            # `<rev>:<path>` where the rev resolves but the path is absent gets
            # git's specific message rather than the generic ambiguous-arg one.
            if ":" in arg and not arg.startswith(("^", "-", ":")):
                left, _, path = arg.partition(":")
                if left and not path.startswith("/") and refs_mod.rev_parse(r, left) is not None:
                    _print(arg)
                    _err(f"fatal: path '{path}' does not exist in '{left}'")
                    return 128
            if verify:
                if quiet:
                    return 1
                _err("fatal: Needed a single revision")
                return 128
            # An unresolved token with a preceding "--" is a hard error; without
            # one it becomes a filename: as_is=1, echo it (subject to the
            # filter), then verify it names a real path.
            if has_dashdash:
                _err(f"fatal: bad revision '{arg}'")
                return 128
            as_is = 1
            if not show_file(arg):
                return None
            return verify_filename(arg)
        if verify:
            verified_count += 1
            if verified_count > 1:
                if quiet:
                    return 1
                _err("fatal: Needed a single revision")
                return 128
        # show_rev: a resolved revision is printed only when DO_REVS is set.
        typ = "reversed" if arg.startswith("^") else "normal"
        name = arg[1:] if typ == "reversed" else arg
        show_rev(typ, sha, name)
        return None

    for arg in argv:
        if as_is:
            # After "--" (as_is==2) just echo; after a failed bare token
            # (as_is==1) echo then verify each subsequent filename.
            if show_file(arg) and as_is < 2:
                rc = verify_filename(arg)
                if rc is not None:
                    return rc
            continue
        if pending_default:
            # --default consumes the next token verbatim as the fallback rev.
            pending_default = False
            def_rev = arg
            continue
        if pending_resolve_git_dir:
            # --resolve-git-dir <path>: validate/resolve a path as a gitdir.
            pending_resolve_git_dir = False
            resolved = _resolve_gitdir(arg)
            if resolved is None:
                _err(f"fatal: not a gitdir '{arg}'")
                return 128
            _print(resolved)
            continue
        if arg == "--":
            # Pass on the "--" separator when we are showing flags or revs.
            as_is = 2
            if filter_bits & (DO_FLAGS | DO_REVS):
                show_file(arg)
            continue
        # builtin/rev-parse.c: the entire dash-flag block is gated by
        # !seen_end_of_options. After --end-of-options any dashed token (other
        # than the "--" handled above) falls through to the rev/filename path.
        # We mirror that by routing such args straight to resolve_arg().
        if seen_end_of_options:
            rc = resolve_arg(arg)
            if rc is not None:
                return rc
            continue
        if arg == "--git-dir":
            r = R()
            cwd = Path(os.getcwd()).resolve()
            if path_format == "absolute":
                _print(str(r.gitdir))
            elif cwd == r.path and not r.bare:
                _print(os.path.relpath(r.gitdir, cwd))
            else:
                _print(str(r.gitdir))
            continue
        if arg == "--absolute-git-dir":
            _print(str(R().gitdir))
            continue
        if arg == "--git-common-dir":
            r = R()
            cwd = Path(os.getcwd()).resolve()
            if cwd == r.path and not r.bare:
                _print(os.path.relpath(r.gitdir, cwd))
            else:
                _print(str(r.gitdir))
            continue
        if arg == "--show-object-format" or arg.startswith("--show-object-format="):
            # --show-object-format[=(storage|compat|input|output)]: prints the
            # hash algorithm. compat has no peer here (sha1-only), so it prints
            # an empty line; any other mode prints the storage algo name.
            val = arg.split("=", 1)[1] if "=" in arg else "storage"
            if val not in ("storage", "compat", "input", "output"):
                _err(f"fatal: unknown mode for --show-object-format: {val}")
                return 128
            if val == "compat":
                _print("")
            else:
                _print(R().object_format())
            continue
        if arg == "--show-ref-format":
            # builtin/rev-parse.c: ref_storage_format_to_name on the repo's ref
            # backend. pythongit only implements the "files" backend (reftable
            # is read-only/experimental). Report what the repo uses.
            R()
            _print("reftable" if refs_mod.uses_reftable(repo) else "files")
            continue
        if arg == "--end-of-options":
            # Any subsequent dashed token is treated as a non-option (path).
            seen_end_of_options = True
            if filter_bits & (DO_FLAGS | DO_REVS):
                show_file(arg)
            continue
        if arg.startswith("--output-object-format="):
            # Sets the output hash algo. sha1-only here: "sha1"/"storage" are
            # accepted (no-op). An empty "=" value is a non-NULL empty string,
            # so it falls through to the "unsupported object format" error
            # (only the bare spelling yields the "no object format" message).
            val = arg.split("=", 1)[1]
            if val in ("sha1", "storage"):
                output_algo = val
                continue
            _err(f"fatal: unsupported object format: {val}")
            return 128
        if arg == "--output-object-format":
            # Bare form: opt_with_value requires the value to be "="-attached;
            # the bare spelling yields value NULL -> "no object format".
            _err("fatal: no object format specified")
            return 128
        if pending_git_path:
            pending_git_path = False
            r = R()
            cwd = Path(os.getcwd()).resolve()
            base = os.path.relpath(r.gitdir, cwd) if (cwd == r.path and not r.bare) else str(r.gitdir)
            _print(f"{base}/{arg}" if arg else base)
            continue
        if pending_n:
            # The count consumed by a bare "-n"; C shows BOTH "-n" and the value
            # together, only after confirming the value exists (so a dangling
            # "-n" prints nothing before dying).
            pending_n = False
            if (filter_bits & DO_FLAGS) and (filter_bits & DO_REVS):
                show("-n")
                show(arg)
            continue
        if arg == "-n":
            # Bare "-n" takes the NEXT token as the count (shown on consume).
            pending_n = True
            continue
        if arg.startswith("-n") and len(arg) > 2:
            # Attached form "-nN": show as a single flag (gated by FLAGS&REVS).
            if (filter_bits & DO_FLAGS) and (filter_bits & DO_REVS):
                show(arg)
            continue
        if arg == "--git-path":
            pending_git_path = True
            continue
        # NOTE: builtin/rev-parse.c only matches the exact spelling "--git-path"
        # (value in the NEXT argument). The "=" form "--git-path=hooks" is NOT
        # recognized and falls through to show_flag (echoed verbatim).
        if arg == "--show-toplevel":
            _print(str(R().path))
            continue
        if arg == "--show-prefix":
            r = R()
            rel = os.path.relpath(Path(os.getcwd()).resolve(), r.path)
            _print("" if rel == "." else rel.replace(os.sep, "/") + "/")
            continue
        if arg == "--show-cdup":
            r = R()
            rel = os.path.relpath(Path(os.getcwd()).resolve(), r.path)
            depth = 0 if rel == "." else len(Path(rel).parts)
            _print("../" * depth)
            continue
        if arg == "--is-inside-work-tree":
            r = R()
            inside_git = _is_inside(Path(os.getcwd()).resolve(), r.gitdir)
            _print("false" if (r.bare or inside_git) else "true")
            continue
        if arg == "--is-inside-git-dir":
            r = R()
            _print("true" if _is_inside(Path(os.getcwd()).resolve(), r.gitdir) else "false")
            continue
        if arg == "--is-bare-repository":
            _print("true" if R().bare else "false")
            continue
        if arg == "--is-shallow-repository":
            _print("true" if (R().gitdir / "shallow").exists() else "false")
            continue
        if arg == "--show-superproject-working-tree":
            # pythongit has no submodule support; never inside a superproject.
            continue
        if arg.startswith("--path-format="):
            path_format = arg.split("=", 1)[1]
            continue
        if arg == "--all":
            # --all enumerates ALL refs (full names), consulting ref_excludes,
            # then clears them. Not gated by hidden_refs_configured.
            for refname, refsha in _enumerate_refs(R()):
                if ref_excluded(refname):
                    continue
                show_rev("normal", refsha, refname)
            clear_ref_exclusions()
            continue
        if arg == "--bisect":
            # Enumerate refs/bisect/bad* (normal) then refs/bisect/good* (anti).
            for refname, refsha in _enumerate_refs(R()):
                if refname.startswith("refs/bisect/bad"):
                    show_rev("normal", refsha, refname)
            for refname, refsha in _enumerate_refs(R()):
                if refname.startswith("refs/bisect/good"):
                    show_rev("reversed", refsha, refname)
            continue
        if arg == "--branches" or arg.startswith("--branches="):
            if hidden_refs_configured:
                _err("error: options '--exclude-hidden' and '--branches' cannot be used together")
                return 255
            handle_ref_opt(arg.split("=", 1)[1] if "=" in arg else None, "refs/heads/")
            continue
        if arg == "--tags" or arg.startswith("--tags="):
            if hidden_refs_configured:
                _err("error: options '--exclude-hidden' and '--tags' cannot be used together")
                return 255
            handle_ref_opt(arg.split("=", 1)[1] if "=" in arg else None, "refs/tags/")
            continue
        if arg == "--remotes" or arg.startswith("--remotes="):
            if hidden_refs_configured:
                _err("error: options '--exclude-hidden' and '--remotes' cannot be used together")
                return 255
            handle_ref_opt(arg.split("=", 1)[1] if "=" in arg else None, "refs/remotes/")
            continue
        if arg.startswith("--glob="):
            handle_ref_opt(arg.split("=", 1)[1], None)
            continue
        if arg.startswith("--exclude="):
            excluded_refs.append(arg.split("=", 1)[1])
            continue
        if arg.startswith("--exclude-hidden="):
            section = arg.split("=", 1)[1]
            if section not in ("fetch", "receive", "uploadpack"):
                _err(f"fatal: unsupported section for hidden refs: {section}")
                return 128
            if hidden_refs_configured:
                _err("fatal: --exclude-hidden= passed more than once")
                return 128
            hidden_refs_configured = True
            continue
        if arg == "--verify":
            # builtin/rev-parse.c: --verify clears DO_FLAGS and DO_NOREV so only
            # the verified revision is shown (no flag/path echo).
            verify = True
            filter_bits &= ~(DO_FLAGS | DO_NOREV)
            continue
        if arg in ("-q", "--quiet"):
            quiet = True
            continue
        if arg == "--short":
            abbrev = 7
            continue
        if arg.startswith("--short="):
            try:
                abbrev = int(arg.split("=", 1)[1])
            except ValueError:
                abbrev = 7
            continue
        if arg == "--no-revs":
            filter_bits &= ~DO_REVS
            continue
        if arg == "--revs-only":
            filter_bits &= ~DO_NOREV
            continue
        if arg == "--sq":
            output_sq = True
            continue
        if arg == "--default":
            pending_default = True
            continue
        if arg == "--symbolic":
            # SHOW_SYMBOLIC_ASIS: print each rev/ref in its original name form.
            symbolic = "asis"
            sym_refs = True
            continue
        if arg == "--flags":
            filter_bits &= ~DO_NONFLAGS
            continue
        if arg == "--no-flags":
            filter_bits &= ~DO_FLAGS
            continue
        if arg == "--local-env-vars":
            for v in _LOCAL_REPO_ENV:
                _print(v)
            continue
        if arg == "--resolve-git-dir":
            pending_resolve_git_dir = True
            continue
        if arg.startswith("--disambiguate="):
            pfx = arg.split("=", 1)[1].lower()
            if pfx and len(pfx) >= 2 and all(c in "0123456789abcdef" for c in pfx):
                for full in _all_object_shas(R()):
                    if full.startswith(pfx):
                        _print(full)
            continue
        if arg.startswith(("--since=", "--after=")):
            # Translated to --max-age=<epoch>; requires DO_FLAGS and DO_REVS.
            if (filter_bits & (DO_FLAGS | DO_REVS)) == (DO_FLAGS | DO_REVS):
                show(f"--max-age={_approxidate(arg.split('=', 1)[1])}")
            continue
        if arg.startswith(("--before=", "--until=")):
            if (filter_bits & (DO_FLAGS | DO_REVS)) == (DO_FLAGS | DO_REVS):
                show(f"--min-age={_approxidate(arg.split('=', 1)[1])}")
            continue
        if arg == "--shared-index-path":
            # Only meaningful with a split index, which pythongit never writes.
            continue
        if arg == "--symbolic-full-name":
            symbolic = "full"
            continue
        if arg == "--abbrev-ref" or arg.startswith("--abbrev-ref="):
            symbolic = "abbrev"
            continue
        if arg.startswith("^") and len(arg) > 1 and arg[1] != "{":
            r = R()
            sha = refs_mod.rev_parse(r, arg[1:])
            if sha is not None:
                # A reversed revision: gated by DO_REVS (show_rev). The name
                # passed for symbolic display is the part after the leading "^".
                show_rev("reversed", sha, arg[1:])
                continue
        if arg.startswith("-") and arg != "-":
            # An unrecognized dashed arg is a flag (show_flag): printed only if
            # DO_FLAGS is set and the appropriate rev/no-rev bit is set. Generic
            # flags are non-rev arguments, so they need DO_NOREV.
            if (filter_bits & DO_FLAGS) and (filter_bits & DO_NOREV):
                show(arg)
            continue
        # A revision argument (show_rev): suppressed when DO_REVS is cleared
        # (--no-revs). The token must still resolve; an unresolved one falls
        # through to the filename path (resolve_arg).
        rc = resolve_arg(arg)
        if rc is not None:
            return rc
    if pending_n:
        _err("fatal: -n requires an argument")
        return 128
    if pending_default:
        _err("fatal: --default requires an argument")
        return 128
    if pending_resolve_git_dir:
        _err("fatal: --resolve-git-dir requires an argument")
        return 128
    # show_default() at the very end if no rev was emitted (C: !verify branch).
    show_default()
    return 0


_LS_FILES_USAGE = (
    "usage: git ls-files [<options>] [<file>...]\n"
    "\n"
    "    -z                    separate paths with the NUL character\n"
    "    -t                    identify the file status with tags\n"
    "    -v                    use lowercase letters for 'assume unchanged' files\n"
    "    -f                    use lowercase letters for 'fsmonitor clean' files\n"
    "    -c, --[no-]cached     show cached files in the output (default)\n"
    "    -d, --[no-]deleted    show deleted files in the output\n"
    "    -m, --[no-]modified   show modified files in the output\n"
    "    -o, --[no-]others     show other files in the output\n"
    "    -i, --[no-]ignored    show ignored files in the output\n"
    "    -s, --[no-]stage      show staged contents' object name in the output\n"
    "    -k, --[no-]killed     show files on the filesystem that need to be removed\n"
    "    --[no-]directory      show 'other' directories' names only\n"
    "    --[no-]eol            show line endings of files\n"
    "    --[no-]empty-directory\n"
    "                          don't show empty directories\n"
    "    -u, --[no-]unmerged   show unmerged files in the output\n"
    "    --[no-]resolve-undo   show resolve-undo information\n"
    "    -x, --exclude <pattern>\n"
    "                          skip files matching pattern\n"
    "    -X, --exclude-from <file>\n"
    "                          read exclude patterns from <file>\n"
    "    --[no-]exclude-per-directory <file>\n"
    "                          read additional per-directory exclude patterns in <file>\n"
    "    --exclude-standard    add the standard git exclusions\n"
    "    --full-name           make the output relative to the project top directory\n"
    "    --[no-]recurse-submodules\n"
    "                          recurse through submodules\n"
    "    --[no-]error-unmatch  if any <file> is not in the index, treat this as an error\n"
    "    --[no-]with-tree <tree-ish>\n"
    "                          pretend that paths removed since <tree-ish> are still present\n"
    "    --[no-]abbrev[=<n>]   use <n> digits to display object names\n"
    "    --[no-]debug          show debugging data\n"
    "    --[no-]deduplicate    suppress duplicate entries\n"
    "    --[no-]sparse         show sparse directories in the presence of a sparse index\n"
    "    --format <format>     format to use for the output\n"
    "\n"
)


def cmd_ls_files(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit ls-files", add_help=False)
    ap.add_argument("-s", "--stage", action="store_true")
    ap.add_argument("-c", "--cached", action="store_true")
    ap.add_argument("-m", "--modified", action="store_true")
    ap.add_argument("-o", "--others", action="store_true")
    ap.add_argument("-d", "--deleted", action="store_true")
    ap.add_argument("-i", "--ignored", action="store_true")
    ap.add_argument("-u", "--unmerged", action="store_true")
    ap.add_argument("-k", "--killed", action="store_true")
    ap.add_argument("-x", "--exclude", action="append", default=None)
    ap.add_argument("-X", "--exclude-from", dest="exclude_from", action="append", default=None)
    ap.add_argument("--exclude-standard", action="store_true")
    ap.add_argument("--error-unmatch", action="store_true")
    ap.add_argument("--full-name", action="store_true")
    ap.add_argument("-t", dest="tag", action="store_true")
    ap.add_argument("-v", dest="tag_v", action="store_true")
    ap.add_argument("-f", dest="tag_f", action="store_true")
    ap.add_argument("--format", default=None)
    ap.add_argument("--abbrev", nargs="?", const=7, type=int, default=None)
    ap.add_argument("-z", dest="nul", action="store_true")
    ap.add_argument("--eol", action="store_true")
    ap.add_argument("--directory", dest="directory", action="store_true")
    ap.add_argument("--empty-directory", dest="hide_empty", action="store_false", default=False)
    ap.add_argument("--no-empty-directory", dest="hide_empty", action="store_true")
    ap.add_argument("--with-tree", dest="with_tree", default=None)
    ap.add_argument("--debug", action="store_true")
    ap.add_argument("--deduplicate", action="store_true")
    ap.add_argument("--resolve-undo", dest="resolve_undo", action="store_true")
    ap.add_argument("--sparse", action="store_true")
    ap.add_argument("--recurse-submodules", dest="recurse_submodules", action="store_true")
    ap.add_argument("--exclude-per-directory", dest="exclude_per_directory", default=None)
    ap.add_argument("paths", nargs="*")
    argv = ["--abbrev=7" if a == "--abbrev" else a for a in argv]
    args = ap.parse_args(argv)
    # -v/-f are tag variants (lowercase markers for assume-unchanged / fsmonitor,
    # which we don't track, so they render like -t).
    if args.tag_v or args.tag_f:
        args.tag = True
    repo = _repo()
    # --format cannot combine with the output modes that aren't a plain path list.
    if args.format is not None and (args.stage or args.others or args.killed
                                    or args.resolve_undo or args.deduplicate
                                    or args.eol or args.tag or args.tag_v
                                    or args.tag_f):
        _err("fatal: --format cannot be used with -s, -o, -k, -t, "
             "--resolve-undo, --deduplicate, --eol")
        sys.stderr.write("\n" + _LS_FILES_USAGE)
        return 129
    # -i/--ignored only makes sense alongside -o or -c (explicitly): the others
    # scan and the cached listing are the only sources it can filter
    # (builtin/ls-files.c). The check runs before the no-flags->cached default.
    if args.ignored and not args.others and not args.cached:
        _err("fatal: ls-files -i must be used with either -o or -c")
        return 128
    idx = read_index(repo)
    eol = "\0" if args.nul else "\n"

    # Subdirectory scoping (builtin/ls-files.c). `prefix` is cwd relative to the
    # work-tree root with a trailing slash (empty at the root). With no pathspec
    # the listing is implicitly limited to that subtree; pathspecs are resolved
    # relative to cwd; output is relative to cwd unless --full-name is given.
    try:
        rel_cwd = os.path.relpath(Path(os.getcwd()).resolve(), repo.path)
    except ValueError:
        rel_cwd = "."
    prefix = "" if rel_cwd == "." else rel_cwd.replace(os.sep, "/") + "/"

    def _to_repo_path(ps: str) -> str:
        # Resolve a user pathspec (relative to cwd) to a work-tree-root path.
        if prefix:
            joined = os.path.normpath(os.path.join(prefix, ps))
            return "" if joined == "." else joined.replace(os.sep, "/")
        return ps

    # Repo-root-relative pathspecs used for matching the index.
    spec_paths = [_to_repo_path(p) for p in args.paths]
    # Implicit scope: with no pathspec but a prefix, limit to the subtree.
    if not spec_paths and prefix:
        scope_specs = [prefix.rstrip("/")]
    else:
        scope_specs = spec_paths

    def _out_name(p: str) -> str:
        # write_name_quoted_relative: relative to cwd unless --full-name.
        if args.full_name or not prefix:
            return p
        return os.path.relpath(p, prefix.rstrip("/")).replace(os.sep, "/")

    if args.error_unmatch:
        tracked = set(idx.by_path())
        for ps, norm_full in zip(args.paths, spec_paths):
            norm = norm_full.rstrip("/")
            if not (norm in tracked or any(t.startswith(norm + "/") for t in tracked)):
                _err(f"error: pathspec '{ps}' did not match any file(s) known to git")
                _err("Did you forget to 'git add'?")
                return 1

    def match(p: str) -> bool:
        if not scope_specs:
            return True
        return any(p == ps or p.startswith(ps.rstrip("/") + "/") for ps in scope_specs)

    want_cached = args.cached or args.stage
    if not (want_cached or args.modified or args.others or args.deleted
            or args.unmerged or args.killed or args.resolve_undo):
        want_cached = True

    def _tag(prefix: str, text: str) -> str:
        return (prefix + " " + text) if args.tag else text

    # Build the exclude matcher for -o from --exclude-standard, -x and -X.
    from . import ignore as ignore_mod
    exc = None
    if args.others or args.ignored:
        exc = ignore_mod.IgnoreSet()
        if args.exclude_standard:
            exc.rules.extend(ignore_mod.load(repo.path).rules)
        for pat in (args.exclude or []):
            exc.rules.append(ignore_mod.IgnoreRule(pat, "", "", 0))
        for xf in (args.exclude_from or []):
            exc.add_file(Path(xf), "", xf)

    def _is_excluded(p: str) -> bool:
        return exc is not None and exc.is_ignored(p)

    # --with-tree overlay: add tree paths absent from the index as synthetic
    # cache entries (overlay_tree_on_index), so removed-since-<tree-ish> paths
    # still appear in the cached/deleted listing.
    overlay_entries = []
    if args.with_tree is not None:
        tsha = refs_mod.rev_parse(repo, args.with_tree)
        if tsha:
            try:
                tt, tdata = objs.read_object(repo, tsha)
                if tt == "commit":
                    tsha = objs.parse_commit(tdata).tree
                elif tt == "tag":
                    tsha = refs_mod._peel_to_type(repo, tsha, "tree") or tsha
            except KeyError:
                tsha = None
        if tsha:
            in_index = set(idx.by_path())
            for tp, tmode, tblob in workdir.iter_tree_files(repo, tsha):
                if tp in in_index:
                    continue

                class _Ov:
                    pass
                ov = _Ov()
                ov.path = tp
                ov.sha = tblob
                ov.stage = 0
                ov.skip_worktree = False
                ov.flags = 0
                ov._mode = tmode
                ov.mode_str = (lambda m=tmode: m if isinstance(m, str) else f"{m:06o}")
                overlay_entries.append(ov)

    # C Git's show_files emits groups in a fixed order with no deduplication:
    # first 'others'/'killed' (from the directory scan, sorted), then a single
    # pass over the index where each entry shows its cached/stage line followed
    # by its deleted/modified line.
    out: list[str] = []
    status = None
    if args.modified or args.deleted or args.others:
        status = workdir.status(repo, include_ignored=True)

    def _eol_prefix(entry, path: str) -> str:
        return _ls_files_eolinfo(repo, entry, path) if args.eol else ""

    if args.others and status is not None:
        others = []
        untracked = list(status["untracked"])
        if args.directory:
            untracked = _ls_files_collapse_dirs(repo, untracked, args.hide_empty)
        for p in untracked:
            is_dir_entry = p.endswith("/")
            mp = p.rstrip("/")
            if not match(mp if is_dir_entry else p):
                continue
            # Default: hide excluded files; -i: show only excluded files.
            if args.ignored != _is_excluded(mp if is_dir_entry else p):
                continue
            others.append((p, _tag("?", _eol_prefix(None, mp) + _out_name(p))))
        for _p, line in sorted(others, key=lambda t: t[0]):
            out.append(line)

    modified_set = set(status["modified"]) | set(status["missing"]) if status else set()
    missing_set = set(status["missing"]) if status else set()
    all_cache = list(idx.entries) + overlay_entries
    for e in sorted(all_cache, key=lambda e: (e.path, getattr(e, "stage", 0))):
        st = getattr(e, "stage", 0)
        if not match(e.path):
            continue
        show_this_cached = want_cached or (args.unmerged and st != 0)
        if show_this_cached and not (args.ignored and not _is_excluded(e.path)):
            tag = "S" if (st == 0 and e.skip_worktree) else ("M" if st != 0 else "H")
            # -v lowercases the tag for assume-unchanged (CE_VALID) entries.
            if args.tag_v and (e.flags & 0x8000):
                tag = tag.lower()
            if args.format is not None:
                out.append(_ls_files_format(repo, e, args.format, args.abbrev,
                                            _out_name(e.path)))
            elif args.stage or args.unmerged:
                sha = e.sha[:args.abbrev] if args.abbrev is not None else e.sha
                out.append(_tag(tag, _eol_prefix(e, e.path)
                                + f"{e.mode_str()} {sha} {st}\t{_out_name(e.path)}"))
            else:
                out.append(_tag(tag, _eol_prefix(e, e.path) + _out_name(e.path)))
            if args.debug:
                out.extend(_ls_files_debug_lines(e))
        if args.deleted and e.path in missing_set:
            out.append(_tag("R", _eol_prefix(e, e.path) + _out_name(e.path)))
        if args.modified and e.path in modified_set:
            out.append(_tag("C", _eol_prefix(e, e.path) + _out_name(e.path)))

    # --deduplicate: suppress consecutive duplicate output lines (git compares
    # against the previous emitted line).
    if args.deduplicate:
        deduped = []
        prev = None
        for line in out:
            if line != prev:
                deduped.append(line)
            prev = line
        out = deduped

    for line in out:
        sys.stdout.write(line + eol)

    # --resolve-undo: print REUC information after the file listing.
    if args.resolve_undo:
        for line in _ls_files_resolve_undo(repo, idx):
            sys.stdout.write(line + eol)
    return 0


def _ls_files_debug_lines(entry) -> list[str]:
    """Port of builtin/ls-files.c print_debug. Stat fields come straight from the
    cache entry (these values are inherently non-deterministic in upstream git
    too, so they are not relied upon for byte-exact parity)."""
    return [
        f"  ctime: {getattr(entry, 'ctime_s', 0)}:{getattr(entry, 'ctime_n', 0)}",
        f"  mtime: {getattr(entry, 'mtime_s', 0)}:{getattr(entry, 'mtime_n', 0)}",
        f"  dev: {getattr(entry, 'dev', 0)}\tino: {getattr(entry, 'ino', 0)}",
        f"  uid: {getattr(entry, 'uid', 0)}\tgid: {getattr(entry, 'gid', 0)}",
        # ce_flags as held in memory: the low 12 bits (name length) are masked
        # out by read_cache, leaving only stage/valid/extended flag bits.
        f"  size: {getattr(entry, 'size', 0)}\tflags: {getattr(entry, 'flags', 0) & 0xf000:x}",
    ]


def _ls_files_resolve_undo(repo: Repository, idx) -> list[str]:
    """Emit resolve-undo (REUC) records the way show_ru_info() does. pygit's
    index reader does not retain the REUC extension, so this is empty unless a
    future reader populates idx.resolve_undo."""
    ru = getattr(idx, "resolve_undo", None)
    if not ru:
        return []
    lines = []
    for path in sorted(ru):
        modes = ru[path]
        for stage in (1, 2, 3):
            mode, sha = modes.get(stage, (0, None))
            if not mode:
                continue
            lines.append(f"{mode:06o} {sha} {stage}\t{path}")
    return lines


def _ls_files_collapse_dirs(repo: Repository, untracked: list[str],
                            hide_empty: bool) -> list[str]:
    """Port of dir.c DIR_SHOW_OTHER_DIRECTORIES: collapse a wholly-untracked
    directory to a single '<dir>/' entry. With hide_empty set
    (DIR_HIDE_EMPTY_DIRECTORIES) an empty directory is not shown."""
    # Group untracked files by their top-level untracked directory. A directory
    # is "other" (collapsed) when none of its contents are tracked — which is
    # already guaranteed here since these are all untracked paths.
    result: list[str] = []
    seen_dirs: set[str] = set()
    tracked = None
    for p in untracked:
        top = p.split("/", 1)[0] if "/" in p else None
        if top is None:
            result.append(p)
            continue
        if top in seen_dirs:
            continue
        seen_dirs.add(top)
        result.append(top + "/")
    # Also surface untracked empty directories on disk (unless hidden).
    if not hide_empty:
        try:
            for entry in os.scandir(repo.path):
                if entry.is_dir() and entry.name != ".git":
                    if entry.name in seen_dirs:
                        continue
                    if not any(os.scandir(entry.path)):
                        result.append(entry.name + "/")
                        seen_dirs.add(entry.name)
        except OSError:
            pass
    return result


def _convert_stats_ascii(data: bytes) -> str:
    """Port of convert.c gather_convert_stats_ascii: classify a buffer's line
    endings as 'lf'/'crlf'/'mixed'/'none'/'-text'."""
    if not data:
        # gather_convert_stats returns 0 for an empty buffer; the ascii switch's
        # default arm then yields "none".
        return "none"
    nul = lonecr = lonelf = crlf = printable = nonprintable = 0
    n = len(data)
    i = 0
    while i < n:
        c = data[i]
        if c == 0x0d:  # '\r'
            if i + 1 < n and data[i + 1] == 0x0a:
                crlf += 1
                i += 2
                continue
            lonecr += 1
            i += 1
            continue
        if c == 0x0a:  # '\n'
            lonelf += 1
            i += 1
            continue
        if c == 127:
            nonprintable += 1
        elif c < 32:
            if c in (0x08, 0x09, 0x1b, 0x0c):
                printable += 1
            elif c == 0:
                nul += 1
                nonprintable += 1
            else:
                nonprintable += 1
        else:
            printable += 1
        i += 1
    if n >= 1 and data[n - 1] == 0x1a:  # trailing EOF (^Z)
        nonprintable -= 1
    is_bin = bool(lonecr) or bool(nul) or ((printable >> 7) < nonprintable)
    if is_bin:
        return "-text"
    BIT_CRLF = 1
    BIT_LF = 2
    stats = 0
    if crlf:
        stats |= BIT_CRLF
    if lonelf:
        stats |= BIT_LF
    if stats == BIT_LF:
        return "lf"
    if stats == BIT_CRLF:
        return "crlf"
    if stats == (BIT_LF | BIT_CRLF):
        return "mixed"
    return "none"


def _ls_files_eolinfo(repo: Repository, entry, path: str) -> str:
    """Port of builtin/ls-files.c write_eolinfo: 'i/<eol> w/<eol> attr/<attr>\\t'."""
    i_txt = ""
    w_txt = ""
    a_txt = ""
    # Cached (index) eol stats — only for regular files.
    if entry is not None and entry.mode_str() in ("100644", "100755"):
        try:
            _t, data = objs.read_object(repo, entry.sha)
            i_txt = _convert_stats_ascii(data)
        except KeyError:
            i_txt = ""
    # Worktree eol stats.
    wt = repo.path / path
    try:
        if wt.is_file() and not wt.is_symlink():
            w_txt = _convert_stats_ascii(wt.read_bytes())
    except OSError:
        w_txt = ""
    # Attribute column (get_convert_attr_ascii).
    a_txt = _ls_files_convert_attr_ascii(repo, path)
    return f"i/{i_txt:<5} w/{w_txt:<5} attr/{a_txt:<17}\t"


def _ls_files_convert_attr_ascii(repo: Repository, path: str) -> str:
    """Port of convert.c get_convert_attr_ascii (the attr column of --eol).

    Unlike crlf_action, attr_action reflects only the .gitattributes state — it
    does NOT apply the core.autocrlf fallback, nor resolve CRLF_TEXT to an
    eol-specific action (convert.c convert_attrs saves attr_action before those
    steps)."""
    try:
        from . import convert as _conv
        attrs = _conv._check_attrs(repo, path)

        def check_crlf(value):
            if value is True:
                return _conv.CRLF_TEXT
            if value is False:
                return _conv.CRLF_BINARY
            if value is None:
                return _conv.CRLF_UNDEFINED
            if value == "input":
                return _conv.CRLF_TEXT_INPUT
            if value == "auto":
                return _conv.CRLF_AUTO
            return _conv.CRLF_UNDEFINED

        action = check_crlf(attrs.get("text", None))
        if action == _conv.CRLF_UNDEFINED:
            action = check_crlf(attrs.get("crlf", None))
        if action != _conv.CRLF_BINARY:
            eol_val = attrs.get("eol", None)
            if action == _conv.CRLF_AUTO and eol_val == "lf":
                action = _conv.CRLF_AUTO_INPUT
            elif action == _conv.CRLF_AUTO and eol_val == "crlf":
                action = _conv.CRLF_AUTO_CRLF
            elif eol_val == "lf":
                action = _conv.CRLF_TEXT_INPUT
            elif eol_val == "crlf":
                action = _conv.CRLF_TEXT_CRLF
    except Exception:
        return ""
    return {
        _conv.CRLF_UNDEFINED: "",
        _conv.CRLF_BINARY: "-text",
        _conv.CRLF_TEXT: "text",
        _conv.CRLF_TEXT_INPUT: "text eol=lf",
        _conv.CRLF_TEXT_CRLF: "text eol=crlf",
        _conv.CRLF_AUTO: "text=auto",
        _conv.CRLF_AUTO_CRLF: "text=auto eol=crlf",
        _conv.CRLF_AUTO_INPUT: "text=auto eol=lf",
    }.get(action, "")


def _ls_files_format(repo: Repository, entry, fmt: str, abbrev: Optional[int],
                     display_path: Optional[str] = None) -> str:
    """Expand a `ls-files --format` string for one index entry."""
    import re
    sha = entry.sha[:abbrev] if abbrev is not None else entry.sha
    mode = entry.mode_str()
    otype = "commit" if mode == "160000" else "blob"
    if display_path is None:
        display_path = entry.path

    def _size() -> str:
        try:
            return str(len(objs.read_object(repo, entry.sha)[1]))
        except KeyError:
            return "-"

    def atom(name: str) -> str:
        if name == "objectmode":
            return mode
        if name == "objectname":
            return sha
        if name == "objecttype":
            return otype
        if name == "objectsize":
            return _size()
        if name == "stage":
            return str(getattr(entry, "stage", 0))
        if name == "path":
            return display_path
        if name in ("eolinfo:index", "eolinfo:worktree", "eolattr"):
            return ""
        return ""

    return re.sub(r"%\(([^)]*)\)", lambda m: atom(m.group(1)), fmt)


