def _hide_refs_patterns(repo, section: str) -> list[str]:
    """Ordered ``transfer.hideRefs`` / ``<section>.hideRefs`` patterns.

    Mirrors C Git's ``parse_hide_refs_config``: every matching config entry
    (across files, in declared order) is appended; trailing ``/`` is stripped.
    """
    from . import gitconfig

    keys = {"transfer.hiderefs", f"{section.lower()}.hiderefs"}
    pats: list[str] = []
    for full, value in gitconfig.list_all(repo):
        if full in keys:
            pats.append(value.rstrip("/"))
    return pats


def _ref_is_hidden(refname: str, patterns: list[str]) -> bool:
    """C Git's ``ref_is_hidden``: last matching pattern wins; ``!`` un-hides.

    Without ref namespaces, the stripped and full refname coincide, so a
    leading ``^`` (match full refname) behaves the same as no prefix.
    """
    for match in reversed(patterns):
        neg = False
        if match.startswith("!"):
            neg = True
            match = match[1:]
        if match.startswith("^"):
            match = match[1:]
        if refname == match or refname.startswith(match + "/"):
            return not neg
    return False


def _rev_list_emit_pretty(repo: Repository, sha: str, c, style: str, ab) -> None:
    """Render one commit for `rev-list --pretty=<style>` (builtin multiline
    styles). Mirrors `git log --pretty=<style>` for a single commit, but every
    entry is terminated with a trailing blank line (the rev-list convention)."""
    _print(f"commit {ab(sha)}")
    if style == "raw":
        _print(f"tree {c.tree}")
        for p in c.parents:
            _print(f"parent {p}")
        _print(f"author {c.author}")
        _print(f"committer {c.committer}")
    elif style == "short":
        if len(c.parents) > 1:
            _print("Merge: " + " ".join(p[:7] for p in c.parents))
        _print(f"Author: {_split_ident(c.author)[0]}")
    elif style == "full":
        if len(c.parents) > 1:
            _print("Merge: " + " ".join(p[:7] for p in c.parents))
        _print(f"Author: {_split_ident(c.author)[0]}")
        _print(f"Commit: {_split_ident(c.committer)[0]}")
    elif style == "fuller":
        if len(c.parents) > 1:
            _print("Merge: " + " ".join(p[:7] for p in c.parents))
        _print(f"Author:     {_split_ident(c.author)[0]}")
        _print(f"AuthorDate: {_format_date(c.author, 'default')}")
        _print(f"Commit:     {_split_ident(c.committer)[0]}")
        _print(f"CommitDate: {_format_date(c.committer, 'default')}")
    else:  # medium (and bare --pretty)
        if len(c.parents) > 1:
            _print("Merge: " + " ".join(p[:7] for p in c.parents))
        _print(f"Author: {_split_ident(c.author)[0]}")
        _print(f"Date:   {_format_date(c.author, 'default')}")
    _print("")
    if style == "short":
        first = c.message.splitlines()[0] if c.message.strip() else ""
        _print(f"    {first}")
    else:
        for line in c.message.rstrip("\n").splitlines():
            _print(f"    {line}")
    _print("")


def cmd_rev_list(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit rev-list", add_help=False)
    ap.add_argument("--count", action="store_true")
    ap.add_argument("--max-count", "-n", type=int, default=None)
    ap.add_argument("--all", action="store_true")
    ap.add_argument("--branches", nargs="?", const="*", default=None)
    ap.add_argument("--tags", nargs="?", const="*", default=None)
    ap.add_argument("--remotes", nargs="?", const="*", default=None)
    ap.add_argument("--reverse", action="store_true")
    ap.add_argument("--objects", action="store_true")
    ap.add_argument("--objects-edge", dest="objects_edge", action="store_true")
    ap.add_argument("--parents", action="store_true")
    ap.add_argument("--no-walk", nargs="?", const="sorted", default=None)
    ap.add_argument("--children", action="store_true")
    ap.add_argument("--first-parent", action="store_true")
    ap.add_argument("--topo-order", dest="topo_order", action="store_true")
    ap.add_argument("--date-order", dest="date_order", action="store_true")
    ap.add_argument("--header", action="store_true")
    ap.add_argument("--abbrev-commit", dest="abbrev_commit", action="store_true")
    ap.add_argument("--abbrev", type=int, default=None)
    ap.add_argument("-z", dest="z", action="store_true")
    ap.add_argument("--disk-usage", dest="disk_usage", nargs="?", const="", default=None)
    ap.add_argument("--bisect", action="store_true")
    ap.add_argument("--bisect-all", dest="bisect_all", action="store_true")
    ap.add_argument("--bisect-vars", dest="bisect_vars", action="store_true")
    ap.add_argument("--quiet", action="store_true")
    ap.add_argument("--no-abbrev", dest="no_abbrev", action="store_true")
    ap.add_argument("--max-age", dest="max_age", type=int, default=None)
    ap.add_argument("--min-age", dest="min_age", type=int, default=None)
    ap.add_argument("--unpacked", action="store_true")
    ap.add_argument("--remove-empty", dest="remove_empty", action="store_true")
    ap.add_argument("--pretty", nargs="?", const="medium", default=None)
    ap.add_argument("--format", default=None)
    ap.add_argument("--oneline", action="store_true")
    ap.add_argument("--since", "--after", dest="since", default=None)
    ap.add_argument("--until", "--before", dest="until", default=None)
    ap.add_argument("--merges", action="store_true")
    ap.add_argument("--no-merges", dest="no_merges", action="store_true")
    ap.add_argument("--min-parents", dest="min_parents", type=int, default=None)
    ap.add_argument("--max-parents", dest="max_parents", type=int, default=None)
    ap.add_argument("--no-min-parents", dest="no_min_parents", action="store_true")
    ap.add_argument("--no-max-parents", dest="no_max_parents", action="store_true")
    ap.add_argument("--grep", action="append", default=None)
    ap.add_argument("--author", action="append", default=None)
    ap.add_argument("--committer", action="append", default=None)
    ap.add_argument("--all-match", dest="all_match", action="store_true")
    ap.add_argument("-i", "--regexp-ignore-case", dest="ignore_case", action="store_true")
    ap.add_argument("--left-right", dest="left_right", action="store_true")
    ap.add_argument("--timestamp", action="store_true")
    ap.add_argument("--stdin", action="store_true")
    ap.add_argument("--exclude-hidden", dest="exclude_hidden", default=None)
    # --sparse/--dense toggle history simplification density (revs->dense).
    # dense (the default) prunes TREESAME single-parent commits during a
    # pathspec-limited walk; --sparse leaves every non-merge/root commit in
    # the output (C: try_to_simplify_commit early-returns for `!dense &&
    # !commit->parents->next`, so they never get the TREESAME flag, and
    # get_commit_action only prunes when `prune && dense`). Without a pathspec
    # neither flag has any effect.
    ap.add_argument("--sparse", dest="dense", action="store_false", default=True)
    ap.add_argument("--dense", dest="dense", action="store_true")
    ap.add_argument("revs", nargs="*")
    # Split a trailing "-- <pathspec>..." off before argparse consumes the "--".
    rl_paths: list[str] = []
    pre = _expand_count_shorthand(argv)
    if "--" in pre:
        i = pre.index("--")
        rl_paths = pre[i + 1:]
        pre = pre[:i]
    # `--exclude-hidden <section>` (separate token) is equivalent to the
    # attached `--exclude-hidden=<section>` form; fold it so the value is not
    # mistaken for a revision. A bare flag with no value is an error.
    _norm: list[str] = []
    _i = 0
    while _i < len(pre):
        t = pre[_i]
        if t == "--exclude-hidden":
            if _i + 1 >= len(pre):
                _err("fatal: Option '--exclude-hidden' requires a value")
                return 128
            _norm.append(f"--exclude-hidden={pre[_i + 1]}")
            _i += 2
            continue
        _norm.append(t)
        _i += 1
    pre = _norm
    # `--exclude-hidden=<section>` excludes refs hidden by transfer/<section>
    # hideRefs from the ref-namespace pseudo-opts. It is order-sensitive: C Git
    # errors when it precedes --branches/--tags/--remotes, but each namespace op
    # consumes (clears) the exclusion, so a preceding --all is fine. Walk the
    # cleaned argv left-to-right to reproduce that exactly.
    _apply_hidden_section: Optional[str] = None
    _hidden_configured = False
    _ns_clear = ("--all", "--branches", "--tags", "--remotes", "--glob")
    for tok in pre:
        head = tok.split("=", 1)[0]
        if head == "--exclude-hidden":
            section = tok.split("=", 1)[1] if "=" in tok else ""
            if section not in ("fetch", "receive", "uploadpack"):
                _err(f"fatal: unsupported section for hidden refs: {section}")
                return 128
            if _hidden_configured:
                _err("fatal: --exclude-hidden= passed more than once")
                return 128
            _hidden_configured = True
            _pending_section = section
        elif _hidden_configured and head in ("--branches", "--tags", "--remotes"):
            opt = head[2:]
            sys.stderr.write(
                f"error: options '--exclude-hidden' and '--{opt}' "
                "cannot be used together\n")
            sys.stderr.write(_REV_LIST_USAGE)
            return 129
        elif head in _ns_clear:
            # This namespace op consumes (and clears) the pending exclusion.
            if _hidden_configured:
                _apply_hidden_section = _pending_section
            _hidden_configured = False
    # argparse's nargs="?" greedily eats the following token, so a bare optional-
    # value flag like `--disk-usage HEAD` would swallow the revision. Rewrite the
    # bare forms to their attached "=<const>" so the next token stays a revision.
    _opt_const = {"--disk-usage": "", "--branches": "*", "--tags": "*",
                  "--remotes": "*", "--no-walk": "sorted", "--pretty": "medium"}
    pre = [f"{t}={_opt_const[t]}" if t in _opt_const else t for t in pre]
    args = ap.parse_args(pre)
    # Reject -z combined with the options C Git refuses (builtin/rev-list.c:
    # "-z option used with unsupported option"): --header, --timestamp,
    # --pretty/--format, --objects-edge, --left-right, --disk-usage, --bisect*.
    if args.z and (args.header or args.timestamp or args.pretty is not None
                   or args.format is not None or args.oneline
                   or args.objects_edge or args.left_right
                   or args.disk_usage is not None or args.bisect
                   or args.bisect_all or args.bisect_vars):
        _err("fatal: -z option used with unsupported option")
        return 128
    if args.parents and args.children:
        _err("fatal: options '--parents' and '--children' cannot be used together")
        return 128
    if args.no_min_parents:
        args.min_parents = None
    if args.no_max_parents:
        args.max_parents = None
    repo = _repo()
    graph = _graph_for_repo(repo)
    rev_args = args.revs
    starts: list[str] = []
    excludes: list[str] = []
    lr_left: set[str] = set()
    lr_right: set[str] = set()
    # Annotated-tag objects to emit in `--objects` mode, in pending order. Each
    # entry is (tag_sha, tag_header_name); only collected when traversing objects.
    pending_tags: list[tuple[str, str]] = []
    want_objects = bool(args.objects or args.objects_edge)

    def _collect_tags(name: str) -> None:
        if not want_objects:
            return
        obj = _rev_object_sha(repo, name)
        if obj is not None:
            pending_tags.extend(_tag_chain(repo, obj))

    def _rl_resolve(spec: str) -> Optional[str]:
        # Resolve a rev-ish to the commit rev-list should walk, peeling any
        # annotated tag (revision.c handle_commit). Endpoints/excludes are
        # always commits, so peeling is safe and matches C.
        sha = refs_mod.rev_parse(repo, spec)
        if sha is None:
            return None
        peeled = _peel_to_non_tag(repo, sha)
        return peeled if peeled is not None else sha

    # `--all`/`--branches`/`--tags`/`--remotes` seed tips from ref namespaces
    # (refname order, peeling annotated tags), with HEAD appended for --all.
    namespaces = []
    if args.all or args.branches is not None:
        namespaces.append(("refs/heads/", None if args.branches in (None, "*") else args.branches))
    if args.all or args.tags is not None:
        namespaces.append(("refs/tags/", None if args.tags in (None, "*") else args.tags))
    if args.all or args.remotes is not None:
        namespaces.append(("refs/remotes/", None if args.remotes in (None, "*") else args.remotes))
    have_ns = bool(namespaces)
    hide_patterns = (_hide_refs_patterns(repo, _apply_hidden_section)
                     if _apply_hidden_section is not None else [])
    if have_ns:
        import fnmatch
        for refname, _rsha in _enumerate_refs(repo):
            for pre_ns, pat in namespaces:
                if refname.startswith(pre_ns):
                    if pat and not fnmatch.fnmatch(refname[len(pre_ns):], pat):
                        continue
                    if hide_patterns and _ref_is_hidden(refname, hide_patterns):
                        continue
                    csha = refs_mod.rev_parse(repo, refname + "^{commit}")
                    if csha:
                        starts.append(csha)
                    if want_objects:
                        pending_tags.extend(_tag_chain(repo, _rev_object_sha(repo, refname) or ""))
                    break
        if args.all:
            _, head_sha = refs_mod.read_head(repo)
            if head_sha:
                starts.append(head_sha)

    def _reach(start: str) -> set:
        seen_r: set[str] = set()
        st = [start]
        while st:
            x = st.pop()
            if x in seen_r:
                continue
            seen_r.add(x)
            info = _commit_tree_parents(repo, x)
            if info:
                st.extend(info[1])
        return seen_r

    # --stdin: each input line is a revision argument (or, after a "--" line,
    # a pathspec). Lines starting with "-" are pseudo-options; an unrecognized
    # one is fatal, mirroring C Git's read_revisions_from_stdin. A revision that
    # does not resolve is fatal here (unlike command-line args, which are lenient
    # for back-compat). "--not" sticky-flips the include/exclude sense.
    if pre.count("--stdin") > 1:
        _err("fatal: --stdin given twice?")
        return 128
    if args.stdin:
        not_flag = False
        seen_eoo = False
        seen_dd = False
        _stdin_data = sys.stdin.read()
        _stdin_lines = _stdin_data.split("\n")
        # A trailing newline yields a final empty element that is not a record.
        if _stdin_lines and _stdin_lines[-1] == "":
            _stdin_lines.pop()
        _li = 0
        while _li < len(_stdin_lines):
            raw = _stdin_lines[_li]
            _li += 1
            if raw == "":
                break
            line = raw
            if line == "--":
                seen_dd = True
                break
            if not seen_eoo and line.startswith("-"):
                if line == "--end-of-options":
                    seen_eoo = True
                    continue
                if line == "--not":
                    not_flag = True
                    continue
                if line == "--all":
                    for refname, _rs in _enumerate_refs(repo):
                        if (refname.startswith("refs/heads/")
                                or refname.startswith("refs/tags/")
                                or refname.startswith("refs/remotes/")):
                            csha = refs_mod.rev_parse(repo, refname + "^{commit}")
                            if csha:
                                (excludes if not_flag else starts).append(csha)
                    _, hsha = refs_mod.read_head(repo)
                    if hsha:
                        (excludes if not_flag else starts).append(hsha)
                    continue
                if line in ("--branches", "--tags", "--remotes"):
                    ns = {"--branches": "refs/heads/", "--tags": "refs/tags/",
                          "--remotes": "refs/remotes/"}[line]
                    for refname, _rs in _enumerate_refs(repo):
                        if refname.startswith(ns):
                            csha = refs_mod.rev_parse(repo, refname + "^{commit}")
                            if csha:
                                (excludes if not_flag else starts).append(csha)
                    continue
                _err(f"fatal: invalid option '{line}' in --stdin mode")
                return 128
            tok = line
            neg = not_flag
            if tok.startswith("^"):
                tok = tok[1:]
                neg = not neg
            if "..." in tok:
                a, _, b = tok.partition("...")
                a_sha = _rl_resolve(a or "HEAD")
                b_sha = _rl_resolve(b or "HEAD")
                from . import merge as _m
                if a_sha:
                    _collect_tags(a or "HEAD")
                    starts.append(a_sha)
                    lr_left |= _reach(a_sha)
                if b_sha:
                    _collect_tags(b or "HEAD")
                    starts.append(b_sha)
                    lr_right |= _reach(b_sha)
                if a_sha and b_sha:
                    excludes.extend(_m.merge_bases(repo, a_sha, b_sha))
                continue
            if ".." in tok:
                lo, _, hi = tok.partition("..")
                hi_sha = _rl_resolve(hi or "HEAD")
                lo_sha = _rl_resolve(lo) if lo else None
                if hi_sha:
                    _collect_tags(hi or "HEAD")
                    starts.append(hi_sha)
                if lo_sha:
                    excludes.append(lo_sha)
                continue
            sha = _rl_resolve(tok)
            if not sha:
                _err(f"fatal: bad revision '{line}'")
                return 128
            if not neg:
                _collect_tags(tok)
            (excludes if neg else starts).append(sha)
        if seen_dd:
            while _li < len(_stdin_lines):
                rl_paths.append(_stdin_lines[_li])
                _li += 1

    for r in rev_args:
        if r.startswith("^"):
            sha = _rl_resolve(r[1:])
            if sha:
                excludes.append(sha)
            continue
        if "..." in r:
            # Symmetric difference: A...B = A B --not $(merge-base A B).
            a, _, b = r.partition("...")
            a_sha = _rl_resolve(a or "HEAD")
            b_sha = _rl_resolve(b or "HEAD")
            from . import merge as _m
            if a_sha:
                _collect_tags(a or "HEAD")
                starts.append(a_sha)
                lr_left |= _reach(a_sha)
            if b_sha:
                _collect_tags(b or "HEAD")
                starts.append(b_sha)
                lr_right |= _reach(b_sha)
            if a_sha and b_sha:
                excludes.extend(_m.merge_bases(repo, a_sha, b_sha))
            continue
        if ".." in r:
            lo, _, hi = r.partition("..")
            hi_sha = _rl_resolve(hi or "HEAD")
            lo_sha = _rl_resolve(lo) if lo else None
            if hi_sha:
                _collect_tags(hi or "HEAD")
                starts.append(hi_sha)
            if lo_sha:
                excludes.append(lo_sha)
            continue
        sha = _rl_resolve(r)
        if sha:
            _collect_tags(r)
            starts.append(sha)
    if not starts and not have_ns and not args.stdin:
        # No commits to walk and no rev input. C Git prints the full usage
        # (rc 129) when no revision input was given at all; --stdin (even if it
        # produced nothing) suppresses the error and yields empty output.
        if not rev_args:
            sys.stderr.write(_REV_LIST_USAGE)
            return 129
        _err("usage: git rev-list [<options>] <commit>... [--] [<path>...]")
        return 128

    excluded: set[str] = set()
    estack = deque(excludes)
    while estack:
        sha = estack.popleft()
        if sha in excluded:
            continue
        excluded.add(sha)
        info = _commit_tree_parents(repo, sha)
        if info:
            estack.extend(info[1])

    if (args.count and args.max_count is None and starts and not excludes
            and not have_ns and not args.disk_usage and not args.bisect
            and not args.bisect_all):
        try:
            from . import pack as _p

            bitmapped = _p.reachable_from_bitmaps(repo, starts, object_type="commit")
            if bitmapped is not None:
                _print(str(len(bitmapped)))
                return 0
        except Exception:
            pass

    # Default traversal is a committer-date max-heap (C Git's date-ordered
    # commit_list): pop the most recent commit, emit it, push its parents.
    want_topo = args.topo_order and not args.date_order
    want_date = args.date_order
    has_filter = bool(rl_paths or args.since or args.until or args.merges
                      or args.no_merges or args.min_parents is not None
                      or args.max_parents is not None or args.grep or args.author
                      or args.committer or args.max_age is not None
                      or args.min_age is not None)
    need_full = (has_filter or want_topo or want_date or args.reverse or args.count
                 or args.bisect or args.bisect_all or args.bisect_vars
                 or args.disk_usage is not None or args.children)
    import heapq
    heap: list[tuple] = []
    counter = 0
    pushed: set[str] = set()

    def _push(s: str) -> None:
        nonlocal counter
        if s in pushed:
            return
        pushed.add(s)
        heapq.heappush(heap, (-_commit_date(repo, s), counter, s))
        counter += 1

    for s in starts:
        _push(s)
    out: list[str] = []
    emitted: set[str] = set()
    edges: list[str] = []
    edge_seen: set[str] = set()
    while heap:
        _d, _c, sha = heapq.heappop(heap)
        if sha in emitted:
            continue
        emitted.add(sha)
        if sha in excluded:
            continue
        info = _commit_tree_parents(repo, sha, graph)
        if info is None:
            continue
        out.append(sha)
        if args.no_walk is None:
            for p in (info[1][:1] if args.first_parent else info[1]):
                if p in excluded:
                    if p not in edge_seen:
                        edge_seen.add(p)
                        edges.append(p)
                _push(p)
        if args.max_count and len(out) >= args.max_count and not need_full:
            break
    if args.no_walk is not None and args.no_walk == "unsorted":
        # Preserve command-line / seed order rather than date order.
        order = {s: i for i, s in enumerate(starts)}
        out.sort(key=lambda s: order.get(s, len(order)))

    if rl_paths:
        def _touches(s: str) -> bool:
            info = _commit_tree_parents(repo, s, graph)
            if info is None:
                return False
            tree, parents = info
            ptree = _commit_tree_parents(repo, parents[0], graph)[0] if parents else None
            for path in rl_paths:
                before = workdir.tree_path_entry(repo, ptree, path) if ptree else None
                after = workdir.tree_path_entry(repo, tree, path)
                if (before.sha if before else None) != (after.sha if after else None):
                    return True
            return False

        if args.dense:
            out = [s for s in out if _touches(s)]
        else:
            # --sparse: TREESAME pruning is disabled for single-parent and root
            # commits, so they are always shown (revision.c try_to_simplify_commit
            # early-returns for `!dense && !commit->parents->next`, leaving the
            # TREESAME flag unset; get_commit_action only drops a commit when
            # `prune && dense`). Merge commits still follow the change test.
            def _keep_sparse(s: str) -> bool:
                info = _commit_tree_parents(repo, s, graph)
                if info is None:
                    return False
                if len(info[1]) <= 1:
                    return True
                return _touches(s)
            out = [s for s in out if _keep_sparse(s)]
    out = _filter_commits(repo, out, args)
    if args.unpacked:
        out = [s for s in out if objs._loose_path(repo, s).exists()]
    if want_topo:
        out = _topo_order(repo, out, args.first_parent, by_date=False)
    elif want_date:
        out = _topo_order(repo, out, args.first_parent, by_date=True)
    if args.max_count is not None:
        out = out[:max(0, args.max_count)]

    # Output helpers: abbreviation and record terminator (-z → NUL). --oneline
    # implies --abbrev-commit. Only a commit's own id is abbreviated; parent and
    # child ids in --parents/--children output stay full.
    abbrev_len = None
    if args.abbrev_commit or args.oneline:
        abbrev_len = max(4, args.abbrev) if args.abbrev is not None else 7
    if args.no_abbrev:
        abbrev_len = None

    def _ab(s: str) -> str:
        return s[:abbrev_len] if abbrev_len else s

    term = "\0" if args.z else "\n"

    # --quiet suppresses all object output (rc only).
    if args.quiet:
        return 0

    # --bisect / --bisect-all / --bisect-vars: weigh each suspect by how many
    # suspects it reaches and report the commit closest to halving the set.
    if args.bisect or args.bisect_all or args.bisect_vars:
        sset = set(out)
        total = len(sset)

        def _weight(x: str) -> int:
            cnt = 0
            st = [x]
            seen_w: set[str] = set()
            while st:
                y = st.pop()
                if y in seen_w or y not in sset:
                    continue
                seen_w.add(y)
                cnt += 1
                info = _commit_tree_parents(repo, y, graph)
                if info:
                    st.extend(info[1])
            return cnt

        weights = {s: _weight(s) for s in out}
        if args.bisect_all:
            # --bisect-all: C Git's compare_commit_dist (distance descending,
            # ties by oid ascending) over the whole suspect set.
            decos = _commit_decorations(repo)
            ranked = sorted(out, key=lambda s: (-min(weights[s], total - weights[s]), s))
            for s in ranked:
                dist = min(weights[s], total - weights[s])
                parts = list(decos.get(s, [])) + [f"dist={dist}"]
                sys.stdout.write(f"{_ab(s)} ({', '.join(parts)})" + term)
            return 0
        # Single --bisect / --bisect-vars: C Git's best_bisection (bisect.c)
        # reverses the walk to oldest-first, then keeps the first commit with a
        # strictly-greater folded distance.
        best = None
        best_distance = -1
        for s in reversed(out):
            distance = min(weights[s], total - weights[s])
            if distance > best_distance:
                best = s
                best_distance = distance
        if best is None:
            return 0
        if args.bisect_vars:
            reaches = weights[best]
            _print(f"bisect_rev='{best}'")
            _print(f"bisect_nr={max(reaches, total - reaches) - 1}")
            _print(f"bisect_good={total - reaches - 1}")
            _print(f"bisect_bad={reaches - 1}")
            _print(f"bisect_all={total}")
            _print(f"bisect_steps={_estimate_bisect_steps(total)}")
        else:
            sys.stdout.write(_ab(best) + term)
        return 0

    # --disk-usage: sum the on-disk byte size of every object that would be shown.
    if args.disk_usage is not None:
        total_bytes = 0
        seen_du: set[str] = set()
        if args.objects or args.objects_edge:
            seen_du = _reachable_tree_objects(repo, excluded, graph)
        for s in out:
            if s not in seen_du:
                seen_du.add(s)
                total_bytes += _object_disk_size(repo, s)
            if args.objects or args.objects_edge:
                info = _commit_tree_parents(repo, s, graph)
                if info:
                    for osha, _p in _walk_objects(repo, info[0], ""):
                        if osha not in seen_du:
                            seen_du.add(osha)
                            total_bytes += _object_disk_size(repo, osha)
        _print(_humanise_bytes(total_bytes) if args.disk_usage == "human" else str(total_bytes))
        return 0

    # --header: raw commit record (oid, raw headers, indented message), NUL-sep.
    if args.header:
        buf = sys.stdout.buffer
        for s in out:
            raw = objs.read_object(repo, s)[1]
            hdr, _, msg = raw.partition(b"\n\n")
            lines = msg.split(b"\n")
            if lines and lines[-1] == b"":
                lines = lines[:-1]
            indented = b"".join(b"    " + ln + b"\n" for ln in lines)
            buf.write(s.encode() + b"\n" + hdr + b"\n\n" + indented + b"\0")
        buf.flush()
        return 0

    if args.pretty is not None or args.format is not None or args.oneline:
        fmt = args.format
        if fmt is None and args.pretty and (args.pretty.startswith("format:")
                                            or args.pretty.startswith("tformat:")):
            fmt = args.pretty.split(":", 1)[1]
        elif fmt is None and args.pretty and "%" in args.pretty:
            fmt = args.pretty
        is_oneline = args.oneline or args.pretty == "oneline"
        # The bare/builtin multiline styles (medium is the default with a bare
        # --pretty). Each is rendered like `git log --pretty=<style>` for one
        # commit but rev-list terminates every entry with a trailing blank line
        # rather than separating entries with a leading blank.
        style = args.pretty if args.pretty in (
            "medium", "full", "fuller", "short", "raw") else "medium"
        if args.reverse:
            out = list(reversed(out))
        for s in out:
            c = objs.parse_commit(objs.read_object(repo, s)[1])
            if is_oneline and fmt is None:
                first = c.message.splitlines()[0] if c.message.strip() else ""
                _print(f"{_ab(s)} {first}")
            elif fmt is not None:
                # rev-list prefixes a "commit <oid>" line before the format.
                _print(f"commit {_ab(s)}")
                _print(_expand_commit_format(repo, s, c, fmt, {}))
            else:
                _rev_list_emit_pretty(repo, s, c, style, _ab)
        return 0
    if args.count:
        # --count with --left-right prints the two sides tab-separated
        # (builtin/rev-list.c): count_left = commits flagged SYMMETRIC_LEFT.
        if args.left_right:
            left = sum(1 for s in out if s in lr_left)
            right = len(out) - left
            _print(f"{left}\t{right}")
        else:
            _print(str(len(out)))
    elif args.objects or args.objects_edge:
        out_buf = sys.stdout.buffer

        def wz(line: str) -> None:
            out_buf.write(line.encode("utf-8", "surrogateescape"))
            out_buf.write(term.encode("latin-1"))

        # Boundary (uninteresting) commits, prefixed with '-', precede the rest.
        if args.objects_edge:
            for e in edges:
                wz(f"-{_ab(e)}")
        if args.reverse:
            out = list(reversed(out))
        for s in out:
            wz(_ab(s))
        # Objects reachable from the uninteresting (excluded) commits are
        # already in the receiver, so C Git omits them from the listing. With
        # -z each named object is "<oid>\0path=<name>\0" (a separate record for
        # the path); the bare non-z layout is "<oid> <name>" on one line.
        seen_obj = _reachable_tree_objects(repo, excluded, graph)

        def emit_named(osha: str, name: str) -> None:
            if args.z:
                out_buf.write(_ab(osha).encode("ascii"))
                out_buf.write(b"\0")
                if name:
                    out_buf.write(b"path=")
                    out_buf.write(name.encode("utf-8", "surrogateescape"))
                    out_buf.write(b"\0")
            else:
                wz(f"{_ab(osha)} {name}")

        # Annotated tag objects (revision.c handle_commit) are emitted after the
        # commit list and before trees/blobs, in pending order, each named by its
        # own `tag` header. Tags reachable only from excluded tips are skipped.
        for tsha, tname in pending_tags:
            if tsha in seen_obj or tsha in excluded:
                continue
            seen_obj.add(tsha)
            emit_named(tsha, tname)
        for s in out:
            info = _commit_tree_parents(repo, s, graph)
            if info is None:
                continue
            for osha, opath in _walk_objects(repo, info[0], ""):
                if osha in seen_obj:
                    continue
                seen_obj.add(osha)
                if args.z:
                    out_buf.write(osha.encode("ascii"))
                    out_buf.write(b"\0")
                    if opath:
                        out_buf.write(b"path=")
                        out_buf.write(opath.encode("utf-8", "surrogateescape"))
                        out_buf.write(b"\0")
                else:
                    wz(f"{osha} {opath}")
        out_buf.flush()
    else:
        if args.reverse:
            out = list(reversed(out))
        # --children: map each commit to the in-set commits that name it parent.
        children_map: dict[str, list[str]] = {}
        if args.children:
            for s in out:
                info = _commit_tree_parents(repo, s, graph)
                if info:
                    # C Git prepends each child to its parent's list, so the
                    # last commit processed appears first.
                    for p in info[1]:
                        children_map.setdefault(p, []).insert(0, s)
        for s in out:
            mark = ""
            if args.left_right:
                mark = "<" if s in lr_left else (">" if s in lr_right else "")
            ts_prefix = ""
            if args.timestamp:
                ts_prefix = f"{_commit_date(repo, s)} "
            extra = ""
            if args.parents:
                info = _commit_tree_parents(repo, s, graph)
                if info and info[1]:
                    extra += " " + " ".join(info[1])
            if args.children:
                kids = children_map.get(s, [])
                if kids:
                    extra += " " + " ".join(kids)
            sys.stdout.write(f"{ts_prefix}{mark}{_ab(s)}{extra}" + term)
    return 0


def _reachable_tree_objects(repo: Repository, commits, graph=None) -> set[str]:
    """Set of tree/blob object ids reachable from the given commits' trees.

    Used to subtract objects already implied by uninteresting commits from
    `rev-list --objects` / `--objects-edge` / `--disk-usage --objects`."""
    seen: set[str] = set()
    for c in commits:
        info = _commit_tree_parents(repo, c, graph)
        if info is None:
            continue
        for osha, _p in _walk_objects(repo, info[0], ""):
            seen.add(osha)
    return seen


def _walk_objects(repo: Repository, tree_sha: str, prefix: str):
    yield (tree_sha, prefix.rstrip("/"))
    try:
        _, data = objs.read_object(repo, tree_sha)
    except KeyError:
        return
    for e in objs.parse_tree(data, repo.hash_len):
        path = prefix + e.name
        if e.is_dir():
            yield from _walk_objects(repo, e.sha, path + "/")
        elif not e.is_gitlink():
            yield (e.sha, path)


# ---------------------------------------------------------------------------
# porcelain


def _pathspec_matches(repo: Repository, pathspec: str, tracked: set[str]) -> bool:
    full = repo.path / pathspec
    if full.exists() or full.is_symlink():
        return True
    norm = pathspec.rstrip("/")
    if norm in (".", ""):
        return True
    return any(t == norm or t.startswith(norm + "/") for t in tracked)


def _add_interactive(repo: Repository, args, *, patch: bool) -> int:
    """Dispatch `git add -p` / `git add -i` to the shared add-patch engine."""
    from . import addpatch
    pathspec = list(args.paths)
    if patch:
        rc = addpatch.run_add_p(
            repo, "add", None, pathspec,
            context=args.unified, interhunkcontext=args.interhunkcontext,
            auto_advance=args.auto_advance)
        return 1 if rc else 0
    rc = addpatch.run_add_i(
        repo, pathspec,
        context=args.unified, interhunkcontext=args.interhunkcontext,
        auto_advance=args.auto_advance)
    return 1 if rc else 0


def _commit_interactive(repo: Repository, args) -> Optional[int]:
    """Stage interactively-selected changes for `git commit -p/--interactive`.

    Returns None to let the normal commit proceed from the updated index, or an
    rc to abort (mirrors die("interactive add failed"))."""
    from . import addpatch
    pathspec = list(args.pathspec)
    if args.patch:
        rc = addpatch.run_add_p(
            repo, "add", None, pathspec,
            context=args.unified, interhunkcontext=args.interhunkcontext,
            auto_advance=args.auto_advance)
    else:
        rc = addpatch.run_add_i(
            repo, pathspec,
            context=args.unified, interhunkcontext=args.interhunkcontext,
            auto_advance=args.auto_advance)
    if rc:
        _err("fatal: interactive add failed")
        return 128
    return None


def _add_edit_patch(repo: Repository, paths: list[str]) -> int:
    """Port of builtin/add.c edit_patch(): diff -U7, edit, apply --recount --cached."""
    from . import addpatch
    # Generate the worktree-vs-index diff with 7 lines of context.
    buf = addpatch._run_capture(cmd_diff_files, ["-U7", "-p", "--"] + list(paths))
    path = repo.gitdir / "ADD_EDIT.patch"
    # git names the file via repo_git_path() -> "$GIT_DIR/ADD_EDIT.patch"; from
    # the worktree root that displays as the relative ".git/ADD_EDIT.patch".
    try:
        disp = os.path.relpath(str(path), os.getcwd())
    except ValueError:
        disp = str(path)
    path.write_text(buf, encoding="utf-8")
    import subprocess
    editor = addpatch._editor_command(repo)
    try:
        rc = subprocess.call("%s %s" % (editor, addpatch._shell_quote(str(path))),
                             shell=True)
    except OSError:
        _err("fatal: editing patch failed")
        return 128
    if rc != 0:
        _err("fatal: editing patch failed")
        return 128
    try:
        data = path.read_bytes()
    except OSError:
        _err(f"fatal: could not stat '{disp}'")
        return 128
    if not data:
        _err("fatal: empty patch. aborted")
        return 128
    rc = addpatch._run_apply(repo, data.decode("utf-8", "surrogateescape"),
                             ["--recount", "--cached"])
    if rc != 0:
        _err(f"fatal: could not apply '{disp}'")
        return 128
    try:
        path.unlink()
    except OSError:
        pass
    return 0


def cmd_add(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit add", add_help=False)
    ap.add_argument("-A", "--all", action="store_true")
    ap.add_argument("-n", "--dry-run", dest="dry_run", action="store_true")
    ap.add_argument("-v", "--verbose", action="store_true")
    ap.add_argument("-f", "--force", action="store_true")
    ap.add_argument("-u", "--update", action="store_true")
    ap.add_argument("-N", "--intent-to-add", dest="intent_to_add", action="store_true")
    ap.add_argument("-p", "--patch", dest="patch", action="store_true")
    ap.add_argument("-i", "--interactive", dest="interactive", action="store_true")
    ap.add_argument("-e", "--edit", dest="edit", action="store_true")
    ap.add_argument("-U", "--unified", dest="unified", type=int, default=-1)
    ap.add_argument("--inter-hunk-context", dest="interhunkcontext", type=int, default=-1)
    ap.add_argument("--auto-advance", dest="auto_advance", action="store_true", default=True)
    ap.add_argument("--no-auto-advance", dest="auto_advance", action="store_false")
    ap.add_argument("--no-all", "--ignore-removal", dest="no_all", action="store_true")
    ap.add_argument("--pathspec-from-file", dest="pathspec_from_file", default=None)
    ap.add_argument("--pathspec-file-nul", dest="pathspec_file_nul", action="store_true")
    ap.add_argument("paths", nargs="*")
    args = ap.parse_args(argv)
    repo = _repo()

    # Interactive / patch machinery (builtin/add.c cmd_add ordering).
    if args.unified < -1:
        _err("fatal: '--unified' cannot be negative")
        return 128
    if args.interhunkcontext < -1:
        _err("fatal: '--inter-hunk-context' cannot be negative")
        return 128
    if args.patch:
        args.interactive = True
    if args.interactive:
        if args.dry_run:
            _err("fatal: options '--dry-run' and '--interactive/--patch' cannot be used together")
            return 128
        if args.pathspec_from_file is not None:
            _err("fatal: options '--pathspec-from-file' and '--interactive/--patch' cannot be used together")
            return 128
        return _add_interactive(repo, args, patch=args.patch)
    else:
        if args.unified != -1:
            _err("fatal: the option '--unified' requires '--interactive/--patch'")
            return 128
        if args.interhunkcontext != -1:
            _err("fatal: the option '--inter-hunk-context' requires '--interactive/--patch'")
            return 128
        if not args.auto_advance:
            _err("fatal: the option '--no-auto-advance' requires '--interactive/--patch'")
            return 128
    if args.edit:
        if args.pathspec_from_file is not None:
            _err("fatal: options '--pathspec-from-file' and '--edit' cannot be used together")
            return 128
        return _add_edit_patch(repo, args.paths)
    # --pathspec-from-file supplies the pathspecs instead of the command line.
    if args.pathspec_from_file is not None:
        raw = (sys.stdin.buffer.read() if args.pathspec_from_file == "-"
               else open(args.pathspec_from_file, "rb").read())
        sep = "\0" if args.pathspec_file_nul else "\n"
        args.paths = [p for p in raw.decode("utf-8").split(sep) if p]
    explicit = bool(args.paths) and not args.all
    targets = args.paths if (args.paths) else ["."]
    if explicit:
        tracked = workdir.tracked_paths(repo)
        for ps in targets:
            if not _pathspec_matches(repo, ps, tracked):
                _err(f"fatal: pathspec '{ps}' did not match any files")
                return 128
    # Explicitly-named ignored paths trigger the addIgnoredFile advice
    # (builtin/add.c add_files) unless -f. They are also excluded from staging.
    exit_status = 0
    ignored_named: list[str] = []
    if explicit and not args.force and not args.intent_to_add:
        ignored_named = workdir.explicit_ignored(repo, targets)
    report = None
    if args.dry_run or args.verbose:
        report = workdir.would_add_report(
            repo, targets, ignore_removal=args.no_all, update_only=args.update,
            force=args.force)
        if args.dry_run:
            for label, rel in report:
                _print(f"{label} '{rel}'")
            _add_emit_ignored(ignored_named)
            return 1 if ignored_named else 0
    workdir.add_paths(repo, targets, ignore_removal=args.no_all, update_only=args.update,
                      intent_to_add=args.intent_to_add, force=args.force)
    if args.verbose and report is not None:
        for label, rel in report:
            _print(f"{label} '{rel}'")
    _add_emit_ignored(ignored_named)
    return 1 if ignored_named else 0


def _add_emit_ignored(ignored_named: list[str]) -> None:
    if not ignored_named:
        return
    _err("The following paths are ignored by one of your .gitignore files:")
    for name in ignored_named:
        _err(name)
    _err("hint: Use -f if you really want to add them.")
    _err('hint: Disable this message with "git config set advice.addIgnoredFile false"')


def _rm_check_local_mod(repo: Repository, names: list[str], *, index_only: bool) -> int:
    """Port of builtin/rm.c check_local_mod. Returns 1 if removal is unsafe
    (and prints the matching error blocks), 0 otherwise."""
    import stat as _stat
    idx = read_index(repo)
    by_path = idx.by_path()
    head_sha = refs_mod.rev_parse(repo, "HEAD")
    no_head = head_sha is None
    head_map = _tree_map_full(repo, _commit_tree(repo, head_sha)) if head_sha else {}
    want = set(names)
    files_staged: list[str] = []
    files_cached: list[str] = []
    files_local: list[str] = []
    # Iterate in cache (index) order, like git's `list`.
    for name, ce in by_path.items():
        if name not in want:
            continue
        full = repo.path / name
        try:
            st = os.lstat(full)
        except OSError:
            # already vanished from the working tree
            continue
        if _stat.S_ISDIR(st.st_mode):
            # not a gitlink -> treated as ENOENT
            continue
        local_changes = False
        staged_changes = False
        # Is the index different from the file in the work tree?
        try:
            data = workdir._blob_data(full)
            wt_sha, _ = objs.hash_bytes("blob", data, repo)
            wt_mode = workdir._mode_for(full)
        except OSError:
            wt_sha, wt_mode = None, None
        if wt_sha is None or wt_sha != ce.sha or wt_mode != ce.mode:
            local_changes = True
        # Is the index different from the HEAD commit?
        if no_head or name not in head_map:
            staged_changes = True
        else:
            h_mode, h_sha = head_map[name]
            if int(h_mode, 8) != ce.mode or h_sha != ce.sha:
                staged_changes = True
        if local_changes and staged_changes:
            if not index_only or not ce.intent_to_add:
                files_staged.append(name)
        elif not index_only:
            if staged_changes:
                files_cached.append(name)
            if local_changes:
                files_local.append(name)
    errs = 0

    def _emit(lst: list[str], main_msg: str, hint: str) -> None:
        nonlocal errs
        if lst:
            msg = main_msg
            for n in lst:
                msg += f"\n    {n}"
            msg += hint
            _err(f"error: {msg}")
            errs = 1

    _emit(files_staged,
          "the following file has staged content different from both the\nfile and the HEAD:"
          if len(files_staged) == 1 else
          "the following files have staged content different from both the\nfile and the HEAD:",
          "\n(use -f to force removal)")
    _emit(files_cached,
          "the following file has changes staged in the index:"
          if len(files_cached) == 1 else
          "the following files have changes staged in the index:",
          "\n(use --cached to keep the file, or -f to force removal)")
    _emit(files_local,
          "the following file has local modifications:"
          if len(files_local) == 1 else
          "the following files have local modifications:",
          "\n(use --cached to keep the file, or -f to force removal)")
    return errs


def cmd_rm(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit rm", add_help=False)
    ap.add_argument("--cached", action="store_true")
    ap.add_argument("-f", "--force", action="store_true")
    ap.add_argument("-r", dest="recursive", action="store_true")
    ap.add_argument("-n", "--dry-run", dest="dry_run", action="store_true")
    ap.add_argument("paths", nargs="+")
    args = ap.parse_args(argv)
    repo = _repo()
    tracked = workdir.tracked_paths(repo)
    for ps in args.paths:
        norm = ps.rstrip("/")
        if not (norm in tracked or any(t.startswith(norm + "/") for t in tracked)):
            _err(f"fatal: pathspec '{ps}' did not match any files")
            return 128
    # Expand directory pathspecs to the tracked files they contain.
    expanded: list[str] = []
    for ps in args.paths:
        norm = ps.rstrip("/")
        if norm in tracked:
            expanded.append(norm)
        else:
            under = sorted(t for t in tracked if t.startswith(norm + "/"))
            if under and not args.recursive:
                _err(f"fatal: not removing '{ps}' recursively without -r")
                return 1
            expanded.extend(under)
    # Up-to-date safety check (builtin/rm.c check_local_mod). Unless -f, the
    # file, the index and HEAD must match; --cached is safe if the index
    # matches either the worktree or HEAD.
    if not args.force:
        rc = _rm_check_local_mod(repo, expanded, index_only=args.cached)
        if rc:
            return 1
    if args.dry_run:
        for rel in expanded:
            _print(f"rm '{rel}'")
        return 0
    removed = workdir.rm_paths(repo, expanded, cached=args.cached)
    for rel in removed:
        _print(f"rm '{rel}'")
    return 0


def cmd_mv(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit mv", add_help=False)
    ap.add_argument("-n", "--dry-run", dest="dry_run", action="store_true")
    ap.add_argument("-v", "--verbose", action="store_true")
    ap.add_argument("-f", "--force", action="store_true")
    ap.add_argument("-k", dest="skip", action="store_true")
    ap.add_argument("args", nargs="+")
    args = ap.parse_args(argv)
    repo = _repo()
    if len(args.args) < 2:
        _err("fatal: bad source")
        return 1
    sources = [a.rstrip("/") for a in args.args[:-1]]
    dest_arg = args.args[-1]

    idx = read_index(repo)
    in_index = set(idx.by_path())

    def _isdir(rel: str) -> bool:
        return (repo.path / rel).is_dir()

    # Determine destinations (builtin/mv.c: a directory destination maps each
    # source to <dest>/<basename(source)>; otherwise it is a 1:1 rename).
    dest_norm = dest_arg.rstrip("/")
    dest_is_dir = (repo.path / dest_norm).is_dir() if dest_norm else False
    if dest_is_dir:
        destinations = [f"{dest_norm}/{os.path.basename(s)}" for s in sources]
    else:
        if len(sources) != 1:
            _err(f"fatal: destination '{dest_arg}' is not a directory")
            return 128
        destinations = [dest_arg.rstrip("/") if dest_arg.endswith("/") else dest_arg]

    # Checking phase (builtin/mv.c): collect a fatal "bad" reason per pair. With
    # -k (ignore_errors) a bad pair is silently dropped ("remove_entry") and the
    # remaining valid pairs still move; without -k the first bad pair dies.
    class _BadPair(Exception):
        def __init__(self, reason: str, src: str, dst: str) -> None:
            self.reason, self.src, self.dst = reason, src, dst

    def _bad(reason: str, src: str, dst: str) -> int:
        raise _BadPair(reason, src, dst)

    plan: list[tuple[str, str]] = []
    seen_dst: set[str] = set()
    for src, dst in zip(sources, destinations):
        pair_plan: list[tuple[str, str]] = []
        try:
            full_src = repo.path / src
            if args.dry_run:
                _print(f"Checking rename of '{src}' to '{dst}'")
            if not (full_src.exists() or full_src.is_symlink()):
                # lstat(src) < 0 and not in index -> bad source
                _bad("bad source", src, dst)
            # can not move directory into itself
            if dst == src or dst.startswith(src + "/"):
                _bad("can not move directory into itself", src, dst)
            if full_src.is_dir() and not full_src.is_symlink():
                full_dst = repo.path / dst
                if full_dst.exists() or full_dst.is_symlink():
                    _bad("destination already exists", src, dst)
                under = sorted(t for t in in_index if t.startswith(src + "/"))
                if not under:
                    _bad("source directory is empty", src, dst)
                for t in under:
                    pair_plan.append((t, dst + "/" + t[len(src) + 1:]))
                plan.extend(pair_plan)
                continue
            if src not in in_index:
                _bad("not under version control", src, dst)
            full_dst = repo.path / dst
            if full_dst.exists() or full_dst.is_symlink():
                if args.force:
                    import stat as _stat
                    st = os.lstat(full_dst)
                    if _stat.S_ISREG(st.st_mode) or _stat.S_ISLNK(st.st_mode):
                        if args.verbose:
                            _err(f"warning: overwriting '{dst}'")
                    else:
                        _bad("Cannot overwrite", src, dst)
                else:
                    _bad("destination exists", src, dst)
            if dst in seen_dst:
                _bad("multiple sources for the same target", src, dst)
            if dst.endswith("/"):
                _bad("destination directory does not exist", src, dst)
            seen_dst.add(dst)
            plan.append((src, dst))
        except _BadPair as bp:
            if not args.skip:
                _err(f"fatal: {bp.reason}, source={bp.src}, destination={bp.dst}")
                return 128
            # ignore_errors: drop this pair and keep going.
            continue

    for src, dst in plan:
        if args.dry_run or args.verbose:
            _print(f"Renaming {src} to {dst}")
    if args.dry_run:
        return 0

    for src, dst in plan:
        full_src = repo.path / src
        full_dst = repo.path / dst
        full_dst.parent.mkdir(parents=True, exist_ok=True)
        if full_dst.exists() or full_dst.is_symlink():
            full_dst.unlink()
        full_src.rename(full_dst)
    workdir.rm_paths(repo, [s for s, _ in plan], cached=True)
    workdir.add_paths(repo, [d for _, d in plan])
    return 0


def _wt_mode(full: Path) -> str:
    import stat as _stat
    try:
        st = os.lstat(full)
    except OSError:
        return "000000"
    if _stat.S_ISLNK(st.st_mode):
        return "120000"
    if st.st_mode & 0o111:
        return "100755"
    return "100644"


def _status_model(repo: Repository, s: dict) -> tuple[list[tuple[str, str, str]], list[str]]:
    """Return (changes, untracked).

    ``changes`` is a sorted list of ``(path, X, Y)`` where X is the index-vs-HEAD
    status and Y the worktree-vs-index status; spaces mean unchanged.
    """
    index_status: dict[str, str] = {}
    for p in s["staged_new"]:
        index_status[p] = "A"
    for p in s["staged_mod"]:
        index_status[p] = "M"
    for p in s["staged_del"]:
        index_status[p] = "D"
    worktree_status: dict[str, str] = {}
    for p in s["modified"]:
        worktree_status[p] = "M"
    for p in s["missing"]:
        worktree_status[p] = "D"
    # Intent-to-add entries report as a not-yet-staged new file (" A").
    for p in s.get("intent_to_add", []):
        worktree_status[p] = "A"
    changes = []
    for p in sorted(set(index_status) | set(worktree_status)):
        changes.append((p, index_status.get(p, " "), worktree_status.get(p, " ")))
    return changes, sorted(s["untracked"])


def _parse_rename_score(s: str) -> int:
    """Port of diffcore-rename.c parse_rename_score: turn an -M/-C threshold like
    "50%", "9", or "0.9" into a 0..MAX_SCORE similarity score (0 means default)."""
    num, scale, dot = 0, 1, False
    for ch in s:
        if not dot and ch == ".":
            scale, dot = 1, True
        elif ch == "%":
            scale = scale * 100 if dot else 100
            break
        elif ch.isdigit():
            if scale < 100000:
                scale *= 10
                num = num * 10 + int(ch)
        else:
            break
    from . import diffcore
    m = int(diffcore.MAX_SCORE)
    return m if num >= scale else (m * num) // scale


def _status_staged_renames(repo: Repository, s: dict, minimum_score: int = 0,
                           detailed: bool = False,
                           reference: str = "HEAD") -> list:
    """Detect staged renames (baseline->index). Returns (src, dst) pairs, or
    (src, dst, score, status) tuples when ``detailed`` (for porcelain v2).
    ``reference`` is the comparison base (HEAD, or HEAD^1 under --amend)."""
    if not s["staged_del"] or not s["staged_new"]:
        return []
    from . import diffcore
    head_sha = refs_mod.rev_parse(repo, reference)
    head_map = _tree_map_full(repo, _commit_tree(repo, head_sha)) if head_sha else {}
    idx = read_index(repo).by_path()
    base_map: dict[str, tuple[int, str]] = {}
    for p in s["staged_del"]:
        if p in head_map:
            base_map[p] = (int(head_map[p][0], 8), head_map[p][1])
    side_map: dict[str, tuple[int, str]] = {}
    for p in s["staged_new"]:
        if p in idx:
            side_map[p] = (idx[p].mode, idx[p].sha)
    if not base_map or not side_map:
        return []
    pairs = diffcore.detect_renames(repo, base_map, side_map, minimum_score=minimum_score)
    if detailed:
        # score = p.score * 100 / MAX_SCORE; status is 'R' (detect_renames never
        # returns copies here).
        return [(p.src.path, p.dst.path, int(p.score * 100 / diffcore.MAX_SCORE), "R")
                for p in pairs]
    return [(pair.src.path, pair.dst.path) for pair in pairs]


def _status_branch_header_short(repo: Repository, head_sym, head_sha) -> str:
    branch = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else None
    if head_sym and head_sha is None:
        return f"## No commits yet on {branch}"
    if branch is None:
        return "## HEAD (no branch)"
    upstream, ahead, behind = _branch_tracking(repo, head_sym)
    line = f"## {branch}"
    if upstream:
        line += f"...{upstream}"
        markers = []
        if ahead:
            markers.append(f"ahead {ahead}")
        if behind:
            markers.append(f"behind {behind}")
        if markers:
            line += " [" + ", ".join(markers) + "]"
    return line


def _branch_tracking(repo: Repository, head_sym):
    """Return (upstream_shortname_or_None, ahead, behind)."""
    if not head_sym or not head_sym.startswith("refs/heads/"):
        return None, 0, 0
    branch = head_sym[len("refs/heads/"):]
    from . import gitconfig
    remote = gitconfig.get(repo, f"branch.{branch}.remote")
    merge = gitconfig.get(repo, f"branch.{branch}.merge")
    if not remote or not merge:
        return None, 0, 0
    merge_short = merge[len("refs/heads/"):] if merge.startswith("refs/heads/") else merge
    if remote == ".":
        upstream = merge_short
        upstream_ref = merge
    else:
        upstream = f"{remote}/{merge_short}"
        upstream_ref = f"refs/remotes/{remote}/{merge_short}"
    local = refs_mod.read_ref(repo, head_sym)
    up = refs_mod.read_ref(repo, upstream_ref)
    ahead = behind = 0
    if local and up:
        ahead = _count_commits(repo, local, up)
        behind = _count_commits(repo, up, local)
    return upstream, ahead, behind


def _count_commits(repo: Repository, tip: str, exclude: str) -> int:
    """Count commits reachable from tip but not from exclude."""
    excluded: set[str] = set()
    stack = deque([exclude])
    while stack:
        sha = stack.popleft()
        if sha in excluded:
            continue
        excluded.add(sha)
        info = _commit_tree_parents(repo, sha)
        if info:
            stack.extend(info[1])
    count = 0
    seen: set[str] = set()
    stack = deque([tip])
    while stack:
        sha = stack.popleft()
        if sha in seen or sha in excluded:
            continue
        seen.add(sha)
        info = _commit_tree_parents(repo, sha)
        if info is None:
            continue
        count += 1
        stack.extend(info[1])
    return count


def _status_ignored_paths(repo: Repository) -> list[str]:
    """Gather ignored paths for `status --ignored` (traditional mode): list
    ignored files, collapsing a directory that contains no tracked files to a
    single '<dir>/' entry (mirrors dir.c DIR_SHOW_IGNORED + collapse)."""
    from . import ignore as ignore_mod
    ig = ignore_mod.load(repo.path)
    idx = read_index(repo)
    tracked = set(idx.by_path())

    def has_tracked_under(rel: str) -> bool:
        prefix = rel + "/"
        return any(t.startswith(prefix) for t in tracked)

    out: list[str] = []

    def walk(dir_rel: str) -> None:
        base = repo.path / dir_rel if dir_rel else repo.path
        try:
            entries = sorted(os.scandir(base), key=lambda e: e.name)
        except OSError:
            return
        for entry in entries:
            if entry.name == ".git":
                continue
            rel = f"{dir_rel}/{entry.name}" if dir_rel else entry.name
            is_dir = entry.is_dir(follow_symlinks=False)
            if rel in tracked:
                continue
            if is_dir and has_tracked_under(rel):
                # Mixed directory: descend to surface only ignored leaves.
                walk(rel)
                continue
            if ig.is_ignored(rel, is_dir=is_dir):
                out.append(rel + "/" if is_dir else rel)
            elif is_dir:
                # Untracked, non-ignored directory: descend in case ignored
                # files live beneath it.
                walk(rel)

    walk("")
    return sorted(out)


def cmd_status(argv: list[str]) -> int:
    # Rename detection is on by default (status.renames -> diff.renames -> true).
    # Per builtin/commit.c: --no-renames/--renames set a tri-state (last wins),
    # then -M/--find-renames is applied afterwards and force-enables detection
    # regardless of order. -M/--find-renames take a threshold only when attached.
    no_renames = -1  # -1 unset, 0 --renames, 1 --no-renames
    find_given = False
    rename_score = 0  # 0 -> diffcore's default (50%)
    rest: list[str] = []
    for t in argv:
        if t == "--no-renames":
            no_renames = 1
        elif t == "--renames":
            no_renames = 0
        elif t in ("-M", "--find-renames"):
            find_given = True
            rename_score = 0
        elif t.startswith("-M") and not t.startswith("--"):
            find_given, rename_score = True, _parse_rename_score(t[2:])
        elif t.startswith("--find-renames="):
            find_given, rename_score = True, _parse_rename_score(t[len("--find-renames="):])
        else:
            rest.append(t)
    rename_enabled = not (no_renames == 1 and not find_given)

    ap = argparse.ArgumentParser(prog="pygit status", add_help=False)
    ap.add_argument("-s", "--short", action="store_true")
    ap.add_argument("-b", "--branch", action="store_true")
    ap.add_argument("--long", dest="long", action="store_true")
    ap.add_argument("--porcelain", nargs="?", const="v1", default=None)
    ap.add_argument("-u", "--untracked-files", nargs="?", const="all", default="all")
    ap.add_argument("-z", "--null", dest="nul", action="store_true")
    ap.add_argument("-v", "--verbose", action="count", default=0)
    ap.add_argument("--show-stash", dest="show_stash", action="store_true")
    ap.add_argument("--no-show-stash", dest="show_stash", action="store_false")
    ap.add_argument("--ahead-behind", dest="ahead_behind", action="store_true", default=True)
    ap.add_argument("--no-ahead-behind", dest="ahead_behind", action="store_false")
    ap.add_argument("--ignored", nargs="?", const="traditional", default=None)
    ap.add_argument("--ignore-submodules", dest="ignore_submodules",
                    nargs="?", const="all", default=None)
    ap.add_argument("--column", nargs="?", const="always", default=None)
    ap.add_argument("--no-column", dest="column", action="store_const", const="never")
    args = ap.parse_args(rest)
    repo = _repo()
    s = workdir.status(repo)
    head_sym, head_sha = refs_mod.read_head(repo)
    branch = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else None
    changes, untracked = _status_model(repo, s)
    renames = _status_staged_renames(repo, s, rename_score) if rename_enabled else []
    if renames:
        consumed = {src for src, _ in renames} | {dst for _, dst in renames}
        changes = [(p, x, y) for p, x, y in changes if p not in consumed]
    show_untracked = args.untracked_files != "no"
    untracked_hidden = bool(untracked) and not show_untracked
    if not show_untracked:
        untracked = []

    porcelain = args.porcelain
    short_mode = args.short and not args.long and porcelain is None
    # -z/--null implies porcelain-v1 NUL output unless a format is already
    # selected; with --long it is a hard error (builtin/commit.c null rule).
    if args.nul:
        if args.long:
            _err("fatal: options '--long' and '-z' cannot be used together")
            return 128
        if porcelain is None and not short_mode:
            porcelain = "v1"
    eol = "\0" if args.nul else "\n"

    def emit(line: str):
        sys.stdout.write(line + eol)

    if porcelain == "v2":
        v2_renames = (_status_staged_renames(repo, s, rename_score, detailed=True)
                      if rename_enabled else [])
        return _status_porcelain_v2(repo, s, changes, untracked, args.branch,
                                    head_sym, head_sha, eol, renames=v2_renames)

    if porcelain is not None or short_mode:
        if args.branch:
            emit(_status_branch_header_short(repo, head_sym, head_sha))
        entries = [(dst, f"R  {src} -> {dst}") for src, dst in renames]
        entries += [(p, f"{x}{y} {p}") for p, x, y in changes]
        for _key, line in sorted(entries):
            emit(line)
        for p in untracked:
            emit(f"?? {p}")
        if args.ignored is not None and args.ignored != "no":
            for p in _status_ignored_paths(repo):
                emit(f"!! {p}")
        return 0

    # Long (default) format. -v/-vv append the staged (and, for -vv, worktree)
    # diff just before the summary line.
    verbose_hook = None
    if args.verbose:
        verbose_hook = lambda committable: _status_verbose_diff(
            repo, args.verbose, committable, rename_enabled, rename_score)
    ignored_paths = (_status_ignored_paths(repo)
                     if (args.ignored is not None and args.ignored != "no") else None)
    stash_count = None
    if args.show_stash:
        from . import stash as _stash
        try:
            stash_count = len(_stash.list_stashes(repo))
        except Exception:
            stash_count = 0
    return _status_long(repo, s, changes, untracked, branch, head_sym, head_sha,
                        untracked_hidden, renames, verbose_hook,
                        ignored_paths=ignored_paths, stash_count=stash_count)


def _status_long(repo, s, changes, untracked, branch, head_sym, head_sha, untracked_hidden=False, renames=None, verbose_hook=None, reference="HEAD", commit_template=False, ignored_paths=None, stash_count=None) -> int:
    unborn = head_sym is not None and head_sha is None
    if branch is not None:
        _print(f"On branch {branch}")
    else:
        _print("HEAD detached")
    if unborn:
        # wt-status.c: "Initial commit" in a commit-template context (e.g.
        # `commit --amend --dry-run` of a root), "No commits yet" for plain
        # status; both bracketed by blank lines.
        _print("")
        _print("Initial commit" if commit_template else "No commits yet")
        _print("")

    staged = [(p, x) for p, x, y in changes if x != " "]
    unstaged = [(p, y) for p, x, y in changes if y != " "]
    label = {"A": "new file:   ", "M": "modified:   ", "D": "deleted:    "}
    rename_rows = [(dst, f"\trenamed:    {src} -> {dst}") for src, dst in (renames or [])]

    if staged or rename_rows:
        _print("Changes to be committed:")
        if unborn:
            _print('  (use "git rm --cached <file>..." to unstage)')
        elif reference == "HEAD":
            _print('  (use "git restore --staged <file>..." to unstage)')
        else:
            _print(f'  (use "git restore --source={reference} --staged <file>..." to unstage)')
        staged_rows = rename_rows + [(p, f"\t{label[x]}{p}") for p, x in staged]
        for _key, line in sorted(staged_rows):
            _print(line)
        _print("")
    if unstaged:
        _print("Changes not staged for commit:")
        if any(y == "D" for _, y in unstaged):
            _print('  (use "git add/rm <file>..." to update what will be committed)')
        else:
            _print('  (use "git add <file>..." to update what will be committed)')
        _print('  (use "git restore <file>..." to discard changes in working directory)')
        for p, y in unstaged:
            _print(f"\t{label[y]}{p}")
        _print("")
    if untracked:
        _print("Untracked files:")
        _print('  (use "git add <file>..." to include in what will be committed)')
        for p in untracked:
            _print(f"\t{p}")
        _print("")
    elif untracked_hidden and (staged or rename_rows):
        # With staged changes present (so no trailing summary), -uno still notes
        # hidden untracked files. Without staged changes the summary line
        # ("no changes added"/"nothing to commit, use -u") carries the hint.
        _print("Untracked files not listed (use -u option to show untracked files)")

    # Ignored files section (status --ignored), after untracked, before summary.
    if ignored_paths:
        _print("Ignored files:")
        _print('  (use "git add -f <file>..." to include in what will be committed)')
        for p in ignored_paths:
            _print(f"\t{p}")
        _print("")

    has_staged = bool(staged) or bool(rename_rows)
    # C Git prints the verbose (-v/-vv) diff after the sections but before the
    # trailing summary line (wt_longstatus_print order).
    if verbose_hook is not None:
        verbose_hook(has_staged)
    if not has_staged and not unstaged and not untracked:
        if untracked_hidden:
            _print("nothing to commit (use -u to show untracked files)")
        elif unborn:
            _print('nothing to commit (create/copy files and use "git add" to track)')
        else:
            _print("nothing to commit, working tree clean")
    elif not has_staged and not unstaged and untracked:
        _print('nothing added to commit but untracked files present (use "git add" to track)')
    elif not has_staged and unstaged:
        _print('no changes added to commit (use "git add" and/or "git commit -a")')
    # --show-stash: the stash line is emitted last (wt_longstatus_print_stash).
    if stash_count:
        plural = "entry" if stash_count == 1 else "entries"
        _print(f"Your stash currently has {stash_count} {plural}")
    return 0


def _emit_change_diffs(repo: Repository, changes: list, rename_enabled: bool,
                       rename_score: int, a_prefix: str, b_prefix: str) -> None:
    """Render a change list as a patch (rename-aware), with the given prefixes."""
    if rename_enabled:
        renames, remaining = _detect_changes_renames(repo, changes, rename_score)
    else:
        renames, remaining = [], changes
    emit = [(dst, lambda s=src, d=dst, sm=sim, sa=sa, db=db:
             _emit_rename_patch(s, d, sm, sa, db, a_prefix=a_prefix, b_prefix=b_prefix))
            for src, dst, sim, sa, db in renames]
    emit += [(path, lambda p=path, a=a, b=b:
              _emit_file_diff(p, a, b, a_prefix=a_prefix, b_prefix=b_prefix))
             for path, a, b in remaining]
    for _key, fn in sorted(emit, key=lambda e: e[0]):
        fn()


def _status_verbose_diff(repo: Repository, verbose: int, committable: bool,
                         rename_enabled: bool, rename_score: int) -> None:
    """Port of wt_longstatus_print_verbose: the staged diff (HEAD vs index) and,
    for -vv, the worktree diff (index vs worktree). -v uses a/b prefixes with no
    header; -vv uses c/i under a "Changes to be committed:" header, then a
    50-dash separator and i/w under "Changes not staged for commit:"."""
    idx = read_index(repo).by_path()
    head_sha = refs_mod.rev_parse(repo, "HEAD")
    head_map = _tree_map_full(repo, _commit_tree(repo, head_sha)) if head_sha else {}

    staged: list[tuple[str, _Side, _Side]] = []
    for p in sorted(set(head_map) | set(idx)):
        if p in idx and idx[p].intent_to_add and p not in head_map:
            continue  # intent-to-add is not staged
        a = _side_from_object(repo, *head_map[p]) if p in head_map else _ABSENT
        b = _side_from_object(repo, idx[p].mode_str(), idx[p].sha) if p in idx else _ABSENT
        if a.sha != b.sha or a.mode != b.mode:
            staged.append((p, a, b))
    if verbose > 1 and committable:
        _print("Changes to be committed:")
        sa, sb = "c", "i"
    else:
        sa, sb = "a", "b"
    _emit_change_diffs(repo, staged, rename_enabled, rename_score, sa, sb)

    if verbose > 1:
        unstaged: list[tuple[str, _Side, _Side]] = []
        for p in sorted(idx):
            a = _ABSENT if idx[p].intent_to_add else _side_from_object(repo, idx[p].mode_str(), idx[p].sha)
            b = _side_from_worktree(repo, p)
            if a.sha != b.sha or a.mode != b.mode:
                unstaged.append((p, a, b))
        if unstaged:
            _print("--------------------------------------------------")
            _print("Changes not staged for commit:")
            _emit_change_diffs(repo, unstaged, rename_enabled, rename_score, "i", "w")


def _status_porcelain_v2(repo, s, changes, untracked, want_branch, head_sym, head_sha,
                         eol, renames=None) -> int:
    def emit(line: str):
        sys.stdout.write(line + eol)
    if want_branch:
        oid = head_sha or "(initial)"
        emit(f"# branch.oid {oid}")
        emit(f"# branch.head {head_sym[len('refs/heads/'):] if head_sym and head_sym.startswith('refs/heads/') else '(detached)'}")
        upstream, ahead, behind = _branch_tracking(repo, head_sym)
        if upstream:
            emit(f"# branch.upstream {upstream}")
            emit(f"# branch.ab +{ahead} -{behind}")
    idx = read_index(repo).by_path()
    head_modes: dict[str, str] = {}
    head_shas: dict[str, str] = {}
    if head_sha:
        _, hdata = objs.read_object(repo, head_sha)
        htree = objs.parse_commit(hdata).tree
        for path, mode, sha in workdir.iter_tree_files(repo, htree):
            head_modes[path] = mode
            head_shas[path] = sha
    zero = "0" * 40
    sep = "\0" if eol == "\0" else "\t"
    # Changed entries (1-type) and rename/copy entries (2-type) interleave in
    # current-path order (wt-status.c iterates the path-sorted change list).
    rows: list[tuple[str, str]] = []
    for p, x, y in changes:
        xv = x if x != " " else "."
        yv = y if y != " " else "."
        mH = head_modes.get(p, "000000")
        mI = idx[p].mode_str() if p in idx else "000000"
        mW = "000000" if y == "D" else _wt_mode(repo.path / p)
        hH = head_shas.get(p, zero)
        hI = idx[p].sha if p in idx else zero
        rows.append((p, f"1 {xv}{yv} N... {mH} {mI} {mW} {hH} {hI} {p}"))
    for entry in (renames or []):
        src, dst, score, rstatus = entry
        # A staged rename: index_status = R (or C), worktree_status = '.'.
        xv, yv = rstatus, "."
        mH = head_modes.get(src, "000000")
        mI = idx[dst].mode_str() if dst in idx else "000000"
        mW = _wt_mode(repo.path / dst) if (repo.path / dst).exists() else mI
        hH = head_shas.get(src, zero)
        hI = idx[dst].sha if dst in idx else zero
        rows.append((dst, f"2 {xv}{yv} N... {mH} {mI} {mW} {hH} {hI} "
                          f"{rstatus}{score} {dst}{sep}{src}"))
    for _key, line in sorted(rows):
        emit(line)
    for p in untracked:
        emit(f"? {p}")
    return 0


def _commit_status_report(repo: Repository) -> int:
    s = workdir.status(repo)
    head_sym, head_sha = refs_mod.read_head(repo)
    branch = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else None
    changes, untracked = _status_model(repo, s)
    _status_long(repo, s, changes, untracked, branch, head_sym, head_sha)
    return 1


def _partial_commit_tree(repo: Repository, parent: Optional[str], only_paths: list[str]) -> str:
    """Build the tree for a partial commit: HEAD's tree with only ``only_paths``
    updated from the index (added/modified/removed), the rest left as in HEAD."""
    entries: dict[str, tuple[str, str]] = {}  # path -> (mode_str, sha)
    if parent:
        ptree = objs.parse_commit(objs.read_object(repo, parent)[1]).tree
        for path, mode, sha in workdir.iter_tree_files(repo, ptree):
            entries[path] = (mode, sha)
    idx = read_index(repo).by_path()
    wanted = set(only_paths)
    for p in only_paths:
        if p in idx:
            entries[p] = (idx[p].mode_str(), idx[p].sha)
        else:
            entries.pop(p, None)  # path removed in this partial commit
    # Build nested trees from the flat entry map.
    root: dict = {}
    for path, (mode, sha) in entries.items():
        parts = path.split("/")
        cur = root
        for part in parts[:-1]:
            cur = cur.setdefault(part, {})
        cur[parts[-1]] = (mode, sha)

    def emit(node: dict) -> str:
        te: list[objs.TreeEntry] = []
        for name, val in node.items():
            if isinstance(val, dict):
                te.append(objs.TreeEntry("40000", name, emit(val)))
            else:
                mode, sha = val
                te.append(objs.TreeEntry(mode.lstrip("0") or "0", name, sha))
        return objs.write_object(repo, "tree", objs.encode_tree(te))

    return emit(root)


def _git_parse_maybe_bool(value: str) -> Optional[int]:
    """Port of parse.c git_parse_maybe_bool: 1/0 for the recognized bool
    spellings (and integers, nonzero->1), else None (-1 in C)."""
    if value == "":
        return 0
    low = value.lower()
    if low in ("true", "yes", "on"):
        return 1
    if low in ("false", "no", "off"):
        return 0
    try:
        return 1 if int(value, 10) != 0 else 0
    except ValueError:
        return None


_APPROXIDATE_MONTHS = ("january", "february", "march", "april", "may", "june",
                       "july", "august", "september", "october", "november",
                       "december")
_APPROXIDATE_WEEKDAYS = ("sunday", "monday", "tuesday", "wednesday", "thursday",
                         "friday", "saturday")
_APPROXIDATE_SPECIAL = ("yesterday", "noon", "midnight", "tea", "pm", "am",
                        "never", "now", "last")
_APPROXIDATE_NUMBERS = ("zero", "one", "two", "three", "four", "five", "six",
                        "seven", "eight", "nine", "ten")


def _force_date_is_valid(value: str) -> bool:
    """Port of builtin/commit.c parse_force_date: a --date value is valid if
    parse_date accepts it (handled by objects._parse_date_env for the raw/ISO/
    RFC2822 spellings) or approxidate_careful finds at least one recognizable
    token.  approxidate flags an error only when *nothing* in the string was
    touched, so we accept any value containing a digit, a month/weekday-name
    prefix (>=3 letters), or one of the special/number relative words."""
    from . import objects as _objs
    if value.strip() == "":
        return False
    if _objs._parse_date_env(value) is not None:
        return True
    if any(ch.isdigit() for ch in value):
        return True
    import re as _re
    for word in _re.findall(r"[A-Za-z]+", value):
        w = word.lower()
        if w in _APPROXIDATE_SPECIAL or w in _APPROXIDATE_NUMBERS:
            return True
        if len(w) >= 3:
            for name in _APPROXIDATE_MONTHS + _APPROXIDATE_WEEKDAYS:
                if name.startswith(w) or w.startswith(name):
                    return True
    return False


def _validate_untracked_mode(value: str) -> Optional[str]:
    """Port of builtin/commit.c parse_untracked_setting_name +
    handle_untracked_files_arg.  Maps bool spellings (yes/true/on/N>0 -> normal,
    no/false/off/0 -> no), then validates no|normal|all.  Returns the canonical
    mode, or None after emitting the fatal for an invalid value."""
    u = value
    b = _git_parse_maybe_bool(value)
    if b == 0:
        u = "no"
    elif b == 1:
        u = "normal"
    if u in ("no", "normal", "all"):
        return u
    _err(f"fatal: Invalid untracked files mode '{value}'")
    return None


def _cleanup_commit_message(msg: str, mode: Optional[str],
                            comment_prefix: Optional[str] = "#") -> str:
    """Apply git's commit-message cleanup (sequencer.c cleanup_message /
    strbuf.c strbuf_stripspace). 'verbatim' (NONE) is a no-op; 'whitespace' and
    non-editor 'default'/'scissors' (SPACE) strip trailing whitespace per line
    and collapse leading/trailing/consecutive blank lines; 'strip' (ALL) does
    the same AND drops whole lines that begin with the comment prefix (default
    '#', i.e. core.commentChar)."""
    if mode == "verbatim":
        return msg
    # COMMIT_MSG_CLEANUP_ALL ('strip') removes comment lines; every other mode
    # that reaches here (SPACE) passes comment_prefix=None.
    strip_comments = (mode == "strip")
    lines = msg.split("\n")
    out: list[str] = []
    for ln in lines:
        if strip_comments and comment_prefix and ln.startswith(comment_prefix):
            continue
        ln = ln.rstrip()
        if ln == "" and (not out or out[-1] == ""):
            continue
        out.append(ln)
    while out and out[-1] == "":
        out.pop()
    while out and out[0] == "":
        out.pop(0)
    return "\n".join(out)


def _trailer_cmdline_separator_pos(text: str) -> int:
    """Port of trailer.c:find_separator with cl_separators '=:' (the '=' that
    command-line trailers additionally accept, plus the default ':'). Returns
    the index of the separator, 0 if it leads, or -1 if not well-formed."""
    seps = "=:"
    whitespace_found = False
    for i, ch in enumerate(text):
        if ch in seps:
            return i
        if not whitespace_found and (ch.isalnum() or ch == "-"):
            continue
        if i != 0 and ch in (" ", "\t"):
            whitespace_found = True
            continue
        break
    return -1


def _normalize_cmdline_trailer(text: str) -> str:
    """Port of trailer.c:parse_trailer + format_trailers for a single
    command-line --trailer argument with no trailer config. Splits on '=' or
    ':', trims key and value, and re-emits 'key: value' (the default key/value
    separator is ': ', appended when the key doesn't already end in a
    separator). A value-less trailer keeps the bare key."""
    pos = _trailer_cmdline_separator_pos(text)
    if pos == 0:
        # Empty token: git errors, but callers only reach here with valid
        # trailers; preserve the literal as a defensive fallback.
        return text.strip()
    if pos == -1:
        return text.strip()
    tok = text[:pos].strip()
    val = text[pos + 1:].strip()
    # format_trailers: key_value_separator is unset, so append "<sep0> " only
    # if the key's last non-space char is not already a separator (':').
    last = tok.rstrip()
    if last and last[-1] not in ":":
        return f"{tok}: {val}"
    return f"{tok} {val}"


def _apply_trailers(msg: str, trailers: list[str]) -> str:
    """Append a trailer block (Signed-off-by etc.) to a commit message, after a
    blank line separating it from the body — matching git's simple case."""
    if not trailers:
        return msg
    body = msg.rstrip("\n")
    block = "\n".join(trailers)
    return (body + "\n\n" + block) if body else block


def _incompatible_opts(opts: list[str]) -> str:
    """Render C Git's "options ... cannot be used together" message for a list
    of 2-4 option names (the count selects the comma/and punctuation)."""
    if len(opts) == 2:
        joined = f"'{opts[0]}' and '{opts[1]}'"
    else:
        joined = ", ".join(f"'{o}'" for o in opts[:-1]) + f", and '{opts[-1]}'"
    return f"fatal: options {joined} cannot be used together"


def _strip_commit_subject(msg: str) -> str:
    """Return a commit message's body: everything after the first blank line,
    with leading blank lines skipped (C Git's skip_blank_lines(buffer + 2))."""
    idx = msg.find("\n\n")
    if idx < 0:
        return ""
    return msg[idx + 2:].lstrip("\n")


def _commit_message_conflict(args) -> Optional[str]:
    """Mirror C Git's commit message-source incompatibility checks, in order:
    (A) at most one of -m/-C/-c/-F; (B) --squash and --fixup are exclusive;
    (C) --fixup cannot combine with -C/-c/-F (but -m is allowed as a body)."""
    group = []
    if args.message is not None:
        group.append("-m")
    if args.reuse_message is not None:
        group.append("-C")
    if args.reedit_message is not None:
        group.append("-c")
    if args.file is not None:
        group.append("-F")
    if len(group) >= 2:
        return _incompatible_opts(group)
    if args.squash is not None and args.fixup is not None:
        return _incompatible_opts(["--squash", "--fixup"])
    if args.fixup is not None:
        for opt, val in (("-C", args.reuse_message), ("-c", args.reedit_message),
                         ("-F", args.file)):
            if val is not None:
                return _incompatible_opts([opt, "--fixup"])
    return None


def _require_value_flags(argv: list[str], specs: "dict[str, str]") -> None:
    """Raise _SwitchParseError when a value-taking flag appears as the final
    token (or before the next option) with no value, matching parse-options.

    *specs* maps each accepted token form to the error word to quote.  Short
    flags (``-x``) report ``switch `x'``; long flags report ``option `name'``.
    Only the separate-token form is checked here (the attached ``-xval`` /
    ``--long=val`` forms always carry a value).  Tokens after ``--`` skipped.
    """
    i = 0
    n = len(argv)
    while i < n:
        t = argv[i]
        if t == "--":
            break
        if t in specs:
            if i + 1 >= n:
                if t.startswith("--"):
                    raise _SwitchParseError(
                        f"error: option `{t[2:]}' requires a value")
                raise _SwitchParseError(
                    f"error: switch `{t[1]}' requires a value")
            i += 2
            continue
        i += 1


def _extract_gpg_sign_optarg(argv: list[str]) -> tuple[list[str], Optional[str], bool]:
    """Strip ``-S`` / ``-Skeyid`` / ``--gpg-sign`` / ``--gpg-sign=keyid`` and
    ``--no-gpg-sign`` from *argv*, honoring git's PARSE_OPT_OPTARG semantics:
    only the *attached* forms supply a key-id; a following token is never taken
    as the value.  Returns (argv_without_them, gpg_sign_value_or_None,
    no_gpg_sign_seen).  Tokens after ``--`` are left untouched."""
    out: list[str] = []
    gpg_sign: Optional[str] = None
    no_sign = False
    i = 0
    n = len(argv)
    seen_ddash = False
    while i < n:
        t = argv[i]
        if seen_ddash:
            out.append(t)
            i += 1
            continue
        if t == "--":
            seen_ddash = True
            out.append(t)
            i += 1
            continue
        if t == "--no-gpg-sign":
            no_sign = True
            gpg_sign = None
            i += 1
            continue
        if t == "--gpg-sign":
            gpg_sign = ""
            no_sign = False
            i += 1
            continue
        if t.startswith("--gpg-sign="):
            gpg_sign = t[len("--gpg-sign="):]
            no_sign = False
            i += 1
            continue
        if t == "-S":
            gpg_sign = ""
            no_sign = False
            i += 1
            continue
        if t.startswith("-S") and len(t) > 2 and not t.startswith("--"):
            gpg_sign = t[2:]
            no_sign = False
            i += 1
            continue
        out.append(t)
        i += 1
    return out, gpg_sign, no_sign


def _strbuf_stripspace(text: str, strip_comments_char: Optional[str]) -> str:
    """Port of strbuf_stripspace(): trim trailing whitespace on each line, drop
    leading/trailing blank lines, collapse runs of blank lines into a single
    one.  When *strip_comments_char* is given, lines beginning with it are
    removed entirely (cleanup=all)."""
    out: list[str] = []
    pending_blank = False
    started = False
    for raw in text.split("\n"):
        line = raw.rstrip(" \t\r\f\v")
        if strip_comments_char is not None and line.startswith(strip_comments_char):
            continue
        if line == "":
            if started:
                pending_blank = True
            continue
        if pending_blank:
            out.append("")
            pending_blank = False
        out.append(line)
        started = True
    result = "\n".join(out)
    if result:
        result += "\n"
    return result


def _rest_is_empty(sb: str, start: int) -> bool:
    """Port of rest_is_empty() (sequencer.c): the remainder is only whitespace
    and Signed-off-by trailers."""
    sign_off = "Signed-off-by: "
    i = start
    n = len(sb)
    while i < n:
        nl = sb.find("\n", i)
        eol = nl if nl >= 0 else n
        if eol - i >= len(sign_off) and sb.startswith(sign_off, i):
            i = eol
            if nl >= 0:
                i += 1
            continue
        while i < eol:
            if not sb[i].isspace():
                return False
            i += 1
        if nl >= 0:
            i += 1
        else:
            break
    return True


def _template_untouched(sb: str, template_text: Optional[str], cleanup_all: bool) -> bool:
    """Port of template_untouched() (sequencer.c): true if the edited buffer is
    still the (stripped) template followed by nothing but whitespace/sign-offs.
    Here cleanup is NONE only when --cleanup=verbatim; otherwise the template
    is stripspace'd before comparison."""
    if template_text is None:
        return False
    tmpl = _strbuf_stripspace(template_text, "#" if cleanup_all else None)
    if not tmpl:
        return False
    if sb.startswith(tmpl):
        start = len(tmpl)
    else:
        start = 0
    return _rest_is_empty(sb, start)


def _commit_apply_template(repo: Repository, args) -> Optional[int]:
    """Handle ``commit -t/--template``.  Returns None to continue, or an exit
    code to return immediately (missing template, unedited template, or
    editor-aborted commit)."""
    if args.template is None:
        return None
    # Any explicit message source (-m/-F/-C/-c/--fixup/--squash) wins; the
    # template file is never even opened in that case (prepare_to_commit order).
    if args.message is not None:
        return None
    try:
        with open(args.template, "rb") as fh:
            template_text = fh.read().decode("utf-8", "replace")
    except OSError as e:
        import errno
        _err(f"fatal: could not read '{args.template}': {os.strerror(e.errno or errno.ENOENT)}")
        return 128
    # cleanup mode: default/strip => clean (strip comments), verbatim => NONE.
    cleanup_none = (args.cleanup == "verbatim")
    cleanup_all = args.cleanup in (None, "default", "strip", "whitespace", "all", "scissors")
    # prepare_to_commit: with a template, clean_message_contents=0, so the seed
    # written to COMMIT_EDITMSG is the raw template (no stripspace yet).
    seed = template_text
    edited = _launch_commit_editor(repo, seed)
    if edited is None:
        _err("error: There was a problem with the editor '%s'." % _commit_editor_name(repo))
        _err("Please supply the message using either -m or -F option.")
        return 1
    # cleanup of the editor result.
    if cleanup_none:
        cleaned = edited
    else:
        cleaned = _strbuf_stripspace(edited, "#" if cleanup_all else None)
    # message_is_empty / template_untouched aborts (unless --allow-empty-message).
    if not args.allow_empty_message:
        if _commit_message_is_empty(cleaned, cleanup_none):
            _err("Aborting commit due to empty commit message.")
            return 1
        if _template_untouched(cleaned, template_text, cleanup_all):
            _err("Aborting commit; you did not edit the message.")
            return 1
    args.message = cleaned
    # The message is already cleaned here; _cleanup_commit_message later is a
    # no-op on already-stripped text, matching C Git's single cleanup pass.
    return None


def _commit_message_is_empty(sb: str, cleanup_none: bool) -> bool:
    """Port of message_is_empty()."""
    if cleanup_none and sb:
        return False
    return _rest_is_empty(sb, 0)


def _commit_editor_name(repo: Repository) -> str:
    from . import addpatch
    return addpatch._editor_command(repo)


def _launch_commit_editor(repo: Repository, seed: str) -> Optional[str]:
    """Write *seed* to .git/COMMIT_EDITMSG, run the configured editor, and read
    the file back.  Returns the edited text, or None if the editor failed."""
    import subprocess
    from . import addpatch
    editor = addpatch._editor_command(repo)
    path = repo.gitdir / "COMMIT_EDITMSG"
    path.write_text(seed, encoding="utf-8")
    try:
        rc = subprocess.call(
            "%s %s" % (editor, addpatch._shell_quote(str(path))), shell=True)
    except OSError:
        return None
    if rc != 0:
        return None
    try:
        return path.read_text(encoding="utf-8")
    except OSError:
        return None


def _resolve_sign_commit(repo: Repository, args) -> Optional[str]:
    """Resolve the effective ``sign_commit`` value (commit.c semantics):

      * config commit.gpgsign=true  -> "" (sign with default key)
      * -S / --gpg-sign             -> "" (or the inline key-id)
      * --no-gpg-sign               -> None (disable)

    Returns the signing-key string ("" = default), or None when unsigned.
    """
    from . import gitconfig
    sign: Optional[str] = None
    try:
        cfg = gitconfig.get(repo, "commit.gpgsign")
    except Exception:
        cfg = None
    if cfg is not None and _git_config_bool(cfg):
        sign = ""
    if getattr(args, "gpg_sign", None) is not None:
        sign = args.gpg_sign
    if getattr(args, "no_gpg_sign", False):
        sign = None
    return sign


def _ident_no_date(signature: str) -> str:
    """From a 'Name <email> <ts> <tz>' signature line, return 'Name <email>'
    (git_committer_info(IDENT_NO_DATE))."""
    gt = signature.rfind(">")
    if gt >= 0:
        return signature[:gt + 1]
    return signature


def _format_subject(message: str, separator: str = " ") -> str:
    """Reproduce pretty.c format_subject(): skip leading blank lines, then fold
    consecutive non-blank lines (until the first blank line) into one string
    joined by ``separator``. Each line has trailing whitespace stripped. This is
    the %s placeholder used by the commit summary line."""
    lines = message.split("\n")
    # Skip leading blank lines (whitespace-only).
    i = 0
    while i < len(lines) and lines[i].strip() == "":
        i += 1
    out: list[str] = []
    while i < len(lines):
        # is_blank_line() strips trailing whitespace then checks emptiness.
        stripped = lines[i].rstrip()
        if stripped == "":
            break
        out.append(stripped)
        i += 1
    return separator.join(out)


def _find_author_by_nickname(repo: Repository, name: str) -> Optional[str]:
    """Port of builtin/commit.c:find_author_by_nickname. Runs the equivalent of
    'git log --all -i --author=<name>' and returns the first matching commit's
    '%aN <%aE>'. Returns None if nothing matches (caller turns that into the
    fatal error)."""
    import re
    import heapq
    import fnmatch
    pat = re.compile(re.escape(name), re.IGNORECASE)
    # Walk all refs (+ HEAD) in stable committer-date-descending order, exactly
    # like cmd_log's --all collection, and take the first author match.
    heap: list[tuple[int, int, str]] = []
    pushed: set[str] = set()
    counter = 0

    def _push(csha: str) -> None:
        nonlocal counter
        if not csha or csha in pushed:
            return
        pushed.add(csha)
        heapq.heappush(heap, (-_commit_date(repo, csha), counter, csha))
        counter += 1

    for refname, _rsha in _enumerate_refs(repo):
        for pre in ("refs/heads/", "refs/tags/", "refs/remotes/"):
            if refname.startswith(pre):
                csha = refs_mod.rev_parse(repo, refname + "^{commit}")
                if csha:
                    _push(csha)
                break
    _, head_sha = refs_mod.read_head(repo)
    if head_sha:
        _push(head_sha)
    seen: set[str] = set()
    while heap:
        _d, _c, s = heapq.heappop(heap)
        if s in seen:
            continue
        seen.add(s)
        info = _commit_tree_parents(repo, s)
        if info is None:
            continue
        c = objs.parse_commit(objs.read_object(repo, s)[1])
        # --author greps the raw author header (Name <email> ts tz), -i.
        if pat.search(c.author):
            who, _ts, _tz = _split_ident(c.author)
            n, e = _parse_who(who)
            return f"{n} <{e}>"
        for p in info[1]:
            _push(p)
    return None


def cmd_commit(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit commit", add_help=False)
    ap.add_argument("-m", "--message", action="append", default=None)
    ap.add_argument("-F", "--file", default=None)
    ap.add_argument("-a", "--all", action="store_true")
    ap.add_argument("--amend", action="store_true")
    ap.add_argument("--no-edit", action="store_true")
    ap.add_argument("-e", "--edit", action="store_true")
    ap.add_argument("--allow-empty", action="store_true")
    ap.add_argument("--allow-empty-message", dest="allow_empty_message", action="store_true")
    ap.add_argument("--date", default=None)
    ap.add_argument("--author", default=None)
    ap.add_argument("-s", "--signoff", action="store_true", default=False)
    ap.add_argument("--no-signoff", dest="signoff", action="store_false")
    ap.add_argument("--trailer", action="append", default=None)
    ap.add_argument("--reset-author", dest="reset_author", action="store_true")
    ap.add_argument("--cleanup", default=None)
    ap.add_argument("-o", "--only", action="store_true")
    ap.add_argument("-i", "--include", action="store_true")
    ap.add_argument("-p", "--patch", dest="patch", action="store_true")
    ap.add_argument("--interactive", dest="interactive", action="store_true")
    ap.add_argument("-U", "--unified", dest="unified", type=int, default=-1)
    ap.add_argument("--inter-hunk-context", dest="interhunkcontext", type=int, default=-1)
    ap.add_argument("--auto-advance", dest="auto_advance", action="store_true", default=True)
    ap.add_argument("--no-auto-advance", dest="auto_advance", action="store_false")
    ap.add_argument("-n", "--no-verify", dest="no_verify", action="store_true")
    ap.add_argument("--verify", dest="verify", action="store_true")
    ap.add_argument("--no-post-rewrite", dest="no_post_rewrite", action="store_true")
    ap.add_argument("--post-rewrite", dest="post_rewrite", action="store_true")
    ap.add_argument("-C", "--reuse-message", dest="reuse_message", default=None)
    ap.add_argument("-c", "--reedit-message", dest="reedit_message", default=None)
    ap.add_argument("--squash", default=None)
    ap.add_argument("--fixup", default=None)
    ap.add_argument("--dry-run", dest="dry_run", action="store_true")
    ap.add_argument("--pathspec-from-file", dest="pathspec_from_file", default=None)
    ap.add_argument("--pathspec-file-nul", dest="pathspec_file_nul", action="store_true")
    ap.add_argument("-u", "--untracked-files", dest="untracked_files", nargs="?", const="all", default="all")
    # Dry-run output formats: --short/--porcelain/--long/-z all imply --dry-run.
    ap.add_argument("--short", action="store_true")
    ap.add_argument("--porcelain", action="store_true")
    ap.add_argument("--long", dest="long", action="store_true")
    ap.add_argument("--branch", action="store_true")
    ap.add_argument("--ahead-behind", dest="ahead_behind", action="store_true")
    ap.add_argument("--no-ahead-behind", dest="no_ahead_behind", action="store_true")
    ap.add_argument("--status", dest="status", action="store_true")
    ap.add_argument("--no-status", dest="no_status", action="store_true")
    ap.add_argument("-z", "--null", dest="nul", action="store_true")
    ap.add_argument("-v", "--verbose", action="count", default=0)
    ap.add_argument("-q", "--quiet", action="store_true")
    ap.add_argument("-t", "--template", dest="template", default=None)
    # -S / --gpg-sign carry an OPTIONAL inline key-id (PARSE_OPT_OPTARG): only
    # the attached forms `-Skeyid` / `--gpg-sign=keyid` supply a value; a bare
    # `-S` / `--gpg-sign` means "sign with the default key" (sentinel "").
    ap.add_argument("--gpg-sign-arg", dest="gpg_sign", default=None)
    ap.add_argument("--no-gpg-sign", dest="no_gpg_sign", action="store_true")
    ap.add_argument("pathspec", nargs="*")
    # Pre-pass: pull out -S/--gpg-sign with OPTARG semantics so a following
    # token is never swallowed as the key-id (matches PARSE_OPT_OPTARG).
    argv, gpg_sign_pre, no_gpg_sign_pre = _extract_gpg_sign_optarg(argv)
    # -t/--template (and -F/--file, -F's value) require a value: report the
    # exact parse-options error instead of argparse's generic usage dump.
    try:
        _require_value_flags(argv, {
            "-t": "t", "--template": "template",
            "-F": "F", "--file": "file",
        })
    except _SwitchParseError as exc:
        _err(exc.message)
        return exc.rc
    args = ap.parse_args(argv)
    if no_gpg_sign_pre:
        args.no_gpg_sign = True
    if gpg_sign_pre is not None:
        args.gpg_sign = gpg_sign_pre
    # builtin/commit.c finalize_deferred_config: -z with --long is rejected.
    # (-z is only meaningful with --porcelain / --short.)
    if args.nul and args.long:
        _err(_incompatible_opts(["--long", "-z"]))
        return 128
    # handle_untracked_files_arg(): validate the -u/--untracked-files mode.
    # Accepted: no|normal|all plus the bool spellings (yes/true/1 -> normal,
    # no/false/0/off -> no), via git_parse_maybe_bool.
    args.untracked_files = _validate_untracked_mode(args.untracked_files)
    if args.untracked_files is None:
        return 128
    # get_cleanup_mode(): reject any --cleanup value other than the documented
    # modes.  "default" is mapped to None (the implicit per-context default).
    if args.cleanup is not None:
        if args.cleanup not in ("default", "verbatim", "whitespace",
                                "strip", "scissors"):
            _err(f"fatal: Invalid cleanup mode {args.cleanup}")
            return 128
        if args.cleanup == "default":
            args.cleanup = None
    # parse_force_date(): an unparseable --date value is fatal.
    if args.date is not None and not _force_date_is_valid(args.date):
        _err(f"fatal: invalid date format: {args.date}")
        return 128
    # --fixup=reword:<commit> makes an "only" commit (reuse HEAD's tree); set by
    # the fixup-message construction below.
    args.fixup_reword = False
    args.fixup_prefix = None
    repo = _repo()

    # builtin/commit.c: a --author value without '>' is treated as a nickname,
    # searched case-insensitively over all existing authors. No match is fatal.
    if args.author is not None and ">" not in args.author:
        found = _find_author_by_nickname(repo, args.author)
        if found is None:
            _err(f"fatal: --author '{args.author}' is not 'Name <email>' "
                 "and matches no existing author")
            return 128
        args.author = found

    # commit -p/--patch implies --interactive.  The interactive machinery stages
    # the selected hunks/files into the index, then a normal full-index commit
    # proceeds from there (builtin/commit.c prepare_to_commit's interactive
    # block, which uses a temporary index and commits with COMMIT_NORMAL).
    if args.patch:
        args.interactive = True
    if args.interactive:
        if args.pathspec_from_file is not None:
            _err("fatal: options '--pathspec-from-file' and '--interactive/--patch' cannot be used together")
            return 128
        rc = _commit_interactive(repo, args)
        if rc is not None:
            return rc
        # fall through: the index now holds the selected changes; commit as-is.
        args.pathspec = []
        args.all = False
        args.include = False
    else:
        if args.unified != -1:
            _err("fatal: the option '--unified' requires '--interactive/--patch'")
            return 128
        if args.interhunkcontext != -1:
            _err("fatal: the option '--inter-hunk-context' requires '--interactive/--patch'")
            return 128

    # --pathspec-from-file supplies the pathspec for a partial commit.
    if args.pathspec_from_file is not None:
        raw = (sys.stdin.buffer.read() if args.pathspec_from_file == "-"
               else open(args.pathspec_from_file, "rb").read())
        psep = "\0" if args.pathspec_file_nul else "\n"
        args.pathspec = [p for p in raw.decode("utf-8").split(psep) if p]
    # Message construction. --squash/--fixup set the subject header; -m/-F/-C/-c
    # supply the body (and -C/-c also reuse the source commit's author). C Git
    # appends the body under the squash!/fixup! header. Incompatible combinations
    # (e.g. two body sources, --squash with --fixup) are rejected first.
    conflict = _commit_message_conflict(args)
    if conflict is not None:
        _err(conflict)
        return 128
    if args.reset_author and not (args.amend or args.reuse_message or args.reedit_message):
        _err("fatal: --reset-author can be used only with -C, -c or --amend.")
        return 128
    reuse = args.reuse_message or args.reedit_message
    reuse_author = None
    reuse_sha = None
    body = None
    if args.message is not None:
        body = "\n\n".join(args.message)
    elif args.file is not None:
        body = (sys.stdin.read() if args.file == "-"
                else open(args.file, encoding="utf-8").read())
    elif reuse is not None:
        reuse_sha = refs_mod.rev_parse(repo, reuse)
        rc_commit = objs.parse_commit(objs.read_object(repo, reuse_sha)[1])
        body = rc_commit.message.rstrip("\n")
        reuse_author = rc_commit.author
    header = None
    header_sha = None
    if args.squash is not None:
        header_sha = refs_mod.rev_parse(repo, args.squash)
        subj = objs.parse_commit(objs.read_object(repo, header_sha)[1]).message.splitlines()[0]
        header = f"squash! {subj}"
    elif args.fixup is not None:
        spec = args.fixup
        if ":" in spec:
            mode, ref = spec.split(":", 1)
        else:
            mode, ref = "fixup", spec
        header_sha = refs_mod.rev_parse(repo, ref)
        c = objs.parse_commit(objs.read_object(repo, header_sha)[1])
        subj = _format_subject(c.message)
        if mode in ("amend", "reword"):
            # -m is incompatible with the amend!/reword forms (builtin/commit.c
            # prepare_to_commit: "options '-m' and '--fixup:<mode>' ...").
            if args.message is not None:
                _err(f"fatal: options '-m' and '--fixup:{mode}' cannot be used together")
                return 128
            # prepare_amend_commit(): the amend body is the original commit's %B
            # (raw message), unless that commit is itself an 'amend!' commit, in
            # which case only its %b (body after the subject) is reused so the
            # 'amend!' subject is not duplicated. builtin/commit.c.
            if _format_subject(c.message).startswith("amend!"):
                amend_body = _strip_commit_subject(c.message)
            else:
                amend_body = c.message.rstrip("\n")
            header = f"amend! {subj}\n\n{amend_body}"
            # amend!/reword always allow an empty content change; reword makes an
            # 'only'-style commit (no pathspec) so HEAD's tree is reused and any
            # staged content is left untouched.
            args.allow_empty = True
            args.fixup_prefix = "amend"
            if mode == "reword":
                args.fixup_reword = True
        else:
            header = f"fixup! {subj}"
            args.fixup_prefix = "fixup"
    # When -C/-c reuse the very commit being squashed/fixed up, C Git keeps only
    # the reused body (its subject is already in the squash!/fixup! header).
    if (reuse_sha is not None and header_sha is not None
            and reuse_sha == header_sha and body is not None):
        body = _strip_commit_subject(body)
    if header is not None and body is not None:
        args.message = f"{header}\n\n{body}"
    elif header is not None:
        args.message = header
    else:
        args.message = body
    # commit -t/--template: seed the editor with the template, but only when no
    # other message source applies (prepare_to_commit precedence: -m/-F/-C/-c/
    # --fixup/MERGE_MSG/SQUASH_MSG all win over the template).  When the editor
    # leaves the template intact, the commit aborts ("you did not edit the
    # message").  Errors surfacing the missing file are byte-exact with C Git.
    template_aborted = _commit_apply_template(repo, args)
    if template_aborted is not None:
        return template_aborted
    # builtin/commit.c prepare_to_commit: -i/--include or -o/--only without any
    # pathspec is rejected, except for the amend/allow-empty/--fixup=amend cases
    # where an empty path set is meaningful (reword reuses HEAD's tree).
    if not args.pathspec and (
            args.include
            or (args.only and not args.allow_empty
                and (not args.amend
                     or (args.fixup_prefix is not None
                         and args.fixup_prefix != "amend")))):
        _err("fatal: No paths with --include/--only does not make sense.")
        return 128
    try:
        from . import rerere as _rr
        _rr.scan_and_record(repo)
    except Exception:
        pass

    # --short/--porcelain/--long/-z all imply --dry-run in C Git. Dry-run must not
    # touch the index, so snapshot it before any staging and restore it after.
    dry_mode = (args.dry_run or args.short or args.porcelain or args.long or args.nul)
    idx_file = repo.gitdir / "index"
    dry_snapshot = idx_file.read_bytes() if (dry_mode and idx_file.exists()) else None

    if args.all:
        workdir.add_paths(repo, sorted(workdir.tracked_paths(repo)))
    elif args.include and args.pathspec:
        # -i/--include: stage the named paths, then commit the whole index.
        workdir.add_paths(repo, args.pathspec)

    cur_idx = read_index(repo)
    if cur_idx.has_conflicts():
        _err("error: unresolved conflicts:")
        for p in cur_idx.conflicted_paths():
            _err(f"\t{p}")
        _err("hint: stage the resolved files with `pygit add` then commit again.")
        return 1

    if dry_mode:
        only = not args.all and not args.include and args.pathspec
        if only:
            workdir.add_paths(repo, args.pathspec)
        # builtin/commit.c run_status: --amend compares against HEAD^1 (and is
        # "initial" when amending a root commit). The branch header still names
        # the current branch / HEAD.
        reference = "HEAD^1" if args.amend else "HEAD"
        s = workdir.status(repo, reference=reference)
        hsym, _hsha_real = refs_mod.read_head(repo)
        if args.amend:
            hsha = refs_mod.rev_parse(repo, "HEAD^1")
        else:
            hsha = _hsha_real
        br = hsym[len("refs/heads/"):] if hsym and hsym.startswith("refs/heads/") else None
        ch, unt = _status_model(repo, s)
        rnm = _status_staged_renames(repo, s, reference=reference)
        if rnm:
            consumed = {p for pair in rnm for p in pair}
            ch = [(p, x, y) for p, x, y in ch if p not in consumed]
        show_unt = args.untracked_files != "no"
        had_untracked = bool(unt)
        if not show_unt:
            unt = []
        if dry_snapshot is not None:
            idx_file.write_bytes(dry_snapshot)
        elif idx_file.exists():
            idx_file.unlink()
        staged = [p for p, x, y in ch if x != " "]
        rc = 0 if (staged or rnm) else 1
        # Format selection mirrors C Git: --long (or plain --dry-run) → long;
        # --porcelain → porcelain v1; --short → short; bare -z → porcelain.
        if args.porcelain or (args.nul and not args.short and not args.long):
            fmt = "porcelain"
        elif args.short:
            fmt = "short"
        else:
            fmt = "long"
        if fmt == "long":
            # -v/-vv append the staged (HEAD-vs-index) diff — and, for -vv, the
            # worktree (index-vs-worktree) diff — before the summary line, exactly
            # like wt_longstatus_print_verbose.  In dry-run the output goes to
            # stdout, so no scissors cut line is inserted (s->fp == stdout).
            verbose_hook = None
            if args.verbose:
                verbose_hook = lambda committable: _status_verbose_diff(
                    repo, args.verbose, committable, True, 0)
            _status_long(repo, s, ch, unt, br, hsym, hsha,
                         untracked_hidden=(had_untracked and not show_unt),
                         renames=rnm, verbose_hook=verbose_hook,
                         reference=reference, commit_template=True)
            return rc
        eol = "\0" if args.nul else "\n"
        out = []
        if args.branch:
            out.append(_status_branch_header_short(repo, hsym, hsha))
        entries = [(dst, f"R  {src} -> {dst}") for src, dst in rnm]
        entries += [(p, f"{x}{y} {p}") for p, x, y in ch]
        out += [line for _key, line in sorted(entries)]
        out += [f"?? {p}" for p in unt]
        sys.stdout.write("".join(line + eol for line in out))
        return rc

    head_sym, parent = refs_mod.read_head(repo)
    # A pathspec (or -o/--only) makes a partial commit: HEAD's tree with just the
    # named paths updated from the working tree, leaving the rest of the index out.
    # --fixup=reword: is an "only" commit with no pathspec, so HEAD's tree is
    # reused verbatim (the resulting commit only changes the message).
    only_mode = (not args.all and not args.include
                 and (bool(args.pathspec) or args.fixup_reword))
    if only_mode:
        if args.pathspec:
            workdir.add_paths(repo, args.pathspec)  # refresh named index entries
        tree = _partial_commit_tree(repo, parent, args.pathspec)
    else:
        # Intent-to-add entries are excluded from the commit (treated as
        # not-yet-staged), matching C Git.
        tree = workdir.write_tree(repo, skip_intent_to_add=True)

    if args.amend:
        if parent is None:
            _err("fatal: You have nothing to amend.")
            return 128
        _, pdata = objs.read_object(repo, parent)
        pc = objs.parse_commit(pdata)
        parents = list(pc.parents)
        author_sig = pc.author
        if args.date is not None:
            # --amend --date keeps the original author identity but resets the
            # author date to the supplied value.
            who, _ts, _tz = _split_ident(pc.author)
            fresh = objs.build_signature(repo, "author", date_override=args.date)
            author_sig = who + fresh[fresh.rindex(">") + 1:]
        message = args.message if args.message is not None else pc.message.rstrip("\n")
        compare_tree = None
        if pc.parents:
            _, gpd = objs.read_object(repo, pc.parents[0])
            compare_tree = objs.parse_commit(gpd).tree
        if not args.allow_empty and compare_tree == tree:
            _err("fatal: You asked to amend the most recent commit, but doing so would make")
            _err("it empty. You can repeat your command with --allow-empty, or you can")
            _err('remove the commit entirely with "git reset HEAD^".')
            return 1
    else:
        if args.message is None and not args.allow_empty_message:
            # No message source and (in this non-interactive env) no editor
            # content: builtin/commit.c aborts with the empty-message error.
            _err("Aborting commit due to empty commit message.")
            return 1
        parents = [parent] if parent else []
        # -C/-c reuse the source commit's author identity *and* date; --date
        # overrides just the date, --author/--reset-author override identity below.
        if reuse_author is not None and args.date is None:
            author_sig = reuse_author
        elif reuse_author is not None:
            who, _ts, _tz = _split_ident(reuse_author)
            fresh = objs.build_signature(repo, "author", date_override=args.date)
            author_sig = who + fresh[fresh.rindex(">") + 1:]
        else:
            author_sig = objs.build_signature(repo, "author", date_override=args.date)
        # With --allow-empty-message and no message source the message is empty.
        message = args.message if args.message is not None else ""
        if parent and not args.allow_empty:
            _, pdata = objs.read_object(repo, parent)
            if objs.parse_commit(pdata).tree == tree:
                return _commit_status_report(repo)
        empty_tree_sha, _ = objs.hash_bytes("tree", b"", repo)
        if parent is None and not args.allow_empty and tree == empty_tree_sha:
            return _commit_status_report(repo)

    committer_sig = objs.build_signature(repo, "committer")
    # --author overrides the author identity (date stays from env/--date);
    # --reset-author (with --amend) resets it to the current committer identity.
    if args.author is not None:
        base = objs.build_signature(repo, "author", date_override=args.date)
        author_sig = args.author + base[base.rindex(">") + 1:]
    elif args.reset_author:
        author_sig = objs.build_signature(repo, "author", date_override=args.date)
    # Message cleanup (default 'whitespace' for -m/-F; 'verbatim' keeps as-is),
    # then any --signoff / --trailer trailers.  'strip' additionally drops
    # comment lines (lines starting with core.commentChar, default '#').
    comment_prefix = "#"
    if args.cleanup == "strip":
        try:
            from . import gitconfig
            cc = gitconfig.get(repo, "core.commentChar")
            if cc and cc != "auto":
                comment_prefix = cc
        except Exception:
            pass
    message = _cleanup_commit_message(message, args.cleanup, comment_prefix)
    trailers: list[str] = []
    if args.signoff:
        cwho, _t, _z = _split_ident(committer_sig)
        cn, ce = _parse_who(cwho)
        trailers.append(f"Signed-off-by: {cn} <{ce}>")
    trailers.extend(_normalize_cmdline_trailer(t) for t in (args.trailer or []))
    message = _apply_trailers(message, trailers)
    if (not message.strip()) and not args.allow_empty_message:
        _err("Aborting commit due to empty commit message.")
        return 1
    # An allowed-empty message stays empty (the commit object ends "...\n\n");
    # a non-empty message is given a single trailing newline.
    if message == "":
        msg = ""
    else:
        msg = message if message.endswith("\n") else message + "\n"
    c = objs.Commit(tree=tree, parents=parents, author=author_sig, committer=committer_sig, message=msg)
    commit_bytes = c.encode()
    # GPG signing: -S/--gpg-sign[=keyid] or commit.gpgsign=true, unless
    # --no-gpg-sign.  Sign the commit payload and fold the signature into a
    # gpgsig header.  On gpg failure git aborts before writing the object.
    sign_commit = _resolve_sign_commit(repo, args)
    if sign_commit is not None:
        from . import gpgsign
        signing_key = (sign_commit if sign_commit
                       else gpgsign.get_signing_key(repo, _ident_no_date(committer_sig)))
        sig, errmsg = gpgsign.sign_buffer(repo, commit_bytes, signing_key)
        if sig is None:
            _error(errmsg)
            _err("fatal: failed to write commit object")
            return 128
        commit_bytes = gpgsign.add_header_signature(commit_bytes, sig)
    sha = objs.write_object(repo, "commit", commit_bytes)
    verb = "commit (amend)" if args.amend else ("commit (initial)" if not parents else "commit")
    reflog_msg = f"{verb}: {_format_subject(msg)}"
    if head_sym:
        refs_mod.update_ref(repo, head_sym, sha, message=reflog_msg)
    else:
        refs_mod.set_head(repo, sha)
    if args.quiet:
        return 0
    branch = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else "detached HEAD"
    root = " (root-commit)" if not parents and not args.amend else ""
    _print(f"[{branch}{root} {sha[:7]}] {_format_subject(msg)}")
    # git prints " Author:" when the author identity differs from the committer,
    # and " Date:" when the author date differs from the committer date.
    a_who, a_ts, _atz = _split_ident(author_sig)
    c_who, c_ts, _ctz = _split_ident(committer_sig)
    if a_who != c_who:
        _print(f" Author: {a_who}")
    # Mirrors C Git's author_date_is_interesting() == author_message || force_date:
    # the " Date:" line shows when the author identity was reused from another
    # commit (--amend / -C / -c) or set via --date, not on a fresh default and
    # not when --reset-author discards the reused identity.
    date_interesting = (
        args.date is not None
        or ((args.amend or reuse_author is not None) and not args.reset_author)
    )
    if date_interesting:
        _print(f" Date: {_format_ident_date(author_sig)}")
    parent_tree = None
    if parents:
        _, pdata = objs.read_object(repo, parents[0])
        parent_tree = objs.parse_commit(pdata).tree
    _print_commit_summary(repo, parent_tree, tree)
    return 0


def _blob_lines(repo: Repository, sha: str) -> list[str]:
    try:
        _, data = objs.read_object(repo, sha)
    except KeyError:
        return []
    return data.decode("utf-8", errors="replace").splitlines()


def _print_commit_summary(repo: Repository, parent_tree: Optional[str], new_tree: str) -> None:
    files = insertions = deletions = 0
    mode_lines: list[tuple[str, str]] = []
    for path, a, b in workdir.iter_tree_changes(repo, parent_tree, new_tree):
        files += 1
        old_lines = _blob_lines(repo, a.sha) if a is not None else []
        new_lines = _blob_lines(repo, b.sha) if b is not None else []
        for op in diff_mod.diff_lines(old_lines, new_lines):
            if op[0] == "ins":
                insertions += 1
            elif op[0] == "del":
                deletions += 1
        if a is None and b is not None:
            mode_lines.append((path, f" create mode {b.mode.zfill(6)} {path}"))
        elif b is None and a is not None:
            mode_lines.append((path, f" delete mode {a.mode.zfill(6)} {path}"))
    if files == 0:
        return
    _print(_stat_summary_line(files, insertions, deletions))
    for _, line in sorted(mode_lines):
        _print(line)


def _parse_who(who: str) -> tuple[str, str]:
    if who.endswith(">") and " <" in who:
        name, email = who[:-1].split(" <", 1)
        return name, email
    return who, ""


def _note_text(repo: Repository, sha: str) -> str:
    """Return the notes blob text attached to commit ``sha`` (refs/notes/commits),
    or '' if none."""
    nref = refs_mod.read_ref(repo, "refs/notes/commits")
    if not nref:
        return ""
    try:
        nc = objs.parse_commit(objs.read_object(repo, nref)[1])
    except KeyError:
        return ""
    for path, _m, bsha in workdir.iter_tree_files(repo, nc.tree):
        if path.replace("/", "") == sha:
            return objs.read_object(repo, bsha)[1].decode("utf-8", "replace")
    return ""


def _pad_column(text: str, spec) -> str:
    """Apply a git pretty-format column spec (align, width, trunc) to text.
    Text wider than width is left untouched unless a truncation mode is set
    (trunc=right with '..', ltrunc=left, mtrunc=middle)."""
    align, width, trunc = spec
    n = len(text)
    if n > width:
        if not trunc:
            return text
        if width <= 2:
            return text[:width]
        if trunc == "ltrunc":
            return ".." + text[n - (width - 2):]
        if trunc == "mtrunc":
            keep = width - 2
            start = keep // 2
            end = keep - start
            return text[:start] + ".." + (text[n - end:] if end else "")
        return text[:width - 2] + ".."
    pad = width - n
    if align == "right":
        return " " * pad + text
    if align == "center":
        left = pad // 2
        return " " * left + text + " " * (pad - left)
    return text + " " * pad


def _gpg_format_placeholders(repo: Repository, sha: str, fmt: str
                            ) -> "list[tuple[str, str]]":
    """Expand the %G* signature placeholders (pretty.c).  Returns (token, value)
    pairs.  When no %G token is present the commit is never read/verified and
    every placeholder expands to empty (matching git's lazy behavior)."""
    empty = [("%GG", ""), ("%GS", ""), ("%GK", ""), ("%GP", ""),
             ("%GF", ""), ("%GT", ""), ("%G?", "")]
    if "%G" not in fmt:
        return empty
    from . import gpgsign
    try:
        _t, data = objs.read_object(repo, sha)
    except KeyError:
        return empty
    fields = gpgsign.check_commit_signature_full(repo, data)
    result = fields["result"]
    # %G? : 'G' good (unless trust UNDEFINED/NEVER -> 'U'); B/E/N/X/Y/R verbatim.
    if result == "G":
        gq = "U" if fields["trust_level"] in (0, 1) else "G"
    elif result in ("B", "E", "N", "X", "Y", "R"):
        gq = result
    else:
        gq = ""
    # %GT : trust level name, but only meaningful once a signature was checked.
    gt = fields["trust_name"] if result != "N" else "undefined"
    return [
        ("%GG", fields["output"]),
        ("%GS", fields["signer"]),
        ("%GK", fields["key"]),
        ("%GP", fields["primary_key_fingerprint"]),
        ("%GF", fields["fingerprint"]),
        ("%GT", gt),
        ("%G?", gq),
    ]


_TRAILER_SEPARATORS = ":"
_GIT_GENERATED_PREFIXES = ("Signed-off-by: ", "(cherry picked from commit ")


def _trailer_is_blank(line: str) -> bool:
    """Port of trailer.c:is_blank_line — true if the line is empty or all
    whitespace up to the (excluded) newline."""
    return line.strip(" \t\r\v\f") == ""


def _trailer_find_separator(line: str, separators: str) -> int:
    """Port of trailer.c:find_separator. Returns the separator index, 0 if the
    line begins with a separator, or -1 if not a well-formed trailer line."""
    whitespace_found = False
    for i, ch in enumerate(line):
        if ch in separators:
            return i
        if not whitespace_found and (ch.isalnum() or ch == "-"):
            continue
        if i != 0 and ch in (" ", "\t"):
            whitespace_found = True
            continue
        break
    return -1


def _trailer_block_start(lines: list[str]) -> int:
    """Port of trailer.c:find_trailer_block_start. ``lines`` are the message
    lines (no trailing newline). Returns the index of the first trailer line, or
    len(lines) if there is no trailer block."""
    n = len(lines)
    # The first paragraph is the title and cannot be trailers.
    end_of_title = 0
    while end_of_title < n:
        if _trailer_is_blank(lines[end_of_title]):
            break
        end_of_title += 1
    only_spaces = True
    recognized_prefix = False
    trailer_lines = 0
    non_trailer_lines = 0
    possible_continuation_lines = 0
    l = n - 1
    while l >= end_of_title:
        bol = lines[l]
        if _trailer_is_blank(bol):
            if only_spaces:
                l -= 1
                continue
            non_trailer_lines += possible_continuation_lines
            if recognized_prefix and trailer_lines * 3 >= non_trailer_lines:
                return l + 1
            if trailer_lines and not non_trailer_lines:
                return l + 1
            return n
        only_spaces = False
        matched_prefix = False
        for p in _GIT_GENERATED_PREFIXES:
            if bol.startswith(p):
                trailer_lines += 1
                possible_continuation_lines = 0
                recognized_prefix = True
                matched_prefix = True
                break
        if matched_prefix:
            l -= 1
            continue
        sep = _trailer_find_separator(bol, _TRAILER_SEPARATORS)
        if sep >= 1 and not (bol[0:1].isspace()):
            trailer_lines += 1
            possible_continuation_lines = 0
            # No configured trailer keys in the hermetic env, so this never sets
            # recognized_prefix; the 25%-and-git-generated rule still applies.
        elif bol[0:1].isspace():
            possible_continuation_lines += 1
        else:
            non_trailer_lines += 1
            non_trailer_lines += possible_continuation_lines
            possible_continuation_lines = 0
        l -= 1
    return n


def _trailer_unfold(val: str) -> str:
    """Port of trailer.c:unfold_value — collapse folded continuation lines."""
    out = []
    i = 0
    n = len(val)
    while i < n:
        c = val[i]
        i += 1
        if c == "\n":
            while i < n and val[i] in " \t\r\v\f\n":
                i += 1
            out.append(" ")
        else:
            out.append(c)
    return "".join(out).strip()


def _format_trailers(message: str, arg: str) -> str:
    """Port of pretty.c %(trailers[:opts]) / trailer.c:format_trailers_from_commit.

    ``message`` is the full commit message; ``arg`` is the text after
    ``%(trailers`` up to the closing paren (e.g. ":only,key=Reviewed-by").
    """
    # Parse options.
    only_trailers = False
    unfold = False
    key_only = False
    value_only = False
    separator = None        # None => default "\n" terminator per item
    key_value_separator = None
    filters: list[str] = []
    if arg:
        # arg starts with ':'
        spec = arg[1:] if arg.startswith(":") else arg
        for opt in _split_trailer_opts(spec):
            k, eq, v = opt.partition("=")
            if k == "key":
                key = v
                if key.endswith(":"):
                    key = key[:-1]
                filters.append(key)
                only_trailers = True
            elif k == "separator":
                separator = _expand_trailer_arg(v)
            elif k == "key_value_separator":
                key_value_separator = _expand_trailer_arg(v)
            elif k == "only":
                only_trailers = _trailer_bool(v)
            elif k == "unfold":
                unfold = _trailer_bool(v)
            elif k == "keyonly":
                key_only = _trailer_bool(v)
            elif k == "valueonly":
                value_only = _trailer_bool(v)

    lines = message.split("\n")
    # message commonly ends with "\n" producing a trailing "" element; the C
    # code operates on the buffer up to end_of_log_message. We mirror by keeping
    # lines as-is (blank trailing line acts like is_blank_line).
    start = _trailer_block_start(lines)
    block = lines[start:]

    # Fast path: whole block untouched.
    if (not only_trailers and not unfold and not filters and separator is None
            and not key_only and not value_only and key_value_separator is None):
        # Reconstruct the raw block bytes from start..end (end is the end of log
        # message). Each line plus its newline.
        out = "\n".join(block)
        # The raw block in git includes the trailing newline of each line; our
        # split dropped them. Re-add a trailing newline if the block is
        # non-empty (git's block ends right at end_of_log_message).
        if block and any(ln for ln in block):
            if not out.endswith("\n"):
                out += "\n"
            return out
        return out

    # Parse the block into (tok, val) items, joining folded continuations.
    raw_trailers: list[str] = []
    for ln in block:
        if raw_trailers and ln[0:1].isspace():
            raw_trailers[-1] = raw_trailers[-1] + "\n" + ln
        elif ln == "" and (not raw_trailers):
            continue
        else:
            # Skip a trailing empty line produced by the final newline.
            if ln == "":
                continue
            raw_trailers.append(ln)

    items: list[tuple[Optional[str], str]] = []
    for trailer in raw_trailers:
        sep = _trailer_find_separator(trailer, _TRAILER_SEPARATORS)
        if sep >= 1:
            tok = trailer[:sep].strip()
            val = trailer[sep + 1:].strip()
            if unfold:
                val = _trailer_unfold(val)
            items.append((tok, val))
        elif not only_trailers:
            val = trailer
            if val.endswith("\n"):
                val = val[:-1]
            items.append((None, val))

    out_parts: list[str] = []
    for tok, val in items:
        if tok is not None:
            if not (not filters or tok in filters):
                continue
            if separator is not None and out_parts:
                out_parts.append(separator)
            piece = ""
            if not value_only:
                piece += tok
            if not key_only and not value_only:
                if key_value_separator is not None:
                    piece += key_value_separator
                else:
                    last_char = tok.rstrip()[-1:] if tok.rstrip() else ""
                    if last_char and last_char not in _TRAILER_SEPARATORS:
                        piece += _TRAILER_SEPARATORS[0] + " "
            if not key_only:
                piece += val
            out_parts.append(piece)
            if separator is None:
                out_parts.append("\n")
        elif not only_trailers:
            if separator is not None and out_parts:
                out_parts.append(separator)
            out_parts.append(val)
            if separator is not None:
                # strbuf_rtrim
                joined = "".join(out_parts).rstrip()
                out_parts = [joined]
            else:
                out_parts.append("\n")
    return "".join(out_parts)


def _split_trailer_opts(spec: str) -> list[str]:
    """Split a trailers option spec on commas, respecting that separator values
    may contain expansions but not bare commas (git uses strcspn up to ',)')."""
    return [s for s in spec.split(",") if s != ""] if spec else []


def _trailer_bool(v: str) -> bool:
    """match_placeholder_bool_arg: bare option is true; '=true'/'=false' set it."""
    if v == "":
        return True
    return v.lower() in ("true", "1", "yes", "on")


def _expand_trailer_arg(v: str) -> str:
    """Expand %x?? / %n escapes in a trailers option value (pretty.c
    expand_string_arg via strbuf_expand_step minimal subset)."""
    import re as _re
    v = v.replace("%n", "\n")
    v = _re.sub(r"%x([0-9a-fA-F]{2})", lambda m: chr(int(m.group(1), 16)), v)
    return v


_FORMATTING_LIMIT = 16 * 1024


def _strbuf_add_wrapped_text(text: str, indent1: int, indent2: int, width: int) -> str:
    """Port of utf8.c strbuf_add_wrapped_text (ASCII-width subset): wrap ``text``
    to ``width`` columns, indenting the first line by ``indent1`` and subsequent
    lines by ``indent2``. ``width <= 0`` only indents (no wrapping)."""
    if width <= 0:
        # strbuf_add_indented_text: prefix each line with the indent.
        out: list[str] = []
        first = True
        for line in text.split("\n"):
            ind = indent1 if first else indent2
            first = False
            out.append((" " * ind + line) if line else line)
        return "\n".join(out)
    buf: list[str] = []
    i = 0
    n = len(text)
    bol = 0
    w = indent = indent1
    space = -1
    if indent < 0:
        w = -indent
        space = 0
    while True:
        c = text[i] if i < n else ""
        if c == "" or c.isspace():
            if w <= width or space < 0:
                start = bol
                if c == "" and i == start:
                    return "".join(buf)
                if space >= 0:
                    start = space
                else:
                    buf.append(" " * indent)
                buf.append(text[start:i])
                if c == "":
                    return "".join(buf)
                space = i
                if c == "\t":
                    w |= 0x07
                elif c == "\n":
                    space += 1
                    nxt = text[space] if space < n else ""
                    if nxt == "\n":
                        buf.append("\n")
                        # goto new_line
                        buf.append("\n")
                        i = bol = space + (1 if (space < n and text[space].isspace()) else 0)
                        space = -1
                        w = indent = indent2
                        continue
                    elif not nxt.isalnum():
                        buf.append("\n")
                        i = bol = space + (1 if (space < n and text[space].isspace()) else 0)
                        space = -1
                        w = indent = indent2
                        continue
                    else:
                        buf.append(" ")
                w += 1
                i += 1
            else:
                buf.append("\n")
                i = bol = space + (1 if (space < n and text[space].isspace()) else 0)
                space = -1
                w = indent = indent2
            continue
        w += 1
        i += 1


def _git_describe_capture(repo: Repository, sha: str, extra_args: list[str]) -> str:
    """Run the equivalent of ``git describe [extra_args] <sha>`` and return its
    rtrimmed stdout (empty on failure), for the %(describe) pretty atom."""
    argv = list(extra_args) + [sha]
    buf = _capture_output(lambda: cmd_describe(argv))
    return buf.rstrip("\n")


def _parse_describe_args(arg: str) -> tuple[list[str], int]:
    """Port of pretty.c parse_describe_args: read comma-separated describe
    options from ``arg`` (which begins right after ``%(describe:``). Returns
    (cli_args, consumed) where consumed is the byte count up to (not including)
    the closing ')'."""
    # Supported keys mirror pretty.c's describe_args[] table.
    bool_opts = {"tags": "--tags", "all": "--all", "long": "--long"}
    val_opts = {"abbrev": "--abbrev", "match": "--match", "exclude": "--exclude"}
    out: list[str] = []
    i = 0
    n = len(arg)
    while i < n and arg[i] != ")":
        # token up to ',' or ')'
        j = i
        while j < n and arg[j] not in ",)":
            j += 1
        token = arg[i:j]
        key, eq, val = token.partition("=")
        if not eq and key in bool_opts:
            out.append(bool_opts[key])
        elif eq and key in val_opts:
            out.append(f"{val_opts[key]}={val}")
        elif eq and key in bool_opts:
            # boolean given a value
            if val.lower() in ("true", "1", "yes", "on", ""):
                out.append(bool_opts[key])
        # unknown tokens: pretty.c errors; we just skip to stay robust.
        i = j
        if i < n and arg[i] == ",":
            i += 1
    return out, i


def _strip_color_placeholders(s: str) -> str:
    """Resolve pretty %C color placeholders to the empty string (no-color mode),
    matching pretty.c parse_color/`%C(auto)` when want_color is false. Unknown
    %C<text> sequences are left literal (parse_color returns 0)."""
    import re as _re
    # %C(...) — any parenthesized form expands to "" in no-color mode.
    s = _re.sub(r"%C\([^)]*\)", "", s)
    # %Cred / %Cgreen / %Cblue / %Creset (the only paren-less basic colors).
    s = _re.sub(r"%C(red|green|blue|reset)", "", s)
    return s
def _format_sanitized_subject(msg: str) -> str:
    """Port of pretty.c:format_sanitized_subject (the %f slug).

    Title chars are [a-zA-Z0-9._]. Each run of one or more non-title chars
    collapses to a single '-' (but never a leading one). Consecutive '.' are
    collapsed to a single '.'. Trailing '.'/'-' are trimmed.
    """
    # C operates byte-by-byte (istitlechar on a `char`); a non-ASCII multibyte
    # sequence is a run of non-title bytes, so encode to UTF-8 and walk bytes.
    raw = msg.encode("utf-8", "surrogateescape")
    out = bytearray()
    # space==2 at start suppresses a leading '-'; space|=1 marks a pending
    # separator; space==1 emits '-' before the next title char.
    space = 2
    i = 0
    n = len(raw)
    DOT = 0x2E
    UND = 0x5F
    while i < n:
        b = raw[i]
        title = (0x61 <= b <= 0x7A) or (0x41 <= b <= 0x5A) or (0x30 <= b <= 0x39) or b == DOT or b == UND
        if title:
            if space == 1:
                out.append(0x2D)  # '-'
            space = 0
            out.append(b)
            if b == DOT:
                while i + 1 < n and raw[i + 1] == DOT:
                    i += 1
        else:
            space |= 1
        i += 1
    # Trim any trailing '.' or '-'.
    end = len(out)
    while end > 0 and out[end - 1] in (DOT, 0x2D):
        end -= 1
    return out[:end].decode("utf-8", "surrogateescape")


def _expand_commit_format(repo: Repository, sha: str, c, fmt: str, decorations: dict,
                          date_mode: str = "default", abbrev: int = 7,
                          reflog=None, date_given: bool = False) -> str:
    a_who, a_ts, a_tz = _split_ident(c.author)
    c_who, c_ts, c_tz = _split_ident(c.committer)
    an, ae = _parse_who(a_who)
    cn, ce = _parse_who(c_who)
    # %aN/%aE/%cN/%cE are always mailmap-resolved (independent of --use-mailmap,
    # which only governs the builtin-format identity lines). %an/%ae stay raw.
    man, mae, mcn, mce = an, ae, cn, ce
    if any(k in fmt for k in ("%aN", "%aE", "%cN", "%cE")):
        from . import mailmap as _mailmap
        mm = _mailmap.load(repo)
        if not mm.empty:
            man, mae = mm.resolve(an, ae)
            mcn, mce = mm.resolve(cn, ce)
    # The subject (%s) is the first line with trailing whitespace stripped.
    subject = c.message.splitlines()[0].rstrip() if c.message.strip() else ""
    # %B is the raw message; %b is the body after the subject's blank line; %f
    # is the subject sanitized into a path-safe slug.
    import re as _re
    raw_body = c.message
    _parts = c.message.split("\n\n", 1)
    body = _parts[1] if len(_parts) > 1 else ""
    sanitized = _format_sanitized_subject(subject)
    deco_names = decorations.get(sha, [])
    deco = _format_decoration(deco_names)
    deco_d = ", ".join(deco_names)
    # Longer tokens must precede their prefixes (e.g. %ad before %a*) so a
    # str.replace pass does not consume the prefix first.
    replacements = [
        ("%H", sha), ("%h", sha[:abbrev]),
        ("%T", c.tree), ("%t", c.tree[:abbrev]),
        ("%P", " ".join(c.parents)), ("%p", " ".join(p[:abbrev] for p in c.parents)),
        ("%an", an), ("%ae", ae), ("%cn", cn), ("%ce", ce),
        # Mailmap-resolved name/email; with no mailmap these equal %an/%ae/etc.
        ("%aN", man), ("%aE", mae), ("%cN", mcn), ("%cE", mce),
        # Date placeholders: %ad/%cd honor --date; %aD/%ai/%aI (and committer
        # equivalents) are fixed styles; %at/%ct are the raw unix timestamps.
        ("%aD", _format_date(c.author, "rfc")), ("%cD", _format_date(c.committer, "rfc")),
        ("%aI", _format_date(c.author, "iso-strict")), ("%cI", _format_date(c.committer, "iso-strict")),
        ("%ai", _format_date(c.author, "iso")), ("%ci", _format_date(c.committer, "iso")),
        ("%ad", _format_date(c.author, date_mode)), ("%cd", _format_date(c.committer, date_mode)),
        ("%ar", _format_date(c.author, "relative")), ("%cr", _format_date(c.committer, "relative")),
        ("%as", _format_date(c.author, "short")), ("%cs", _format_date(c.committer, "short")),
        ("%ah", _format_date(c.author, "human")), ("%ch", _format_date(c.committer, "human")),
        ("%at", str(a_ts) if a_ts is not None else ""), ("%ct", str(c_ts) if c_ts is not None else ""),
        ("%B", raw_body), ("%b", body), ("%f", sanitized),
        # %e (encoding) is empty for unencoded commits; %N is the commit's note.
        ("%e", ""),
        ("%N", _note_text(repo, sha) if "%N" in fmt else ""),
        # Signature placeholders (%G*): lazily verify the commit's gpgsig like
        # C Git (only when a %G token is present), per pretty.c.
        *_gpg_format_placeholders(repo, sha, fmt),
        ("%s", subject), ("%D", deco_d), ("%d", deco),
        # %m is the left/right/boundary mark; without --left-right it is ">".
        ("%m", ">"),
        ("%n", "\n"), ("%%", "%"),
    ]
    # Reflog placeholders (only meaningful under `log -g`): %gD/%gd selector
    # (full/short ref), %gs subject, %gn/%ge identity name/email. They expand to
    # empty when not walking reflogs, matching git.
    if reflog is not None:
        gd = _reflog_selector(reflog, full=False, date_mode=date_mode, date_given=date_given)
        gD = _reflog_selector(reflog, full=True, date_mode=date_mode, date_given=date_given)
        gn, ge = _parse_who(_reflog_who(reflog["ident"]))
        replacements[:0] = [("%gD", gD), ("%gd", gd), ("%gs", reflog["msg"]),
                            ("%gn", gn), ("%ge", ge)]
    else:
        replacements[:0] = [("%gD", ""), ("%gd", ""), ("%gs", ""), ("%gn", ""), ("%ge", "")]
    def _decorate_atom(spec: str) -> str:
        # %(decorate) / %(decorate:prefix=..,suffix=..,separator=..,...)
        prefix, suffix, sep = " (", ")", ", "
        tag = pointer = ""
        if spec.startswith("decorate:"):
            for opt in spec[len("decorate:"):].split(","):
                k, _, v = opt.partition("=")
                if k == "prefix":
                    prefix = v
                elif k == "suffix":
                    suffix = v
                elif k == "separator":
                    sep = v
                elif k == "tag":
                    tag = v
                elif k == "pointer":
                    pointer = v
        if not deco_names:
            return ""
        names = list(deco_names)
        if pointer:
            names = [n.replace(" -> ", pointer) for n in names]
        if tag:
            names = [tag + n[len("tag: "):] if n.startswith("tag: ") else n for n in names]
        return prefix + sep.join(names) + suffix

    def expand_seg(s: str) -> str:
        # %(trailers[:opts]) expands the commit's trailer block. Handle before
        # %xHH so a %x?? inside a separator= value isn't expanded twice.
        s = _re.sub(r"%\(trailers(:[^)]*)?\)",
                    lambda m: _format_trailers(c.message, m.group(1) or ""), s)
        # %(describe[:opts]) runs git-describe on the commit (pretty.c).
        def _describe_sub(m):
            opts = m.group(1) or ""
            extra, _consumed = _parse_describe_args(opts[1:]) if opts.startswith(":") else ([], 0)
            return _git_describe_capture(repo, sha, extra)
        s = _re.sub(r"%\(describe(:[^)]*)?\)", _describe_sub, s)
        # %C(...) / %Cred / %Creset color placeholders -> "" in no-color mode.
        s = _strip_color_placeholders(s)
        # %xHH expands to the literal byte (e.g. %x09 -> tab) before field tokens.
        s = _re.sub(r"%x([0-9a-fA-F]{2})", lambda m: chr(int(m.group(1), 16)), s)
        s = _re.sub(r"%\((decorate(?::[^)]*)?)\)", lambda m: _decorate_atom(m.group(1)), s)
        for token, value in replacements:
            s = s.replace(token, value)
        return s

    # Column padding/truncation: %<(N[,trunc]) left-align, %>(N) right-align,
    # %><(N) center. The spec pads the text from the marker through the next
    # single placeholder, then is flushed (git pads nothing if no placeholder
    # follows before the format ends).
    col_re = _re.compile(r"%(<\(|>\(|><\(|>>\()(\d+)(?:,(trunc|ltrunc|mtrunc))?\)")

    tok_sorted = sorted({t for t, _ in replacements}, key=len, reverse=True)

    def _first_ph(s: str, start: int):
        # Return (placeholder_start, placeholder_end) of the next %-placeholder,
        # matching the longest known token (so %an/%ad/%G? aren't split).
        j = s.find("%", start)
        if j < 0:
            return None
        if s[j:j + 2] == "%(":
            k = s.find(")", j)
            return (j, k + 1 if k >= 0 else len(s))
        if s[j:j + 2] == "%x":
            return (j, j + 4)
        for tok in tok_sorted:
            if s.startswith(tok, j):
                return (j, j + len(tok))
        return (j, j + 2)

    def _expand_with_cols(seg_fmt: str) -> str:
        if col_re.search(seg_fmt):
            out_parts: list[str] = []
            i = 0
            while i < len(seg_fmt):
                m = col_re.match(seg_fmt, i)
                if m:
                    kind = m.group(1)
                    align = {"<(": "left", ">(": "right", "><(": "center", ">>(": "right"}[kind]
                    spec = (align, int(m.group(2)), m.group(3))
                    i = m.end()
                    ph = _first_ph(seg_fmt, i)
                    if ph is None:
                        out_parts.append(expand_seg(seg_fmt[i:]))
                        break
                    ph_start, ph_end = ph
                    # Literals between the marker and the placeholder are emitted
                    # unpadded; only the placeholder's output is padded to width.
                    if ph_start > i:
                        out_parts.append(expand_seg(seg_fmt[i:ph_start]))
                    out_parts.append(_pad_column(expand_seg(seg_fmt[ph_start:ph_end]), spec))
                    i = ph_end
                else:
                    nm = col_re.search(seg_fmt, i)
                    end = nm.start() if nm else len(seg_fmt)
                    out_parts.append(expand_seg(seg_fmt[i:end]))
                    i = end
            return "".join(out_parts)
        return expand_seg(seg_fmt)

    # %w(width,indent1,indent2) sets line-wrapping for the text that follows,
    # rewrapping the buffer tail when the next %w (or end of format) is reached
    # (pretty.c rewrap_message_tail). Split the format on %w markers and wrap
    # each accumulated tail with the params from its preceding marker.
    w_re = _re.compile(r"%w\((\d+)(?:,(\d+)(?:,(\d+))?)?\)")
    if w_re.search(fmt):
        result = ""              # the rendered buffer
        wrap_start = 0           # offset in result where the active region starts
        width = ind1 = ind2 = 0  # active wrap params (0,0,0 = no wrapping)
        pos = 0
        for m in w_re.finditer(fmt):
            seg = fmt[pos:m.start()]
            result += _expand_with_cols(seg)
            new_w = int(m.group(1))
            new_i1 = int(m.group(2)) if m.group(2) is not None else 0
            new_i2 = int(m.group(3)) if m.group(3) is not None else 0
            # %w with any param over FORMATTING_LIMIT is treated as a literal
            # (parse returns 0): emit the marker text verbatim and keep params.
            if (new_w > _FORMATTING_LIMIT or new_i1 > _FORMATTING_LIMIT
                    or new_i2 > _FORMATTING_LIMIT):
                result += _expand_with_cols(m.group(0))
                pos = m.end()
                continue
            if not (width == new_w and ind1 == new_i1 and ind2 == new_i2):
                if wrap_start < len(result):
                    head = result[:wrap_start]
                    tail = _strbuf_add_wrapped_text(result[wrap_start:], ind1, ind2, width)
                    result = head + tail
                wrap_start = len(result)
                width, ind1, ind2 = new_w, new_i1, new_i2
            pos = m.end()
        result += _expand_with_cols(fmt[pos:])
        # Final rewrap to (0,0,0): wrap the last active region.
        if not (width == 0 and ind1 == 0 and ind2 == 0) and wrap_start < len(result):
            head = result[:wrap_start]
            tail = _strbuf_add_wrapped_text(result[wrap_start:], ind1, ind2, width)
            result = head + tail
        return result
    return _expand_with_cols(fmt)


def _line_log_file_header(path: str, parent_path: str, a_text: str, b_text: str,
                          a_sha: Optional[str], b_sha: Optional[str],
                          a_present: bool, b_mode: str) -> list[str]:
    """The ``diff --git`` / mode / ``index`` / ``---``+``+++`` header lines for a
    line-log file pair, matching git's builtin_diff for the line-range case."""
    out: list[str] = []
    out.append(f"diff --git a/{parent_path} b/{path}")
    a_abbrev = (a_sha or "0" * 40)[:7]
    b_abbrev = (b_sha or "0" * 40)[:7]
    if not a_present:
        out.append(f"new file mode {b_mode}")
        out.append(f"index {a_abbrev}..{b_abbrev}")
        out.append("--- /dev/null")
        out.append(f"+++ b/{path}")
    else:
        out.append(f"index {a_abbrev}..{b_abbrev} {b_mode}")
        out.append(f"--- a/{parent_path}")
        out.append(f"+++ b/{path}")
    return out


def _run_line_log(repo: Repository, args, mode: str) -> int:
    """Drive ``git log -L`` / ``git show -L`` (line-level history).

    ``mode`` is "log" (walk ancestry) or "show" (no-walk: render only the start
    commit, with the in-range lines shown as a new-file diff).
    """
    from . import linelog as _ll

    # The single starting commit.  Both log and show dig from exactly one commit.
    start_rev = None
    if mode == "log":
        non_dd = [t for t in args.pos if t != "--"]
        revs = [t for t in non_dd]
        start_rev = revs[0] if revs else "HEAD"
    else:
        revs = args.rev or ["HEAD"]
        if len(revs) > 1:
            # git: "More than one commit to dig from: <b> and <a>?"
            _err(f"fatal: More than one commit to dig from: {revs[1]} and {revs[0]}?")
            return 128
        start_rev = revs[0]

    start_sha = refs_mod.rev_parse(repo, start_rev + "^{commit}") \
        or refs_mod.rev_parse(repo, start_rev)
    if not start_sha:
        head_sym, _ = refs_mod.read_head(repo)
        if start_rev == "HEAD" and head_sym and head_sym.startswith("refs/heads/"):
            branch = head_sym[len("refs/heads/"):]
            _err(f"fatal: your current branch '{branch}' does not have any commits yet")
            return 128
        _err(f"fatal: ambiguous argument '{start_rev}': unknown revision or path not in the working tree.")
        _err("Use '--' to separate paths from revisions, like this:")
        _err("'git <command> [<revision>...] -- [<file>...]'")
        return 128

    info = _commit_tree_parents(repo, start_sha)
    if info is None:
        _err(f"fatal: ambiguous argument '{start_rev}': unknown revision or path not in the working tree.")
        return 128
    start_tree = info[0]

    def _read_path_text(tree: str, path: str) -> Optional[str]:
        e = workdir.tree_path_entry(repo, tree, path)
        if e is None:
            return None
        if e.is_dir() or e.is_gitlink():
            # git: get_tree_entry succeeds, then diff_populate_filespec fails to
            # read the (tree/gitlink) object as a blob.
            raise _ll.LParseError(f"Cannot read blob {e.sha}")
        return objs.read_object(repo, e.sha)[1].decode("utf-8", errors="replace")

    try:
        ranges0 = _ll.parse_args(repo, start_tree, args.line_ranges, _read_path_text)
    except _ll.LParseError as exc:
        _err("fatal: " + str(exc))
        return 128

    # Output format determination (shared with cmd_log / cmd_show).
    fmt_string: Optional[str] = None
    style = "medium"
    fmt_terminator = True
    pretty = getattr(args, "pretty", None)
    fmt_attr = getattr(args, "format", None)
    if fmt_attr in ("oneline", "short", "medium", "full", "fuller", "raw", "reference"):
        pretty, fmt_attr = fmt_attr, None
    if fmt_attr is not None:
        fmt_string = fmt_attr
        style = "format"
    elif pretty is not None:
        if pretty == "oneline":
            style = "oneline_full"
        elif pretty.startswith("format:"):
            fmt_terminator = False
            fmt_string = pretty.split(":", 1)[1]
            style = "format"
        elif pretty.startswith("tformat:") or "%" in pretty:
            fmt_string = (pretty.split(":", 1)[1]
                          if pretty.startswith("tformat:") else pretty)
            style = "format"
        else:
            style = pretty
    if getattr(args, "oneline", False):
        style = "oneline"
    date_mode = getattr(args, "date", None) or "default"
    no_patch = getattr(args, "no_patch", False) or getattr(args, "quiet", False)
    context = getattr(args, "unified", 3)
    from . import mailmap as _mailmap
    mm = None if getattr(args, "no_use_mailmap", False) else _mailmap.load(repo)

    # Render a single commit's header in the active style.
    def render_header(count: int, sha: str, c) -> None:
        if style == "format":
            expansion = _expand_commit_format(repo, sha, c, fmt_string, {},
                                              date_mode, getattr(args, "abbrev", 7))
            if fmt_terminator:
                sys.stdout.write(expansion + "\n")
            else:
                if count > 0:
                    sys.stdout.write("\n")
                sys.stdout.write(expansion)
        elif style in ("oneline", "oneline_full"):
            abbrev = sha[:7] if style == "oneline" else sha
            first = c.message.splitlines()[0] if c.message.strip() else ""
            _print(f"{abbrev} {first}")
        elif style == "reference":
            first = c.message.splitlines()[0] if c.message.strip() else ""
            _print(f"{sha[:7]} ({first}, {_format_date(c.author, 'short')})")
        elif style in ("short", "raw"):
            if count > 0:
                _print("")
            _print(f"commit {sha}")
            if style == "raw":
                _print(f"tree {c.tree}")
                for p in c.parents:
                    _print(f"parent {p}")
                _print(f"author {c.author}")
                _print(f"committer {c.committer}")
                _print("")
                for line in c.message.rstrip("\n").splitlines():
                    _print(f"    {line}")
            else:
                if len(c.parents) > 1:
                    _print("Merge: " + " ".join(p[:7] for p in c.parents))
                _print(f"Author: {_mapped_who(_split_ident(c.author)[0], mm)}")
                _print("")
                first = c.message.splitlines()[0] if c.message.strip() else ""
                _print(f"    {first}")
        else:  # medium / full / fuller
            if count > 0:
                _print("")
            _emit_commit_header(sha, c, style=style, date_mode=date_mode, mailmap=mm)
            _print("")
            for line in c.message.rstrip("\n").splitlines():
                _print(f"    {line}")

    # Emit one commit's scoped line-log diff (after its header).
    def emit_diff(diff_blocks: list[tuple]) -> None:
        # line_log_print: fprintf(file, "%s\n", prefix) -> a blank line.
        _print("")
        for (path, parent_path, a_text, b_text, a_sha, b_sha, a_present,
             b_mode, scoped) in diff_blocks:
            for h in _line_log_file_header(path, parent_path, a_text, b_text,
                                           a_sha, b_sha, a_present, b_mode):
                _print(h)
            for ln in scoped:
                _print(ln)

    if mode == "show":
        # show -L: render the start commit only, with each tracked file's
        # in-range lines as a brand-new-file diff (no parent).
        c = objs.parse_commit(objs.read_object(repo, start_sha)[1])
        render_header(0, start_sha, c)
        if not no_patch:
            blocks = []
            for fr in ranges0:
                e = workdir.tree_path_entry(repo, start_tree, fr.path)
                b_sha = e.sha
                b_mode = e.mode
                b_text = objs.read_object(repo, b_sha)[1].decode("utf-8", errors="replace")
                scoped = _ll.emit_scoped_hunks("", b_text, fr.ranges, context)
                blocks.append((fr.path, fr.path, "", b_text, None, b_sha,
                               False, b_mode, scoped))
            emit_diff(blocks)
        return 0

    # log -L: line-level traverse forces topological order (revision.c
    # sets revs->topo_order=1).  Collect the reachable commit set in
    # committer-date order (limit_list), topo-sort it, then run the line-log
    # filter in that order so each commit is seen after all its children.
    graph = _graph_for_repo(repo)
    import heapq
    first_parent = getattr(args, "first_parent", False)

    seed_heap: list[tuple] = []
    seed_counter = 0
    seen_collect: set[str] = set()
    reachable: list[str] = []
    heapq.heappush(seed_heap, (-_commit_date(repo, start_sha), seed_counter, start_sha))
    seed_counter += 1
    seeded = {start_sha}
    while seed_heap:
        _d, _c, sha = heapq.heappop(seed_heap)
        if sha in seen_collect:
            continue
        seen_collect.add(sha)
        info = _commit_tree_parents(repo, sha, graph)
        if info is None:
            continue
        reachable.append(sha)
        for p in (info[1][:1] if first_parent else info[1]):
            if p not in seeded:
                heapq.heappush(seed_heap, (-_commit_date(repo, p), seed_counter, p))
                seed_counter += 1
                seeded.add(p)
    order = _topo_order(repo, reachable, first_parent)

    # Decoration: sha -> list[FileRanges] tracked at that commit.
    tracked: dict[str, list] = {start_sha: ranges0}
    out_commits: list[tuple] = []  # (sha, commit_obj, diff_blocks)

    def _propagate(parent: str, parent_ranges):
        existing = tracked.get(parent)
        tracked[parent] = (_ll.merge_file_ranges(existing, parent_ranges)
                           if existing else parent_ranges)

    for sha in order:
        cinfo = _commit_tree_parents(repo, sha, graph)
        if cinfo is None:
            continue
        ctree, parents = cinfo
        fr_list = tracked.get(sha)
        if fr_list is None:
            continue

        is_merge = len(parents) > 1
        if is_merge:
            eff_parents = parents[:1] if first_parent else parents
            ptrees = [(p, _commit_tree_parents(repo, p, graph)[0]) for p in eff_parents]
            shown, propagate = _ll.process_merge_commit(repo, fr_list, ctree, ptrees)
            if shown:
                c = objs.parse_commit(objs.read_object(repo, sha)[1])
                out_commits.append((sha, c, []))  # merge: empty (combined) diff
            for psha, pr in propagate:
                _propagate(psha, pr)
            continue

        # Ordinary commit (or first-parent traversal of a merge).
        parent = parents[0] if parents else None
        parent_tree = _commit_tree_parents(repo, parent, graph)[0] if parent else None
        changed, parent_ranges = _ll.process_commit(repo, fr_list, ctree, parent_tree)
        if changed:
            blocks = []
            c = objs.parse_commit(objs.read_object(repo, sha)[1])
            for fr in fr_list:
                if fr.pair is None:
                    continue
                parent_path, a_text, b_text = fr.pair
                pe = (workdir.tree_path_entry(repo, parent_tree, parent_path)
                      if parent_tree else None)
                a_sha = pe.sha if pe else None
                b_entry = workdir.tree_path_entry(repo, ctree, fr.path)
                b_sha = b_entry.sha if b_entry else None
                b_mode = b_entry.mode if b_entry else "100644"
                scoped = _ll.emit_scoped_hunks(a_text, b_text, fr.ranges_at_target,
                                               context)
                blocks.append((fr.path, parent_path, a_text, b_text, a_sha, b_sha,
                               a_sha is not None, b_mode, scoped))
            out_commits.append((sha, c, blocks))
        if parent is not None:
            _propagate(parent, parent_ranges)

    max_count = getattr(args, "max_count", None)
    if max_count is not None:
        out_commits = out_commits[:max(0, max_count)]
    if getattr(args, "reverse", False):
        out_commits = list(reversed(out_commits))

    for count, (sha, c, blocks) in enumerate(out_commits):
        render_header(count, sha, c)
        if not no_patch:
            emit_diff(blocks)
    return 0


def cmd_log(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit log", add_help=False)
    ap.add_argument("--oneline", action="store_true")
    ap.add_argument("--decorate", nargs="?", const="short", default=None)
    ap.add_argument("--no-decorate", action="store_true")
    ap.add_argument("--pretty", nargs="?", const="medium", default=None)
    ap.add_argument("--format", default=None)
    ap.add_argument("--abbrev-commit", action="store_true")
    ap.add_argument("--no-abbrev-commit", dest="no_abbrev_commit", action="store_true")
    ap.add_argument("--abbrev", type=int, default=7)
    ap.add_argument("--no-abbrev", dest="no_abbrev", action="store_true")
    ap.add_argument("-p", "--patch", "-u", action="store_true")
    # -q/--quiet sets the diff machinery's NO_OUTPUT format *before* the
    # in-order diff options are parsed, so for log (whose default diff output
    # is already empty) it is a near no-op: any -p/--stat/--raw overrides it.
    # Its one observable effect is the diff_setup_done conflict against
    # --name-only/--name-status (NO_OUTPUT and NAME[_STATUS] cannot coexist).
    ap.add_argument("-q", "--quiet", dest="quiet", action="store_true")
    ap.add_argument("-U", "--unified", type=int, default=3)
    ap.add_argument("--stat", action="store_true")
    ap.add_argument("--shortstat", action="store_true")
    ap.add_argument("--numstat", action="store_true")
    ap.add_argument("--summary", action="store_true")
    ap.add_argument("--compact-summary", dest="compact_summary", action="store_true")
    ap.add_argument("--name-only", dest="name_only", action="store_true")
    ap.add_argument("--name-status", dest="name_status", action="store_true")
    ap.add_argument("--raw", action="store_true")
    # --patch-with-stat / --patch-with-raw are synonyms handled by the order
    # resolver; accepted here so argparse doesn't reject them.
    ap.add_argument("--patch-with-stat", dest="_pws", action="store_true")
    ap.add_argument("--patch-with-raw", dest="_pwr", action="store_true")
    # Shared patch-rendering options threaded into the _DiffOpts renderer.
    ap.add_argument("--no-prefix", dest="no_prefix", action="store_true")
    ap.add_argument("--src-prefix", dest="src_prefix", default=None)
    ap.add_argument("--dst-prefix", dest="dst_prefix", default=None)
    ap.add_argument("--default-prefix", dest="default_prefix", action="store_true")
    ap.add_argument("--full-index", dest="full_index", action="store_true")
    ap.add_argument("-w", "--ignore-all-space", dest="ignore_all_space", action="store_true")
    ap.add_argument("-b", "--ignore-space-change", dest="ignore_space_change", action="store_true")
    ap.add_argument("--ignore-space-at-eol", dest="ignore_space_at_eol", action="store_true")
    ap.add_argument("--ignore-cr-at-eol", dest="ignore_cr_at_eol", action="store_true")
    # --clear-decorations resets the (currently unsupported) --decorate-refs
    # include/exclude filters; with no such filters in effect it is a no-op.
    ap.add_argument("--clear-decorations", dest="clear_decorations", action="store_true")
    ap.add_argument("--no-merges", dest="no_merges", action="store_true")
    # The builtin formats honour the mailmap by default (log.mailmap=true);
    # --no-use-mailmap shows raw identities. %an/%ae stay raw regardless.
    ap.add_argument("--use-mailmap", "--mailmap", dest="use_mailmap", action="store_true")
    ap.add_argument("--no-use-mailmap", "--no-mailmap", dest="no_use_mailmap", action="store_true")
    # pythongit never colorizes, so color controls are accepted and ignored.
    ap.add_argument("--color", nargs="?", const="always", default=None)
    ap.add_argument("--no-color", action="store_true")
    ap.add_argument("--reverse", action="store_true")
    ap.add_argument("--first-parent", dest="first_parent", action="store_true")
    ap.add_argument("--all", action="store_true")
    ap.add_argument("--branches", nargs="?", const="*", default=None)
    ap.add_argument("--tags", nargs="?", const="*", default=None)
    ap.add_argument("--remotes", nargs="?", const="*", default=None)
    ap.add_argument("--no-walk", dest="no_walk", nargs="?", const="sorted", default=None)
    ap.add_argument("--graph", action="store_true")
    ap.add_argument("--topo-order", dest="topo_order", action="store_true")
    ap.add_argument("--date-order", dest="date_order", action="store_true")
    ap.add_argument("--parents", action="store_true")
    ap.add_argument("--merges", action="store_true")
    ap.add_argument("--min-parents", dest="min_parents", type=int, default=None)
    ap.add_argument("--max-parents", dest="max_parents", type=int, default=None)
    ap.add_argument("--grep", action="append", default=None)
    ap.add_argument("--author", action="append", default=None)
    ap.add_argument("--committer", action="append", default=None)
    ap.add_argument("--all-match", dest="all_match", action="store_true")
    ap.add_argument("-i", "--regexp-ignore-case", dest="ignore_case", action="store_true")
    ap.add_argument("-S", dest="pickaxe_s", default=None)
    ap.add_argument("-G", dest="pickaxe_g", default=None)
    ap.add_argument("--since", "--after", dest="since", default=None)
    ap.add_argument("--until", "--before", dest="until", default=None)
    ap.add_argument("--date", default=None)
    ap.add_argument("-n", "--max-count", type=int, default=None)
    ap.add_argument("-g", "--walk-reflogs", dest="walk_reflogs", action="store_true")
    ap.add_argument("--follow", action="store_true")
    ap.add_argument("--left-right", dest="left_right", action="store_true")
    ap.add_argument("-L", dest="line_ranges", action="append", default=None)
    # -s/--no-patch suppresses the per-commit patch; only consulted in the
    # line-log path (the default log output already emits no diff).
    ap.add_argument("-s", "--no-patch", dest="no_patch", action="store_true")
    ap.add_argument("pos", nargs="*")
    # `--word-diff[=<mode>]` / `--word-diff-regex=<re>` are pulled out before
    # argparse so the trailing rev isn't consumed; they feed the _DiffOpts.
    raw_argv = list(argv)
    word_diff_mode = None
    word_regex_src = None
    _wd_argv = []
    for a in _expand_count_shorthand(argv):
        if a == "--word-diff":
            word_diff_mode = "plain"
        elif a.startswith("--word-diff="):
            word_diff_mode = a.split("=", 1)[1]
        elif a.startswith("--word-diff-regex="):
            word_regex_src = a.split("=", 1)[1]
            if word_diff_mode is None:
                word_diff_mode = "plain"
        else:
            _wd_argv.append(a)
    args = ap.parse_args(_wd_argv)
    args.word_diff = word_diff_mode
    import re as _re_mod
    args.word_regex = _re_mod.compile(word_regex_src) if word_regex_src else None
    # The output-format flags interact in command-line order: -s/--no-patch
    # reset the format to NO_OUTPUT (clearing an earlier -p/--stat/etc.), while
    # -p and the --stat-family bits accumulate. For *log*, -q/--quiet sets
    # NO_OUTPUT early in the revision parser (before the in-order diff options),
    # so any later -p/--stat/--raw overrides it — model that by hoisting -q to
    # the front. -s stays in place (true command-line order).
    fmt_argv = [t for t in raw_argv if t not in ("-q", "--quiet")]
    if any(t in ("-q", "--quiet") for t in raw_argv):
        fmt_argv = ["--no-patch"] + fmt_argv
    out_fmt, fmt_conflict = _resolve_diff_output_format(fmt_argv)
    args._fmt_conflict = fmt_conflict
    args.patch = "patch" in out_fmt
    args.stat = "stat" in out_fmt
    args.shortstat = "shortstat" in out_fmt
    args.numstat = "numstat" in out_fmt
    args.summary = "summary" in out_fmt
    args.compact_summary = "compact_summary" in out_fmt
    args.name_only = "name_only" in out_fmt
    args.name_status = "name_status" in out_fmt
    args.raw = "raw" in out_fmt
    repo = _repo()
    if args.line_ranges:
        return _run_line_log(repo, args, mode="log")
    # Builtin formats honour the mailmap by default; --no-use-mailmap disables it.
    from . import mailmap as _mailmap
    mm_log = None if args.no_use_mailmap else _mailmap.load(repo)
    # --no-abbrev[-commit] override the abbreviation: full oids everywhere.
    if args.no_abbrev:
        args.abbrev = repo.hex_len
    if args.no_abbrev_commit:
        args.abbrev_commit = False

    if args.graph and args.reverse:
        _err("fatal: options '--graph' and '--reverse' cannot be used together")
        return 128
    if args.walk_reflogs and args.reverse:
        _err("fatal: options '--reverse' and '--walk-reflogs' cannot be used together")
        return 128
    # diff_setup_done() rejects more than one of {--name-only, --name-status,
    # --check, -s} with rc 128 (the patch/stat/raw flags clear NO_OUTPUT first,
    # so the conflict only fires among the surviving name/no-output formats).
    if args._fmt_conflict:
        _err("fatal: options '--name-only', '--name-status', '--check', and '-s' "
             "cannot be used together")
        return 128

    # Split positionals into revisions and pathspecs.
    revs: list[str] = []
    log_paths: list[str] = []
    if "--" in args.pos:
        di = args.pos.index("--")
        revs, log_paths = args.pos[:di], args.pos[di + 1:]
    else:
        for tok in args.pos:
            if ".." in tok or refs_mod.rev_parse(repo, tok) is not None:
                revs.append(tok)
            elif (repo.path / tok).exists():
                log_paths.append(tok)
            else:
                # Not a rev and not a path: keep as a rev so resolution errors.
                revs.append(tok)
    rev = revs[0] if revs else "HEAD"

    exclude: set[str] = set()
    if ".." in rev:
        lo, _, hi = rev.partition("..")
        sha = refs_mod.rev_parse(repo, hi or "HEAD")
        if lo:
            lo_sha = refs_mod.rev_parse(repo, lo)
            if lo_sha:
                stack = deque([lo_sha])
                while stack:
                    x = stack.popleft()
                    if x in exclude:
                        continue
                    exclude.add(x)
                    info = _commit_tree_parents(repo, x)
                    if info:
                        stack.extend(info[1])
    else:
        sha = refs_mod.rev_parse(repo, rev)
    if not sha and not args.all:
        head_sym, _ = refs_mod.read_head(repo)
        if rev == "HEAD" and head_sym and head_sym.startswith("refs/heads/"):
            branch = head_sym[len("refs/heads/"):]
            _err(f"fatal: your current branch '{branch}' does not have any commits yet")
            return 128
        _err(f"fatal: ambiguous argument '{rev}': unknown revision or path not in the working tree.")
        _err("Use '--' to separate paths from revisions, like this:")
        _err("'git <command> [<revision>...] -- [<file>...]'")
        return 128
    # Determine output style. `--format`/`tformat:` terminate each entry with a
    # newline; `format:` only separates entries (no trailing newline).
    fmt_string: Optional[str] = None
    style = "medium"
    fmt_terminator = True
    # `--format=<builtin>` is an alias for `--pretty=<builtin>`, not a literal.
    if args.format in ("oneline", "short", "medium", "full", "fuller", "raw", "reference"):
        args.pretty, args.format = args.format, None
    if args.format is not None:
        fmt_string = args.format
        style = "format"
    elif args.pretty is not None:
        if args.pretty == "oneline":
            style = "oneline_full"
        elif args.pretty.startswith("format:"):
            fmt_terminator = False
            fmt_string = args.pretty.split(":", 1)[1]
            style = "format"
        elif args.pretty.startswith("tformat:") or "%" in args.pretty:
            # A non-builtin value containing '%' is a tformat string.
            fmt_terminator = True
            fmt_string = (args.pretty.split(":", 1)[1]
                          if args.pretty.startswith("tformat:") else args.pretty)
            style = "format"
        else:
            style = args.pretty
    if args.oneline:
        style = "oneline"
    date_mode = args.date or "default"
    date_given = args.date is not None

    decorate = args.decorate is not None and not args.no_decorate
    # The %d/%D/%(decorate) placeholders always expand decorations.
    if not decorate and fmt_string and ("%d" in fmt_string or "%D" in fmt_string
                                        or "%(decorate" in fmt_string):
        decorate = True
    decorations = _commit_decorations(repo, full=(args.decorate == "full")) if decorate else {}

    # `--graph` and `--topo-order` reorder commits topologically (unless
    # `--date-order` is also given); collect the full set first, then sort.
    want_topo = (args.graph or args.topo_order) and not args.date_order
    # Commit-level filters mean the early --max-count cutoff during collection
    # would truncate before filtering, so collect fully when any filter is set.
    want_filter = any((
        args.merges, args.no_merges, args.min_parents is not None,
        args.max_parents is not None, args.grep, args.author, args.committer,
        args.pickaxe_s is not None, args.pickaxe_g is not None,
        args.since, args.until))
    collect_full = want_topo or want_filter

    # Collect the ordered list of commit shas first so --reverse can flip it.
    seen: set[str] = set()
    commit_list: list[str] = []
    # `-g`/`--walk-reflogs`: enumerate the named ref's reflog (newest first)
    # instead of walking commit ancestry. Each entry carries its own selector,
    # committer identity and message, which the renderer injects per commit.
    reflog_meta: Optional[list[dict]] = None
    if args.walk_reflogs:
        from . import reflog as _reflog
        full_ref = rev if rev == "HEAD" else (refs_mod.dwim_full_name(repo, rev) or rev)
        entries = _reflog.read(repo, full_ref)
        reflog_meta = []
        zero = repo.null_oid()
        # git's selector keeps the ref *as given on the command line* for %gD;
        # %gd shortens it via shorten_unambiguous_ref(). The ref-rev-parse rules
        # strip the well-known namespaces, and the general "refs/%.*s" rule turns
        # e.g. refs/stash into "stash".
        short_rev = rev
        for pre in ("refs/heads/", "refs/remotes/", "refs/tags/"):
            if short_rev.startswith(pre):
                short_rev = short_rev[len(pre):]
                break
        else:
            if short_rev.startswith("refs/") and short_rev.count("/") == 1:
                short_rev = short_rev[len("refs/"):]
        for i, (_old, new, ident, msg) in enumerate(reversed(entries)):
            # Deletion markers (zero new-oid) consume an @{N} slot but aren't shown.
            if new == zero:
                continue
            commit_list.append(new)
            reflog_meta.append({"sref": short_rev, "fref": rev, "i": i,
                                "ident": ident, "msg": msg})
        want_topo = collect_full = False
    elif args.no_walk is not None:
        # --no-walk shows only the named revisions, no ancestry traversal. The
        # default ("sorted") orders by committer date; "unsorted" keeps the
        # command-line order. Downstream filter/--max-count/--reverse still run.
        want_topo = collect_full = False
        wanted = revs if revs else ["HEAD"]
        for r in wanted:
            rsha = refs_mod.rev_parse(repo, r)
            if rsha and rsha not in commit_list:
                commit_list.append(rsha)
        if args.no_walk != "unsorted":
            commit_list.sort(key=lambda s: -_commit_date(repo, s))
    elif args.all or args.branches is not None or args.tags is not None or args.remotes is not None:
        # `--all`/`--branches`/`--tags`/`--remotes` walk the selected ref
        # namespaces. Match git's reverse-chronological order: a stable max-heap
        # keyed on committer date, ties broken by seed order (ascending refname,
        # then HEAD for --all).
        import heapq
        import fnmatch
        heap: list[tuple[int, int, str]] = []
        pushed: set[str] = set()
        counter = 0

        def _push(csha: str) -> None:
            nonlocal counter
            if csha in pushed:
                return
            pushed.add(csha)
            heapq.heappush(heap, (-_commit_date(repo, csha), counter, csha))
            counter += 1

        wanted_ns = []
        if args.all or args.branches is not None:
            wanted_ns.append(("refs/heads/", args.branches if args.branches not in (None, "*") else None))
        if args.all or args.tags is not None:
            wanted_ns.append(("refs/tags/", args.tags if args.tags not in (None, "*") else None))
        if args.all or args.remotes is not None:
            wanted_ns.append(("refs/remotes/", args.remotes if args.remotes not in (None, "*") else None))
        for refname, _rsha in _enumerate_refs(repo):
            for pre, pat in wanted_ns:
                if refname.startswith(pre):
                    if pat and not fnmatch.fnmatch(refname[len(pre):], pat):
                        continue
                    csha = refs_mod.rev_parse(repo, refname + "^{commit}")
                    if csha:
                        _push(csha)
                    break
        if args.all:
            _, head_sha = refs_mod.read_head(repo)
            if head_sha:
                _push(head_sha)
        while heap:
            _d, _c, s = heapq.heappop(heap)
            if s in seen or s in exclude:
                continue
            seen.add(s)
            info = _commit_tree_parents(repo, s)
            if info is None:
                continue
            commit_list.append(s)
            for p in (info[1][:1] if args.first_parent else info[1]):
                _push(p)
            if not log_paths and not collect_full and args.max_count and len(commit_list) >= args.max_count:
                break
    else:
        cur = deque([sha])
        while cur:
            s = cur.popleft()
            if s in seen or s in exclude:
                continue
            seen.add(s)
            info = _commit_tree_parents(repo, s)
            if info is None:
                break
            commit_list.append(s)
            cur.extend(info[1][:1] if args.first_parent else info[1])
            if not log_paths and not collect_full and args.max_count and len(commit_list) >= args.max_count:
                break

    if want_topo:
        commit_list = _topo_order(repo, commit_list, args.first_parent)

    if args.follow and len(log_paths) == 1 and not args.walk_reflogs:
        # --follow: include commits that touch the file, switching the followed
        # name to the rename source whenever the file first appears via a rename.
        followed = log_paths[0]
        filtered = []
        for s in commit_list:
            info = _commit_tree_parents(repo, s)
            tree, parents = info[0], info[1]
            ptree = _commit_tree_parents(repo, parents[0])[0] if parents else None
            before = workdir.tree_path_entry(repo, ptree, followed) if ptree else None
            after = workdir.tree_path_entry(repo, tree, followed)
            bsha = before.sha if before else None
            asha = after.sha if after else None
            if bsha != asha:
                filtered.append(s)
                if asha and not bsha and ptree:
                    src = _follow_rename_source(repo, ptree, tree, followed)
                    if src:
                        followed = src
        commit_list = filtered
    elif log_paths and not args.walk_reflogs:
        filtered: list[str] = []
        for s in commit_list:
            info = _commit_tree_parents(repo, s)
            tree, parents = info[0], info[1]
            ptree = _commit_tree_parents(repo, parents[0])[0] if parents else None
            for path in log_paths:
                before = workdir.tree_path_entry(repo, ptree, path) if ptree else None
                after = workdir.tree_path_entry(repo, tree, path)
                if (before.sha if before else None) != (after.sha if after else None):
                    filtered.append(s)
                    break
            if not collect_full and args.max_count and len(filtered) >= args.max_count:
                break
        commit_list = filtered

    # Commit-level filters (applied before --max-count truncation, like git).
    if not args.walk_reflogs:
        commit_list = _filter_commits(repo, commit_list, args)

    if args.max_count is not None:
        commit_list = commit_list[:max(0, args.max_count)]
        if reflog_meta is not None:
            reflog_meta = reflog_meta[:max(0, args.max_count)]
    if args.reverse:
        commit_list = list(reversed(commit_list))
        if reflog_meta is not None:
            reflog_meta = list(reversed(reflog_meta))

    graph = None
    if args.graph:
        from . import graph as _graph_mod

        def _parents_of(csha: str) -> list:
            info = _commit_tree_parents(repo, csha)
            return list(info[1]) if info else []

        graph = _graph_mod.Graph(_parents_of)
    # Styles whose commits are separated by a blank line (graph prefixes it).
    multiline = style in ("medium", "full", "fuller", "short", "raw", "email", "mboxrd")
    last_index = len(commit_list) - 1

    # The shared patch-rendering options for -p/--full-index/--no-prefix/...;
    # --raw blob SHAs honor --abbrev/--no-abbrev (args.abbrev already folds in
    # --no-abbrev = full hex length). Prefix flags are order-sensitive.
    _a_pfx, _b_pfx = _resolve_diff_prefixes(raw_argv)
    log_dopts = _DiffOpts(
        a_prefix=_a_pfx, b_prefix=_b_pfx,
        full_index=args.full_index, abbrev=args.abbrev,
        ignore_all_space=args.ignore_all_space,
        ignore_space_change=args.ignore_space_change,
        ignore_space_at_eol=args.ignore_space_at_eol,
        ignore_cr_at_eol=args.ignore_cr_at_eol,
        word_diff=args.word_diff, word_regex=args.word_regex,
    )
    raw_abbrev = args.abbrev
    # The 'Merge:' parent-id width follows pp->abbrev = rev->abbrev, which is
    # DEFAULT_ABBREV (7) unless --abbrev set it explicitly.
    _merge_abbrev = args.abbrev if args.abbrev is not None else 7

    def emit_commit_diff(s, c, lead_blank):
        # The stat/patch/raw/name listing that --stat/-p/--raw/--name-* append
        # to each commit. A merge has no default (non-combined) diff, so git
        # emits nothing (not even the leading blank line).
        if not (args.stat or args.shortstat or args.numstat or args.summary
                or args.compact_summary or args.patch or args.name_only
                or args.name_status or args.raw):
            return
        # A merge has no default (non-combined) diff, so git emits nothing -- but
        # under --first-parent a merge is diffed against its first parent (this is
        # how `git stash list -p` shows each stash's changes).
        if len(c.parents) > 1 and not args.first_parent:
            return
        parent_tree = None
        if c.parents:
            _, pd = objs.read_object(repo, c.parents[0])
            parent_tree = objs.parse_commit(pd).tree
        tchanges = _tree_changes(repo, parent_tree, c.tree)
        # A pathspec restricts the per-commit diff to the matching files (git
        # shows only changes touching the pathspec). --follow varies the name
        # per commit, so leave it unrestricted there.
        if log_paths and not args.follow:
            def _pm(p):
                return any(p == w or p.startswith(w.rstrip("/") + "/") for w in log_paths)
            tchanges = [ch for ch in tchanges if _pm(ch[0])]
        if lead_blank:
            # When showing a verbose header with both a diffstat (--stat /
            # --compact-summary) AND a patch, git emits a "---" line instead of
            # a blank line before the diff group (log-tree.c). Otherwise blank.
            if (args.stat or args.compact_summary) and args.patch:
                _print("---")
            else:
                _print("")
        # Output formats accumulate in git's fixed diff_flush order: raw/name →
        # numstat → stat/compact-summary → shortstat → summary → patch, with a
        # blank-line separator before the patch when any earlier group printed.
        separator = False
        # RAW / NAME / NAME_STATUS share one rendering block (diff.c
        # flush_one_pair): name-status wins over raw (suppresses the mode/sha
        # prefix), and name-status wins over name-only.
        if args.raw or args.name_only or args.name_status:
            zero = "0" * raw_abbrev
            for path, a, b in tchanges:
                status = "A" if not a.present else ("D" if not b.present else "M")
                if args.name_status:
                    _print(f"{status}\t{path}")
                elif args.name_only:
                    _print(path)
                else:
                    a_sha = a.sha[:raw_abbrev] if a.present else zero
                    b_sha = b.sha[:raw_abbrev] if b.present else zero
                    _print(f":{(a.mode or '000000').zfill(6)} {(b.mode or '000000').zfill(6)} "
                           f"{a_sha} {b_sha} {status}\t{path}")
            separator = True
        if args.numstat:
            _diff_numstat(tchanges)
            separator = True
        if args.compact_summary:
            _diff_stat(tchanges, compact_summary=True)
            separator = True
        elif args.stat:
            _diff_stat(tchanges)
            separator = True
        if args.shortstat:
            _diff_shortstat(tchanges)
            separator = True
        if args.summary:
            _diff_summary(tchanges)
            separator = True
        if args.patch:
            if separator:
                _print("")
            for path, a, b in tchanges:
                _emit_file_diff(path, a, b, context=args.unified, opts=log_dopts)

    # --left-right prepends a side mark (get_revision_mark/put_revision_mark).
    # pythongit walks single tips only, so every shown commit is right-side ">".
    lr_mark = "> " if args.left_right else ""

    def render(count, s, c, meta=None):
        if style == "format":
            expansion = _expand_commit_format(repo, s, c, fmt_string, decorations, date_mode, args.abbrev,
                                              reflog=meta, date_given=date_given)
            # commit_format_is_empty: an empty user --format emits no commit text,
            # no terminator newline, and no blank line before the diff (log-tree.c
            # lines 915 & 944).
            fmt_is_empty = fmt_string == ""
            if fmt_is_empty:
                pass
            elif fmt_terminator:
                sys.stdout.write(expansion + "\n")
            else:
                if count > 0:
                    sys.stdout.write("\n")
                sys.stdout.write(expansion)
            emit_commit_diff(s, c, lead_blank=not fmt_is_empty)
        elif style in ("oneline", "oneline_full"):
            short = style == "oneline" or args.abbrev_commit
            abbrev = s[:args.abbrev] if short else s
            if meta is not None:
                # The oneline reflog selector uses the ref as given on the
                # command line (get_reflog_selector with the full ref), e.g.
                # "refs/stash@{0}" / "main@{0}" -- not the %gd shortening.
                sel = _reflog_selector(meta, full=True, date_mode=date_mode, date_given=date_given)
                _print(f"{lr_mark}{abbrev} {sel}: {meta['msg']}")
                return
            first = c.message.splitlines()[0] if c.message.strip() else ""
            deco = _format_decoration(decorations.get(s, []))
            pre = abbrev
            if args.parents:
                pre += "".join(" " + (p[:7] if short else p) for p in c.parents)
            _print(f"{lr_mark}{pre}{deco} {first}")
            emit_commit_diff(s, c, lead_blank=False)
        elif style == "reference":
            first = c.message.splitlines()[0] if c.message.strip() else ""
            _print(f"{s[:7]} ({first}, {_format_date(c.author, 'short')})")
        elif style in ("email", "mboxrd"):
            if count > 0:
                _print("")
            _emit_email_commit(s, c, mailmap=mm_log)
            emit_commit_diff(s, c, lead_blank=True)
        elif style in ("short", "raw"):
            if count > 0:
                _print("")
            sha_disp = s[:7] if args.abbrev_commit else s
            psuf = ("".join(" " + (p[:7] if args.abbrev_commit else p) for p in c.parents)
                    if args.parents else "")
            _print(f"commit {lr_mark}{sha_disp}{psuf}{_format_decoration(decorations.get(s, []))}")
            if style == "raw":
                _print(f"tree {c.tree}")
                for p in c.parents:
                    _print(f"parent {p}")
                _print(f"author {c.author}")
                _print(f"committer {c.committer}")
                _print("")
                for line in c.message.rstrip("\n").splitlines():
                    _print(f"    {line}")
            else:  # short
                if len(c.parents) > 1:
                    _print("Merge: " + " ".join(p[:_merge_abbrev] for p in c.parents))
                _print(f"Author: {_mapped_who(_split_ident(c.author)[0], mm_log)}")
                _print("")
                first = c.message.splitlines()[0] if c.message.strip() else ""
                _print(f"    {first}")
        else:
            if count > 0:
                _print("")
            psuf = ("".join(" " + (p[:7] if args.abbrev_commit else p) for p in c.parents)
                    if args.parents else "")
            _emit_commit_header(s[:7] if args.abbrev_commit else s, c, style=style,
                                date_mode=date_mode, parents_suffix=psuf,
                                decoration=_format_decoration(decorations.get(s, [])),
                                reflog=meta, date_given=date_given, mailmap=mm_log,
                                abbrev=_merge_abbrev,
                                mark=lr_mark)
            _print("")
            for line in c.message.rstrip("\n").splitlines():
                _print(f"    {line}")
            emit_commit_diff(s, c, lead_blank=True)

    for count, s in enumerate(commit_list):
        c = objs.parse_commit(objs.read_object(repo, s)[1])
        meta = reflog_meta[count] if reflog_meta is not None else None
        if graph is None:
            render(count, s, c, meta)
        else:
            text = _capture_output(lambda: render(0, s, c, meta))
            sys.stdout.write(graph.format_commit(
                s, text, emit_separator=(multiline and count > 0)))
    return 0


def _expand_count_shorthand(argv: list[str]) -> list[str]:
    out: list[str] = []
    for a in argv:
        if len(a) > 1 and a[0] == "-" and a[1:].isdigit():
            out.extend(["-n", a[1:]])
        else:
            out.append(a)
    return out


def _commit_decorations(repo: Repository, full: bool = False) -> dict[str, list[str]]:
    """Map commit sha -> ordered decoration labels, matching C Git.

    Git iterates refs in ascending full-name order, *prepending* each label to
    its target's list (so the result is reverse-alphabetical), peels annotated
    tags to the commit they reference, and finally hoists the current branch to
    the front as ``HEAD -> <branch>`` (or a bare ``HEAD`` when detached).
    With ``full`` the labels keep their full ``refs/...`` names.
    """
    out: dict[str, list[str]] = {}
    for refname, sha in _enumerate_refs(repo):
        if refname.startswith("refs/heads/"):
            label = refname if full else refname[len("refs/heads/"):]
            target = sha
        elif refname.startswith("refs/remotes/"):
            label = refname if full else refname[len("refs/remotes/"):]
            target = sha
        elif refname.startswith("refs/tags/"):
            label = "tag: " + (refname if full else refname[len("refs/tags/"):])
            # Annotated tags decorate the commit they ultimately point to.
            target = refs_mod.rev_parse(repo, refname + "^{commit}") or sha
        else:
            continue
        out.setdefault(target, []).insert(0, label)

    head_sym, head_sha = refs_mod.read_head(repo)
    if head_sha:
        if head_sym and head_sym.startswith("refs/heads/"):
            disp = head_sym if full else head_sym[len("refs/heads/"):]
            lst = out.setdefault(head_sha, [])
            if disp in lst:
                lst.remove(disp)
            lst.insert(0, f"HEAD -> {disp}")
        else:
            out.setdefault(head_sha, []).insert(0, "HEAD")
    return out


def _format_decoration(names: list[str]) -> str:
    return f" ({', '.join(names)})" if names else ""


def _split_ident(sig: str) -> tuple[str, Optional[int], Optional[str]]:
    """Split ``Name <email> <unixtime> <tz>`` into (who, unixtime, tz)."""
    import re
    m = re.match(r"^(.*) (\d+) ([+-]\d{4})$", sig)
    if m:
        return m.group(1), int(m.group(2)), m.group(3)
    return sig, None, None


def _relative_date(ts: int, now: Optional[int] = None) -> str:
    """C Git's ``--date=relative`` string (date.c:show_date_relative)."""
    import time
    if now is None:
        now = int(time.time())
    if now < ts:
        return "in the future"
    diff = now - ts

    def ago(n: int, unit: str) -> str:
        return f"{n} {unit}{'' if n == 1 else 's'} ago"

    if diff < 90:
        return ago(diff, "second")
    diff = (diff + 30) // 60          # minutes
    if diff < 90:
        return ago(diff, "minute")
    diff = (diff + 30) // 60          # hours
    if diff < 36:
        return ago(diff, "hour")
    diff = (diff + 12) // 24          # days
    if diff < 14:
        return ago(diff, "day")
    if diff < 70:
        return ago((diff + 3) // 7, "week")
    if diff < 365:
        return ago((diff + 15) // 30, "month")
    if diff < 1825:                   # under ~5 years: years and months
        totalmonths = (diff * 12 * 2 + 365) // (365 * 2)
        years, months = totalmonths // 12, totalmonths % 12
        if months:
            return (f"{years} year{'' if years == 1 else 's'}, "
                    f"{months} month{'' if months == 1 else 's'} ago")
        return f"{years} year{'' if years == 1 else 's'} ago"
    return ago((diff + 183) // 365, "year")


def _reflog_who(ident: str) -> str:
    """Strip the trailing ``<secs> <tz>`` from a reflog ident, leaving
    ``Name <email>`` (the portion git shows in ``Reflog:``/``%gn``/``%ge``)."""
    parts = ident.rsplit(" ", 2)
    if len(parts) == 3 and parts[1].lstrip("-").isdigit():
        return parts[0]
    return ident


def _reflog_selector(meta: dict, *, full: bool, date_mode: str, date_given: bool) -> str:
    """Build a reflog selector ``<ref>@{<index-or-date>}``. ``full`` chooses the
    full ref name (``%gD``) over the short one (``%gd``); with an explicit
    ``--date`` the brace holds the formatted entry time instead of the index."""
    ref = meta["fref"] if full else meta["sref"]
    inner = _format_date(meta["ident"], date_mode) if date_given else str(meta["i"])
    return f"{ref}@{{{inner}}}"


def _format_date(sig: str, mode: str = "default") -> str:
    """Render a signature's timestamp in one of git's ``--date=<mode>`` styles.

    The day of month is never zero-padded in the default and rfc styles,
    matching C Git. ``relative`` is computed against the current time; a
    ``-local`` suffix (or the bare ``local`` mode) renders in the system
    timezone; ``format:<strftime>`` applies an explicit strftime template.
    """
    import datetime
    _who, ts, tz = _split_ident(sig)
    if ts is None or tz is None:
        return sig
    mode = {"iso8601": "iso", "iso8601-strict": "iso-strict",
            "rfc2822": "rfc", "default-local": "local"}.get(mode, mode)

    if mode == "relative":
        return _relative_date(ts)

    # `format:` / `format-local:` apply a raw strftime template.
    if mode.startswith("format:") or mode.startswith("format-local:"):
        local = mode.startswith("format-local:")
        template = mode.split(":", 1)[1]
        d = datetime.datetime.fromtimestamp(ts) if local else (
            datetime.datetime.fromtimestamp(ts, datetime.timezone.utc)
            + datetime.timedelta(minutes=_tz_minutes(tz)))
        return d.strftime(template)

    # A `-local` suffix renders in the system timezone; the bare `local` mode is
    # `default` rendered locally. In local mode the displayed offset is the
    # system offset (still shown by iso/iso-strict/rfc; hidden by default).
    local = mode == "local" or mode.endswith("-local")
    if mode == "local":
        mode = "default"
    elif mode.endswith("-local"):
        mode = mode[: -len("-local")]
    if local:
        dt = datetime.datetime.fromtimestamp(ts)
        tz_out = _git_tz_str(dt.astimezone().utcoffset())
    else:
        dt = datetime.datetime.fromtimestamp(ts, datetime.timezone.utc) + datetime.timedelta(minutes=_tz_minutes(tz))
        tz_out = tz

    if mode == "iso":
        return dt.strftime("%Y-%m-%d %H:%M:%S ") + tz_out
    if mode == "iso-strict":
        suffix = "Z" if tz_out == "+0000" else tz_out[:3] + ":" + tz_out[3:]
        return dt.strftime("%Y-%m-%dT%H:%M:%S") + suffix
    if mode == "rfc":
        return dt.strftime("%a, ") + str(dt.day) + dt.strftime(" %b %Y %H:%M:%S ") + tz_out
    if mode == "human":
        return _human_date(dt, ts, tz, local)
    if mode == "short":
        return dt.strftime("%Y-%m-%d")
    if mode == "raw":
        return f"{ts} {tz_out}"
    if mode == "unix":
        return str(ts)
    # The default format shows the offset, except in local mode (hide.tz).
    tail = "" if local else (" " + tz_out)
    return dt.strftime("%a %b ") + str(dt.day) + dt.strftime(" %H:%M:%S %Y") + tail


def _tz_minutes(tz: str) -> int:
    sign = 1 if tz[0] == "+" else -1
    return sign * (int(tz[1:3]) * 60 + int(tz[3:5]))


def _git_tz_str(offset) -> str:
    """Render a timedelta UTC offset as git's ``+HHMM`` / ``-HHMM`` form."""
    mins = int(offset.total_seconds()) // 60 if offset else 0
    sign = "+" if mins >= 0 else "-"
    mins = abs(mins)
    return f"{sign}{mins // 60:02d}{mins % 60:02d}"


def _human_date(dt, ts: int, tz: str, local: bool) -> str:
    """C Git's ``--date=human`` (date.c:show_date_normal with a human now).

    Recent same-day timestamps fall back to a relative string; otherwise git
    drops fields that are redundant relative to the current local time (the
    year within this year, the date for the last few days, always seconds).
    """
    import datetime
    import time
    now = int(time.time())
    now_local = datetime.datetime.fromtimestamp(now)
    # git compares the integer +HHMM tz forms; for tests TZ is pinned so this
    # only matters for the rarely-shown human tz field.
    human_off = now_local.astimezone().utcoffset()
    human_min = int(human_off.total_seconds()) // 60 if human_off else 0
    human_tz_int = (1 if human_min >= 0 else -1) * ((abs(human_min) // 60) * 100 + abs(human_min) % 60)
    tz_int = int(tz)

    hide_tz = local or tz_int == human_tz_int
    hide_year = dt.year == now_local.year
    hide_date = hide_wday = False
    if hide_year and dt.month == now_local.month:
        if dt.day > now_local.day:
            pass  # future date: think timezones
        elif dt.day == now_local.day:
            hide_date = hide_wday = True
        elif dt.day + 5 > now_local.day:
            hide_date = True

    # "today" times collapse to a relative string.
    if hide_wday:
        return _relative_date(ts, now)

    hide_tz = hide_tz or not hide_date
    hide_wday = hide_time = not hide_year

    buf = ""
    if not hide_wday:
        buf += dt.strftime("%a") + " "
    if not hide_date:
        buf += dt.strftime("%b") + " " + str(dt.day) + " "
    if not hide_time:
        buf += dt.strftime("%H:%M")
    else:
        buf = buf.rstrip()
    if not hide_year:
        buf += " " + str(dt.year)
    if not hide_tz:
        buf += " " + tz
    return buf


def _format_ident_date(sig: str) -> str:
    """Format a signature's timestamp like C Git's default ``Date:`` line."""
    return _format_date(sig, "default")


def _mapped_who(who: str, mailmap=None) -> str:
    """Apply a mailmap to a `Name <email>` string (identity unless mailmap maps it)."""
    if mailmap is None or mailmap.empty:
        return who
    n, e = _parse_who(who)
    mn, me = mailmap.resolve(n, e)
    return f"{mn} <{me}>"


def _email_subject_body(c) -> tuple[str, str]:
    """Split a commit message into (subject, body) for the email/mbox pretty
    formats. The subject is the first paragraph with internal newlines folded to
    single spaces (pretty.c format_subject with a " " separator); the body is the
    remainder, leading blank lines skipped."""
    msg = c.message
    # Skip leading blank lines.
    lines = msg.split("\n")
    idx = 0
    while idx < len(lines) and lines[idx].strip() == "":
        idx += 1
    # format_subject: collect lines until a blank line, folding them with " ".
    subj_parts: list[str] = []
    while idx < len(lines) and lines[idx].strip() != "":
        subj_parts.append(lines[idx])
        idx += 1
    subject = " ".join(subj_parts)
    # Skip the blank line(s) separating subject from body.
    while idx < len(lines) and lines[idx].strip() == "":
        idx += 1
        break
    body = "\n".join(lines[idx:]).rstrip("\n")
    return subject, body


def _emit_email_commit(sha: str, c, *, mailmap=None) -> None:
    """Emit the email/mbox header block for one commit (log/show --pretty=email),
    matching pretty.c CMIT_FMT_EMAIL: the mbox 'From <sha> Mon Sep 17' line, the
    From:/Date: identity headers, the 'Subject: [PATCH] ...' line, a blank line,
    and the un-indented body."""
    author_who = _split_ident(c.author)[0]
    if mailmap is not None and not mailmap.empty:
        an, ae = _parse_who(author_who)
        mn, me = mailmap.resolve(an, ae)
        author_who = f"{mn} <{me}>"
    subject, body = _email_subject_body(c)
    _print(f"From {sha} Mon Sep 17 00:00:00 2001")
    _print(f"From: {author_who}")
    _print(f"Date: {_format_date(c.author, 'rfc')}")
    _print(f"Subject: [PATCH] {subject}")
    # pp_email_subject writes the subject line then a blank line after the
    # headers. pp_remainder then appends the body followed by a single newline
    # (nothing extra for an empty body).
    _print("")
    if body:
        _print(body)


def _emit_commit_header(sha: str, c, *, style: str = "medium",
                        date_mode: str = "default", decoration: str = "",
                        parents_suffix: str = "", reflog=None, date_given: bool = False,
                        mailmap=None, mark: str = "", abbrev: int = 7) -> None:
    """Print the ``commit``/``Author``/``Date`` header block for medium, full,
    and fuller pretty styles, shared by ``log`` and ``show``. ``mark`` is the
    optional --left-right side marker prepended to the commit id. ``abbrev``
    sizes the parent ids on the ``Merge:`` line (pretty.c add_merge_info)."""
    _print(f"commit {mark}{sha}{parents_suffix}{decoration}")
    if reflog is not None:
        # The "Reflog:" header uses the ref as given on the command line (full),
        # e.g. "refs/stash@{0}" / "main@{0}", not the %gd shortening.
        sel = _reflog_selector(reflog, full=True, date_mode=date_mode, date_given=date_given)
        _print(f"Reflog: {sel} ({_reflog_who(reflog['ident'])})")
        _print(f"Reflog message: {reflog['msg']}")
    if len(c.parents) > 1:
        _print("Merge: " + " ".join(p[:abbrev] for p in c.parents))
    author_who = _split_ident(c.author)[0]
    committer_who = _split_ident(c.committer)[0]
    # The builtin formats honour the mailmap by default (log.mailmap=true);
    # --no-use-mailmap passes mailmap=None to show the raw identities.
    if mailmap is not None and not mailmap.empty:
        an, ae = _parse_who(author_who)
        mn, me = mailmap.resolve(an, ae)
        author_who = f"{mn} <{me}>"
        cwho_n, cwho_e = _parse_who(committer_who)
        mcn, mce = mailmap.resolve(cwho_n, cwho_e)
        committer_who = f"{mcn} <{mce}>"
    if style == "fuller":
        _print(f"Author:     {author_who}")
        _print(f"AuthorDate: {_format_date(c.author, date_mode)}")
        _print(f"Commit:     {committer_who}")
        _print(f"CommitDate: {_format_date(c.committer, date_mode)}")
    elif style == "full":
        _print(f"Author: {author_who}")
        _print(f"Commit: {committer_who}")
    else:
        _print(f"Author: {author_who}")
        _print(f"Date:   {_format_date(c.author, date_mode)}")


def cmd_show(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit show", add_help=False)
    ap.add_argument("-s", "--no-patch", dest="no_patch", action="store_true")
    # -q/--quiet sets the diff machinery's NO_OUTPUT format; for show (whose
    # default output is a patch) this suppresses the diff exactly like -s.
    ap.add_argument("-q", "--quiet", dest="quiet", action="store_true")
    ap.add_argument("-p", "--patch", "-u", dest="patch", action="store_true")
    ap.add_argument("--stat", action="store_true")
    ap.add_argument("--shortstat", action="store_true")
    ap.add_argument("--numstat", action="store_true")
    ap.add_argument("--summary", action="store_true")
    ap.add_argument("--compact-summary", dest="compact_summary", action="store_true")
    ap.add_argument("--raw", action="store_true")
    ap.add_argument("--name-only", dest="name_only", action="store_true")
    ap.add_argument("--name-status", dest="name_status", action="store_true")
    # Shared patch-rendering options threaded into the _DiffOpts renderer.
    ap.add_argument("--no-prefix", dest="no_prefix", action="store_true")
    ap.add_argument("--src-prefix", dest="src_prefix", default=None)
    ap.add_argument("--dst-prefix", dest="dst_prefix", default=None)
    ap.add_argument("--default-prefix", dest="default_prefix", action="store_true")
    ap.add_argument("--full-index", dest="full_index", action="store_true")
    ap.add_argument("-w", "--ignore-all-space", dest="ignore_all_space", action="store_true")
    ap.add_argument("-b", "--ignore-space-change", dest="ignore_space_change", action="store_true")
    ap.add_argument("--ignore-space-at-eol", dest="ignore_space_at_eol", action="store_true")
    ap.add_argument("--ignore-cr-at-eol", dest="ignore_cr_at_eol", action="store_true")
    # --clear-decorations resets the (unsupported) --decorate-refs filters; a
    # no-op here since show never applies decoration ref filters.
    ap.add_argument("--clear-decorations", dest="clear_decorations", action="store_true")
    # --patch-with-stat / --patch-with-raw synonyms (resolved by order resolver).
    ap.add_argument("--patch-with-stat", dest="_pws", action="store_true")
    ap.add_argument("--patch-with-raw", dest="_pwr", action="store_true")
    ap.add_argument("--oneline", action="store_true")
    ap.add_argument("--format", default=None)
    ap.add_argument("--pretty", nargs="?", const="medium", default=None)
    ap.add_argument("--date", default=None)
    ap.add_argument("--abbrev", type=int, default=7)
    ap.add_argument("--no-abbrev", dest="no_abbrev", action="store_true")
    ap.add_argument("-U", "--unified", type=int, default=3)
    ap.add_argument("--use-mailmap", "--mailmap", dest="use_mailmap", action="store_true")
    ap.add_argument("--no-use-mailmap", "--no-mailmap", dest="no_use_mailmap", action="store_true")
    ap.add_argument("-L", dest="line_ranges", action="append", default=None)
    ap.add_argument("rev", nargs="*")
    raw_argv = list(argv)
    word_diff_mode = None
    word_regex_src = None
    _wd_argv = []
    for a in argv:
        if a == "--word-diff":
            word_diff_mode = "plain"
        elif a.startswith("--word-diff="):
            word_diff_mode = a.split("=", 1)[1]
        elif a.startswith("--word-diff-regex="):
            word_regex_src = a.split("=", 1)[1]
            if word_diff_mode is None:
                word_diff_mode = "plain"
        else:
            _wd_argv.append(a)
    args = ap.parse_args(_wd_argv)
    args.word_diff = word_diff_mode
    import re as _re_mod
    args.word_regex = _re_mod.compile(word_regex_src) if word_regex_src else None
    if args.no_abbrev:
        args.abbrev = _repo().hex_len
    if args.line_ranges:
        # `show -L` digs from a single commit and renders only it; -s/-q suppress
        # the patch.  Map show's flags onto the shared line-log driver.
        args.no_patch = args.no_patch or args.quiet
        args.pos = args.rev
        return _run_line_log(_repo(), args, mode="show")
    # Resolve the surviving output format in command-line order. show's default
    # output is a patch, so an absent set means patch. -q/--quiet sets NO_OUTPUT
    # early in the revision parser (before the in-order diff options), so a later
    # -p/--stat/--raw overrides it; model that by hoisting -q to the front. -s
    # stays in true command-line order.
    sh_argv = [t for t in raw_argv if t not in ("-q", "--quiet")]
    if any(t in ("-q", "--quiet") for t in raw_argv):
        sh_argv = ["--no-patch"] + sh_argv
    out_fmt, fmt_conflict = _resolve_diff_output_format(sh_argv)
    # diff_setup_done() rejects more than one of {--name-only, --name-status,
    # --check, -s} with rc 128.
    if fmt_conflict:
        _err("fatal: options '--name-only', '--name-status', '--check', and '-s' "
             "cannot be used together")
        return 128
    # If the user passed *no* format flag and no -s/-q, show defaults to patch.
    no_fmt_flag = not any(
        t.split("=", 1)[0] in _DIFF_FORMAT_BIT_FLAGS
        or t.split("=", 1)[0] in ("-p", "--patch", "-u", "-s", "--no-patch", "-q",
                                  "--quiet", "--patch-with-stat", "--patch-with-raw")
        for t in raw_argv)
    if no_fmt_flag:
        out_fmt = {"patch"}
    args.patch = "patch" in out_fmt
    args.stat = "stat" in out_fmt
    args.shortstat = "shortstat" in out_fmt
    args.numstat = "numstat" in out_fmt
    args.summary = "summary" in out_fmt
    args.compact_summary = "compact_summary" in out_fmt
    args.name_only = "name_only" in out_fmt
    args.name_status = "name_status" in out_fmt
    args.raw = "raw" in out_fmt
    args.no_patch = not out_fmt  # nothing survived -> NO_OUTPUT
    repo = _repo()
    from . import mailmap as _mailmap
    mm_show = None if args.no_use_mailmap else _mailmap.load(repo)
    # Patch-rendering options shared with the renderer (prefix flags order-aware).
    _a_pfx, _b_pfx = _resolve_diff_prefixes(raw_argv)
    show_dopts = _DiffOpts(
        a_prefix=_a_pfx, b_prefix=_b_pfx,
        full_index=args.full_index, abbrev=args.abbrev,
        ignore_all_space=args.ignore_all_space,
        ignore_space_change=args.ignore_space_change,
        ignore_space_at_eol=args.ignore_space_at_eol,
        ignore_cr_at_eol=args.ignore_cr_at_eol,
        word_diff=args.word_diff, word_regex=args.word_regex,
    )
    # `--format=<builtin>` is an alias for `--pretty=<builtin>`.
    if args.format in ("oneline", "short", "medium", "full", "fuller", "raw", "reference"):
        args.pretty, args.format = args.format, None
    # `--pretty=oneline` selects the ONELINE format (header "%H %s", no blank
    # line before the diff), same as --oneline but with the full commit id.
    if args.pretty == "oneline":
        args.oneline = True
    pstyle = args.pretty if args.pretty in ("full", "fuller", "short", "raw", "reference", "email", "mboxrd") else "medium"
    date_mode = args.date or "default"
    fmt = args.format
    if fmt is None and args.pretty:
        if args.pretty.startswith("format:") or args.pretty.startswith("tformat:"):
            fmt = args.pretty.split(":", 1)[1]
        elif args.pretty == "oneline":
            fmt = "%H %s"
        elif "%" in args.pretty:
            fmt = args.pretty
    if fmt is None and args.oneline:
        fmt = "%h %s"

    def _emit_commit_diff_group(parent_tree, btree, *, lead_blank: bool) -> None:
        """Emit the stat/raw/summary/patch group for a (parent_tree, btree)
        pair in git's diff_flush order, with the verbose-header lead separator
        (a blank line, or '---' when both a diffstat and a patch are shown)."""
        if args.no_patch:
            return
        tchanges = _tree_changes(repo, parent_tree, btree)
        if lead_blank:
            if (args.stat or args.compact_summary) and args.patch:
                _print("---")
            else:
                _print("")
        separator = False
        # RAW / NAME / NAME_STATUS share one block (diff.c flush_one_pair):
        # name-status > name-only > raw within that group.
        if args.raw or args.name_only or args.name_status:
            if args.name_status:
                for path, a, b in tchanges:
                    st = "A" if not a.present else ("D" if not b.present else "M")
                    _print(f"{st}\t{path}")
            elif args.name_only:
                for path, _a, _b in tchanges:
                    _print(path)
            else:
                _emit_raw_diff(repo, parent_tree, btree, abbrev=args.abbrev)
            separator = True
        if args.numstat:
            _diff_numstat(tchanges)
            separator = True
        if args.compact_summary:
            _diff_stat(tchanges, compact_summary=True)
            separator = True
        elif args.stat:
            _diff_stat(tchanges)
            separator = True
        if args.shortstat:
            _diff_shortstat(tchanges)
            separator = True
        if args.summary:
            _diff_summary(tchanges)
            separator = True
        if args.patch:
            if separator:
                _print("")
            for path, a, b in tchanges:
                _emit_file_diff(path, a, b, context=args.unified, opts=show_dopts)

    def _show_one(the_rev: str) -> int:
        sha = refs_mod.rev_parse(repo, the_rev)
        if not sha:
            _err(f"fatal: ambiguous argument '{the_rev}': unknown revision or path not in the working tree.")
            _err("Use '--' to separate paths from revisions, like this:")
            _err("'git <command> [<revision>...] -- [<file>...]'")
            return 128
        if fmt is not None:
            peeled = refs_mod.rev_parse(repo, the_rev + "^{commit}") or sha
            c = objs.parse_commit(objs.read_object(repo, peeled)[1])
            # commit_format_is_empty: an empty user format emits no header text,
            # no terminator newline, and no blank line before the diff. The
            # ONELINE format (--oneline) also suppresses the blank line before
            # the diff (log-tree.c line 944).
            fmt_is_empty = fmt == ""
            if not fmt_is_empty:
                # The --format terminator newline is unconditional (so %B, which
                # ends in a newline, yields a trailing blank line) — like git.
                sys.stdout.write(_expand_commit_format(repo, peeled, c, fmt, {},
                                                       date_mode=date_mode, abbrev=args.abbrev) + "\n")
            ptree = None
            if c.parents:
                ptree = objs.parse_commit(objs.read_object(repo, c.parents[0])[1]).tree
            # A merge has no default (non-combined) diff in show.
            if len(c.parents) <= 1:
                _emit_commit_diff_group(
                    ptree, c.tree,
                    lead_blank=not fmt_is_empty and not args.oneline)
            return 0
        return _show_object(the_rev, sha)

    def _show_object(the_rev: str, sha: str) -> int:
        t, data = objs.read_object(repo, sha)
        if t == "tag":
            # Print the annotated-tag header, then peel to its target.
            header, _, tagmsg = data.decode("utf-8", errors="replace").partition("\n\n")
            tag_name = ""
            tagger = ""
            target = None
            for line in header.splitlines():
                key, _, val = line.partition(" ")
                if key == "tag":
                    tag_name = val
                elif key == "tagger":
                    tagger = val
                elif key == "object":
                    target = val.strip()
            _print(f"tag {tag_name}")
            if tagger:
                _print(f"Tagger: {_split_ident(tagger)[0]}")
                _print(f"Date:   {_format_date(tagger, date_mode)}")
            _print("")
            _print(tagmsg.rstrip("\n"))
            _print("")
            if target:
                sha = target
                t, data = objs.read_object(repo, sha)
        if t == "commit":
            c = objs.parse_commit(data)
            if pstyle == "reference":
                first = c.message.splitlines()[0] if c.message.strip() else ""
                _print(f"{sha[:7]} ({first}, {_format_date(c.author, 'short')})")
            elif pstyle == "raw":
                _print(f"commit {sha}")
                _print(f"tree {c.tree}")
                for p in c.parents:
                    _print(f"parent {p}")
                _print(f"author {c.author}")
                _print(f"committer {c.committer}")
                _print("")
                for line in c.message.rstrip("\n").splitlines():
                    _print(f"    {line}")
            elif pstyle == "short":
                _print(f"commit {sha}")
                if len(c.parents) > 1:
                    _print("Merge: " + " ".join(p[:args.abbrev] for p in c.parents))
                _print(f"Author: {_mapped_who(_split_ident(c.author)[0], mm_show)}")
                _print("")
                first = c.message.splitlines()[0] if c.message.strip() else ""
                _print(f"    {first}")
            elif pstyle in ("email", "mboxrd"):
                _emit_email_commit(sha, c, mailmap=mm_show)
            else:
                _emit_commit_header(sha, c, style=pstyle, date_mode=date_mode, mailmap=mm_show,
                                    abbrev=args.abbrev)
                _print("")
                for line in c.message.rstrip("\n").splitlines():
                    _print(f"    {line}")
            parent_tree = None
            if c.parents:
                _, pd = objs.read_object(repo, c.parents[0])
                parent_tree = objs.parse_commit(pd).tree
            # For a merge, the default (combined) patch and raw output collapse to
            # empty for a clean merge, but git still prints the separating blank
            # line. '--stat' is special: it reports against the first parent.
            is_merge = len(c.parents) > 1
            if is_merge:
                # No non-combined diff; git still prints the trailing blank line
                # unless the output format is NO_OUTPUT (-s/-q). --stat reports
                # against the first parent even for a merge.
                if not args.no_patch:
                    if args.stat:
                        _print("")
                        _diff_stat(_tree_changes(repo, parent_tree, c.tree))
                    else:
                        _print("")
            else:
                _emit_commit_diff_group(parent_tree, c.tree, lead_blank=True)
        elif t == "tree":
            # `git show <tree>` prints `<rev>\n\n` then bare entry names
            # (directories suffixed with '/'), not the ls-tree triple.
            _print(f"tree {the_rev}")
            _print("")
            for e in objs.parse_tree(data, repo.hash_len):
                _print(e.name + ("/" if e.is_dir() else ""))
        else:
            sys.stdout.buffer.write(data)
            if not data.endswith(b"\n"):
                sys.stdout.write("\n")
        return 0

    revs = args.rev or ["HEAD"]
    multiline = fmt is None and pstyle in ("medium", "full", "fuller", "short", "raw", "email", "mboxrd")
    for count, the_rev in enumerate(revs):
        if count > 0 and multiline:
            _print("")
        rc = _show_one(the_rev)
        if rc:
            return rc
    return 0


def _tree_changes(repo: Repository, a_tree: Optional[str], b_tree: Optional[str]) -> list[tuple[str, "_Side", "_Side"]]:
    a_map = _tree_map_full(repo, a_tree)
    b_map = _tree_map_full(repo, b_tree)
    changes: list[tuple[str, _Side, _Side]] = []
    for p in sorted(set(a_map) | set(b_map)):
        a = _side_from_object(repo, *a_map[p]) if p in a_map else _ABSENT
        b = _side_from_object(repo, *b_map[p]) if p in b_map else _ABSENT
        if a.sha != b.sha or a.mode != b.mode:
            changes.append((p, a, b))
    return changes


def _emit_raw_diff(repo: Repository, a_tree: Optional[str], b_tree: Optional[str],
                   abbrev: int = 7) -> None:
    """Emit ``git log --raw`` style lines: ``:<amode> <bmode> <asha> <bsha> <st>\\t<path>``.
    ``abbrev`` controls the blob-id width (--abbrev/--no-abbrev)."""
    zero = "0" * abbrev
    for path, a, b in _tree_changes(repo, a_tree, b_tree):
        status = "A" if not a.present else ("D" if not b.present else "M")
        a_sha = a.sha[:abbrev] if a.present else zero
        b_sha = b.sha[:abbrev] if b.present else zero
        a_mode = (a.mode or "000000").zfill(6)
        b_mode = (b.mode or "000000").zfill(6)
        _print(f":{a_mode} {b_mode} {a_sha} {b_sha} {status}\t{path}")


def _emit_tree_patch(repo: Repository, a_tree: Optional[str], b_tree: Optional[str], context: int = 3) -> None:
    for path, a, b in _tree_changes(repo, a_tree, b_tree):
        _emit_file_diff(path, a, b, context=context)


def _print_tree_diff(repo: Repository, a_tree: str, b_tree: str) -> None:
    for p, a_entry, b_entry in workdir.iter_tree_changes(repo, a_tree, b_tree):
        a_sha = a_entry.sha if a_entry else None
        b_sha = b_entry.sha if b_entry else None
        if a_sha == b_sha:
            continue
        a_text = ""
        b_text = ""
        if a_sha:
            _, d = objs.read_object(repo, a_sha)
            a_text = d.decode("utf-8", errors="replace")
        if b_sha:
            _, d = objs.read_object(repo, b_sha)
            b_text = d.decode("utf-8", errors="replace")
        out = diff_mod.unified_diff(a_text, b_text, f"a/{p}", f"b/{p}")
        if out:
            _print(f"diff --git a/{p} b/{p}")
            _print(out.rstrip("\n"))


class _Side:
    __slots__ = ("mode", "sha", "data", "worktree")

    def __init__(self, mode: Optional[str], sha: Optional[str], data: Optional[bytes], worktree: bool = False):
        self.mode = mode
        self.sha = sha
        self.data = data
        self.worktree = worktree

    @property
    def present(self) -> bool:
        return self.mode is not None


_ABSENT = _Side(None, None, None)


def _side_from_object(repo: Repository, mode: Optional[str], sha: Optional[str]) -> _Side:
    if sha is None:
        return _ABSENT
    try:
        _, data = objs.read_object(repo, sha)
    except KeyError:
        data = b""
    return _Side(mode, sha, data)


def _side_from_worktree(repo: Repository, path: str) -> _Side:
    full = repo.path / path
    if not (full.exists() or full.is_symlink()):
        return _ABSENT
    import stat as _stat
    if full.is_symlink():
        data = os.readlink(full).encode("utf-8")
    else:
        data = full.read_bytes()
    sha, _ = objs.hash_bytes("blob", data, repo)
    return _Side(_wt_mode(full), sha, data, worktree=True)


def _tree_map_full(repo: Repository, tree_sha: Optional[str]) -> dict[str, tuple[str, str]]:
    out: dict[str, tuple[str, str]] = {}
    if tree_sha:
        for path, mode, sha in workdir.iter_tree_files(repo, tree_sha):
            out[path] = (mode, sha)
    return out


def _commit_tree(repo: Repository, sha: str) -> Optional[str]:
    try:
        t, data = objs.read_object(repo, sha)
    except KeyError:
        return None
    if t == "commit":
        return objs.parse_commit(data).tree
    if t == "tree":
        return sha
    if t == "tag":
        return refs_mod._peel_to_type(repo, sha, "tree")
    return None


def _is_binary(data: Optional[bytes]) -> bool:
    return bool(data) and b"\x00" in data[:8000]


def _ws_check_line(line: str) -> str:
    """Return git's whitespace-error message(s) for an added line, under the
    default rule (blank-at-eol + space-before-tab), or "" if clean. Ported from
    ws.c:ws_check_emit. (blank-at-eof is hunk-level and intentionally omitted.)"""
    stripped = line.rstrip(" \t")
    parts: list[str] = []
    if len(stripped) < len(line):
        parts.append("trailing whitespace")
    # space-before-tab: a tab in the leading indent preceded by a space.
    n = len(stripped)
    i = 0
    written = 0
    sbt = False
    while i < n:
        ch = line[i]
        if ch == " ":
            i += 1
            continue
        if ch != "\t":
            break
        if written < i:
            sbt = True
        written = i + 1
        i += 1
    if sbt:
        parts.append("space before tab in indent")
    return ", ".join(parts)


def _follow_rename_source(repo: Repository, ptree: Optional[str], tree: Optional[str], dst: str) -> Optional[str]:
    """For `log --follow`: if ``dst`` was created in ``tree`` by renaming a file
    that existed in ``ptree``, return that source path (else None)."""
    changes = _tree_changes(repo, ptree, tree)
    renames, _ = _detect_changes_renames(repo, changes)
    for entry in renames:
        if entry[1] == dst:
            return entry[0]
    return None


def _diff_check(repo: Repository, changes: list) -> int:
    """`git diff --check`: report whitespace errors on added lines, suppressing
    the normal diff. Returns 2 if any error is found, else 0."""
    from . import diff as _diff
    found = False
    for path, a, b in changes:
        if not b.present or _is_binary(b.data):
            continue
        a_text = a.data.decode("utf-8", "replace") if (a.present and a.data is not None) else ""
        b_text = b.data.decode("utf-8", "replace") if b.data is not None else ""
        a_lines = a_text.split("\n")
        b_lines = b_text.split("\n")
        if a_text.endswith("\n"):
            a_lines = a_lines[:-1]
        if b_text.endswith("\n"):
            b_lines = b_lines[:-1]
        for kind, _ai, bi in _diff.diff_lines(a_lines, b_lines):
            if kind != "ins":
                continue
            msg = _ws_check_line(b_lines[bi])
            if msg:
                found = True
                _print(f"{path}:{bi + 1}: {msg}.")
                _print(f"+{b_lines[bi]}")
    return 2 if found else 0


class _DiffOpts:
    """Bundle of patch-rendering options shared by diff/log -p/show -p/diff-tree.

    Mirrors the subset of ``struct diff_options`` that affects the textual
    patch: path prefixes (--no-prefix, --src-prefix/--dst-prefix), index-line
    width (--full-index, --abbrev=<n>), whitespace-ignore flags (-b/-w/...),
    and --word-diff[-regex]. ``None`` opts everywhere preserves defaults.
    """
    __slots__ = ("a_prefix", "b_prefix", "full_index", "abbrev",
                 "ignore_all_space", "ignore_space_change", "ignore_space_at_eol",
                 "ignore_cr_at_eol", "word_diff", "word_regex")

    def __init__(self, a_prefix: str = "a/", b_prefix: str = "b/",
                 full_index: bool = False, abbrev: int = 7,
                 ignore_all_space: bool = False, ignore_space_change: bool = False,
                 ignore_space_at_eol: bool = False, ignore_cr_at_eol: bool = False,
                 word_diff=None, word_regex=None):
        self.a_prefix = a_prefix
        self.b_prefix = b_prefix
        self.full_index = full_index
        self.abbrev = abbrev
        self.ignore_all_space = ignore_all_space
        self.ignore_space_change = ignore_space_change
        self.ignore_space_at_eol = ignore_space_at_eol
        self.ignore_cr_at_eol = ignore_cr_at_eol
        self.word_diff = word_diff
        self.word_regex = word_regex


_DEFAULT_DIFF_OPTS = _DiffOpts()


# Mapping of output-format flags to the bit they OR into output_format. These
# are git's OPT_BIT/OPT_BITOP entries (diff.c). `-p`/`-u`/`--patch` also clear
# the NO_OUTPUT bit; `-s`/`--no-patch` *reset* the whole format to NO_OUTPUT.
_DIFF_FORMAT_BIT_FLAGS = {
    "--raw": "raw", "--numstat": "numstat", "--shortstat": "shortstat",
    "--summary": "summary", "--name-only": "name_only",
    "--name-status": "name_status", "--stat": "stat",
    "--compact-summary": "compact_summary",
}


def _resolve_diff_output_format(argv: list[str]) -> tuple[set, bool]:
    """Replay the diff output-format flags in command-line order, mirroring
    diff.c's bit semantics + diff_setup_done() post-processing.

    Per-flag (command-line order):
    - ``-p``/``--patch``/``-u`` and ``--stat``/``--raw``/etc. add their bit and
      clear "no_output";
    - ``-s``/``--no-patch`` reset the format to just {"no_output"}.

    diff_setup_done() then enforces two rules:
    1. more than one of {name_only, name_status, no_output} -> conflict;
    2. any of {name_only, name_status, no_output} set -> drop raw/numstat/stat/
       shortstat/summary/patch.

    Returns ``(format_set, conflict)``. ``format_set`` excludes "no_output"
    (an empty set means the diff machinery prints nothing).
    """
    # name-only/name-status/check are OPT_BIT_F: they only OR their bit and do
    # NOT clear NO_OUTPUT (so "-s --name-status" leaves both bits set -> the
    # diff_setup_done conflict fires). All other format flags are OPT_BITOP /
    # callbacks that clear NO_OUTPUT first.
    _NO_CLEAR = {"name_only", "name_status"}
    fmt: set = set()
    for tok in argv:
        if tok == "--":
            break
        base = tok.split("=", 1)[0]
        if base in ("-p", "--patch", "-u"):
            fmt.discard("no_output")
            fmt.add("patch")
        elif base in ("-s", "--no-patch"):
            fmt = {"no_output"}
        elif base == "--patch-with-stat":
            fmt.discard("no_output")
            fmt.update(("stat", "patch"))
        elif base == "--patch-with-raw":
            fmt.discard("no_output")
            fmt.update(("raw", "patch"))
        elif base in ("--stat-width", "--stat-name-width", "--stat-graph-width",
                      "--stat-count"):
            # diff_opt_stat: these synonyms also request --stat output.
            fmt.discard("no_output")
            fmt.add("stat")
        elif base in _DIFF_FORMAT_BIT_FLAGS:
            name = _DIFF_FORMAT_BIT_FLAGS[base]
            if name not in _NO_CLEAR:
                fmt.discard("no_output")
            fmt.add(name)
    # Rule 1: HAS_MULTI_BITS(NAME | NAME_STATUS | CHECKDIFF | NO_OUTPUT).
    check_bits = sum(1 for k in ("name_only", "name_status", "no_output") if k in fmt)
    conflict = check_bits > 1
    # Rule 2: NAME/NAME_STATUS/NO_OUTPUT turn off the other output formats.
    if fmt & {"name_only", "name_status", "no_output"}:
        fmt -= {"raw", "numstat", "stat", "compact_summary", "shortstat",
                "summary", "patch"}
    fmt.discard("no_output")
    return fmt, conflict


def _resolve_diff_prefixes(argv: list[str]) -> tuple[str, str]:
    """Replay the prefix flags in command-line order, mirroring diff.c's
    last-wins callbacks: --no-prefix / --default-prefix reset both sides;
    --src-prefix / --dst-prefix replace a single side. Returns (a_prefix,
    b_prefix), each already carrying its trailing slash (empty under
    --no-prefix)."""
    a_pfx, b_pfx = "a/", "b/"
    for tok in argv:
        if tok == "--":
            break
        if tok == "--no-prefix":
            a_pfx = b_pfx = ""
        elif tok == "--default-prefix":
            a_pfx, b_pfx = "a/", "b/"
        elif tok.startswith("--src-prefix="):
            a_pfx = tok.split("=", 1)[1]
        elif tok.startswith("--dst-prefix="):
            b_pfx = tok.split("=", 1)[1]
    return a_pfx, b_pfx


def _index_abbrev(opts: "_DiffOpts", sha: Optional[str]) -> str:
    """Render an object id for the ``index`` line, honoring --full-index and
    --abbrev=<n>. git uses the abbreviation length on the index line and the
    full 40-hex form under --full-index."""
    full = sha or ("0" * 40)
    if opts.full_index:
        return full
    return full[:opts.abbrev]


def _emit_file_diff(path: str, a: _Side, b: _Side, reverse: bool = False, context: int = 3,
                    word_diff=None, a_prefix: str = "a", b_prefix: str = "b",
                    inter_hunk_context: int = 0, opts: "Optional[_DiffOpts]" = None,
                    output_indicators=None) -> None:
    if a.sha == b.sha and a.mode == b.mode:
        return
    # --output-indicator-{new,old,context}: per-line sign overrides.
    oi_new, oi_old, oi_ctx = output_indicators if output_indicators else ("+", "-", " ")
    if opts is None:
        opts = _DiffOpts(a_prefix=a_prefix + "/" if a_prefix else "",
                         b_prefix=b_prefix + "/" if b_prefix else "",
                         word_diff=word_diff)
    elif word_diff is not None:
        opts.word_diff = word_diff
    # Under -R the working-side prefixes are swapped. Prefixes already carry
    # their trailing slash (empty under --no-prefix).
    pa, pb = (opts.b_prefix, opts.a_prefix) if reverse else (opts.a_prefix, opts.b_prefix)
    a_label = pa + path if a.present else "/dev/null"
    b_label = pb + path if b.present else "/dev/null"
    ws_active = (opts.ignore_all_space or opts.ignore_space_change
                 or opts.ignore_space_at_eol or opts.ignore_cr_at_eol)
    # Precompute the hunk body for a pure-content modification so a
    # whitespace-only change (no visible body) suppresses the whole file pair,
    # exactly like git's whitespace-ignore output (no diff --git/index header).
    precomputed_body = None
    content_only = (a.present and b.present and a.mode == b.mode and a.sha != b.sha
                    and not (opts.word_diff)
                    and not (_is_binary(a.data) or _is_binary(b.data)))
    if content_only:
        a_text = (a.data or b"").decode("utf-8", errors="replace")
        b_text = (b.data or b"").decode("utf-8", errors="replace")
        precomputed_body = diff_mod.format_hunks_ex(
            a_text.splitlines(), b_text.splitlines(),
            context,
            a_no_newline=bool(a_text) and not a_text.endswith("\n"),
            b_no_newline=bool(b_text) and not b_text.endswith("\n"),
            inter_hunk_context=inter_hunk_context,
            ignore_all_space=opts.ignore_all_space,
            ignore_space_change=opts.ignore_space_change,
            ignore_space_at_eol=opts.ignore_space_at_eol,
            ignore_cr_at_eol=opts.ignore_cr_at_eol,
            new_ind=oi_new, old_ind=oi_old, ctx_ind=oi_ctx,
        )
        if ws_active and not precomputed_body:
            return
    # The "diff --git" header drops the trailing slash separator handling: git
    # prints "diff --git <pa><path> <pb><path>"; with empty prefixes this is
    # "diff --git <path> <path>".
    _print(f"diff --git {pa}{path} {pb}{path}")
    if not a.present:
        _print(f"new file mode {b.mode}")
    elif not b.present:
        _print(f"deleted file mode {a.mode}")
    elif a.mode != b.mode:
        _print(f"old mode {a.mode}")
        _print(f"new mode {b.mode}")
    if a.sha != b.sha:
        suffix = f" {a.mode}" if a.present and b.present and a.mode == b.mode else ""
        _print(f"index {_index_abbrev(opts, a.sha)}..{_index_abbrev(opts, b.sha)}{suffix}")
        if _is_binary(a.data) or _is_binary(b.data):
            _print(f"Binary files {a_label} and {b_label} differ")
            return
        a_text = (a.data or b"").decode("utf-8", errors="replace")
        b_text = (b.data or b"").decode("utf-8", errors="replace")
        if opts.word_diff:
            _print(f"--- {a_label}")
            _print(f"+++ {b_label}")
            sys.stdout.write(diff_mod.word_diff_hunks(
                a_text.splitlines(), b_text.splitlines(), context, mode=opts.word_diff,
                word_regex=opts.word_regex))
            return
        if precomputed_body is not None:
            body = precomputed_body
        else:
            body = diff_mod.format_hunks_ex(
                a_text.splitlines(), b_text.splitlines(),
                context,
                a_no_newline=bool(a_text) and not a_text.endswith("\n"),
                b_no_newline=bool(b_text) and not b_text.endswith("\n"),
                inter_hunk_context=inter_hunk_context,
                ignore_all_space=opts.ignore_all_space,
                ignore_space_change=opts.ignore_space_change,
                ignore_space_at_eol=opts.ignore_space_at_eol,
                ignore_cr_at_eol=opts.ignore_cr_at_eol,
                new_ind=oi_new, old_ind=oi_old, ctx_ind=oi_ctx,
            )
        # git emits the ---/+++ file header only when there is a hunk body
        # (an empty new/deleted file stops after the `index` line).
        if body:
            _print(f"--- {a_label}")
            _print(f"+++ {b_label}")
            for line in body:
                _print(line)


def _pprint_rename(a: str, b: str) -> str:
    """Port of diff.c pprint_rename: render 'a => b' compactly by factoring out a
    common directory prefix and suffix, e.g. 'dir/{x => y}' or '{a => b}/sfx'."""
    # If either path needs C-style quoting, git falls back to 'a => b'.
    len_a, len_b = len(a), len(b)
    # common prefix ending at a slash
    pfx_length = 0
    i = 0
    while i < len_a and i < len_b and a[i] == b[i]:
        if a[i] == "/":
            pfx_length = i + 1
        i += 1
    # common suffix (may run 1 into the prefix slash)
    pfx_adjust = 1 if pfx_length else 0
    sfx_length = 0
    oa = len_a
    ob = len_b
    while (pfx_length - pfx_adjust <= oa - 1 and
           pfx_length - pfx_adjust <= ob - 1 and
           oa - 1 >= 0 and ob - 1 >= 0 and a[oa - 1] == b[ob - 1]):
        if a[oa - 1] == "/":
            sfx_length = len_a - (oa - 1)
        oa -= 1
        ob -= 1
    a_mid = max(0, len_a - pfx_length - sfx_length)
    b_mid = max(0, len_b - pfx_length - sfx_length)
    out = []
    if pfx_length + sfx_length:
        out.append(a[:pfx_length])
        out.append("{")
    out.append(a[pfx_length:pfx_length + a_mid])
    out.append(" => ")
    out.append(b[pfx_length:pfx_length + b_mid])
    if pfx_length + sfx_length:
        out.append("}")
        out.append(a[len_a - sfx_length:])
    return "".join(out)


def _compact_summary_comment(a: _Side, b: _Side, is_renamed: bool) -> str:
    """Port of diff.c:get_compact_summary — the ' (<comment>)' suffix that
    --compact-summary appends to a stat row's name."""
    def is_lnk(mode):
        return mode is not None and mode.startswith("120")
    def perm(mode):
        try:
            return int(mode, 8) & 0o777
        except (TypeError, ValueError):
            return 0
    if not is_renamed:
        if not a.present and b.present:  # ADDED
            if is_lnk(b.mode):
                return "new +l"
            if perm(b.mode) == 0o755:
                return "new +x"
            return "new"
        if a.present and not b.present:  # DELETED
            return "gone"
    if is_lnk(a.mode) and not is_lnk(b.mode):
        return "mode -l"
    if not is_lnk(a.mode) and is_lnk(b.mode):
        return "mode +l"
    if perm(a.mode) == 0o644 and perm(b.mode) == 0o755:
        return "mode +x"
    if perm(a.mode) == 0o755 and perm(b.mode) == 0o644:
        return "mode -x"
    return ""


def _diff_stat(changes: list[tuple[str, _Side, _Side]], renames=None,
               complete=None, order=None, unmerged=None,
               compact_summary: bool = False) -> None:
    # rows carry (sort_key, name, ins, del, total); sort_key orders the output
    # by the diff queue (via ``order`` map keyed on dst/path) when provided.
    # ``unmerged`` rows render as "<name> | Unmerged" (total == -2) and never
    # contribute to the summary line.
    rows: list[tuple, ...] = []
    total_ins = total_del = 0
    complete = complete or {}
    order = order or {}
    for _k, name in (unmerged or []):
        rows.append((_k, name, 0, 0, -2))
    for src, dst, _sim, src_side, dst_side in (renames or []):
        a_lines = (src_side.data or b"").decode("utf-8", errors="replace").splitlines()
        b_lines = (dst_side.data or b"").decode("utf-8", errors="replace").splitlines()
        ins = dele = 0
        for op in diff_mod.diff_lines(a_lines, b_lines):
            if op[0] == "ins":
                ins += 1
            elif op[0] == "del":
                dele += 1
        name = _pprint_rename(src, dst)
        if compact_summary:
            cmt = _compact_summary_comment(src_side, dst_side, True)
            if cmt:
                name += f" ({cmt})"
        rows.append((order.get(dst, len(rows)), name, ins, dele, ins + dele))
        total_ins += ins
        total_del += dele
    for path, a, b in changes:
        if a.sha == b.sha and a.mode == b.mode:
            continue
        name = path
        if compact_summary:
            cmt = _compact_summary_comment(a, b, False)
            if cmt:
                name += f" ({cmt})"
        if _is_binary(a.data) or _is_binary(b.data):
            rows.append((order.get(path, len(rows)), name, -1, -1, -1))
            continue
        if path in complete:
            ins, dele = complete[path]
        else:
            a_lines = (a.data or b"").decode("utf-8", errors="replace").splitlines()
            b_lines = (b.data or b"").decode("utf-8", errors="replace").splitlines()
            ins = dele = 0
            for op in diff_mod.diff_lines(a_lines, b_lines):
                if op[0] == "ins":
                    ins += 1
                elif op[0] == "del":
                    dele += 1
        rows.append((order.get(path, len(rows)), name, ins, dele, ins + dele))
        total_ins += ins
        total_del += dele
    if not rows:
        return
    if order:
        rows.sort(key=lambda r: r[0])
    name_w = max(len(r[1]) for r in rows)
    count_w = max(len(str(t if t >= 0 else 0)) for *_, t in rows)
    n_files = 0
    for _k, path, ins, dele, total in rows:
        if total == -2:
            _print(f" {path:<{name_w}} | Unmerged")
            continue
        n_files += 1
        if total < 0:
            _print(f" {path:<{name_w}} | Bin")
            continue
        bar = "+" * ins + "-" * dele
        _print(f" {path:<{name_w}} | {total:>{count_w}}{(' ' + bar) if bar else ''}")
    if n_files == 0:
        # All rows were unmerged: git prints just " 0 files changed".
        _print(" 0 files changed")
    else:
        _print(_stat_summary_line(n_files, total_ins, total_del))


def _diff_shortstat(changes: list[tuple[str, _Side, _Side]]) -> None:
    """Print only C Git's ``--shortstat`` summary line for a set of changes."""
    files = total_ins = total_del = 0
    for _path, a, b in changes:
        if a.sha == b.sha and a.mode == b.mode:
            continue
        files += 1
        if _is_binary(a.data) or _is_binary(b.data):
            continue
        a_lines = (a.data or b"").decode("utf-8", errors="replace").splitlines()
        b_lines = (b.data or b"").decode("utf-8", errors="replace").splitlines()
        for op in diff_mod.diff_lines(a_lines, b_lines):
            if op[0] == "ins":
                total_ins += 1
            elif op[0] == "del":
                total_del += 1
    if files == 0:
        return
    _print(_stat_summary_line(files, total_ins, total_del))


def _diff_summary(changes: list[tuple[str, _Side, _Side]], renames=None) -> None:
    """Print C Git's ``--summary`` lines (create/delete/mode-change/rename)."""
    lines: list[tuple[str, str]] = []
    for src, dst, sim, _sa, _db in (renames or []):
        lines.append((dst, f" rename {src} => {dst} ({sim}%)"))
    for path, a, b in changes:
        if not a.present and b.present:
            lines.append((path, f" create mode {(b.mode or '000000').zfill(6)} {path}"))
        elif a.present and not b.present:
            lines.append((path, f" delete mode {(a.mode or '000000').zfill(6)} {path}"))
        elif a.present and b.present and a.mode != b.mode:
            lines.append((path, f" mode change {a.mode} => {b.mode} {path}"))
    for _key, line in sorted(lines):
        _print(line)


def _stat_summary_line(files: int, insertions: int, deletions: int) -> str:
    """Render C Git's ' N files changed, X insertions(+), Y deletions(-)' line,
    showing the zero parts only when both counts are zero."""
    parts = [f"{files} file{'s' if files != 1 else ''} changed"]
    if insertions or deletions == 0:
        parts.append(f"{insertions} insertion{'s' if insertions != 1 else ''}(+)")
    if deletions or insertions == 0:
        parts.append(f"{deletions} deletion{'s' if deletions != 1 else ''}(-)")
    return " " + ", ".join(parts)


def _diff_no_index(argv: list[str]) -> int:
    """``git diff --no-index <pathA> <pathB>``: diff two arbitrary filesystem
    paths (works outside any repository). Returns 1 when they differ, 0 when
    identical, matching diff(1) (diff-no-index.c diff_no_index)."""
    diff_raw_argv = list(argv)
    # Strip the --no-index marker and collect the two operands + options.
    a_pfx, b_pfx = _resolve_diff_prefixes(diff_raw_argv)
    unified = 3
    reverse = False
    operands: list[str] = []
    i = 0
    after_dd = False
    while i < len(argv):
        tok = argv[i]
        if after_dd:
            operands.append(tok)
            i += 1
            continue
        if tok == "--":
            after_dd = True
        elif tok == "--no-index":
            pass
        elif tok in ("-R",):
            reverse = True
        elif tok in ("-U", "--unified"):
            unified = int(argv[i + 1]); i += 1
        elif tok.startswith("--unified="):
            unified = int(tok.split("=", 1)[1])
        elif tok.startswith("-U") and tok[2:].isdigit():
            unified = int(tok[2:])
        elif tok.startswith("-"):
            pass  # other options: accepted, not all honored
        else:
            operands.append(tok)
        i += 1
    if len(operands) < 2:
        _err("usage: git diff --no-index [<options>] <path> <path> [<pathspec>...]")
        return 129
    name1, name2 = operands[0], operands[1]

    def _read(path):
        if path == "/dev/null":
            return b"", False
        try:
            with open(path, "rb") as f:
                return f.read(), True
        except FileNotFoundError:
            return None, False
        except IsADirectoryError:
            return None, True

    d1, ok1 = _read(name1)
    d2, ok2 = _read(name2)
    if d1 is None and not ok1:
        _err(f"error: Could not access '{name1}'")
        return 1
    if d2 is None and not ok2:
        _err(f"error: Could not access '{name2}'")
        return 1
    # Build a one-pair diff. The display names are the operands as given (git's
    # mnemonic prefixes default to a/ b/ here for an explicit --no-index).
    import stat as _stat
    def _mode(path):
        # canon_mode (diff.c): regular files are 100644 (100755 if executable),
        # symlinks 120000 — the on-disk group/other bits are not preserved.
        try:
            st = os.lstat(path)
        except OSError:
            return "100644"
        if _stat.S_ISLNK(st.st_mode):
            return "120000"
        return "100755" if (st.st_mode & 0o100) else "100644"
    m1 = _mode(name1) if name1 != "/dev/null" else None
    m2 = _mode(name2) if name2 != "/dev/null" else None
    repo = None
    try:
        repo = _repo()
    except Exception:
        repo = None
    def _hash(data):
        if repo is not None:
            return objs.hash_bytes("blob", data, repo)[0]
        import hashlib
        h = hashlib.sha1()
        h.update(b"blob " + str(len(data)).encode() + b"\x00" + data)
        return h.hexdigest()
    s1 = _Side(m1, _hash(d1 or b""), d1 or b"") if name1 != "/dev/null" else _ABSENT
    s2 = _Side(m2, _hash(d2 or b""), d2 or b"") if name2 != "/dev/null" else _ABSENT
    if s1.sha == s2.sha and s1.mode == s2.mode:
        return 0
    dopts = _DiffOpts(a_prefix=a_pfx, b_prefix=b_pfx)
    # The diff --git header uses the operand names verbatim (with prefixes).
    _emit_no_index_pair(name1, name2, s1, s2, reverse, unified, dopts)
    return 1


def _emit_no_index_pair(name1: str, name2: str, a: _Side, b: _Side, reverse: bool,
                        context: int, opts: "_DiffOpts") -> None:
    """Render a single --no-index file pair (names taken verbatim, not derived
    from a single path as in the in-repo case)."""
    pa, pb = (opts.b_prefix, opts.a_prefix) if reverse else (opts.a_prefix, opts.b_prefix)
    n_a, n_b = (name2, name1) if reverse else (name1, name2)
    a_label = pa + n_a if a.present else "/dev/null"
    b_label = pb + n_b if b.present else "/dev/null"
    _print(f"diff --git {pa}{n_a} {pb}{n_b}")
    if not a.present:
        _print(f"new file mode {b.mode}")
    elif not b.present:
        _print(f"deleted file mode {a.mode}")
    elif a.mode != b.mode:
        _print(f"old mode {a.mode}")
        _print(f"new mode {b.mode}")
    if a.sha != b.sha:
        suffix = f" {a.mode}" if a.present and b.present and a.mode == b.mode else ""
        _print(f"index {_index_abbrev(opts, a.sha)}..{_index_abbrev(opts, b.sha)}{suffix}")
        if _is_binary(a.data) or _is_binary(b.data):
            _print(f"Binary files {a_label} and {b_label} differ")
            return
        a_text = (a.data or b"").decode("utf-8", errors="replace")
        b_text = (b.data or b"").decode("utf-8", errors="replace")
        body = diff_mod.format_hunks_ex(
            a_text.splitlines(), b_text.splitlines(), context,
            a_no_newline=bool(a_text) and not a_text.endswith("\n"),
            b_no_newline=bool(b_text) and not b_text.endswith("\n"))
        if body:
            _print(f"--- {a_label}")
            _print(f"+++ {b_label}")
            for line in body:
                _print(line)


def cmd_diff(argv: list[str]) -> int:
    if "--no-index" in argv:
        return _diff_no_index(argv)
    diff_raw_argv = list(argv)  # before any normalization (for order-sensitive flags)
    ap = argparse.ArgumentParser(prog="pygit diff", add_help=False)
    ap.add_argument("--cached", "--staged", dest="cached", action="store_true")
    ap.add_argument("--stat", action="store_true")
    ap.add_argument("--numstat", action="store_true")
    ap.add_argument("--shortstat", action="store_true")
    ap.add_argument("--summary", action="store_true")
    ap.add_argument("--diff-filter", dest="diff_filter", default=None)
    ap.add_argument("--name-only", dest="name_only", action="store_true")
    ap.add_argument("--name-status", dest="name_status", action="store_true")
    ap.add_argument("--raw", action="store_true")
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--quiet", action="store_true")
    ap.add_argument("--exit-code", dest="exit_code", action="store_true")
    ap.add_argument("-R", dest="reverse", action="store_true")
    ap.add_argument("-U", "--unified", type=int, default=3)
    # Number of equal lines that still merge two adjacent hunks (diff.c
    # OPT_DIFF_INTERHUNK_CONTEXT, default 0); honored by the unified patch path.
    ap.add_argument("--inter-hunk-context", dest="interhunkcontext", type=int, default=0)
    # -M/-C (with optional attached values) are accepted but never consume a
    # following token; rename detection is on by default (diff.renames=true).
    ap.add_argument("--no-renames", dest="no_renames", action="store_true")
    # Patch-rendering options shared with the _DiffOpts renderer.
    ap.add_argument("--no-prefix", dest="no_prefix", action="store_true")
    ap.add_argument("--src-prefix", dest="src_prefix", default=None)
    ap.add_argument("--dst-prefix", dest="dst_prefix", default=None)
    ap.add_argument("--default-prefix", dest="default_prefix", action="store_true")
    ap.add_argument("--full-index", dest="full_index", action="store_true")
    ap.add_argument("--abbrev", dest="abbrev", type=int, default=7)
    ap.add_argument("--compact-summary", dest="compact_summary", action="store_true")
    # Whitespace-ignore flags (xdiff XDF_IGNORE_*). git's -b/-w are short opts.
    ap.add_argument("-w", "--ignore-all-space", dest="ignore_all_space", action="store_true")
    ap.add_argument("-b", "--ignore-space-change", dest="ignore_space_change", action="store_true")
    ap.add_argument("--ignore-space-at-eol", dest="ignore_space_at_eol", action="store_true")
    ap.add_argument("--ignore-cr-at-eol", dest="ignore_cr_at_eol", action="store_true")
    ap.add_argument("-z", dest="nul", action="store_true")
    ap.add_argument("-a", "--text", dest="text", action="store_true")
    # -p/-u/--patch select the patch format (combinable with stat/raw/numstat).
    ap.add_argument("-p", "-u", "--patch", dest="patch", action="store_true")
    ap.add_argument("--patch-with-stat", dest="patch_with_stat", action="store_true")
    ap.add_argument("--patch-with-raw", dest="patch_with_raw", action="store_true")
    ap.add_argument("-s", "--no-patch", dest="no_patch", action="store_true")
    # --output-indicator-{new,old,context} replace the per-line +/-/space sign.
    ap.add_argument("--output-indicator-new", dest="oi_new", default=None)
    ap.add_argument("--output-indicator-old", dest="oi_old", default=None)
    ap.add_argument("--output-indicator-context", dest="oi_context", default=None)
    # `--stat=<width>` only tunes column widths, which do not affect pythongit's
    # output for the file sizes under test; normalize the value form to bare. The
    # `--stat-width=<n>` synonym also requests stat output (diff.c diff_opt_stat).
    argv = ["--stat" if (a.startswith("--stat=") or a.startswith("--stat-width=")
                         or a.startswith("--stat-name-width=")
                         or a.startswith("--stat-graph-width=")
                         or a.startswith("--stat-count=")) else a for a in argv]
    # --dirstat[=<params>] / -X[=<params>] selects per-directory change percents.
    dirstat = False
    dirstat_params = ""
    _ds_argv: list[str] = []
    for a in argv:
        if a == "--dirstat" or a == "-X":
            dirstat = True
        elif a.startswith("--dirstat=") or a.startswith("-X="):
            dirstat = True
            dirstat_params = a.split("=", 1)[1]
        elif a == "--cumulative":
            dirstat = True
            dirstat_params = (dirstat_params + "," if dirstat_params else "") + "cumulative"
        elif a.startswith("--dirstat-by-file"):
            dirstat = True
            dirstat_params = (dirstat_params + "," if dirstat_params else "") + "files"
            if a.startswith("--dirstat-by-file="):
                dirstat_params += "," + a.split("=", 1)[1]
        else:
            _ds_argv.append(a)
    argv = _ds_argv
    # --relative[=<path>] restricts to (and strips the prefix of) a subdirectory.
    relative = None  # None = off; "" = cwd; else the given subdir
    _rel_argv: list[str] = []
    for a in argv:
        if a == "--relative":
            relative = ""
        elif a.startswith("--relative="):
            relative = a.split("=", 1)[1]
        elif a == "--no-relative":
            relative = None
        else:
            _rel_argv.append(a)
    argv = _rel_argv
    # Pickaxe: -S<needle> / -G<regex> (value attached or as the next token),
    # plus --pickaxe-all / --pickaxe-regex (diffcore_pickaxe).
    ap.add_argument("--pickaxe-all", dest="pickaxe_all", action="store_true")
    ap.add_argument("--pickaxe-regex", dest="pickaxe_regex", action="store_true")
    pickaxe = None
    pickaxe_kind = None
    _px_argv: list[str] = []
    _pi = 0
    while _pi < len(argv):
        a = argv[_pi]
        if a == "-S" or (a.startswith("-S") and len(a) > 2):
            if a == "-S":
                pickaxe = argv[_pi + 1] if _pi + 1 < len(argv) else ""
                _pi += 1
            else:
                pickaxe = a[2:]
            pickaxe_kind = "S"
        elif a == "-G" or (a.startswith("-G") and len(a) > 2):
            if a == "-G":
                pickaxe = argv[_pi + 1] if _pi + 1 < len(argv) else ""
                _pi += 1
            else:
                pickaxe = a[2:]
            pickaxe_kind = "G"
        else:
            _px_argv.append(a)
        _pi += 1
    argv = _px_argv
    # `--word-diff[=<mode>]` only takes a value when attached with '='; a bare
    # flag means "plain". `--word-diff-regex=<re>` selects word boundaries by a
    # regex and (per diff.c) implies word-diff mode. Pull both out of argv so the
    # trailing rev isn't consumed.
    word_diff_mode = None
    word_regex_src = None
    _wd_argv = []
    for a in argv:
        if a == "--word-diff":
            word_diff_mode = "plain"
        elif a.startswith("--word-diff="):
            word_diff_mode = a.split("=", 1)[1]
        elif a.startswith("--word-diff-regex="):
            word_regex_src = a.split("=", 1)[1]
            if word_diff_mode is None:
                word_diff_mode = "plain"
        elif a == "--color-words":
            word_diff_mode = "plain"
        elif a.startswith("--color-words="):
            word_regex_src = a.split("=", 1)[1]
            word_diff_mode = "plain"
        else:
            _wd_argv.append(a)
    argv = _wd_argv
    args, rest = ap.parse_known_args(argv)
    args.word_diff = word_diff_mode
    import re as _re_mod
    args.word_regex = _re_mod.compile(word_regex_src) if word_regex_src else None
    repo = _repo()
    # The display prefix for --relative: git strips the leading directory of the
    # cwd relative to the worktree top from every shown path, and only shows
    # files under it. ``relative == ""`` means use the cwd; otherwise the given
    # subdir (resolved against the cwd).
    rel_prefix = None
    if relative is not None:
        try:
            top = os.path.realpath(str(repo.path))
            base = os.path.realpath(os.path.join(top, relative)) if relative else os.path.realpath(os.getcwd())
            rp = os.path.relpath(base, top)
            rel_prefix = "" if rp == "." else rp.replace(os.sep, "/").rstrip("/") + "/"
        except Exception:
            rel_prefix = ""
    revs: list[str] = []
    paths: list[str] = []
    after_dd = False
    for tok in rest:
        if after_dd:
            paths.append(tok)
        elif tok == "--":
            after_dd = True
        elif tok.startswith("-"):
            continue
        else:
            # A non-flag token before '--' is a rev if it resolves as one; an
            # unresolvable token is treated as a pathspec (setup_revisions:
            # try_to_simplify_commit / pathspec fallback).
            if refs_mod.rev_parse(repo, tok) is not None:
                revs.append(tok)
            else:
                paths.append(tok)

    idx = read_index(repo).by_path()
    changes: list[tuple[str, _Side, _Side]] = []

    def add_change(path, a, b):
        if a.sha != b.sha or a.mode != b.mode:
            changes.append((path, a, b))

    if len(revs) >= 2:
        a_map = _tree_map_full(repo, _commit_tree(repo, refs_mod.rev_parse(repo, revs[0]) or ""))
        b_map = _tree_map_full(repo, _commit_tree(repo, refs_mod.rev_parse(repo, revs[1]) or ""))
        for p in sorted(set(a_map) | set(b_map)):
            a = _side_from_object(repo, *a_map[p]) if p in a_map else _ABSENT
            b = _side_from_object(repo, *b_map[p]) if p in b_map else _ABSENT
            add_change(p, a, b)
    elif len(revs) == 1:
        a_map = _tree_map_full(repo, _commit_tree(repo, refs_mod.rev_parse(repo, revs[0]) or ""))
        if args.cached:
            for p in sorted(set(a_map) | set(idx)):
                a = _side_from_object(repo, *a_map[p]) if p in a_map else _ABSENT
                b = _side_from_object(repo, idx[p].mode_str(), idx[p].sha) if p in idx else _ABSENT
                add_change(p, a, b)
        else:
            for p in sorted(set(a_map) | set(idx)):
                a = _side_from_object(repo, *a_map[p]) if p in a_map else _ABSENT
                b = _side_from_worktree(repo, p)
                add_change(p, a, b)
    elif args.cached:
        head_map = _tree_map_full(repo, _commit_tree(repo, refs_mod.rev_parse(repo, "HEAD") or ""))
        for p in sorted(set(head_map) | set(idx)):
            # Intent-to-add entries are not staged, so --cached ignores them.
            if p in idx and idx[p].intent_to_add and p not in head_map:
                continue
            a = _side_from_object(repo, *head_map[p]) if p in head_map else _ABSENT
            b = _side_from_object(repo, idx[p].mode_str(), idx[p].sha) if p in idx else _ABSENT
            add_change(p, a, b)
    else:
        for p in sorted(idx):
            # An intent-to-add entry diffs as a brand-new file (a-side absent),
            # not against its placeholder empty blob.
            a = _ABSENT if idx[p].intent_to_add else _side_from_object(repo, idx[p].mode_str(), idx[p].sha)
            b = _side_from_worktree(repo, p)
            add_change(p, a, b)

    if paths:
        wanted = set(paths)
        changes = [c for c in changes if c[0] in wanted or any(c[0].startswith(w.rstrip("/") + "/") for w in paths)]

    # Pickaxe (-S/-G) filters the queue to file pairs whose change matches the
    # needle (diffcore_pickaxe runs after pathspec selection, before output).
    if pickaxe is not None:
        changes = _changes_pickaxe(changes, pickaxe, pickaxe_kind,
                                   args.pickaxe_all, args.pickaxe_regex, getattr(args, "text", False))

    # --relative restricts to the prefix subtree and strips that prefix from the
    # displayed paths (diff.c relative_name handling).
    if rel_prefix is not None:
        np = len(rel_prefix)
        changes = [(p[np:], a, b) for p, a, b in changes if rel_prefix == "" or p.startswith(rel_prefix)]

    if args.reverse:
        # -R swaps the two sides of every change.
        changes = [(p, b, a) for p, a, b in changes]

    if args.diff_filter:
        want = set(args.diff_filter.upper())
        def _status(a, b):
            return "A" if not a.present else ("D" if not b.present else "M")
        changes = [(p, a, b) for p, a, b in changes if _status(a, b) in want]

    # Resolve the output-format bit set in command-line order (diff.c bit
    # semantics + diff_setup_done): handles -p/-s/--patch-with-stat etc. and the
    # name-only/name-status/no-output conflict + override rules.
    fmt, conflict = _resolve_diff_output_format(diff_raw_argv)
    if args.check:
        fmt = {"check"}
    if conflict:
        _err("fatal: options '--name-only', '--name-status', '--check', and '-s' "
             "cannot be used together")
        return 128
    # --dirstat / --stat-width(normalized to --stat) augment the format set.
    if dirstat:
        fmt.add("dirstat")
    # A default invocation (no explicit format) is a plain patch.
    if not fmt:
        fmt = {"patch"}

    # Build the shared patch-rendering options. Prefix flags are last-wins and
    # order-sensitive (e.g. "--no-prefix --src-prefix=Z/" keeps Z/ on the a side).
    a_pfx, b_pfx = _resolve_diff_prefixes(diff_raw_argv)
    dopts = _DiffOpts(
        a_prefix=a_pfx, b_prefix=b_pfx,
        full_index=args.full_index, abbrev=args.abbrev,
        ignore_all_space=args.ignore_all_space,
        ignore_space_change=args.ignore_space_change,
        ignore_space_at_eol=args.ignore_space_at_eol,
        ignore_cr_at_eol=args.ignore_cr_at_eol,
        word_diff=args.word_diff, word_regex=args.word_regex,
    )
    # Per-line sign overrides (--output-indicator-{new,old,context}).
    oi_new = args.oi_new[0] if args.oi_new else "+"
    oi_old = args.oi_old[0] if args.oi_old else "-"
    oi_ctx = args.oi_context[0] if args.oi_context else " "
    oi = (oi_new, oi_old, oi_ctx) if (args.oi_new or args.oi_old or args.oi_context) else None

    if "check" in fmt:
        return _diff_check(repo, changes)
    # Under whitespace-ignore flags, a change with no visible (non-ws) content
    # difference produces no patch, which also drives --quiet/--exit-code rc.
    if args.quiet or args.exit_code:
        effective = [c for c in changes if _change_is_visible(c, dopts)]
        if args.exit_code:
            for path, a, b in effective:
                _emit_file_diff(path, a, b, args.reverse, args.unified,
                                inter_hunk_context=args.interhunkcontext, opts=dopts)
        return 1 if effective else 0

    sep = "\0" if args.nul else "\t"
    term = "\0" if args.nul else "\n"
    raw_w = 40 if args.full_index else max(4, args.abbrev)

    def _emit_raw():
        zero = "0" * raw_w
        for path, a, b in changes:
            status = "A" if not a.present else ("D" if not b.present else "M")
            a_sha = (a.sha[:raw_w] if raw_w < 40 else a.sha) if a.present else zero
            b_sha = zero if (b.worktree or not b.present) else (b.sha[:raw_w] if raw_w < 40 else b.sha)
            sys.stdout.write(f":{a.mode or '000000'} {b.mode or '000000'} {a_sha} {b_sha} {status}{sep}{path}{term}")

    def _emit_name_only():
        for path, _, _ in changes:
            sys.stdout.write(path + term)

    def _emit_name_status():
        renames = []
        if not args.no_renames:
            renames, ch = _detect_changes_renames(repo, list(changes))
        else:
            ch = changes
        entries = [(dst, f"R{sim:03d}{sep}{src}{sep}{dst}") for src, dst, sim, _sa, _db in renames]
        for path, a, b in ch:
            status = "A" if not a.present else ("D" if not b.present else "M")
            entries.append((path, f"{status}{sep}{path}"))
        for _key, line in sorted(entries):
            sys.stdout.write(line + term)

    # Render in diff_flush order: raw/name → numstat → stat/compact → shortstat
    # → summary → dirstat → patch, separated by a blank line before the patch.
    separator = False
    if "raw" in fmt or "name_only" in fmt or "name_status" in fmt:
        if "name_status" in fmt:
            _emit_name_status()
        elif "name_only" in fmt:
            _emit_name_only()
        else:
            _emit_raw()
        separator = True
    if "numstat" in fmt:
        _diff_numstat(changes, nul=args.nul)
        separator = True
    stat_renames = []
    if "stat" in fmt or "compact_summary" in fmt:
        if not args.no_renames:
            stat_renames, changes = _detect_changes_renames(repo, changes)
        _diff_stat(changes, stat_renames, compact_summary=("compact_summary" in fmt))
        separator = True
    if "shortstat" in fmt:
        _diff_shortstat(changes)
        separator = True
    if "summary" in fmt:
        if not stat_renames and not args.no_renames and "stat" not in fmt and "compact_summary" not in fmt:
            stat_renames, changes = _detect_changes_renames(repo, changes)
        _diff_summary(changes, stat_renames)
        separator = True
    if "dirstat" in fmt:
        permille, cumulative, by_file = _parse_dirstat_params(dirstat_params)
        _diff_dirstat(changes, permille, cumulative, by_file)
        separator = True
    if "patch" in fmt:
        if separator:
            _print("")
        renames = []
        if not args.no_renames:
            renames, changes = _detect_changes_renames(repo, changes)
        emit = [(dst, lambda s=src, d=dst, sm=sim, sa=sa, db=db: _emit_rename_patch(s, d, sm, sa, db, opts=dopts))
                for src, dst, sim, sa, db in renames]
        emit += [(path, lambda p=path, a=a, b=b: _emit_file_diff(p, a, b, args.reverse, args.unified,
                                                                 inter_hunk_context=args.interhunkcontext,
                                                                 opts=dopts, output_indicators=oi))
                 for path, a, b in changes]
        for _key, fn in sorted(emit, key=lambda e: e[0]):
            fn()
    return 0


def _parse_dirstat_params(params: str) -> tuple[int, bool, bool]:
    """Parse --dirstat params, returning (permille, cumulative, by_file).
    The default threshold is 3% (30 permille); a bare integer sets it
    (with optional decimal). Mirrors diff.c parse_dirstat_params."""
    permille = 30
    cumulative = False
    by_file = False
    for p in params.split(","):
        p = p.strip()
        if p == "" :
            continue
        if p in ("changes",):
            by_file = False
        elif p in ("lines",):
            by_file = False  # line mode; treated like default for our outputs
        elif p in ("files",):
            by_file = True
        elif p in ("cumulative",):
            cumulative = True
        elif p == "noncumulative":
            cumulative = False
        else:
            # numeric threshold, possibly "N" or "N.M"
            try:
                if "." in p:
                    whole, frac = p.split(".", 1)
                    permille = int(whole) * 10 + (int((frac + "0")[:1]))
                else:
                    permille = int(p) * 10
            except ValueError:
                pass
    return permille, cumulative, by_file


def _diff_dirstat(changes: list, permille: int, cumulative: bool, by_file: bool) -> None:
    """Port of diff.c show_dirstat: per-directory damage percentages. Damage for
    a file is (one.size - copied) + added via the spanhash estimator (or 1 in
    --dirstat-by-file mode); directories at or above the threshold are printed."""
    from . import diffcore
    files: list[tuple[str, int]] = []  # (name, damage)
    total = 0
    for path, a, b in changes:
        name = path
        if a.present and b.present and a.sha == b.sha:
            damage = 0
        elif by_file:
            damage = 1
        elif a.present and b.present:
            src = diffcore.Filespec(None, path, a.sha, int(a.mode, 8),
                                    data=a.data if a.data is not None else b"")
            dst = diffcore.Filespec(None, path, b.sha, int(b.mode, 8),
                                    data=b.data if b.data is not None else b"")
            copied, added = diffcore._count_changes(src, dst)
            damage = (src.size - copied) + added
            if not damage:
                damage = 1
        elif a.present:
            damage = 0
        elif b.present:
            damage = len(b.data or b"")
        else:
            continue
        files.append((name, damage))
        total += damage
    if not total:
        return
    files.sort(key=lambda f: f[0])

    # gather_dirstat recursion over the sorted file list.
    state = {"i": 0}

    def gather(base: str, baselen: int) -> int:
        sum_changes = 0
        sources = 0
        while state["i"] < len(files):
            fname = files[state["i"]][0]
            if len(fname) < baselen:
                break
            if fname[:baselen] != base[:baselen]:
                break
            slash = fname.find("/", baselen)
            if slash >= 0:
                newbaselen = slash + 1
                changes_here = gather(fname[:newbaselen], newbaselen)
                sources += 1
            else:
                changes_here = files[state["i"]][1]
                state["i"] += 1
                sources += 2
            sum_changes += changes_here
        if baselen and sources != 1:
            if sum_changes:
                this_permille = sum_changes * 1000 // total
                if this_permille >= permille:
                    _print(f"{this_permille // 10:4d}.{this_permille % 10:01d}% {base[:baselen]}")
                    if not cumulative:
                        return 0
        return sum_changes

    gather("", 0)


def _changes_pickaxe(changes: list, needle: str, kind: str, pickaxe_all: bool,
                     pickaxe_regex: bool, text: bool) -> list:
    """Port of diffcore_pickaxe for the (path, a, b) change list used by the diff
    command. ``kind`` is 'S' (has_changes: needle count differs between the two
    sides) or 'G' (diff_grep: needle matches an added/removed line). With
    --pickaxe-all, all changes survive iff any one matches."""
    import re as _re
    regexp = None
    if kind == "G" or pickaxe_regex:
        regexp = _re.compile(needle.encode("utf-8", "replace"), _re.MULTILINE)

    def _contains(data: bytes) -> int:
        if not data:
            return 0
        if regexp is not None:
            cnt = 0
            pos = 0
            while pos <= len(data):
                m = regexp.search(data, pos)
                if not m:
                    break
                cnt += 1
                pos = m.end() + 1 if m.end() == m.start() else m.end()
            return cnt
        nd = needle.encode("utf-8", "replace")
        if not nd:
            return 0
        cnt = 0
        pos = 0
        while True:
            k = data.find(nd, pos)
            if k < 0:
                break
            cnt += 1
            pos = k + len(nd)
        return cnt

    def _has_changes(a, b) -> bool:
        c1 = _contains(a.data or b"") if a.present else 0
        c2 = _contains(b.data or b"") if b.present else 0
        return c1 != c2

    def _diff_grep(a, b) -> bool:
        if (not text and ((a.present and _is_binary(a.data)) or
                          (b.present and _is_binary(b.data)))):
            return False
        a_lines = (a.data or b"").decode("utf-8", "replace").splitlines() if a.present else []
        b_lines = (b.data or b"").decode("utf-8", "replace").splitlines() if b.present else []
        for kind2, ai, bi in diff_mod.diff_lines(a_lines, b_lines):
            if kind2 == "ins" and regexp.search(b_lines[bi].encode("utf-8", "replace")):
                return True
            if kind2 == "del" and regexp.search(a_lines[ai].encode("utf-8", "replace")):
                return True
        return False

    def _match(ch) -> bool:
        _p, a, b = ch
        if not a.present and not b.present:
            return False
        if a.present and b.present and a.sha == b.sha:
            return False
        if kind == "G":
            if (not text and ((a.present and _is_binary(a.data)) or
                              (b.present and _is_binary(b.data)))):
                return False
            return _diff_grep(a, b)
        return _has_changes(a, b)

    if pickaxe_all:
        return changes if any(_match(c) for c in changes) else []
    return [c for c in changes if _match(c)]


def _change_is_visible(change, opts: "_DiffOpts") -> bool:
    """True if a (path, a, b) change yields a non-empty patch under the active
    whitespace-ignore flags (drives diff --quiet/--exit-code, like git's
    DIFF_FROM_CONTENTS handling). Mode changes and add/delete are always
    visible; pure-content changes are tested through the hunk renderer."""
    _path, a, b = change
    if a.mode != b.mode:
        return True
    if not a.present or not b.present:
        return True
    if a.sha == b.sha:
        return False
    if not (opts.ignore_all_space or opts.ignore_space_change
            or opts.ignore_space_at_eol or opts.ignore_cr_at_eol):
        return True
    if _is_binary(a.data) or _is_binary(b.data):
        return True
    a_text = (a.data or b"").decode("utf-8", errors="replace")
    b_text = (b.data or b"").decode("utf-8", errors="replace")
    body = diff_mod.format_hunks_ex(
        a_text.splitlines(), b_text.splitlines(),
        a_no_newline=bool(a_text) and not a_text.endswith("\n"),
        b_no_newline=bool(b_text) and not b_text.endswith("\n"),
        ignore_all_space=opts.ignore_all_space,
        ignore_space_change=opts.ignore_space_change,
        ignore_space_at_eol=opts.ignore_space_at_eol,
        ignore_cr_at_eol=opts.ignore_cr_at_eol,
    )
    return bool(body)


def _emit_rename_patch(src: str, dst: str, sim: int, src_side: _Side, dst_side: _Side,
                       a_prefix: str = "a", b_prefix: str = "b",
                       opts: "Optional[_DiffOpts]" = None) -> None:
    if opts is None:
        opts = _DiffOpts(a_prefix=a_prefix + "/" if a_prefix else "",
                         b_prefix=b_prefix + "/" if b_prefix else "")
    pa, pb = opts.a_prefix, opts.b_prefix
    _print(f"diff --git {pa}{src} {pb}{dst}")
    _print(f"similarity index {sim}%")
    _print(f"rename from {src}")
    _print(f"rename to {dst}")
    if src_side.sha == dst_side.sha:
        return
    _print(f"index {_index_abbrev(opts, src_side.sha)}..{_index_abbrev(opts, dst_side.sha)} {dst_side.mode}")
    a_text = (src_side.data or b"").decode("utf-8", errors="replace")
    b_text = (dst_side.data or b"").decode("utf-8", errors="replace")
    _print(f"--- {pa}{src}")
    _print(f"+++ {pb}{dst}")
    for line in diff_mod.format_hunks_ex(
        a_text.splitlines(), b_text.splitlines(),
        a_no_newline=bool(a_text) and not a_text.endswith("\n"),
        b_no_newline=bool(b_text) and not b_text.endswith("\n"),
        ignore_all_space=opts.ignore_all_space,
        ignore_space_change=opts.ignore_space_change,
        ignore_space_at_eol=opts.ignore_space_at_eol,
        ignore_cr_at_eol=opts.ignore_cr_at_eol,
    ):
        _print(line)


def _detect_changes_renames(repo: Repository, changes: list, minimum_score: int = 0):
    """Split ``changes`` into detected (src, dst, similarity%) renames and the
    remaining non-rename changes, using the validated spanhash estimator."""
    from . import diffcore
    base_map: dict[str, tuple[int, str]] = {}
    side_map: dict[str, tuple[int, str]] = {}
    for path, a, b in changes:
        if a.present and not b.present:
            base_map[path] = (int(a.mode, 8), a.sha)
        elif b.present and not a.present and not b.worktree:
            side_map[path] = (int(b.mode, 8), b.sha)
    if not base_map or not side_map:
        return [], changes
    by_path = {p: (a, b) for p, a, b in changes}
    pairs = diffcore.detect_renames(repo, base_map, side_map, minimum_score=minimum_score)
    renamed_src = {p.src.path for p in pairs}
    renamed_dst = {p.dst.path for p in pairs}
    renames = [
        (p.src.path, p.dst.path, int(p.score * 100 / diffcore.MAX_SCORE),
         by_path[p.src.path][0], by_path[p.dst.path][1])
        for p in pairs
    ]
    remaining = [
        (path, a, b)
        for path, a, b in changes
        if not (a.present and not b.present and path in renamed_src)
        and not (b.present and not a.present and path in renamed_dst)
    ]
    return renames, remaining


def _diff_counts(a: _Side, b: _Side) -> tuple[int, int]:
    if _is_binary(a.data) or _is_binary(b.data):
        return -1, -1
    a_lines = (a.data or b"").decode("utf-8", errors="replace").splitlines()
    b_lines = (b.data or b"").decode("utf-8", errors="replace").splitlines()
    ins = dele = 0
    for op in diff_mod.diff_lines(a_lines, b_lines):
        if op[0] == "ins":
            ins += 1
        elif op[0] == "del":
            dele += 1
    return ins, dele


def _diff_numstat(changes: list, renames=None, nul: bool = False,
                  complete=None, order=None, unmerged=None) -> None:
    # In -z mode renames emit 'ins<TAB>del<TAB>\0src\0dst\0'; otherwise the
    # compact 'src => dst' name terminated by newline. ``order`` (dst/path ->
    # queue index) reorders output to match the diff queue when provided.
    # Unmerged ('U') paths emit '0\t0\t<path>' (builtin_diffstat: added=deleted=0).
    complete = complete or {}
    order = order or {}
    out: list[tuple[int, str]] = []
    for _k, path in (unmerged or []):
        line = f"0\t0\t{path}\0" if nul else f"0\t0\t{path}\n"
        out.append((_k, line))
    for src, dst, _sim, sa, db in (renames or []):
        ins, dele = _diff_counts(sa, db)
        cnt = "-\t-\t" if ins < 0 else f"{ins}\t{dele}\t"
        if nul:
            line = f"{cnt}\0{src}\0{dst}\0" if src != dst else f"{cnt}{dst}\0"
        else:
            name = _pprint_rename(src, dst) if src != dst else dst
            line = f"{cnt}{name}\n"
        out.append((order.get(dst, len(out)), line))
    for path, a, b in changes:
        if path in complete and not (_is_binary(a.data) or _is_binary(b.data)):
            ins, dele = complete[path]
        else:
            ins, dele = _diff_counts(a, b)
        cnt = "-\t-\t" if ins < 0 else f"{ins}\t{dele}\t"
        line = f"{cnt}{path}\0" if nul else f"{cnt}{path}\n"
        out.append((order.get(path, len(out)), line))
    if order:
        out.sort(key=lambda r: r[0])
    for _k, line in out:
        sys.stdout.write(line)


def _diff_shortstat(changes: list, renames=None, complete=None,
                    n_unmerged: int = 0) -> None:
    files = total_ins = total_del = 0
    complete = complete or {}
    for _src, _dst, _sim, sa, db in (renames or []):
        files += 1
        ins, dele = _diff_counts(sa, db)
        if ins > 0:
            total_ins += ins
        if dele > 0:
            total_del += dele
    for path, a, b in changes:
        files += 1
        if path in complete and not (_is_binary(a.data) or _is_binary(b.data)):
            ins, dele = complete[path]
        else:
            ins, dele = _diff_counts(a, b)
        if ins > 0:
            total_ins += ins
        if dele > 0:
            total_del += dele
    if files == 0:
        # Unmerged-only queue still prints the summary as " 0 files changed".
        if n_unmerged:
            _print(" 0 files changed")
        return
    _print(_stat_summary_line(files, total_ins, total_del))


def _remote_branches(repo: Repository) -> list[str]:
    found: list[str] = []
    root = repo.gitdir / "refs" / "remotes"
    if root.exists():
        for f in sorted(root.rglob("*")):
            if f.is_file():
                rel = str(f.relative_to(repo.gitdir / "refs" / "remotes")).replace(os.sep, "/")
                found.append(rel)
    for ref in refs_mod.read_packed_refs(repo):
        if ref.startswith("refs/remotes/"):
            found.append(ref[len("refs/remotes/"):])
    return sorted(set(found))


def _branch_checked_out_path(repo: Repository, full_ref: str,
                             cur: Optional[str]) -> Optional[str]:
    """Port of branch_checked_out(): return the worktree path whose HEAD symref
    is full_ref, or None. Checks the main worktree (whose head ref is `cur`) and
    any linked worktrees recorded under .git/worktrees/."""
    if cur is not None and f"refs/heads/{cur}" == full_ref:
        return str(repo.path)
    worktrees_dir = repo.gitdir / "worktrees"
    if worktrees_dir.exists():
        for d in sorted(worktrees_dir.iterdir()):
            head_file = d / "HEAD"
            gitdir_file = d / "gitdir"
            if not (d.is_dir() and head_file.exists() and gitdir_file.exists()):
                continue
            head_txt = head_file.read_text(encoding="utf-8").strip()
            if head_txt.startswith("ref: ") and head_txt[len("ref: "):] == full_ref:
                return str(Path(gitdir_file.read_text(encoding="utf-8").strip()).parent)
    return None


_SET_UPSTREAM_HINT = (
    "hint:\n"
    "hint: If you are planning on basing your work on an upstream\n"
    "hint: branch that already exists at the remote, you may need to\n"
    "hint: run \"git fetch\" to retrieve it.\n"
    "hint:\n"
    "hint: If you are planning to push out a new local branch that\n"
    "hint: will track its remote counterpart, you may want to use\n"
    "hint: \"git push -u\" to set the upstream config as you push.\n"
    "hint: Disable this message with \"git config set advice.setUpstreamFailure false\"\n"
)


def _set_branch_upstream(repo: Repository, branch: str, upstream: str, quiet: bool) -> int:
    """Configure branch.<branch>.{remote,merge} to track <upstream>, matching
    C Git's dwim_branch_start() with explicit tracking (branch.c)."""
    # 1. The starting point must resolve to an object at all; otherwise it is
    #    reported as a missing upstream branch (with the push/fetch advice).
    if refs_mod.rev_parse(repo, upstream) is None:
        _err(f"fatal: the requested upstream branch '{upstream}' does not exist")
        sys.stderr.write(_SET_UPSTREAM_HINT)
        return 128
    # 2. DWIM the name to a ref. With explicit tracking, the resolved ref must be
    #    a local branch (refs/heads/) or a remote-tracking branch (refs/remotes/);
    #    anything else (e.g. a tag) is "not a branch".
    real_ref = refs_mod.dwim_full_name(repo, upstream)
    if real_ref is not None and real_ref.startswith("refs/heads/"):
        remote, merge = ".", real_ref
    elif real_ref is not None and real_ref.startswith("refs/remotes/"):
        rname, _, rest = real_ref[len("refs/remotes/"):].partition("/")
        remote, merge = rname, f"refs/heads/{rest}"
    else:
        _err(f"fatal: cannot set up tracking information; starting point '{upstream}' is not a branch")
        return 128
    from . import gitconfig
    cfg = repo.gitdir / "config"
    gitconfig.write_value(cfg, "branch", branch, "remote", remote)
    gitconfig.write_value(cfg, "branch", branch, "merge", merge)
    if not quiet:
        _print(f"branch '{branch}' set up to track '{upstream}'.")
    return 0


def _set_branch_upstream_inherit(repo: Repository, branch: str, start: str,
                                 quiet: bool) -> int:
    """Port of branch.c setup_tracking with BRANCH_TRACK_INHERIT: copy the
    start-point branch's upstream config onto the new branch. If the start
    branch has no remote configured, warn and set nothing (the new branch is
    still created)."""
    from . import gitconfig
    src = start
    if src.startswith("refs/heads/"):
        src = src[len("refs/heads/"):]
    remote = gitconfig.get(repo, f"branch.{src}.remote")
    merge = gitconfig.get(repo, f"branch.{src}.merge")
    if remote is None:
        _err(f"warning: asked to inherit tracking from '{src}', but no remote is set")
        return 0
    if merge is None:
        _err(f"warning: asked to inherit tracking from '{src}', "
             f"but no merge configuration is set")
        return 0
    cfg = repo.gitdir / "config"
    gitconfig.write_value(cfg, "branch", branch, "remote", remote)
    gitconfig.write_value(cfg, "branch", branch, "merge", merge)
    if not quiet:
        _print(f"branch '{branch}' set up to track '{src}'.")
    return 0


def cmd_branch(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit branch", add_help=False)
    ap.add_argument("-d", "--delete", action="store_true")
    ap.add_argument("-D", dest="force_delete", action="store_true")
    ap.add_argument("-a", "--all", action="store_true")
    ap.add_argument("-r", "--remotes", action="store_true")
    ap.add_argument("-l", "--list", dest="list_mode", action="store_true")
    ap.add_argument("-m", "--move", action="store_true")
    ap.add_argument("-M", dest="force_move", action="store_true")
    ap.add_argument("-c", "--copy", action="store_true")
    ap.add_argument("-C", dest="force_copy", action="store_true")
    ap.add_argument("--show-current", action="store_true")
    ap.add_argument("--contains", default=None)
    ap.add_argument("--no-contains", dest="no_contains", default=None)
    # builtin/branch.c: OPT_WITH/OPT_WITHOUT are hidden synonyms of
    # --contains/--no-contains (they take a commit, defval HEAD).
    ap.add_argument("--with", dest="with_commit", nargs="?", const="HEAD", default=None)
    ap.add_argument("--without", dest="without_commit", nargs="?", const="HEAD", default=None)
    ap.add_argument("--points-at", dest="points_at", default=None)
    ap.add_argument("--merged", nargs="?", const="HEAD", default=None)
    ap.add_argument("--no-merged", dest="no_merged", nargs="?", const="HEAD", default=None)
    ap.add_argument("--sort", action="append", default=None)
    ap.add_argument("--format", default=None)
    ap.add_argument("-f", "--force", action="store_true")
    ap.add_argument("-q", "--quiet", action="store_true")
    ap.add_argument("-i", "--ignore-case", dest="ignore_case", action="store_true")
    ap.add_argument("-t", "--track", nargs="?", const="direct", default=None)
    # builtin/branch.c: --no-track negates -t/--track (BRANCH_TRACK_NEVER).
    ap.add_argument("--no-track", dest="no_track", action="store_true")
    ap.add_argument("-u", "--set-upstream-to", dest="set_upstream_to", default=None)
    # OPT_SET_INT_F(0, "set-upstream", ...PARSE_OPT_HIDDEN): registered only to
    # produce the "no longer supported" die. OPT_BOOL unset-upstream.
    ap.add_argument("--set-upstream", dest="set_upstream", action="store_true")
    ap.add_argument("--unset-upstream", dest="unset_upstream", action="store_true")
    ap.add_argument("--omit-empty", dest="omit_empty", action="store_true")
    ap.add_argument("--create-reflog", dest="create_reflog", action="store_true")
    ap.add_argument("--edit-description", dest="edit_description", action="store_true")
    # OPT_COLUMN / OPT__COLOR. We accept and (for color) honour the defval.
    ap.add_argument("--column", nargs="?", const="", default=None)
    ap.add_argument("--no-column", dest="no_column", action="store_true")
    ap.add_argument("--color", nargs="?", const="always", default=None)
    ap.add_argument("--no-color", dest="no_color", action="store_true")
    # OPT__ABBREV: --abbrev[=<n>] (default 7) and --no-abbrev (n=0).
    ap.add_argument("--abbrev", nargs="?", const="7", default=None)
    ap.add_argument("--no-abbrev", dest="no_abbrev", action="store_true")
    ap.add_argument("--recurse-submodules", dest="recurse_submodules", action="store_true")
    ap.add_argument("-v", "--verbose", action="count", default=0)
    ap.add_argument("names", nargs="*")
    # PARSE_OPT_LASTARG_DEFAULT / PARSE_OPT_OPTARG handling: these options take an
    # optional value. C consumes a *following separate* token as the value unless
    # the option is the last argument or followed by another option, in which case
    # the defval is used. -t/--track is OPTARG (defval direct); --with/--without/
    # --points-at are LASTARG_DEFAULT (defval HEAD). --column/--color/--abbrev take
    # an optional stuck value only, so a following token stays positional.
    _LASTARG_DEFAULT = {"--with": "HEAD", "--without": "HEAD",
                        "--points-at": "HEAD"}
    _STUCK_DEFAULT = {"-t": "direct", "--track": "direct",
                      "--column": "", "--color": "always", "--abbrev": "7"}
    pre: list[str] = []
    i = 0
    while i < len(argv):
        t = argv[i]
        if t in _LASTARG_DEFAULT:
            nxt = argv[i + 1] if i + 1 < len(argv) else None
            if nxt is not None and not (nxt.startswith("-") and nxt != "-"):
                pre.append(f"{t}={nxt}")
                i += 2
                continue
            pre.append(f"{t}={_LASTARG_DEFAULT[t]}")
            i += 1
            continue
        if t in _STUCK_DEFAULT:
            sep = "=" if t.startswith("--") else ""
            pre.append(f"{t}{sep}{_STUCK_DEFAULT[t]}")
            i += 1
            continue
        pre.append(t)
        i += 1
    args = ap.parse_args(pre)
    # --set-upstream is no longer supported (builtin/branch.c BRANCH_TRACK_OVERRIDE).
    if args.set_upstream:
        _err("fatal: the '--set-upstream' option is no longer supported. "
             "Please use '--track' or '--set-upstream-to' instead")
        return 128
    # --with/--without are plain synonyms of --contains/--no-contains.
    if args.with_commit is not None and args.contains is None:
        args.contains = args.with_commit
    if args.without_commit is not None and args.no_contains is None:
        args.no_contains = args.without_commit
    # parse_opt_tracking_mode: -t/--track only accepts direct|inherit.
    track_inherit = False
    if args.track is not None:
        if args.track == "inherit":
            track_inherit = True
        elif args.track != "direct":
            _err('error: option `--track\' expects "direct" or "inherit"')
            return 129
    if args.no_track:
        args.track = None
    # OPT_REF_SORT validates each sort key (builtin/branch.c -> ref-filter).
    if args.sort:
        for spec in args.sort:
            key = spec[1:] if spec[:1] in "-+" else spec
            err = _ref_sort_validate(key)
            if err is not None:
                _err(err)
                return 128
    # Reconstruct legacy name/start positionals from the list. The delete path
    # consumes the whole list (git deletes every named branch).
    args.name = args.names[0] if args.names else None
    args.start = args.names[1] if len(args.names) > 1 else None
    repo = _repo()
    head_sym, _ = refs_mod.read_head(repo)
    cur = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else None

    contains_sha = refs_mod.rev_parse(repo, args.contains) if args.contains else None
    no_contains_sha = refs_mod.rev_parse(repo, args.no_contains) if args.no_contains else None
    merged_sha = refs_mod.rev_parse(repo, args.merged) if args.merged else None
    no_merged_sha = refs_mod.rev_parse(repo, args.no_merged) if args.no_merged else None
    points_at_sha = refs_mod.rev_parse(repo, args.points_at) if args.points_at else None

    def _reachable_from(start: str, target: str) -> bool:
        stack = deque([start])
        seen_c: set[str] = set()
        while stack:
            x = stack.popleft()
            if x == target:
                return True
            if x in seen_c:
                continue
            seen_c.add(x)
            info = _commit_tree_parents(repo, x)
            if info:
                stack.extend(info[1])
        return False

    def _branch_contains(branch: str) -> bool:
        tip = refs_mod.read_ref(repo, f"refs/heads/{branch}")
        if tip is None:
            return False
        # --contains C: branch tip can reach C. --merged C: C can reach the tip.
        if contains_sha is not None and not _reachable_from(tip, contains_sha):
            return False
        if no_contains_sha is not None and _reachable_from(tip, no_contains_sha):
            return False
        if merged_sha is not None and not _reachable_from(merged_sha, tip):
            return False
        if no_merged_sha is not None and _reachable_from(no_merged_sha, tip):
            return False
        if points_at_sha is not None and tip != points_at_sha:
            return False
        return True

    # --edit-description opens an editor; with no editor/tty available it is a
    # no-op returning 0 (builtin/branch.c edit_branch_description). It must NOT
    # fall through to the listing path.
    if args.edit_description:
        return 0

    # --unset-upstream removes branch.<name>.{remote,merge} (builtin/branch.c).
    if args.unset_upstream:
        from . import gitconfig
        if len(args.names) > 1:
            _err("fatal: too many arguments to unset upstream")
            return 128
        branch = args.name or cur
        if branch is None:
            tgt = args.name if args.name else "HEAD"
            if not args.name or tgt == "HEAD":
                _err("fatal: could not unset upstream of HEAD when "
                     "it does not point to any branch")
            else:
                _err(f"fatal: no such branch '{tgt}'")
            return 128
        # branch_has_merge_config: a branch.<name>.merge must be configured.
        if gitconfig.get(repo, f"branch.{branch}.merge") is None:
            _err(f"fatal: branch '{branch}' has no upstream information")
            return 128
        cfg = repo.gitdir / "config"
        gitconfig.unset_value(cfg, "branch", branch, "remote", all_values=True)
        gitconfig.unset_value(cfg, "branch", branch, "merge", all_values=True)
        return 0

    # -u/--set-upstream-to changes the upstream of an existing branch (the named
    # one, else the current branch).
    if args.set_upstream_to is not None:
        branch = args.name or cur
        if branch is None:
            _err("fatal: HEAD not found below refs/heads!")
            return 128
        if refs_mod.read_ref(repo, f"refs/heads/{branch}") is None:
            _err(f"error: branch '{branch}' does not exist")
            return 1
        return _set_branch_upstream(repo, branch, args.set_upstream_to, args.quiet)

    if args.move or args.force_move or args.copy or args.force_copy:
        if args.name is not None and args.start is not None:
            src, dst = args.name, args.start
        elif args.name is not None:
            src, dst = cur, args.name
        else:
            _err("fatal: branch name required")
            return 128
        if src is None:
            _err("fatal: no such branch")
            return 128
        sha = refs_mod.read_ref(repo, f"refs/heads/{src}")
        if sha is None:
            _err(f"fatal: Branch '{src}' not found.")
            return 128
        # builtin/branch.c validate_new_branchname: force is (copy+rename)>1,
        # i.e. -M/-C or -m/-c combined with -f. Without force, refuse to clobber
        # an existing destination branch (same-name renames are always allowed).
        move_force = args.force_move or args.force_copy or args.force
        dst_exists = src != dst and refs_mod.read_ref(repo, f"refs/heads/{dst}") is not None
        if dst_exists and not move_force:
            _err(f"fatal: a branch named '{dst}' already exists")
            return 128
        # validate_new_branchname: when forcing onto an existing branch that is
        # checked out in a worktree, refuse (would desync HEAD). For a copy the
        # source/HEAD is irrelevant; the destination check still applies.
        if dst_exists and move_force:
            wt_path = _branch_checked_out_path(repo, f"refs/heads/{dst}", cur)
            if wt_path is not None:
                _err(f"fatal: cannot force update the branch '{dst}' "
                     f"used by worktree at '{wt_path}'")
                return 128
        # Reftable repos rename through the backend's write_copy_table, which
        # writes the new ref + reflog and deletes the old ref + reflog across
        # two update indices (byte-identical to C Git).
        if (args.move or args.force_move) and src != dst and refs_mod.uses_reftable(repo):
            rename_msg = f"Branch: renamed refs/heads/{src} to refs/heads/{dst}"
            refs_mod.rename_ref(repo, f"refs/heads/{src}", f"refs/heads/{dst}",
                                rename_msg)
            if cur == src:
                refs_mod.set_head(repo, f"refs/heads/{dst}")
            return 0
        # A same-name rename (e.g. `branch -M main` while already on main) is a
        # no-op move in git: the ref already points at sha, so re-writing it
        # would inject a spurious "update:" reflog entry that the moved-log path
        # normally overwrites. Skip the update for that case.
        same_name_move = (args.move or args.force_move) and src == dst
        if not same_name_move:
            refs_mod.update_ref(repo, f"refs/heads/{dst}", sha)
        if args.move or args.force_move:
            # Moving/deleting the source for a same-name rename would destroy the
            # (identical) destination ref and its reflog, so skip it; only the
            # rename reflog entries below are appended.
            if src != dst:
                old_log = repo.gitdir / "logs" / "refs" / "heads" / src
                new_log = repo.gitdir / "logs" / "refs" / "heads" / dst
                if old_log.exists():
                    new_log.parent.mkdir(parents=True, exist_ok=True)
                    old_log.replace(new_log)
                refs_mod.delete_ref(repo, f"refs/heads/{src}")
            # git records the rename in the reflog: a no-op (old==new) entry on
            # the renamed branch's own log, plus a delete/create pair on HEAD
            # when the current branch is the one being renamed.
            from . import reflog as _reflog
            rename_msg = f"Branch: renamed refs/heads/{src} to refs/heads/{dst}"
            zero = repo.null_oid()
            _reflog.append(repo, f"refs/heads/{dst}", sha, sha, rename_msg)
            if cur == src:
                # The HEAD reflog records the value HEAD resolved to just before
                # the symref is re-pointed. For a real rename the source ref was
                # deleted, so that value is zero; for a same-name move the source
                # ref still resolves to sha, so the second entry is sha->sha.
                _reflog.append(repo, "HEAD", sha, zero, rename_msg)
                head_old = sha if src == dst else zero
                _reflog.append(repo, "HEAD", head_old, sha, rename_msg)
                refs_mod.set_head(repo, f"refs/heads/{dst}")
        return 0

    if args.show_current:
        if cur:
            _print(cur)
        return 0

    if args.delete or args.force_delete:
        if not args.names:
            _err("fatal: branch name required")
            return 128
        # builtin/branch.c delete_branches: force is (delete>1), i.e. -D or
        # -d combined with -f. Without force, refuse to delete a branch whose
        # tip is not reachable from HEAD (not fully merged). Collect deletable
        # branches first (reporting errors in order), delete, then print.
        delete_force = args.force_delete or args.force
        _, head_sha = refs_mod.read_head(repo)
        rc = 0
        collected: list[tuple[str, str]] = []  # (name, oid)
        for name in args.names:
            full = f"refs/heads/{name}"
            if name == cur:
                _err(f"error: cannot delete branch '{name}' used by worktree at '{repo.path}'")
                rc = 1
                continue
            sha = refs_mod.read_ref(repo, full)
            if sha is None:
                _err(f"error: branch '{name}' not found")
                rc = 1
                continue
            if not delete_force:
                # branch_merged: tip must be an ancestor of HEAD.
                merged = bool(head_sha) and _reachable_from(head_sha, sha)
                if not merged:
                    _err(f"error: the branch '{name}' is not fully merged")
                    _err(f"hint: If you are sure you want to delete it, "
                         f"run 'git branch -D {name}'")
                    _err('hint: Disable this message with "git config set '
                         'advice.forceDeleteBranch false"')
                    rc = 1
                    continue
            collected.append((name, sha))
        for name, sha in collected:
            refs_mod.delete_ref(repo, f"refs/heads/{name}")
        for name, sha in collected:
            _print(f"Deleted branch {name} (was {sha[:7]}).")
        return rc

    if args.name is None or args.list_mode:
        import fnmatch
        pattern = args.name
        # builtin/branch.c: -a/--all and -r/--remotes both OPT_SET_INT_F the same
        # filter.kind, so the LAST of -a/-r/--all/--remotes on the command line
        # wins. -r => REMOTES (remote refs shown WITHOUT the "remotes/" prefix);
        # -a => ALL (local + remotes WITH the "remotes/" prefix).
        filter_kind = "branches"
        # Determine the last-set kind by scanning the option stream in order.
        for tok in argv:
            if tok in ("-a", "--all"):
                filter_kind = "all"
            elif tok in ("-r", "--remotes"):
                filter_kind = "remotes"
            elif tok.startswith("-") and not tok.startswith("--") and tok != "-":
                for ch in tok[1:]:
                    if ch == "a":
                        filter_kind = "all"
                    elif ch == "r":
                        filter_kind = "remotes"
        # (display, head-compare-name, full-ref)
        names: list[tuple[str, Optional[str], str]] = []
        if filter_kind != "remotes":
            names.extend((b, b, f"refs/heads/{b}") for b in refs_mod.list_branches(repo))
        if filter_kind == "all":
            names.extend((f"remotes/{b}", None, f"refs/remotes/{b}")
                         for b in _remote_branches(repo))
        elif filter_kind == "remotes":
            # REMOTES filter prints remote-tracking refs without the prefix.
            names.extend((b, None, f"refs/remotes/{b}") for b in _remote_branches(repo))
        def _pat_ok(d: str) -> bool:
            if not pattern:
                return True
            if args.ignore_case:
                import re as _re
                return bool(_re.match(fnmatch.translate(pattern), d, _re.IGNORECASE))
            return fnmatch.fnmatch(d, pattern)
        shown = [
            (d, p, r) for d, p, r in names
            if _pat_ok(d) and (p is None or _branch_contains(p))
        ]
        if args.sort:
            # Multiple keys: apply in reverse so the first key is the primary one.
            for spec in reversed(args.sort):
                reverse = spec.startswith("-")
                key = spec[1:] if reverse else spec
                def _bkey(item, key=key):
                    display, plain, ref = item
                    if key in ("version:refname", "v:refname"):
                        return _version_sort_key(display)
                    if key in ("committerdate", "creatordate", "authordate", "taggerdate"):
                        sha = refs_mod.read_ref(repo, ref)
                        return _ref_sort_date(repo, sha, key) if sha else 0
                    if key == "objectname":
                        return refs_mod.read_ref(repo, ref) or ""
                    return display
                shown.sort(key=_bkey, reverse=reverse)
        # OPT__ABBREV: --no-abbrev => 0 (full hash); --abbrev=<n> => n; default 7.
        abbrev = 7
        if args.no_abbrev:
            abbrev = 0
        elif args.abbrev is not None:
            try:
                abbrev = int(args.abbrev)
            except ValueError:
                abbrev = 7
        # --column lays the marked branch lines into terminal-width columns
        # (builtin/branch.c print_columns; COL_ENABLED, layout COL_COLUMN). It is
        # incompatible with --verbose and ignored with --format.
        if (args.column is not None and not args.no_column
                and args.format is None and not args.verbose):
            items = [f"{'*' if (p is not None and p == cur) else ' '} {d}"
                     for d, p, _ in shown]
            colopts = _COL_ENABLED | _COL_COLUMN
            if args.column:
                colopts2, ok, _ls, _es = _col_parse_option(args.column, colopts)
                if ok:
                    colopts = colopts2
                    if (colopts & _COL_ENABLE_MASK) == 0:
                        colopts |= _COL_ENABLED
            _col_print_columns(items, colopts, "", "\n", 1, 0)
            return 0
        # OPT__COLOR: --color[=<when>] (bare defval "always"). build_format colors
        # the current branch GREEN, remote-tracking RED, local NORMAL("") and
        # always appends RESET after the name.
        _C_RESET, _C_GREEN, _C_RED = "\033[m", "\033[32m", "\033[31m"
        use_color = False
        if args.no_color:
            use_color = False
        elif args.color is not None:
            when = args.color or "always"
            if when == "always":
                use_color = True
            elif when == "auto":
                use_color = sys.stdout.isatty()
        width = max((len(d) for d, _, _ in shown), default=0)
        for display, plain, ref in shown:
            mark = "*" if plain is not None and plain == cur else " "
            if args.format is not None:
                sha = refs_mod.read_ref(repo, ref)
                _print(_fer_expand(repo, ref, sha or "", args.format, head_sym))
                continue
            if args.verbose:
                sha = refs_mod.read_ref(repo, ref)
                subject = ""
                if sha:
                    try:
                        subject = objs.parse_commit(objs.read_object(repo, sha)[1]).message.splitlines()[0]
                    except (KeyError, IndexError):
                        subject = ""
                short = sha[:abbrev] if (sha and abbrev) else (sha or "")
                _print(f"{mark} {display:<{width}} {short} {subject}".rstrip())
            elif use_color:
                if plain is not None and plain == cur:
                    col = _C_GREEN
                elif plain is None:
                    col = _C_RED
                else:
                    col = ""  # local NORMAL
                _print(f"{mark} {col}{display}{_C_RESET}")
            else:
                _print(f"{mark} {display}")
        return 0

    full = f"refs/heads/{args.name}"
    if refs_mod.read_ref(repo, full) is not None and not args.force:
        _err(f"fatal: a branch named '{args.name}' already exists")
        return 128
    start = refs_mod.rev_parse(repo, args.start) if args.start else refs_mod.rev_parse(repo, "HEAD")
    if not start:
        # branch.c dwim_branch_start: die("not a valid object name: '%s'").
        _err(f"fatal: not a valid object name: '{args.start or 'HEAD'}'")
        return 128
    # git records "branch: Created from <start_name>" (builtin/branch.c). The
    # start name is the explicit start-point if given, else the current branch
    # name, falling back to the literal "HEAD" when HEAD is detached.
    start_name = args.start if args.start else (cur if cur else "HEAD")
    refs_mod.update_ref(repo, full, start, message=f"branch: Created from {start_name}")
    # -t/--track sets the new branch to track its (local or remote) start point.
    # --track=inherit copies the start-point's upstream; if the start branch has
    # no remote configured, C warns and does not set tracking.
    if track_inherit:
        _set_branch_upstream_inherit(repo, args.name, args.start or start_name, args.quiet)
    elif args.track is not None and args.start is not None:
        _set_branch_upstream(repo, args.name, args.start, args.quiet)
    return 0


def _version_sort_key(name: str):
    import re
    return [int(part) if part.isdigit() else part for part in re.split(r"(\d+)", name)]


def _tag_message_body(repo: Repository, sha: Optional[str]) -> str:
    """Return the message body for a tag list entry: the annotated tag's body
    (after the header) or the lightweight tag's target commit message."""
    if sha is None:
        return ""
    try:
        t, data = objs.read_object(repo, sha)
    except KeyError:
        return ""
    if t == "tag":
        _header, _, msg = data.decode("utf-8", errors="replace").partition("\n\n")
        return msg
    if t == "commit":
        c = objs.parse_commit(data)
        return c.message
    return ""


def _tag_annotation(repo: Repository, sha: Optional[str]) -> str:
    body = _tag_message_body(repo, sha)
    return body.splitlines()[0] if body.strip() else ""


def _tag_list_line(repo: Repository, name: str, sha: Optional[str], lines: int) -> str:
    """Render a 'tag -n<lines>' entry, porting builtin/tag.c list_tags' format
    '%(align:15)%(refname:lstrip=2)%(end) %(contents:lines=N)' plus
    ref-filter.c:append_lines (continuation lines indented by 4 spaces)."""
    body = _tag_message_body(repo, sha)
    msg_lines = body.split("\n")
    # Trailing empty element from a final newline is not a real line.
    if msg_lines and msg_lines[-1] == "":
        msg_lines = msg_lines[:-1]
    shown = msg_lines[:lines] if lines > 0 else []
    first = shown[0] if shown else ""
    out = f"{name:<15} {first}"
    for extra in shown[1:]:
        out += f"\n    {extra}"
    return out


def _tag_options() -> list["_PoOpt"]:
    """The builtin/tag.c option table, as _PoOpt entries, for byte-exact usage
    rendering and unique-prefix (abbreviation) resolution."""
    NOARG, OPTARG, NONEG, HIDDEN = (_PARSEOPT_NOARG, _PARSEOPT_OPTARG,
                                    _PARSEOPT_NONEG, _PARSEOPT_HIDDEN)

    def O(short=None, long=None, argh=None, flags=0, help="", group=False):
        o = _PoOpt()
        if group:
            o.is_group = True
            o.help = help
            return o
        o.short_name = short or ""
        o.long_name = long
        o.argh = argh
        o.flags = flags
        o.help = help
        return o

    return [
        O('l', 'list', flags=NOARG | NONEG, help="list tag names"),
        O('n', None, argh='n', flags=OPTARG, help="print <n> lines of each tag message"),
        O('d', 'delete', flags=NOARG | NONEG, help="delete tags"),
        O('v', 'verify', flags=NOARG | NONEG, help="verify tags"),
        O(group=True, help="Tag creation options"),
        O('a', 'annotate', flags=NOARG, help="annotated tag, needs a message"),
        O('m', 'message', argh='message', flags=NONEG, help="tag message"),
        O('F', 'file', argh='file', flags=0, help="read message from file"),
        O(None, 'trailer', argh='trailer', flags=0, help="add custom trailer(s)"),
        O('e', 'edit', flags=NOARG, help="force edit of tag message"),
        O('s', 'sign', flags=NOARG, help="annotated and GPG-signed tag"),
        O(None, 'cleanup', argh='mode', flags=0,
          help="how to strip spaces and #comments from message"),
        O('u', 'local-user', argh='key-id', flags=0,
          help="use another key to sign the tag"),
        O('f', 'force', flags=NOARG, help="replace the tag if exists"),
        O(None, 'create-reflog', flags=NOARG, help="create a reflog"),
        O(group=True, help="Tag listing options"),
        O(None, 'column', argh='style', flags=OPTARG, help="show tag list in columns"),
        O(None, 'contains', argh='commit', flags=NONEG,
          help="print only tags that contain the commit"),
        O(None, 'no-contains', argh='commit', flags=NONEG,
          help="print only tags that don't contain the commit"),
        O(None, 'with', argh='commit', flags=NONEG | HIDDEN,
          help="print only tags that contain the commit"),
        O(None, 'without', argh='commit', flags=NONEG | HIDDEN,
          help="print only tags that don't contain the commit"),
        O(None, 'merged', argh='commit', flags=NONEG, help="print only tags that are merged"),
        O(None, 'no-merged', argh='commit', flags=NONEG,
          help="print only tags that are not merged"),
        O(None, 'omit-empty', flags=NOARG,
          help="do not output a newline after empty formatted refs"),
        O(None, 'sort', argh='key', flags=0, help="field name to sort on"),
        O(None, 'points-at', argh='object', flags=0, help="print only tags of the object"),
        O(None, 'format', argh='format', flags=0, help="format to use for the output"),
        O(None, 'color', argh='when', flags=OPTARG, help="respect format colors"),
        O('i', 'ignore-case', flags=NOARG, help="sorting and filtering are case insensitive"),
    ]


_TAG_USAGE_LINES = [
    "git tag [-a | -s | -u <key-id>] [-f] [-m <msg> | -F <file>] [-e]\n"
    "        [(--trailer <token>[(=|:)<value>])...]\n"
    "        <tagname> [<commit> | <object>]",
    "git tag -d <tagname>...",
    "git tag [-n[<num>]] -l [--contains <commit>] [--no-contains <commit>]\n"
    "        [--points-at <object>] [--column[=<options>] | --no-column]\n"
    "        [--create-reflog] [--sort=<key>] [--format=<format>]\n"
    "        [--merged <commit>] [--no-merged <commit>] [<pattern>...]",
    "git tag -v [--format=<format>] <tagname>...",
]


def _tag_usage_err() -> int:
    """Emit the full git-tag usage block to stderr, rc 129 (usage_with_options)."""
    sys.stderr.write(_po_render_usage(_TAG_USAGE_LINES, _tag_options(), False, True))
    return 129


def _po_abbrev_resolve(opts: list["_PoOpt"], name: str) -> tuple[Optional[str], list[str]]:
    """Resolve a possibly-abbreviated long option name against an option table,
    mirroring parse-options.c get_value's unique-prefix logic. Returns
    (resolved_full_name, []) on a unique match (exact or prefix), (None, [])
    when unknown, or (None, [candidates]) when ambiguous. Hidden options still
    participate (an exact hidden match wins; prefixes include them)."""
    longs = [o.long_name for o in opts
             if (not o.is_group) and o.long_name is not None]
    # negations: every non-NONEG option also has a "no-" form.
    negs = [f"no-{o.long_name}" for o in opts
            if (not o.is_group) and o.long_name is not None
            and not (o.flags & _PARSEOPT_NONEG)]
    all_names = longs + negs
    if name in all_names:
        return (name, [])
    cands = [n for n in all_names if n.startswith(name)]
    # De-dup while keeping order; an abbrev that matches both --x and --no-x via
    # the same root is still two candidates in git's output.
    if len(cands) == 1:
        return (cands[0], [])
    if not cands:
        return (None, [])
    return (None, cands)


def cmd_tag(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit tag", add_help=False)
    ap.add_argument("-d", "--delete", action="store_true")
    ap.add_argument("-l", "--list", action="store_true")
    ap.add_argument("-a", "--annotate", action="store_true")
    ap.add_argument("-s", "--sign", action="store_true")
    ap.add_argument("-u", "--local-user", dest="local_user", default=None)
    ap.add_argument("-f", "--force", action="store_true")
    ap.add_argument("-m", "--message", action="append", default=None)
    ap.add_argument("-F", "--file", default=None)
    ap.add_argument("-e", "--edit", action="store_true")
    ap.add_argument("--trailer", action="append", default=None)
    ap.add_argument("--cleanup", default=None)
    ap.add_argument("-n", nargs="?", const=1, type=int, default=None, dest="num")
    ap.add_argument("--sort", default=None)
    ap.add_argument("--points-at", nargs="?", const="HEAD", default=None)
    ap.add_argument("--format", default=None)
    ap.add_argument("--contains", default=None)
    ap.add_argument("--no-contains", dest="no_contains", default=None)
    ap.add_argument("--with", dest="with_commit", default=None)
    ap.add_argument("--without", dest="without_commit", default=None)
    ap.add_argument("--merged", nargs="?", const="HEAD", default=None)
    ap.add_argument("--no-merged", dest="no_merged", nargs="?", const="HEAD", default=None)
    ap.add_argument("--column", nargs="?", const="__default__", default=None)
    ap.add_argument("--no-column", dest="no_column", action="store_true")
    ap.add_argument("--omit-empty", dest="omit_empty", action="store_true")
    ap.add_argument("--color", nargs="?", const="always", default=None)
    ap.add_argument("--no-color", dest="no_color", action="store_true")
    ap.add_argument("--create-reflog", dest="create_reflog", action="store_true")
    ap.add_argument("-v", "--verify", action="store_true")
    ap.add_argument("-i", "--ignore-case", dest="ignore_case", action="store_true")
    ap.add_argument("names", nargs="*")
    # Unique-prefix abbreviation: resolve long options against the full tag option
    # table (parse-options.c). An ambiguous prefix (e.g. --col matches --column and
    # --color) dumps the usage to stdout + an "ambiguous option" error rc 129.
    _tag_opts = _tag_options()
    for tok in argv:
        if tok.startswith("--") and tok != "--" and len(tok) > 2:
            body = tok[2:]
            nm = body.split("=", 1)[0]
            resolved, cands = _po_abbrev_resolve(_tag_opts, nm)
            if resolved is None and cands:
                sys.stdout.write(_po_render_usage(_TAG_USAGE_LINES, _tag_opts, False, False))
                _err(f"error: ambiguous option: {nm} (could be "
                     + " or ".join(f"--{c}" for c in cands) + ")")
                return 129
    # --merged/--no-merged consume the next token (default HEAD when last);
    # --column takes an optional attached style only.
    consume = ("--merged", "--no-merged")
    pre: list[str] = []
    i = 0
    while i < len(argv):
        t = argv[i]
        if t in consume:
            pre.append(f"{t}={argv[i + 1]}" if i + 1 < len(argv) else f"{t}=HEAD")
            i += 2 if i + 1 < len(argv) else 1
            continue
        if t == "--column":
            pre.append("--column=__default__")
            i += 1
            continue
        pre.append(t)
        i += 1
    # -u/--local-user (key-id) and -F/--file require a value: emit the exact
    # parse-options error rather than argparse's generic usage dump.
    try:
        _require_value_flags(pre, {
            "-u": "u", "--local-user": "local-user",
            "-F": "F", "--file": "file",
        })
    except _SwitchParseError as exc:
        _err(exc.message)
        return exc.rc
    args = ap.parse_args(pre)
    # --with/--without are hidden synonyms of --contains/--no-contains.
    if args.with_commit is not None and args.contains is None:
        args.contains = args.with_commit
    if args.without_commit is not None and args.no_contains is None:
        args.no_contains = args.without_commit
    # OPT_REF_SORT validates each sort key.
    if args.sort:
        skey = args.sort[1:] if args.sort[:1] in "-+" else args.sort
        serr = _ref_sort_validate(skey)
        if serr is not None:
            _err(serr)
            return 128
    # cmdmode = first of -l/-d/-v; create_tag_object reflects -a/-s/-m/-F/-e/
    # --trailer. builtin/tag.c: when no cmdmode is set, argc==0 or any listing
    # filter implies cmdmode='l'. Then (create_tag_object||force)&&cmdmode -> usage.
    explicit_cmdmode = bool(args.list or args.delete or args.verify)
    create_tag_object = bool(args.annotate or args.sign or args.message
                             or args.file or args.edit or args.trailer)
    cmdmode = explicit_cmdmode
    if not cmdmode:
        list_filters = (args.contains is not None or args.no_contains is not None
                        or args.merged is not None or args.no_merged is not None
                        or args.points_at is not None or args.num is not None)
        if not args.names or list_filters:
            cmdmode = True  # 'l'
    if (create_tag_object or args.force) and cmdmode:
        return _tag_usage_err()
    # Reconstruct the legacy single name/target from the positional list so the
    # create/list paths keep working, while -d/-v consume the whole list.
    args.name = args.names[0] if args.names else None
    args.target = args.names[1] if len(args.names) > 1 else None
    repo = _repo()
    if args.verify:
        # builtin/tag.c verify_tag(): GPG_VERIFY_VERBOSE by default, or
        # GPG_VERIFY_OMIT_STATUS when --format is given (then pretty-print).
        from . import gpgsign
        rc = 0
        head_sym, _ = refs_mod.read_head(repo)
        use_format = args.format is not None
        flags = 4 if use_format else _GPG_VERIFY_VERBOSE  # OMIT_STATUS / VERBOSE
        for name in args.names:
            sha = (refs_mod.rev_parse(repo, name)
                   or refs_mod.read_ref(repo, f"refs/tags/{name}"))
            if sha is None:
                _err(f"error: tag '{name}' not found.")
                rc = 1
                continue
            otype, data = objs.read_object(repo, sha)
            if otype != "tag":
                _err(f"error: {name}: cannot verify a non-tag object of type {otype}.")
                rc = 1
                continue
            payload, signature = gpgsign.parse_signature(data)
            if not signature:
                if flags & _GPG_VERIFY_VERBOSE:
                    sys.stdout.buffer.write(data)
                    sys.stdout.flush()
                _err("error: no signature found")
                rc = 1
                continue
            status, gpg_stderr, gpg_status = gpgsign.verify_signed(repo, payload, signature)
            if not (flags & 4):
                _emit_signature_buffer(payload, flags, gpg_stderr, gpg_status)
            if status:
                rc = 1
                continue
            if use_format:
                # pretty_print_ref() uses the bare command-line name as refname.
                _print(_fer_expand(repo, name, sha, args.format, head_sym))
        return rc
    if (args.list or args.num is not None or args.sort is not None
            or args.points_at is not None or args.format is not None
            or args.contains is not None or args.no_contains is not None
            or args.merged is not None or args.no_merged is not None
            or args.column is not None
            or (args.name is None and not args.delete)):
        import fnmatch
        pattern = args.name
        tags = list(refs_mod.list_tags(repo))
        if args.points_at is not None:
            # ref-filter.c:match_points_at — compare the ref's *tip* object id
            # (for an annotated tag, the tag object itself) against the target,
            # then walk the tag chain comparing each tagged oid. The target is
            # whatever the arg resolves to (a tag name yields the tag oid).
            target = refs_mod.rev_parse(repo, args.points_at)

            def _points_at(tag_name: str) -> bool:
                cur = refs_mod.read_ref(repo, f"refs/tags/{tag_name}")
                while cur is not None:
                    if cur == target:
                        return True
                    try:
                        otype, data = objs.read_object(repo, cur)
                    except Exception:
                        return False
                    if otype != "tag":
                        return False
                    tagged = None
                    for line in data.decode("utf-8", "replace").splitlines():
                        if line.startswith("object "):
                            tagged = line[7:].strip()
                            break
                        if line == "":
                            break
                    cur = tagged
                return False

            tags = [t for t in tags if _points_at(t)]
        if args.contains is not None or args.no_contains is not None:
            graph = _graph_for_repo(repo)

            def _reaches(tip: str, target: str) -> bool:
                stack, seen_c = [tip], set()
                while stack:
                    x = stack.pop()
                    if x == target:
                        return True
                    if x in seen_c:
                        continue
                    seen_c.add(x)
                    info = _commit_tree_parents(repo, x, graph)
                    if info:
                        stack.extend(info[1])
                return False

            def _tag_commit(t):
                return refs_mod.rev_parse(repo, f"refs/tags/{t}^{{commit}}")
            if args.contains is not None:
                cs = refs_mod.rev_parse(repo, args.contains)
                tags = [t for t in tags if (_tag_commit(t) and cs and _reaches(_tag_commit(t), cs))]
            if args.no_contains is not None:
                cs = refs_mod.rev_parse(repo, args.no_contains)
                tags = [t for t in tags if not (_tag_commit(t) and cs and _reaches(_tag_commit(t), cs))]
        if args.merged is not None or args.no_merged is not None:
            graph = _graph_for_repo(repo)

            def _reach2(start: str, target: str) -> bool:
                stack, seen_c = [start], set()
                while stack:
                    x = stack.pop()
                    if x == target:
                        return True
                    if x in seen_c:
                        continue
                    seen_c.add(x)
                    info = _commit_tree_parents(repo, x, graph)
                    if info:
                        stack.extend(info[1])
                return False

            def _tc(t):
                return refs_mod.rev_parse(repo, f"refs/tags/{t}^{{commit}}")
            if args.merged is not None:
                m = refs_mod.rev_parse(repo, args.merged + "^{commit}") or refs_mod.rev_parse(repo, args.merged)
                tags = [t for t in tags if (_tc(t) and m and _reach2(m, _tc(t)))]
            if args.no_merged is not None:
                m = refs_mod.rev_parse(repo, args.no_merged + "^{commit}") or refs_mod.rev_parse(repo, args.no_merged)
                tags = [t for t in tags if not (_tc(t) and m and _reach2(m, _tc(t)))]
        if args.sort:
            key = args.sort.lstrip("-")
            reverse = args.sort.startswith("-")
            if key in ("version:refname", "v:refname"):
                tags.sort(key=_version_sort_key, reverse=reverse)
            else:
                tags.sort(key=str.lower if args.ignore_case else None, reverse=reverse)
        elif args.ignore_case:
            tags.sort(key=str.lower)
        head_sym, _ = refs_mod.read_head(repo)
        selected = []
        for t in tags:
            if pattern:
                import re as _re
                if args.ignore_case:
                    if not _re.match(fnmatch.translate(pattern), t, _re.IGNORECASE):
                        continue
                elif not fnmatch.fnmatch(t, pattern):
                    continue
            selected.append(t)
        # --column lays the plain tag-name list into terminal-width columns.
        if args.column is not None and not args.no_column and args.format is None and args.num is None:
            if args.column == "plain":
                for t in selected:
                    _print(t)
            elif selected:
                for line in _columnate(selected):
                    _print(line)
            return 0
        for t in selected:
            if args.format is not None:
                ref = f"refs/tags/{t}"
                _print(_fer_expand(repo, ref, refs_mod.read_ref(repo, ref) or "", args.format, head_sym))
            elif args.num is not None:
                if args.num <= 0:
                    _print(t)
                else:
                    _print(_tag_list_line(
                        repo, t, refs_mod.read_ref(repo, f"refs/tags/{t}"), args.num))
            else:
                _print(t)
        return 0
    if args.delete:
        # builtin/tag.c delete_tags: collect all named tags (reporting missing
        # ones to stderr in order), delete them, then print every "Deleted tag"
        # line. Missing names set rc 1 but don't abort the rest.
        rc = 0
        collected: list[tuple[str, str, str]] = []  # (name, ref, oid)
        for name in args.names:
            ref = f"refs/tags/{name}"
            sha = refs_mod.read_ref(repo, ref)
            if sha is None:
                _err(f"error: tag '{name}' not found.")
                rc = 1
                continue
            collected.append((name, ref, sha))
        for name, ref, sha in collected:
            refs_mod.delete_ref(repo, ref)
        for name, ref, sha in collected:
            _print(f"Deleted tag '{name}' (was {sha[:7]})")
        return rc
    ref = f"refs/tags/{args.name}"
    if refs_mod.read_ref(repo, ref) is not None and not args.force:
        _err(f"fatal: tag '{args.name}' already exists")
        return 128
    target = refs_mod.rev_parse(repo, args.target) if args.target else refs_mod.rev_parse(repo, "HEAD")
    if not target:
        _err(f"fatal: Failed to resolve '{args.target or 'HEAD'}' as a valid ref.")
        return 128
    # OPT_CLEANUP validation (builtin/tag.c): only strip/verbatim/whitespace (the
    # default, NULL, maps to strip). Anything else dies "Invalid cleanup mode <m>".
    if args.cleanup is not None and args.cleanup not in ("strip", "verbatim", "whitespace"):
        _err(f"fatal: Invalid cleanup mode {args.cleanup}")
        return 128
    # Effective signing: -s/--sign or -u/--local-user force signing; otherwise
    # tag.gpgsign=true signs annotated tags created (builtin/tag.c: opt.sign).
    # -u also selects the signing key (set_signing_key(keyid)).
    do_sign = bool(args.sign or args.local_user is not None)
    if not do_sign:
        from . import gitconfig
        try:
            tcfg = gitconfig.get(repo, "tag.gpgsign")
        except Exception:
            tcfg = None
        if tcfg is not None and _git_config_bool(tcfg):
            do_sign = True
    annotated = (args.annotate or do_sign or args.message is not None
                 or args.file is not None or args.local_user is not None
                 or args.trailer is not None)
    old_sha = refs_mod.read_ref(repo, ref)
    if annotated:
        target_type, _ = objs.read_object(repo, target)
        if args.file is not None:
            message = sys.stdin.read() if args.file == "-" else open(args.file, encoding="utf-8").read()
        elif args.message:
            message = "\n\n".join(args.message)
        else:
            message = ""
        message = _cleanup_commit_message(message, args.cleanup or "strip")
        if args.trailer:
            message = _apply_trailers(
                message, [_normalize_cmdline_trailer(t) for t in args.trailer])
        # create_tag (builtin/tag.c): with no -m/-F supplied and an empty body
        # (no editor available), die "no tag message?". message_given is true
        # whenever -m or -F was passed (even if the resulting text is empty).
        message_given = bool(args.message) or args.file is not None
        if not message_given and not message.strip():
            _err("fatal: no tag message?")
            return 128
        if not message.endswith("\n"):
            message += "\n"
        tagger = objs.build_signature(repo, "committer")
        body = (
            f"object {target}\n"
            f"type {target_type}\n"
            f"tag {args.name}\n"
            f"tagger {tagger}\n"
            f"\n{message}"
        )
        body_bytes = body.encode("utf-8")
        if do_sign:
            from . import gpgsign
            signing_key = (args.local_user if args.local_user
                           else gpgsign.get_signing_key(repo, _ident_no_date(tagger)))
            sig, errmsg = gpgsign.sign_buffer(repo, body_bytes, signing_key)
            if sig is None:
                # builtin/tag.c: do_sign() failure -> "unable to sign the tag",
                # and the message is preserved in .git/TAG_EDITMSG.
                _error(errmsg)
                _err("error: unable to sign the tag")
                try:
                    (repo.gitdir / "TAG_EDITMSG").write_bytes(message.encode("utf-8"))
                except OSError:
                    pass
                _err("The tag message has been left in .git/TAG_EDITMSG")
                return 128
            body_bytes = body_bytes + sig
        tag_sha = objs.write_object(repo, "tag", body_bytes)
        refs_mod.update_ref(repo, ref, tag_sha)
        new_sha = tag_sha
    else:
        refs_mod.update_ref(repo, ref, target)
        new_sha = target
    if args.create_reflog:
        from . import reflog as _reflog
        zero = repo.null_oid()
        # git's reflog message tags the underlying commit:
        # "tag: tagging <abbrev> (<subject>, <committer-date-short>)".
        msg = ""
        if _commit_tree_parents(repo, target) is not None:
            c = objs.parse_commit(objs.read_object(repo, target)[1])
            subj = c.message.splitlines()[0] if c.message.strip() else ""
            msg = f"tag: tagging {target[:7]} ({subj}, {_format_date(c.committer, 'short')})"
        _reflog.append(repo, ref, old_sha or zero, new_sha, msg)
    return 0


_DETACHED_ADVICE = (
    "You are in 'detached HEAD' state. You can look around, make experimental\n"
    "changes and commit them, and you can discard any commits you make in this\n"
    "state without impacting any branches by switching back to a branch.\n"
    "\n"
    "If you want to create a new branch to retain commits you create, you may\n"
    "do so (now or later) by using -c with the switch command. Example:\n"
    "\n"
    "  git switch -c <new-branch-name>\n"
    "\n"
    "Or undo this operation with:\n"
    "\n"
    "  git switch -\n"
    "\n"
    "Turn off this advice by setting config variable advice.detachedHead to false\n"
    "\n"
)


def _restore_paths(repo: Repository, paths: list[str], source_tree: Optional[str], update_index: bool) -> None:
    idx = read_index(repo)
    by_path = idx.by_path()
    for p in paths:
        if source_tree is not None:
            blob = refs_mod._object_at_path(repo, source_tree, p)
            if blob is None:
                continue
        elif p in by_path:
            blob = by_path[p].sha
        else:
            continue
        _, data = objs.read_object(repo, blob)
        (repo.path / p).parent.mkdir(parents=True, exist_ok=True)
        (repo.path / p).write_bytes(data)
        if update_index and p in by_path:
            from .index import IndexEntry, REG_MODE
            idx.upsert(IndexEntry(mode=REG_MODE, sha=blob, path=p))
    if update_index:
        write_index(repo, idx)


def _checkout_two_way_plan(repo: Repository, old_tree: Optional[str],
                           new_tree: str, do_merge: bool,
                           merge_label: Optional[str] = None):
    """Compute the builtin/checkout.c twoway_merge plan for a worktree switch.

    Returns (conflict, carry, merged, report) where:
      conflict — paths whose local edits would be overwritten (target differs);
      carry    — {path: worktree_bytes} local edits the target leaves alone;
      merged   — {path: merged_bytes} from -m 3-way content merges;
      report   — paths to print as "M\\t<path>".
    Returns (None, ...) when there is nothing to inspect (no old tree / same).
    """
    import stat as _st2
    conflict: list[str] = []
    carry: dict[str, bytes] = {}
    merged: dict[str, bytes] = {}
    report: list[str] = []
    if old_tree is None or new_tree == old_tree:
        return conflict, carry, merged, report
    idx_now = read_index(repo).by_path()
    for p in sorted(idx_now):
        full = repo.path / p
        if not (full.exists() or full.is_symlink()):
            continue
        ls = full.lstat()
        wdata = (os.readlink(full).encode() if _st2.S_ISLNK(ls.st_mode)
                 else full.read_bytes())
        wt_sha = objs.hash_bytes("blob", wdata, repo)[0]
        old_blob = refs_mod._object_at_path(repo, old_tree, p)
        new_blob = refs_mod._object_at_path(repo, new_tree, p)
        if wt_sha == old_blob:
            continue
        if new_blob == old_blob:
            carry[p] = wdata
            report.append(p)
        elif do_merge:
            # builtin/checkout.c -m two-way merge: "ours" is the branch being
            # switched to, "theirs" is the local worktree, labelled <branch> and
            # "local" in any conflict markers.
            ob = objs.read_object(repo, old_blob)[1] if old_blob else b""
            bb = objs.read_object(repo, new_blob)[1] if new_blob else b""
            from . import xdiff as _xd
            m, _confl = _xd.xdl_merge(ob, bb, wdata,
                                      name1=(merge_label or "ours"),
                                      name2="local")
            merged[p] = m
            report.append(p)
        else:
            conflict.append(p)
    return conflict, carry, merged, report


def _checkout_overwrite_error(conflict: list[str]) -> None:
    _err("error: Your local changes to the following files would be "
         "overwritten by checkout:")
    for p in conflict:
        _err(f"\t{p}")
    _err("Please commit your changes or stash them before you switch branches.")
    _err("Aborting")


def _checkout_writeout_paths(repo: Repository, paths: list[str],
                             writeout_stage: int) -> int:
    """Port of builtin/checkout.c checkout_paths for --ours/--theirs/-2/-3.
    Writes the requested conflict stage's blob to the worktree, leaving the
    index conflict stages in place. Reports 'Updated N path(s) from the index'
    to stderr (builtin/checkout.c checkout_paths)."""
    idx = read_index(repo)
    all_stages = idx.by_path_all_stages()
    nr_checkouts = 0
    errs = 0
    for p in paths:
        stages = all_stages.get(p)
        if stages is None:
            _err(f"error: pathspec '{p}' did not match any file(s) known to git")
            errs = 1
            continue
        if 0 in stages:
            # Resolved path: plain checkout from the index.
            blob = stages[0].sha
        else:
            ce = stages.get(writeout_stage)
            if ce is None:
                if writeout_stage == 2:
                    _err(f"error: path '{p}' does not have our version")
                else:
                    _err(f"error: path '{p}' does not have their version")
                errs = 1
                continue
            blob = ce.sha
        data = objs.read_object(repo, blob)[1]
        (repo.path / p).parent.mkdir(parents=True, exist_ok=True)
        (repo.path / p).write_bytes(data)
        nr_checkouts += 1
    if nr_checkouts:
        plural = "s" if nr_checkouts != 1 else ""
        _err(f"Updated {nr_checkouts} path{plural} from the index")
    return errs


def cmd_checkout(argv: list[str]) -> int:
    new_branch: Optional[str] = None
    new_branch_force = False  # -B: create-or-reset (force)
    force_detach = False      # explicit -d/--detach
    orphan_branch: Optional[str] = None  # --orphan <name>
    force = False             # -f/--force
    do_merge = False          # -m/--merge
    writeout_stage = 0        # 2 = --ours/-2, 3 = --theirs/-3
    revs: list[str] = []
    paths: list[str] = []
    after_dd = False
    quiet = False
    # Expand bundled short options ("-qb" -> "-q" "-b") the way parse_options
    # does, so "git checkout -qb topic" treats topic as the new branch name.
    # Stop expanding at the first option that consumes a value (-b/-B): the
    # remainder of the cluster is that option's attached argument.
    expanded: list[str] = []
    _seen_dd = False
    for a in argv:
        if _seen_dd or a == "--" or not a.startswith("-") or a == "-" or a.startswith("--"):
            expanded.append(a)
            if a == "--":
                _seen_dd = True
            continue
        # short cluster like -q, -qb, -bTOPIC
        k = 1
        n = len(a)
        emitted_value_opt = False
        while k < n:
            ch = a[k]
            if ch in ("b", "B"):
                # value option: rest of cluster (if any) is the branch name
                rest = a[k + 1:]
                expanded.append("-" + ch)
                if rest:
                    expanded.append(rest)
                emitted_value_opt = True
                break
            expanded.append("-" + ch)
            k += 1
        if not emitted_value_opt:
            pass
    argv = expanded
    i = 0
    while i < len(argv):
        a = argv[i]
        if after_dd:
            paths.append(a)
        elif a == "--":
            after_dd = True
        elif a in ("-b", "-B"):
            i += 1
            new_branch = argv[i] if i < len(argv) else None
            if a == "-B":
                new_branch_force = True
        elif a == "--orphan":
            i += 1
            orphan_branch = argv[i] if i < len(argv) else None
        elif a.startswith("--orphan="):
            orphan_branch = a.split("=", 1)[1]
        elif a in ("-d", "--detach"):
            force_detach = True
        elif a in ("-q", "--quiet"):
            quiet = True
        elif a in ("-f", "--force"):
            force = True
        elif a in ("-m", "--merge"):
            do_merge = True
        elif a in ("--ours", "-2"):
            writeout_stage = 2
        elif a in ("--theirs", "-3"):
            writeout_stage = 3
        elif a.startswith("-") and a != "-":
            pass
        else:
            revs.append(a)
        i += 1
    repo = _repo()

    # Capture the pre-checkout HEAD so each branch switch can append the
    # "checkout: moving from <old> to <new>" HEAD reflog entry git writes.
    head_sym0, old_sha0 = refs_mod.read_head(repo)
    old_name0 = (head_sym0[len("refs/heads/"):] if head_sym0 and head_sym0.startswith("refs/heads/")
                 else (old_sha0[:7] if old_sha0 else None))

    reftable_repo = refs_mod.uses_reftable(repo)

    def _switch_head(target: str, new_sha: Optional[str], new_name: str) -> None:
        """Point HEAD at ``target`` and append the checkout reflog entry.

        For reftable the symref move and its HEAD reflog entry must share one
        transaction (one update_index), so the message is folded into set_head.
        For files the reflog is appended separately, as before.
        """
        msg = f"checkout: moving from {old_name0} to {new_name}"
        if reftable_repo:
            refs_mod.set_head(repo, target,
                              message=(msg if old_sha0 and new_sha else None),
                              old=old_sha0)
        else:
            refs_mod.set_head(repo, target)
            if old_sha0 and new_sha:
                from . import reflog as _reflog
                _reflog.append(repo, "HEAD", old_sha0, new_sha, msg)

    if orphan_branch is not None:
        # builtin/checkout.c --orphan (orphan_from_empty_tree=0 for `checkout`):
        # keep the current index/worktree (new_tree = the start commit's tree),
        # but repoint HEAD at an unborn branch (the ref is not written until the
        # first commit). The start point defaults to HEAD.
        if refs_mod.read_ref(repo, f"refs/heads/{orphan_branch}") is not None:
            _err(f"fatal: a branch named '{orphan_branch}' already exists")
            return 128
        start = refs_mod.rev_parse(repo, revs[0]) if revs else refs_mod.rev_parse(repo, "HEAD")
        if start is not None:
            nt, ndata = objs.read_object(repo, start)
            ntree = objs.parse_commit(ndata).tree if nt == "commit" else start
            workdir.checkout_tree(repo, ntree)
        refs_mod.set_head(repo, f"refs/heads/{orphan_branch}")
        if not quiet:
            _err(f"Switched to a new branch '{orphan_branch}'")
        return 0

    if new_branch:
        branch_exists = refs_mod.read_ref(repo, f"refs/heads/{new_branch}") is not None
        # -b refuses to clobber an existing branch; -B (create-or-reset) force-
        # moves it (builtin/checkout.c: validate_new_branchname vs
        # validate_branchname).
        if branch_exists and not new_branch_force:
            _err(f"fatal: a branch named '{new_branch}' already exists")
            return 128
        start = refs_mod.rev_parse(repo, revs[0]) if revs else refs_mod.rev_parse(repo, "HEAD")
        if not start:
            if not revs:
                # Branching from an unborn HEAD just repoints HEAD at the new
                # branch; no ref is written until the first commit, like git.
                refs_mod.set_head(repo, f"refs/heads/{new_branch}")
                _err(f"Switched to a new branch '{new_branch}'")
                return 0
            _err(f"fatal: '{revs[0]}' is not a commit and a branch '{new_branch}' cannot be created from it")
            return 128
        start_name = revs[0] if revs else "HEAD"
        # create_branch(): forcing an existing branch logs "branch: Reset to
        # <start>"; a fresh branch logs "branch: Created from <start>".
        forcing = new_branch_force and branch_exists
        reflog = (f"branch: Reset to {start_name}" if forcing
                  else f"branch: Created from {start_name}")
        # The files backend skips the ref write (and its reflog entry) when the
        # ref already holds the target value (oideq(old,new)).
        cur_val = refs_mod.read_ref(repo, f"refs/heads/{new_branch}")
        if cur_val != start:
            refs_mod.update_ref(repo, f"refs/heads/{new_branch}", start, message=reflog)
        # Check out the new branch's tree into the worktree before moving HEAD.
        nt, ndata = objs.read_object(repo, start)
        ntree = objs.parse_commit(ndata).tree if nt == "commit" else start
        workdir.checkout_tree(repo, ntree)
        already_on = (cur_branch0 := (head_sym0[len("refs/heads/"):]
                      if head_sym0 and head_sym0.startswith("refs/heads/") else None)
                      ) == new_branch
        _switch_head(f"refs/heads/{new_branch}", start, new_branch)
        if not quiet:
            if already_on:
                _err(f"Reset branch '{new_branch}'")
            elif forcing:
                _err(f"Switched to and reset branch '{new_branch}'")
            else:
                _err(f"Switched to a new branch '{new_branch}'")
        return 0

    # --ours/--theirs/-2/-3 (writeout_stage) and -m/--merge on paths are always
    # the path-restore form even when written without a leading "--". When set,
    # the leading non-flag tokens are pathspecs, not a tree-ish.
    if writeout_stage:
        restore_paths = revs + paths
        return _checkout_writeout_paths(repo, restore_paths, writeout_stage)

    # Path-restore form: `checkout [<tree-ish>] -- <paths>` or `checkout <paths>`.
    if paths or (after_dd):
        source_tree = None
        if revs:
            src = refs_mod.rev_parse(repo, revs[0])
            source_tree = _commit_tree(repo, src) if src else None
        # A pathspec checkout from the index of an unmerged path errors rather
        # than silently restoring (builtin/checkout.c: "path '%s' is unmerged").
        if source_tree is None:
            unmerged = read_index(repo).conflicted_paths()
            bad = [p for p in paths if p in unmerged]
            if bad:
                for p in bad:
                    _err(f"error: path '{p}' is unmerged")
                return 1
        _restore_paths(repo, paths, source_tree, update_index=bool(revs))
        return 0

    if not revs:
        _err("error: you must specify path(s) to restore")
        return 1
    target = revs[0]
    # A bare `checkout <path>` (no rev resolution) against an unmerged index
    # path is the path-restore form and reports the path as unmerged.
    if (not new_branch and refs_mod.rev_parse(repo, target) is None):
        unmerged = read_index(repo).conflicted_paths()
        names = [r for r in revs if r in unmerged]
        if names:
            for p in names:
                _err(f"error: path '{p}' is unmerged")
            return 1
    head_sym, _ = refs_mod.read_head(repo)
    cur_branch = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else None
    on_branch = head_sym is not None and head_sym.startswith("refs/heads/")
    # An explicit -d/--detach detaches HEAD even when the target names a branch.
    is_branch = (refs_mod.read_ref(repo, f"refs/heads/{target}") is not None
                 and not force_detach)
    sha = refs_mod.rev_parse(repo, target)
    if not sha:
        _err(f"error: pathspec '{target}' did not match any file(s) known to git")
        return 1
    t, data = objs.read_object(repo, sha)
    tree = objs.parse_commit(data).tree if t == "commit" else sha

    # Two-way merge for the worktree switch (builtin/checkout.c twoway_merge):
    # carry local edits the target leaves alone (reporting "M\t<path>"), abort
    # when they would be overwritten (unless -f/--force), or 3-way merge with -m.
    _, old_head_sha = refs_mod.read_head(repo)
    old_tree = (objs.parse_commit(objs.read_object(repo, old_head_sha)[1]).tree
                if old_head_sha else None)
    if old_tree is not None and tree != old_tree and not force:
        conflict, carry, merged_bytes, report_modified = _checkout_two_way_plan(
            repo, old_tree, tree, do_merge, merge_label=target)
        if conflict:
            _checkout_overwrite_error(conflict)
            return 1
        if carry or merged_bytes or report_modified:
            workdir.checkout_tree(repo, tree)
            for p, wdata in {**carry, **merged_bytes}.items():
                (repo.path / p).parent.mkdir(parents=True, exist_ok=True)
                (repo.path / p).write_bytes(wdata)
            if is_branch:
                if cur_branch == target:
                    if not quiet:
                        _err(f"Already on '{target}'")
                else:
                    _switch_head(f"refs/heads/{target}", sha, target)
                    if not quiet:
                        _err(f"Switched to branch '{target}'")
            else:
                _switch_head(sha, sha, sha[:7])
                from . import gitconfig
                advice = (gitconfig.get(repo, "advice.detachedhead") or "").lower()
                if (not quiet and not force_detach and on_branch
                        and advice not in ("false", "0", "no", "off")):
                    sys.stderr.write(f"Note: switching to '{target}'.\n\n")
                    sys.stderr.write(_DETACHED_ADVICE)
                subject = _format_subject(objs.parse_commit(data).message) if t == "commit" else ""
                if not quiet:
                    _err(f"HEAD is now at {sha[:7]} {subject}")
            for p in sorted(report_modified):
                _print(f"M\t{p}")
            return 0
    workdir.checkout_tree(repo, tree)
    if is_branch:
        if cur_branch == target:
            if not quiet:
                _err(f"Already on '{target}'")
        else:
            _switch_head(f"refs/heads/{target}", sha, target)
            if not quiet:
                _err(f"Switched to branch '{target}'")
    else:
        _switch_head(sha, sha, sha[:7])
        from . import gitconfig
        advice = (gitconfig.get(repo, "advice.detachedhead") or "").lower()
        # The detached-HEAD advice is suppressed by an explicit -d/--detach
        # (force_detach) and only shown when leaving a branch (old HEAD was a
        # branch). builtin/checkout.c update_refs_for_switch().
        if (not quiet and not force_detach and on_branch
                and advice not in ("false", "0", "no", "off")):
            sys.stderr.write(f"Note: switching to '{target}'.\n\n")
            sys.stderr.write(_DETACHED_ADVICE)
        subject = _format_subject(objs.parse_commit(data).message) if t == "commit" else ""
        if not quiet:
            _err(f"HEAD is now at {sha[:7]} {subject}")
    return 0


def _switch_describe_head(repo: Repository, msg: str, sha: str) -> None:
    """Emit git's '<msg> <abbrev> <subject>' line for a commit (to stderr)."""
    subject = ""
    try:
        t, data = objs.read_object(repo, sha)
        if t == "commit":
            lines = objs.parse_commit(data).message.splitlines()
            subject = lines[0] if lines else ""
    except Exception:
        pass
    _err(f"{msg} {sha[:7]} {subject}")


def _switch_prev_branch(repo: Repository) -> Optional[str]:
    """Resolve switch's '-' / '@{-1}': the branch left by the most recent
    'checkout: moving from <X> to <Y>' HEAD reflog entry."""
    from . import reflog as _reflog
    for _old, _new, _ident, msg in reversed(_reflog.read(repo, "HEAD")):
        if msg.startswith("checkout: moving from "):
            rest = msg[len("checkout: moving from "):]
            frm, _, _ = rest.partition(" to ")
            return frm or None
    return None


def _switch_track_friendly(remote: Optional[str], merge_ref: str) -> str:
    """The friendly name git prints in 'set up to track '<name>'.'."""
    short = merge_ref
    if short.startswith("refs/heads/"):
        short = short[len("refs/heads/"):]
    if remote and remote != ".":
        return f"{remote}/{short}"
    return short


def _switch_resolve_tracking(repo: Repository, real_ref: str):
    """Map a fully-resolved start ref to (remote, merge_ref) for direct
    tracking. A remote-tracking ref under refs/remotes/<r>/<b> with the
    standard fetch refspec maps back to (<r>, refs/heads/<b>); a local
    branch maps to ('.', refs/heads/<b>)."""
    from . import gitconfig
    if real_ref.startswith("refs/remotes/"):
        rest = real_ref[len("refs/remotes/"):]
        # Find a remote whose fetch refspec maps real_ref back to a head.
        for name, value in gitconfig.list_all(repo):
            if not (name.startswith("remote.") and name.endswith(".fetch")):
                continue
            remote_name = name[len("remote."):-len(".fetch")]
            spec = value[1:] if value.startswith("+") else value
            src, _, dst = spec.partition(":")
            if dst.endswith("/*") and src.endswith("/*"):
                dpre, spre = dst[:-1], src[:-1]
                if real_ref.startswith(dpre):
                    tail = real_ref[len(dpre):]
                    return remote_name, spre + tail
        # No refspec matched; fall back to splitting on the remote name.
        head, _, branch = rest.partition("/")
        return head, f"refs/heads/{branch}"
    if real_ref.startswith("refs/heads/"):
        return ".", real_ref
    return ".", real_ref


def _switch_inherit_tracking(repo: Repository, real_ref: str):
    """Resolve --track=inherit: copy the start branch's upstream config.
    Returns (remote, merge_ref) on success, or a warning string to print
    (before switching) when the source has no usable tracking config."""
    from . import gitconfig
    if not real_ref.startswith("refs/heads/"):
        return f"warning: asked to inherit tracking from '{real_ref}', but no remote is set"
    base = real_ref[len("refs/heads/"):]
    remote = gitconfig.get(repo, f"branch.{base}.remote")
    merge = gitconfig.get(repo, f"branch.{base}.merge")
    if not remote:
        return f"warning: asked to inherit tracking from '{base}', but no remote is set"
    if not merge:
        return f"warning: asked to inherit tracking from '{base}', but no merge configuration is set"
    return (remote, merge)


def _switch_write_tracking(repo: Repository, local: str,
                           remote: str, merge_ref: str, quiet: bool) -> None:
    """Write branch.<local>.{remote,merge} and print git's confirmation."""
    from . import gitconfig
    cfg = repo.gitdir / "config"
    gitconfig.write_value(cfg, "branch", local, "remote", remote, mode="set")
    gitconfig.write_value(cfg, "branch", local, "merge", merge_ref, mode="set")
    if not quiet:
        friendly = _switch_track_friendly(remote, merge_ref)
        _print(f"branch '{local}' set up to track '{friendly}'.")


_SWITCH_USAGE = (
    "usage: git switch [<options>] [<branch>]\n"
    "\n"
    "    -c, --[no-]create <branch>\n"
    "                          create and switch to a new branch\n"
    "    -C, --[no-]force-create <branch>\n"
    "                          create/reset and switch to a branch\n"
    "    --[no-]guess          second guess 'git switch <no-such-branch>'\n"
    "    --[no-]discard-changes\n"
    "                          throw away local modifications\n"
    "    -q, --[no-]quiet      suppress progress reporting\n"
    "    --[no-]recurse-submodules[=<checkout>]\n"
    "                          control recursive updating of submodules\n"
    "    --[no-]progress       force progress reporting\n"
    "    -m, --[no-]merge      perform a 3-way merge with the new branch\n"
    "    --[no-]conflict <style>\n"
    "                          conflict style (merge, diff3, or zdiff3)\n"
    "    -d, --[no-]detach     detach HEAD at named commit\n"
    "    -t, --[no-]track[=(direct|inherit)]\n"
    "                          set branch tracking configuration\n"
    "    -f, --[no-]force      force checkout (throw away local modifications)\n"
    "    --[no-]orphan <new-branch>\n"
    "                          new unborn branch\n"
    "    --[no-]overwrite-ignore\n"
    "                          update ignored files (default)\n"
    "    --[no-]ignore-other-worktrees\n"
    "                          do not check if another worktree is using this branch\n"
    "\n"
)


class _SwitchParseError(Exception):
    def __init__(self, message: str, rc: int = 129, show_usage: bool = False):
        super().__init__(message)
        self.message = message
        self.rc = rc
        self.show_usage = show_usage


def _switch_parse(argv: list[str]) -> dict:
    """Faithful subset of git switch's parse-options handling."""
    opts = {"create": None, "force_create": None, "quiet": False,
            "detach": False, "track": None, "args": []}
    i = 0
    n = len(argv)
    saw_dd = False
    while i < n:
        a = argv[i]
        if saw_dd:
            opts["args"].append(a)
            i += 1
            continue
        if a == "--":
            saw_dd = True
            i += 1
            continue
        if a == "-" or not a.startswith("-"):
            opts["args"].append(a)
            i += 1
            continue
        if a.startswith("--"):
            name, eq, val = a[2:].partition("=")
            has_val = bool(eq)
            if name in ("create", "force-create"):
                key = "create" if name == "create" else "force_create"
                if has_val:
                    opts[key] = val
                else:
                    i += 1
                    if i >= n:
                        raise _SwitchParseError(f"error: option `{name}' requires a value")
                    opts[key] = argv[i]
            elif name == "quiet":
                if has_val:
                    raise _SwitchParseError(f"error: option `{name}' takes no value")
                opts["quiet"] = True
            elif name == "detach":
                if has_val:
                    raise _SwitchParseError(f"error: option `{name}' takes no value")
                opts["detach"] = True
            elif name == "track":
                if has_val:
                    if val not in ("direct", "inherit"):
                        raise _SwitchParseError('error: option `--track\' expects "direct" or "inherit"')
                    opts["track"] = val
                else:
                    opts["track"] = "direct"
            elif name == "no-track":
                if has_val:
                    raise _SwitchParseError(f"error: option `{name}' takes no value")
                opts["track"] = "none"
            else:
                raise _SwitchParseError(f"error: unknown option `{name}'", show_usage=True)
            i += 1
            continue
        # Short option cluster, possibly with an attached value.
        j = 1
        while j < len(a):
            ch = a[j]
            if ch in ("c", "C"):
                key = "create" if ch == "c" else "force_create"
                rest = a[j + 1:]
                if rest:
                    opts[key] = rest
                else:
                    i += 1
                    if i >= n:
                        raise _SwitchParseError(f"error: switch `{ch}' requires a value")
                    opts[key] = argv[i]
                break
            elif ch == "q":
                opts["quiet"] = True
            elif ch == "d":
                opts["detach"] = True
            elif ch == "t":
                opts["track"] = "direct"
            else:
                raise _SwitchParseError(f"error: unknown switch `{ch}'", show_usage=True)
            j += 1
        i += 1
    return opts


def cmd_switch(argv: list[str]) -> int:
    try:
        opts = _switch_parse(argv)
    except _SwitchParseError as exc:
        _err(exc.message)
        if exc.show_usage:
            sys.stderr.write(_SWITCH_USAGE)
        return exc.rc

    create = opts["create"]
    force_create = opts["force_create"]
    quiet = opts["quiet"]
    detach = opts["detach"]
    track = opts["track"]
    args = opts["args"]
    new_branch = create or force_create

    if detach and new_branch is not None:
        _err("fatal: '--detach' cannot be used with '-b/-B/--orphan'")
        return 128
    # --track/-t/--no-track without -c/-C makes git DWIM a branch name from the
    # positional argument (strip refs/, remotes/, take the part after '/').
    if track is not None and new_branch is None:
        if not args or args[0] == "--":
            _err("fatal: --track needs a branch name")
            return 128
        argv0 = args[0]
        for pre in ("refs/", "remotes/"):
            if argv0.startswith(pre):
                argv0 = argv0[len(pre):]
        slash = argv0.find("/")
        if slash < 0 or slash == len(argv0) - 1:
            _err("fatal: missing branch name; try -c")
            return 128
        new_branch = argv0[slash + 1:]
        create = new_branch  # behaves like -c <dwimmed-name>
        args = list(args)  # the original arg stays as the start point
    if len(args) > 1:
        _err("fatal: only one reference expected")
        return 128

    repo = _repo()
    head_sym0, old_sha0 = refs_mod.read_head(repo)
    on_branch0 = bool(head_sym0 and head_sym0.startswith("refs/heads/"))
    old_name0 = (head_sym0[len("refs/heads/"):] if on_branch0
                 else (old_sha0 if old_sha0 else None))

    def _log_head(new_sha: Optional[str], new_name: str) -> None:
        from . import reflog as _reflog
        if old_sha0 and new_sha:
            _reflog.append(repo, "HEAD", old_sha0, new_sha,
                           f"checkout: moving from {old_name0} to {new_name}")

    def _leaving_detached(new_sha: Optional[str]) -> None:
        # When leaving a detached HEAD for a different commit, git reports the
        # previous position (or warns about commits left behind if unreachable).
        if quiet or on_branch0 or not old_sha0 or new_sha == old_sha0:
            return
        lost = _switch_orphans(repo, old_sha0)
        if lost:
            plural = "s" if len(lost) != 1 else ""
            verb = "them" if len(lost) != 1 else "it"
            _err(f"Warning: you are leaving {len(lost)} commit{plural} behind, not connected to")
            _err("any of your branches:")
            _err("")
            for c_sha, c_subj in lost:
                _err(f"  {c_sha[:7]} {c_subj}")
            _err("")
            _err(f"If you want to keep {verb} by creating a new branch, this may be a good time")
            _err("to do so with:")
            _err("")
            _err(f" git branch <new-branch-name> {lost[0][0][:7]}")
            _err("")
        else:
            _switch_describe_head(repo, "Previous HEAD position was", old_sha0)

    raw_arg = args[0] if args else None
    # git rewrites the `-` shorthand to `@{-1}` (the previously checked-out
    # branch); the error message reflects the rewritten form.
    if raw_arg == "-":
        raw_arg = "@{-1}"
    if raw_arg == "@{-1}":
        prev = _switch_prev_branch(repo)
        if prev is None:
            _err("fatal: invalid reference: @{-1}")
            return 128
        raw_arg = prev

    # Determine the start point for branch creation / the switch target.
    if new_branch is not None:
        start_arg = raw_arg
        start_sha = (refs_mod.rev_parse(repo, start_arg) if start_arg
                     else refs_mod.rev_parse(repo, "HEAD"))
        if start_arg is not None and start_sha is None:
            _err(f"fatal: invalid reference: {start_arg}")
            return 128
        # A branch is created at the peeled commit of its start point.
        if start_sha is not None:
            start_sha = refs_mod._peel_to_commit(repo, start_sha) or start_sha
        exists = refs_mod.read_ref(repo, f"refs/heads/{new_branch}") is not None
        if create is not None and exists:
            _err(f"fatal: a branch named '{new_branch}' already exists")
            return 128

        # Resolve the real ref of the start point for tracking decisions.
        real_ref = None
        if start_arg is not None:
            real_ref = _switch_dwim_ref(repo, start_arg)
        # Resolve the effective tracking mode. track is None (unset → auto),
        # "none" (--no-track suppresses auto), or "direct"/"inherit" (explicit).
        explicit_track = track in ("direct", "inherit")
        if track in (None, "none"):
            do_track = None
            if track is None and real_ref and real_ref.startswith("refs/remotes/"):
                do_track = "direct"  # autoSetupMerge default for remote starts
        else:
            do_track = track
        if explicit_track:
            # Explicit -t/--track requires the start point to be a branch.
            if real_ref is None or not (real_ref.startswith("refs/heads/")
                                        or real_ref.startswith("refs/remotes/")):
                disp = start_arg if start_arg is not None else "HEAD"
                _err(f"fatal: cannot set up tracking information; starting point '{disp}' is not a branch")
                return 128

        if start_sha is None:
            # Unborn HEAD: just repoint HEAD; ref is written on first commit.
            refs_mod.set_head(repo, f"refs/heads/{new_branch}")
            if not quiet:
                _err(f"Switched to a new branch '{new_branch}'")
            return 0

        # Resolve tracking config up-front: inherit emits its failure
        # warning before the switch happens; direct resolves the remote/merge.
        track_pair = None
        if do_track == "inherit":
            res = _switch_inherit_tracking(repo, real_ref) if real_ref else \
                f"warning: asked to inherit tracking from '{start_arg}', but no remote is set"
            if isinstance(res, str):
                _err(res)
            else:
                track_pair = res
        elif do_track == "direct":
            track_pair = _switch_resolve_tracking(repo, real_ref)

        currently_on = on_branch0 and old_name0 == new_branch
        reset_existing = exists  # only reachable via force_create
        start_name = start_arg if start_arg is not None else "HEAD"
        msg = (f"branch: Reset to {start_name}" if reset_existing
               else f"branch: Created from {start_name}")
        # git snapshots the "leaving detached HEAD" report before updating refs.
        _leaving_detached(start_sha)
        refs_mod.update_ref(repo, f"refs/heads/{new_branch}", start_sha, message=msg)
        tree = _commit_tree(repo, start_sha) or start_sha
        _log_head(start_sha, new_branch)
        workdir.checkout_tree(repo, tree)
        refs_mod.set_head(repo, f"refs/heads/{new_branch}")
        if not quiet:
            if currently_on:
                _err(f"Reset branch '{new_branch}'")
            elif reset_existing:
                _err(f"Switched to and reset branch '{new_branch}'")
            else:
                _err(f"Switched to a new branch '{new_branch}'")
        if track_pair is not None:
            _switch_write_tracking(repo, new_branch, track_pair[0], track_pair[1], quiet)
        return 0

    # No -c/-C: a plain switch (optionally detaching).
    if raw_arg is None:
        if detach:
            # `switch -d` with no argument detaches at the current HEAD.
            if old_sha0 is None:
                if on_branch0:
                    # Unborn HEAD: symref to a branch with no commit yet.
                    _err("fatal: You are on a branch yet to be born")
                else:
                    _err("fatal: missing branch or commit argument")
                return 128
            tree = _commit_tree(repo, old_sha0) or old_sha0
            workdir.checkout_tree(repo, tree)
            _log_head(old_sha0, old_sha0)
            refs_mod.set_head(repo, old_sha0)
            if not quiet:
                _switch_describe_head(repo, "HEAD is now at", old_sha0)
            return 0
        _err("fatal: missing branch or commit argument")
        return 128

    sha = refs_mod.rev_parse(repo, raw_arg)
    if sha is None:
        _err(f"fatal: invalid reference: {raw_arg}")
        return 128
    real_ref = _switch_dwim_ref(repo, raw_arg)

    if detach:
        # Peel tags/objects to the underlying commit; detached HEAD stores it.
        commit_sha = refs_mod._peel_to_commit(repo, sha) or sha
        tree = _commit_tree(repo, commit_sha) or commit_sha
        _leaving_detached(commit_sha)
        workdir.checkout_tree(repo, tree)
        _log_head(commit_sha, raw_arg)
        refs_mod.set_head(repo, commit_sha)
        if not quiet:
            _switch_describe_head(repo, "HEAD is now at", commit_sha)
        return 0

    # Plain switch: the target must be a local branch.
    is_branch = refs_mod.read_ref(repo, f"refs/heads/{raw_arg}") is not None
    if not is_branch:
        if real_ref and real_ref.startswith("refs/tags/"):
            _err(f"fatal: a branch is expected, got tag '{real_ref[len('refs/tags/'):]}'")
        elif real_ref and real_ref.startswith("refs/remotes/"):
            _err(f"fatal: a branch is expected, got remote branch '{real_ref[len('refs/remotes/'):]}'")
        elif real_ref:
            _err(f"fatal: a branch is expected, got '{real_ref}'")
        else:
            _err(f"fatal: a branch is expected, got commit '{raw_arg}'")
        _err("hint: If you want to detach HEAD at the commit, try again with the --detach option.")
        return 128

    if on_branch0 and old_name0 == raw_arg:
        if not quiet:
            _err(f"Already on '{raw_arg}'")
        return 0
    tree = _commit_tree(repo, sha) or sha
    # Two-way merge safety (builtin/checkout.c twoway_merge): carry local edits
    # the target leaves alone, abort when they would be overwritten. switch has
    # no -m, so conflicts always abort.
    old_tree = _commit_tree(repo, old_sha0) if old_sha0 else None
    conflict, carry, _merged, report_modified = _checkout_two_way_plan(
        repo, old_tree, tree, do_merge=False)
    if conflict:
        _checkout_overwrite_error(conflict)
        return 1
    _leaving_detached(sha)
    workdir.checkout_tree(repo, tree)
    for p, wdata in carry.items():
        (repo.path / p).parent.mkdir(parents=True, exist_ok=True)
        (repo.path / p).write_bytes(wdata)
    _log_head(sha, raw_arg)
    refs_mod.set_head(repo, f"refs/heads/{raw_arg}")
    if not quiet:
        _err(f"Switched to branch '{raw_arg}'")
    for p in sorted(report_modified):
        _print(f"M\t{p}")
    return 0


def _switch_dwim_ref(repo: Repository, name: str) -> Optional[str]:
    """Return the full ref that <name> resolves to (git's repo_dwim_ref),
    trying the standard search order, or None if it is not a ref."""
    if name.startswith("refs/") and refs_mod.read_ref(repo, name) is not None:
        return name
    for pat in (f"refs/heads/{name}", f"refs/tags/{name}",
                f"refs/remotes/{name}", f"refs/remotes/{name}/HEAD"):
        if refs_mod.read_ref(repo, pat) is not None:
            return pat
    if name == "HEAD" and refs_mod.read_ref(repo, "HEAD") is not None:
        return "HEAD"
    return None


def _switch_orphans(repo: Repository, old_sha: str):
    """Commits reachable from old_sha but from no ref, newest-first, as
    (sha, subject) — git's 'commits left behind' list."""
    from . import merge as merge_mod
    # Collect ref tips (excluding HEAD itself).
    tips = []
    refs_dir = repo.gitdir / "refs"
    for base in ("heads", "tags", "remotes"):
        d = refs_dir / base
        if not d.exists():
            continue
        for p in d.rglob("*"):
            if p.is_file():
                rel = "refs/" + str(p.relative_to(refs_dir)).replace(os.sep, "/")
                t = refs_mod.read_ref(repo, rel)
                if t:
                    tips.append(t)
    packed = repo.gitdir / "packed-refs"
    if packed.exists():
        for line in packed.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line or line.startswith("#") or line.startswith("^"):
                continue
            sha_part, _, ref_part = line.partition(" ")
            if ref_part.startswith("refs/"):
                tips.append(sha_part)

    def reachable_from_tips(c: str) -> bool:
        for t in tips:
            if t == c or merge_mod.is_ancestor(repo, c, t):
                return True
        return False

    # Walk commits from old_sha; stop descending once we hit a reachable one.
    seen = set()
    stack = [old_sha]
    collected = []  # (sha, subject, commit_timestamp)
    while stack:
        cur = stack.pop()
        if cur in seen:
            continue
        seen.add(cur)
        if reachable_from_tips(cur):
            continue
        subj, cts = "", 0
        try:
            t, data = objs.read_object(repo, cur)
            if t == "commit":
                c = objs.parse_commit(data)
                lines = c.message.splitlines()
                subj = lines[0] if lines else ""
                parts = c.committer.rsplit(" ", 2)
                if len(parts) == 3 and parts[1].lstrip("-").isdigit():
                    cts = int(parts[1])
                for par in c.parents:
                    if par not in seen:
                        stack.append(par)
        except Exception:
            pass
        collected.append((cur, subj, cts))
    # rev-list default order: most recent commit date first.
    collected.sort(key=lambda e: e[2], reverse=True)
    return [(sha, subj) for sha, subj, _ts in collected]


def cmd_restore(argv: list[str]) -> int:
    repo = _repo()
    # Manual parse-options port: the full restore option set (builtin/checkout.c
    # restore_options).  Flags pythongit does not act on are accepted as no-ops.
    staged = False
    worktree = False
    source = None
    quiet = False
    overlay = None  # None unset, True/False
    pathspec_from_file = None
    pathspec_file_nul = False
    patch_mode = False
    unified_seen = False        # -U / --unified
    ihc_seen = False            # --inter-hunk-context
    paths: list[str] = []
    i, n = 0, len(argv)
    dd = False
    while i < n:
        a = argv[i]
        if dd:
            paths.append(a); i += 1; continue
        if a == "--":
            dd = True; i += 1; continue
        if a == "--staged" or a == "-S":
            staged = True
        elif a in ("-W", "--worktree"):
            worktree = True
        elif a in ("-s", "--source"):
            i += 1
            if i >= n:
                sys.stderr.write("error: option `source' requires a value\n")
                return 129
            source = argv[i]
        elif a.startswith("--source="):
            source = a.split("=", 1)[1]
        elif a.startswith("-s") and len(a) > 2:
            source = a[2:]
        elif a in ("-q", "--quiet"):
            quiet = True
        elif a == "--overlay":
            overlay = True
        elif a == "--no-overlay":
            overlay = False
        elif a == "--pathspec-from-file":
            i += 1
            pathspec_from_file = argv[i] if i < n else ""
        elif a.startswith("--pathspec-from-file="):
            pathspec_from_file = a.split("=", 1)[1]
        elif a == "--pathspec-file-nul":
            pathspec_file_nul = True
        elif a in ("--ours", "--theirs", "--ignore-unmerged", "--progress",
                   "--no-progress", "-m", "--merge", "--ignore-skip-worktree-bits",
                   "--recurse-submodules", "--no-recurse-submodules",
                   "-2", "-3"):
            pass  # accepted; conflict-resolution variants not modeled here
        elif a in ("-p", "--patch"):
            patch_mode = True
        elif a == "--conflict" or a.startswith("--conflict="):
            if a == "--conflict":
                i += 1  # consume the style value
        elif a in ("-U", "--unified"):
            # -U/--unified take a value; bare form -> "requires a value" rc 129.
            i += 1
            if i >= n:
                sys.stderr.write("error: option `unified' requires a value\n")
                return 129
            unified_seen = True
        elif a.startswith("--unified=") or (a.startswith("-U") and len(a) > 2):
            unified_seen = True
        elif a == "--inter-hunk-context":
            i += 1
            if i >= n:
                sys.stderr.write("error: option `inter-hunk-context' requires a value\n")
                return 129
            ihc_seen = True
        elif a.startswith("--inter-hunk-context="):
            ihc_seen = True
        elif a.startswith("-") and a != "-":
            if a.startswith("--"):
                sys.stderr.write(f"error: unknown option `{a[2:]}'\n")
            else:
                sys.stderr.write(f"error: unknown switch `{a[1:]}'\n")
            return 129
        else:
            paths.append(a)
        i += 1

    # builtin/checkout.c: --unified (-U) and --inter-hunk-context only apply to
    # the interactive patch flow, so they die unless --patch is also given.
    if unified_seen and not patch_mode:
        _err("fatal: the option '--unified' requires '--patch'")
        return 128
    if ihc_seen and not patch_mode:
        _err("fatal: the option '--inter-hunk-context' requires '--patch'")
        return 128

    if pathspec_from_file is not None:
        raw = (sys.stdin.buffer.read() if pathspec_from_file == "-"
               else open(pathspec_from_file, "rb").read())
        sep = "\0" if pathspec_file_nul else "\n"
        paths.extend(p for p in raw.decode("utf-8").split(sep) if p)

    # builtin/checkout.c: at least one path is required for restore.
    if not paths:
        _err("fatal: you must specify path(s) to restore")
        return 128

    idx = read_index(repo)
    # The source tree: --source if given, else HEAD for --staged. Default target
    # is the worktree; --staged targets the index; both can be combined.
    src_map = None
    if source is not None:
        src_tree = (refs_mod.rev_parse(repo, source + "^{tree}")
                    or refs_mod.rev_parse(repo, source))
        src_map = {p: sha for p, _m, sha in workdir.iter_tree_files(repo, src_tree)} if src_tree else {}
    do_staged = staged
    do_worktree = worktree or not staged

    # Pathspec validation: each literal (non-magic, non-glob) path must match a
    # tracked entry — the index, or the --source tree.  dir.c errors otherwise.
    by_path0 = idx.by_path()
    match_set = set(src_map) if src_map is not None else set(by_path0)
    if src_map is None:
        match_set |= set(workdir._head_tree_map(repo))
    bad = None
    for p in paths:
        if p and (p[0] == ":" or any(ch in p for ch in "*?[")):
            continue  # pathspec magic/glob: not literally validated here
        if p not in match_set and not any(
                m == p or m.startswith(p.rstrip("/") + "/") for m in match_set):
            bad = p
            break
    if bad is not None:
        _err(f"error: pathspec '{bad}' did not match any file(s) known to git")
        return 1

    if do_staged:
        from .index import REG_MODE, IndexEntry
        stage_map = src_map if src_map is not None else workdir._head_tree_map(repo)
        for p in paths:
            if p in stage_map:
                idx.upsert(IndexEntry(mode=REG_MODE, sha=stage_map[p], path=p))
            else:
                idx.remove(p)
        write_index(repo, idx)

    if do_worktree:
        # Worktree source: --source tree if given, else the index.
        by_path = idx.by_path()
        for p in paths:
            sha = src_map.get(p) if src_map is not None else (by_path[p].sha if p in by_path else None)
            if sha is not None:
                _t, data = objs.read_object(repo, sha)
                (repo.path / p).parent.mkdir(parents=True, exist_ok=True)
                (repo.path / p).write_bytes(data)
    return 0


def _reset_worktree_path(repo: Repository, p: str, sha: Optional[str], mode: Optional[int]) -> None:
    """Materialize (or delete) one worktree path during reset --merge/--keep."""
    full = repo.path / p
    if sha is None:
        if full.exists() or full.is_symlink():
            full.unlink()
        return
    data = objs.read_object(repo, sha)[1]
    full.parent.mkdir(parents=True, exist_ok=True)
    full.write_bytes(data)
    if mode is not None and (mode & 0o111):
        full.chmod(full.stat().st_mode | 0o111)


def _reset_merge_keep(repo: Repository, kind: str, target_sha: str, target_tree: str,
                      treeish: str) -> int:
    """reset --merge / --keep: a two-way merge that updates files differing
    between HEAD and the target while protecting local changes (atomically)."""
    head_sha = refs_mod.rev_parse(repo, "HEAD")
    head_tree = _commit_tree(repo, head_sha) if head_sha else None
    H = workdir.flatten_tree(repo, head_tree) if head_tree else {}
    T = workdir.flatten_tree(repo, target_tree) if target_tree else {}
    idx = read_index(repo)
    I = {p: e.sha for p, e in idx.by_path().items()}

    def wt_sha(p: str) -> Optional[str]:
        full = repo.path / p
        if not (full.exists() or full.is_symlink()):
            return None
        import stat as _st
        ls = full.lstat()
        data = os.readlink(full).encode() if _st.S_ISLNK(ls.st_mode) else full.read_bytes()
        return objs.hash_bytes("blob", data, repo)[0]

    paths = sorted(set(H) | set(T) | set(I))
    # Dry-run: report the first blocking entry (index order) and abort wholesale.
    for p in paths:
        h, t, i = H.get(p), T.get(p), I.get(p)
        if h == t:
            continue
        w = wt_sha(p)
        if kind == "keep" and i != h:
            _err(f"error: Entry '{p}' would be overwritten by merge. Cannot merge.")
            _err(f"fatal: Could not reset index file to revision '{treeish}'.")
            return 128
        if w != i:
            _err(f"error: Entry '{p}' not uptodate. Cannot merge.")
            _err(f"fatal: Could not reset index file to revision '{treeish}'.")
            return 128

    # Capture the per-path worktree state before any mutation.
    W = {p: wt_sha(p) for p in paths}
    head_sym, _ = refs_mod.read_head(repo)
    if head_sym:
        refs_mod.update_ref(repo, head_sym, target_sha, message=f"reset: moving to {treeish}")
    else:
        refs_mod.set_head(repo, target_sha)
    workdir.read_tree(repo, target_tree)
    new_idx = read_index(repo).by_path()
    for p in paths:
        h, t, i, w = H.get(p), T.get(p), I.get(p), W[p]
        if kind == "keep":
            update = h != t  # checks guaranteed i==h==w for these
        else:  # merge: update unless there is an unstaged change to keep
            update = w == i
        if update:
            tmode = new_idx[p].mode if p in new_idx else None
            _reset_worktree_path(repo, p, t, tmode)
    return 0


def _parse_options_int(name_disp: str, raw: str, precision: int = 4) -> int:
    """Faithful port of parse-options.c OPTION_INTEGER value parsing
    (git_parse_signed + get_unit_factor + the precision range check).

    *name_disp* is the already-formatted ``optname()`` string ("switch `U'" or
    "option `unified'") used in the diagnostics.  *raw* is the option argument
    text (already separated from the option, never None).  *precision* is the
    sizeof() of the target integer (4 = int).  Raises _SwitchParseError
    (rc 129, no usage block) on a malformed or out-of-range value, mirroring
    git's error() return from the option callback.
    """
    if raw == "":
        # OPTION_INTEGER: "} else if (!*arg) { error("%s expects a numerical
        # value") }" — checked before git_parse_signed is ever called.
        raise _SwitchParseError(
            f"error: {name_disp} expects a numerical value")
    upper_bound = (1 << (precision * 8 - 1)) - 1
    lower_bound = -upper_bound - 1
    # git_parse_signed: strtoimax(value, &end, 0) then get_unit_factor(end).
    s = raw
    sign = 1
    body = s
    if body[:1] in ("+", "-"):
        sign = -1 if body[0] == "-" else 1
        body = body[1:]
    # strtoimax base 0: 0x.. hex, 0.. octal, else decimal.  We require at least
    # one digit to be consumed (end == value otherwise -> EINVAL).
    digits = body
    factor = 1
    if digits and digits[-1] in "kKmMgG":
        factor = {"k": 1024, "m": 1024 * 1024,
                  "g": 1024 * 1024 * 1024}[digits[-1].lower()]
        digits = digits[:-1]
    base = 10
    if digits[:2] in ("0x", "0X"):
        base = 16
        num = digits[2:]
        valid = bool(num) and all(c in "0123456789abcdefABCDEF" for c in num)
    elif digits[:1] == "0" and len(digits) > 1:
        base = 8
        num = digits
        valid = all(c in "01234567" for c in num)
    else:
        num = digits
        valid = bool(num) and all(c in "0123456789" for c in num)
    if not valid:
        raise _SwitchParseError(
            f"error: {name_disp} expects an integer value with an "
            "optional k/m/g suffix")
    value = sign * int(num, base) * factor
    # git_parse_signed's ERANGE branch and the trailing "value < lower_bound"
    # check both report the same out-of-range diagnostic.
    if not (lower_bound <= value <= upper_bound):
        raise _SwitchParseError(
            f"error: value {raw} for {name_disp} not in range "
            f"[{lower_bound},{upper_bound}]")
    return value


def _reset_extract_context(argv: list[str]) -> tuple[int, int, list[str]]:
    """Pull -U/--unified and --inter-hunk-context out of *argv* with git's
    OPTION_INTEGER ('U'/'unified', NONEG) and (0/'inter-hunk-context', NONEG)
    semantics, returning (context, interhunkcontext, remaining_argv).

    Defaults are -1 (the OPT_DIFF_UNIFIED / OPT_DIFF_INTERHUNK_CONTEXT
    sentinels meaning "not set").  Everything else is left in remaining_argv
    for argparse.  Stops splitting at "--".
    """
    context = -1
    interhunk = -1
    rest: list[str] = []
    i = 0
    n = len(argv)
    while i < n:
        a = argv[i]
        if a == "--":
            rest.extend(argv[i:])
            break
        if a == "--unified":
            i += 1
            if i >= n:
                raise _SwitchParseError("error: option `unified' requires a value")
            context = _parse_options_int("option `unified'", argv[i])
        elif a.startswith("--unified="):
            context = _parse_options_int("option `unified'", a[len("--unified="):])
        elif a == "--inter-hunk-context":
            i += 1
            if i >= n:
                raise _SwitchParseError(
                    "error: option `inter-hunk-context' requires a value")
            interhunk = _parse_options_int(
                "option `inter-hunk-context'", argv[i])
        elif a.startswith("--inter-hunk-context="):
            interhunk = _parse_options_int(
                "option `inter-hunk-context'", a[len("--inter-hunk-context="):])
        elif a.startswith("-") and a != "-" and not a.startswith("--"):
            # Short-option cluster (e.g. -pU2): scan char by char so that a 'U'
            # appearing after value-less flags still consumes the rest of the
            # token (or the next argv) as its integer value, matching how
            # parse_options walks a packed short-option string.  Non-'U' chars
            # are re-emitted as their own short token for argparse to handle.
            cluster = a[1:]
            j = 0
            keep = ""
            while j < len(cluster):
                ch = cluster[j]
                if ch == "U":
                    attached = cluster[j + 1:]
                    if attached:
                        context = _parse_options_int("switch `U'", attached)
                    else:
                        i += 1
                        if i >= n:
                            raise _SwitchParseError(
                                "error: switch `U' requires a value")
                        context = _parse_options_int("switch `U'", argv[i])
                    break
                keep += ch
                j += 1
            if keep:
                rest.append("-" + keep)
        else:
            rest.append(a)
        i += 1
    return context, interhunk, rest


def cmd_reset(argv: list[str]) -> int:
    try:
        context, interhunk, argv = _reset_extract_context(argv)
    except _SwitchParseError as exc:
        sys.stderr.write(exc.message + "\n")
        return exc.rc
    # builtin/reset.c: the mode flags are OPT_SET_INT_F on one shared variable,
    # so combining/repeating them is legal and last-one-wins.  Extract them
    # (and the accepted-no-op --recurse-submodules / --auto-advance) before
    # argparse so a combination like "--soft --hard" is not rejected.
    reset_mode = None  # last-wins among soft/mixed/hard/merge/keep
    pre_rest: list[str] = []
    _ri, _rn = 0, len(argv)
    _seen_dd = False
    while _ri < _rn:
        _t = argv[_ri]
        if _seen_dd:
            pre_rest.append(_t); _ri += 1; continue
        if _t == "--":
            _seen_dd = True; pre_rest.append(_t); _ri += 1; continue
        if _t in ("--soft", "--mixed", "--hard", "--merge", "--keep"):
            reset_mode = _t[2:]
        elif _t == "--recurse-submodules" or _t.startswith("--recurse-submodules="):
            pass  # accepted; pythongit has no submodules
        elif _t in ("--no-recurse-submodules", "--auto-advance",
                    "--no-auto-advance"):
            pass
        else:
            pre_rest.append(_t)
        _ri += 1
    argv = pre_rest

    ap = argparse.ArgumentParser(prog="pygit reset", add_help=False)
    ap.add_argument("-q", "--quiet", action="store_true")
    ap.add_argument("-p", "--patch", dest="patch", action="store_true")
    ap.add_argument("-N", "--intent-to-add", dest="intent_to_add", action="store_true")
    ap.add_argument("--no-refresh", dest="no_refresh", action="store_true")
    ap.add_argument("--refresh", action="store_true")
    ap.add_argument("--pathspec-from-file", dest="pathspec_from_file", default=None)
    ap.add_argument("--pathspec-file-nul", dest="pathspec_file_nul", action="store_true")
    ap.add_argument("args", nargs="*")
    args = ap.parse_args(argv)
    # Reconstruct the per-mode booleans the rest of the function reads.
    args.soft = reset_mode == "soft"
    args.mixed = reset_mode == "mixed"
    args.hard = reset_mode == "hard"
    args.merge = reset_mode == "merge"
    args.keep = reset_mode == "keep"
    repo = _repo()

    # Split into an optional treeish and pathspecs.
    positionals = list(args.args)
    paths: list[str] = []
    if "--" in positionals:
        idx_dd = positionals.index("--")
        paths = positionals[idx_dd + 1:]
        positionals = positionals[:idx_dd]
    treeish = "HEAD"
    from_file_paths: list[str] = []
    if args.pathspec_from_file is not None:
        raw = (sys.stdin.buffer.read() if args.pathspec_from_file == "-"
               else open(args.pathspec_from_file, "rb").read())
        sep = "\0" if args.pathspec_file_nul else "\n"
        from_file_paths = [p for p in raw.decode("utf-8").split(sep) if p]
    # builtin/reset.c parse_args(): classify positionals into <rev> + <paths>.
    explicit_dd = "--" in args.args
    used_dd_paths = explicit_dd  # whether '--' supplied the path separator

    def _looks_like_pathspec(arg: str) -> bool:
        # setup.c looks_like_pathspec: a leading ':' magic prefix or a glob char.
        if arg and arg[0] == ":":
            return True
        return any(ch in arg for ch in "*?[")

    def _check_filename(arg: str) -> bool:
        full = repo.path / arg
        return full.exists() or full.is_symlink()

    def _die_ambiguous(arg: str) -> int:
        _err(f"fatal: ambiguous argument '{arg}': unknown revision or path "
             "not in the working tree.\n"
             "Use '--' to separate paths from revisions, like this:\n"
             "'git <command> [<revision>...] -- [<file>...]'")
        return 128

    rc_ambig = None
    if positionals and not explicit_dd:
        first = positionals[0]
        has_more = len(positionals) > 1 or bool(paths) or bool(from_file_paths)
        if not has_more:
            # Single argument: it cannot be a tree, only a committish or a path.
            if refs_mod.rev_parse(repo, first) is not None and _commit_tree(
                    repo, refs_mod.rev_parse(repo, first)) is not None:
                # Resolvable as a commit -> rev.  verify_non_filename is silent
                # unless the same name is also a tracked file (warning omitted).
                treeish = first
                positionals = positionals[1:]
            else:
                # Treat as a filename; if it does not exist (and is not a
                # pathspec magic/glob), git dies with the ambiguous error.
                if not (_looks_like_pathspec(first) or _check_filename(first)):
                    rc_ambig = _die_ambiguous(first)
                paths = positionals + paths
                positionals = []
        else:
            # Multiple args (or paths present): argv[0] may be a tree.
            if refs_mod.rev_parse(repo, first) is not None:
                treeish = first
                paths = positionals[1:] + paths
                positionals = []
            else:
                if not (_looks_like_pathspec(first) or _check_filename(first)):
                    rc_ambig = _die_ambiguous(first)
                paths = positionals + paths
                positionals = []
    elif positionals:
        # An explicit '--' was given; the single pre-'--' token (if any) is the
        # <rev>/<tree> (git's `argv[1] == "--"` branch sets rev = argv[0]).
        treeish = positionals[0]
        positionals = positionals[1:]
    if rc_ambig is not None:
        return rc_ambig
    paths += from_file_paths
    # Validate explicit-path resets too: every named path must be a known
    # pathspec (tracked / present), else the ambiguous-argument error fires.
    if paths and used_dd_paths:
        for p in paths:
            if not (_looks_like_pathspec(p) or _check_filename(p)
                    or refs_mod._object_at_path(repo, _commit_tree(
                        repo, refs_mod.rev_parse(repo, treeish) or "") or "", p) is not None):
                return _die_ambiguous(p)

    mode = ("soft" if args.soft else "hard" if args.hard else "merge" if args.merge
            else "keep" if args.keep else "mixed")

    # builtin/reset.c after parse_options: a value below the -1 "unset" sentinel
    # is rejected outright (this runs for both patch and non-patch modes).
    if context < -1:
        _err("fatal: '--unified' cannot be negative")
        return 128
    if interhunk < -1:
        _err("fatal: '--inter-hunk-context' cannot be negative")
        return 128

    # reset --patch: hand the selected pathspec to the shared add-patch engine.
    if args.patch:
        if args.pathspec_from_file is not None:
            _err("fatal: options '--pathspec-from-file' and '--patch' cannot be used together")
            return 128
        reset_type_given = args.soft or args.hard or args.merge or args.keep
        if reset_type_given:
            _err("fatal: options '--patch' and '--{hard,mixed,soft}' cannot be used together")
            return 128
        # The revision was split out above (default "HEAD").
        if refs_mod.rev_parse(repo, treeish) is None:
            _err(f"fatal: Failed to resolve '{treeish}' as a valid tree.")
            return 128
        from . import addpatch
        rc = addpatch.run_add_p(repo, "reset", treeish, paths,
                                context=context, interhunkcontext=interhunk)
        return 1 if rc else 0

    # Non-patch reset: the diff-context options only make sense with --patch.
    if context != -1:
        _err("fatal: the option '--unified' requires '--patch'")
        return 128
    if interhunk != -1:
        _err("fatal: the option '--inter-hunk-context' requires '--patch'")
        return 128

    if paths and mode != "mixed":
        _err(f"fatal: Cannot do {mode} reset with paths.")
        return 128

    if paths and args.mixed:
        _err("warning: --mixed with paths is deprecated; use 'git reset -- <paths>' instead.")

    if paths:
        # Pathspec reset: restore the named index entries to <treeish>.
        sha = refs_mod.rev_parse(repo, treeish)
        if sha is None:
            _err(f"fatal: ambiguous argument '{treeish}'")
            return 128
        tree = _commit_tree(repo, sha) or sha
        idx = read_index(repo)
        for p in paths:
            blob = refs_mod._object_at_path(repo, tree, p)
            if blob is None:
                idx.remove(p)
            else:
                from .index import IndexEntry, REG_MODE
                idx.upsert(IndexEntry(mode=REG_MODE, sha=blob, path=p))
        write_index(repo, idx)
        # Report files now differing between the worktree and the reset index,
        # matching C Git's "Unstaged changes after reset:" diff-files summary.
        new_idx = read_index(repo).by_path()
        modified: list[str] = []
        for p in paths:
            entry = new_idx.get(p)
            if entry is None:
                continue
            full = repo.path / p
            if not (full.exists() or full.is_symlink()):
                modified.append((p, "D"))
            else:
                wt_sha, _ = objs.hash_bytes("blob", full.read_bytes(), repo)
                if wt_sha != entry.sha:
                    modified.append((p, "M"))
        if modified and not args.quiet:
            _print("Unstaged changes after reset:")
            for p, st in sorted(modified):
                _print(f"{st}\t{p}")
        return 0

    sha = refs_mod.rev_parse(repo, treeish)
    if not sha:
        return 128
    t, data = objs.read_object(repo, sha)
    tree = objs.parse_commit(data).tree if t == "commit" else sha
    # --merge / --keep run a protected two-way merge (and move HEAD themselves,
    # only after their abort checks pass).
    if mode in ("merge", "keep"):
        return _reset_merge_keep(repo, mode, sha, tree, treeish)
    head_sym, _ = refs_mod.read_head(repo)
    if head_sym:
        refs_mod.update_ref(repo, head_sym, sha, message=f"reset: moving to {treeish}")
    else:
        refs_mod.set_head(repo, sha)
    if mode == "soft":
        return 0
    if mode == "hard":
        workdir.checkout_tree(repo, tree)
        if t == "commit" and not args.quiet:
            subject = objs.parse_commit(data).message.splitlines()[0] if data else ""
            _print(f"HEAD is now at {sha[:7]} {subject}")
        return 0
    # mixed (default): reset the index to the target, then report files whose
    # worktree content now differs from it (unless -q / --no-refresh).
    old_paths = set(read_index(repo).by_path())
    workdir.read_tree(repo, tree)
    if args.intent_to_add:
        # -N: paths the reset dropped from the index but still in the worktree
        # are re-added as intent-to-add.
        idx2 = read_index(repo)
        now = set(idx2.by_path())
        empty = objs.write_object(repo, "blob", b"")
        changed = False
        for p in old_paths - now:
            full = repo.path / p
            if full.exists() or full.is_symlink():
                from .index import IndexEntry
                e = IndexEntry(mode=workdir._mode_for(full), sha=empty, path=p)
                e.intent_to_add = True
                idx2.upsert(e)
                changed = True
        if changed:
            write_index(repo, idx2)
    if not args.quiet and not args.no_refresh:
        new_idx = read_index(repo).by_path()
        modified = []
        import stat as _st
        for p, entry in new_idx.items():
            full = repo.path / p
            if entry.intent_to_add:
                modified.append((p, "A"))
                continue
            if not (full.exists() or full.is_symlink()):
                modified.append((p, "D"))
                continue
            ls = full.lstat()
            wdata = os.readlink(full).encode() if _st.S_ISLNK(ls.st_mode) else full.read_bytes()
            if objs.hash_bytes("blob", wdata, repo)[0] != entry.sha:
                modified.append((p, "M"))
        if modified:
            _print("Unstaged changes after reset:")
            for p, stt in sorted(modified):
                _print(f"{stt}\t{p}")
    return 0


def _config_list_pairs(repo: Optional[Repository]) -> list[tuple[str, str]]:
    from . import gitconfig
    return gitconfig.list_all(repo)


def _config_typed(value: str, type_: Optional[str]) -> str:
    """Apply git config --type normalization (bool / int / bool-or-int)."""
    if not type_:
        return value
    v = value.strip()
    if type_ == "bool":
        low = v.lower()
        if low in ("true", "yes", "on", "1") or v == "":
            return "true"
        if low in ("false", "no", "off", "0"):
            return "false"
        return value
    if type_ in ("int", "bool-or-int"):
        m = __import__("re").match(r"^(-?\d+)([kKmMgG]?)$", v)
        if m:
            n = int(m.group(1))
            mult = {"k": 1024, "m": 1024 ** 2, "g": 1024 ** 3}.get(m.group(2).lower(), 1)
            return str(n * mult)
        return value
    return value


def cmd_config(argv: list[str]) -> int:
    from . import gitconfig

    is_global = False
    is_local = False
    name_only = False
    show_origin = False
    file_path: Optional[str] = None
    default_val: Optional[str] = None
    type_: Optional[str] = None
    action: Optional[str] = None   # get | get_all | get_regexp | list | unset | unset_all | add | replace_all
    positional: list[str] = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--default":
            i += 1
            default_val = argv[i] if i < len(argv) else None
        elif a.startswith("--default="):
            default_val = a.split("=", 1)[1]
        elif a == "--type":
            i += 1
            type_ = argv[i] if i < len(argv) else None
        elif a.startswith("--type="):
            type_ = a.split("=", 1)[1]
        elif a == "--global":
            is_global = True
        elif a == "--local":
            is_local = True
        elif a == "--system":
            pass
        elif a == "--name-only":
            name_only = True
        elif a == "--show-origin":
            show_origin = True
        elif a in ("-f", "--file"):
            i += 1
            file_path = argv[i] if i < len(argv) else None
        elif a.startswith("--file="):
            file_path = a.split("=", 1)[1]
        elif a in ("-l", "--list"):
            action = "list"
        elif a == "--get":
            action = "get"
        elif a == "--get-all":
            action = "get_all"
        elif a == "--get-regexp":
            action = "get_regexp"
        elif a == "--unset":
            action = "unset"
        elif a == "--unset-all":
            action = "unset_all"
        elif a == "--add":
            action = "add"
        elif a == "--replace-all":
            action = "replace_all"
        elif a == "--":
            i += 1
            positional.extend(argv[i:])
            break
        elif a.startswith("-") and a != "-":
            # Unknown flags are ignored for now; common value-type flags
            # (--bool, --int) don't change which value is stored.
            pass
        else:
            positional.append(a)
        i += 1

    repo: Optional[Repository] = None

    def get_repo() -> Repository:
        nonlocal repo
        if repo is None:
            repo = _repo()
        return repo

    if action == "list" or (action is None and not positional):
        if action is None and not positional:
            action = "list"
    if action == "list":
        try:
            repo = _repo()
        except RepositoryError:
            repo = None
        origin = ""
        if show_origin and repo is not None:
            origin = "file:" + os.path.relpath(repo.gitdir / "config") + "\t"
        for key, value in gitconfig.list_all(repo):
            line = key if name_only else f"{key}={value}"
            _print(origin + line)
        return 0

    if action == "get_regexp":
        try:
            repo = _repo()
        except RepositoryError:
            repo = None
        import re as _re
        if not positional:
            _err("error: wrong number of arguments, should be from 1 to 3")
            return 129
        pat = _re.compile(positional[0])
        found = False
        for key, value in gitconfig.list_all(repo):
            if pat.search(key):
                _print(key if name_only else f"{key} {value}")
                found = True
        return 0 if found else 1

    if not positional:
        _err("error: wrong number of arguments, should be from 1 to 3")
        return 129
    name = positional[0]
    value = positional[1] if len(positional) > 1 else None

    parts = gitconfig.split_key(name)
    if parts is None:
        _err(f"error: key does not contain a section: {name}")
        return 1
    section, subsection, key = parts

    # Reads
    if action in ("get", "get_all") or (action is None and value is None):
        try:
            repo = _repo()
        except RepositoryError:
            repo = None
        values = gitconfig.get_all(repo, name)
        if not values:
            if default_val is not None:
                _print(_config_typed(default_val, type_))
                return 0
            return 1
        if action == "get_all":
            for v in values:
                _print(_config_typed(v, type_))
        else:
            _print(_config_typed(values[-1], type_))
        return 0

    # Writes (and unsets) operate on a single file.
    if file_path is not None:
        cfg_path = Path(file_path)
    elif is_global:
        cfg_path = Path(os.environ.get("GIT_CONFIG_GLOBAL") or (Path.home() / ".gitconfig"))
    else:
        cfg_path = get_repo().gitdir / "config"

    if action in ("unset", "unset_all"):
        rc = gitconfig.unset_value(cfg_path, section, subsection, key, all_values=(action == "unset_all"))
        return 0 if rc == 0 else rc
    if value is None:
        _err("error: wrong number of arguments, should be from 1 to 3")
        return 129
    mode = {"add": "add", "replace_all": "replace_all"}.get(action, "set")
    gitconfig.write_value(cfg_path, section, subsection, key, value, mode=mode)
    return 0


def _config_section_key(name: str) -> tuple[str, str]:
    prefix, sep, key = name.rpartition(".")
    if not sep or not prefix or not key:
        return "", ""
    section, dot, subsection = prefix.partition(".")
    if dot:
        return f'{section} "{subsection}"', key
    return section, key


_REMOTE_SUBCOMMANDS = {"add", "rename", "remove", "rm", "set-head", "show",
                       "prune", "update", "set-branches", "get-url", "set-url"}


def cmd_remote(argv: list[str]) -> int:
    verbose = False
    rest: list[str] = []
    for a in argv:
        if a in ("-v", "--verbose"):
            verbose = True
        else:
            rest.append(a)
    action = None
    if rest and not rest[0].startswith("-"):
        if rest[0] in _REMOTE_SUBCOMMANDS:
            action = rest[0]
            rest = rest[1:]
        else:
            # parse-options-style: an unrecognised subcommand is an error
            # (builtin/remote.c, OPT_SUBCOMMAND dispatch).
            from ._transport_usage import REMOTE_USAGE
            sys.stderr.write(f"error: unknown subcommand: `{rest[0]}'\n")
            sys.stderr.write(REMOTE_USAGE)
            return 129
    repo = _repo()
    from . import gitconfig
    cfg_path = repo.gitdir / "config"

    def _remote_unreadable(name: str) -> int:
        """git's 'does not appear to be a git repository' fatal block (rc 128)
        emitted whenever a subcommand needs to read from the named remote and
        cannot (no network / unconfigured / unreachable)."""
        _err(f"fatal: '{name}' does not appear to be a git repository")
        _err("fatal: Could not read from remote repository.")
        _err("")
        _err("Please make sure you have the correct access rights")
        _err("and the repository exists.")
        return 128

    def _write_symref(ref: str, target: str) -> None:
        p = repo.gitdir / ref
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(f"ref: {target}\n", encoding="utf-8")

    def _remote_names() -> list[str]:
        seen: list[str] = []
        for key, _v in gitconfig.list_all(repo):
            if key.startswith("remote.") and key.endswith(".url"):
                nm = key[len("remote."):-len(".url")]
                if nm not in seen:
                    seen.append(nm)
        return seen

    def _cfg(name: str, sub: str):
        try:
            return gitconfig.get(repo, f"remote.{name}.{sub}")
        except Exception:
            return None

    if action in (None, "show") and not rest:
        for name in _remote_names():
            if verbose:
                url = _cfg(name, "url") or ""
                pushurl = _cfg(name, "pushurl") or url
                _print(f"{name}\t{url} (fetch)")
                _print(f"{name}\t{pushurl} (push)")
            else:
                _print(name)
        return 0

    if action == "add":
        # --mirror takes a value only in the attached form (--mirror=<v>); the
        # bare, space-separated form is a boolean (BOTH).  Normalise the bare
        # form to a private sentinel before argparse so it never swallows the
        # following <name> positional.
        rest = ["--mirror=__both__" if t == "--mirror" else t for t in rest]
        ap = argparse.ArgumentParser(prog="pygit remote add", add_help=False)
        ap.add_argument("-t", "--track", action="append", default=None)
        ap.add_argument("-m", "--master", default=None)
        ap.add_argument("-f", "--fetch", action="store_true")
        ap.add_argument("--tags", dest="tags", action="store_true")
        ap.add_argument("--no-tags", dest="no_tags", action="store_true")
        ap.add_argument("--mirror", default=None)
        ap.add_argument("name")
        ap.add_argument("url")
        a = ap.parse_args(rest)
        # parse_mirror_opt: validate the value to (push|fetch); a bare --mirror
        # means BOTH (with a deprecation warning); anything else is an error.
        if a.mirror not in (None, "__both__", "push", "fetch"):
            _err(f"error: unknown --mirror argument: {a.mirror}")
            return 129
        if a.name in _remote_names():
            _err(f"error: remote {a.name} already exists.")
            return 3
        gitconfig.write_value(cfg_path, "remote", a.name, "url", a.url)
        if a.mirror == "__both__":
            _err("warning: --mirror is dangerous and deprecated; please")
            _err("\t use --mirror=fetch or --mirror=push instead")
            gitconfig.write_value(cfg_path, "remote", a.name, "fetch", "+refs/*:refs/*")
            gitconfig.write_value(cfg_path, "remote", a.name, "mirror", "true")
        elif a.mirror == "push":
            gitconfig.write_value(cfg_path, "remote", a.name, "mirror", "true")
        elif a.mirror == "fetch":
            gitconfig.write_value(cfg_path, "remote", a.name, "fetch", "+refs/*:refs/*")
        else:
            tracks = a.track or ["*"]
            for i, br in enumerate(tracks):
                gitconfig.write_value(
                    cfg_path, "remote", a.name, "fetch",
                    f"+refs/heads/{br}:refs/remotes/{a.name}/{br}",
                    mode="set" if i == 0 else "add")
        if a.tags:
            gitconfig.write_value(cfg_path, "remote", a.name, "tagopt", "--tags")
        elif a.no_tags:
            gitconfig.write_value(cfg_path, "remote", a.name, "tagopt", "--no-tags")
        if a.master:
            _write_symref(f"refs/remotes/{a.name}/HEAD",
                          f"refs/remotes/{a.name}/{a.master}")
        return 0

    if action in ("remove", "rm"):
        name = rest[0] if rest else ""
        if name not in _remote_names():
            _err(f"error: No such remote: '{name}'")
            return 2
        gitconfig.remove_section(cfg_path, "remote", name)
        # Drop the remote-tracking refs and the branch.<x>.remote links.
        rdir = repo.gitdir / "refs" / "remotes" / name
        if rdir.exists():
            import shutil as _sh
            _sh.rmtree(rdir, ignore_errors=True)
        return 0

    if action == "rename":
        old, new = rest[0], rest[1]
        if old not in _remote_names():
            _err(f"error: No such remote: '{old}'")
            return 2
        # git refuses to overwrite an existing destination remote (rc 3).
        if new != old and new in _remote_names():
            _err(f"error: remote {new} already exists.")
            return 3
        for key, value in gitconfig.list_all(repo):
            if key.startswith(f"remote.{old}."):
                sub = key[len(f"remote.{old}."):]
                if sub == "fetch":
                    value = value.replace(f"refs/remotes/{old}/", f"refs/remotes/{new}/")
                gitconfig.write_value(cfg_path, "remote", new, sub, value,
                                      mode="add" if sub == "fetch" else "set")
        gitconfig.remove_section(cfg_path, "remote", old)
        # Rewrite every branch.<name>.remote that referenced the old remote
        # (builtin/remote.c migrate_file rewrites branch.<x>.{remote,pushRemote}).
        for key, value in gitconfig.list_all(repo):
            if key.startswith("branch.") and key.endswith((".remote", ".pushremote")) \
                    and value == old:
                br = key[len("branch."):key.rindex(".")]
                sub = key[key.rindex(".") + 1:]
                # preserve the original spelling git writes (remote/pushRemote).
                outkey = "pushRemote" if sub == "pushremote" else "remote"
                gitconfig.write_value(cfg_path, "branch", br, outkey, new)
        odir = repo.gitdir / "refs" / "remotes" / old
        ndir = repo.gitdir / "refs" / "remotes" / new
        if odir.exists():
            ndir.parent.mkdir(parents=True, exist_ok=True)
            odir.replace(ndir)
        return 0

    if action == "get-url":
        ap = argparse.ArgumentParser(prog="pygit remote get-url", add_help=False)
        ap.add_argument("--push", action="store_true")
        ap.add_argument("--all", action="store_true")
        ap.add_argument("name")
        a = ap.parse_args(rest)
        if a.name not in _remote_names():
            _err(f"error: No such remote '{a.name}'")
            return 2
        key = "pushurl" if a.push else "url"
        vals = [v for k, v in gitconfig.list_all(repo) if k == f"remote.{a.name}.{key}"]
        if not vals and a.push:
            vals = [v for k, v in gitconfig.list_all(repo) if k == f"remote.{a.name}.url"]
        if a.all:
            for v in vals:
                _print(v)
        elif vals:
            _print(vals[-1])
        return 0

    if action == "set-url":
        ap = argparse.ArgumentParser(prog="pygit remote set-url", add_help=False)
        ap.add_argument("--push", action="store_true")
        ap.add_argument("--add", action="store_true")
        ap.add_argument("--delete", action="store_true")
        ap.add_argument("name")
        ap.add_argument("newurl", nargs="?")
        ap.add_argument("oldurl", nargs="?")
        a = ap.parse_args(rest)
        if a.name not in _remote_names():
            _err(f"error: No such remote '{a.name}'")
            return 2
        key = "pushurl" if a.push else "url"
        if a.delete:
            # Remove only the URL(s) matching the given value: drop all, re-add rest.
            current = [v for k, v in gitconfig.list_all(repo) if k == f"remote.{a.name}.{key}"]
            keep = [v for v in current if v != a.newurl]
            gitconfig.unset_value(cfg_path, "remote", a.name, key, all_values=True)
            for i, v in enumerate(keep):
                gitconfig.write_value(cfg_path, "remote", a.name, key, v,
                                      mode="set" if i == 0 else "add")
        elif a.add:
            gitconfig.write_value(cfg_path, "remote", a.name, key, a.newurl, mode="add")
        else:
            gitconfig.write_value(cfg_path, "remote", a.name, key, a.newurl)
        return 0

    if action == "set-branches":
        ap = argparse.ArgumentParser(prog="pygit remote set-branches", add_help=False)
        ap.add_argument("--add", action="store_true")
        ap.add_argument("name")
        ap.add_argument("branches", nargs="+")
        a = ap.parse_args(rest)
        for i, br in enumerate(a.branches):
            mode = "add" if (a.add or i > 0) else "set"
            gitconfig.write_value(cfg_path, "remote", a.name, "fetch",
                                  f"+refs/heads/{br}:refs/remotes/{a.name}/{br}", mode=mode)
        return 0

    if action == "set-head":
        ap = argparse.ArgumentParser(prog="pygit remote set-head", add_help=False)
        ap.add_argument("-a", "--auto", action="store_true")
        ap.add_argument("-d", "--delete", action="store_true")
        ap.add_argument("name")
        ap.add_argument("branch", nargs="?")
        a = ap.parse_args(rest)
        head_ref = f"refs/remotes/{a.name}/HEAD"
        if a.delete:
            refs_mod.delete_ref(repo, head_ref)
            # Prune now-empty ref directories, like C Git.
            d = (repo.gitdir / head_ref).parent
            while d != repo.gitdir and d.is_dir() and not any(d.iterdir()):
                d.rmdir()
                d = d.parent
        elif a.auto:
            # --auto queries the remote's HEAD over the network; with no network
            # (unconfigured/unreachable remote) git dies trying to read it.
            return _remote_unreadable(a.name)
        elif a.branch:
            target = f"refs/remotes/{a.name}/{a.branch}"
            if refs_mod.read_ref(repo, target) is None:
                _err(f"error: Not a valid ref: {target}")
                return 1
            refs_mod.update_ref_symbolic(repo, head_ref, target)
        return 0

    # prune / update / show <name> need to read from the named remote; with no
    # network they die ("does not appear to be a git repository").
    if action in ("prune", "update", "show"):
        # 'show'/'update' take options before the name; pick the last bare arg.
        names = [t for t in rest if not t.startswith("-")]
        if action == "show":
            ap = argparse.ArgumentParser(prog="pygit remote show", add_help=False)
            ap.add_argument("-n", dest="no_query", action="store_true")
            ap.add_argument("name", nargs="?")
            sa = ap.parse_args(rest)
            if sa.name is None:
                return 0
            if sa.no_query:
                # -n avoids the network: report the configured URLs only.
                if sa.name not in _remote_names():
                    return _remote_unreadable(sa.name)
                url = _cfg(sa.name, "url") or ""
                pushurl = _cfg(sa.name, "pushurl") or url
                _print(f"* remote {sa.name}")
                _print(f"  Fetch URL: {url}")
                _print(f"  Push  URL: {pushurl}")
                _print("  HEAD branch: (not queried)")
                _print("  Local ref configured for 'git push' (status not queried):")
                _print("    (matching) pushes to (matching)")
                return 0
            return _remote_unreadable(sa.name)
        # prune / update reach the remote.
        if names:
            return _remote_unreadable(names[0])
        return 0
    return 0


def cmd_ls_remote(argv: list[str]) -> int:
    from ._transport_usage import LS_REMOTE_USAGE

    def _ls_usage_err(msg: str) -> int:
        # parse-options writes the diagnostic to stderr but the usage block to
        # stdout (observed against git 2.54.0).
        sys.stderr.write(f"error: {msg}\n")
        sys.stdout.write(LS_REMOTE_USAGE)
        return 129

    # The boolean --tags/--branches/--heads reject an attached value, exactly
    # like C Git's parse-options ("option `<name>' takes no value").
    for tok in argv:
        for nm in ("branches", "tags", "heads"):
            if tok.startswith(f"--{nm}="):
                _err(f"error: option `{nm}' takes no value")
                return 129
    # Resolve unique-prefix abbreviations and detect ambiguity, exactly like
    # parse-options.  Hidden long options (exec, heads) participate too.
    _ls_long = ("quiet", "upload-pack", "exec", "tags", "branches", "heads",
                "refs", "get-url", "sort", "exit-code", "symref",
                "server-option")
    norm: list[str] = []
    saw_dd = False
    for tok in argv:
        if saw_dd or not tok.startswith("--") or tok == "--":
            if tok == "--":
                saw_dd = True
            norm.append(tok)
            continue
        name, eq, val = tok[2:].partition("=")
        bare = name[3:] if name.startswith("no-") else name
        neg = name.startswith("no-")
        if bare in _ls_long:
            norm.append(tok)
            continue
        matches = [c for c in _ls_long if c.startswith(bare)]
        if len(matches) == 1:
            full = ("no-" if neg else "") + matches[0]
            norm.append(f"--{full}" + (eq + val if eq else ""))
        elif len(matches) > 1:
            joined = " or ".join("--" + m for m in matches)
            return _ls_usage_err(f"ambiguous option: {bare} (could be {joined})")
        else:
            norm.append(tok)
    argv = norm

    ap = argparse.ArgumentParser(prog="pygit ls-remote", add_help=False)
    ap.add_argument("-t", "--tags", action="store_true")
    ap.add_argument("-b", "--branches", "--heads", "-h", dest="branches", action="store_true")
    ap.add_argument("--refs", action="store_true")
    ap.add_argument("--symref", action="store_true")
    ap.add_argument("--get-url", dest="get_url", action="store_true")
    ap.add_argument("-q", "--quiet", action="store_true")
    ap.add_argument("--exit-code", dest="exit_code", action="store_true")
    ap.add_argument("--sort", default=None)
    # --exec is a hidden alias of --upload-pack (builtin/ls-remote.c).
    ap.add_argument("--upload-pack", "--exec", dest="upload_pack", default=None)
    ap.add_argument("-o", "--server-option", dest="server_option", action="append", default=None)
    ap.add_argument("url", nargs="?", default=None)
    ap.add_argument("patterns", nargs="*")
    args = ap.parse_args(argv)
    url = args.url
    if url is None:
        # No <repository> given: git uses the current branch's remote (or
        # origin), erroring when none is configured.
        from . import gitconfig
        try:
            r = _repo()
            url = gitconfig.get(r, "remote.origin.url")
        except RepositoryError:
            url = None
        if not url:
            _err("fatal: No remote configured to list refs from.")
            return 128
    # Resolve a configured remote name to its URL (remote_get), so `ls-remote
    # origin` works and only genuinely unknown repositories error out.
    if not url.startswith(("http://", "https://", "git://", "ssh://", "file://")) \
            and "://" not in url and not url.startswith("git@"):
        from . import gitconfig
        try:
            r = _repo()
            resolved = gitconfig.get(r, f"remote.{url}.url")
            if resolved:
                url = resolved
        except RepositoryError:
            pass
    # remote_get() applies url.<base>.insteadOf rewriting; --get-url documents
    # exactly that ("take url.<base>.insteadOf into account").
    from . import gitconfig as _gc
    try:
        url = _gc.apply_insteadof(_repo(), url)
    except RepositoryError:
        url = _gc.apply_insteadof(None, url)
    if args.get_url:
        _print(url)
        return 0
    if url == "":
        _err("fatal: bad repository ''")
        return 128
    src = url[7:] if url.startswith("file://") else url

    import fnmatch as _fn

    def _pat_match(name: str) -> bool:
        if not args.patterns:
            return True
        for p in args.patterns:
            if name == p or _fn.fnmatch(name, p) or name.endswith("/" + p) \
                    or _fn.fnmatch(name, "*/" + p):
                return True
        return False

    def _sort_key(disp: str):
        key = args.sort.lstrip("-") if args.sort else "refname"
        if key in ("version:refname", "v:refname"):
            return _version_sort_key(disp)
        return disp

    # A local repository path is read directly: HEAD, then refs in sorted order,
    # with annotated tags followed by their peeled ``^{}`` line — like git.
    if not url.startswith(("http://", "https://", "git://", "ssh://")) and Path(src).exists():
        # With an explicit --upload-pack/--exec, git spawns that program over the
        # local connection; a custom binary that doesn't speak the protocol makes
        # the connection fail ("Could not read from remote repository").
        if args.upload_pack:
            _err("fatal: Could not read from remote repository.")
            _err("")
            _err("Please make sure you have the correct access rights")
            _err("and the repository exists.")
            return 128
        repo = Repository.discover(src)
        head_symref, head_sha = refs_mod.read_head(repo)
        # Each output line is (display-name, oid). HEAD shows only when no
        # namespace filter and --refs is off.
        lines: list[tuple[str, str]] = []
        if head_sha and not (args.tags or args.branches) and not args.refs:
            lines.append(("HEAD", head_sha))
        for name, sha in sorted(_enumerate_refs(repo)):
            if (args.tags or args.branches) and not (
                    (args.branches and name.startswith("refs/heads/"))
                    or (args.tags and name.startswith("refs/tags/"))):
                continue
            lines.append((name, sha))
            if name.startswith("refs/tags/") and not args.refs:
                try:
                    if objs.read_object(repo, sha)[0] == "tag":
                        peeled = refs_mod.rev_parse(repo, name + "^{commit}")
                        if peeled:
                            lines.append((name + "^{}", peeled))
                except KeyError:
                    pass
        lines = [(n, s) for n, s in lines if _pat_match(n)]
        if args.sort:
            reverse = args.sort.startswith("-")
            lines.sort(key=lambda t: _sort_key(t[0]), reverse=reverse)
        emitted = 0
        for name, sha in lines:
            # --symref prefixes HEAD's oid line with its symbolic target.
            if args.symref and name == "HEAD" and head_symref:
                _print(f"ref: {head_symref}\tHEAD")
            _print(f"{sha}\t{name}")
            emitted += 1
        if args.exit_code and emitted == 0:
            return 2
        return 0
    # Reaching here means the argument was not an existing local repository.
    # Only genuine network transports proceed; anything else is reported as a
    # bad remote, mirroring git's "does not appear to be a git repository".
    if not url.startswith(("http://", "https://", "git://", "ssh://")) \
            and "://" not in url and not url.startswith("git@"):
        _err(f"fatal: '{url}' does not appear to be a git repository")
        _err("fatal: Could not read from remote repository.")
        _err("")
        _err("Please make sure you have the correct access rights")
        _err("and the repository exists.")
        return 128
    from . import protocol
    refs = protocol.discover_refs(url)
    emitted = 0
    for name, sha in refs.items():
        if _pat_match(name):
            _print(f"{sha}\t{name}")
            emitted += 1
    if args.exit_code and emitted == 0:
        return 2
    return 0


def cmd_clone(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit clone", add_help=False)
    # builtin/clone.c option table.  Most flags are accepted for parity; the
    # local-copy clone honours --bare/--mirror, -q/-v, -b/--branch and
    # -n/--no-checkout, which cover the observable behaviour.
    ap.add_argument("--object-format", choices=["sha1", "sha256"], default=None)
    ap.add_argument("--ref-format", default=None)
    ap.add_argument("-q", "--quiet", action="store_true")
    ap.add_argument("-v", "--verbose", action="store_true")
    ap.add_argument("--progress", action="store_true")
    ap.add_argument("--no-progress", dest="no_progress", action="store_true")
    ap.add_argument("--bare", action="store_true")
    ap.add_argument("--mirror", action="store_true")
    ap.add_argument("-n", "--no-checkout", dest="no_checkout", action="store_true")
    ap.add_argument("--checkout", dest="checkout", action="store_true")
    ap.add_argument("-b", "--branch", default=None)
    ap.add_argument("-o", "--origin", default="origin")
    ap.add_argument("-l", "--local", action="store_true")
    ap.add_argument("--no-hardlinks", action="store_true")
    ap.add_argument("-s", "--shared", action="store_true")
    ap.add_argument("--single-branch", action="store_true")
    ap.add_argument("--no-single-branch", dest="no_single_branch", action="store_true")
    ap.add_argument("--depth", default=None)
    ap.add_argument("--shallow-since", default=None)
    ap.add_argument("--shallow-exclude", action="append", default=None)
    ap.add_argument("--reject-shallow", action="store_true")
    ap.add_argument("--no-reject-shallow", dest="no_reject_shallow", action="store_true")
    ap.add_argument("-c", "--config", action="append", default=None)
    ap.add_argument("-j", "--jobs", default=None)
    ap.add_argument("--template", default=None)
    ap.add_argument("--reference", action="append", default=None)
    ap.add_argument("--reference-if-able", action="append", default=None)
    ap.add_argument("--dissociate", action="store_true")
    ap.add_argument("-u", "--upload-pack", dest="upload_pack", default=None)
    ap.add_argument("--tags", action="store_true")
    ap.add_argument("--no-tags", dest="no_tags", action="store_true")
    ap.add_argument("--separate-git-dir", default=None)
    ap.add_argument("--server-option", action="append", default=None)
    ap.add_argument("-4", "--ipv4", action="store_true")
    ap.add_argument("-6", "--ipv6", action="store_true")
    ap.add_argument("--filter", default=None)
    ap.add_argument("--recurse-submodules", "--recursive", nargs="?", const="", default=None)
    ap.add_argument("--sparse", action="store_true")
    ap.add_argument("--bundle-uri", default=None)
    ap.add_argument("--revision", default=None)
    ap.add_argument("url")
    ap.add_argument("directory", nargs="?")
    args = ap.parse_args(argv)

    bare = args.bare or args.mirror
    # guess_dir_name(): strip trailing slashes and ".git"; bare clones keep
    # ".git" (so the dir is named "<name>.git").
    if args.directory:
        target = args.directory
    else:
        name = args.url.rstrip("/").split("/")[-1]
        name = name.removesuffix(".git") if not bare else name
        target = name if not bare else (name if name.endswith(".git") else name + ".git")

    def _msg(s: str) -> None:
        if not args.quiet:
            sys.stderr.write(s)

    label = "bare repository " if bare else ""
    _msg(f"Cloning into {label}'{target}'...\n")

    src_path = args.url[7:] if args.url.startswith("file://") else args.url
    if not args.url.startswith(("http://", "https://", "git://")) and Path(src_path).exists():
        from . import translate
        src = Repository.discover(src_path)
        obj_fmt = args.object_format or src.object_format()
        # Determine the set of refs the source advertises (empty => warning).
        from .translate import iter_refs as _iter_refs
        adv = [r for r in _iter_refs(src) if refs_mod.read_ref(src, r)]
        # -b/--branch: the named branch must exist on the source.
        if args.branch is not None:
            want = f"refs/heads/{args.branch}"
            if want not in adv and f"refs/tags/{args.branch}" not in adv:
                sys.stderr.write(
                    f"fatal: Remote branch {args.branch} not found in upstream {args.origin}\n")
                return 128
        dst = Repository.init(target, bare=bare, object_format=obj_fmt)
        do_checkout = (not bare) and (not args.no_checkout)
        translate.translate_repository(src, dst, checkout=do_checkout)
        if not adv:
            sys.stderr.write("warning: You appear to have cloned an empty repository.\n")
    else:
        from . import protocol
        protocol.clone(args.url, target, object_format=args.object_format)

    _msg("done.\n")
    return 0


_FSCK_USAGE = (
    "usage: git fsck [--tags] [--root] [--unreachable] [--cache] [--no-reflogs]\n"
    "                [--[no-]full] [--strict] [--verbose] [--lost-found]\n"
    "                [--[no-]dangling] [--[no-]progress] [--connectivity-only]\n"
    "                [--[no-]name-objects] [--[no-]references] [<object>...]\n"
    "\n"
    "    -v, --[no-]verbose    be verbose\n"
    "    --[no-]unreachable    show unreachable objects\n"
    "    --[no-]dangling       show dangling objects\n"
    "    --[no-]tags           report tags\n"
    "    --[no-]root           report root nodes\n"
    "    --[no-]cache          make index objects head nodes\n"
    "    --[no-]reflogs        make reflogs head nodes (default)\n"
    "    --[no-]full           also consider packs and alternate objects\n"
    "    --[no-]connectivity-only\n"
    "                          check only connectivity\n"
    "    --[no-]strict         enable more strict checking\n"
    "    --[no-]lost-found     write dangling objects in .git/lost-found\n"
    "    --[no-]progress       show progress\n"
    "    --[no-]name-objects   show verbose names for reachable objects\n"
    "    --[no-]references     check reference database consistency\n"
    "\n"
)


def _fsck_object_referents(obj_type: str, data: bytes, repo: Repository):
    """Yield the object ids that ``obj`` (already read) points to.

    Mirrors fsck_walk's referent enumeration: commit -> tree + parents,
    tree -> entry oids, tag -> tagged object. Blobs have no referents."""
    if obj_type == "commit":
        c = objs.parse_commit(data)
        yield c.tree
        for p in c.parents:
            yield p
    elif obj_type == "tree":
        for e in objs.parse_tree(data, repo.hash_len):
            yield e.sha
    elif obj_type == "tag":
        for line in data.decode("utf-8", errors="replace").splitlines():
            if line.startswith("object "):
                yield line[len("object "):].strip()
                break


def cmd_fsck(argv: list[str]) -> int:
    # Port of builtin/fsck.c option handling + reachability reporting.
    show_unreachable = False
    show_dangling = True
    show_root = False
    objects_args: list[str] = []
    i = 0
    saw_dashdash = False
    while i < len(argv):
        a = argv[i]
        if saw_dashdash:
            objects_args.append(a)
            i += 1
            continue
        if a == "--":
            saw_dashdash = True
        elif a == "-h":
            sys.stdout.write(_FSCK_USAGE)
            return 129
        elif a in ("-v", "--verbose", "--no-verbose"):
            pass
        elif a == "--unreachable":
            show_unreachable = True
        elif a == "--no-unreachable":
            show_unreachable = False
        elif a == "--dangling":
            show_dangling = True
        elif a == "--no-dangling":
            show_dangling = False
        elif a == "--root":
            show_root = True
        elif a == "--no-root":
            show_root = False
        elif a in ("--tags", "--no-tags", "--cache", "--no-cache",
                   "--reflogs", "--no-reflogs", "--full", "--no-full",
                   "--connectivity-only", "--no-connectivity-only",
                   "--strict", "--no-strict", "--lost-found", "--no-lost-found",
                   "--progress", "--no-progress",
                   "--name-objects", "--no-name-objects",
                   "--references", "--no-references"):
            pass
        elif a.startswith("--"):
            _err(f"error: unknown option `{a[2:]}'")
            sys.stderr.write(_FSCK_USAGE)
            return 129
        elif a.startswith("-") and a != "-":
            _err(f"error: unknown switch `{a[1]}'")
            sys.stderr.write(_FSCK_USAGE)
            return 129
        else:
            objects_args.append(a)
        i += 1

    repo = _repo()
    import zlib
    from . import pack as _p

    errors_found = 0

    # Enumerate the entire object store in fsck's iteration order: loose objects
    # first (sorted by sha, as for_each_loose_file_in_objdir yields), then each
    # pack in idx (sha) order. Record type and content for every object.
    obj_types: dict[str, str] = {}
    obj_order: list[str] = []  # check-pass order (loose sorted, then packs)
    obj_root = repo.gitdir / "objects"
    if obj_root.is_dir():
        loose_shas = []
        for d in sorted(obj_root.iterdir(), key=lambda p: p.name):
            if not d.is_dir() or len(d.name) != 2 or any(
                c not in "0123456789abcdef" for c in d.name
            ):
                continue
            for f in sorted(d.iterdir(), key=lambda p: p.name):
                loose_shas.append(d.name + f.name)
        for sha in loose_shas:
            try:
                t, _data = objs.read_object(repo, sha)
            except Exception as e:
                _err(f"error: {sha}: {e}")
                errors_found = 1
                continue
            obj_types[sha] = t
            obj_order.append(sha)
    for pk in _p._iter_packs(repo):
        for sha in pk.shas:
            if sha in obj_types:
                continue
            try:
                t, _d = pk.get(sha)
            except Exception:
                continue
            obj_types[sha] = t
            obj_order.append(sha)

    # Compute reachable set and the "USED" set (objects referenced by ANY other
    # object in the store, which fsck uses to distinguish dangling tips).
    # fsck treats reflog entries as head nodes by default (--reflogs is on), so
    # an object kept alive only by a reflog (e.g. after reset/amend) is NOT
    # dangling. Collect every old/new oid recorded in .git/logs as extra roots.
    reflog_roots: list[str] = []
    logs_root = repo.gitdir / "logs"
    if logs_root.is_dir():
        for logf in logs_root.rglob("*"):
            if not logf.is_file():
                continue
            try:
                text = logf.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            for line in text.splitlines():
                parts = line.split(" ", 2)
                if len(parts) >= 2:
                    for oid in (parts[0], parts[1]):
                        if len(oid) == repo.hex_len and oid != "0" * repo.hex_len \
                                and all(c in "0123456789abcdef" for c in oid):
                            reflog_roots.append(oid)
    reachable = _reachable(repo, extra_roots=reflog_roots or None)
    used: set[str] = set()
    for sha in obj_order:
        t = obj_types[sha]
        if t == "blob":
            continue
        try:
            _t, data = objs.read_object(repo, sha)
        except KeyError:
            continue
        for ref in _fsck_object_referents(t, data, repo):
            used.add(ref)

    # Check pass: per-object output (root commits) in check order.
    if show_root:
        for sha in obj_order:
            if obj_types[sha] != "commit":
                continue
            try:
                _t, data = objs.read_object(repo, sha)
            except KeyError:
                continue
            c = objs.parse_commit(data)
            if not c.parents:
                _print(f"root {sha}")

    # Connectivity pass: unreachable / dangling objects in sha-sorted order.
    if show_unreachable or show_dangling:
        for sha in sorted(obj_types):
            if sha in reachable:
                continue
            t = obj_types[sha]
            if show_unreachable:
                _print(f"unreachable {t} {sha}")
            elif show_dangling and sha not in used:
                _print(f"dangling {t} {sha}")

    return 0 if errors_found == 0 else 1


_GC_USAGE = (
    "usage: git gc [<options>]\n"
    "\n"
    "    -q, --[no-]quiet      suppress progress reporting\n"
    "    --[no-]prune[=<date>] prune unreferenced objects\n"
    "    --[no-]cruft          pack unreferenced objects separately\n"
    "    --max-cruft-size <n>  with --cruft, limit the size of new cruft packs\n"
    "    --[no-]aggressive     be more thorough (increased runtime)\n"
    "    --[no-]auto           enable auto-gc mode\n"
    "    --[no-]detach         perform garbage collection in the background\n"
    "    --[no-]force          force running gc even if there may be another gc running\n"
    "    --[no-]keep-largest-pack\n"
    "                          repack all other packs except the largest pack\n"
    "    --[no-]expire-to <dir>\n"
    "                          pack prefix to store a pack containing pruned objects\n"
    "\n"
)


def _parse_magnitude(value: str) -> Optional[int]:
    """Port of git_parse_ulong (parse-options OPT_MAGNITUDE/OPT_UNSIGNED).

    Accepts a non-negative integer with an optional k/m/g (case-insensitive)
    suffix. Returns the parsed value, or None when the string is malformed.
    """
    s = value.strip()
    if not s:
        return None
    mult = 1
    if s[-1:] in ("k", "K"):
        mult, s = 1024, s[:-1]
    elif s[-1:] in ("m", "M"):
        mult, s = 1024 * 1024, s[:-1]
    elif s[-1:] in ("g", "G"):
        mult, s = 1024 * 1024 * 1024, s[:-1]
    if not s or not s.isdigit():
        return None
    return int(s) * mult


def _parse_integer(value: str) -> Optional[int]:
    """Port of git_parse_long (parse-options OPT_INTEGER): a (possibly signed)
    integer with an optional k/m/g suffix. Returns None when malformed."""
    s = value.strip()
    if not s:
        return None
    mult = 1
    if s[-1:] in ("k", "K"):
        mult, s = 1024, s[:-1]
    elif s[-1:] in ("m", "M"):
        mult, s = 1024 * 1024, s[:-1]
    elif s[-1:] in ("g", "G"):
        mult, s = 1024 * 1024 * 1024, s[:-1]
    body = s[1:] if s[:1] in ("+", "-") else s
    if not body or not body.isdigit():
        return None
    return int(s) * mult


def cmd_gc(argv: list[str]) -> int:
    # Port of builtin/gc.c cmd_gc's option parsing. The actual housekeeping is a
    # no-op for pygit, but git validates every option before doing any work, so
    # we must reject unknown options and bad option values byte-exactly.
    # parse_options handles -h when reached (after valid preceding options),
    # printing usage to STDOUT (rc 129).
    prune_expire = None  # default config value; only validated when set
    i = 0
    extra: list[str] = []
    saw_dashdash = False
    while i < len(argv):
        a = argv[i]
        if saw_dashdash:
            extra.append(a)
            i += 1
            continue
        if a == "--":
            saw_dashdash = True
        elif a == "-h":
            sys.stdout.write(_GC_USAGE)
            return 129
        elif a in ("-q", "--quiet", "--no-quiet",
                   "--cruft", "--no-cruft",
                   "--aggressive", "--no-aggressive",
                   "--auto", "--no-auto",
                   "--detach", "--no-detach",
                   "--force", "--no-force",
                   "--keep-largest-pack", "--no-keep-largest-pack"):
            pass
        elif a == "--prune":
            prune_expire = "now"  # OPT_OPTARG default when bare
        elif a == "--no-prune":
            prune_expire = None
        elif a.startswith("--prune="):
            prune_expire = a[len("--prune="):]
        elif a == "--expire-to" or a.startswith("--expire-to="):
            if a == "--expire-to":
                i += 1
                if i >= len(argv):
                    _err("error: option `expire-to' requires a value")
                    sys.stderr.write(_GC_USAGE)
                    return 129
        elif a == "--max-cruft-size" or a.startswith("--max-cruft-size="):
            if a == "--max-cruft-size":
                i += 1
                if i >= len(argv):
                    _err("error: option `max-cruft-size' requires a value")
                    sys.stderr.write(_GC_USAGE)
                    return 129
                val = argv[i]
            else:
                val = a[len("--max-cruft-size="):]
            if _parse_magnitude(val) is None:
                _err("error: option `max-cruft-size' expects a non-negative "
                     "integer value with an optional k/m/g suffix")
                return 129
        elif a.startswith("--"):
            _err(f"error: unknown option `{a[2:]}'")
            sys.stderr.write(_GC_USAGE)
            return 129
        elif a.startswith("-") and a != "-":
            _err(f"error: unknown switch `{a[1]}'")
            sys.stderr.write(_GC_USAGE)
            return 129
        else:
            extra.append(a)
        i += 1

    # parse_options(..., 0): any leftover positional triggers usage (rc 129).
    if extra:
        sys.stderr.write(_GC_USAGE)
        return 129

    # git: `if (cfg.prune_expire && parse_expiry_date(...)) die(...)`.
    if prune_expire is not None:
        try:
            _parse_expiry_date(prune_expire)
        except ValueError:
            _err(f"fatal: failed to parse prune expiry value {prune_expire}")
            return 128

    # Housekeeping itself is a no-op; a clean `git gc` prints nothing on success.
    return 0


def cmd_help(argv: list[str]) -> int:
    _print("Available commands:")
    for name in sorted(_COMMANDS):
        _print(f"  {name}")
    return 0


# ---------------------------------------------------------------------------
# Opt-in `git` drop-in installer.
#
# We do NOT declare a `git` console-script in pyproject.toml because that
# would silently shadow the system's real git binary on every install. Users
# opt in by running `pygit install-git-shim`, which copies the existing
# `pygit` launcher to a sibling `git` file (or .exe on Windows). Reversed by
# `pygit uninstall-git-shim`.


def _scripts_dir() -> Path:
    """Where pip placed pygit's console-script launcher."""
    import sysconfig
    return Path(sysconfig.get_path("scripts"))


def _shim_paths() -> tuple[Path, Path]:
    """Return (existing pygit launcher, target git launcher path)."""
    d = _scripts_dir()
    if os.name == "nt":
        return d / "pygit.exe", d / "git.exe"
    return d / "pygit", d / "git"


def cmd_install_git_shim(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(
        prog="pygit install-git-shim",
        description="Install a `git` console-script alongside `pygit` so "
                    "the command `git` invokes pythongit. By default this "
                    "refuses to overwrite an existing `git` on PATH; pass "
                    "--force to install anyway.",
    )
    ap.add_argument("--force", action="store_true",
                    help="overwrite an existing git file in the scripts dir")
    ap.add_argument("--dir", default=None,
                    help="install into this directory instead of pygit's scripts dir")
    args = ap.parse_args(argv)
    import shutil as _sh
    if args.dir:
        d = Path(args.dir)
        src = (d / "pygit.exe") if os.name == "nt" else (d / "pygit")
        dst = (d / "git.exe") if os.name == "nt" else (d / "git")
    else:
        src, dst = _shim_paths()
    if not src.exists():
        _err(f"pygit launcher not found at {src}. Is pythongit installed?")
        return 1
    if dst.exists() and not args.force:
        _err(f"refusing to overwrite existing {dst} (use --force).")
        return 1
    # Resolve PATH conflict: warn if a different `git` is earlier on PATH.
    other = _sh.which("git")
    if other and Path(other).resolve() != dst.resolve():
        _err(f"warning: a different `git` is already first on PATH: {other}")
        _err(f"         after this install, `git` will still resolve to that "
             f"unless you put {dst.parent} earlier on PATH.")
    _sh.copy2(src, dst)
    # On Unix make sure it's executable
    if os.name != "nt":
        st = dst.stat()
        os.chmod(dst, st.st_mode | 0o111)
    _print(f"Installed git shim at {dst}")
    return 0


def cmd_uninstall_git_shim(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit uninstall-git-shim")
    ap.add_argument("--dir", default=None)
    args = ap.parse_args(argv)
    if args.dir:
        d = Path(args.dir)
        dst = (d / "git.exe") if os.name == "nt" else (d / "git")
    else:
        _, dst = _shim_paths()
    if not dst.exists():
        _print(f"no git shim found at {dst}")
        return 0
    # Sanity check: only remove a file that looks like our shim. We compare
    # against pygit's launcher; if the file at `dst` doesn't share size and
    # the same first bytes, refuse.
    src = (Path(args.dir) / ("pygit.exe" if os.name == "nt" else "pygit")) if args.dir else _shim_paths()[0]
    if src.exists():
        if dst.stat().st_size != src.stat().st_size or dst.read_bytes()[:64] != src.read_bytes()[:64]:
            _err(f"refusing to remove {dst}: it does not look like a pythongit shim. "
                 f"Delete it manually if you're sure.")
            return 1
    dst.unlink()
    _print(f"Removed git shim at {dst}")
    return 0


def cmd_version(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit version")
    ap.add_argument("--build-options", action="store_true")
    args = ap.parse_args(argv)
    from . import __version__
    _print(f"pygit version {__version__}")
    if args.build_options:
        _print("cpu: pure-python")
        _print("sizeof-long: 8")
    return 0


