def _expand_pick_revs(repo: Repository, specs: list[str]) -> "Optional[list[str]]":
    """Expand cherry-pick/revert positional args into an ordered list of commit
    shas.  Each spec is a single rev or an ``A..B`` range (the commits reachable
    from B but not A, applied oldest-first).  Returns None after emitting the
    'fatal: bad revision' for an unresolvable token."""
    out: list[str] = []
    for spec in specs:
        if ".." in spec and "..." not in spec and not spec.startswith("."):
            lo, _, hi = spec.partition("..")
            lo = lo or "HEAD"
            hi = hi or "HEAD"
            lo_sha = refs_mod.rev_parse(repo, lo)
            hi_sha = refs_mod.rev_parse(repo, hi)
            if not hi_sha:
                _err(f"fatal: bad revision '{spec}'")
                return None
            if not lo_sha:
                _err(f"fatal: bad revision '{spec}'")
                return None
            out.extend(_revs_in_range(repo, lo_sha, hi_sha))
        else:
            sha = refs_mod.rev_parse(repo, spec)
            if not sha:
                _err(f"fatal: bad revision '{spec}'")
                return None
            out.append(sha)
    return out


def _revs_in_range(repo: Repository, exclude_sha: str, include_sha: str) -> list[str]:
    """Commits reachable from *include_sha* but not from *exclude_sha*, in
    cherry-pick order (oldest first), following first parents along the chain
    and stopping at any ancestor of *exclude_sha*."""
    from . import merge as _m
    excluded = set()
    stack = [exclude_sha]
    while stack:
        cur = stack.pop()
        if cur in excluded:
            continue
        excluded.add(cur)
        try:
            c = objs.parse_commit(objs.read_object(repo, cur)[1])
        except KeyError:
            continue
        stack.extend(c.parents)
    chain: list[str] = []
    cur = include_sha
    seen = set()
    while cur and cur not in excluded and cur not in seen:
        seen.add(cur)
        chain.append(cur)
        c = objs.parse_commit(objs.read_object(repo, cur)[1])
        if not c.parents:
            break
        cur = c.parents[0]
    chain.reverse()
    return chain


def _parse_sequencer_opts(argv: list[str], usage: str, *, is_revert: bool):
    """Manual parse-options port shared by cherry-pick and revert.  Returns a
    SimpleNamespace of options plus a list of positional revs, or an int rc when
    it has already printed an error/usage block (129 on a parse error)."""
    import types
    o = types.SimpleNamespace(
        no_commit=False, edit=None, no_edit=False, signoff=False, mainline=None,
        strategy=None, strategy_option=[], cleanup=None, gpg_sign=None,
        no_gpg_sign=False, rerere_autoupdate=None, x=False, ff=False,
        allow_empty=False, allow_empty_message=False, keep_redundant=False,
        empty=None, reference=False,
        cmdmode=None,  # one of continue/skip/abort/quit
        revs=[])
    i, n = 0, len(argv)
    dd = False
    while i < n:
        a = argv[i]
        if dd:
            o.revs.append(a); i += 1; continue
        if a == "--":
            dd = True; i += 1; continue
        if a in ("--continue", "--skip", "--abort", "--quit"):
            o.cmdmode = a[2:]
        elif a in ("-n", "--no-commit"):
            o.no_commit = True
        elif a == "--commit":
            o.no_commit = False
        elif a in ("-e", "--edit"):
            o.edit = True
        elif a == "--no-edit":
            o.no_edit = True; o.edit = False
        elif a in ("-s", "--signoff"):
            o.signoff = True
        elif a == "--no-signoff":
            o.signoff = False
        elif a == "-x":
            o.x = True
        elif a in ("--ff",):
            o.ff = True
        elif a == "--no-ff":
            o.ff = False
        elif a == "--allow-empty":
            o.allow_empty = True
        elif a == "--no-allow-empty":
            o.allow_empty = False
        elif a == "--allow-empty-message":
            o.allow_empty_message = True
        elif a == "--no-allow-empty-message":
            o.allow_empty_message = False
        elif a in ("--keep-redundant-commits",):
            o.keep_redundant = True
        elif a == "-r":
            pass  # historical no-op
        elif a in ("--rerere-autoupdate",):
            o.rerere_autoupdate = True
        elif a == "--no-rerere-autoupdate":
            o.rerere_autoupdate = False
        elif a == "--reference" and is_revert:
            o.reference = True
        elif a == "--no-reference" and is_revert:
            o.reference = False
        elif a in ("-m", "--mainline"):
            i += 1
            if i >= n:
                sys.stderr.write(f"error: switch `m' requires a value\n")
                sys.stderr.write(usage)
                return 129
            o.mainline = argv[i]
        elif a.startswith("-m") and len(a) > 2:
            o.mainline = a[2:]
        elif a.startswith("--mainline="):
            o.mainline = a.split("=", 1)[1]
        elif a in ("-s", "--strategy"):
            i += 1
            if i >= n:
                sys.stderr.write(usage); return 129
            o.strategy = argv[i]
        elif a == "--strategy" or a.startswith("--strategy="):
            if a.startswith("--strategy="):
                o.strategy = a.split("=", 1)[1]
            else:
                i += 1
                if i >= n:
                    sys.stderr.write(usage); return 129
                o.strategy = argv[i]
        elif a in ("-X", "--strategy-option"):
            i += 1
            if i >= n:
                sys.stderr.write(usage); return 129
            o.strategy_option.append(argv[i])
        elif a.startswith("-X"):
            o.strategy_option.append(a[2:])
        elif a.startswith("--strategy-option="):
            o.strategy_option.append(a.split("=", 1)[1])
        elif a == "--cleanup":
            i += 1
            if i >= n:
                sys.stderr.write(usage); return 129
            o.cleanup = argv[i]
        elif a.startswith("--cleanup="):
            o.cleanup = a.split("=", 1)[1]
        elif a == "--empty":
            i += 1
            if i >= n:
                sys.stderr.write(usage); return 129
            o.empty = argv[i]
        elif a.startswith("--empty="):
            o.empty = a.split("=", 1)[1]
        elif a in ("-S", "--gpg-sign"):
            o.gpg_sign = ""  # PARSE_OPT_OPTARG: bare -S means default key
        elif a.startswith("-S"):
            o.gpg_sign = a[2:]
        elif a.startswith("--gpg-sign="):
            o.gpg_sign = a.split("=", 1)[1]
        elif a == "--no-gpg-sign":
            o.no_gpg_sign = True; o.gpg_sign = None
        elif a.startswith("-") and a != "-":
            if not a.startswith("--") and len(a) > 2:
                sys.stderr.write(f"error: unknown switch `{a[1]}'\n")
            elif a.startswith("--"):
                sys.stderr.write(f"error: unknown option `{a[2:]}'\n")
            else:
                sys.stderr.write(f"error: unknown switch `{a[1:]}'\n")
            sys.stderr.write(usage)
            return 129
        else:
            o.revs.append(a)
        i += 1
    return o


def _resolve_sequencer_sign(repo: Repository, o) -> "Optional[str]":
    """Resolve the signing key for a cherry-pick/revert commit from -S /
    commit.gpgsign, honoring --no-gpg-sign.  Returns None when unsigned."""
    if o.no_gpg_sign:
        return None
    key = o.gpg_sign
    if key is None:
        from . import gitconfig as _gc
        cfg = (_gc.get(repo, "commit.gpgsign") or "").lower()
        if cfg in ("true", "1", "yes", "on"):
            key = ""
        else:
            return None
    if key:
        return key
    from . import gpgsign as _gpg
    return _gpg.get_signing_key(repo, _ident_no_date(objs.build_signature(repo, "committer")))


def cmd_cherry_pick(argv: list[str]) -> int:
    repo = _repo()
    from . import sequencer
    o = _parse_sequencer_opts(argv, _CHERRY_PICK_USAGE, is_revert=False)
    if isinstance(o, int):
        return o
    # Sequence cmdmodes: with no sequence in progress, all four behave the same.
    if o.cmdmode is not None:
        return _sequencer_cmdmode(repo, o.cmdmode, "cherry-pick")
    if not o.revs:
        sys.stderr.write(_CHERRY_PICK_USAGE)
        return 129
    if o.cleanup is not None and o.cleanup not in (
            "default", "verbatim", "whitespace", "strip", "scissors"):
        _err(f"error: Invalid cleanup mode {o.cleanup}")
        return 129
    targets = _expand_pick_revs(repo, o.revs)
    if targets is None:
        return 128
    sign_key = _resolve_sequencer_sign(repo, o)
    for target in targets:
        tc = objs.parse_commit(objs.read_object(repo, target)[1])
        # -x appends "(cherry picked from commit <full-sha>)" as a trailer.
        msg = None
        if o.x or o.signoff:
            msg = _cherry_pick_message(repo, tc, o)
        try:
            sha, conflicts, messages = sequencer.cherry_pick(
                repo, target, no_commit=o.no_commit, message=msg,
                allow_empty=o.allow_empty, sign_key=sign_key)
        except sequencer._SignFailure as e:
            _error(e.errmsg)
            _err("fatal: failed to write commit object")
            return 128
        if conflicts:
            from .mergeort import _abbrev as _merge_abbrev
            subj = tc.message.splitlines()[0] if tc.message.strip() else ""
            for m in messages:
                _print(m[2])
            _err(f"error: could not apply {_merge_abbrev(repo, target)}... {subj}")
            _err("hint: After resolving the conflicts, mark them with")
            _err('hint: "git add/rm <pathspec>", then run')
            _err('hint: "git cherry-pick --continue".')
            _err('hint: You can instead skip this commit with "git cherry-pick --skip".')
            _err('hint: To abort and get back to the state before "git cherry-pick",')
            _err('hint: run "git cherry-pick --abort".')
            _err('hint: Disable this message with "git config set advice.mergeConflict false"')
            return 1
        if not o.no_commit:
            _print_pick_summary(repo, sha)
    return 0


def _cherry_pick_message(repo: Repository, tc, o) -> str:
    """Compose the cherry-pick commit message: the picked commit's message,
    plus a '(cherry picked from commit <sha>)' trailer for -x and a
    Signed-off-by trailer for --signoff (sequencer.c do_pick_commit)."""
    msg = tc.message.rstrip("\n")
    trailers: list[str] = []
    if o.x:
        full = refs_mod.rev_parse(repo, tc.message.splitlines()[0]) if False else None
        # The cherry-picked source sha is the commit object's own oid.
        trailers.append(f"(cherry picked from commit {_cherry_source_sha(repo, tc)})")
    if o.signoff:
        committer = objs.build_signature(repo, "committer")
        cwho, _t, _z = _split_ident(committer)
        cn, ce = _parse_who(cwho)
        trailers.append(f"Signed-off-by: {cn} <{ce}>")
    if trailers:
        return msg + "\n\n" + "\n".join(trailers) + "\n"
    return msg + "\n"


def _cherry_source_sha(repo: Repository, tc) -> str:
    """Return the full sha of the commit whose parsed form is *tc* by
    re-hashing its encoded bytes."""
    return objs.hash_bytes("commit", tc.encode(), repo)[0]


def _sequencer_cmdmode(repo: Repository, mode: str, op: str) -> int:
    """Handle cherry-pick/revert --continue|--skip|--abort|--quit.  With no
    sequence in progress git prints 'error: no cherry-pick or revert in
    progress' / 'fatal: <op> failed' (rc 128)."""
    seq_dir = repo.gitdir / "sequencer"
    cherry_head = (repo.gitdir / "CHERRY_PICK_HEAD").exists()
    revert_head = (repo.gitdir / "REVERT_HEAD").exists()
    in_progress = seq_dir.exists() or cherry_head or revert_head
    if not in_progress:
        _err("error: no cherry-pick or revert in progress")
        _err(f"fatal: {op} failed")
        return 128
    # A real in-progress sequence is not modeled beyond single-commit picks;
    # --abort/--quit clear the pseudo-refs, --continue finalizes via commit.
    if mode in ("abort", "quit"):
        for f in ("CHERRY_PICK_HEAD", "REVERT_HEAD", "MERGE_MSG"):
            (repo.gitdir / f).unlink(missing_ok=True)
        if mode == "abort":
            head = refs_mod.rev_parse(repo, "HEAD")
            if head:
                workdir.checkout_tree(repo, objs.parse_commit(objs.read_object(repo, head)[1]).tree)
        return 0
    if mode == "skip":
        for f in ("CHERRY_PICK_HEAD", "REVERT_HEAD"):
            (repo.gitdir / f).unlink(missing_ok=True)
        return 0
    return cmd_commit([])


def cmd_revert(argv: list[str]) -> int:
    repo = _repo()
    from . import sequencer
    o = _parse_sequencer_opts(argv, _REVERT_USAGE, is_revert=True)
    if isinstance(o, int):
        return o
    if o.cmdmode is not None:
        return _sequencer_cmdmode(repo, o.cmdmode, "revert")
    if not o.revs:
        sys.stderr.write(_REVERT_USAGE)
        return 129
    if o.cleanup is not None and o.cleanup not in (
            "default", "verbatim", "whitespace", "strip", "scissors"):
        _err(f"error: Invalid cleanup mode {o.cleanup}")
        return 129
    targets = _expand_pick_revs(repo, o.revs)
    if targets is None:
        return 128
    # revert applies in reverse (newest first) for a range (sequencer.c).
    if any(".." in s for s in o.revs):
        targets = list(reversed(targets))
    sign_key = _resolve_sequencer_sign(repo, o)
    from .mergeort import _abbrev as _merge_abbrev
    for target in targets:
        _, tdata = objs.read_object(repo, target)
        tc = objs.parse_commit(tdata)
        t_subject = tc.message.splitlines()[0] if tc.message.strip() else ""
        t_abbrev = _merge_abbrev(repo, target)

        try:
            sha, conflicts, messages = sequencer.revert(
                repo, target, no_commit=o.no_commit, signoff=o.signoff,
                sign_key=sign_key)
        except sequencer._SignFailure as e:
            _error(e.errmsg)
            _err("fatal: failed to write commit object")
            return 128
        if conflicts:
            # The merge engine's "Auto-merging"/"CONFLICT" lines go to stdout in
            # the order recorded (merge_display_update_messages); each tuple is
            # (primary_path, type_str, message_text, [paths]).
            for m in messages:
                _print(m[2])
            _err(f"error: could not revert {t_abbrev}... {t_subject}")
            _err("hint: After resolving the conflicts, mark them with")
            _err('hint: "git add/rm <pathspec>", then run')
            _err('hint: "git revert --continue".')
            _err('hint: You can instead skip this commit with "git revert --skip".')
            _err('hint: To abort and get back to the state before "git revert",')
            _err('hint: run "git revert --abort".')
            _err("hint: Disable this message with \"git config set advice.mergeConflict false\"")
            return 1
        if not o.no_commit:
            _print_pick_summary(repo, sha)
    return 0


# builtin/rebase.c options that take a value (consume the next token).
_REBASE_VALUE_OPTS = {
    "--onto", "--keep-base", "-s", "--strategy", "-X", "--strategy-option",
    "-x", "--exec", "--whitespace", "-S", "--gpg-sign", "--autosquash",
    "--empty", "-C", "--reschedule-failed-exec", "--gpg-sign",
}
# value-taking forms that, if missing a value, are still benign for our subset.


def cmd_rebase(argv: list[str]) -> int:
    repo = _repo()
    from . import sequencer

    quiet = False
    onto = None
    cmdmode = None  # continue/skip/abort/quit
    positional: list[str] = []
    i, n = 0, len(argv)
    dd = False
    while i < n:
        a = argv[i]
        if dd:
            positional.append(a); i += 1; continue
        if a == "--":
            dd = True; i += 1; continue
        if a in ("--continue", "--skip", "--abort", "--quit", "--edit-todo",
                 "--show-current-patch"):
            cmdmode = a[2:]
        elif a in ("-q", "--quiet"):
            quiet = True
        elif a == "--onto":
            i += 1
            onto = argv[i] if i < n else None
        elif a.startswith("--onto="):
            onto = a.split("=", 1)[1]
        elif a in ("-S", "--gpg-sign"):
            # PARSE_OPT_OPTARG: bare form takes no following token.
            pass
        elif a.startswith("-S") or a.startswith("--gpg-sign="):
            pass
        elif a in _REBASE_VALUE_OPTS:
            i += 1  # consume the value; the option itself is accepted as a no-op
        elif a.startswith("--") and "=" in a:
            pass  # --opt=value forms accepted as no-ops for our subset
        elif a.startswith("-") and a != "-":
            # Other documented rebase flags are accepted as no-ops (the subset of
            # behavior pythongit implements is the non-interactive linear rebase).
            pass
        else:
            positional.append(a)
        i += 1

    head_sym, _ = refs_mod.read_head(repo)
    branch = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else "HEAD"

    # Sequence cmdmodes with no rebase in progress: builtin/rebase.c dies
    # "fatal: no rebase in progress" (rc 128).
    if cmdmode is not None:
        rebase_dir = repo.gitdir / "rebase-merge"
        rebase_apply = repo.gitdir / "rebase-apply"
        if not (rebase_dir.exists() or rebase_apply.exists()):
            _err("fatal: no rebase in progress")
            return 128
        # A real in-progress rebase is not modeled; clear state on abort/quit.
        if cmdmode in ("abort", "quit"):
            import shutil
            for d in (rebase_dir, rebase_apply):
                if d.exists():
                    shutil.rmtree(d, ignore_errors=True)
            return 0
        return 0

    upstream = positional[0] if positional else None
    if upstream is None:
        # No upstream and no tracking info: builtin/rebase.c prints the helpful
        # "no tracking information" block to stdout (rc 1).
        from . import gitconfig as _gc
        remote = _gc.get(repo, f"branch.{branch}.remote") if branch != "HEAD" else None
        if not remote:
            _print("There is no tracking information for the current branch.")
            _print("Please specify which branch you want to rebase against.")
            _print("See git-rebase(1) for details.")
            _print("")
            _print("    git rebase '<branch>'")
            _print("")
            _print("If you wish to set tracking information for this branch you can do so with:")
            _print("")
            _print(f"    git branch --set-upstream-to=<remote>/<branch> {branch}")
            _print("")
            return 1
        merge_cfg = _gc.get(repo, f"branch.{branch}.merge") or ""
        short = merge_cfg[len("refs/heads/"):] if merge_cfg.startswith("refs/heads/") else merge_cfg
        upstream = f"{remote}/{short}"

    # --onto <newbase> selects the base to replay onto; otherwise upstream.
    base_ref = onto if onto is not None else upstream
    picked, conflicts = sequencer.rebase_onto(repo, base_ref)
    if conflicts:
        for p in conflicts:
            _err(f"CONFLICT: {p}")
        return 1
    if quiet:
        return 0
    if picked == 0:
        _print(f"Current branch {branch} is up to date.")
    else:
        # git's rebase prints progress + the result line to stderr: each step
        # "Rebasing (k/n)\r" overwriting the previous, then the final message.
        prog = "".join(f"Rebasing ({k}/{picked})\r" for k in range(1, picked + 1))
        sys.stderr.write(prog + f"Successfully rebased and updated {head_sym or 'HEAD'}.\n")
    return 0


def cmd_reflog(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit reflog", add_help=False)
    ap.add_argument("-n", "--max-count", type=int, default=None)
    ap.add_argument("--oneline", action="store_true")  # default format is already oneline
    ap.add_argument("--date", default=None)
    ap.add_argument("--no-abbrev", dest="no_abbrev", action="store_true")
    ap.add_argument("--abbrev", nargs="?", type=int, const=7, default=7)
    ap.add_argument("action", nargs="?", default="show")
    ap.add_argument("ref", nargs="?", default="HEAD")
    # `reflog expire`/`delete` take extra flags (--dry-run, --expire=, --all, …)
    # that we accept and treat as a no-op, so tolerate unknown options.
    args, _unknown = ap.parse_known_args(_expand_count_shorthand(argv))
    repo = _repo()
    if args.action in ("expire", "delete"):
        # pythongit never expires/prunes reflog entries; accept as a no-op.
        return 0
    if args.action == "exists":
        from . import reflog as _rl
        rr = args.ref
        full = rr if rr == "HEAD" else (refs_mod.dwim_full_name(repo, rr) or rr)
        return 0 if _rl.read(repo, full) else 1
    # `reflog [show] [ref]`: the first positional may be the subcommand or a ref.
    ref = args.ref
    if args.action not in ("show",) and ref == "HEAD":
        ref = args.action
    from . import reflog
    # The reflog is stored under logs/<full-ref>; resolve short names like
    # "main" to refs/heads/main (HEAD keeps its top-level log).
    full_ref = ref if ref == "HEAD" else (refs_mod.dwim_full_name(repo, ref) or ref)
    entries = reflog.read(repo, full_ref)
    zero = repo.null_oid()
    shown = 0
    for i, (old, new, ident, msg) in enumerate(reversed(entries)):
        # git skips deletion markers (zero new-oid, e.g. a branch rename's
        # delete half) in the display, but they still consume an @{N} slot.
        if new == zero:
            continue
        if args.max_count is not None and shown >= args.max_count:
            break
        inner = _format_date(ident, args.date) if args.date else str(i)
        disp = new if args.no_abbrev else new[:args.abbrev]
        _print(f"{disp} {ref}@{{{inner}}}: {msg}")
        shown += 1
    return 0


# The full git_stash_usage[] block from builtin/stash.c (the BUILTIN_STASH_*
# _USAGE macros joined by parse_options' "   or: " prefix), followed by the
# blank line + option list that parse_options prints for the default (push)
# option table on a parse error.  Emitted verbatim on an unknown stash option.
_STASH_USAGE = (
    "usage: git stash list [<log-options>]\n"
    "   or: git stash show [-u | --include-untracked | --only-untracked] [<diff-options>] [<stash>]\n"
    "   or: git stash drop [-q | --quiet] [<stash>]\n"
    "   or: git stash pop [--index] [-q | --quiet] [<stash>]\n"
    "   or: git stash apply [--index] [-q | --quiet] [<stash>]\n"
    "   or: git stash branch <branchname> [<stash>]\n"
    "   or: git stash [push] [-p | --patch] [-S | --staged] [-k | --[no-]keep-index] [-q | --quiet]\n"
    "                 [-u | --include-untracked] [-a | --all] [(-m | --message) <message>]\n"
    "                 [--pathspec-from-file=<file> [--pathspec-file-nul]]\n"
    "                 [--] [<pathspec>...]\n"
    "   or: git stash save [-p | --patch] [-S | --staged] [-k | --[no-]keep-index] [-q | --quiet]\n"
    "                 [-u | --include-untracked] [-a | --all] [<message>]\n"
    "   or: git stash clear\n"
    "   or: git stash create [<message>]\n"
    "   or: git stash store [(-m | --message) <message>] [-q | --quiet] <commit>\n"
    "   or: git stash export (--print | --to-ref <ref>) [<stash>...]\n"
    "   or: git stash import <commit>\n"
    "\n"
    "    -k, --[no-]keep-index keep index\n"
    "    -S, --[no-]staged     stash staged changes only\n"
    "    -p, --[no-]patch      stash in patch mode\n"
    "    --[no-]auto-advance   auto advance to the next file when selecting hunks interactively\n"
    "    -U, --unified <n>     generate diffs with <n> lines context\n"
    "    --inter-hunk-context <n>\n"
    "                          show context between diff hunks up to the specified number of lines\n"
    "    -q, --[no-]quiet      quiet mode\n"
    "    -u, --[no-]include-untracked\n"
    "                          include untracked files in stash\n"
    "    -a, --[no-]all        include ignore files\n"
    "    -m, --[no-]message <message>\n"
    "                          stash message\n"
    "    --[no-]pathspec-from-file <file>\n"
    "                          read pathspec from file\n"
    "    --[no-]pathspec-file-nul\n"
    "                          with --pathspec-from-file, pathspec elements are separated with NUL character\n"
    "\n"
)


def _stash_unknown_option(opt: str) -> int:
    """Emit parse_options' diagnostic for an unknown stash option: the
    "error: unknown {option,switch} `X'" line plus the full git_stash_usage
    block, then return rc 129 (PARSE_OPT_HELP / parse error)."""
    if opt.startswith("--"):
        sys.stderr.write(f"error: unknown option `{opt[2:]}'\n")
    else:
        sys.stderr.write(f"error: unknown switch `{opt[1:]}'\n")
    sys.stderr.write(_STASH_USAGE)
    return 129


def _stash_push(argv: list[str], save: bool) -> int:
    """Handle `git stash push` / `git stash save` (non-interactive subset)."""
    from . import stash
    quiet = False
    keep_index = False
    include_untracked = 0  # 0 none, 1 -u, 2 -a/--all
    only_staged = False
    patch_mode = False
    message = ""
    pathspec_from_file = None
    pathspec_file_nul = False
    pathspecs: list[str] = []

    i = 0
    seen_dashdash = False
    n = len(argv)
    while i < n:
        a = argv[i]
        if seen_dashdash:
            pathspecs.append(a)
            i += 1
            continue
        if a == "--":
            seen_dashdash = True
        elif a in ("-q", "--quiet"):
            quiet = True
        elif a in ("-k", "--keep-index"):
            keep_index = True
        elif a == "--no-keep-index":
            keep_index = False
        elif a in ("-u", "--include-untracked"):
            include_untracked = stash.INCLUDE_UNTRACKED
        elif a in ("-a", "--all"):
            include_untracked = stash.INCLUDE_ALL_FILES
        elif a in ("-S", "--staged"):
            only_staged = True
        elif a in ("-p", "--patch"):
            patch_mode = True
        elif a in ("-m", "--message"):
            i += 1
            message = argv[i] if i < n else ""
        elif a.startswith("--message="):
            message = a[len("--message="):]
        elif a.startswith("-m") and len(a) > 2:
            message = a[2:]
        elif a == "--pathspec-from-file":
            i += 1
            pathspec_from_file = argv[i] if i < n else ""
        elif a.startswith("--pathspec-from-file="):
            pathspec_from_file = a[len("--pathspec-from-file="):]
        elif a == "--pathspec-file-nul":
            pathspec_file_nul = True
        elif save and not a.startswith("-"):
            # `git stash save <message...>` joins the rest as the message.
            message = " ".join(argv[i:])
            break
        elif not a.startswith("-"):
            pathspecs.append(a)
        else:
            return _stash_unknown_option(a)
        i += 1

    # --patch interactive hunk selection (do_push_stash patch branch).
    if patch_mode:
        if pathspec_from_file is not None:
            _err("fatal: options '--pathspec-from-file' and '--patch' cannot be used together")
            return 128
        if include_untracked:
            _err("Can't use --patch and --include-untracked or --all at the same time")
            return 1
        # --patch overrides --staged; keep_index defaults to 1 in patch mode.
        repo = _repo()
        ps_items = None
        if pathspecs:
            try:
                cwd = os.path.realpath(os.getcwd())
                root = os.path.realpath(str(repo.path))
                prefix = os.path.relpath(cwd, root)
                if prefix == ".":
                    prefix = ""
            except (OSError, ValueError):
                prefix = ""
            try:
                ps_items = stash.parse_pathspecs(prefix, pathspecs)
            except stash.PathspecParseError as exc:
                _err(f"fatal: {exc}")
                return 128
        result = stash.push_patch(repo, message, pathspecs=ps_items, quiet=quiet)
        if result is None:
            if not quiet:
                _print("No local changes to save")
            return 0
        if result == "no-head":
            return 1
        if result == 1:
            return 1
        if result == "apply-failed":
            return 1
        return 0

    # --pathspec-from-file conflicts (push_stash, in C-source order: --patch is
    # checked first, then --staged, then command-line pathspec args).
    if pathspec_from_file is not None:
        if only_staged:
            _err("fatal: options '--pathspec-from-file' and '--staged' cannot be used together")
            return 128
        if pathspecs:
            _err("fatal: '--pathspec-from-file' and pathspec arguments cannot be used together")
            return 128
        # Read the pathspecs from the file (or stdin for "-").
        try:
            if pathspec_from_file == "-":
                raw = sys.stdin.buffer.read()
            else:
                with open(pathspec_from_file, "rb") as fh:
                    raw = fh.read()
        except OSError as exc:
            _err(f"fatal: could not open '{pathspec_from_file}' for reading: "
                 f"{exc.strerror}")
            return 128
        sep = "\0" if pathspec_file_nul else "\n"
        text = raw.decode("utf-8")
        pathspecs = [p for p in text.split(sep) if p]
    elif pathspec_file_nul:
        _err("fatal: the option '--pathspec-file-nul' requires '--pathspec-from-file'")
        return 128

    if only_staged and include_untracked:
        _err("Can't use --staged and --include-untracked or --all at the same time")
        return 1

    repo = _repo()
    # Build the parsed pathspec items (with the cwd prefix git would prepend).
    ps_items = None
    if pathspecs:
        try:
            cwd = os.path.realpath(os.getcwd())
            root = os.path.realpath(str(repo.path))
            prefix = os.path.relpath(cwd, root)
            if prefix == ".":
                prefix = ""
        except (OSError, ValueError):
            prefix = ""
        try:
            ps_items = stash.parse_pathspecs(prefix, pathspecs)
        except stash.PathspecParseError as exc:
            _err(f"fatal: {exc}")
            return 128

    result = stash.push(repo, message, keep_index=keep_index,
                        include_untracked=include_untracked,
                        only_staged=only_staged, pathspecs=ps_items,
                        quiet=quiet)
    if result == "path-error":
        return 1
    if result == "no-head":
        # "You do not have the initial commit yet" already printed by push().
        return 1
    if result == "staged-apply-failed":
        # The stash was created; the reverse-apply of the staged patch failed.
        # Errors + "Cannot remove worktree changes" already printed by push().
        return 1
    if result == "no-staged":
        if not quiet:
            _err("No staged changes")
        return 1
    if result is None:
        if not quiet:
            _print("No local changes to save")
        return 0
    # Success: push() already printed the "Saved working directory ..." line.
    return 0


def _stash_export(argv: list[str]) -> int:
    from . import stash
    action = None  # "print" | "to-ref"
    ref = None
    revs: list[str] = []
    i = 0
    n = len(argv)
    while i < n:
        a = argv[i]
        if a == "--print":
            action = "print" if action is None else action
        elif a == "--to-ref":
            i += 1
            ref = argv[i] if i < n else ""
        elif a.startswith("--to-ref="):
            ref = a[len("--to-ref="):]
        elif a == "--":
            pass
        else:
            revs.append(a)
        i += 1

    if ref and action is None:
        action = "to-ref"
    if action is None or (ref and action == "print"):
        _err("error: exactly one of --print and --to-ref is required")
        return 1

    repo = _repo()
    tip = stash.export_stash(repo, revs)
    if tip is None:
        return 1
    if action == "print":
        _print(tip)
    else:
        refs_mod.update_ref(repo, ref, tip)
    return 0


def _stash_show(argv: list[str]) -> int:
    patch = False
    unified = 3
    show_untracked = 0  # 0 none, 1 include, 2 only
    ref = None
    i = 0
    n = len(argv)
    while i < n:
        a = argv[i]
        if a in ("-p", "--patch"):
            patch = True
        elif a in ("-u", "--include-untracked"):
            show_untracked = 1
        elif a == "--only-untracked":
            show_untracked = 2
        elif a in ("-U", "--unified"):
            i += 1
            unified = int(argv[i]) if i < n else 3
        elif a.startswith("-U"):
            unified = int(a[2:])
        elif a.startswith("--unified="):
            unified = int(a[len("--unified="):])
        elif a == "--":
            pass
        elif not a.startswith("-"):
            ref = a
        i += 1
    repo = _repo()
    # Resolve via get_stash_info so the empty-stash ("No stash entries found.")
    # and out-of-range errors match git's stash machinery.
    from . import stash as _stash_mod
    info = _stash_mod.get_stash_info(repo, [ref] if ref else [])
    if info is None:
        return 1
    sha = info.w_commit
    c = objs.parse_commit(objs.read_object(repo, sha)[1])
    base_tree = _commit_tree(repo, c.parents[0]) if c.parents else None
    # u_tree is parent[2]'s tree, if present.
    u_tree = None
    if len(c.parents) >= 3:
        u_tree = _commit_tree(repo, c.parents[2])

    if show_untracked == 2:
        # --only-untracked: diff the empty tree against u_tree.
        if u_tree is not None:
            if patch:
                _emit_tree_patch(repo, None, u_tree, unified)
            else:
                _diff_stat(_tree_changes(repo, None, u_tree))
        return 0

    target_tree = c.tree
    if show_untracked == 1 and u_tree is not None:
        # Merge w_tree and u_tree (disjoint paths) into one virtual tree.
        merged: dict[str, tuple[str, str]] = {}
        for path, mode, blob in workdir.iter_tree_files(repo, c.tree):
            merged[path] = (mode, blob)
        for path, mode, blob in workdir.iter_tree_files(repo, u_tree):
            merged[path] = (mode, blob)
        target_tree = _stash_build_tree(repo, merged)

    if patch:
        _emit_tree_patch(repo, base_tree, target_tree, unified)
    else:
        _diff_stat(_tree_changes(repo, base_tree, target_tree))
    return 0


def _stash_build_tree(repo: Repository, files: dict[str, tuple[str, str]]) -> str:
    from . import stash
    return stash._build_tree_from_blobs(repo, {p: (int(m, 8), s) for p, (m, s) in files.items()})


def cmd_stash(argv: list[str]) -> int:
    from . import stash
    _stash_subs = {"push", "save", "list", "apply", "pop", "show", "drop",
                   "clear", "branch", "create", "store", "export", "import"}
    if not argv:
        action, rest = "push", []
    elif argv[0] in _stash_subs:
        action, rest = argv[0], argv[1:]
    else:
        action, rest = "push", argv

    if action == "push":
        return _stash_push(rest, save=False)
    if action == "save":
        return _stash_push(rest, save=True)
    if action == "export":
        return _stash_export(rest)
    if action == "show":
        return _stash_show(rest)

    repo = _repo()
    if action == "list":
        # builtin/stash.c list_stash(): if refs/stash is absent, print nothing.
        # Otherwise run `git log --format=%gd: %gs -g --first-parent
        # <user-options> refs/stash --`, so all git-log options (--oneline, -p,
        # --format, --stat, ...) pass straight through to the log machinery.
        if not refs_mod.read_ref(repo, "refs/stash"):
            return 0
        log_argv = ["--format=%gd: %gs", "-g", "--first-parent"]
        log_argv += rest
        log_argv += ["refs/stash", "--"]
        return cmd_log(log_argv)
    if action in ("apply", "pop"):
        quiet = False
        want_index = False
        positionals: list[str] = []
        for a in rest:
            if a in ("-q", "--quiet"):
                quiet = True
            elif a == "--index":
                want_index = True
            elif a == "--no-index":
                want_index = False
            elif a == "--":
                continue
            else:
                positionals.append(a)
        info, rc = stash.get_stash_info_rc(repo, positionals)
        if info is None:
            return rc
        # pop drops only a genuine stash reference; the assertion happens before
        # applying (get_stash_info_assert in builtin/stash.c).
        if action == "pop" and not info.is_stash_ref:
            _err(f"error: '{info.revision}' is not a stash reference")
            return 1
        arc = stash.do_apply(repo, info, index=want_index)
        if arc:
            return arc
        if not quiet:
            cmd_status([])
        if action == "pop":
            drc = stash.do_drop(repo, info, quiet)
            if drc:
                return drc
        return 0
    if action == "drop":
        positionals = [a for a in rest if not a.startswith("-")]
        quiet = any(a in ("-q", "--quiet") for a in rest)
        info, rc = stash.get_stash_info_rc(repo, positionals)
        if info is None:
            return rc
        if not info.is_stash_ref:
            _err(f"error: '{info.revision}' is not a stash reference")
            return 1
        return stash.do_drop(repo, info, quiet)
    if action == "clear":
        return stash.do_clear(repo)
    if action == "branch":
        if not rest:
            _err("fatal: 'git stash branch' requires a branch name")
            return 128
        branch_name = rest[0]
        positionals = [a for a in rest[1:] if not a.startswith("-")]
        info, rc = stash.get_stash_info_rc(repo, positionals)
        if info is None:
            return rc
        # git stash branch: create+checkout branch at b_commit, apply --index,
        # then drop the stash.
        rc = cmd_checkout(["-b", branch_name, info.b_commit])
        if rc:
            return rc
        arc = stash.do_apply(repo, info, index=True)
        if arc:
            return arc
        cmd_status([])
        if info.is_stash_ref:
            return stash.do_drop(repo, info, False)
        return 0
    if action == "create":
        # create_stash: argv[1:] are joined (space-separated) as the message.
        message = " ".join(rest)
        result = stash.create(repo, message)
        if result == "no-head":
            return 1
        if result is None:
            return 0  # no tracked changes: nothing printed
        _print(result)
        return 0
    if action == "store":
        # store_stash: -q/--quiet, -m/--message <msg>, one required <commit> arg.
        quiet = False
        store_msg: Optional[str] = None
        positionals = []
        j = 0
        while j < len(rest):
            a = rest[j]
            if a in ("-q", "--quiet"):
                quiet = True
            elif a in ("-m", "--message"):
                j += 1
                store_msg = rest[j] if j < len(rest) else ""
            elif a.startswith("--message="):
                store_msg = a[len("--message="):]
            elif a.startswith("-m") and len(a) > 2:
                store_msg = a[2:]
            elif a == "--":
                pass
            else:
                positionals.append(a)
            j += 1
        if len(positionals) != 1:
            if not quiet:
                _err('"git stash store" requires one <commit> argument')
            return 1
        return stash.store(repo, positionals[0], store_msg, quiet)
    # import is not implemented here.
    _err(f"fatal: pygit: stash {action} is not supported")
    return 128


# ===========================================================================
# fetch / push / pull over local (file path / file://) remotes
#
# Mirrors builtin/fetch.c, builtin/push.c, builtin/pull.c, transport.c and the
# local-transport object/ref negotiation.  Display output is byte-exact with
# git 2.54.0 (the "From"/"To" headers, the columnated status records, the
# rejection/advice messages, FETCH_HEAD, and tracking-ref updates).
# ===========================================================================

_DEFAULT_ABBREV = 7


def _xport_anonymize_url(url: str) -> str:
    """transport_anonymize_url(): for local paths this is the path unchanged."""
    return url


def _strip_url_for_display(url: str) -> str:
    """display_state_init(): strip trailing slashes, then a trailing ``.git``."""
    s = url
    i = len(s) - 1
    while i >= 0 and s[i] == "/":
        i -= 1
    # i is the index of the last non-slash char
    if i > 3 and s[i - 3:i + 1] == ".git":
        return s[:i - 3]
    return s[:i + 1]


def _summary_width(pairs: list[tuple[str, str]]) -> int:
    """transport_summary_width(): 2*maxw+3 where maxw is the widest abbrev.

    With DEFAULT_ABBREV=7 and small fresh repos this is always 7, giving 17.
    """
    maxw = -1
    for old, new in pairs:
        for oid in (old, new):
            # find_unique_abbrev is >= DEFAULT_ABBREV; 7 in practice
            w = _DEFAULT_ABBREV
            if w > maxw:
                maxw = w
    if maxw < 0:
        maxw = _DEFAULT_ABBREV
    return 2 * maxw + 3


def _abbrev(sha: str) -> str:
    return sha[:_DEFAULT_ABBREV]


def _resolve_remote(repo: Repository, name_or_url: str) -> "tuple[str, str, list[str], list[str]]":
    """Return (remote_name, url, fetch_refspecs, push_refspecs).

    ``name_or_url`` may be a configured remote name or a bare URL.  For a URL,
    remote_name is the URL itself (git uses the URL as the "remote name").
    """
    from . import gitconfig
    cp = repo.config()
    sect = f'remote "{name_or_url}"'
    if cp.has_section(sect):
        url = gitconfig.get(repo, f"remote.{name_or_url}.url") or ""
        pushurl = gitconfig.get(repo, f"remote.{name_or_url}.pushurl")
        fetch_rs = gitconfig.get_all(repo, f"remote.{name_or_url}.fetch")
        push_rs = gitconfig.get_all(repo, f"remote.{name_or_url}.push")
        return name_or_url, url, fetch_rs, push_rs
    # Bare URL.
    return name_or_url, name_or_url, [], []


def _push_url_for(repo: Repository, name_or_url: str) -> str:
    from . import gitconfig
    cp = repo.config()
    sect = f'remote "{name_or_url}"'
    if cp.has_section(sect):
        pushurl = gitconfig.get(repo, f"remote.{name_or_url}.pushurl")
        if pushurl:
            return pushurl
        return gitconfig.get(repo, f"remote.{name_or_url}.url") or ""
    return name_or_url


def _prettify_refname(name: str) -> str:
    for prefix in ("refs/heads/", "refs/tags/", "refs/remotes/"):
        if name.startswith(prefix):
            return name[len(prefix):]
    return name


def _err_no_repo(spec: str) -> int:
    """connect.c die_no_repository(): the canonical no-remote error block."""
    sys.stderr.write(
        f"fatal: '{spec}' does not appear to be a git repository\n"
        "fatal: Could not read from remote repository.\n\n"
        "Please make sure you have the correct access rights\n"
        "and the repository exists.\n")
    return 128


# ---------------------------------------------------------------------------
# push
# ---------------------------------------------------------------------------

_PUSH_ADVICE = {
    "non_ff_head": (
        "Updates were rejected because the tip of your current branch is behind\n"
        "its remote counterpart. If you want to integrate the remote changes,\n"
        "use 'git pull' before pushing again.\n"
        "See the 'Note about fast-forwards' in 'git push --help' for details."),
    "non_ff_other": (
        "Updates were rejected because a pushed branch tip is behind its remote\n"
        "counterpart. If you want to integrate the remote changes, use 'git pull'\n"
        "before pushing again.\n"
        "See the 'Note about fast-forwards' in 'git push --help' for details."),
    "already_exists": (
        "Updates were rejected because the tag already exists in the remote."),
    "fetch_first": (
        "Updates were rejected because the remote contains work that you do not\n"
        "have locally. This is usually caused by another repository pushing to\n"
        "the same ref. If you want to integrate the remote changes, use\n"
        "'git pull' before pushing again.\n"
        "See the 'Note about fast-forwards' in 'git push --help' for details."),
    "needs_force": (
        "You cannot update a remote ref that points at a non-commit object,\n"
        "or update a remote ref to make it point at a non-commit object,\n"
        "without using the '--force' option.\n"),
}


def _print_push_status_line(code: str, summary: str, frm: Optional[str],
                            to: str, msg: Optional[str], width: int) -> None:
    """transport.c print_ref_status (non-porcelain)."""
    line = " %c %-*s " % (code, width, summary)
    if frm is not None:
        line += "%s -> %s" % (_prettify_refname(frm), _prettify_refname(to))
    else:
        line += _prettify_refname(to)
    if msg:
        line += " (%s)" % msg
    sys.stderr.write(line + "\n")


def cmd_push(argv: list[str]) -> int:
    repo = _repo()
    from . import localtransport as lt
    from . import gitconfig

    verbosity = 0          # -1 quiet, 0 normal, 1+ verbose
    dry_run = False
    force = False
    delete = False
    set_upstream = False
    push_all = False        # --all / --branches
    mirror = False
    push_tags = False
    no_verify = True        # local has no hooks; --verify/--no-verify accepted
    porcelain = False
    push_options: list[str] = []
    positional: list[str] = []
    family = None
    cas = None              # force-with-lease: None | {} (tracking-for-all) | {ref: expect}
    force_if_includes = False
    repo_opt = None         # --repo <value>: only used when no positional repo
    follow_tags = False
    prune = False
    receivepack = None      # --receive-pack/--exec <path>: spawned for local xport

    i = 0
    n = len(argv)
    def need(arg):
        nonlocal i
        i += 1
        if i >= n:
            _err(f"error: option `{arg[2:] if arg.startswith('--') else arg}' requires a value")
            sys.exit(129)
        return argv[i]

    while i < n:
        a = argv[i]
        if a == "--":
            positional.extend(argv[i + 1:])
            break
        elif a in ("-v", "--verbose"):
            verbosity += 1
        elif a in ("-q", "--quiet"):
            verbosity = -1
        elif a in ("-n", "--dry-run"):
            dry_run = True
        elif a in ("-f", "--force"):
            force = True
        elif a in ("-d", "--delete"):
            delete = True
        elif a in ("-u", "--set-upstream"):
            set_upstream = True
        elif a in ("--all", "--branches"):
            push_all = True
        elif a == "--mirror":
            mirror = True
        elif a in ("-t", "--tags"):
            push_tags = True
        elif a == "--no-verify":
            no_verify = True
        elif a == "--verify":
            no_verify = False
        elif a == "--porcelain":
            porcelain = True
        elif a in ("-o", "--push-option"):
            push_options.append(need(a))
        elif a.startswith("--push-option="):
            push_options.append(a.split("=", 1)[1])
        elif a == "--ipv4" or a == "-4":
            family = "ipv4"
        elif a == "--ipv6" or a == "-6":
            family = "ipv6"
        elif a == "--progress" or a == "--no-progress":
            pass
        elif a == "--repo":
            repo_opt = need(a)
        elif a.startswith("--repo="):
            repo_opt = a.split("=", 1)[1]
        elif a == "--follow-tags":
            follow_tags = True
        elif a == "--no-follow-tags":
            follow_tags = False
        elif a == "--prune":
            prune = True
        elif a == "--no-prune":
            prune = False
        elif a in ("--receive-pack", "--exec"):
            receivepack = need(a)
        elif a.startswith("--receive-pack=") or a.startswith("--exec="):
            receivepack = a.split("=", 1)[1]
        elif a == "--signed":
            pass      # OPTARG bool; bare form == --signed=yes (no-op for local)
        elif a.startswith("--signed="):
            val = a.split("=", 1)[1]
            if val not in ("yes", "no", "true", "false", "if-asked"):
                _err(f"error: invalid value for '--signed': '{val}'")
                return 129
        elif a == "--no-signed":
            pass
        elif a.startswith("--recurse-submodules="):
            val = a.split("=", 1)[1]
            if val not in ("check", "on-demand", "no", "only"):
                _err(f"error: invalid value for '--recurse-submodules': '{val}'")
                return 129
        elif a in ("--recurse-submodules", "--no-recurse-submodules"):
            if a == "--recurse-submodules":
                need(a)
        elif a == "--force-with-lease":
            if cas is None:
                cas = {}
            cas["__all__"] = True
        elif a.startswith("--force-with-lease="):
            val = a.split("=", 1)[1]
            if cas is None:
                cas = {}
            if ":" in val:
                ref, expect = val.split(":", 1)
                cas[ref] = expect
            else:
                cas[val] = None   # use tracking for this ref
        elif a == "--no-force-with-lease":
            cas = None
        elif a == "--force-if-includes":
            force_if_includes = True
        elif a == "--no-force-if-includes":
            force_if_includes = False
        elif a == "--atomic" or a == "--no-atomic":
            pass
        elif a == "--thin" or a == "--no-thin":
            pass
        elif a == "--dry":
            # unique-prefix abbreviation of --dry-run (parse-options).
            dry_run = True
        elif a.startswith("-") and a != "-" and not (len(a) == 41 or len(a) == 65):
            from ._transport_usage import PUSH_USAGE
            if a.startswith("--"):
                sys.stderr.write(f"error: unknown option `{a[2:]}'\n")
            else:
                sys.stderr.write(f"error: unknown switch `{a[1]}'\n")
            sys.stderr.write(PUSH_USAGE)
            return 129
        else:
            positional.append(a)
        i += 1

    # Determine remote and refspecs.  builtin/push.c: repo starts as --repo's
    # value, but the FIRST positional (if any) overrides it; the remaining
    # positionals are the refspecs.  So --repo only takes effect when no
    # positional repository was given.
    if positional:
        remote_arg = positional[0]
        spec_args = positional[1:]
    else:
        remote_arg = repo_opt
        spec_args = []

    if remote_arg is None:
        # Default remote = branch's remote, else "origin".
        head_sym, _ = refs_mod.read_head(repo)
        branch = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else None
        remote_arg = (gitconfig.get(repo, f"branch.{branch}.remote") if branch else None) or "origin"

    cp = repo.config()
    if not cp.has_section(f'remote "{remote_arg}"') and not lt.is_local_url(remote_arg):
        return _err_no_repo(remote_arg)

    remote_name, _url, _frs, push_rs = _resolve_remote(repo, remote_arg)
    url = _push_url_for(repo, remote_arg)
    if not lt.is_local_url(url):
        _err("fatal: pygit push supports local (file) remotes only")
        return 128
    if not os.path.exists(lt.local_path(url)):
        return _err_no_repo(url)
    remote = lt.open_remote(url)

    # --receive-pack/--exec: git's local (file) transport spawns the named
    # program via the shell (connect.c: "use_shell=1; <prog> '<path>'").  A
    # bogus program makes the connection fail before any refs are exchanged.
    if receivepack is not None and receivepack not in ("git-receive-pack", "git receive-pack"):
        import subprocess as _sp
        local = lt.local_path(url)
        # sq_quote_buf always wraps the path in single quotes (escaping any ').
        sq = "'" + local.replace("'", "'\\''") + "'"
        cmdstr = f"{receivepack} {sq}"
        # git runs the program via the shell with $0 set to the command line, so
        # the shell's "not found" diagnostic is prefixed with the full command.
        cp2 = _sp.run(["/bin/sh", "-c", cmdstr, cmdstr],
                      stdin=_sp.DEVNULL, stdout=_sp.DEVNULL, stderr=_sp.PIPE)
        if cp2.returncode != 0:
            sys.stderr.buffer.write(cp2.stderr)
            # connect dies with the bare "Could not read from remote
            # repository" block (no "does not appear" line in this path).
            sys.stderr.write(
                "fatal: Could not read from remote repository.\n\n"
                "Please make sure you have the correct access rights\n"
                "and the repository exists.\n")
            return 128

    # send-pack: push options require the receiver to advertise support
    # (receive.advertisePushOptions); otherwise send_pack dies before any work.
    if push_options:
        adv = (gitconfig.get(remote, "receive.advertisePushOptions") or "").lower()
        if adv not in ("true", "1", "yes", "on"):
            sys.stderr.write("fatal: the receiving end does not support push options\n")
            sys.stderr.write("fatal: the remote end hung up unexpectedly\n")
            return 128

    return _do_push(repo, remote, remote_name, url, spec_args, push_rs,
                    verbosity=verbosity, dry_run=dry_run, force=force,
                    delete=delete, set_upstream=set_upstream, push_all=push_all,
                    mirror=mirror, push_tags=push_tags, porcelain=porcelain,
                    cas=cas)


def _do_push(repo, remote, remote_name, url, spec_args, configured_push_rs, *,
             verbosity, dry_run, force, delete, set_upstream, push_all,
             mirror, push_tags, porcelain, cas=None) -> int:
    from . import localtransport as lt
    from . import gitconfig

    anon_url = _xport_anonymize_url(url)
    remote_refs = lt.advertised_refs(remote)   # name -> oid on remote
    local_refs = refs_mod.iter_all_refs(repo)  # name -> oid locally

    # Build the list of (src_name, dst_name, src_oid, force) push commands.
    # commands keep submission order for display.
    commands: list[dict] = []

    def add_command(src_name, dst_name, src_oid, forced, *, display_to=None,
                    src_real=None):
        commands.append(dict(src=src_name, dst=dst_name, new=src_oid,
                             force=forced, src_real=src_real or src_name))

    # match_push_refs errors (e.g. deleting a nonexistent ref) are reported
    # before the transport runs and do not emit a "To" header.
    match_errors: list[str] = []

    def add_delete(spec_name):
        if spec_name.startswith("refs/"):
            if spec_name in remote_refs:
                add_command(None, spec_name, repo.null_oid(), True)
            else:
                match_errors.append(spec_name)
            return
        for cand in (spec_name, f"refs/heads/{spec_name}", f"refs/tags/{spec_name}"):
            if cand in remote_refs:
                add_command(None, cand, repo.null_oid(), True)
                return
        match_errors.append(spec_name)

    if mirror:
        # Mirror: every local ref under refs/ -> same name; delete remote refs
        # not present locally.
        for name in sorted(local_refs):
            add_command(name, name, local_refs[name], True)
        for name in sorted(remote_refs):
            if name not in local_refs:
                add_command(None, name, repo.null_oid(), True)
    elif push_all:
        for name in sorted(local_refs):
            if name.startswith("refs/heads/"):
                add_command(name, name, local_refs[name], force)
        if not commands:
            pass
    elif delete:
        if not spec_args:
            _err("fatal: --delete doesn't make sense without any refs")
            return 128
        for spec in spec_args:
            add_delete(spec)
    else:
        specs = spec_args or configured_push_rs
        # --tags is sugar for the refs/tags/* refspec; when present, no default
        # push refspec is needed even with no positional refspecs.
        if not specs and not push_tags:
            rc = _default_push_refspec(repo, remote_name, set_upstream)
            if isinstance(rc, int):
                return rc
            specs = [rc[0]]
            if rc[1]:
                set_upstream = True
        for raw in specs:
            rs = lt.Refspec(raw)
            if rs.matching:
                # ":" — push matching refs (those existing on both sides).
                for name in sorted(local_refs):
                    if name.startswith("refs/heads/") and name in remote_refs:
                        add_command(name, name, local_refs[name], rs.force or force)
                continue
            src = rs.src
            has_colon = rs.dst is not None
            # Delete: empty source with a destination (":dst" or "src:" where
            # src empty), i.e. nothing to push to the dst.
            if has_colon and (src is None or src == ""):
                add_delete(rs.dst)
                continue
            src_oid = refs_mod.rev_parse(repo, src) if src else None
            src_full = refs_mod.dwim_full_name(repo, src) if src else None
            if src_oid is None:
                _err(f"error: src refspec {src} does not match any")
                _err(f"error: failed to push some refs to '{anon_url}'")
                return 1
            dst = rs.dst if has_colon else (src_full or src)
            dstfull = _expand_dst_ref(dst, src_full, remote_refs)
            # The displayed source is the original refspec token (e.g. HEAD).
            add_command(src, dstfull, src_oid, rs.force or force,
                        src_real=src_full or src)

    if push_tags:
        for name in sorted(local_refs):
            if name.startswith("refs/tags/"):
                if not any(c["dst"] == name for c in commands):
                    add_command(name, name, local_refs[name], force)

    # match_push_refs errors abort the whole push before the transport runs:
    # no "To" header, no other refs are pushed.
    if match_errors:
        if verbosity > 0:
            sys.stderr.write(f"Pushing to {anon_url}\n")
        for name in match_errors:
            sys.stderr.write(f"error: unable to delete '{name}': remote ref does not exist\n")
        sys.stderr.write(f"error: failed to push some refs to '{anon_url}'\n")
        return 1

    if verbosity > 0 and commands:
        sys.stderr.write(f"Pushing to {anon_url}\n")

    if not commands:
        if verbosity >= 0:
            sys.stderr.write("Everything up-to-date\n")
        return 0

    # Classify each command into a status.
    results = []  # list of dict with status info
    reject_reasons = set()
    head_sym, _ = refs_mod.read_head(repo)

    fetch_rs_cfg = gitconfig.get_all(repo, f"remote.{remote_name}.fetch")
    for c in commands:
        dst = c["dst"]
        new = c["new"]
        old = remote_refs.get(dst, repo.null_oid())
        is_delete = (new == repo.null_oid())
        status = None
        force_update = c["force"]
        cas_reject = None
        # --force-with-lease: expected old value comes from the tracking ref.
        if cas is not None and not is_delete:
            entry_all = cas.get("__all__")
            expect = None
            has_cas = False
            if dst in cas and cas[dst] is not None:
                expect = cas[dst]; has_cas = True
            elif dst in cas and cas[dst] is None:
                expect = _tracking_oid(repo, fetch_rs_cfg, dst); has_cas = True
            elif entry_all:
                expect = _tracking_oid(repo, fetch_rs_cfg, dst); has_cas = True
            if has_cas:
                # remote.c apply_cas: when the tracking ref can't be read the
                # expected old value is cleared to the null oid (oidclr), not a
                # hard reject; for a brand-new remote ref old is also null, so
                # the lease is satisfied and the push proceeds.
                if expect is None:
                    expect = repo.null_oid()
                if old != expect:
                    cas_reject = "reject_stale"
                else:
                    force_update = True
        if is_delete:
            status = "deleted"
        elif old == new:
            status = "uptodate"
        elif cas_reject:
            status = cas_reject
        elif old == repo.null_oid():
            status = "new"
        else:
            # Existing ref update — classify the rejection reason like remote.c.
            if not objs.object_exists(repo, old):
                base = "reject_fetch_first"
            elif not _both_commits(repo, old, new):
                base = "reject_needs_force"
            elif not _is_fast_forward(repo, remote, old, new):
                base = "reject_nonff"
            else:
                base = None
            if base is None:
                status = "ff"
            elif force_update:
                status = "forced"
            else:
                status = base
        results.append(dict(cmd=c, status=status, old=old, new=new,
                            is_delete=is_delete))

    # Determine if everything is uptodate / none pushed.
    pushed_any = any(r["status"] in ("new", "ff", "forced", "deleted")
                     for r in results)
    _error_statuses = ("reject_nonff", "reject_fetch_first", "reject_needs_force",
                       "reject_stale")
    has_error = any(r["status"] in _error_statuses for r in results)

    if not pushed_any and not has_error and verbosity <= 0 and not porcelain:
        # Nothing to do — but transport still may print uptodate at -v.
        sys.stderr.write("Everything up-to-date\n")
        return 0

    # width across all involved oids
    width = _summary_width([(r["old"], r["new"]) for r in results])

    # Apply updates (unless dry-run) and collect display, mirroring
    # transport_print_push_status ordering: uptodate (verbose) first, then OK,
    # then errors.
    def _status_fields(r):
        """Return (flag, summary, msg) for a result, like transport.c."""
        c = r["cmd"]; st = r["status"]
        dst = c["dst"]; old = r["old"]; new = r["new"]
        if st == "uptodate":
            return "=", "[up to date]", None
        if st == "new":
            if dst.startswith("refs/tags/"):
                return "*", "[new tag]", None
            if dst.startswith("refs/heads/"):
                return "*", "[new branch]", None
            return "*", "[new reference]", None
        if st == "deleted":
            return "-", "[deleted]", None
        if st == "ff":
            return " ", "%s..%s" % (_abbrev(old), _abbrev(new)), None
        if st == "forced":
            return "+", "%s...%s" % (_abbrev(old), _abbrev(new)), "forced update"
        if st == "reject_nonff":
            return "!", "[rejected]", "non-fast-forward"
        if st == "reject_fetch_first":
            return "!", "[rejected]", "fetch first"
        if st == "reject_needs_force":
            return "!", "[rejected]", "needs force"
        if st == "reject_stale":
            return "!", "[rejected]", "stale info"
        return None, None, None

    def emit(r):
        c = r["cmd"]; st = r["status"]
        dst = c["dst"]; src = c["src"]
        flag, summary, msg = _status_fields(r)
        if flag is None:
            return
        if porcelain:
            # print_ref_status porcelain branch: full ref names, tab-separated,
            # on stdout.  deleted has no "from".
            from_name = c["src_real"] if (src is not None and st != "deleted") else None
            if from_name is not None:
                line = f"{flag}\t{from_name}:{dst}\t"
            else:
                line = f"{flag}\t:{dst}\t"
            line += f"{summary} ({msg})" if msg else summary
            sys.stdout.write(line + "\n")
        else:
            from_name = src if st != "deleted" else None
            _print_push_status_line(flag, summary, from_name, dst, msg, width)

    # Header "To <url>" before the first status record (stderr, or stdout in
    # porcelain mode).
    quiet = verbosity < 0
    show_status = (not quiet) or has_error or porcelain
    printed_header = False

    def header():
        nonlocal printed_header
        if not printed_header:
            (sys.stdout if porcelain else sys.stderr).write(f"To {anon_url}\n")
            printed_header = True

    if show_status:
        header()
        # verbose (or porcelain, which transport.c treats as verbose): uptodate
        # rows are shown first.
        if verbosity > 0 or porcelain:
            for r in results:
                if r["status"] == "uptodate":
                    emit(r)
        # OK statuses
        for r in results:
            if r["status"] in ("new", "ff", "forced", "deleted"):
                emit(r)
        # error statuses
        for r in results:
            st = r["status"]
            if st in _error_statuses:
                emit(r)
                if st == "reject_nonff":
                    if r["cmd"]["dst"] == head_sym:
                        reject_reasons.add("non_ff_head")
                    else:
                        reject_reasons.add("non_ff_other")
                elif st == "reject_fetch_first":
                    reject_reasons.add("fetch_first")
                elif st == "reject_needs_force":
                    reject_reasons.add("needs_force")

    # Apply ref updates on the remote (and local tracking).
    if not dry_run:
        for r in results:
            st = r["status"]; c = r["cmd"]; dst = c["dst"]; new = r["new"]
            if st in ("new", "ff", "forced"):
                # copy objects then update remote ref
                lt.copy_objects(repo, remote, [new], lt.destination_have(remote))
                refs_mod.update_ref(remote, dst, new)
            elif st == "deleted":
                refs_mod.delete_ref(remote, dst)
        # update local tracking refs for OK/uptodate
        _update_tracking_refs(repo, remote_name, results, verbosity)

    # set upstream
    if set_upstream and not dry_run:
        _set_push_upstreams(repo, remote_name, results)

    # cmd_push: "if (porcelain && !push_ret) puts("Done")".  The local transport
    # always succeeds at the protocol level (ref-level rejections are tracked
    # separately), so Done is printed whenever porcelain status was shown.
    if porcelain:
        sys.stdout.write("Done\n")

    # Failure summary + advice.
    if has_error:
        sys.stderr.write(f"error: failed to push some refs to '{anon_url}'\n")
        _emit_push_advice(reject_reasons)
        return 1

    # transport.c: "Everything up-to-date" when nothing was actually pushed
    # (reached only at verbosity > 0 here; the v<=0 case returned earlier).
    # Suppressed in porcelain mode (Done already printed).
    if not pushed_any and verbosity >= 0 and not porcelain:
        sys.stderr.write("Everything up-to-date\n")
    return 0


def _emit_push_advice(reasons: set) -> None:
    if "non_ff_head" in reasons:
        _err(_advice_lines(_PUSH_ADVICE["non_ff_head"]))
    elif "non_ff_other" in reasons:
        _err(_advice_lines(_PUSH_ADVICE["non_ff_other"]))
    elif "already_exists" in reasons:
        _err(_advice_lines(_PUSH_ADVICE["already_exists"]))
    elif "fetch_first" in reasons:
        _err(_advice_lines(_PUSH_ADVICE["fetch_first"]))
    elif "needs_force" in reasons:
        _err(_advice_lines(_PUSH_ADVICE["needs_force"]))


def _advice_lines(text: str) -> str:
    """advise(): prefix each message line with 'hint: ' ('hint:' for blanks).

    A single trailing newline in the message does not produce an extra blank
    hint line (git's strbuf split treats it as the line terminator).
    """
    if text.endswith("\n"):
        text = text[:-1]
    out = []
    for line in text.split("\n"):
        out.append("hint: " + line if line else "hint:")
    return "\n".join(out)


def _is_fast_forward(repo, remote, old, new) -> bool:
    """Whether ``old`` is an ancestor of ``new`` (need both objects).

    The objects for ``old`` live on the remote, ``new`` locally; for the local
    push case we have both via the local store once we have pushed, but for the
    decision we read from whichever store has the object.
    """
    from . import merge as merge_mod
    # old is on the remote; new is local. We need the commit graph of new in
    # the local repo, and old as a candidate ancestor.  old may also be present
    # locally (tracking ref).  Use the local repo if it has old, else copy is
    # not needed — we can walk the remote for the ancestor check using local
    # objects since 'new' descends from history that includes 'old' iff old is
    # reachable from new.
    try:
        return merge_mod.is_ancestor(repo, old, new)
    except Exception:
        return False


def _both_commits(repo, old, new) -> bool:
    """True when both oids resolve to commit objects (remote.c ref_newer guard)."""
    for oid in (old, new):
        try:
            t, _ = objs.read_object(repo, oid)
        except KeyError:
            return False
        if t != "commit":
            return False
    return True


def _tracking_oid(repo, fetch_rs, remote_ref):
    """Local value of the remote-tracking ref for ``remote_ref`` (CAS expect)."""
    track = _tracking_ref_for(fetch_rs, remote_ref)
    if not track:
        return None
    return refs_mod.read_ref(repo, track)


def _full_remote_ref_for_delete(remote_refs: dict, name: str) -> str:
    if name.startswith("refs/"):
        return name
    for cand in (f"refs/heads/{name}", f"refs/tags/{name}"):
        if cand in remote_refs:
            return cand
    if name in remote_refs:
        return name
    return f"refs/heads/{name}"


def _expand_dst_ref(dst: str, src_full: Optional[str], remote_refs: dict) -> str:
    if dst.startswith("refs/"):
        return dst
    # If a remote ref already matches under heads/tags, prefer it.
    if src_full and src_full.startswith("refs/tags/"):
        return f"refs/tags/{dst}"
    for cand in (f"refs/heads/{dst}",):
        return cand
    return f"refs/heads/{dst}"


def _default_push_refspec(repo, remote_name, set_upstream):
    """setup_default_push_refspecs() for push.default=simple.

    Returns (refspec_str, auto_set_upstream) or an int return code on error.
    """
    from . import gitconfig
    head_sym, head_sha = refs_mod.read_head(repo)
    if not head_sym or not head_sym.startswith("refs/heads/"):
        sys.stderr.write(
            "fatal: You are not currently on a branch.\n"
            "To push the history leading to the current (detached HEAD)\n"
            "state now, use\n\n"
            f"    git push {remote_name} HEAD:<name-of-remote-branch>\n\n")
        return 128
    branch = head_sym[len("refs/heads/"):]
    merge = gitconfig.get(repo, f"branch.{branch}.merge")
    bremote = gitconfig.get(repo, f"branch.{branch}.remote")
    auto = (gitconfig.get(repo, "push.autoSetupRemote") or "").lower() in ("true", "1", "yes", "on")
    if not merge or not bremote:
        if auto:
            return (f"{head_sym}:{head_sym}", True)
        advice = ("\nTo have this happen automatically for branches without a tracking\n"
                  "upstream, see 'push.autoSetupRemote' in 'git help config'.\n")
        sys.stderr.write(
            f"fatal: The current branch {branch} has no upstream branch.\n"
            "To push the current branch and set the remote as upstream, use\n\n"
            f"    git push --set-upstream {remote_name} {branch}\n"
            f"{advice}\n")
        return 128
    # simple: upstream branch name must match local branch name
    upstream = merge  # refs/heads/<name>
    up_short = upstream[len("refs/heads/"):] if upstream.startswith("refs/heads/") else upstream
    if up_short != branch:
        _err("fatal: The upstream branch of your current branch does not match\n"
             "the name of your current branch.  To push to the upstream branch\n"
             "on the remote, use\n\n"
             f"    git push {remote_name} HEAD:{up_short}\n\n"
             "To push to the branch of the same name on the remote, use\n\n"
             f"    git push {remote_name} HEAD\n")
        return 128
    return (f"{head_sym}:{upstream}", False)


def _update_tracking_refs(repo, remote_name, results, verbosity) -> None:
    """transport_update_tracking_ref: map pushed remote refs to local tracking."""
    from . import gitconfig
    fetch_rs = gitconfig.get_all(repo, f"remote.{remote_name}.fetch")
    for r in results:
        if r["status"] not in ("new", "ff", "forced", "deleted", "uptodate"):
            continue
        c = r["cmd"]; dst = c["dst"]
        track = _tracking_ref_for(fetch_rs, dst)
        if not track:
            continue
        if verbosity > 0:
            sys.stderr.write(f"updating local tracking ref '{track}'\n")
        if r["status"] == "deleted":
            try:
                refs_mod.delete_ref(repo, track)
            except Exception:
                pass
        else:
            refs_mod.update_ref(repo, track, r["new"])


def _tracking_ref_for(fetch_rs: list[str], remote_ref: str) -> Optional[str]:
    """Map a remote ref through fetch refspecs to a local tracking ref."""
    for raw in fetch_rs:
        spec = raw[1:] if raw.startswith("+") else raw
        if ":" not in spec:
            continue
        src, dst = spec.split(":", 1)
        if src.endswith("*") and dst.endswith("*"):
            prefix = src[:-1]
            if remote_ref.startswith(prefix):
                return dst[:-1] + remote_ref[len(prefix):]
        elif src == remote_ref:
            return dst
    return None


def _set_push_upstreams(repo, remote_name, results) -> None:
    from . import gitconfig
    cfg_path = repo.gitdir / "config"
    for r in results:
        if r["status"] not in ("new", "ff", "forced", "uptodate"):
            continue
        c = r["cmd"]; src = c.get("src_real") or c["src"]; dst = c["dst"]
        if not src or not src.startswith("refs/heads/"):
            continue
        if not dst.startswith("refs/heads/"):
            continue
        local_branch = src[len("refs/heads/"):]
        gitconfig.write_value(cfg_path, "branch", local_branch, "remote", remote_name)
        gitconfig.write_value(cfg_path, "branch", local_branch, "merge", dst)
        dst_short = dst[len("refs/heads/"):]
        _print(f"branch '{local_branch}' set up to track '{remote_name}/{dst_short}'.")


def cmd_fetch(argv: list[str]) -> int:
    return _cmd_fetch_impl(argv)


# ---------------------------------------------------------------------------
# fetch
# ---------------------------------------------------------------------------

def _refcol_width(updates: list[dict], verbosity: int) -> int:
    """builtin/fetch.c refcol_width(): widest remote refname among shown rows.

    ``updates`` is the list of display rows (each with 'remote' and 'local'
    full ref names and an 'uptodate' flag).  Min width 10; uptodate rows count
    only at verbosity>0.
    """
    width = 10
    for u in updates:
        if u.get("hidden"):
            continue
        if verbosity <= 0 and u.get("uptodate"):
            continue
        rlen = len(_prettify_refname(u["remote"]))
        if width < rlen:
            width = rlen
    return width


def _fetch_head_note(remote_ref: str, url_disp: str) -> str:
    # builtin/fetch.c: note is "<kind> '<what>' of <url>"; for HEAD the kind and
    # what are both empty so only the url is written.
    if remote_ref == "HEAD":
        return url_disp
    if remote_ref.startswith("refs/heads/"):
        return f"branch '{remote_ref[len('refs/heads/'):]}' of {url_disp}"
    if remote_ref.startswith("refs/tags/"):
        return f"tag '{remote_ref[len('refs/tags/'):]}' of {url_disp}"
    if remote_ref.startswith("refs/remotes/"):
        return f"remote-tracking branch '{remote_ref[len('refs/remotes/'):]}' of {url_disp}"
    return f"'{remote_ref}' of {url_disp}"


def _cmd_fetch_impl(argv: list[str]) -> int:
    repo = _repo()
    from . import localtransport as lt
    from . import gitconfig

    verbosity = 0
    dry_run = False
    fetch_all = False
    multiple = False
    append = False
    force = False
    prune = False
    prune_tags = False
    keep = False
    update_head_ok = False
    no_tags = False
    tags = False        # -t / --tags : fetch all tags too
    write_fetch_head = True
    refmap: list[str] = []
    fetch_options: list[str] = []
    positional: list[str] = []
    family = None
    unshallow = False
    refetch = False
    porcelain = False
    set_upstream = False
    negotiate_only = False
    negotiation_tips = 0
    no_show_forced_updates = False

    i = 0
    n = len(argv)

    # parse-options unique-prefix abbreviation for the long flags fetch defines.
    _fetch_long = ("verbose", "quiet", "all", "set-upstream", "append", "atomic",
                   "upload-pack", "force", "multiple", "tags", "jobs", "prefetch",
                   "prune", "prune-tags", "recurse-submodules", "dry-run",
                   "porcelain", "write-fetch-head", "keep", "update-head-ok",
                   "progress", "depth", "shallow-since", "shallow-exclude",
                   "deepen", "unshallow", "refetch", "update-shallow", "refmap",
                   "server-option", "ipv4", "ipv6", "negotiation-tip",
                   "negotiate-only", "filter", "auto-maintenance", "auto-gc",
                   "show-forced-updates", "write-commit-graph", "stdin",
                   "no-tags")

    def _expand_fetch_abbrev(tok: str) -> Optional[str]:
        if not tok.startswith("--") or tok == "--" or "=" in tok:
            return tok
        name = tok[2:]
        bare = name[3:] if name.startswith("no-") else name
        neg = name.startswith("no-")
        if bare in _fetch_long:
            return tok
        matches = [c for c in _fetch_long if c.startswith(bare)]
        if len(matches) == 1:
            return "--" + ("no-" if neg else "") + matches[0]
        if len(matches) > 1:
            joined = " or ".join("--" + m for m in matches)
            # parse-options: diagnostic to stderr, usage block to stdout.
            sys.stderr.write(f"error: ambiguous option: {bare} (could be {joined})\n")
            from ._transport_usage import FETCH_USAGE
            sys.stdout.write(FETCH_USAGE)
            return "__ambig__"
        return tok

    # Pre-expand abbreviations (preserving order and -- handling).
    _norm: list[str] = []
    _dd = False
    for tok in argv:
        if _dd:
            _norm.append(tok); continue
        if tok == "--":
            _dd = True; _norm.append(tok); continue
        ex = _expand_fetch_abbrev(tok)
        if ex == "__ambig__":
            return 129
        _norm.append(ex)
    argv = _norm
    n = len(argv)

    def need(arg):
        nonlocal i
        i += 1
        if i >= n:
            _err(f"error: option requires a value")
            sys.exit(129)
        return argv[i]

    while i < n:
        a = argv[i]
        if a == "--":
            positional.extend(argv[i + 1:]); break
        elif a in ("-v", "--verbose"):
            verbosity += 1
        elif a in ("-q", "--quiet"):
            verbosity = -1
        elif a in ("--all",):
            fetch_all = True
        elif a == "--multiple":
            multiple = True
        elif a == "--dry-run":
            dry_run = True
        elif a == "--no-dry-run":
            dry_run = False
        elif a in ("-a", "--append"):
            append = True
        elif a in ("-f", "--force"):
            force = True
        elif a in ("-p", "--prune"):
            prune = True
        elif a in ("-P", "--prune-tags"):
            prune_tags = True
        elif a in ("-k", "--keep"):
            keep = True
        elif a in ("-u", "--update-head-ok"):
            update_head_ok = True
        elif a in ("-n", "--no-tags"):
            no_tags = True
        elif a in ("-t", "--tags"):
            tags = True
        elif a == "--no-write-fetch-head":
            write_fetch_head = False
        elif a == "--write-fetch-head":
            write_fetch_head = True
        elif a == "-m" or a == "--refmap":
            refmap.append(need(a))
        elif a.startswith("--refmap="):
            refmap.append(a.split("=", 1)[1])
        elif a in ("-o", "--server-option"):
            fetch_options.append(need(a))
        elif a.startswith("--server-option="):
            fetch_options.append(a.split("=", 1)[1])
        elif a in ("-j", "--jobs"):
            need(a)
        elif a.startswith("--jobs="):
            pass
        elif a == "--ipv4" or a == "-4":
            family = "ipv4"
        elif a == "--ipv6" or a == "-6":
            family = "ipv6"
        elif a == "--unshallow":
            unshallow = True
        elif a == "--refetch":
            refetch = True
        elif a in ("--auto-maintenance", "--auto-gc", "--no-auto-maintenance",
                   "--no-auto-gc"):
            pass
        elif a == "--progress" or a == "--no-progress":
            pass
        elif a == "--set-upstream":
            set_upstream = True
        elif a == "--atomic" or a == "--no-atomic":
            pass
        elif a == "--porcelain" or a == "--no-porcelain":
            porcelain = (a == "--porcelain")
        elif a == "--negotiate-only":
            negotiate_only = True
        elif a in ("--negotiation-tip",):
            need(a); negotiation_tips += 1
        elif a.startswith("--negotiation-tip="):
            negotiation_tips += 1
        elif a == "--show-forced-updates":
            no_show_forced_updates = False
        elif a == "--no-show-forced-updates":
            no_show_forced_updates = True
        elif a in ("--prefetch", "--no-prefetch", "--update-shallow",
                   "--no-update-shallow", "--stdin", "--write-commit-graph",
                   "--no-write-commit-graph", "--deepen"):
            if a == "--deepen":
                need(a)
        elif a == "--upload-pack":
            need(a)
        elif a.startswith("--upload-pack="):
            pass
        elif a in ("--recurse-submodules", "--no-recurse-submodules"):
            if a == "--recurse-submodules":
                pass
        elif a.startswith("--recurse-submodules="):
            pass
        elif a == "--filter":
            need(a)
        elif a.startswith("--filter=") or a == "--no-filter":
            pass
        elif a in ("--shallow-since", "--shallow-exclude"):
            need(a)
        elif a.startswith("--shallow-since=") or a.startswith("--shallow-exclude="):
            pass
        elif a.startswith("--depth=") or a == "--depth":
            if a == "--depth":
                need(a)
        elif a.startswith("-") and a != "-":
            from ._transport_usage import FETCH_USAGE
            if a.startswith("--"):
                sys.stderr.write(f"error: unknown option `{a[2:]}'\n")
            else:
                sys.stderr.write(f"error: unknown switch `{a[1]}'\n")
            sys.stderr.write(FETCH_USAGE)
            return 129
        else:
            positional.append(a)
        i += 1

    # builtin/fetch.c: --dry-run disables FETCH_HEAD writing entirely.
    if dry_run:
        write_fetch_head = False

    # --negotiate-only requires at least one --negotiation-tip (validated even
    # before any remote work; builtin/fetch.c).
    if negotiate_only and negotiation_tips == 0:
        _err("fatal: --negotiate-only needs one or more --negotiation-tip=*")
        return 128

    # --unshallow on a complete (non-shallow) repository is an error.
    if unshallow and not (repo.gitdir / "shallow").exists():
        _err("fatal: --unshallow on a complete repository does not make sense")
        return 128

    # --no-show-forced-updates prints a one-time warning before fetching.
    if no_show_forced_updates:
        _err("warning: fetch normally indicates which branches had a forced update,")
        _err("but that check has been disabled; to re-enable, use '--show-forced-updates'")
        _err("flag or run 'git config fetch.showForcedUpdates true'")

    # Resolve the list of remotes to fetch from.
    if fetch_all:
        remotes = _all_remote_names(repo)
        spec_args = []
    elif multiple:
        remotes = positional or _all_remote_names(repo)
        spec_args = []
    else:
        if positional:
            remote_arg = positional[0]
            spec_args = positional[1:]
        else:
            head_sym, _ = refs_mod.read_head(repo)
            branch = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else None
            configured = gitconfig.get(repo, f"branch.{branch}.remote") if branch else None
            # remote_get(NULL): no args and no remotes configured -> nothing to
            # do (git runs fetch_multiple on an empty list and exits 0, having
            # truncated FETCH_HEAD).
            if not configured and not _all_remote_names(repo):
                if write_fetch_head and not append:
                    (repo.gitdir / "FETCH_HEAD").write_text("", encoding="utf-8")
                return 0
            remote_arg = configured or "origin"
            spec_args = []
        remotes = [remote_arg]

    # builtin/fetch.c: truncate FETCH_HEAD up front unless --append; this
    # happens before the transport connects, so a failing fetch still leaves an
    # empty FETCH_HEAD behind.
    if write_fetch_head and not append:
        (repo.gitdir / "FETCH_HEAD").write_text("", encoding="utf-8")

    # builtin/fetch.c: --all (or --multiple) with exactly ONE remote is NOT run
    # through fetch_multiple ("do not do fetch_multiple() of one"); it goes via
    # fetch_one, so no "Fetching <name>" header is printed.
    multi = (fetch_all or multiple) and len(remotes) != 1
    rc = 0
    for ridx, remote_arg in enumerate(remotes):
        # fetch_multiple(): print "Fetching <name>" before each remote.
        if multi and verbosity >= 0:
            sys.stdout.write(f"Fetching {remote_arg}\n")
            sys.stdout.flush()
        r = _fetch_one_remote(repo, remote_arg, [] if multi else spec_args,
                              verbosity=verbosity, dry_run=dry_run, force=force,
                              prune=prune, prune_tags=prune_tags, no_tags=no_tags,
                              tags=tags, append=True, write_fetch_head=write_fetch_head,
                              refmap=refmap, update_head_ok=update_head_ok,
                              porcelain=porcelain, set_upstream=set_upstream)
        if r != 0:
            if multi:
                sys.stderr.write(f"error: could not fetch {remote_arg}\n")
            rc = 1 if multi else r
    return rc


def _all_remote_names(repo: Repository) -> list[str]:
    from . import gitconfig
    seen = []
    for full, _v in gitconfig.list_all(repo):
        if full.startswith("remote.") and full.endswith(".url"):
            name = full[len("remote."):-len(".url")]
            if name not in seen:
                seen.append(name)
    return seen


def _fetch_one_remote(repo, remote_arg, spec_args, *, verbosity, dry_run, force,
                      prune, prune_tags, no_tags, tags, append, write_fetch_head,
                      refmap, update_head_ok, porcelain=False, set_upstream=False) -> int:
    from . import localtransport as lt
    from . import gitconfig

    cp = repo.config()
    is_named = cp.has_section(f'remote "{remote_arg}"')
    if not is_named and not lt.is_local_url(remote_arg):
        return _err_no_repo(remote_arg)
    remote_name, url, fetch_rs, _push_rs = _resolve_remote(repo, remote_arg)
    if not url:
        url = remote_arg
    if not lt.is_local_url(url):
        _err("fatal: pygit fetch supports local (file) remotes only")
        return 128
    if not os.path.exists(lt.local_path(url)):
        return _err_no_repo(url)
    remote = lt.open_remote(url)
    remote_refs = lt.advertised_refs(remote)
    url_disp = _strip_url_for_display(url)

    # Determine whether tags should be auto-followed.  Default: when fetching
    # via configured refspecs, tags pointing at fetched objects are followed.
    tag_opt = "follow"
    if no_tags:
        tag_opt = "none"
    elif tags:
        tag_opt = "all"

    # Expand the "tag <name>" shorthand into refs/tags/<name>:refs/tags/<name>.
    expanded_specs = []
    j = 0
    while j < len(spec_args):
        if spec_args[j] == "tag" and j + 1 < len(spec_args):
            nm = spec_args[j + 1]
            expanded_specs.append(f"refs/tags/{nm}:refs/tags/{nm}")
            j += 2
        else:
            expanded_specs.append(spec_args[j])
            j += 1
    spec_args = expanded_specs

    # Build the ref_map (builtin/fetch.c get_ref_map).  Each entry:
    #   remote: full remote refname
    #   local:  full local destination ref, or None (FETCH_HEAD display only)
    #   oid:    remote oid
    #   force:  forced update
    #   fhs:    fetch-head status "merge" / "not-for-merge" / "ignore"
    ref_map = []
    opp_entries = []   # opportunistic orefs, appended after tags (get_ref_map)
    if spec_args:
        # Command-line refspecs -> FETCH_HEAD_MERGE.
        for raw in spec_args:
            rs = lt.Refspec(raw)
            src = rs.src
            if src is None:
                continue
            matched = _match_remote_src(remote_refs, src)
            for mref, moid in matched:
                dst = _expand_fetch_dst(rs.dst, mref) if rs.dst else None
                ref_map.append(dict(remote=mref, local=dst, oid=moid,
                                    force=rs.force or force, fhs="merge"))
        # Opportunistic remote-tracking updates from the configured fetch
        # refspec (or --refmap); FETCH_HEAD_IGNORE, appended after tags.
        opp_specs = refmap if refmap else fetch_rs
        for raw in opp_specs:
            rs = lt.Refspec(raw)
            if not (rs.pattern and rs.src and rs.dst):
                continue
            prefix = rs.src[:-1]; dprefix = rs.dst[:-1]
            for u in list(ref_map):
                mref = u["remote"]
                if u["local"] is not None:
                    continue
                if mref.startswith(prefix):
                    local = dprefix + mref[len(prefix):]
                    if any(o["remote"] == mref and o["local"] == local for o in ref_map):
                        continue
                    opp_entries.append(dict(remote=mref, local=local,
                                            oid=remote_refs[mref],
                                            force=rs.force or force, fhs="ignore"))
    elif not fetch_rs:
        # No refspecs at all (bare URL with no configured fetch): fetch HEAD.
        # get_remote_ref(remote_refs, "HEAD") — die if HEAD is unresolvable.
        head_target = lt.remote_head_target(remote)
        head_oid = None
        if head_target and head_target in remote_refs:
            head_oid = remote_refs[head_target]
        elif "HEAD" in remote_refs:
            head_oid = remote_refs["HEAD"]
        if head_oid is None:
            _err("fatal: couldn't find remote ref HEAD")
            return 128
        ref_map.append(dict(remote="HEAD", local=None, oid=head_oid,
                            force=force, fhs="merge"))
    else:
        for raw in fetch_rs:
            rs = lt.Refspec(raw)
            if rs.pattern and rs.src and rs.dst:
                prefix = rs.src[:-1]; dprefix = rs.dst[:-1]
                for mref in sorted(remote_refs):
                    if mref.startswith(prefix):
                        local = dprefix + mref[len(prefix):]
                        ref_map.append(dict(remote=mref, local=local,
                                            oid=remote_refs[mref],
                                            force=rs.force or force,
                                            fhs="not-for-merge"))
            elif rs.src:
                matched = _match_remote_src(remote_refs, rs.src)
                for mref, moid in matched:
                    dst = _expand_fetch_dst(rs.dst, mref) if rs.dst else None
                    ref_map.append(dict(remote=mref, local=dst, oid=moid,
                                        force=rs.force or force,
                                        fhs="not-for-merge"))
        # branch.<current>.merge tip is FETCH_HEAD_MERGE.
        head_sym, _ = refs_mod.read_head(repo)
        cur_branch = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else None
        merge_ref = gitconfig.get(repo, f"branch.{cur_branch}.merge") if cur_branch else None
        bremote = gitconfig.get(repo, f"branch.{cur_branch}.remote") if cur_branch else None
        if merge_ref and bremote == remote_name:
            for u in ref_map:
                if u["remote"] == merge_ref:
                    u["fhs"] = "merge"

    # Tag following.
    if tag_opt == "all":
        for mref in sorted(remote_refs):
            if mref.startswith("refs/tags/") and not any(u["remote"] == mref for u in ref_map):
                ref_map.append(dict(remote=mref, local=mref, oid=remote_refs[mref],
                                    force=force, fhs="not-for-merge"))
    elif tag_opt == "follow":
        # find_non_local_tags(): auto-follow tags that point at objects we are
        # fetching and that are NOT already present locally (same oid).
        wanted = {u["oid"] for u in ref_map}
        local_all = refs_mod.iter_all_refs(repo)
        for mref in sorted(remote_refs):
            if not mref.startswith("refs/tags/"):
                continue
            if any(u["remote"] == mref for u in ref_map):
                continue
            toid = remote_refs[mref]
            if local_all.get(mref) == toid:
                continue  # already have this tag at this oid
            if toid in wanted or _peel_remote(remote, toid) in wanted:
                ref_map.append(dict(remote=mref, local=mref, oid=toid,
                                    force=force, fhs="not-for-merge",
                                    autotag=True))

    # Opportunistic ref updates are appended last (get_ref_map orders these
    # after the tags so duplicate-removal keeps the not-for-merge tag entry).
    ref_map.extend(opp_entries)

    # Transfer objects for all wanted oids.
    have = lt.destination_have(repo)
    wanted_tips = [u["oid"] for u in ref_map]
    if wanted_tips and not dry_run:
        lt.copy_objects(remote, repo, wanted_tips, have)

    # Compute display rows + apply ref updates.
    rows = []
    fetch_head_entries = []
    failed = False
    for u in ref_map:
        remote_ref = u["remote"]; local = u["local"]; new = u["oid"]
        # FETCH_HEAD entry (skip ignore/ duplicates).
        if u["fhs"] in ("merge", "not-for-merge"):
            fetch_head_entries.append((remote_ref, new, u["fhs"] == "merge"))
        if local is None:
            # FETCH_HEAD-only display row.
            if remote_ref.startswith("refs/heads/"):
                summ = "branch"
            elif remote_ref.startswith("refs/tags/"):
                summ = "tag"
            elif remote_ref.startswith("refs/remotes/"):
                summ = "remote-tracking branch"
            else:
                summ = "branch"
            rows.append(dict(remote=remote_ref, local="FETCH_HEAD",
                             old=repo.null_oid(), new=new, uptodate=False,
                             code="*", summary=summ, msg=None, peer=False))
            continue
        old = refs_mod.read_ref(repo, local)
        row = dict(remote=remote_ref, local=local,
                   old=old or repo.null_oid(), new=new, uptodate=False,
                   code=None, summary=None, msg=None, peer=True,
                   autotag=u.get("autotag", False))
        if old == new:
            row["uptodate"] = True
            row["code"] = "="; row["summary"] = "[up to date]"
        elif old is None:
            if remote_ref.startswith("refs/tags/") or local.startswith("refs/tags/"):
                row["code"] = "*"; row["summary"] = "[new tag]"
            elif remote_ref.startswith("refs/heads/"):
                row["code"] = "*"; row["summary"] = "[new branch]"
            else:
                row["code"] = "*"; row["summary"] = "[new ref]"
            if not dry_run:
                refs_mod.update_ref(repo, local, new)
        else:
            if local.startswith("refs/tags/"):
                if u["force"]:
                    row["code"] = "t"; row["summary"] = "[tag update]"
                    if not dry_run:
                        refs_mod.update_ref(repo, local, new)
                else:
                    row["code"] = "!"; row["summary"] = "[rejected]"
                    row["msg"] = "would clobber existing tag"
                    failed = True
            else:
                ff = _is_fast_forward(repo, remote, old, new)
                if ff:
                    row["code"] = " "
                    row["summary"] = "%s..%s" % (_abbrev(old), _abbrev(new))
                    if not dry_run:
                        refs_mod.update_ref(repo, local, new)
                elif u["force"]:
                    row["code"] = "+"
                    row["summary"] = "%s...%s" % (_abbrev(old), _abbrev(new))
                    row["msg"] = "forced update"
                    if not dry_run:
                        refs_mod.update_ref(repo, local, new)
                else:
                    row["code"] = "!"
                    row["summary"] = "%s...%s" % (_abbrev(old), _abbrev(new))
                    row["msg"] = "(non-fast-forward)"
                    failed = True
        rows.append(row)

    # builtin/fetch.c: after the main store, do_fetch runs find_non_local_tags +
    # backfill_tags a SECOND time.  In a real fetch the tags are now local so
    # nothing is re-displayed, but under --dry-run the transaction never wrote
    # them, so the auto-followed tag rows are displayed again.
    if dry_run:
        dup = [dict(r) for r in rows if r.get("autotag")]
        rows.extend(dup)

    # Prune.
    prune_rows = []
    if prune:
        prune_rows = _compute_prune(repo, remote_name, fetch_rs, remote_refs,
                                    spec_args, dry_run)

    # Write FETCH_HEAD (append=add).
    if write_fetch_head and not dry_run:
        _write_fetch_head_file(repo, fetch_head_entries, url_disp, append)

    # --set-upstream: builtin/fetch.c picks the single ref_map entry with no
    # local peer (the FETCH_HEAD-merge source) as the upstream; with none such,
    # it warns "no source branch found".  Multiple such entries are ambiguous.
    if set_upstream:
        sources = [u for u in ref_map if u["local"] is None]
        if len(sources) > 1:
            _err("warning: multiple branches detected, incompatible with --set-upstream")
        elif len(sources) == 1:
            src_ref = sources[0]["remote"]
            head_sym, _ = refs_mod.read_head(repo)
            cur = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else None
            if cur is None:
                short = src_ref[len("refs/heads/"):] if src_ref.startswith("refs/heads/") else src_ref
                _err(f"warning: could not set upstream of HEAD to '{short}' from "
                     f"'{remote_name}' when it does not point to any branch.")
            elif src_ref == "HEAD" or src_ref.startswith("refs/heads/"):
                if not dry_run:
                    cfg_path = repo.gitdir / "config"
                    gitconfig.write_value(cfg_path, "branch", cur, "remote", remote_name)
                    gitconfig.write_value(cfg_path, "branch", cur, "merge", src_ref)
            elif src_ref.startswith("refs/remotes/"):
                _err("warning: not setting upstream for a remote remote-tracking branch")
            elif src_ref.startswith("refs/tags/"):
                _err("warning: not setting upstream for a remote tag")
        else:
            _err("warning: no source branch found;")
            _err("you need to specify exactly one branch with the --set-upstream option")

    # Display.
    if porcelain:
        # machine-readable: "<flag> <old-oid> <new-oid> <local-ref>" per row.
        for r in rows:
            if r["uptodate"] and verbosity <= 0:
                continue
            if not r.get("peer", True):
                continue
            sys.stdout.write("%s %s %s %s\n" % (
                r["code"], r["old"], r["new"], r["local"]))
        for r in prune_rows:
            sys.stdout.write("- %s %s %s\n" % (
                r["old"], repo.null_oid(), r["local"]))
    else:
        _display_fetch(url_disp, rows, prune_rows, verbosity, failed)

    return 1 if failed else 0


def _match_remote_src(remote_refs: dict, src: str) -> list[tuple[str, str]]:
    if src in remote_refs:
        return [(src, remote_refs[src])]
    if src == "HEAD":
        return []
    out = []
    for cand in (f"refs/heads/{src}", f"refs/tags/{src}"):
        if cand in remote_refs:
            out.append((cand, remote_refs[cand]))
    if out:
        return out
    # last resort: any ref ending with /src
    for name, oid in remote_refs.items():
        if name == src:
            out.append((name, oid))
    return out


def _expand_fetch_dst(dst: str, remote_ref: str) -> str:
    if dst.startswith("refs/"):
        return dst
    if remote_ref.startswith("refs/tags/"):
        return f"refs/tags/{dst}"
    return f"refs/heads/{dst}"


def _peel_remote(remote, oid) -> str:
    from . import objects as o
    cur = oid
    for _ in range(10):
        try:
            t, data = o.read_object(remote, cur)
        except KeyError:
            return cur
        if t == "tag":
            tgt = refs_mod._tag_target(data)
            if not tgt:
                return cur
            cur = tgt
        else:
            return cur
    return cur


def _tag_points_into(remote, oid, wanted: set) -> bool:
    return _peel_remote(remote, oid) in wanted


def _compute_prune(repo, remote_name, fetch_rs, remote_refs, spec_args, dry_run):
    """Delete local tracking refs that no longer exist on the remote."""
    rows = []
    for raw in fetch_rs:
        rs_force = raw.startswith("+")
        spec = raw[1:] if rs_force else raw
        if ":" not in spec:
            continue
        src, dst = spec.split(":", 1)
        if not (src.endswith("*") and dst.endswith("*")):
            continue
        sprefix = src[:-1]; dprefix = dst[:-1]
        # current local tracking refs under dprefix
        for name, oid in sorted(refs_mod.iter_all_refs(repo).items()):
            if not name.startswith(dprefix):
                continue
            remote_equiv = sprefix + name[len(dprefix):]
            if remote_equiv not in remote_refs:
                rows.append(dict(local=name, old=oid))
                if not dry_run:
                    refs_mod.delete_ref(repo, name)
    return rows


def _write_fetch_head_file(repo, entries, url_disp, append) -> None:
    lines = []
    for remote_ref, oid, merge in entries:
        marker = "" if merge else "not-for-merge"
        note = _fetch_head_note(remote_ref, url_disp)
        lines.append(f"{oid}\t{marker}\t{note}\n")
    path = repo.gitdir / "FETCH_HEAD"
    if append and path.exists():
        with open(path, "a", encoding="utf-8") as f:
            f.write("".join(lines))
    else:
        path.write_text("".join(lines), encoding="utf-8")


def _display_fetch(url_disp, rows, prune_rows, verbosity, failed=False) -> None:
    if verbosity < 0:
        return
    # Prune rows are displayed first (builtin/fetch.c prunes before stores).
    shown = []
    for r in prune_rows:
        shown.append(dict(remote="(none)", local=r["local"], code="-",
                          summary="[deleted]", msg=None, uptodate=False,
                          old=r["old"], new="", peer=True, prune=True))
    for r in rows:
        if r["uptodate"] and verbosity <= 0:
            continue
        shown.append(r)
    if not shown:
        return
    # builtin/fetch.c: summary_width = transport_summary_width(ref_map) only when
    # the ref transaction succeeded; if any update failed, the computation is
    # skipped and summary_width stays 0 (no padding for any row).
    if failed:
        width = 0
    else:
        width = _summary_width([(r.get("old", "0"), r.get("new", "0")) for r in rows])
    # refcol_width: skip non-peer rows (FETCH_HEAD-only) and uptodate at v<=0.
    refcol = 10
    for r in shown:
        if not r.get("peer", True):
            continue
        if verbosity <= 0 and r.get("uptodate"):
            continue
        rlen = len(_prettify_refname(r["remote"]) if r["remote"] != "(none)" else "(none)")
        if refcol < rlen:
            refcol = rlen
    out = [f"From {url_disp}"]
    for r in shown:
        code = r["code"]; summary = r["summary"]
        remote = _prettify_refname(r["remote"]) if r["remote"] != "(none)" else "(none)"
        local = _prettify_refname(r["local"])
        line = " %c %-*s " % (code, width, summary)
        line += "%-*s -> %s" % (refcol, remote, local)
        if r.get("msg"):
            msg = r["msg"]
            line += ("  " + msg) if msg.startswith("(") else ("  (%s)" % msg)
        out.append(line)
    sys.stderr.write("\n".join(out) + "\n")


_MERGE_TREE_USAGE = (
    "usage: git merge-tree [--write-tree] [<options>] <branch1> <branch2>\n"
    "   or: git merge-tree [--trivial-merge] <base-tree> <branch1> <branch2>\n"
    "\n"
    "    --write-tree          do a real merge instead of a trivial merge\n"
    "    --trivial-merge       do a trivial merge only\n"
    "    --[no-]messages       also show informational/conflict messages\n"
    "    --quiet               suppress all output; only exit status wanted\n"
    "    -z                    separate paths with the NUL character\n"
    "    --name-only           list filenames without modes/oids/stages\n"
    "    --allow-unrelated-histories\n"
    "                          allow merging unrelated histories\n"
    "    --stdin               perform multiple merges, one per line of input\n"
    "    --[no-]merge-base <tree-ish>\n"
    "                          specify a merge-base for the merge\n"
    "    -X, --[no-]strategy-option <option=value>\n"
    "                          option for selected merge strategy\n"
    "\n"
)


def _mt_quote_c_style(path: str) -> bytes:
    """Mirror git's quote_c_style(): emit a C-quoted, double-quoted string when
    the name contains a control/high/special byte, else the raw bytes.  Used
    for the merge-tree info section under the newline terminator."""
    raw = path.encode("utf-8", "surrogateescape")
    sq = {ord('"'): b'\\"', ord("\\"): b"\\\\", ord("\a"): b"\\a",
          ord("\b"): b"\\b", ord("\f"): b"\\f", ord("\n"): b"\\n",
          ord("\r"): b"\\r", ord("\t"): b"\\t", ord("\v"): b"\\v"}
    needs = False
    out = bytearray()
    for byte in raw:
        if byte in sq:
            out += sq[byte]
            needs = True
        elif byte < 0x20 or byte >= 0x80:
            out += b"\\%03o" % byte
            needs = True
        else:
            out.append(byte)
    if not needs:
        return raw
    return b'"' + bytes(out) + b'"'


def _mt_real_merge(repo, merge_base, branch1, branch2, opts) -> int:
    """Perform a real (ort) merge for ``merge-tree`` and emit git's output.

    ``opts`` carries: name_only, quiet, show_messages (-1/0/1), z (NUL term),
    use_stdin, allow_unrelated, favor, rename_detection.
    Returns git's exit status (!clean), or 128/1 on errors."""
    from . import ort as ort_mod
    from . import merge as merge_mod

    z = opts["z"]
    term = b"\0" if z else b"\n"
    out = opts.get("_out") or sys.stdout.buffer

    def _resolve_commit(name):
        sha = refs_mod.rev_parse(repo, name)
        if sha is None:
            return None
        try:
            t, _data = objs.read_object(repo, sha)
        except KeyError:
            return None
        if t not in ("commit", "tag"):
            return None
        return sha

    # _build_config only reads repo config/attributes; the tree arguments are
    # unused, so empty placeholders are fine here.
    cfg = ort_mod._build_config(repo, "", "", "")
    cfg.variant = opts["favor"]
    cfg.rename_detection = opts["rename_detection"]

    if merge_base is not None:
        # Explicit merge base: a non-recursive 3-way merge of the trees.
        # git peels each of base/branch1/branch2 to a tree, dying with the
        # offending name if any cannot be parsed.
        for nm in (merge_base, branch1, branch2):
            try:
                ort_mod._peel_to_tree(repo, nm)
            except (ValueError, KeyError):
                _err(f"fatal: could not parse as tree '{nm}'")
                return 128
        res = ort_mod.merge_tree(repo, merge_base, branch1, branch2, cfg=cfg)
    else:
        one = _resolve_commit(branch1)
        if one is None:
            _err(f"merge-tree: {branch1} - not something we can merge")
            return 1
        two = _resolve_commit(branch2)
        if two is None:
            _err(f"merge-tree: {branch2} - not something we can merge")
            return 1
        bases = merge_mod.merge_bases(repo, one, two)
        if not bases and not opts["allow_unrelated"]:
            _err("fatal: refusing to merge unrelated histories")
            return 128
        # Pass the original ref names so conflict-marker labels match git
        # (opt.branch1/branch2 become the "<<<<<<< name" markers).
        res = ort_mod.merge_commits(repo, branch1, branch2, cfg=cfg,
                                    allow_unrelated=True, favor=opts["favor"])

    clean = res.clean
    show_messages = opts["show_messages"]
    if show_messages == -1:
        show_messages = 0 if clean else 1

    if opts["use_stdin"]:
        out.write(b"%d" % (1 if clean else 0))
        out.write(term)
    out.write(res.tree.encode())
    out.write(term)

    if not clean:
        # Info section: one record per (path, stage) in path/stage order.
        entries = []
        if res.conflict_index is not None:
            for e in res.conflict_index.entries:
                if getattr(e, "stage", 0):
                    entries.append((e.path, e.stage, e.mode, e.sha))
        entries.sort(key=lambda t: (t[0], t[1]))
        last = None
        for path, stage, mode, sha in entries:
            if not opts["name_only"]:
                out.write(b"%06o %s %d\t" % (mode, sha.encode(), stage))
            elif last is not None and last == path:
                continue
            if z:
                out.write(path.encode("utf-8", "surrogateescape"))
            else:
                out.write(_mt_quote_c_style(path))
            out.write(term)
            last = path

    if show_messages:
        out.write(term)
        # Messages: sorted by path, then in recording order within each path.
        for _primary, type_str, message, paths in res.messages:
            if z:
                out.write(b"%d" % len(paths))
                out.write(b"\0")
                for p in paths:
                    out.write(p.encode("utf-8", "surrogateescape"))
                    out.write(b"\0")
                out.write(type_str.encode())
                out.write(b"\0")
            out.write(message.encode("utf-8", "surrogateescape"))
            out.write(b"\n")
            if z:
                out.write(b"\0")

    if opts["use_stdin"]:
        out.write(term)
    out.flush()
    return 0 if clean else 1


def cmd_merge_tree(argv: list[str]) -> int:
    repo = _repo()

    # Manual option parsing mirroring builtin/merge-tree.c's parse-options.
    mode = None            # None / "real" / "trivial"
    name_only = False
    quiet = False
    show_messages = -1     # -1 = auto (!clean), 0 = off, 1 = on
    z = False
    use_stdin = False
    allow_unrelated = False
    merge_base = None
    favor = 0              # 0 / FAVOR_OURS / FAVOR_THEIRS
    rename_detection = True
    xopts: list[str] = []
    pos: list[str] = []

    from . import xdiff as _xd

    def usage(code=129):
        sys.stderr.write(_MERGE_TREE_USAGE)
        return code

    def unknown(opt):
        # parse-options prints "error: unknown switch `x'" for short options and
        # "error: unknown option `name'" for long options, then the usage.
        if opt.startswith("--"):
            sys.stderr.write(f"error: unknown option `{opt[2:]}'\n")
        else:
            sys.stderr.write(f"error: unknown switch `{opt[1:]}'\n")
        sys.stderr.write(_MERGE_TREE_USAGE)
        return 129

    i = 0
    n = len(argv)
    while i < n:
        a = argv[i]
        if a == "--":
            pos.extend(argv[i + 1:])
            break
        elif a == "--write-tree":
            mode = "real"
        elif a == "--trivial-merge":
            mode = "trivial"
        elif a == "--name-only":
            name_only = True
        elif a == "--quiet":
            quiet = True
        elif a == "--messages":
            show_messages = 1
        elif a == "--no-messages":
            show_messages = 0
        elif a == "-z":
            z = True
        elif a == "--stdin":
            use_stdin = True
        elif a == "--allow-unrelated-histories":
            allow_unrelated = True
        elif a == "--no-allow-unrelated-histories":
            allow_unrelated = False
        elif a == "--no-merge-base":
            merge_base = None
        elif a == "--merge-base":
            i += 1
            if i >= n:
                return usage()
            merge_base = argv[i]
        elif a.startswith("--merge-base="):
            merge_base = a.split("=", 1)[1]
        elif a == "-X" or a == "--strategy-option":
            i += 1
            if i >= n:
                return usage()
            xopts.append(argv[i])
        elif a.startswith("-X"):
            xopts.append(a[2:])
        elif a.startswith("--strategy-option="):
            xopts.append(a.split("=", 1)[1])
        elif a.startswith("-") and a != "-":
            # Split a stacked short cluster's first switch for the error
            # message (git reports the first unknown short switch).
            if not a.startswith("--") and len(a) > 2:
                return unknown("-" + a[1])
            return unknown(a)
        else:
            pos.append(a)
        i += 1

    # Apply -X strategy options (subset; defer the rest).
    for x in xopts:
        if x == "ours":
            favor = _xd.XDL_MERGE_FAVOR_OURS
        elif x == "theirs":
            favor = _xd.XDL_MERGE_FAVOR_THEIRS
        elif x == "no-renames":
            rename_detection = False
        elif x in ("find-renames", "renames"):
            rename_detection = True
        elif x == "diff-algorithm=histogram":
            pass  # histogram is the engine default
        else:
            _err(f"fatal: unknown strategy option: -X{x}")
            return 128

    # Incompatible-option checks (match git's die_for_incompatible_opt2 text).
    if quiet:
        if show_messages == 1:
            _err("fatal: options '--quiet' and '--messages' cannot be used "
                 "together")
            return 128
        if name_only:
            _err("fatal: options '--quiet' and '--name-only' cannot be used "
                 "together")
            return 128
        if use_stdin:
            _err("fatal: options '--quiet' and '--stdin' cannot be used "
                 "together")
            return 128
        if z:
            _err("fatal: options '--quiet' and '-z' cannot be used together")
            return 128
        # --quiet implies messages off; output suppressed regardless below.
        if show_messages == -1:
            show_messages = 0

    opts = dict(name_only=name_only, quiet=quiet, show_messages=show_messages,
                z=z, use_stdin=use_stdin, allow_unrelated=allow_unrelated,
                favor=favor, rename_detection=rename_detection)

    # --stdin: one merge per input line, NUL-terminated records, always rc 0.
    if use_stdin:
        if mode == "trivial":
            _err("fatal: --trivial-merge is incompatible with all other "
                 "options")
            return 128
        if merge_base is not None:
            _err("fatal: options '--merge-base' and '--stdin' cannot be used "
                 "together")
            return 128
        sopts = dict(opts)
        sopts["z"] = True
        sopts["use_stdin"] = True
        data = sys.stdin.buffer.read()
        lines = data.split(b"\n")
        if lines and lines[-1] == b"":
            lines.pop()  # trailing newline does not yield an empty line
        for line in lines:
            text = line.decode("utf-8", "surrogateescape")
            # git's string_list_split_in_place_f(" ", -1, TRIM): split on each
            # single space, then strip whitespace from each resulting token.
            parts = [p.strip() for p in text.split(" ")]
            if len(parts) < 2:
                _err(f"fatal: malformed input line: '{text}'.")
                return 128
            if len(parts) == 4 and parts[1] == "--":
                _mt_real_merge(repo, parts[0], parts[2], parts[3], sopts)
            elif len(parts) == 2:
                _mt_real_merge(repo, None, parts[0], parts[1], sopts)
            else:
                _err(f"fatal: malformed input line: '{text}'.")
                return 128
        return 0

    # Decide mode for the non-stdin case (matches git's MODE_UNKNOWN logic).
    if mode is None:
        if len(pos) == 2:
            mode = "real"
        elif len(pos) == 3:
            mode = "trivial"
        else:
            return usage()
    if mode == "real" and len(pos) != 2:
        return usage()
    if mode == "trivial" and len(pos) != 3:
        return usage()

    if mode == "real":
        if quiet:
            # Suppress stdout; only the exit status matters.
            import io
            opts["_out"] = io.BytesIO()
        return _mt_real_merge(repo, merge_base, pos[0], pos[1], opts)

    # Trivial-merge form (legacy `git merge-tree <base> <branch1> <branch2>`):
    # a faithful port of builtin/merge-tree.c's three-way lock-step tree walk.
    return _merge_tree_trivial(repo, pos[0], pos[1], pos[2])


def _merge_tree_trivial(repo: Repository, base: str, branch1: str,
                        branch2: str) -> int:
    """Port of builtin/merge-tree.c trivial_merge(): walk base/ours/theirs
    trees in lock-step and print the unmerged/taken-from-theirs entries with the
    'explanation' header, the per-stage '  <desc> <mode> <oid> <path>' lines,
    and a unified diff of origin (ours) vs result."""

    def tree_of(rev):
        s = refs_mod.rev_parse(repo, rev)
        if not s:
            sys.stderr.write(f"unknown rev {rev}\n")
            return None
        t, data = objs.read_object(repo, s)
        if t == "commit":
            return objs.parse_commit(data).tree
        if t == "tag":
            return refs_mod._peel_to_type(repo, s, "tree")
        if t == "tree":
            return s
        sys.stderr.write(f"{rev} is not a tree\n")
        return None

    bt = tree_of(base)
    ot = tree_of(branch1)
    tt = tree_of(branch2)
    if bt is None or ot is None or tt is None:
        return 128

    NULL = "0" * 40
    DESC = {0: "result", 1: "base", 2: "our", 3: "their"}

    # A merge_list entry is a dict: stage, mode(int), oid, path, link(next).
    merge_result: list[dict] = []

    def read_tree_map(tree_sha):
        """name -> (mode_str, sha) for one tree level (non-recursive)."""
        out = {}
        _t, data = objs.read_object(repo, tree_sha)
        for e in objs.parse_tree(data):
            out[e.name] = (e.mode, e.sha)
        return out

    def is_dir(mode):
        return mode in ("40000", "040000")

    def same(a, b):
        # same_entry: both non-null, equal oid and mode.
        if a is None or b is None:
            return False
        am, aoid = a
        bm, boid = b
        return aoid != NULL and boid != NULL and aoid == boid and am == bm

    def both_empty(a, b):
        ae = a is None
        be = b is None
        return ae and be

    def create_entry(stage, mode, oid, path):
        return {"stage": stage, "mode": int(mode, 8) if mode else 0,
                "oid": oid, "path": path, "link": None}

    def resolve(ours, result_entry, path):
        # resolve(info, ours, result): only emitted when 'ours' is present.
        if ours is None:
            return
        final = create_entry(0, result_entry[0], result_entry[1], path)
        orig = create_entry(2, ours[0], ours[1], path)
        final["link"] = orig
        merge_result.append(final)

    def walk(base_map_tree, our_tree, their_tree, prefix):
        bm = read_tree_map(base_map_tree) if base_map_tree else {}
        om = read_tree_map(our_tree) if our_tree else {}
        tm = read_tree_map(their_tree) if their_tree else {}
        # Walk all names in git's tree order (directories sort with a trailing
        # '/').  Sorting on (name + ('/' if dir)) reproduces base_name_compare
        # closely enough for non-conflicting/typical inputs.
        def sort_key(name):
            md = None
            for mp in (bm, om, tm):
                if name in mp:
                    md = mp[name][0]
                    break
            return name + ("/" if md and is_dir(md) else "")
        names = sorted(set(bm) | set(om) | set(tm), key=sort_key)
        for name in names:
            path = (prefix + "/" + name) if prefix else name
            b = bm.get(name)
            o = om.get(name)
            t = tm.get(name)
            b_dir = b is not None and is_dir(b[0])
            o_dir = o is not None and is_dir(o[0])
            t_dir = t is not None and is_dir(t[0])
            # threeway_callback: same in both / both empty -> take ours (hidden).
            if same(o, t) or both_empty(o, t):
                resolve(None, o, path)
                continue
            if same(b, o):
                if t is not None and not t_dir:
                    # we did not touch, they modified -- take theirs (shown).
                    resolve(o, t, path)
                    continue
                # fall through to unresolved (dir/file transition recurses).
            if same(b, t) or both_empty(b, t):
                resolve(None, o, path)
                continue
            # unresolved(): recurse into any directory level, then emit the
            # non-directory stage entries.
            mask = 0b111
            dirmask = 0
            for i, (e, d) in enumerate(((b, b_dir), (o, o_dir), (t, t_dir))):
                if e is None or d:
                    dirmask |= (1 << i)
            walk(b[1] if b_dir else None,
                 o[1] if o_dir else None,
                 t[1] if t_dir else None,
                 path) if (b_dir or o_dir or t_dir) else None
            if dirmask == mask:
                continue
            entry = None
            if t is not None and not t_dir:
                link = create_entry(3, t[0], t[1], path)
                link["link"] = entry
                entry = link
            if o is not None and not o_dir:
                link = create_entry(2, o[0], o[1], path)
                link["link"] = entry
                entry = link
            if b is not None and not b_dir:
                link = create_entry(1, b[0], b[1], path)
                link["link"] = entry
                entry = link
            if entry is not None:
                merge_result.append(entry)

    walk(bt, ot, tt, "")

    def explanation(entry):
        st = entry["stage"]
        if st == 0:
            return "merged"
        if st == 3:
            return "added in remote"
        if st == 2:
            return "added in both" if entry["link"] else "added in local"
        # Existed in base (stage 1).
        link = entry["link"]
        if not link:
            return "removed in both"
        if link["link"]:
            return "changed in both"
        return "removed in local" if link["stage"] == 3 else "removed in remote"

    def blob_bytes(oid):
        try:
            t, data = objs.read_object(repo, oid)
        except KeyError:
            return b""
        return data if t == "blob" else b""

    def origin_bytes(entry):
        e = entry
        while e is not None:
            if e["stage"] == 2:
                return blob_bytes(e["oid"])
            e = e["link"]
        return None

    def result_bytes(entry):
        if entry["stage"] == 0:
            return blob_bytes(entry["oid"])
        base = our = their = None
        e = entry
        if e["stage"] == 1:
            base = e["oid"]; e = e["link"]
        if e is not None and e["stage"] == 2:
            our = e["oid"]; e = e["link"]
        if e is not None:
            their = e["oid"]
        # merge_blobs(): a removed side -> NULL unless base present; otherwise a
        # 3-way file merge.
        if our is None or their is None:
            if base is not None:
                return None
            side = our if our is not None else their
            return blob_bytes(side) if side is not None else None
        from . import xdiff as _xd
        oursb = blob_bytes(our)
        theirsb = blob_bytes(their)
        baseb = blob_bytes(base) if base is not None else b""
        # merge-blobs.c three_way_filemerge: labels ".our"/".their", no
        # ancestor label (cmd_merge_tree ignores merge.conflictstyle).
        merged, _confl = _xd.xdl_merge(baseb, oursb, theirsb,
                                       ancestor_name=None,
                                       name1=".our", name2=".their")
        return merged

    out_lines: list[str] = []
    for entry in merge_result:
        out_lines.append(explanation(entry))
        e = entry
        while e is not None:
            out_lines.append(f"  {DESC[e['stage']]:<6} {e['mode']:o} "
                             f"{e['oid']} {e['path']}")
            e = e["link"]
        # show_diff: unified diff of origin (ours) vs result, ctxlen 3, no
        # file header — just the @@ hunks.
        src = origin_bytes(entry)
        dst = result_bytes(entry)
        src_t = (src or b"").decode("utf-8", "replace")
        dst_t = (dst or b"").decode("utf-8", "replace")
        body = diff_mod.format_hunks(
            src_t.splitlines(), dst_t.splitlines(), 3,
            a_no_newline=bool(src_t) and not src_t.endswith("\n"),
            b_no_newline=bool(dst_t) and not dst_t.endswith("\n"))
        out_lines.extend(body)
    sys.stdout.write("".join(l + "\n" for l in out_lines))
    return 0


# register
def _register_phase2() -> None:
    _COMMANDS["merge-base"] = cmd_merge_base
    _COMMANDS["merge"] = cmd_merge
    _COMMANDS["merge-tree"] = cmd_merge_tree
    _COMMANDS["cherry-pick"] = cmd_cherry_pick
    _COMMANDS["revert"] = cmd_revert
    _COMMANDS["rebase"] = cmd_rebase
    _COMMANDS["reflog"] = cmd_reflog
    _COMMANDS["stash"] = cmd_stash
    _COMMANDS["fetch"] = cmd_fetch
    _COMMANDS["push"] = cmd_push


_register_phase2()


# ---------------------------------------------------------------------------
# Phase 3 — apply / format-patch / am / clean / describe / blame /
#           for-each-ref / shortlog / archive / bundle / show-ref /
#           mktree / update-index / check-ignore


def _apply_target(fp) -> str:
    """The path a parsed apply.Patch operates on (for stat/numstat/summary)."""
    return fp.new_name if fp.new_name else (fp.old_name or fp.def_name or "")


def _apply_build_fake_ancestor(repo, patches, dest: str) -> int:
    """Port of apply.c build_fake_ancestor(): build a temporary index from each
    patch's embedded "index <old>.." blob id and write it to <dest>."""
    from . import index as index_mod
    result = index_mod.Index()
    for patch in patches:
        name = patch.old_name if patch.old_name else patch.new_name
        if patch.is_new > 0:
            continue
        # repo_get_oid_blob: the abbreviated id must resolve to an existing blob.
        oid = None
        full = refs_mod.rev_parse(repo, patch.old_oid_prefix) if patch.old_oid_prefix else None
        if full is not None:
            try:
                t, _ = objs.read_object(repo, full)
            except (KeyError, ValueError):
                t = None
            if t == "blob":
                oid = full
        if oid is None:
            if not patch.lines_added and not patch.lines_deleted:
                # Mode-only change: take the blob from the current HEAD.
                head = refs_mod.rev_parse(repo, "HEAD:" + (patch.old_name or "")) \
                    if patch.old_name else None
                if head is None:
                    _err(f"error: mode change for {name}, which is not in current HEAD")
                    return 128
                oid = head
            else:
                _err(f"error: sha1 information is lacking or useless ({name}).")
                return 128
        e = index_mod.IndexEntry()
        e.mode = patch.old_mode if patch.old_mode else 0o100644
        e.sha = oid
        e.path = name
        result.entries.append(e)
    data = index_mod.serialize_index(repo, result)
    tmp = dest + ".lock"
    with open(tmp, "wb") as fh:
        fh.write(data)
    os.replace(tmp, dest)
    return 0


def cmd_apply(argv: list[str]) -> int:
    from . import apply as apply_mod

    ap = argparse.ArgumentParser(prog="pygit apply", add_help=False)
    ap.add_argument("-R", "--reverse", action="store_true")
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--stat", action="store_true")
    ap.add_argument("--numstat", action="store_true")
    ap.add_argument("--summary", action="store_true")
    ap.add_argument("--exclude", action="append", default=None)
    ap.add_argument("--include", action="append", default=None)
    ap.add_argument("-v", "--verbose", action="count", default=0)
    ap.add_argument("-q", "--quiet", action="store_true")
    # path strip / context / merge family
    ap.add_argument("-p", dest="p_value", type=int, default=None)
    ap.add_argument("-C", dest="p_context", type=int, default=None)
    # OPT_BOOL(0, "no-add", &state->no_add) in apply.c: --add is the positive
    # form (the default — keep added lines), --no-add ignores additions.
    ap.add_argument("--no-add", dest="no_add", action="store_true", default=False)
    ap.add_argument("--add", dest="no_add", action="store_false")
    ap.add_argument("--unidiff-zero", dest="unidiff_zero", action="store_true")
    ap.add_argument("--allow-overlap", dest="allow_overlap", action="store_true")
    ap.add_argument("-z", dest="nul", action="store_true")
    ap.add_argument("--recount", dest="recount", action="store_true")
    ap.add_argument("-N", "--intent-to-add", dest="ita", action="store_true")
    ap.add_argument("--index", dest="index", action="store_true")
    ap.add_argument("--cached", dest="cached", action="store_true")
    ap.add_argument("-3", "--3way", dest="threeway", action="store_true")
    ap.add_argument("--ours", dest="favor", action="store_const", const=1)
    ap.add_argument("--theirs", dest="favor", action="store_const", const=2)
    ap.add_argument("--union", dest="favor", action="store_const", const=3)
    ap.add_argument("--apply", dest="force_apply", action="store_true")
    ap.add_argument("--allow-empty", dest="allow_empty", action="store_true")
    ap.add_argument("--whitespace", dest="whitespace", default=None)
    ap.add_argument("--reject", dest="reject", action="store_true")
    # Historical no-op flags (apply.c OPT_NOOP_NOARG): accepted and ignored.
    ap.add_argument("--binary", dest="_noop_binary", action="store_true")
    ap.add_argument("--allow-binary-replacement", dest="_noop_abr", action="store_true")
    # apply.c OPT_BOOL_F unsafe-paths: accept (pygit does not enforce the
    # outside-worktree safety check, so this is effectively a parse-only flag).
    ap.add_argument("--unsafe-paths", dest="unsafe_paths", action="store_true")
    ap.add_argument("--no-unsafe-paths", dest="unsafe_paths", action="store_false")
    # apply.c OPT_CALLBACK_F ignore-whitespace / ignore-space-change
    # (PARSE_OPT_NOARG, callback sets ws_ignore_action). Both spellings set the
    # same state; the auto-generated --no- forms reset it.
    ap.add_argument("--ignore-whitespace", dest="ws_ignore", action="store_true")
    ap.add_argument("--ignore-space-change", dest="ws_ignore", action="store_true")
    ap.add_argument("--no-ignore-whitespace", dest="ws_ignore", action="store_false")
    ap.add_argument("--no-ignore-space-change", dest="ws_ignore", action="store_false")
    # apply.c OPT_BIT inaccurate-eof: relax EOF newline matching.
    ap.add_argument("--inaccurate-eof", dest="inaccurate_eof", action="store_true")
    ap.add_argument("--no-inaccurate-eof", dest="inaccurate_eof", action="store_false")
    # apply.c OPT_CALLBACK directory=<root>: prepend <root> to all filenames.
    ap.add_argument("--directory", dest="directory", default=None)
    # apply.c OPT_FILENAME build-fake-ancestor=<file>.
    ap.add_argument("--build-fake-ancestor", dest="fake_ancestor", default=None)
    # parse-options auto-negations for the OPT_BOOL/OPT_BIT flags above. These
    # set the corresponding boolean to its negated (default) value.
    ap.add_argument("--no-reject", dest="reject", action="store_false")
    ap.add_argument("--no-stat", dest="stat", action="store_false")
    ap.add_argument("--no-numstat", dest="numstat", action="store_false")
    ap.add_argument("--no-summary", dest="summary", action="store_false")
    ap.add_argument("--no-check", dest="check", action="store_false")
    ap.add_argument("--no-index", dest="index", action="store_false")
    ap.add_argument("--no-cached", dest="cached", action="store_false")
    ap.add_argument("--no-intent-to-add", dest="ita", action="store_false")
    ap.add_argument("--no-apply", dest="force_apply", action="store_false")
    ap.add_argument("--no-3way", dest="threeway", action="store_false")
    ap.add_argument("--no-reverse", dest="reverse", action="store_false")
    ap.add_argument("--no-unidiff-zero", dest="unidiff_zero", action="store_false")
    ap.add_argument("--no-allow-overlap", dest="allow_overlap", action="store_false")
    ap.add_argument("--no-recount", dest="recount", action="store_false")
    ap.add_argument("--no-allow-empty", dest="allow_empty", action="store_false")
    ap.add_argument("--no-no-add", dest="no_add", action="store_false")
    ap.add_argument("file", nargs="?")
    args = ap.parse_args(argv)
    repo = _repo()

    # Capture include/exclude rules in their command-line order: apply.c keeps a
    # single ordered limit_by_name list and uses the FIRST matching rule, so the
    # separate argparse lists (which lose interleaving) cannot drive use_patch().
    limit_by_name = []   # list of (pattern, is_include)
    has_include = False
    j = 0
    while j < len(argv):
        tok = argv[j]
        for opt, inc in (("--include", True), ("--exclude", False)):
            if tok == opt:
                if j + 1 < len(argv):
                    limit_by_name.append((argv[j + 1], inc))
                    has_include = has_include or inc
                j += 1
                break
            if tok.startswith(opt + "="):
                limit_by_name.append((tok[len(opt) + 1:], inc))
                has_include = has_include or inc
                break
        j += 1

    favor = args.favor or 0
    if favor and not args.threeway:
        _err("fatal: --ours, --theirs, and --union require --3way")
        return 128

    # parse_whitespace_option(): reject unknown actions before reading the patch.
    if args.whitespace is not None and args.whitespace not in (
            "warn", "nowarn", "error", "error-all", "strip", "fix"):
        _err(f"error: unrecognized whitespace option '{args.whitespace}'")
        return 129

    pif = args.file if args.file else "<stdin>"
    if not args.file:
        text = sys.stdin.buffer.read()
    else:
        # apply.c opens the file (error: can't open patch ...) then reads it
        # (error: failed to read patch ...); a directory opens fine but fails to
        # read with EISDIR, so the two failures use different messages.
        try:
            fd = os.open(args.file, os.O_RDONLY)
        except OSError as exc:
            _err(f"error: can't open patch '{args.file}': {exc.strerror}")
            return 128
        try:
            chunks = []
            while True:
                b = os.read(fd, 65536)
                if not b:
                    break
                chunks.append(b)
            text = b"".join(chunks)
        except OSError as exc:
            _err(f"error: failed to read patch: {exc.strerror}")
            os.close(fd)
            return 128
        os.close(fd)
    try:
        patches = apply_mod.parse_patches(text, args.p_value, patch_input_file=pif,
                                          recount=args.recount)
    except apply_mod.ApplyError as exc:
        _err(exc.message)
        return exc.rc

    # --directory=<root>: prepend <root>/ to every filename (apply.c applies
    # state->root inside find_name during parsing; we equivalently prefix the
    # resolved names). The root is path-normalized and slash-terminated.
    if args.directory is not None:
        root = os.path.normpath(args.directory)
        if root in (".", ""):
            root = ""
        else:
            root = root.replace(os.sep, "/").rstrip("/") + "/"
        if root:
            for fp in patches:
                if fp.old_name is not None:
                    fp.old_name = root + fp.old_name
                if fp.new_name is not None:
                    fp.new_name = root + fp.new_name
                if fp.def_name is not None:
                    fp.def_name = root + fp.def_name

    # reverse_patches() runs right after parsing, before any check/apply, so the
    # rest of the pipeline treats a reversed patch as an ordinary forward one.
    if args.reverse:
        apply_mod.reverse_patches(patches)

    # --include/--exclude: walk the ordered limit_by_name list; the first rule
    # whose wildmatch() matches the pathname decides (include->use, exclude->skip).
    # A path matching no rule is used unless any --include was given.  Mirror
    # apply.c use_patch(); track skipped patches for the empty-result rule below.
    skipped_patch = 0
    if limit_by_name:
        import fnmatch as _fn

        def _use_patch(t: str) -> bool:
            for pat, inc in limit_by_name:
                if _fn.fnmatchcase(t, pat):
                    return inc
            return not has_include
        kept = []
        for fp in patches:
            if _use_patch(_apply_target(fp)):
                kept.append(fp)
            else:
                skipped_patch += 1
        patches = kept

    if not patches:
        # apply.c: the "No valid patches" error fires only when nothing was
        # parsed AND nothing was skipped by include/exclude.  If patches were
        # filtered out, applying zero patches succeeds silently.
        if args.allow_empty or skipped_patch:
            return 0
        _err('error: No valid patches in input (allow with "--allow-empty")')
        return 128

    # check_apply_state: --reject/--3way mutually exclusive (we never produce
    # rejects, so only --3way matters here); --3way and --index need a repo.
    if args.threeway and args.cached is False:
        pass
    # --3way implies check_index; --cached implies check_index; -N is cleared
    # when check_index is on (or outside a repo).
    check_index = bool(args.index or args.cached or args.threeway)
    ita_only = bool(args.ita) and not check_index

    verbosity = 1 if args.verbose else (-1 if args.quiet else 0)
    # --reject forces verbose (apply.c check_apply_state).
    if args.reject and verbosity == 0:
        verbosity = 1

    # check_apply_state: stat/numstat/summary/check (and --build-fake-ancestor)
    # turn off the actual apply unless --apply forces it.  --check never writes.
    info_mode = (args.stat or args.numstat or args.summary or args.check
                 or args.fake_ancestor is not None)
    do_apply = args.force_apply or not info_mode

    opts = apply_mod.ApplyOpts(
        p_value=args.p_value,
        no_add=args.no_add,
        reverse=args.reverse,
        unidiff_zero=args.unidiff_zero,
        p_context=(apply_mod.UINT_MAX if args.p_context is None else args.p_context),
        allow_overlap=args.allow_overlap,
        threeway=args.threeway,
        merge_variant=favor,
        cached=args.cached,
        check_index=check_index,
        ita_only=ita_only,
        check=not do_apply,
        verbosity=verbosity,
        ws_action=_apply_ws_action(args.whitespace, do_apply),
        apply_with_reject=args.reject,
        ws_ignore=bool(args.ws_ignore),
        inaccurate_eof=bool(args.inaccurate_eof),
    )
    # When applying (or --check), run the matching/apply pass first; its rc and
    # any errors take precedence.  The diffstat/numstat/summary are emitted at
    # the end, mirroring apply_patch().
    if do_apply or args.check or args.fake_ancestor is not None:
        rc = apply_mod.check_and_apply(repo, patches, opts, pif)
        if rc != 0:
            return rc
    # --build-fake-ancestor=<file>: write a temporary index built from each
    # patch's embedded "index <old>.." blob id (apply.c build_fake_ancestor).
    if args.fake_ancestor is not None:
        rc = _apply_build_fake_ancestor(repo, patches, args.fake_ancestor)
        if rc != 0:
            return rc
    if args.stat:
        _apply_emit_stat(patches)
    if args.numstat:
        _apply_emit_numstat(patches, args.nul)
    if args.summary:
        _apply_emit_summary(patches)
    return 0


def _apply_ws_action(whitespace: Optional[str], do_apply: bool) -> str:
    """Map git-apply's --whitespace=<action> to the ApplyOpts ws_action.  The
    default is 'warn' when applying and 'nowarn' otherwise (apply.c:196)."""
    if whitespace is None:
        return "warn" if do_apply else "nowarn"
    mapping = {
        "warn": "warn", "nowarn": "nowarn",
        "fix": "fix", "strip": "fix",
        "error": "error", "error-all": "error",
    }
    return mapping.get(whitespace, "warn" if do_apply else "nowarn")


def _apply_emit_summary(patches) -> None:
    for fp in patches:
        if fp.is_new > 0:
            _print(f" create mode {fp.new_mode:06o} {fp.new_name}")
        elif fp.is_delete > 0:
            _print(f" delete mode {fp.old_mode:06o} {fp.old_name}")
        elif fp.is_rename:
            _print(f" rename {fp.old_name} => {fp.new_name} (100%)")
        if fp.old_mode and fp.new_mode and fp.old_mode != fp.new_mode and not (fp.is_new > 0 or fp.is_delete > 0):
            _print(f" mode change {fp.old_mode:06o} => {fp.new_mode:06o} {fp.new_name}")


def _apply_emit_numstat(patches, nul: bool) -> None:
    sys.stdout.flush()  # keep ordering with text-layer _print output
    out = sys.stdout.buffer
    term = b"\0" if nul else b"\n"
    for fp in patches:
        name = _apply_target(fp)
        if fp.is_binary:
            out.write(b"-\t-\t")
        else:
            out.write(f"{fp.lines_added}\t{fp.lines_deleted}\t".encode())
        if nul:
            out.write(name.encode("utf-8", "surrogateescape"))
        else:
            out.write(_mt_quote_c_style(name))
        out.write(term)
    out.flush()


def _apply_emit_stat(patches) -> None:
    # Mirror apply.c show_stats(): name field is %-*s with max=min(max_len,50),
    # the change count is always %5d, and the +/- bar is scaled so name+bar<=70.
    if not patches:
        return
    rows = []  # (qname, add, del, is_binary)
    max_len = 0
    max_change = 0
    for fp in patches:
        qname = _mt_quote_c_style(_apply_target(fp)).decode("utf-8", "surrogateescape")
        rows.append((qname, fp.lines_added, fp.lines_deleted, fp.is_binary))
        if len(qname) > max_len:
            max_len = len(qname)
        if fp.lines_added + fp.lines_deleted > max_change:
            max_change = fp.lines_added + fp.lines_deleted
    name_w = min(max_len, 50)
    ti = td = 0
    nfiles = 0
    for qname, add, dele, is_binary in rows:
        nfiles += 1
        # scale filename: if longer than name_w, splice in "..."
        nm = qname
        if len(nm) > name_w:
            tail = nm[len(nm) + 3 - name_w:]
            slash = tail.find("/")
            if slash >= 0:
                nm = "..." + tail[slash:]
            else:
                nm = "..." + tail
        if is_binary:
            _print(f" {nm:<{name_w}} |  Bin")
            continue
        ti += add
        td += dele
        scale = (70 - name_w) if (name_w + max_change > 70) else max_change
        if max_change > 0:
            total = ((add + dele) * scale + max_change // 2) // max_change
            sadd = (add * scale + max_change // 2) // max_change
            sdel = total - sadd
        else:
            sadd = sdel = 0
        bar = "+" * sadd + "-" * sdel
        _print(f" {nm:<{name_w}} |{add + dele:>5} {bar}")
    _print(_stat_summary_line(nfiles, ti, td))


def cmd_format_patch(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit format-patch", add_help=False)
    ap.add_argument("-o", "--output-directory", default=".")
    ap.add_argument("--stdout", action="store_true")
    ap.add_argument("-n", "--numbered", action="store_true")
    ap.add_argument("-N", "--no-numbered", dest="no_numbered", action="store_true")
    ap.add_argument("--no-stat", dest="no_stat", action="store_true")
    ap.add_argument("-s", "--signoff", action="store_true")
    ap.add_argument("-v", "--reroll-count", dest="reroll", type=int, default=None)
    ap.add_argument("range", help="e.g. main..topic or -1 or HEAD~3")
    args = ap.parse_args(argv)
    repo = _repo()
    rng = args.range
    starts: list[str] = []
    excludes: list[str] = []
    def _ambiguous(name):
        # setup_revisions() rejects an unresolvable endpoint, naming the whole
        # argument as given on the command line.
        _err(f"fatal: ambiguous argument '{name}': unknown revision or path not in the working tree.")
        _err("Use '--' to separate paths from revisions, like this:")
        _err("'git <command> [<revision>...] -- [<file>...]'")
        return 128

    if ".." in rng:
        a, b = rng.split("..", 1)
        if a:
            ea = refs_mod.rev_parse(repo, a)
            if ea is None:
                return _ambiguous(rng)
            excludes.append(ea)
        sb = refs_mod.rev_parse(repo, b or "HEAD")
        if sb is None:
            return _ambiguous(rng)
        starts.append(sb)
    elif rng.startswith("-"):
        n = int(rng[1:])
        head = refs_mod.rev_parse(repo, "HEAD") or ""
        cur = head
        seq = []
        for _ in range(n):
            seq.append(cur)
            c = objs.parse_commit(objs.read_object(repo, cur)[1])
            if not c.parents:
                break
            cur = c.parents[0]
        c = objs.parse_commit(objs.read_object(repo, seq[-1])[1])
        if c.parents:
            excludes.append(c.parents[0])
        starts.append(head)
    else:
        # A bare <rev> means <rev>..HEAD (the commits since <rev>), like git.
        base = refs_mod.rev_parse(repo, rng)
        if base is None:
            _err(f"fatal: ambiguous argument '{rng}': unknown revision or path not in the working tree.")
            _err("Use '--' to separate paths from revisions, like this:")
            _err("'git <command> [<revision>...] -- [<file>...]'")
            return 128
        excludes.append(base)
        starts.append(refs_mod.rev_parse(repo, "HEAD") or "")

    seen = set(excludes)
    commits: list[str] = []
    stack = list(starts)
    while stack:
        s = stack.pop()
        if not s or s in seen:
            continue
        seen.add(s)
        t, data = objs.read_object(repo, s)
        if t != "commit":
            continue
        commits.append(s)
        c = objs.parse_commit(data)
        stack.extend(c.parents)
    commits.reverse()

    from . import diff as _diff
    out_dir = Path(args.output_directory)
    if not args.stdout:
        out_dir.mkdir(parents=True, exist_ok=True)

    for i, sha in enumerate(commits, 1):
        c = objs.parse_commit(objs.read_object(repo, sha)[1])
        msg_parts = c.message.rstrip("\n").split("\n\n", 1)
        subject = msg_parts[0].replace("\n", " ") if c.message.strip() else ""
        body_lines = msg_parts[1].splitlines() if len(msg_parts) > 1 else []
        parent_tree = ""
        if c.parents:
            parent_tree = objs.parse_commit(objs.read_object(repo, c.parents[0])[1]).tree
        changes = _tree_changes(repo, parent_tree or None, c.tree)
        stat = _capture_output(lambda: _emit_diffstat_summary(changes))
        diff = _capture_output(lambda: [_emit_file_diff(p, a, b) for p, a, b in changes])

        # Default: number only when there are multiple patches. --numbered
        # forces N/M even for one; --no-numbered suppresses it even for many.
        numbered = (len(commits) > 1 or args.numbered) and not args.no_numbered
        num = f" {i}/{len(commits)}" if numbered else ""
        ver = f" v{args.reroll}" if args.reroll is not None else ""
        body = "\n".join(body_lines).rstrip("\n")
        # --signoff appends a Signed-off-by trailer (committer identity).
        if args.signoff:
            body = (body + "\n\n" if body else "") + f"Signed-off-by: {_split_ident(c.committer)[0]}"
        lines = [
            f"From {sha} Mon Sep 17 00:00:00 2001",
            f"From: {_split_ident(c.author)[0]}",
            f"Date: {_format_rfc2822_date(c.author)}",
            f"Subject: [PATCH{ver}{num}] {subject}",
            "",
        ]
        if body:
            lines.append(body)
        if args.no_stat:
            lines.append("")
        else:
            lines.append("---")
            lines.append(stat.rstrip("\n"))
            lines.append("")
        lines.append(diff.rstrip("\n"))
        lines.append("-- ")
        lines.append("2.54.0")
        out = "\n".join(lines) + "\n"
        if args.stdout:
            # git separates patches by a blank line; between patches that yields
            # two blank lines after the signature, one after the final patch.
            sys.stdout.write(out + ("\n" if i == len(commits) else "\n\n"))
        else:
            # log-tree.c:fmt_output_subject. The %f slug, the "%04d-" number,
            # and a sanitized "v<n>-" reroll prefix are concatenated, then the
            # whole thing is truncated to (patch_name_max - len(suffix) - 1)
            # before the ".patch" suffix is appended. patch_name_max defaults
            # to 64; suffix ".patch" is 6 -> max_len 57. Truncation can leave a
            # trailing '-' (it is NOT re-trimmed).
            safe = _format_sanitized_subject(subject)
            suffix = ".patch"
            max_len = 64 - (len(suffix) + 1)
            stem = ""
            if args.reroll is not None:
                stem += _format_sanitized_subject(f"v{args.reroll}") + "-"
            stem += f"{i:04d}-{safe}"
            if len(stem) > max_len:
                stem = stem[:max_len]
            fname = stem + suffix
            # In file-output mode git terminates each patch file with an extra
            # blank line (the same trailing "\n\n" the --stdout form emits).
            (out_dir / fname).write_text(out + "\n", encoding="utf-8")
            _print(str(out_dir / fname))
    return 0


def _capture_output(fn) -> str:
    import io
    buf = io.StringIO()
    old = sys.stdout
    sys.stdout = buf
    try:
        fn()
    finally:
        sys.stdout = old
    return buf.getvalue()


def _format_rfc2822_date(sig: str) -> str:
    return _format_date(sig, "rfc")


class _AmAbort(Exception):
    """Raised by the am machinery to stop the session (like die_user_resolve /
    die): carries the process exit code."""

    def __init__(self, rc: int):
        self.rc = rc


# Resume modes (mirror enum resume_type in builtin/am.c)
_RESUME_FALSE = 0
_RESUME_APPLY = 1
_RESUME_RESOLVED = 2
_RESUME_SKIP = 3
_RESUME_ABORT = 4
_RESUME_QUIT = 5
_RESUME_SHOW_PATCH_RAW = 6
_RESUME_SHOW_PATCH_DIFF = 7
_RESUME_ALLOW_EMPTY = 8

# empty_action
_STOP_ON_EMPTY = 0
_DROP_EMPTY = 1
_KEEP_EMPTY = 2

# keep_type
_KEEP_FALSE = 0
_KEEP_TRUE = 1
_KEEP_NON_PATCH = 2

# scissors_type
_SCISSORS_UNSET = -1
_SCISSORS_FALSE = 0
_SCISSORS_TRUE = 1

# signoff_type
_SIGNOFF_FALSE = 0
_SIGNOFF_TRUE = 1
_SIGNOFF_EXPLICIT = 2

_EMPTY_TREE_SHA = "4b825dc642cb6eb9a060e54bf8d69288fbee4904"


class _AmState:
    """Port of struct am_state plus the am_run state machine."""

    def __init__(self, repo: Repository):
        self.repo = repo
        self.dir = repo.gitdir / "rebase-apply"
        self.cur = 0
        self.last = 0
        self.prec = 4
        self.author_name: Optional[str] = None
        self.author_email: Optional[str] = None
        self.author_date: Optional[str] = None
        self.msg: Optional[str] = None
        # options
        self.interactive = 0
        self.no_verify = 0
        self.threeway = 0
        self.quiet = 0
        self.signoff = _SIGNOFF_FALSE
        self.utf8 = 1
        self.keep = _KEEP_FALSE
        self.message_id = 0
        self.scissors = _SCISSORS_UNSET
        self.quoted_cr = -1  # quoted_cr_unset
        self.empty_type = _STOP_ON_EMPTY
        self.git_apply_opts: list[str] = []
        self.resolvemsg: Optional[str] = None
        self.committer_date_is_author_date = 0
        self.ignore_date = 0
        self.sign_commit: Optional[str] = None
        self.rebasing = 0

    # -- path / state-file helpers ------------------------------------------
    def path(self, name: str) -> Path:
        return self.dir / name

    def _write_text(self, name: str, s: str) -> None:
        self.path(name).write_text(s, encoding="utf-8")

    def _write_count(self, name: str, val: int) -> None:
        self.path(name).write_text(str(val), encoding="utf-8")

    def _write_bool(self, name: str, val) -> None:
        self._write_text(name, "t" if val else "f")

    def _read_state(self, name: str, trim: bool) -> Optional[str]:
        p = self.path(name)
        if not p.exists():
            return None
        data = p.read_bytes().decode("utf-8", "surrogateescape")
        return data.strip() if trim else data

    def say(self, stream, text: str) -> None:
        if not self.quiet:
            stream.write(text + "\n")

    # -- am_in_progress -----------------------------------------------------
    def in_progress(self) -> bool:
        if not self.dir.is_dir():
            return False
        if not self.path("last").is_file():
            return False
        if not self.path("next").is_file():
            return False
        return True

    # -- load ---------------------------------------------------------------
    def load(self) -> None:
        from . import am as _am
        self.cur = int((self._read_state("next", True) or "0").split()[0] or 0)
        self.last = int((self._read_state("last", True) or "0").split()[0] or 0)
        script = self.path("author-script")
        if script.exists():
            for line in script.read_text(encoding="utf-8", errors="surrogateescape").splitlines():
                key, _, val = line.partition("=")
                dq = _am.sq_dequote(val)
                if key == "GIT_AUTHOR_NAME":
                    self.author_name = dq
                elif key == "GIT_AUTHOR_EMAIL":
                    self.author_email = dq
                elif key == "GIT_AUTHOR_DATE":
                    self.author_date = dq
        fc = self.path("final-commit")
        if fc.exists():
            self.msg = fc.read_text(encoding="utf-8", errors="surrogateescape")
        self.threeway = 1 if self._read_state("threeway", True) == "t" else 0
        self.quiet = 1 if self._read_state("quiet", True) == "t" else 0
        self.signoff = 1 if self._read_state("sign", True) == "t" else 0
        self.utf8 = 1 if self._read_state("utf8", True) == "t" else 0
        keep = self._read_state("keep", True)
        self.keep = (_KEEP_TRUE if keep == "t" else
                     _KEEP_NON_PATCH if keep == "b" else _KEEP_FALSE)
        self.message_id = 1 if self._read_state("messageid", True) == "t" else 0
        sc = self._read_state("scissors", True)
        self.scissors = (_SCISSORS_TRUE if sc == "t" else
                         _SCISSORS_FALSE if sc == "f" else _SCISSORS_UNSET)
        qcr = self._read_state("quoted-cr", True)
        if not qcr:
            self.quoted_cr = -1
        else:
            from . import am as _am2
            act = {"nowarn": _am2.QCR_NOWARN, "warn": _am2.QCR_WARN,
                   "strip": _am2.QCR_STRIP}.get(qcr)
            self.quoted_cr = act if act is not None else -1
        applyopt = self._read_state("apply-opt", True) or ""
        self.git_apply_opts = _sq_dequote_to_list(applyopt)
        self.rebasing = 1 if self.path("rebasing").exists() else 0

    # -- destroy ------------------------------------------------------------
    def destroy(self) -> None:
        import shutil
        if self.dir.exists():
            shutil.rmtree(self.dir, ignore_errors=True)

    def msgnum(self) -> str:
        return "%0*d" % (self.prec, self.cur)


def _sq_dequote_to_list(s: str) -> list[str]:
    """Port of sq_dequote_to_strvec(): split a sq_quoted line into argv."""
    from . import am as _am
    out: list[str] = []
    s = s.strip()
    i = 0
    n = len(s)
    while i < n:
        while i < n and s[i] == " ":
            i += 1
        if i >= n:
            break
        # find the extent of this quoted token (it may contain '\'' escapes)
        if s[i] != "'":
            # unquoted token (apply opts are always quoted, but be lenient)
            j = i
            while j < n and s[j] != " ":
                j += 1
            out.append(s[i:j])
            i = j
            continue
        # accumulate up to the matching closing quote, honoring '\'' escapes
        j = i + 1
        token_src = ["'"]
        while j < n:
            if s[j] == "'":
                token_src.append("'")
                if j + 1 < n and s[j + 1] == "\\":
                    # '\X' escape: copy '\X'
                    token_src.append(s[j + 1:j + 4])
                    j += 4
                    continue
                j += 1
                break
            token_src.append(s[j])
            j += 1
        dq = _am.sq_dequote("".join(token_src))
        out.append(dq if dq is not None else "")
        i = j
    return out


def _am_index_has_changes(repo: Repository) -> tuple[bool, list[str]]:
    """Port of repo_index_has_changes(): does the index differ from HEAD's
    tree?  Returns (changed, sorted_changed_paths)."""
    head_sym, head = refs_mod.read_head(repo)
    if head:
        head_tree = objs.parse_commit(objs.read_object(repo, head)[1]).tree
        tree_files = {p: s for p, _m, s in workdir.iter_tree_files(repo, head_tree)}
    else:
        tree_files = {}
    from .index import read_index
    idx = read_index(repo)
    idx_files = {e.path: e.sha for e in idx.entries if e.stage == 0}
    changed: list[str] = []
    for p in set(tree_files) | set(idx_files):
        if tree_files.get(p) != idx_files.get(p):
            changed.append(p)
    # unmerged entries also count as changes
    for e in idx.entries:
        if e.stage != 0 and e.path not in changed:
            changed.append(e.path)
    changed.sort()
    return (bool(changed), changed)


def _am_unmerged(repo: Repository) -> bool:
    from .index import read_index
    idx = read_index(repo)
    return any(e.stage != 0 for e in idx.entries)


def cmd_am(argv: list[str]) -> int:
    repo = _repo()
    state = _AmState(repo)
    # am.threeway / am.messageid / commit.gpgsign config defaults
    cp = repo.config()

    def _cfg_bool(section: str, key: str) -> Optional[bool]:
        if cp.has_option(section, key):
            try:
                return cp.getboolean(section, key)
            except ValueError:
                v = cp.get(section, key).strip().lower()
                return v in ("true", "yes", "on", "1", "")
        return None

    tw = _cfg_bool("am", "threeway")
    if tw is not None:
        state.threeway = 1 if tw else 0
    mid = _cfg_bool("am", "messageid")
    if mid is not None:
        state.message_id = 1 if mid else 0
    gs = _cfg_bool("commit", "gpgsign")
    if gs is not None:
        state.sign_commit = "" if gs else None

    in_progress = state.in_progress()
    if in_progress:
        state.load()

    try:
        rc = _am_parse_and_dispatch(repo, state, argv, in_progress)
    except _AmAbort as ab:
        return ab.rc
    return rc


def _rfc2822_to_raw(value: str) -> str:
    """Convert an RFC2822 date to Git's raw '<seconds> <±HHMM>' form."""
    import email.utils
    try:
        dt = email.utils.parsedate_to_datetime(value.strip())
    except (TypeError, ValueError):
        return value.strip()
    secs = int(dt.timestamp())
    off = dt.utcoffset()
    total = int(off.total_seconds()) if off is not None else 0
    sign = "+" if total >= 0 else "-"
    total = abs(total)
    return f"{secs} {sign}{total // 3600:02d}{(total % 3600) // 60:02d}"


_AM_USAGE = (
    "usage: git am [<options>] [(<mbox> | <Maildir>)...]\n"
    "   or: git am [<options>] (--continue | --skip | --abort)\n"
    "\n"
    "    -i, --[no-]interactive\n"
    "                          run interactively\n"
    "    -n, --no-verify       bypass pre-applypatch and applypatch-msg hooks\n"
    "    --verify              opposite of --no-verify\n"
    "    -3, --[no-]3way       allow fall back on 3way merging if needed\n"
    "    -q, --[no-]quiet      be quiet\n"
    "    -s, --[no-]signoff    add a Signed-off-by trailer to the commit message\n"
    "    -u, --[no-]utf8       recode into utf8 (default)\n"
    "    -k, --[no-]keep       pass -k flag to git-mailinfo\n"
    "    --[no-]keep-non-patch pass -b flag to git-mailinfo\n"
    "    -m, --[no-]message-id pass -m flag to git-mailinfo\n"
    "    --[no-]keep-cr        pass --keep-cr flag to git-mailsplit for mbox format\n"
    "    -c, --[no-]scissors   strip everything before a scissors line\n"
    "    --quoted-cr <action>  pass it through git-mailinfo\n"
    "    --[no-]whitespace <action>\n"
    "                          pass it through git-apply\n"
    "    --[no-]ignore-space-change\n"
    "                          pass it through git-apply\n"
    "    --[no-]ignore-whitespace\n"
    "                          pass it through git-apply\n"
    "    --[no-]directory <root>\n"
    "                          pass it through git-apply\n"
    "    --[no-]exclude <path> pass it through git-apply\n"
    "    --[no-]include <path> pass it through git-apply\n"
    "    -C <n>                pass it through git-apply\n"
    "    -p <num>              pass it through git-apply\n"
    "    --[no-]patch-format <format>\n"
    "                          format the patch(es) are in\n"
    "    --[no-]reject         pass it through git-apply\n"
    "    --[no-]resolvemsg ... override error message when patch failure occurs\n"
    "    --continue            continue applying patches after resolving a conflict\n"
    "    -r, --resolved        synonyms for --continue\n"
    "    --skip                skip the current patch\n"
    "    --abort               restore the original branch and abort the patching operation\n"
    "    --quit                abort the patching operation but keep HEAD where it is\n"
    "    --show-current-patch[=(diff|raw)]\n"
    "                          show the patch being applied\n"
    "    --retry               try to apply current patch again\n"
    "    --allow-empty         record the empty patch as an empty commit\n"
    "    --[no-]committer-date-is-author-date\n"
    "                          lie about committer date\n"
    "    --[no-]ignore-date    use current timestamp for author date\n"
    "    --[no-]rerere-autoupdate\n"
    "                          update the index with reused conflict resolution if possible\n"
    "    -S, --[no-]gpg-sign[=<key-id>]\n"
    "                          GPG-sign commits\n"
    "    --empty (stop|drop|keep)\n"
    "                          how to handle empty patches\n"
    "\n"
)


def _am_usage_err(msg: str) -> int:
    sys.stderr.write(f"error: {msg}\n")
    sys.stderr.write(_AM_USAGE)
    return 129


def _am_parse_and_dispatch(repo: Repository, state: "_AmState", argv: list[str],
                           in_progress: bool) -> int:
    """Mirror the parse_options + dispatch tail of cmd_am()."""
    from . import am as _am

    resume_mode = _RESUME_FALSE
    keep_cr = -1
    patch_format = _am.PATCH_FORMAT_UNKNOWN
    binary = -1
    paths: list[str] = []

    # -h handling
    if "-h" in argv or "--help" in argv:
        sys.stdout.write(_AM_USAGE)
        return 129

    i = 0
    n = len(argv)
    saw_dd = False
    seen_resume_opt: Optional[str] = None

    def _cmdmode(mode: int, opt: str) -> Optional[int]:
        nonlocal resume_mode, seen_resume_opt
        if resume_mode != _RESUME_FALSE and resume_mode != mode:
            a, b = sorted([seen_resume_opt, opt])
            sys.stderr.write(f"error: options '{a}' and '{b}' cannot be used together\n")
            return 129
        resume_mode = mode
        seen_resume_opt = opt
        return None

    while i < n:
        a = argv[i]
        if saw_dd:
            paths.append(a)
            i += 1
            continue
        if a == "--":
            saw_dd = True
            i += 1
            continue
        if a == "-" or not a.startswith("-"):
            paths.append(a)
            i += 1
            continue
        # ---- long options ----
        if a.startswith("--"):
            name, eq, val = a[2:].partition("=")
            has_val = bool(eq)
            neg = False
            canon = name
            if name.startswith("no-"):
                neg = True
                canon = name[3:]
            # boolean toggles
            if canon == "interactive":
                state.interactive = 0 if neg else 1
            elif name == "no-verify":
                state.no_verify = 1
            elif name == "verify":
                state.no_verify = 0
            elif canon == "3way":
                state.threeway = 0 if neg else 1
            elif canon == "quiet":
                state.quiet = 0 if neg else 1
            elif canon == "signoff":
                state.signoff = _SIGNOFF_FALSE if neg else _SIGNOFF_EXPLICIT
            elif canon == "utf8":
                state.utf8 = 0 if neg else 1
            elif canon == "keep":
                state.keep = _KEEP_FALSE if neg else _KEEP_TRUE
            elif canon == "keep-non-patch":
                state.keep = _KEEP_FALSE if neg else _KEEP_NON_PATCH
            elif canon == "message-id":
                state.message_id = 0 if neg else 1
            elif canon == "keep-cr":
                keep_cr = 0 if neg else 1
            elif canon == "scissors":
                state.scissors = _SCISSORS_FALSE if neg else _SCISSORS_TRUE
            elif name == "quoted-cr":
                if not has_val:
                    if i + 1 >= n:
                        return _am_usage_err("option `quoted-cr' requires a value")
                    val = argv[i + 1]
                    i += 1
                act = {"nowarn": _am.QCR_NOWARN, "warn": _am.QCR_WARN,
                       "strip": _am.QCR_STRIP}.get(val)
                if act is None:
                    sys.stderr.write(f"error: bad action '{val}' for '--quoted-cr'\n")
                    return 129
                state.quoted_cr = act
            elif canon in ("whitespace", "directory", "exclude", "include"):
                if not has_val:
                    if i + 1 >= n:
                        return _am_usage_err(f"option `{canon}' requires a value")
                    val = argv[i + 1]
                    i += 1
                # --whitespace is OPT_PASSTHRU_ARGV to git-apply; its value is
                # validated lazily during apply (parse_whitespace_option), so an
                # invalid action is reported per-patch AFTER "Applying: ..." —
                # not rejected here.
                state.git_apply_opts.append(f"--{canon}={val}")
            elif canon in ("ignore-space-change", "ignore-whitespace", "reject"):
                state.git_apply_opts.append(f"--{canon}")
            elif name == "patch-format":
                if not has_val:
                    if i + 1 >= n:
                        return _am_usage_err("option `patch-format' requires a value")
                    val = argv[i + 1]
                    i += 1
                fmt = {"mbox": _am.PATCH_FORMAT_MBOX, "stgit": _am.PATCH_FORMAT_STGIT,
                       "stgit-series": _am.PATCH_FORMAT_STGIT_SERIES,
                       "hg": _am.PATCH_FORMAT_HG, "mboxrd": _am.PATCH_FORMAT_MBOXRD}.get(val)
                if fmt is None:
                    sys.stderr.write(f"error: invalid value for '--patch-format': '{val}'\n")
                    return 129
                patch_format = fmt
            elif name == "resolvemsg":
                if not has_val:
                    if i + 1 >= n:
                        return _am_usage_err("option `resolvemsg' requires a value")
                    val = argv[i + 1]
                    i += 1
                state.resolvemsg = val
            elif name == "continue":
                r = _cmdmode(_RESUME_RESOLVED, "--continue")
                if r is not None:
                    return r
            elif name == "resolved":
                r = _cmdmode(_RESUME_RESOLVED, "--resolved")
                if r is not None:
                    return r
            elif name == "skip":
                r = _cmdmode(_RESUME_SKIP, "--skip")
                if r is not None:
                    return r
            elif name == "abort":
                r = _cmdmode(_RESUME_ABORT, "--abort")
                if r is not None:
                    return r
            elif name == "quit":
                r = _cmdmode(_RESUME_QUIT, "--quit")
                if r is not None:
                    return r
            elif name == "show-current-patch":
                mode = _RESUME_SHOW_PATCH_RAW
                if has_val:
                    if val == "raw":
                        mode = _RESUME_SHOW_PATCH_RAW
                    elif val == "diff":
                        mode = _RESUME_SHOW_PATCH_DIFF
                    else:
                        sys.stderr.write(
                            f"error: invalid value for '--show-current-patch': '{val}'\n")
                        return 129
                r = _cmdmode(mode, "--show-current-patch")
                if r is not None:
                    return r
            elif name == "retry":
                r = _cmdmode(_RESUME_APPLY, "--retry")
                if r is not None:
                    return r
            elif name == "allow-empty":
                r = _cmdmode(_RESUME_ALLOW_EMPTY, "--allow-empty")
                if r is not None:
                    return r
            elif canon == "committer-date-is-author-date":
                state.committer_date_is_author_date = 0 if neg else 1
            elif canon == "ignore-date":
                state.ignore_date = 0 if neg else 1
            elif canon == "rerere-autoupdate":
                pass  # rerere autoupdate state (no observable effect here)
            elif name == "gpg-sign" or canon == "gpg-sign":
                if neg:
                    state.sign_commit = None
                else:
                    state.sign_commit = val if has_val else ""
            elif name == "empty":
                if not has_val:
                    if i + 1 >= n:
                        return _am_usage_err("option `empty' requires a value")
                    val = argv[i + 1]
                    i += 1
                et = {"stop": _STOP_ON_EMPTY, "drop": _DROP_EMPTY,
                      "keep": _KEEP_EMPTY}.get(val)
                if et is None:
                    sys.stderr.write(f"error: invalid value for '--empty': '{val}'\n")
                    return 129
                state.empty_type = et
            elif name == "binary" or canon == "binary":
                binary = 0 if neg else 1
            elif name == "rebasing":
                state.rebasing = 1
            else:
                return _am_usage_err(f"unknown option `{name}'")
            i += 1
            continue
        # ---- short options (clustered) ----
        j = 1
        consumed_next = False
        while j < len(a):
            c = a[j]
            if c == "i":
                state.interactive = 1
            elif c == "n":
                state.no_verify = 1
            elif c == "3":
                state.threeway = 1
            elif c == "q":
                state.quiet = 1
            elif c == "s":
                state.signoff = _SIGNOFF_EXPLICIT
            elif c == "u":
                state.utf8 = 1
            elif c == "k":
                state.keep = _KEEP_TRUE
            elif c == "m":
                state.message_id = 1
            elif c == "c":
                state.scissors = _SCISSORS_TRUE
            elif c == "r":
                r = _cmdmode(_RESUME_RESOLVED, "--resolved")
                if r is not None:
                    return r
            elif c == "b":
                binary = 1
            elif c in ("C", "p"):
                rest = a[j + 1:]
                if not rest:
                    if i + 1 >= n:
                        sys.stderr.write(f"error: switch `{c}' requires a value\n")
                        return 129
                    rest = argv[i + 1]
                    consumed_next = True
                state.git_apply_opts.append(f"-{c}{rest}")
                break
            elif c == "S":
                rest = a[j + 1:]
                state.sign_commit = rest  # -S<key> or -S (empty)
                break
            else:
                return _am_usage_err(f"unknown switch `{c}'")
            j += 1
        i += 2 if consumed_next else 1

    if binary >= 0:
        sys.stderr.write(
            "The -b/--binary option has been a no-op for long time, and\n"
            "it will be removed. Please do not use it anymore.\n")

    return _am_dispatch(repo, state, resume_mode, keep_cr, patch_format,
                        paths, in_progress)


def _am_dispatch(repo: Repository, state: "_AmState", resume_mode: int,
                 keep_cr: int, patch_format: int, paths: list[str],
                 in_progress: bool) -> int:
    if in_progress:
        if paths or (resume_mode == _RESUME_FALSE and not sys.stdin.isatty()):
            _err(f"fatal: previous rebase directory {_am_dir_disp(repo, state)} "
                 "still exists but mbox given.")
            return 128
        if resume_mode == _RESUME_FALSE:
            resume_mode = _RESUME_APPLY
        if state.signoff == _SIGNOFF_EXPLICIT:
            _am_append_signoff(state)
    else:
        if state.dir.exists() and not state.rebasing:
            if resume_mode in (_RESUME_ABORT, _RESUME_QUIT):
                state.destroy()
                return 0
            _err(f"fatal: Stray {_am_dir_disp(repo, state)} directory found.\n"
                 'Use "git am --abort" to remove it.')
            return 128
        if resume_mode:
            _err("fatal: Resolve operation not in progress, we are not resuming.")
            return 128
        if state.interactive and not paths:
            _err("fatal: interactive mode requires patches on the command line")
            return 128
        rc = _am_setup(repo, state, patch_format, paths, keep_cr)
        if rc != 0:
            return rc

    if resume_mode == _RESUME_FALSE:
        return _am_run(repo, state, 0)
    if resume_mode == _RESUME_APPLY:
        return _am_run(repo, state, 1)
    if resume_mode in (_RESUME_RESOLVED, _RESUME_ALLOW_EMPTY):
        return _am_resolve(repo, state, 1 if resume_mode == _RESUME_ALLOW_EMPTY else 0)
    if resume_mode == _RESUME_SKIP:
        return _am_skip(repo, state)
    if resume_mode == _RESUME_ABORT:
        return _am_abort(repo, state)
    if resume_mode == _RESUME_QUIT:
        state.destroy()
        return 0
    if resume_mode in (_RESUME_SHOW_PATCH_RAW, _RESUME_SHOW_PATCH_DIFF):
        return _am_show_patch(repo, state, resume_mode)
    return 0


def _am_dir_disp(repo: Repository, state: "_AmState") -> str:
    """Display path for the rebase-apply directory as git prints it (relative to
    cwd when inside the worktree, matching git_path output)."""
    try:
        return os.path.relpath(state.dir, repo.path)
    except ValueError:
        return str(state.dir)


def _am_append_signoff(state: "_AmState") -> None:
    msg = state.msg or ""
    cn, ce = state.repo.user()
    # committer identity for the trailer
    csig = objs.build_signature(state.repo, "committer")
    cwho, _t, _z = _split_ident(csig)
    n, e = _parse_who(cwho)
    body = msg.rstrip("\n")
    trailer = f"Signed-off-by: {n} <{e}>"
    # append_signoff with no existing trailer block: blank line then trailer
    if body:
        state.msg = body + "\n\n" + trailer + "\n"
    else:
        state.msg = trailer + "\n"


def _am_setup(repo: Repository, state: "_AmState", patch_format: int,
              paths: list[str], keep_cr: int) -> int:
    from . import am as _am
    if not patch_format:
        patch_format = _am_detect_format(state, paths)
    if not patch_format:
        _err("Patch format detection failed.")
        return 128
    state.dir.mkdir(parents=True, exist_ok=True)
    refs_mod.delete_ref(repo, "REBASE_HEAD")

    rc = _am_split_mail(repo, state, patch_format, paths, keep_cr)
    if rc != 0:
        state.destroy()
        _err("fatal: Failed to split patches.")
        return 128

    if state.rebasing:
        state.threeway = 1
    state._write_bool("threeway", state.threeway)
    state._write_bool("quiet", state.quiet)
    state._write_bool("sign", state.signoff)
    state._write_bool("utf8", state.utf8)
    state._write_text("keep", {_KEEP_FALSE: "f", _KEEP_TRUE: "t",
                               _KEEP_NON_PATCH: "b"}[state.keep])
    state._write_bool("messageid", state.message_id)
    state._write_text("scissors", {_SCISSORS_UNSET: "", _SCISSORS_FALSE: "f",
                                   _SCISSORS_TRUE: "t"}[state.scissors])
    state._write_text("quoted-cr", {-1: "", _am.QCR_NOWARN: "nowarn",
                                    _am.QCR_WARN: "warn", _am.QCR_STRIP: "strip"}
                      .get(state.quoted_cr, ""))
    state._write_text("apply-opt", " ".join(_am.sq_quote(o) for o in state.git_apply_opts)
                      if state.git_apply_opts else "")
    state._write_text("rebasing" if state.rebasing else "applying", "")

    head_sym, head = refs_mod.read_head(repo)
    if head:
        state._write_text("abort-safety", head)
        if not state.rebasing:
            refs_mod.update_ref(repo, "ORIG_HEAD", head)
    else:
        state._write_text("abort-safety", "")
        if not state.rebasing:
            refs_mod.delete_ref(repo, "ORIG_HEAD")

    state._write_count("next", state.cur)
    state._write_count("last", state.last)
    return 0


def _am_detect_format(state: "_AmState", paths: list[str]) -> int:
    from . import am as _am
    if not paths or paths[0] == "-" or Path(paths[0]).is_dir():
        return _am.PATCH_FORMAT_MBOX
    # builtin/am.c:detect_patch_format opens the first patch with xfopen(),
    # which die_errno()s if the path is not a directory and cannot be opened.
    try:
        data = Path(paths[0]).read_bytes()
    except OSError as e:
        import os as _os
        msg = _os.strerror(e.errno) if e.errno is not None else str(e)
        raise RepositoryError(
            "could not open '%s' for reading: %s" % (paths[0], msg))
    return _am.detect_patch_format(data, False)


def _am_split_mail(repo: Repository, state: "_AmState", patch_format: int,
                   paths: list[str], keep_cr: int) -> int:
    from . import am as _am
    if keep_cr < 0:
        keep_cr = 0
        cp = repo.config()
        if cp.has_option("am", "keepcr"):
            try:
                keep_cr = 1 if cp.getboolean("am", "keepcr") else 0
            except ValueError:
                keep_cr = 0
    if patch_format not in (_am.PATCH_FORMAT_MBOX, _am.PATCH_FORMAT_MBOXRD):
        # stgit/hg conversions are uncommon for am; only mbox/mboxrd supported
        # byte-exact here.
        _err("fatal: Failed to split patches.")
        return 1
    mboxrd = (patch_format == _am.PATCH_FORMAT_MBOXRD)
    skip = 0
    srcs = paths if paths else ["-"]
    for src in srcs:
        is_stdin = (src == "-")
        if is_stdin:
            data = _stdin_bytes()
        elif Path(src).is_dir():
            ns, err = _am.split_maildir(Path(src), state.dir, state.prec, skip,
                                        bool(keep_cr), mboxrd)
            if err:
                return 1
            skip = ns
            continue
        else:
            try:
                data = Path(src).read_bytes()
            except OSError:
                return 1
        ns, err = _am.split_mbox(data, state.dir, True, state.prec, skip,
                                 bool(keep_cr), mboxrd, is_stdin)
        if err or ns < 0:
            return 1
        skip = ns
    state.cur = 1
    state.last = skip
    return 0


def _am_parse_mail(repo: Repository, state: "_AmState", mail: Path) -> bool:
    """Port of parse_mail(): run mailinfo, populate state author/msg, write the
    msg/patch/info state files.  Returns True if the patch should be skipped."""
    from . import am as _am
    mi = _am.Mailinfo()
    mi.metainfo_charset = "UTF-8" if state.utf8 else None
    if state.keep == _KEEP_TRUE:
        mi.keep_subject = 1
    elif state.keep == _KEEP_NON_PATCH:
        mi.keep_non_patch_brackets_in_subject = 1
    if state.message_id:
        mi.add_message_id = 1
    if state.scissors == _SCISSORS_FALSE:
        mi.use_scissors = 0
    elif state.scissors == _SCISSORS_TRUE:
        mi.use_scissors = 1
    if state.quoted_cr in (_am.QCR_NOWARN, _am.QCR_WARN, _am.QCR_STRIP):
        mi.quoted_cr = state.quoted_cr

    data = mail.read_bytes()
    msg_b, patch_b, info_b = _am.run_mailinfo(mi, data)
    if msg_b is None:
        # empty patch -> mailinfo error "could not parse patch" in C -> die
        _err("fatal: could not parse patch")
        raise _AmAbort(128)
    state.path("msg").write_bytes(msg_b)
    state.path("patch").write_bytes(patch_b)
    state.path("info").write_bytes(info_b)
    if mi._warn_quoted_cr:
        _err("warning: quoted CRLF detected")
    if mi.format_flowed:
        _err("warning: Patch sent with format=flowed; "
             "space at the end of lines might be lost.")

    # parse the info file
    subject_parts: list[str] = []
    author_name = author_email = author_date = ""
    for raw in info_b.decode("utf-8", "surrogateescape").split("\n"):
        if raw.startswith("Subject: "):
            subject_parts.append(raw[len("Subject: "):])
        elif raw.startswith("Author: "):
            author_name = raw[len("Author: "):]
        elif raw.startswith("Email: "):
            author_email = raw[len("Email: "):]
        elif raw.startswith("Date: "):
            author_date = raw[len("Date: "):]

    if author_name == "Mail System Internal Data":
        return True

    log_message = msg_b.decode("utf-8", "surrogateescape")
    full = "\n".join(subject_parts) + "\n\n" + log_message
    full = _strbuf_stripspace(full, None)
    state.author_name = author_name
    state.author_email = author_email
    state.author_date = author_date
    state.msg = full
    return False


def _am_write_author_script(state: "_AmState") -> None:
    from . import am as _am
    lines = [
        "GIT_AUTHOR_NAME=" + _am.sq_quote(state.author_name or ""),
        "GIT_AUTHOR_EMAIL=" + _am.sq_quote(state.author_email or ""),
        "GIT_AUTHOR_DATE=" + _am.sq_quote(state.author_date or ""),
        "",
    ]
    state.path("author-script").write_text("\n".join(lines), encoding="utf-8",
                                           errors="surrogateescape")


def _am_is_empty_patch(state: "_AmState") -> bool:
    p = state.path("patch")
    if not p.exists():
        return True
    return p.stat().st_size == 0


def _am_run(repo: Repository, state: "_AmState", resume: int) -> int:
    state.path("dirtyindex").unlink(missing_ok=True)

    # refresh index (refresh stat info, write) then check dirtiness vs HEAD
    _am_refresh_index(repo)
    changed, paths = _am_index_has_changes(repo)
    if changed:
        state._write_bool("dirtyindex", 1)
        _err(f"fatal: Dirty index: cannot apply patches (dirty: {chr(10).join(paths)})")
        return 128

    while state.cur <= state.last:
        mail = state.path(state.msgnum())
        if not mail.exists():
            _am_next(repo, state)
            if resume:
                state.load()
            resume = 0
            continue

        if resume:
            _am_validate_resume(state)
        else:
            skip = _am_parse_mail(repo, state, mail)
            if skip:
                _am_next(repo, state)
                if resume:
                    state.load()
                resume = 0
                continue
            if state.signoff:
                _am_append_signoff(state)
            _am_write_author_script(state)
            state.path("final-commit").write_text(state.msg or "", encoding="utf-8",
                                                  errors="surrogateescape")

        if state.interactive and _am_do_interactive(repo, state):
            _am_next(repo, state)
            if resume:
                state.load()
            resume = 0
            continue

        to_keep = False
        if _am_is_empty_patch(state):
            if state.empty_type == _DROP_EMPTY:
                state.say(sys.stdout, "Skipping: " + _am_first_line(state.msg))
                _am_next(repo, state)
                if resume:
                    state.load()
                resume = 0
                continue
            elif state.empty_type == _KEEP_EMPTY:
                to_keep = True
                state.say(sys.stdout, "Creating an empty commit: " + _am_first_line(state.msg))
            else:  # STOP_ON_EMPTY
                _print("Patch is empty.")
                _am_die_user_resolve(repo, state)

        # applypatch-msg hook (mirror run_applypatch_msg_hook): runs on the
        # final-commit file, then the (possibly edited) message is re-read.
        if _am_run_applypatch_msg_hook(repo, state):
            raise _AmAbort(1)

        if not to_keep:
            state.say(sys.stdout, "Applying: " + _am_first_line(state.msg))
            apply_status = _am_apply(repo, state, None)
            if apply_status and state.threeway:
                apply_status = _am_fall_back_threeway(repo, state)
                if not apply_status:
                    changed, _ = _am_index_has_changes(repo)
                    if not changed:
                        state.say(sys.stdout, "No changes -- Patch already applied.")
                        _am_next(repo, state)
                        if resume:
                            state.load()
                        resume = 0
                        continue
            if apply_status:
                _print(f"Patch failed at {state.msgnum()} {_am_first_line(state.msg)}")
                _am_advise_show_patch(repo)
                _am_die_user_resolve(repo, state)

        _am_do_commit(repo, state)
        _am_next(repo, state)
        if resume:
            state.load()
        resume = 0

    if not state.rebasing:
        state.destroy()
    return 0


def _am_first_line(msg: Optional[str]) -> str:
    if not msg:
        return ""
    nl = msg.find("\n")
    return msg if nl < 0 else msg[:nl]


def _am_refresh_index(repo: Repository) -> None:
    """Refresh the index stat info (REFRESH_QUIET) and write it back."""
    from .index import read_index, write_index
    try:
        idx = read_index(repo)
    except (OSError, ValueError):
        return
    # Update stat info for entries whose worktree content matches; this mirrors
    # repo_refresh_and_write_index just enough for the dirtiness check.
    write_index(repo, idx)


def _am_advise_show_patch(repo: Repository) -> None:
    _err("hint: Use 'git am --show-current-patch=diff' to see the failed patch")


def _am_die_user_resolve(repo: Repository, state: "_AmState") -> None:
    if state.resolvemsg:
        _err("hint: " + state.resolvemsg)
        raise _AmAbort(128)
    cmdline = "git am -i" if state.interactive else "git am"
    _err(f'hint: When you have resolved this problem, run "{cmdline} --continue".')
    _err(f'hint: If you prefer to skip this patch, run "{cmdline} --skip" instead.')
    # advise allow-empty when the patch file is empty/missing and the index has
    # no changes vs HEAD
    if _am_is_empty_patch(state):
        changed, _ = _am_index_has_changes(repo)
        if not changed:
            _err(f'hint: To record the empty patch as an empty commit, run "{cmdline} --allow-empty".')
    _err(f'hint: To restore the original branch and stop patching, run "{cmdline} --abort".')
    _err('hint: Disable this message with "git config set advice.mergeConflict false"')
    raise _AmAbort(128)


def _am_do_interactive(repo: Repository, state: "_AmState") -> bool:
    """Port of do_interactive(): prompt whether to apply the current patch.
    Returns True to skip the patch, False to apply it.  'a' accepts all
    remaining patches (turns interactive off)."""
    while True:
        _print("Commit Body is:")
        _print("--------------------------")
        sys.stdout.write(state.msg or "")
        _print("--------------------------")
        sys.stdout.write("Apply? [y]es/[n]o/[e]dit/[v]iew patch/[a]ccept all: ")
        sys.stdout.flush()
        reply = sys.stdin.readline()
        if not reply:
            _err("fatal: unable to read from stdin; aborting")
            raise _AmAbort(128)
        c = reply[0]
        if c in ("y", "Y"):
            return False
        if c in ("a", "A"):
            state.interactive = 0
            return False
        if c in ("n", "N"):
            return True
        if c in ("e", "E"):
            # launch the editor on final-commit; if it cannot be launched we
            # leave the message unchanged and re-prompt.
            new = _launch_editor_on(repo, state.path("final-commit"))
            if new is not None:
                state.msg = new
        elif c in ("v", "V"):
            pager = os.environ.get("GIT_PAGER") or "cat"
            import subprocess
            try:
                subprocess.call(f"{pager} " + _sh_quote(str(state.path("patch"))),
                                shell=True)
            except OSError:
                pass
        # otherwise re-prompt


def _launch_editor_on(repo: Repository, path: Path) -> Optional[str]:
    """Launch the configured editor on ``path`` and return its new contents, or
    None if no editor could be launched."""
    editor = (os.environ.get("GIT_EDITOR") or os.environ.get("VISUAL")
              or os.environ.get("EDITOR"))
    if not editor:
        return None
    import subprocess
    try:
        rc = subprocess.call(f"{editor} " + _sh_quote(str(path)), shell=True)
    except OSError:
        return None
    if rc != 0:
        return None
    return path.read_text(encoding="utf-8", errors="surrogateescape")


def _sh_quote(s: str) -> str:
    import shlex
    return shlex.quote(s)


def _am_validate_resume(state: "_AmState") -> None:
    if state.msg is None:
        _err(f"fatal: cannot resume: {_am_state_rel(state, 'final-commit')} does not exist.")
        raise _AmAbort(128)
    if state.author_name is None or state.author_email is None or state.author_date is None:
        _err(f"fatal: cannot resume: {_am_state_rel(state, 'author-script')} does not exist.")
        raise _AmAbort(128)


def _am_state_rel(state: "_AmState", name: str) -> str:
    try:
        return os.path.relpath(state.path(name), state.repo.path)
    except ValueError:
        return str(state.path(name))


def _am_apply(repo: Repository, state: "_AmState", index_file: Optional[str]) -> int:
    """Port of run_apply(): apply the state 'patch' file via git-apply with
    check_index (no in-apply 3way).  Returns 0 on success, nonzero on failure."""
    from . import apply as apply_mod
    # git-apply's parse_whitespace_option() validates the action lazily, so an
    # invalid --whitespace fires here (after "Applying: ..." was printed) with
    # rc 129 (builtin/am.c run_apply -> apply errors exit the program).
    for o in state.git_apply_opts:
        if o.startswith("--whitespace="):
            val = o.split("=", 1)[1]
            if val not in ("warn", "nowarn", "error", "error-all", "strip", "fix"):
                sys.stderr.write(f"error: unrecognized whitespace option '{val}'\n")
                raise _AmAbort(129)
    text = state.path("patch").read_bytes()
    pif = _am_state_rel(state, "patch")
    # parse git_apply_opts into apply options
    opts_kw = _am_apply_opts(state)
    p_value = opts_kw.pop("_p_value", None)
    try:
        patches = apply_mod.parse_patches(text, p_value, patch_input_file=pif,
                                          recount=False)
    except apply_mod.ApplyError as exc:
        _err(exc.message)
        return exc.rc if exc.rc else 1
    if not patches:
        return 0
    # --directory=<root>: git-apply prepends <root>/ to every path (apply.c
    # find_name with state->root), so the patch now targets <root>/<path>.
    root = None
    for o in state.git_apply_opts:
        if o.startswith("--directory="):
            root = o.split("=", 1)[1]
    if root:
        rpfx = root.rstrip("/") + "/"
        for p in patches:
            for attr in ("old_name", "new_name", "def_name"):
                v = getattr(p, attr, None)
                if v:
                    setattr(p, attr, rpfx + v)
    # builtin/am.c:run_apply silences git-apply's verbosity ONLY for the
    # initial 3-way attempt (state->threeway && !index_file) so false errors
    # are not shown before falling back; --quiet does NOT silence apply errors.
    verbosity = -1 if (state.threeway and index_file is None) else 0
    # apply_with_reject forces verbose, matching apply.c's check_apply_state.
    if opts_kw.get("apply_with_reject") and verbosity > -1:
        verbosity = 1
    opts = apply_mod.ApplyOpts(
        p_value=p_value,
        check_index=True,
        verbosity=verbosity,
        **opts_kw,
    )
    return apply_mod.check_and_apply(repo, patches, opts, pif)


def _am_apply_opts(state: "_AmState") -> dict:
    """Translate state.git_apply_opts into ApplyOpts kwargs.  ``git am`` always
    applies, so the whitespace default is 'warn'."""
    kw: dict = {"_p_value": None, "ws_action": "warn"}
    for o in state.git_apply_opts:
        if o.startswith("-p"):
            try:
                kw["_p_value"] = int(o[2:])
            except ValueError:
                pass
        elif o.startswith("-C"):
            try:
                kw["p_context"] = int(o[2:])
            except ValueError:
                pass
        elif o.startswith("--whitespace="):
            kw["ws_action"] = _apply_ws_action(o.split("=", 1)[1], True)
        elif o == "--reject":
            kw["apply_with_reject"] = True
    # Only pass kwargs ApplyOpts actually accepts.
    accepted = {}
    import inspect
    from . import apply as apply_mod
    fields = inspect.signature(apply_mod.ApplyOpts).parameters
    for k, v in kw.items():
        if k == "_p_value":
            accepted[k] = v
        elif k in fields:
            accepted[k] = v
    return accepted


def _am_do_commit(repo: Repository, state: "_AmState") -> None:
    """Port of do_commit(): write tree from index, commit with author identity
    from the mail, committer from env/config, update HEAD with reflog 'am: …'."""
    if not state.no_verify:
        rc = _run_hook(repo, "pre-applypatch")
        if rc:
            raise _AmAbort(1)

    tree = workdir.write_tree(repo)
    head_sym, parent = refs_mod.read_head(repo)
    parents = [parent] if parent else []
    if not parent:
        state.say(sys.stderr, "applying to an empty history")

    # Author identity.  The date is the RFC2822 mail "Date:" converted to raw
    # form, unless --ignore-date (in which case it is "now").  fmt_ident with a
    # NULL date uses a single cached "now" for the whole patch, so author and
    # (when committer-date-is-author-date) committer share the exact timestamp.
    if state.ignore_date:
        author_date_raw = _am_now_raw()
    else:
        author_date_raw = _rfc2822_to_raw(state.author_date) if state.author_date else _am_now_raw()
    author_sig = _am_fmt_ident(state.author_name or "", state.author_email or "",
                               author_date_raw)
    if state.committer_date_is_author_date:
        cn = os.environ.get("GIT_COMMITTER_NAME")
        ce = os.environ.get("GIT_COMMITTER_EMAIL")
        # Fall back to configured identity when the env vars are unset.
        csig_default = objs.build_signature(repo, "committer")
        cwho, _t, _z = _split_ident(csig_default)
        dn, de = _parse_who(cwho)
        committer_sig = _am_fmt_ident(cn or dn, ce or de, author_date_raw)
    else:
        committer_sig = objs.build_signature(repo, "committer")

    msg = state.msg or ""
    if not msg.endswith("\n"):
        msg = msg + "\n"
    commit_bytes = objs.Commit(tree=tree, parents=parents, author=author_sig,
                               committer=committer_sig, message=msg).encode()
    if state.sign_commit is not None:
        from . import gpgsign
        signing_key = (state.sign_commit if state.sign_commit
                       else gpgsign.get_signing_key(repo, _ident_no_date(committer_sig)))
        sig, errmsg = gpgsign.sign_buffer(repo, commit_bytes, signing_key)
        if sig is None:
            _error(errmsg)
            _err("fatal: failed to write commit object")
            raise _AmAbort(128)
        commit_bytes = gpgsign.add_header_signature(commit_bytes, sig)
    sha = objs.write_object(repo, "commit", commit_bytes)

    reflog_msg = os.environ.get("GIT_REFLOG_ACTION") or "am"
    reflog = f"{reflog_msg}: {_am_first_line(state.msg)}"
    if head_sym:
        refs_mod.update_ref(repo, head_sym, sha, message=reflog)
    else:
        refs_mod.set_head(repo, sha)

    # post-applypatch always runs (it is NOT gated by --no-verify, am.c:1727).
    _run_hook(repo, "post-applypatch")


def _am_now_raw() -> str:
    """Current time in raw '<secs> <±HHMM>' form (the local UTC offset), used
    when --ignore-date or a mail lacks a Date: header."""
    import time as _t
    from .objects import _local_tz_minutes
    secs = int(_t.time())
    tz = _local_tz_minutes(secs)
    sign = "+" if tz >= 0 else "-"
    tza = abs(tz)
    return f"{secs} {sign}{tza // 60:02d}{tza % 60:02d}"


def _am_fmt_ident(name: str, email: str, date_raw: Optional[str]) -> str:
    secs_tz = None
    if date_raw:
        from .objects import _parse_date_env
        secs_tz = _parse_date_env(date_raw)
    if secs_tz is None:
        import time as _t
        from .objects import _local_tz_minutes
        secs = int(_t.time())
        tz = _local_tz_minutes(secs)
    else:
        secs, tz = secs_tz
    return objs.format_signature(name, email, when=secs, tz_minutes=tz)


def _am_next(repo: Repository, state: "_AmState") -> None:
    state.author_name = None
    state.author_email = None
    state.author_date = None
    state.msg = None
    state.path("author-script").unlink(missing_ok=True)
    state.path("final-commit").unlink(missing_ok=True)
    state.path("original-commit").unlink(missing_ok=True)
    refs_mod.delete_ref(repo, "REBASE_HEAD")
    head_sym, head = refs_mod.read_head(repo)
    state._write_text("abort-safety", head or "")
    state.cur += 1
    state._write_count("next", state.cur)


def _am_resolve(repo: Repository, state: "_AmState", allow_empty: int) -> int:
    _am_validate_resume(state)
    state.say(sys.stdout, "Applying: " + _am_first_line(state.msg))
    changed, _ = _am_index_has_changes(repo)
    if not changed:
        if allow_empty and _am_is_empty_patch(state):
            _print("No changes - recorded it as an empty commit.")
        else:
            _print("No changes - did you forget to use 'git add'?\n"
                   "If there is nothing left to stage, chances are that something else\n"
                   "already introduced the same changes; you might want to skip this patch.")
            _am_die_user_resolve(repo, state)
    if _am_unmerged(repo):
        _print("You still have unmerged paths in your index.\n"
               "You should 'git add' each file with resolved conflicts to mark them as such.\n"
               "You might run `git rm` on a file to accept \"deleted by them\" for it.")
        _am_die_user_resolve(repo, state)
    _am_do_commit(repo, state)
    _am_next(repo, state)
    state.load()
    return _am_run(repo, state, 0)


def _am_skip(repo: Repository, state: "_AmState") -> int:
    head_sym, head = refs_mod.read_head(repo)
    head = head or _EMPTY_TREE_SHA
    _am_clean_index(repo, head, head)
    _am_next(repo, state)
    state.load()
    return _am_run(repo, state, 0)


def _am_abort(repo: Repository, state: "_AmState") -> int:
    if not _am_safe_to_abort(repo, state):
        state.destroy()
        return 0
    head_sym, curr_head = refs_mod.read_head(repo)
    has_curr_head = bool(curr_head)
    if not has_curr_head:
        curr_head = _EMPTY_TREE_SHA
    orig_head = refs_mod.read_ref(repo, "ORIG_HEAD")
    has_orig_head = bool(orig_head)
    if not has_orig_head:
        orig_head = _EMPTY_TREE_SHA
    _am_clean_index(repo, curr_head, orig_head)
    if has_orig_head:
        if head_sym:
            refs_mod.update_ref(repo, head_sym, orig_head, message="am --abort")
        else:
            refs_mod.set_head(repo, orig_head)
    elif head_sym:
        refs_mod.delete_ref(repo, head_sym)
    state.destroy()
    return 0


def _am_safe_to_abort(repo: Repository, state: "_AmState") -> bool:
    if state.path("dirtyindex").exists():
        return False
    abort_safety = state._read_state("abort-safety", True) or ""
    head_sym, head = refs_mod.read_head(repo)
    head = head or ""
    if head == abort_safety:
        return True
    _err("warning: You seem to have moved HEAD since the last 'am' failure.\n"
         "Not rewinding to ORIG_HEAD")
    return False


def _am_clean_index(repo: Repository, head: str, remote: str) -> None:
    """Port of clean_index(): reset the index+worktree to ``remote``'s tree,
    discarding unmerged state (used by --skip and --abort)."""
    def _tree_of(sha: str) -> str:
        if sha == _EMPTY_TREE_SHA:
            return _EMPTY_TREE_SHA
        t, data = objs.read_object(repo, sha)
        return objs.parse_commit(data).tree if t == "commit" else sha
    remote_tree = _tree_of(remote)
    from .index import read_index, write_index, Index, IndexEntry
    # Reset worktree + index to remote_tree.
    if remote_tree == _EMPTY_TREE_SHA:
        idx = Index()
        write_index(repo, idx)
    else:
        workdir.checkout_tree(repo, remote_tree)
        idx = Index()
        for p, mode, sha in workdir.iter_tree_files(repo, remote_tree):
            idx.entries.append(IndexEntry(mode=int(mode, 8), sha=sha, path=p))
        write_index(repo, idx)
    remove_state = repo.gitdir / "MERGE_HEAD"
    remove_state.unlink(missing_ok=True)


def _am_show_patch(repo: Repository, state: "_AmState", resume_mode: int) -> int:
    orig = state._read_state("original-commit", True)
    if orig:
        return cmd_show([orig, "--"])
    if resume_mode == _RESUME_SHOW_PATCH_RAW:
        patch_path = state.path(state.msgnum())
    else:
        patch_path = state.path("patch")
    if not patch_path.exists():
        _err(f"fatal: failed to read '{_am_state_rel(state, patch_path.name)}': "
             "No such file or directory")
        return 128
    sys.stdout.flush()
    sys.stdout.buffer.write(patch_path.read_bytes())
    sys.stdout.buffer.flush()
    return 0


def _am_fall_back_threeway(repo: Repository, state: "_AmState") -> int:
    """Port of fall_back_threeway(): build a fake-ancestor index from the
    patch's index lines, apply onto it to get their_tree, then 3-way merge
    HEAD and their_tree against that base.  Returns 0 on success, nonzero on
    failure."""
    from . import am as _am
    from . import apply as apply_mod
    from . import ort as ort_mod

    head_sym, head = refs_mod.read_head(repo)
    our_tree = (objs.parse_commit(objs.read_object(repo, head)[1]).tree
                if head else _EMPTY_TREE_SHA)

    # build_fake_ancestor
    text = state.path("patch").read_bytes()
    try:
        patches = apply_mod.parse_patches(text, _am_apply_opts(state).get("_p_value"),
                                          patch_input_file=str(state.path("patch")),
                                          recount=False)
    except apply_mod.ApplyError:
        _err("error: could not build fake ancestor")
        return 1
    base_tree = _am_build_fake_ancestor(repo, patches)
    if base_tree is None:
        _err("error: could not build fake ancestor")
        return 1

    state.say(sys.stdout, "Using index info to reconstruct a base tree...")
    if not state.quiet:
        _am_threeway_namestatus(repo, our_tree, base_tree)

    # apply the patch onto the base tree (cached), producing their_tree
    their_tree = _am_apply_to_tree(repo, state, base_tree)
    if their_tree is None:
        _err("error: Did you hand edit your patch?\n"
             "It does not apply to blobs recorded in its index.")
        return 1

    state.say(sys.stdout, "Falling back to patching base and 3-way merge...")

    # merge_ort_generic(o, our_tree, their_tree, 1 base, [base_tree]) with
    # am's labels: branch1="HEAD", branch2=<subject>, ancestor=fake ancestor.
    branch2 = _am_first_line(state.msg)
    result = ort_mod.merge_ort_generic(repo, our_tree, their_tree, [base_tree],
                                       branch1="HEAD", branch2=branch2,
                                       ancestor="constructed fake ancestor")
    # Print "Auto-merging"/"CONFLICT" messages.
    _am_emit_merge_messages(result, branch2)
    # Write the merge result to the worktree and index (stages on conflict).
    workdir.checkout_tree(repo, result.tree)
    from .index import write_index, Index, IndexEntry
    if result.conflict_index is not None:
        write_index(repo, result.conflict_index)
    else:
        idx = Index()
        for p, mode, sha in workdir.iter_tree_files(repo, result.tree):
            idx.entries.append(IndexEntry(mode=int(mode, 8), sha=sha, path=p))
        write_index(repo, idx)
    if result.conflicts:
        _err("error: Failed to merge in the changes.")
        return 1
    return 0


def _am_emit_merge_messages(result, branch2: str) -> None:
    # Mirror merge_switch_to_result -> merge_display_update_messages: print the
    # ort engine's recorded "Auto-merging"/"CONFLICT (...)" message text in the
    # order it produced (already sorted by path in _ort_result).  This carries
    # the proper conflict reason (add/add, content, submodule, ...) instead of
    # hardcoding "content".
    for _primary, _type_str, message, _paths in result.messages:
        _print(message)


def _am_threeway_namestatus(repo: Repository, our_tree: str, base_tree: str) -> None:
    """Print the A/M name-status of HEAD vs the fake-ancestor base, mirroring
    fall_back_threeway's run_diff_index(rev, DIFF_INDEX_CACHED) with the A+M
    filter (DIFF_FORMAT_NAME_STATUS).

    That call diffs the HEAD *tree* against the fake-ancestor *index*, so the
    status convention follows diff-index --cached HEAD: a path present in the
    index (fake ancestor) but not in the tree (HEAD) is 'A'; present in both
    with a different blob is 'M'; present in the tree but not the index is 'D'
    (filtered out by the A+M filter). For an add-only patch the fake ancestor
    skips new files (build_fake_ancestor: `if (0 < patch->is_new) continue;`),
    so the index has no entry for them and nothing is printed."""
    our = {p: (m, s) for p, m, s in workdir.iter_tree_files(repo, our_tree)} if our_tree != _EMPTY_TREE_SHA else {}
    base = {p: (m, s) for p, m, s in workdir.iter_tree_files(repo, base_tree)} if base_tree != _EMPTY_TREE_SHA else {}
    rows = []
    for p in set(our) | set(base):
        if p in base and p not in our:
            rows.append(("A", p))
        elif p in base and p in our and our[p][1] != base[p][1]:
            rows.append(("M", p))
    rows.sort(key=lambda r: r[1])
    for status, p in rows:
        _print(f"{status}\t{p}")


def _am_build_fake_ancestor(repo: Repository, patches) -> Optional[str]:
    """Port of build_fake_ancestor(): construct a tree from the patch index
    lines (preimage blobs).  Returns the tree sha, or None on failure."""
    from .index import Index, IndexEntry, write_index, read_index
    entries: list = []
    for patch in patches:
        name = patch.old_name if patch.old_name else patch.new_name
        if patch.is_new and patch.is_new > 0:
            continue
        oid = None
        prefix = patch.old_oid_prefix
        if prefix:
            full = _am_resolve_blob_prefix(repo, prefix)
            if full is not None:
                oid = full
        if oid is None:
            if not patch.lines_added and not patch.lines_deleted:
                # mode-only change: use current HEAD blob
                head_sym, head = refs_mod.read_head(repo)
                if head:
                    head_tree = objs.parse_commit(objs.read_object(repo, head)[1]).tree
                    for p, m, s in workdir.iter_tree_files(repo, head_tree):
                        if p == name:
                            oid = s
                            break
                if oid is None:
                    return None
            else:
                return None  # "sha1 information is lacking or useless"
        mode = patch.old_mode or 0o100644
        entries.append(IndexEntry(mode=mode, sha=oid, path=name))
    # build a tree from these entries without disturbing the real index
    saved = read_index(repo) if (repo.gitdir / "index").exists() else None
    tmp = Index()
    tmp.entries = entries
    write_index(repo, tmp)
    try:
        tree = workdir.write_tree(repo)
    finally:
        if saved is not None:
            write_index(repo, saved)
        else:
            (repo.gitdir / "index").unlink(missing_ok=True)
    return tree


def _am_resolve_blob_prefix(repo: Repository, prefix: str) -> Optional[str]:
    """Resolve an abbreviated blob oid (the patch index line's old side)."""
    if objs.object_exists(repo, prefix):
        return prefix
    # search loose + packed for a unique blob with this prefix
    try:
        full = refs_mod.rev_parse(repo, prefix)
    except Exception:
        full = None
    if full and objs.object_exists(repo, full):
        return full
    return None


def _am_apply_to_tree(repo: Repository, state: "_AmState", base_tree: str) -> Optional[str]:
    """Apply the state patch onto ``base_tree`` (cached, no worktree), returning
    the resulting tree sha; None on failure.  Mirrors run_apply() to a temp
    index built from base_tree."""
    from . import apply as apply_mod
    from .index import Index, IndexEntry, write_index, read_index
    saved = read_index(repo) if (repo.gitdir / "index").exists() else None
    base = Index()
    if base_tree != _EMPTY_TREE_SHA:
        for p, mode, sha in workdir.iter_tree_files(repo, base_tree):
            base.entries.append(IndexEntry(mode=int(mode, 8), sha=sha, path=p))
    write_index(repo, base)
    try:
        text = state.path("patch").read_bytes()
        pif = str(state.path("patch"))
        opts_kw = _am_apply_opts(state)
        p_value = opts_kw.pop("_p_value", None)
        try:
            patches = apply_mod.parse_patches(text, p_value, patch_input_file=pif,
                                              recount=False)
        except apply_mod.ApplyError:
            return None
        # builtin/am.c fall_back_threeway calls run_apply(state, index_path)
        # with index_file set, so this attempt is NOT silenced: the underlying
        # "patch failed" / "does not apply" errors print here, before the
        # caller's "Did you hand edit your patch?" message (verbosity 0).
        opts = apply_mod.ApplyOpts(p_value=p_value, cached=True, check_index=True,
                                   verbosity=0, **opts_kw)
        rc = apply_mod.check_and_apply(repo, patches, opts, pif)
        if rc != 0:
            return None
        tree = workdir.write_tree(repo)
    finally:
        if saved is not None:
            write_index(repo, saved)
        else:
            (repo.gitdir / "index").unlink(missing_ok=True)
    return tree


def _run_hook(repo: Repository, name: str, *args: str) -> int:
    """Run a repository hook if present and executable.  Returns its exit code
    (0 when there is no hook)."""
    hook = repo.gitdir / "hooks" / name
    if not hook.exists() or not os.access(hook, os.X_OK):
        return 0
    import subprocess
    try:
        return subprocess.call([str(hook), *args], cwd=str(repo.path))
    except OSError:
        return 0


def _am_run_applypatch_msg_hook(repo: Repository, state: "_AmState") -> int:
    """Port of run_applypatch_msg_hook(): run applypatch-msg on the final-commit
    file (unless --no-verify), then re-read the (possibly rewritten) message.
    Returns the hook's exit code; nonzero aborts the am session."""
    ret = 0
    if not state.no_verify:
        ret = _run_hook(repo, "applypatch-msg", _am_state_rel(state, "final-commit"))
    if not ret:
        fc = state.path("final-commit")
        if not fc.exists():
            _err(f"fatal: '{_am_state_rel(state, 'final-commit')}' was deleted "
                 "by the applypatch-msg hook")
            raise _AmAbort(128)
        state.msg = fc.read_text(encoding="utf-8", errors="surrogateescape")
    return ret


_CLEAN_USAGE = (
    "usage: git clean [-d] [-f] [-i] [-n] [-q] [-e <pattern>] "
    "[-x | -X] [--] [<pathspec>...]\n"
    "\n"
    "    -q, --[no-]quiet      do not print names of files removed\n"
    "    -n, --[no-]dry-run    dry run\n"
    "    -f, --[no-]force      force\n"
    "    -i, --[no-]interactive\n"
    "                          interactive cleaning\n"
    "    -d                    remove whole directories\n"
    "    -e, --exclude <pattern>\n"
    "                          add <pattern> to ignore rules\n"
    "    -x                    remove ignored files, too\n"
    "    -X                    remove only ignored files\n"
    "\n"
)


def _is_nonbare_repository_dir(full: Path) -> bool:
    """Port of setup.c is_nonbare_repository_dir: <dir>/.git is a gitfile
    ('gitdir: ...') or a git directory (HEAD + objects + refs)."""
    dotgit = full / ".git"
    if dotgit.is_file():
        try:
            return dotgit.read_bytes().startswith(b"gitdir:")
        except OSError:
            # READ_GITFILE_ERR_OPEN/READ_FAILED still counts as a repo.
            return True
    if dotgit.is_dir():
        return ((dotgit / "HEAD").exists()
                and (dotgit / "objects").is_dir()
                and (dotgit / "refs").is_dir())
    return False


def cmd_clean(argv: list[str]) -> int:
    from . import ignore as ignore_mod

    force = 0
    remove_dirs = False
    dry_run = False
    quiet = False
    ignored = False        # -x: also clean ignored files
    ignored_only = False   # -X: clean only ignored files
    exclude_patterns: list[str] = []
    pathspecs: list[str] = []

    # Hand-rolled option parsing to reproduce C Git's parse-options error
    # messages (rc 129 + usage block) and the -x/-X conflict (rc 128).
    def _unknown_opt(msg: str) -> int:
        sys.stderr.write(f"error: {msg}\n")
        sys.stderr.write(_CLEAN_USAGE)
        return 129

    def _needs_value(msg: str) -> int:
        # parse-options' "requires a value" diagnostics print no usage block.
        sys.stderr.write(f"error: {msg}\n")
        return 129

    # Long-option table mirroring parse_options().  Positive options accept
    # unique-prefix abbreviation; their "--no-" negations are accepted only in
    # full form (the exotic abbreviated-negation ambiguity diagnostics that C
    # Git's parse-options emits are intentionally not reproduced here).
    _long_bools = ("quiet", "dry-run", "force", "interactive")
    _long_value = ("exclude",)
    _positives = list(_long_bools) + list(_long_value)

    def _resolve_long(name: str):
        """Return (canonical, negated) or None when unknown.  On ambiguity it
        writes C Git's ``ambiguous option`` diagnostic and returns ('__ambig__',
        False)."""
        if name.startswith("no-") and name[3:] in _long_bools:
            return (name[3:], True)
        if name in _positives:
            return (name, False)
        matches = [c for c in _positives if c.startswith(name)]
        if len(matches) == 1:
            return (matches[0], False)
        if len(matches) > 1:
            joined = " or ".join("--" + m for m in matches)
            sys.stderr.write(
                f"error: ambiguous option: {name} (could be {joined})\n")
            return ("__ambig__", False)
        return None

    i = 0
    n = len(argv)
    saw_dd = False
    while i < n:
        a = argv[i]
        if saw_dd:
            pathspecs.append(a)
            i += 1
            continue
        if a == "--":
            saw_dd = True
            i += 1
            continue
        if a.startswith("--"):
            name, _, val = a[2:].partition("=")
            has_val = "=" in a
            res = _resolve_long(name)
            if res is None:
                return _unknown_opt(f"unknown option `{name}'")
            canon, negated = res
            if canon == "__ambig__":
                return 129
            if canon == "exclude":
                if negated:    # cannot happen (NONEG), but guard anyway
                    return _unknown_opt(f"unknown option `{name}'")
                if not has_val:
                    if i + 1 >= n:
                        return _needs_value("option `exclude' requires a value")
                    val = argv[i + 1]
                    i += 1
                exclude_patterns.append(val)
            elif canon == "force":
                force = 0 if negated else force + 1
            elif canon == "dry-run":
                dry_run = not negated
            elif canon == "quiet":
                quiet = not negated
            elif canon == "interactive":
                if negated:
                    pass  # --no-interactive: interactive stays off (default)
                else:
                    # Interactive cleaning needs a TTY/editor loop; unsupported.
                    _err("fatal: interactive clean (-i/--interactive) is not "
                         "supported")
                    return 128
            i += 1
            continue
        if a.startswith("-") and a != "-":
            j = 1
            consumed_next = False
            while j < len(a):
                c = a[j]
                if c == "f":
                    force += 1
                elif c == "d":
                    remove_dirs = True
                elif c == "n":
                    dry_run = True
                elif c == "q":
                    quiet = True
                elif c == "x":
                    ignored = True
                elif c == "X":
                    ignored_only = True
                elif c == "i":
                    _err("fatal: interactive clean (-i/--interactive) is not "
                         "supported")
                    return 128
                elif c == "e":
                    rest = a[j + 1:]
                    if rest:
                        exclude_patterns.append(rest)
                    else:
                        if i + 1 >= n:
                            return _needs_value("switch `e' requires a value")
                        exclude_patterns.append(argv[i + 1])
                        consumed_next = True
                    break
                else:
                    return _unknown_opt(f"unknown switch `{c}'")
                j += 1
            i += 2 if consumed_next else 1
            continue
        pathspecs.append(a)
        i += 1

    repo = _repo()

    if ignored and ignored_only:
        _err(_incompatible_opts(["-x", "-X"]))
        return 128

    if force == 0 and not dry_run:
        # clean.requireForce defaults to true; refuse without -f/-n.
        _err("fatal: clean.requireForce is true and -f not given: "
             "refusing to clean")
        return 128

    # Pathspec-limited cleaning. builtin/clean.c parses the trailing args as a
    # PATHSPEC_PREFER_CWD pathspec and passes it to fill_directory, so only
    # untracked paths matching the pathspec are removed. Normalize each pattern
    # against the current prefix (cwd relative to the worktree root) and build a
    # matcher mirroring match_pathspec_item().
    prefix = ""
    try:
        rel_cwd = os.path.relpath(os.getcwd(), repo.path)
    except ValueError:
        rel_cwd = "."
    if rel_cwd not in (".", ""):
        prefix = rel_cwd.replace(os.sep, "/").rstrip("/") + "/"

    ps_items: list[tuple[str, int]] = []  # (match, nowildcard_len)
    if pathspecs:
        for raw in pathspecs:
            pat = raw.replace(os.sep, "/")
            # Strip a leading "./" and resolve against the cwd prefix.
            if pat.startswith("./"):
                pat = pat[2:]
            if pat == ".":
                pat = ""
            full = (prefix + pat) if not pat.startswith("/") else pat.lstrip("/")
            full = full.rstrip("/")
            # nowildcard_len: index of the first glob metacharacter.
            nw = len(full)
            for k, ch in enumerate(full):
                if ch in "*?[":
                    nw = k
                    break
            ps_items.append((full, nw))

    import fnmatch as _fnmatch

    # Match level constants (subset of dir.c).
    M_NONE, M_RECURSIVE, M_EXACT, M_FNMATCH, M_LEADING = 0, 1, 2, 3, 4

    def _match_item(match: str, nowild: int, name: str, is_dir: bool) -> int:
        matchlen = len(match)
        namelen = len(name)
        if not match:  # empty pathspec matches everything (recursively)
            return M_RECURSIVE
        if matchlen <= namelen and name[:matchlen] == match:
            if matchlen == namelen:
                return M_EXACT
            if name[matchlen] == "/":
                return M_RECURSIVE
        elif is_dir and namelen == matchlen - 1 and match[-1] == "/" \
                and match[:namelen] == name:
            return M_EXACT
        # fnmatch on the wildcard portion.
        if nowild < matchlen and _fnmatch.fnmatchcase(name, match):
            return M_FNMATCH
        # Leading-pathspec check (for directories: descend into them).
        offset = 1 if name.endswith("/") else 0
        if namelen < matchlen and match[namelen - offset:namelen - offset + 1] == "/" \
                and match[:namelen] == name:
            return M_LEADING
        if nowild < matchlen:
            # name matched up to the first wildcard -> potential descent.
            if match[:nowild] == name[:nowild] or (nowild and name.startswith(match[:nowild])):
                return M_LEADING
        return M_NONE

    def _ps_match(name: str, is_dir: bool) -> int:
        """Best match level of `name` (worktree-relative) over all pathspecs."""
        if not ps_items:
            return M_RECURSIVE
        best = M_NONE
        for match, nowild in ps_items:
            lvl = _match_item(match, nowild, name, is_dir)
            if lvl == M_NONE:
                continue
            # EXACT/RECURSIVE/FNMATCH are "real" matches; LEADING means descend.
            if lvl in (M_EXACT, M_RECURSIVE, M_FNMATCH):
                return M_RECURSIVE
            best = max(best, M_LEADING)
        return best

    # Build the matcher.  Under -x the standard excludes (.gitignore, core
    # excludesfile, info/exclude) are dropped; only the -e patterns remain.
    # Otherwise the standard excludes apply, with -e patterns appended at the
    # end so they take precedence (including negations).
    iset = ignore_mod.IgnoreSet()
    if not ignored:
        iset.rules.extend(ignore_mod.load(repo.path).rules)
    for pat in exclude_patterns:
        iset.rules.append(ignore_mod.IgnoreRule(pat, "", "command-line", 0))

    tracked = workdir.tracked_paths(repo)
    tracked_dirs: set[str] = set()
    for t in tracked:
        parts = t.split("/")
        for k in range(1, len(parts)):
            tracked_dirs.add("/".join(parts[:k]))

    def is_ignored(rel: str, is_dir: bool) -> bool:
        return iset.is_ignored(rel, is_dir=is_dir)

    def walk(rel_dir: str, dir_is_ignored: bool, dir_matched: bool,
             dir_explicit: bool):
        """Recurse one directory.  Returns (collapsible, has_tracked, my_targets):

        * ``collapsible`` -- the whole directory could be removed as a single
          ``rel_dir/`` entry (subject to ``-d``); the parent decides whether to
          collapse it or keep the individual ``my_targets``.
        * ``has_tracked`` -- the subtree contains a tracked path.
        * ``my_targets`` -- removal targets to use if this directory is *not*
          collapsed.

        ``dir_is_ignored`` says whether ``rel_dir`` itself matched an ignore
        rule; under that condition every descendant counts as ignored.
        ``dir_matched`` says whether ``rel_dir`` already matched a pathspec
        recursively, so every descendant matches without re-checking."""
        base = repo.path / rel_dir if rel_dir else repo.path
        try:
            entries = sorted(os.listdir(base))
        except OSError:
            return (False, False, [])

        has_tracked = False
        has_kept = False          # a path that must be preserved (blocks collapse)
        has_file = False          # any regular file/symlink present
        my_targets: list[str] = []

        for name in entries:
            if name == ".git":
                continue
            rel = f"{rel_dir}/{name}" if rel_dir else name
            full = base / name
            is_dir = workdir._is_dir_no_follow(full)

            if rel in tracked:
                has_tracked = True
                continue

            if is_dir:
                sub_tracked_dir = rel in tracked_dirs
                sub_ignored = dir_is_ignored or is_ignored(rel, True)
                # Pathspec gating: a directory whose ancestor was matched
                # recursively stays matched; otherwise check it. A direct match
                # (exact / recursive / fnmatch on the directory itself) means the
                # whole directory is "explicitly named" and removable even
                # without -d (git removes a pathspec-named directory regardless).
                # A leading match (e.g. pathspec "sub/x") means descend but the
                # directory itself still needs -d. No match -> invisible.
                if dir_matched:
                    # ps_covered: subtree matched (no per-item check needed).
                    # ps_explicit: an actual pathspec named this subtree, which
                    # waives the -d requirement; the no-pathspec default does not.
                    ps_covered, ps_leading = True, False
                    ps_explicit = dir_explicit
                else:
                    ps_lvl = _ps_match(rel, True)
                    ps_covered = ps_lvl == M_RECURSIVE
                    ps_leading = ps_lvl == M_LEADING
                    ps_explicit = ps_covered
                    if ps_lvl == M_NONE:
                        continue
                # A nested non-bare git repository: with force <= 1 the dir walk
                # sets DIR_SKIP_NESTED_GIT, so it returns path_none for the repo
                # — it is invisible to enumeration (neither a target nor a kept
                # path). Physical removal of a parent directory still re-discovers
                # it via remove_dirs and prints "Skipping repository". With -ff
                # it is treated as an ordinary directory.
                if (not sub_tracked_dir and force < 2
                        and _is_nonbare_repository_dir(full)):
                    continue
                # Tracked directories are always descended (to clean their
                # untracked contents).  Untracked directories are descended when
                # -d is given, when explicitly named by a pathspec, or (in -X
                # mode) when not themselves ignored. An ignored directory is an
                # opaque unit: it is only touched with -d.
                descend = (sub_tracked_dir or remove_dirs or ps_explicit
                           or ps_leading
                           or (ignored_only and not sub_ignored))
                if not descend:
                    # Leave the directory untouched; it blocks the parent from
                    # collapsing.
                    has_kept = True
                    continue
                sub_collapsible, sub_has_tracked, sub_targets = walk(
                    rel, sub_ignored, ps_covered, ps_explicit)
                if sub_has_tracked:
                    has_tracked = True
                # Collapse to a single "<dir>/" entry when the directory may be
                # removed wholesale: -d is in effect, or the directory was
                # explicitly named by a pathspec (which waives -d). A leading-only
                # match keeps the individually-matched descendants.
                if (sub_collapsible and not sub_tracked_dir
                        and (remove_dirs or ps_explicit)):
                    my_targets.append(rel + "/")
                else:
                    my_targets.extend(sub_targets)
                    if not sub_collapsible or ps_leading:
                        has_kept = True
                continue

            # Regular file (or symlink).
            has_file = True
            # Pathspec gating for files: a recursively-matched parent dir covers
            # them; otherwise the file must itself match (exact/recursive/glob).
            # A present-but-unmatched file is kept and blocks the directory from
            # collapsing wholesale.
            if not dir_matched and _ps_match(rel, False) != M_RECURSIVE:
                has_kept = True
                continue
            file_ignored = dir_is_ignored or is_ignored(rel, False)
            removable = file_ignored if ignored_only else (not file_ignored)
            if removable:
                my_targets.append(rel)
            else:
                has_kept = True

        # Can this directory be removed as a single unit?
        if has_tracked or has_kept:
            collapsible = False
        elif ignored_only:
            # Collapse only a directory whose entire content is ignored and that
            # contains something (empty dirs never collapse under -X), unless the
            # directory itself is an ignored dir.
            collapsible = dir_is_ignored or has_file or bool(my_targets)
        else:
            # default / -x: any directory with no tracked and no kept content is
            # removable (empty directories included).
            collapsible = True
        return (collapsible, has_tracked, my_targets)

    # With no pathspec the root subtree is implicitly matched (dir_matched), but
    # not "explicit" -- the -d requirement still governs directory removal.
    _, _, targets = walk("", False, not ps_items, False)

    keep_nested = force < 2
    remove_word = "Would remove" if dry_run else "Removing"
    skip_word = "Would skip" if dry_run else "Skipping"

    def remove_dirs_phys(rel: str) -> bool:
        """Physically remove directory <rel> recursively (builtin/clean.c
        remove_dirs). Returns True if the directory is fully gone. A nested
        non-bare repo (with keep_nested) is skipped with a message printed
        inline; on a partial removal the individual removed entries are flushed
        afterwards, mirroring remove_dirs' `dels` list."""
        full = repo.path / rel
        if keep_nested and _is_nonbare_repository_dir(full):
            if not quiet:
                _print(f"{skip_word} repository {rel}")
            return False
        try:
            entries = sorted(os.listdir(full))
        except OSError:
            if not dry_run:
                try:
                    full.rmdir()
                except OSError:
                    return False
            return True
        gone = True
        dels: list[str] = []
        for name in entries:
            child_rel = f"{rel}/{name}"
            child = full / name
            if workdir._is_dir_no_follow(child):
                if remove_dirs_phys(child_rel):
                    dels.append(child_rel + "/")
                else:
                    gone = False
            else:
                if not dry_run:
                    try:
                        child.unlink()
                    except OSError:
                        gone = False
                        continue
                dels.append(child_rel)
        if gone:
            if not dry_run:
                try:
                    full.rmdir()
                except OSError:
                    gone = False
        if not gone and not quiet:
            for d in dels:
                _print(f"{remove_word} {d}")
        return gone

    for target in sorted(targets):
        if target.endswith("/"):
            rel = target.rstrip("/")
            gone = remove_dirs_phys(rel)
            if gone and not quiet:
                _print(f"{remove_word} {target}")
        else:
            if not dry_run:
                full = repo.path / target
                try:
                    full.unlink()
                except OSError:
                    continue
            if not quiet:
                _print(f"{remove_word} {target}")
    return 0


def _describe_contains(repo: Repository, rev: str, sha: str) -> int:
    """``git describe --contains``: name the commit relative to the tag that
    contains it (a descendant tag), delegating to name-rev's tags-only naming.
    Prints ``<tag>^0`` / ``<tag>~N`` or, when no tag contains it, a fatal."""
    target = refs_mod.rev_parse(repo, rev + "^{commit}") or sha
    name_for: dict[str, tuple[str, int]] = {}
    tips: list[tuple[str, str, bool]] = []
    for tag in refs_mod.list_tags(repo):
        raw = refs_mod.read_ref(repo, f"refs/tags/{tag}")
        s = refs_mod.rev_parse(repo, f"refs/tags/{tag}" + "^{commit}") or raw
        if s:
            tips.append((tag, s, s != raw))
    graph = _graph_for_repo(repo)
    for label, tip, deref in tips:
        seen: set[str] = set()
        stack = deque([(tip, 0)])
        while stack:
            csha, depth = stack.popleft()
            if csha in seen:
                continue
            seen.add(csha)
            cur = name_for.get(csha)
            if cur is None or cur[1] > depth:
                suffix = ("^0" if deref else "") if depth == 0 else f"~{depth}"
                name_for[csha] = (label + suffix, depth)
            info = _commit_tree_parents(repo, csha, graph)
            if info is not None:
                for p in info[1]:
                    stack.append((p, depth + 1))
    if target in name_for:
        _print(name_for[target][0])
        return 0
    _err(f"fatal: cannot describe '{target}'")
    return 128


def _describe_dirty(repo: Repository) -> bool:
    """True when the working tree differs from HEAD, matching the semantics of
    `git diff-index --quiet HEAD` (tracked content/mode changes, staged changes,
    and deletions count; untracked files do not)."""
    head = refs_mod.rev_parse(repo, "HEAD")
    if not head:
        return False
    head_tree = _commit_tree(repo, head)
    a_map = _tree_map_full(repo, head_tree)
    from .index import read_index
    idx = read_index(repo).by_path()
    for p in set(a_map) | set(idx):
        a = _side_from_object(repo, *a_map[p]) if p in a_map else _ABSENT
        b_present = p in idx
        b_mode = idx[p].mode_str() if b_present else None
        b_sha = idx[p].sha if b_present else None
        b_dirty = False
        if b_present:
            wt = _side_from_worktree(repo, p)
            if not wt.present:
                b_present, b_mode, b_sha = False, None, None
            else:
                b_dirty = wt.sha != idx[p].sha or wt.mode != b_mode
        if a.present and b_present and a.sha == b_sha and not b_dirty and a.mode == b_mode:
            continue
        if not a.present and not b_present:
            continue
        return True
    return False


_DESCRIBE_PRIO_NAMES = ("head", "lightweight", "annotated")


def _describe_build_names(repo: Repository, *, all_refs: bool, tags_ok: bool,
                          patterns: list[str], exclude: list[str]
                          ) -> dict[str, tuple[str, int]]:
    """Port of builtin/describe.c get_name/add_to_known_names: build a map from a
    commit oid to (name, prio) — the best ref naming that commit. prio: annotated
    tag=2, lightweight tag=1, other ref (only with --all)=0. Iterates refs in
    sorted refname order so ties at equal prio keep the first-seen path (matching
    refs_for_each_ref_ext)."""
    import fnmatch as _fn

    def _tagger_date(oid: str) -> int:
        try:
            t, d = objs.read_object(repo, oid)
        except KeyError:
            return 0
        if t != "tag":
            return 0
        import re as _re
        for line in d.decode("utf-8", "replace").splitlines():
            if line.startswith("tagger "):
                m = _re.search(r" (\d+) [+-]\d{4}\s*$", line)
                return int(m.group(1)) if m else 0
            if line == "":
                break
        return 0

    # Collect (refname, oid) in the order C iterates: refs/heads, refs/remotes,
    # refs/tags all in one sorted-by-full-refname stream.
    refs: list[tuple[str, str]] = []
    for tag in refs_mod.list_tags(repo):
        refs.append((f"refs/tags/{tag}", refs_mod.read_ref(repo, f"refs/tags/{tag}")))
    if all_refs:
        for b in refs_mod.list_branches(repo):
            refs.append((f"refs/heads/{b}", refs_mod.read_ref(repo, f"refs/heads/{b}")))
        for rb in _remote_branches(repo):
            refs.append((f"refs/remotes/{rb}", refs_mod.read_ref(repo, f"refs/remotes/{rb}")))
    refs.sort(key=lambda r: r[0])

    names: dict[str, tuple[str, int, str]] = {}  # peeled -> (path, prio, tag_oid)
    for refname, oid in refs:
        if oid is None:
            continue
        is_tag = refname.startswith("refs/tags/")
        if is_tag:
            path_to_match = refname[len("refs/tags/"):]
        elif all_refs:
            path_to_match = None
            if exclude or patterns:
                if refname.startswith("refs/heads/"):
                    path_to_match = refname[len("refs/heads/"):]
                elif refname.startswith("refs/remotes/"):
                    path_to_match = refname[len("refs/remotes/"):]
                else:
                    continue
        else:
            continue
        if exclude and path_to_match is not None:
            if any(_fn.fnmatch(path_to_match, pat) for pat in exclude):
                continue
        if patterns and path_to_match is not None:
            if not any(_fn.fnmatch(path_to_match, pat) for pat in patterns):
                continue
        # Peel and detect annotation.
        try:
            otype, _ = objs.read_object(repo, oid)
        except KeyError:
            continue
        if otype == "tag":
            peeled = refs_mod.rev_parse(repo, oid + "^{commit}") or oid
            is_annotated = peeled != oid
        else:
            peeled = oid
            is_annotated = False
        prio = 2 if is_annotated else (1 if is_tag else 0)
        path = (refname[len("refs/"):] if all_refs else refname[len("refs/tags/"):])
        # replace_name: keep higher prio; for two prio-2, keep later tagger date.
        cur = names.get(peeled)
        if cur is None or cur[1] < prio:
            names[peeled] = (path, prio, oid)
        elif cur[1] == 2 and prio == 2:
            if _tagger_date(cur[2]) < _tagger_date(oid):
                names[peeled] = (path, prio, oid)
    return {k: (v[0], v[1]) for k, v in names.items()}


def _describe_commit(repo: Repository, cmit: str, *, names: dict,
                     max_candidates: int, abbrev: int, longformat: bool,
                     first_parent: bool, always: bool, suffix: str,
                     debug: bool, arg: str) -> tuple[Optional[str], list[str], Optional[str]]:
    """Faithful port of builtin/describe.c describe_commit(). Returns
    (result_or_None, debug_stderr_lines, error_or_None). The BFS uses a date
    priority queue (newer first, FIFO on ties) exactly like C's lazy_queue."""
    import heapq

    dbg: list[str] = []
    if debug:
        dbg.append(f"describe {arg}")
    # Exact match (depth 0): only when --tags/--all, or the name is an annotated
    # tag (prio 2). A lightweight tag (prio 1) without --tags does not count.
    if cmit in names:
        path, prio = names[cmit]
        if allow_lightweight_state["tags"] or allow_lightweight_state["all"] or prio == 2:
            if longformat:
                ab = max(4, abbrev) if abbrev else 0
                return (f"{path}-0-g{cmit[:ab]}{suffix}", dbg, None)
            return (f"{path}{suffix}", dbg, None)
    if not max_candidates:
        return (None, dbg, f"fatal: no tag exactly matches '{cmit}'")
    if debug:
        dbg.append("No exact match on refs or tags, searching to describe")

    # BFS state.
    flags: dict[str, int] = {}
    SEEN = 1
    date_of: dict[str, int] = {}

    def date(c: str) -> int:
        if c not in date_of:
            date_of[c] = _commit_date(repo, c)
        return date_of[c]

    # Priority queue entries: (-date, ctr, commit). Heap pops smallest => newest
    # date first, FIFO on equal dates.
    heap: list[tuple[int, int, str]] = []
    ctr = 0

    # lazy_queue: get peeks the root without removing; the next put replaces it.
    # We emulate by tracking get_pending + the peeked root.
    get_pending = [False]

    def lq_put(c: str):
        nonlocal ctr
        if get_pending[0] and heap:
            # replace root: pop then push
            heapq.heapreplace(heap, (-date(c), ctr, c))
        else:
            heapq.heappush(heap, (-date(c), ctr, c))
        ctr += 1
        get_pending[0] = False

    def lq_get() -> str:
        if get_pending[0]:
            heapq.heappop(heap)
        else:
            get_pending[0] = True
        return heap[0][2]

    def lq_empty() -> bool:
        return len(heap) == (1 if get_pending[0] else 0)

    all_matches: list[dict] = []  # {name(path),prio,depth,flag_within,found_order}
    match_cnt = 0
    annotated_cnt = 0
    unannotated_cnt = 0
    seen_commits = 0
    gave_up_on: Optional[str] = None

    flags[cmit] = SEEN
    lq_put(cmit)
    while not lq_empty():
        c = lq_get()
        info = _commit_tree_parents(repo, c)
        parents = list(info[1]) if info else []
        seen_commits += 1
        if match_cnt == max_candidates or match_cnt == len(names):
            gave_up_on = c
            break
        n = names.get(c)
        if n is not None:
            path, prio = n
            if (not allow_lightweight_state["tags"]) and (not allow_lightweight_state["all"]) and prio < 2:
                unannotated_cnt += 1
            elif match_cnt < max_candidates:
                fw = 1 << (match_cnt + 1)
                all_matches.append({"name": path, "prio": prio, "depth": seen_commits - 1,
                                    "flag_within": fw, "found_order": match_cnt + 1})
                flags[c] = flags.get(c, 0) | fw
                match_cnt += 1
                if prio == 2:
                    annotated_cnt += 1
        for t in all_matches:
            if not (flags.get(c, 0) & t["flag_within"]):
                t["depth"] += 1
        if annotated_cnt and lq_empty():
            best_depth = None
            best_within = 0
            for t in all_matches:
                if best_depth is None or t["depth"] < best_depth:
                    best_depth = t["depth"]
                    best_within = t["flag_within"]
                elif t["depth"] == best_depth:
                    best_within |= t["flag_within"]
            if (flags.get(c, 0) & best_within) == best_within:
                if debug:
                    dbg.append(f"finished search at {c}")
                break
        for p in parents:
            if not (flags.get(p, 0) & SEEN):
                lq_put(p)
            flags[p] = flags.get(p, 0) | flags.get(c, 0)
            if first_parent:
                break

    if not match_cnt:
        if always:
            ab = max(4, abbrev) if abbrev else 7
            return ((cmit[:ab] if abbrev else cmit[:7]) + suffix, dbg, None)
        if unannotated_cnt:
            return (None, dbg, f"fatal: No annotated tags can describe '{cmit}'.\n"
                    "However, there were unannotated tags: try --tags.")
        return (None, dbg, f"fatal: No tags can describe '{cmit}'.\n"
                "Try --always, or create some tags.")

    all_matches.sort(key=lambda t: (t["depth"], t["found_order"]))

    # finish_depth_computation for the best match.
    best = all_matches[0]
    if gave_up_on is not None:
        lq_put(gave_up_on)
        seen_commits -= 1
    seen_commits += _describe_finish_depth(repo, heap, get_pending, flags, best, date)

    if debug:
        label_width = max(len(s) for s in _DESCRIBE_PRIO_NAMES)
        for t in all_matches:
            dbg.append(f" {_DESCRIBE_PRIO_NAMES[t['prio']]:<{label_width}} {t['depth']:8d} {t['name']}")
        dbg.append(f"traversed {seen_commits} commits")

    name = best["name"]
    depth = best["depth"]
    if abbrev == 0:
        return (f"{name}{suffix}", dbg, None)
    if depth == 0 and not longformat:
        return (f"{name}{suffix}", dbg, None)
    ab = max(4, abbrev)
    return (f"{name}-{depth}-g{cmit[:ab]}{suffix}", dbg, None)


# describe() reads tags/all flags via this dict so the BFS can see them without
# threading two more parameters through every helper call.
allow_lightweight_state = {"tags": False, "all": False}


def _describe_finish_depth(repo: Repository, heap, get_pending, flags, best, date_fn) -> int:
    import heapq
    SEEN = 1
    seen_commits = 0
    fw = best["flag_within"]
    # unflagged = queued commits not carrying the best flag.
    start = 1 if get_pending[0] else 0
    unflagged = set()
    for i in range(start, len(heap)):
        c = heap[i][2]
        if not (flags.get(c, 0) & fw):
            unflagged.add(c)

    def lq_get() -> Optional[str]:
        if get_pending[0]:
            heapq.heappop(heap)
        else:
            get_pending[0] = True
        return heap[0][2] if heap else None

    def lq_empty() -> bool:
        return len(heap) == (1 if get_pending[0] else 0)

    ctr_box = [10 ** 9]

    def lq_put(c: str):
        if get_pending[0] and heap:
            heapq.heapreplace(heap, (-date_fn(c), ctr_box[0], c))
        else:
            heapq.heappush(heap, (-date_fn(c), ctr_box[0], c))
        ctr_box[0] += 1
        get_pending[0] = False

    while not lq_empty():
        c = lq_get()
        if c is None:
            break
        info = _commit_tree_parents(repo, c)
        parents = list(info[1]) if info else []
        seen_commits += 1
        if flags.get(c, 0) & fw:
            if not unflagged:
                break
        else:
            unflagged.discard(c)
            best["depth"] += 1
        for p in parents:
            seen = flags.get(p, 0) & SEEN
            if not seen:
                lq_put(p)
            flag_before = flags.get(p, 0) & fw
            flags[p] = flags.get(p, 0) | flags.get(c, 0)
            flag_after = flags.get(p, 0) & fw
            if (not seen) and (not flag_after):
                unflagged.add(p)
            if seen and (not flag_before) and flag_after:
                unflagged.discard(p)
    return seen_commits


def cmd_describe(argv: list[str]) -> int:
    # --dirty/--broken take an optional value only via "=<mark>" (a bare flag uses
    # the default "-dirty"/"-broken"); unlike argparse's nargs="?", git never
    # consumes the following token as the mark. Strip them out before argparse so a
    # trailing commit-ish stays a positional.
    dirty: Optional[str] = None
    broken: Optional[str] = None
    rest: list[str] = []
    for tok in argv:
        if tok == "--dirty":
            dirty = "-dirty"
        elif tok.startswith("--dirty="):
            dirty = tok[len("--dirty="):]
        elif tok == "--broken":
            broken = "-broken"
        elif tok.startswith("--broken="):
            broken = tok[len("--broken="):]
        else:
            rest.append(tok)
    ap = argparse.ArgumentParser(prog="pygit describe", add_help=False)
    ap.add_argument("--tags", action="store_true")
    ap.add_argument("--all", action="store_true")
    ap.add_argument("--contains", action="store_true")
    ap.add_argument("--always", action="store_true")
    ap.add_argument("--long", action="store_true")
    ap.add_argument("--first-parent", dest="first_parent", action="store_true")
    ap.add_argument("--debug", action="store_true")
    ap.add_argument("--candidates", type=int, default=10)
    # OPT__ABBREV: --abbrev[=<n>] (default 7), --no-abbrev => 0.
    ap.add_argument("--abbrev", nargs="?", const="7", default=None)
    ap.add_argument("--no-abbrev", dest="no_abbrev", action="store_true")
    # OPT_CALLBACK_F exact-match sets max_candidates=0.
    ap.add_argument("--exact-match", dest="exact_match", action="store_true")
    ap.add_argument("--match", action="append", default=None)
    ap.add_argument("--exclude", action="append", default=None)
    ap.add_argument("revs", nargs="*")
    args = ap.parse_args(rest)
    args.dirty = dirty
    args.broken = broken
    # --no-abbrev => 0; bare --abbrev => 7; numeric value parsed; default 7.
    if args.no_abbrev:
        args.abbrev = 0
    elif args.abbrev is None:
        args.abbrev = 7
    else:
        try:
            args.abbrev = int(args.abbrev)
        except ValueError:
            args.abbrev = 7
    # OPT_INTEGER candidates: negatives clamp to 0; exact-match forces 0.
    if args.candidates < 0:
        args.candidates = 0
    if args.exact_match:
        args.candidates = 0
    # --long with --abbrev=0 is a usage error.
    if args.long and args.abbrev == 0:
        _err("fatal: options '--long' and '--abbrev=0' cannot be used together")
        return 128
    repo = _repo()
    revs = args.revs
    if (args.dirty is not None or args.broken is not None) and revs:
        which = "--dirty" if args.dirty is not None else "--broken"
        _err(f"fatal: option '{which}' and commit-ishes cannot be used together")
        return 128
    # --contains delegates to name-rev (handled per-rev below). Keep the
    # single-positional shim for the existing contains path.
    args.rev = revs[0] if revs else None
    suffix = ""
    if args.dirty is not None and _describe_dirty(repo):
        suffix = args.dirty
    if args.rev is None:
        args.rev = "HEAD"
    sha = refs_mod.rev_parse(repo, args.rev)
    if not sha:
        _err(f"fatal: Not a valid object name {args.rev}")
        return 128
    if args.contains:
        return _describe_contains(repo, args.rev, sha)
    # Faithful describe path (non --all, non --contains): port describe.c BFS.
    if not args.all:
        names = _describe_build_names(
            repo, all_refs=False, tags_ok=args.tags,
            patterns=args.match or [], exclude=args.exclude or [])
        if not names and not args.always:
            _err("fatal: No names found, cannot describe anything.")
            return 128
        allow_lightweight_state["tags"] = args.tags
        allow_lightweight_state["all"] = False
        targets = revs if revs else ["HEAD"]
        rc = 0
        for r in targets:
            rsha = refs_mod.rev_parse(repo, r)
            if not rsha:
                _err(f"fatal: Not a valid object name {r}")
                return 128
            csha = refs_mod.rev_parse(repo, r + "^{commit}") or rsha
            result, dbg, errmsg = _describe_commit(
                repo, csha, names=names, max_candidates=args.candidates,
                abbrev=args.abbrev, longformat=args.long,
                first_parent=args.first_parent, always=args.always,
                suffix=suffix, debug=args.debug, arg=r)
            if args.debug:
                for line in dbg:
                    _err(line)
            if errmsg is not None:
                _err(errmsg)
                rc = 128
                continue
            _print(result)
        return rc
    # Peel the target down to a commit (an annotated tag resolves to its object).
    sha = refs_mod.rev_parse(repo, args.rev + "^{commit}") or sha
    tag_for: dict[str, str] = {}
    unann_commits: set[str] = set()
    any_tags = False
    if args.all:
        # --all considers every ref, named with its namespace (tags/, heads/,
        # remotes/). Tags are seeded first so they win ties at equal depth.
        for tag in refs_mod.list_tags(repo):
            tc = refs_mod.rev_parse(repo, f"refs/tags/{tag}^{{commit}}") or refs_mod.read_ref(repo, f"refs/tags/{tag}")
            if tc:
                tag_for.setdefault(tc, f"tags/{tag}")
        for b in refs_mod.list_branches(repo):
            s = refs_mod.read_ref(repo, f"refs/heads/{b}")
            if s:
                tag_for.setdefault(s, f"heads/{b}")
        for rb in _remote_branches(repo):
            s = refs_mod.read_ref(repo, f"refs/remotes/{rb}")
            if s:
                tag_for.setdefault(s, f"remotes/{rb}")
        any_tags = bool(tag_for)
        graph = _graph_for_repo(repo)

        def _reach_all(start: str) -> set:
            out: set[str] = set()
            stack = [start]
            while stack:
                x = stack.pop()
                if x in out:
                    continue
                out.add(x)
                info = _commit_tree_parents(repo, x, graph)
                if info:
                    stack.extend(info[1])
            return out

        reach_sha = _reach_all(sha)
        # --candidates<=0: only an exact ref/tag match is allowed.
        if args.candidates <= 0:
            ab = max(4, args.abbrev) if args.abbrev else 0
            exact = next((name for tc, name in tag_for.items() if tc == sha), None)
            if exact is not None:
                if args.long and args.abbrev != 0:
                    _print(f"{exact}-0-g{sha[:ab]}{suffix}")
                else:
                    _print(exact + suffix)
                return 0
            _err(f"fatal: no tag exactly matches '{sha}'")
            return 128
        candidates = [(tc, name) for tc, name in tag_for.items() if tc in reach_sha]
        if candidates:
            best = None
            for tc, name in candidates:
                depth = len(reach_sha - _reach_all(tc))
                if best is None or depth < best[0]:
                    best = (depth, tc, name)
            depth, tc, name = best
            ab = max(4, args.abbrev) if args.abbrev else 0
            if args.abbrev == 0 or (depth == 0 and not args.long):
                _print(name + suffix)
            else:
                _print(f"{name}-{depth}-g{sha[:ab]}{suffix}")
            return 0
        if args.always:
            _print((sha[:max(4, args.abbrev)] if args.abbrev else sha[:7]) + suffix)
            return 0
        if any_tags:
            _err(f"fatal: No tags can describe '{sha}'.")
            _err("Try --always, or create some tags.")
        else:
            _err("fatal: No names found, cannot describe anything.")
        return 128
    for tag in refs_mod.list_tags(repo):
        ts = refs_mod.read_ref(repo, f"refs/tags/{tag}")
        if not ts:
            continue
        any_tags = True
        annotated = False
        try:
            t, d = objs.read_object(repo, ts)
            if t == "tag":
                annotated = True
                for line in d.decode(errors="replace").splitlines():
                    if line.startswith("object "):
                        ts = line[len("object "):].strip()
                        break
        except KeyError:
            pass
        if not annotated:
            unann_commits.add(ts)
            if not args.tags:
                continue
        tag_for[ts] = tag
    graph = _graph_for_repo(repo)

    def _reachable(start: str) -> set:
        out: set[str] = set()
        stack = [start]
        while stack:
            x = stack.pop()
            if x in out:
                continue
            out.add(x)
            info = _commit_tree_parents(repo, x, graph)
            if info:
                stack.extend(info[1])
        return out

    reach_sha = _reachable(sha)
    # --candidates=N caps how many tags describe considers; N<=0 means "only an
    # exact match", so a commit with no tag pointing exactly at it fails with
    # "no tag exactly matches '<sha>'" (builtin/describe.c describe_commit).
    if args.candidates <= 0:
        ab = max(4, args.abbrev) if args.abbrev else 0
        exact = next((name for tc, name in tag_for.items() if tc == sha), None)
        if exact is not None:
            if args.long and args.abbrev != 0:
                _print(f"{exact}-0-g{sha[:ab]}{suffix}")
            else:
                _print(exact + suffix)
            return 0
        _err(f"fatal: no tag exactly matches '{sha}'")
        return 128
    # Candidate tags whose commit is an ancestor of the target. git's depth is
    # the number of commits reachable from the target but not from the tag; the
    # best tag minimizes that depth (an exact match has depth 0).
    candidates = [(tc, name) for tc, name in tag_for.items() if tc in reach_sha]
    if candidates:
        best = None  # (depth, tag_commit, name)
        for tc, name in candidates:
            depth = len(reach_sha - _reachable(tc))
            if best is None or depth < best[0]:
                best = (depth, tc, name)
        depth, tc, name = best
        ab = max(4, args.abbrev) if args.abbrev else 0
        if args.abbrev == 0:
            _print(name + suffix)
        elif depth == 0 and not args.long:
            _print(name + suffix)
        else:
            _print(f"{name}-{depth}-g{sha[:ab]}{suffix}")
        return 0
    if args.always:
        _print((sha[:max(4, args.abbrev)] if args.abbrev else sha[:7]) + suffix)
        return 0
    if not args.tags and (unann_commits & reach_sha):
        _err(f"fatal: No annotated tags can describe '{sha}'.")
        _err("However, there were unannotated tags: try --tags.")
    elif any_tags:
        _err(f"fatal: No tags can describe '{sha}'.")
        _err("Try --always, or create some tags.")
    else:
        _err("fatal: No names found, cannot describe anything.")
    return 128


_BLAME_USAGE = (
    "usage: git blame [<options>] [<rev-opts>] [<rev>] [--] <file>\n"
    "\n"
    "    <rev-opts> are documented in git-rev-list(1)\n"
    "\n"
    "    --[no-]incremental    show blame entries as we find them, incrementally\n"
    "    -b                    do not show object names of boundary commits (Default: off)\n"
    "    --[no-]root           do not treat root commits as boundaries (Default: off)\n"
    "    --[no-]show-stats     show work cost statistics\n"
    "    --[no-]progress       force progress reporting\n"
    "    --[no-]score-debug    show output score for blame entries\n"
    "    -f, --[no-]show-name  show original filename (Default: auto)\n"
    "    -n, --[no-]show-number\n"
    "                          show original linenumber (Default: off)\n"
    "    -p, --[no-]porcelain  show in a format designed for machine consumption\n"
    "    --[no-]line-porcelain show porcelain format with per-line commit information\n"
    "    -c                    use the same output mode as git-annotate (Default: off)\n"
    "    -t                    show raw timestamp (Default: off)\n"
    "    -l                    show long commit SHA1 (Default: off)\n"
    "    -s                    suppress author name and timestamp (Default: off)\n"
    "    -e, --[no-]show-email show author email instead of name (Default: off)\n"
    "    -w                    ignore whitespace differences\n"
    "    --diff-algorithm <algorithm>\n"
    "                          choose a diff algorithm\n"
    "    --[no-]ignore-rev <rev>\n"
    "                          ignore <rev> when blaming\n"
    "    --[no-]ignore-revs-file <file>\n"
    "                          ignore revisions from <file>\n"
    "    --[no-]color-lines    color redundant metadata from previous line differently\n"
    "    --[no-]color-by-age   color lines by age\n"
    "    -S <file>             use revisions from <file> instead of calling git-rev-list\n"
    "    --[no-]contents <file>\n"
    "                          use <file>'s contents as the final image\n"
    "    -C[<score>]           find line copies within and across files\n"
    "    -M[<score>]           find line movements within and across files\n"
    "    -L <range>            process only line range <start>,<end> or function :<funcname>\n"
    "    --[no-]abbrev[=<n>]   use <n> digits to display object names\n"
    "\n"
)


def cmd_blame(argv: list[str], annotate_compat: bool = False) -> int:
    # Manual option scanner mirroring builtin/blame.c parse_options + the
    # "[<rev>] [--] <file>" positional handling (blame accepts an optional
    # starting revision before the file).
    long_sha = False
    line_range = None
    porcelain = False
    line_porcelain = False
    no_author = False        # -s OUTPUT_NO_AUTHOR
    show_email = False       # -e OUTPUT_SHOW_EMAIL
    raw_time = False         # -t OUTPUT_RAW_TIMESTAMP
    show_number = False      # -n OUTPUT_SHOW_NUMBER
    show_name = False        # -f OUTPUT_SHOW_NAME
    annotate_mode = annotate_compat  # -c / annotate
    show_root = False        # --root
    blank_boundary = False   # -b
    incremental = False      # --incremental
    abbrev = None            # --abbrev=<n>
    positionals: list[str] = []
    i = 0
    n = len(argv)
    seen_dd = False
    while i < n:
        a = argv[i]
        if seen_dd:
            positionals.append(a)
            i += 1
            continue
        if a == "--":
            seen_dd = True
            i += 1
            continue
        if a in ("-h", "--help"):
            sys.stdout.write(_BLAME_USAGE)
            return 129
        if a == "-l":
            long_sha = True
        elif a == "-L":
            i += 1
            line_range = argv[i] if i < n else None
        elif a.startswith("-L") and len(a) > 2:
            line_range = a[2:]
        elif a in ("-p", "--porcelain"):
            porcelain = True
        elif a == "--line-porcelain":
            line_porcelain = True
        elif a == "-s":
            no_author = True
        elif a in ("-e", "--show-email"):
            show_email = True
        elif a == "--no-show-email":
            show_email = False
        elif a == "-t":
            raw_time = True
        elif a in ("-n", "--show-number"):
            show_number = True
        elif a in ("-f", "--show-name"):
            show_name = True
        elif a == "-c":
            annotate_mode = True
        elif a == "--root":
            show_root = True
        elif a == "--no-root":
            show_root = False
        elif a == "-b":
            blank_boundary = True
        elif a in ("--incremental",):
            incremental = True
        elif a == "--no-incremental":
            incremental = False
        elif a == "--abbrev":
            abbrev = 7
        elif a.startswith("--abbrev="):
            try:
                abbrev = int(a[len("--abbrev="):])
            except ValueError:
                sys.stderr.write(_BLAME_USAGE)
                return 129
        elif a == "--no-abbrev":
            abbrev = None
        elif a in ("-w", "--minimal", "--progress", "--no-progress",
                   "--show-stats", "--score-debug", "--no-score-debug",
                   "--color-lines", "--no-color-lines", "--color-by-age",
                   "--no-color-by-age"):
            pass  # accepted; no effect on this naive blame
        elif a.startswith("--diff-algorithm") or a.startswith("--ignore-rev") \
                or a.startswith("--ignore-revs-file") or a.startswith("--contents"):
            # Options that take a value; consume the attached/next token.
            if "=" not in a and i + 1 < n:
                i += 1
        elif a.startswith("-M") or a.startswith("-C") or a.startswith("-S"):
            if a in ("-S",) and i + 1 < n:
                i += 1
        elif a.startswith("-") and a != "-":
            if a.startswith("--"):
                _err(f"error: unknown option `{a[2:]}'")
            else:
                _err(f"error: unknown switch `{a[1]}'")
            sys.stderr.write(_BLAME_USAGE)
            return 129
        else:
            positionals.append(a)
        i += 1

    if not positionals:
        sys.stderr.write(_BLAME_USAGE)
        return 129

    repo = _repo()
    # Positional layout: blame [<rev>] <file>  or  blame <file>. The last
    # positional that does not resolve to a revision is the file; a leading
    # token that resolves to a commit/tree is the starting rev.
    rev_arg = None
    path = positionals[-1]
    if len(positionals) >= 2:
        rev_arg = positionals[0]
        path = positionals[-1]

    if rev_arg is not None:
        start = refs_mod.rev_parse(repo, rev_arg)
        if not start:
            _err(f"fatal: revision walk setup failed")
            return 128
        head = refs_mod._peel_to_type(repo, start, "commit") or start
    else:
        head = refs_mod.rev_parse(repo, "HEAD")
    if not head:
        return 128

    # blame.c: a default abbrev is DEFAULT_ABBREV+1 (=8); an explicit --abbrev=N
    # (0 < N < hexsz) is bumped by one so the boundary '^' fits without losing a
    # significant digit.
    if abbrev is None:
        abbrev = 8 if not long_sha else 40
    elif 0 < abbrev < 40:
        abbrev += 1
    # OUTPUT_NO_AUTHOR/etc -> output_option style flags.
    show_raw_time = raw_time

    graph = _graph_for_repo(repo)
    head_info = _commit_tree_parents(repo, head, graph)
    if head_info is None:
        return 128
    head_tree, _head_parents = head_info
    head_entry = workdir.tree_path_entry(repo, head_tree, path)
    if head_entry is None or head_entry.is_dir() or head_entry.is_gitlink():
        _err(f"fatal: no such path '{path}' in {rev_arg or 'HEAD'}")
        return 128
    args = type("A", (), {})()
    args.path = path
    args.long_sha = long_sha
    args.line_range = line_range
    args.porcelain = porcelain
    args.line_porcelain = line_porcelain
    current_text = objs.read_object(repo, head_entry.sha)[1].decode("utf-8", errors="replace")
    cur_lines = current_text.splitlines()
    blame_sha: list[Optional[str]] = [None] * len(cur_lines)
    chain: list[str] = []
    cur = head
    while cur:
        chain.append(cur)
        info = _commit_tree_parents(repo, cur, graph)
        if info is None:
            break
        _tree, parents = info
        if not parents:
            break
        cur = parents[0]
    from .diff import diff_lines
    for i in range(len(chain) - 1):
        newer = chain[i]
        older = chain[i + 1]
        if graph is not None and not graph.maybe_changed(newer, args.path):
            continue
        newer_info = _commit_tree_parents(repo, newer, graph)
        older_info = _commit_tree_parents(repo, older, graph)
        if newer_info is None or older_info is None:
            continue
        n_tree, _n_parents = newer_info
        o_tree, _o_parents = older_info
        n_entry = workdir.tree_path_entry(repo, n_tree, args.path)
        o_entry = workdir.tree_path_entry(repo, o_tree, args.path)
        if n_entry is None or n_entry.is_dir() or n_entry.is_gitlink():
            break
        if o_entry is not None and (o_entry.is_dir() or o_entry.is_gitlink()):
            o_entry = None
        if o_entry is not None and o_entry.sha == n_entry.sha:
            continue
        n_text = objs.read_object(repo, n_entry.sha)[1].decode("utf-8", errors="replace").splitlines()
        o_text = (
            objs.read_object(repo, o_entry.sha)[1].decode("utf-8", errors="replace").splitlines()
            if o_entry is not None else []
        )
        ops = diff_lines(o_text, n_text)
        added = set()
        for kind, ai, bi in ops:
            if kind == "ins":
                added.add(n_text[bi])
        for idx, line in enumerate(cur_lines):
            if blame_sha[idx] is None and line in added:
                blame_sha[idx] = newer
        if all(b is not None for b in blame_sha):
            break
    for idx in range(len(blame_sha)):
        if blame_sha[idx] is None:
            blame_sha[idx] = chain[-1] if chain else head

    # A root commit is normally a boundary (drawn with '^'); --root suppresses
    # that so root commits print like any other.
    def _is_boundary(c) -> bool:
        return (not c.parents) and not show_root

    if args.porcelain or args.line_porcelain:
        def _porc_info(s):
            c = objs.parse_commit(objs.read_object(repo, s)[1])
            awho, a_ts, a_tz = _split_ident(c.author)
            cwho, c_ts, c_tz = _split_ident(c.committer)
            an, ae = _parse_who(awho)
            cn, ce = _parse_who(cwho)
            subj = c.message.splitlines()[0] if c.message.strip() else ""
            blk = [f"author {an}", f"author-mail <{ae}>", f"author-time {a_ts}",
                   f"author-tz {a_tz}", f"committer {cn}", f"committer-mail <{ce}>",
                   f"committer-time {c_ts}", f"committer-tz {c_tz}", f"summary {subj}"]
            if _is_boundary(c):
                blk.append("boundary")
            elif c.parents:
                ptree = _commit_tree_parents(repo, c.parents[0], graph)
                if ptree and workdir.tree_path_entry(repo, ptree[0], args.path):
                    blk.append(f"previous {c.parents[0]} {args.path}")
            blk.append(f"filename {args.path}")
            return blk
        seen_commit: set[str] = set()
        n = len(cur_lines)
        idx = 0
        while idx < n:
            s = blame_sha[idx] or "0" * 40
            # group: consecutive lines from the same commit.
            g = idx
            while g + 1 < n and (blame_sha[g + 1] or "0" * 40) == s:
                g += 1
            group = g - idx + 1
            for k in range(idx, g + 1):
                first_in_group = (k == idx)
                hdr = f"{s} {k + 1} {k + 1}" + (f" {group}" if first_in_group else "")
                _print(hdr)
                if args.line_porcelain or s not in seen_commit:
                    for bl in _porc_info(s):
                        _print(bl)
                    seen_commit.add(s)
                _print("\t" + cur_lines[k])
            idx = g + 1
        return 0

    # --incremental: emit per-group records (blame.c found_guilty_entry). Groups
    # are emitted as each commit is finished during the newest->oldest walk, so
    # the most-recently-introduced lines appear first. Build contiguous line
    # groups, then order them by the commit's position in the blame chain.
    if incremental:
        n = len(cur_lines)
        groups = []  # (commit, start_idx, count)
        idx = 0
        while idx < n:
            s = blame_sha[idx] or "0" * 40
            g = idx
            while g + 1 < n and (blame_sha[g + 1] or "0" * 40) == s:
                g += 1
            groups.append((s, idx, g - idx + 1))
            idx = g + 1
        # Newest commits (earliest in `chain`) are reported first.
        chain_pos = {sha: i for i, sha in enumerate(chain)}
        groups.sort(key=lambda gr: (chain_pos.get(gr[0], len(chain)), gr[1]))
        seen_commit: set[str] = set()
        for s, gidx, group in groups:
            _print(f"{s} {gidx + 1} {gidx + 1} {group}")
            c = objs.parse_commit(objs.read_object(repo, s)[1])
            if s not in seen_commit:
                awho, a_ts, a_tz = _split_ident(c.author)
                cwho, c_ts, c_tz = _split_ident(c.committer)
                an, ae = _parse_who(awho)
                cn, ce = _parse_who(cwho)
                subj = c.message.splitlines()[0] if c.message.strip() else ""
                _print(f"author {an}")
                _print(f"author-mail <{ae}>")
                _print(f"author-time {a_ts}")
                _print(f"author-tz {a_tz}")
                _print(f"committer {cn}")
                _print(f"committer-mail <{ce}>")
                _print(f"committer-time {c_ts}")
                _print(f"committer-tz {c_tz}")
                _print(f"summary {subj}")
                if _is_boundary(c):
                    _print("boundary")
                elif c.parents:
                    ptree = _commit_tree_parents(repo, c.parents[0], graph)
                    if ptree and workdir.tree_path_entry(repo, ptree[0], args.path):
                        _print(f"previous {c.parents[0]} {args.path}")
                _print(f"filename {args.path}")
                seen_commit.add(s)
        return 0

    # Default / annotate-compat human-readable output.
    info: dict[str, tuple[str, str, str, str, bool]] = {}
    for s in set(b for b in blame_sha if b):
        c = objs.parse_commit(objs.read_object(repo, s)[1])
        who, ts, tz = _split_ident(c.author)
        an, ae = _parse_who(who)
        info[s] = (an, f"<{ae}>", _format_blame_date(c.author),
                   f"{ts} {tz}" if ts is not None else "", _is_boundary(c))

    def _name_of(s) -> str:
        an, ae, _d, _r, _b = info.get(s, ("", "<>", "", "", False))
        return ae if show_email else an

    def _date_of(s) -> str:
        _an, _ae, d, raw, _b = info.get(s, ("", "<>", "", "", False))
        return raw if show_raw_time else d

    author_w = max((len(_name_of(s)) for s in info), default=0)
    lo, hi = 1, len(cur_lines)
    if args.line_range:
        start, _, end = args.line_range.partition(",")
        if start:
            lo = int(start)
        if end:
            hi = int(end)
    shown_max = min(hi, len(cur_lines))
    lineno_w = len(str(shown_max)) if shown_max > 0 else 1

    for idx, line in enumerate(cur_lines):
        if not (lo <= idx + 1 <= hi):
            continue
        s = blame_sha[idx] or "0" * 40
        boundary = info.get(s, (None, None, None, None, False))[4]
        if annotate_mode:
            # OUTPUT_ANNOTATE_COMPAT: <hex>\t(<name padded 10>\t<date padded 10>\t<lineno>)<line>
            hexfield = s[:abbrev] if not args.long_sha else s
            name = _name_of(s)
            date = _date_of(s)
            _print(f"{hexfield}\t({name:>10}\t{date:>10}\t{idx + 1}){line}")
            continue
        # Default format.
        length = abbrev if not args.long_sha else 40
        if boundary and not blank_boundary:
            field = "^" + s[:length - 1]
        elif boundary and blank_boundary:
            field = " " * length
        else:
            field = s[:length]
        prefix = field
        if show_number:
            prefix += f" {idx + 1:>{lineno_w}}"
        if not no_author:
            name = _name_of(s)
            date = _date_of(s)
            prefix += f" ({name:<{author_w}} {date}"
        _print(f"{prefix} {idx + 1:>{lineno_w}}) {line}")
    return 0


def _format_blame_date(sig: str) -> str:
    import datetime
    _who, ts, tz = _split_ident(sig)
    if ts is None or tz is None:
        return ""
    sign = 1 if tz[0] == "+" else -1
    off_min = sign * (int(tz[1:3]) * 60 + int(tz[3:5]))
    dt = datetime.datetime.fromtimestamp(ts, datetime.timezone.utc) + datetime.timedelta(minutes=off_min)
    return dt.strftime("%Y-%m-%d %H:%M:%S ") + tz


def _ref_sort_date(repo: Repository, sha: str, key: str) -> int:
    """Timestamp used by for-each-ref date sort keys (0 if unavailable).

    Mirrors ref-filter.c: each date atom reads only the matching object field,
    so e.g. %(committerdate) is empty (0) for an annotated tag and
    %(taggerdate) is empty for a commit. An empty value sorts as 0, which
    places it before any dated ref in ascending order."""
    import re
    try:
        t, data = objs.read_object(repo, sha)
    except KeyError:
        return 0
    text = data.decode("utf-8", errors="replace")

    def field_date(txt: str, field: str) -> int:
        m = re.search(rf"^{field} .* (\d+) [+-]\d{{4}}$", txt, re.M)
        return int(m.group(1)) if m else 0

    if key == "creatordate":
        # creator = committer for commits, tagger for (annotated) tags.
        if t == "commit":
            return field_date(text, "committer")
        if t == "tag":
            d = field_date(text, "tagger")
            if d:
                return d
            for line in text.splitlines():
                if line.startswith("object "):
                    return _ref_sort_date(repo, line[len("object "):].strip(), key)
            return 0
        return 0
    if key == "taggerdate":
        return field_date(text, "tagger") if t == "tag" else 0
    if key == "authordate":
        return field_date(text, "author") if t == "commit" else 0
    if key == "committerdate":
        return field_date(text, "committer") if t == "commit" else 0
    return 0


def _fer_quote(mode: str, v: str) -> str:
    """Quote an atom value for --shell/--perl/--python/--tcl (quote.c)."""
    if mode == "shell":
        return "'" + v.replace("'", "'\\''") + "'"
    if mode == "perl":
        return "'" + v.replace("\\", "\\\\").replace("'", "\\'") + "'"
    if mode == "python":
        return "'" + v.replace("\\", "\\\\").replace("'", "\\'") + "'"
    if mode == "tcl":
        out = []
        for ch in v:
            if ch in '$[]{}"\\':
                out.append("\\" + ch)
            elif ch == "\n":
                out.append("\\n")
            else:
                out.append(ch)
        return '"' + "".join(out) + '"'
    return v


def _parse_align_spec(arg: Optional[str]):
    """Port of ref-filter.c align_atom_parser. Parse the %(align:<args>)
    parameters into (position, width); return None if no valid width is given
    (C errors, but here we fall back to no padding). ``position`` is one of
    'left'/'right'/'middle' (default 'left'); args are comma-separated and may be
    'position=<p>', 'width=<n>', a bare width, or a bare position word."""
    if not arg:
        return None
    position = "left"
    width = None
    for s in arg.split(","):
        if s.startswith("position="):
            p = s[len("position="):]
            if p in ("left", "right", "middle"):
                position = p
            else:
                return None
        elif s.startswith("width="):
            try:
                width = int(s[len("width="):])
            except ValueError:
                return None
        elif s.isdigit():
            width = int(s)
        elif s in ("left", "right", "middle"):
            position = s
        else:
            return None
    if width is None or width <= 0:
        return None
    return position, width


def _strbuf_utf8_align(s: str, position: str, width: int) -> str:
    """Port of utf8.c strbuf_utf8_align (ASCII path: display width == length)."""
    display_len = len(s)
    if display_len >= width:
        return s
    if position == "left":
        return s + " " * (width - display_len)
    if position == "right":
        return " " * (width - display_len) + s
    # middle
    left = (width - display_len) // 2
    return " " * left + s + " " * (width - left - display_len)


def _fer_expand(repo: Repository, ref: str, sha: str, fmt: str, head_ref: Optional[str],
                quote: Optional[str] = None) -> str:
    """Expand a for-each-ref --format string's %(atom) placeholders. With
    ``quote`` set (shell/perl/python/tcl) each atom value is quoted in output."""
    import re
    try:
        t, data = objs.read_object(repo, sha)
    except KeyError:
        t, data = "commit", b""
    text = data.decode("utf-8", errors="replace")
    header, _, message = text.partition("\n\n")
    fields = {}
    for line in header.splitlines():
        k, _, v = line.partition(" ")
        if k in ("author", "committer", "tagger") and k not in fields:
            fields[k] = v

    def ident_part(role, part):
        sig = fields.get(role, "")
        who, ts, tz = _split_ident(sig)
        name, email = _parse_who(who)
        if part == "name":
            return name
        if part == "email":
            return f"<{email}>" if email else ""
        if part == "email:localpart":
            return email.split("@")[0] if email else ""
        if part.startswith("date"):
            if ts is None:
                return ""
            mode = part.split(":", 1)[1] if ":" in part else "default"
            return _format_date(sig, mode)
        return sig

    subject = message.splitlines()[0] if message.strip() else ""

    def atom(name: str) -> str:
        if name == "refname":
            return ref
        if name == "refname:short":
            return refs_mod.shorten_ref(ref)
        if name.startswith("refname:lstrip=") or name.startswith("refname:rstrip="):
            n = int(name.split("=", 1)[1])
            parts = ref.split("/")
            if name.startswith("refname:lstrip="):
                return "/".join(parts[n:] if n >= 0 else parts[len(parts) + n:])
            return "/".join(parts[:-n] if n > 0 else parts[:len(parts) + n] if n < 0 else parts)
        if name == "objectname":
            return sha
        if name == "objectname:short":
            return sha[:7]
        if name.startswith("objectname:short="):
            return sha[:int(name.split("=", 1)[1])]
        if name == "objecttype":
            return t
        if name == "objectsize":
            return str(len(data))
        if name == "HEAD":
            return "*" if ref == head_ref else " "
        if name in ("upstream", "push", "symref"):
            return ""
        if name in ("subject", "contents:subject"):
            return subject
        if name in ("body", "contents:body"):
            return message.partition("\n\n")[2] if "\n\n" in message else ""
        if name == "contents":
            return message
        if name in ("author", "committer", "tagger"):
            return fields.get(name, "")
        if name == "creator":
            return fields.get("tagger") or fields.get("committer", "")
        if name.startswith("creatordate"):
            role = "tagger" if "tagger" in fields else "committer"
            part = "date" + (":" + name.split(":", 1)[1] if ":" in name else "")
            return ident_part(role, part)
        for role in ("author", "committer", "tagger"):
            if name.startswith(role):
                return ident_part(role, name[len(role):] or "")
        return ""

    def subst(s: str, do_quote: bool = False) -> str:
        if do_quote and quote:
            return re.sub(r"%\(([^)]*)\)", lambda m: _fer_quote(quote, atom(m.group(1))), s)
        return re.sub(r"%\(([^)]*)\)", lambda m: atom(m.group(1)), s)

    # Resolve %(if)...%(then)...[%(else)...]%(end) conditionals and
    # %(align:...)...%(end) padding blocks innermost-first, before the plain
    # atom substitution. Both atoms close with %(end), so look back from each
    # %(end) to the nearest opening %(if or %(align.
    while True:
        end = fmt.find("%(end)")
        if end < 0:
            break
        if_start = fmt.rfind("%(if", 0, end)
        align_start = fmt.rfind("%(align", 0, end)
        start = max(if_start, align_start)
        if start < 0:
            break
        seg = fmt[start:end + len("%(end)")]
        if start == align_start:
            # %(align:<args>)<content>%(end): expand the content, then pad it to
            # the requested width/position (ref-filter.c end_align_handler ->
            # strbuf_utf8_align). For ASCII, display width == byte length.
            ma = re.match(r"%\(align(?::([^)]*))?\)(.*)%\(end\)$", seg, re.S)
            if not ma:
                break
            spec = _parse_align_spec(ma.group(1))
            content = subst(ma.group(2), do_quote=True)
            if spec is None:
                replacement = content
            else:
                position, width = spec
                replacement = _strbuf_utf8_align(content, position, width)
            fmt = fmt[:start] + replacement + fmt[end + len("%(end)"):]
            continue
        m = re.match(r"%\(if(:[^)]*)?\)(.*?)%\(then\)(.*?)(?:%\(else\)(.*))?%\(end\)$", seg, re.S)
        if not m:
            break
        cond_spec, cond, then_s, else_s = m.group(1), m.group(2), m.group(3), m.group(4) or ""
        cond_val = subst(cond)
        if cond_spec and cond_spec.startswith(":equals="):
            truthy = cond_val == cond_spec[len(":equals="):]
        elif cond_spec and cond_spec.startswith(":notequals="):
            truthy = cond_val != cond_spec[len(":notequals="):]
        else:
            truthy = bool(cond_val.strip())
        fmt = fmt[:start] + (then_s if truthy else else_s) + fmt[end + len("%(end)"):]

    return subst(fmt, do_quote=True)


# ref-filter.c valid_atom[] base names. An atom whose name (before ':') is not
# here is "unknown field name".
_FER_VALID_ATOMS = frozenset({
    "refname", "objecttype", "objectsize", "objectname", "deltabase", "tree",
    "parent", "numparent", "object", "type", "tag", "author", "authorname",
    "authoremail", "authordate", "committer", "committername", "committeremail",
    "committerdate", "tagger", "taggername", "taggeremail", "taggerdate",
    "creator", "creatordate", "describe", "subject", "body", "trailers",
    "contents", "signature", "raw", "upstream", "push", "symref", "flag",
    "HEAD", "color", "worktreepath", "align", "end", "if", "then", "else",
    "rest", "ahead-behind", "is-base",
})


def _ref_sort_validate(key: str) -> Optional[str]:
    """Port of ref-filter.c parse_ref_sorting + parse_sorting_atom. Validates a
    single sort key (OPT_REF_SORT). Returns None if the key names a valid atom,
    else the exact "fatal: unknown field name: <atom>\\n" stderr line.

    The caller strips the leading '-'/'+' reverse marker; here we strip the
    version:/v: prefix and the '*' deref, then check the base name (before ':')
    against valid_atom[]. The message echoes the atom AFTER the version prefix
    (matching C's `ep-atom` with atom already advanced past version:)."""
    arg = key
    for pre in ("version:", "v:"):
        if arg.startswith(pre):
            arg = arg[len(pre):]
            break
    sp = arg[1:] if arg.startswith("*") else arg
    base = sp.split(":", 1)[0]
    if base not in _FER_VALID_ATOMS:
        return f"fatal: unknown field name: {arg}\n"
    return None


def _fer_validate_format(fmt: str) -> Optional[tuple[int, str]]:
    """Port of ref-filter.c verify_ref_format + the %(if)/%(then)/%(else)/%(end)
    balance checks. Returns (rc, stderr_text) on the first invalid atom, else
    None. stderr_text already includes the trailing newline."""
    import re as _re

    def _color_ok(value: str) -> bool:
        # Mirror color.c color_parse: accept reset, attrs, and named/#rgb/ansi
        # colors. Anything else is invalid (the JSON probe uses 'notacolor').
        attrs = {"reset", "bold", "dim", "italic", "ul", "underline", "blink",
                 "reverse", "strike", "nobold", "nodim", "noitalic", "noul",
                 "nounderline", "noblink", "noreverse", "nostrike", "no-bold"}
        names = {"normal", "default", "black", "red", "green", "yellow", "blue",
                 "magenta", "cyan", "white"}
        for tok in value.split():
            t = tok
            if t.startswith("bright"):
                t = t[len("bright"):]
            if t in attrs or t in names:
                continue
            if t.startswith("#") and len(t) in (4, 7):
                continue
            if t.isdigit():
                continue
            return False
        return True

    # Container stack: each entry is a dict with "kind" ("if" or "align") plus
    # if/then/else bookkeeping, mirroring the runtime handlers.
    if_stack: list[dict] = []
    for m in _re.finditer(r"%\(([^)]*)\)", fmt):
        body = m.group(1)
        name = body[1:] if body.startswith("*") else body
        base, _, arg_present = name.partition(":")
        has_arg = ":" in name
        arg = name.split(":", 1)[1] if has_arg else None
        if arg == "":
            arg = None
        if base not in _FER_VALID_ATOMS:
            return (128, f"fatal: unknown field name: {body}\n")
        # Per-atom argument validation (only atoms with in-scope error paths).
        if base == "refname" or base == "symref":
            if arg is not None and arg != "short" and not (
                    arg.startswith(("lstrip=", "strip=", "rstrip="))):
                return (128, f"fatal: unrecognized %({base}) argument: {arg}\n")
        elif base == "align":
            if arg is None:
                return (128, "fatal: expected format: "
                             "%(align:<width>,<position>)\n")
            if_stack.append({"kind": "align", "saw_then": True, "saw_else": True})
        elif base == "color":
            if arg is None:
                return (128, "fatal: expected format: %(color:<color>)\n")
            if not _color_ok(arg):
                return (128, f"error: invalid color value: {arg}\n"
                             f"fatal: unrecognized color: %(color:{arg})\n")
        elif base == "if":
            if arg is not None and not arg.startswith(("equals=", "notequals=")):
                return (128, f"fatal: unrecognized %(if) argument: {arg}\n")
            if_stack.append({"kind": "if", "saw_then": False, "saw_else": False})
        elif base == "then":
            if not if_stack or if_stack[-1]["kind"] != "if":
                return (128, "fatal: format: %(then) atom used without a "
                             "%(if) atom\n")
            top = if_stack[-1]
            if top["saw_then"]:
                return (128, "fatal: format: %(then) atom used more than once\n")
            if top["saw_else"]:
                return (128, "fatal: format: %(then) atom used after %(else)\n")
            top["saw_then"] = True
        elif base == "else":
            if not if_stack or if_stack[-1]["kind"] != "if":
                return (128, "fatal: format: %(else) atom used without a "
                             "%(if) atom\n")
            top = if_stack[-1]
            if not top["saw_then"]:
                return (128, "fatal: format: %(else) atom used without a "
                             "%(then) atom\n")
            if top["saw_else"]:
                return (128, "fatal: format: %(else) atom used more than once\n")
            top["saw_else"] = True
        elif base == "end":
            if not if_stack:
                # %(end) for a non-if container (e.g. %(align)) is fine here; a
                # bare %(end) with nothing open is the corresponding-atom error.
                return (128, "fatal: format: %(end) atom used without "
                             "corresponding atom\n")
            top = if_stack.pop()
            if not top["saw_then"]:
                return (128, "fatal: format: %(if) atom used without a "
                             "%(then) atom\n")
    return None


_FER_USAGE_LINE = (
    "git for-each-ref [--count=<count>] [--shell|--perl|--python|--tcl]\n"
    "                         [(--sort=<key>)...] [--format=<format>]\n"
    "                         [--include-root-refs] [--points-at=<object>]\n"
    "                         [--merged[=<object>]] [--no-merged[=<object>]]\n"
    "                         [--contains[=<object>]] [--no-contains[=<object>]]\n"
    "                         [(--exclude=<pattern>)...] [--start-after=<marker>]\n"
    "                         [ --stdin | (<pattern>...)]")


def _fer_options() -> list["_PoOpt"]:
    NOARG, OPTARG, NONEG = (_PARSEOPT_NOARG, _PARSEOPT_OPTARG, _PARSEOPT_NONEG)

    def O(short=None, long=None, argh=None, flags=0, help="", group=False):
        o = _PoOpt()
        if group:
            o.is_group = True
            o.help = help
            return o
        o.short_name = short or ""
        o.long_name = long
        o.argh = argh
        o.flags = flags
        o.help = help
        return o

    return [
        O('s', 'shell', flags=NOARG, help="quote placeholders suitably for shells"),
        O('p', 'perl', flags=NOARG, help="quote placeholders suitably for perl"),
        O(None, 'python', flags=NOARG, help="quote placeholders suitably for python"),
        O(None, 'tcl', flags=NOARG, help="quote placeholders suitably for Tcl"),
        O(None, 'omit-empty', flags=NOARG,
          help="do not output a newline after empty formatted refs"),
        O(group=True, help=""),
        O(None, 'count', argh='n', flags=0, help="show only <n> matched refs"),
        O(None, 'format', argh='format', flags=0, help="format to use for the output"),
        O(None, 'start-after', argh='marker', flags=0,
          help="start iteration after the provided marker"),
        O(None, 'color', argh='when', flags=OPTARG, help="respect format colors"),
        O(None, 'exclude', argh='pattern', flags=0, help="exclude refs which match pattern"),
        O(None, 'sort', argh='key', flags=0, help="field name to sort on"),
        O(None, 'points-at', argh='object', flags=0,
          help="print only refs which points at the given object"),
        O(None, 'merged', argh='commit', flags=NONEG, help="print only refs that are merged"),
        O(None, 'no-merged', argh='commit', flags=NONEG,
          help="print only refs that are not merged"),
        O(None, 'contains', argh='commit', flags=NONEG,
          help="print only refs which contain the commit"),
        O(None, 'no-contains', argh='commit', flags=NONEG,
          help="print only refs which don't contain the commit"),
        O(None, 'ignore-case', flags=NOARG,
          help="sorting and filtering are case insensitive"),
        O(None, 'stdin', flags=NOARG, help="read reference patterns from stdin"),
        O(None, 'include-root-refs', flags=NOARG,
          help="also include HEAD ref and pseudorefs"),
    ]


def _fer_usage_err(prefix_err: str) -> int:
    _err(prefix_err)
    sys.stderr.write(_po_render_usage([_FER_USAGE_LINE], _fer_options(), False, True))
    return 129


def cmd_for_each_ref(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit for-each-ref", add_help=False)
    ap.add_argument("--format", default="%(objectname) %(objecttype)\t%(refname)")
    ap.add_argument("--count", default=None)
    ap.add_argument("--sort", action="append", default=None)
    ap.add_argument("--no-sort", dest="no_sort", action="store_true")
    ap.add_argument("--color", nargs="?", const="always", default=None)
    ap.add_argument("--no-color", dest="no_color", action="store_true")
    ap.add_argument("-s", "--shell", action="store_const", const="shell", dest="quote", default=None)
    ap.add_argument("-p", "--perl", action="store_const", const="perl", dest="quote")
    ap.add_argument("--python", action="store_const", const="python", dest="quote")
    ap.add_argument("--tcl", action="store_const", const="tcl", dest="quote")
    ap.add_argument("--points-at", dest="points_at", default=None)
    ap.add_argument("--merged", nargs="?", const="HEAD", default=None)
    ap.add_argument("--no-merged", dest="no_merged", nargs="?", const="HEAD", default=None)
    ap.add_argument("--contains", nargs="?", const="HEAD", default=None)
    ap.add_argument("--no-contains", dest="no_contains", nargs="?", const="HEAD", default=None)
    ap.add_argument("--exclude", action="append", default=None)
    ap.add_argument("--start-after", dest="start_after", default=None)
    ap.add_argument("--stdin", action="store_true")
    ap.add_argument("--include-root-refs", dest="include_root_refs", action="store_true")
    ap.add_argument("--omit-empty", dest="omit_empty", action="store_true")
    ap.add_argument("--ignore-case", dest="ignore_case", action="store_true")
    ap.add_argument("pattern", nargs="*", default=None)
    # --merged/--contains (and negations) use PARSE_OPT_LASTARG_DEFAULT: they
    # consume the following token as the commit, but default to HEAD when given
    # as the last argument. Rewrite to the attached "=value" form for argparse.
    consume = ("--merged", "--no-merged", "--contains", "--no-contains")
    pre: list[str] = []
    i = 0
    while i < len(argv):
        t = argv[i]
        if t in consume:
            if i + 1 < len(argv):
                pre.append(f"{t}={argv[i + 1]}")
                i += 2
            else:
                pre.append(f"{t}=HEAD")
                i += 1
            continue
        pre.append(t)
        i += 1
    args = ap.parse_args(pre)
    # builtin/for-each-ref.c order: max_count<0 error, then "more than one
    # quoting style", then verify_ref_format, then sort-key validation.
    # OPT_INTEGER --count: parse to int (a non-numeric value is argparse's job in
    # git too, but the negative check is explicit). max_count==0 means unlimited.
    if args.count is not None:
        try:
            args.count = int(args.count)
        except ValueError:
            args.count = 0
        if args.count < 0:
            return _fer_usage_err(f"error: invalid --count argument: `{args.count}'")
    # quote_style is an OPT_BIT: more than one of -s/-p/--python/--tcl is an error.
    quote_count = sum(1 for t in argv if t in (
        "-s", "--shell", "-p", "--perl", "--python", "--tcl"))
    if quote_count > 1:
        return _fer_usage_err("error: more than one quoting style?")
    # Validate the --format string up front (ref-filter.c verify_ref_format):
    # an unknown atom or malformed if/then/else/end aborts before any output.
    fmt_err = _fer_validate_format(args.format)
    if fmt_err is not None:
        sys.stderr.write(fmt_err[1])
        return fmt_err[0]
    # OPT_REF_SORT: validate each sort key after format. --no-sort clears keys.
    if args.no_sort:
        args.sort = None
    if args.sort:
        for spec in args.sort:
            key = spec[1:] if spec[:1] in "-+" else spec
            serr = _ref_sort_validate(key)
            if serr is not None:
                _err(serr)
                return 128
    repo = _repo()
    all_refs: dict[str, str] = {}
    if refs_mod.uses_reftable(repo):
        all_refs.update(refs_mod.iter_all_refs(repo))
    else:
        for name in ("refs/heads", "refs/tags", "refs/remotes"):
            root = repo.gitdir / name
            if root.exists():
                for f in root.rglob("*"):
                    if f.is_file():
                        rel = str(f.relative_to(repo.gitdir)).replace(os.sep, "/")
                        s = refs_mod.read_ref(repo, rel)
                        if s:
                            all_refs[rel] = s
        for ref, s in refs_mod.read_packed_refs(repo).items():
            all_refs.setdefault(ref, s)
    head_sym, head_sha = refs_mod.read_head(repo)
    if args.include_root_refs and head_sha:
        all_refs.setdefault("HEAD", head_sha)

    def _sort_value(ref: str, key: str):
        if key in ("refname", "refname:short"):
            return ref if key == "refname" else refs_mod.shorten_ref(ref)
        if key in ("version:refname", "v:refname"):
            import re as _re
            return [int(t) if t.isdigit() else t for t in _re.split(r"(\d+)", ref)]
        if key == "objectname":
            return all_refs[ref]
        # Date keys: peel to the underlying commit/tag and read its timestamp.
        if key in ("creatordate", "committerdate", "taggerdate", "authordate"):
            return _ref_sort_date(repo, all_refs[ref], key)
        return ref

    order = sorted(all_refs)
    if args.sort:
        # Multiple --sort keys: the last is most significant, so apply in reverse.
        for spec in reversed(args.sort):
            rev = spec.startswith("-")
            key = spec[1:] if rev else spec
            order = sorted(order, key=lambda r: _sort_value(r, key), reverse=rev)

    # --merged/--contains reachability over the ref's peeled commit.
    def _reachable_from(start: str, target: str) -> bool:
        stack = deque([start])
        seen_c: set[str] = set()
        while stack:
            x = stack.popleft()
            if x == target:
                return True
            if x in seen_c:
                continue
            seen_c.add(x)
            info = _commit_tree_parents(repo, x)
            if info:
                stack.extend(info[1])
        return False

    def _peel_commit(ref: str) -> Optional[str]:
        return refs_mod.rev_parse(repo, ref + "^{commit}")

    # Unresolvable object args fail differently per option (matching C Git):
    # --merged/--no-merged die() (fatal:, rc 128); --points-at/--contains/
    # --no-contains return a usage error (error:, rc 129) and --points-at quotes.
    resolved: dict[str, Optional[str]] = {}
    for key, msg, code in (
        ("points_at", "error: malformed object name '{}'", 129),
        ("merged", "fatal: malformed object name {}", 128),
        ("no_merged", "fatal: malformed object name {}", 128),
        ("contains", "error: malformed object name {}", 129),
        ("no_contains", "error: malformed object name {}", 129),
    ):
        val = getattr(args, key)
        if not val:
            resolved[key] = None
            continue
        sha = refs_mod.rev_parse(repo, val)
        if sha is None:
            _err(msg.format(val))
            return code
        # Reachability args are peeled to a commit (e.g. --contains=<annotated-tag>);
        # --points-at compares against the object as-is.
        if key != "points_at":
            sha = refs_mod.rev_parse(repo, val + "^{commit}") or sha
        resolved[key] = sha
    points_at = resolved["points_at"]
    merged = resolved["merged"]
    no_merged = resolved["no_merged"]
    contains = resolved["contains"]
    no_contains = resolved["no_contains"]

    def _ref_ok(ref: str) -> bool:
        sha = all_refs[ref]
        tip = _peel_commit(ref) if (merged or no_merged or contains or no_contains) else None
        if points_at is not None and sha != points_at and _peel_commit(ref) != points_at:
            return False
        if merged is not None and not (tip and _reachable_from(merged, tip)):
            return False
        if no_merged is not None and (tip and _reachable_from(no_merged, tip)):
            return False
        if contains is not None and not (tip and _reachable_from(tip, contains)):
            return False
        if no_contains is not None and tip and _reachable_from(tip, no_contains):
            return False
        return True

    patterns = list(args.pattern or [])
    if args.stdin:
        patterns += [ln.rstrip("\n") for ln in sys.stdin.read().splitlines() if ln.strip()]
    excludes = args.exclude or []

    def _match(ref: str, pats: list[str]) -> bool:
        import fnmatch
        r = ref.lower() if args.ignore_case else ref
        for p in pats:
            q = p.lower() if args.ignore_case else p
            if r == q or r.startswith(q.rstrip("/") + "/") or fnmatch.fnmatch(r, q):
                return True
        return False

    # --start-after: emit only refs positioned after the marker in iteration order.
    started = args.start_after is None
    emitted = 0
    for ref in order:
        if not started:
            if ref == args.start_after:
                started = True
            continue
        if patterns and not _match(ref, patterns):
            continue
        if excludes and _match(ref, excludes):
            continue
        if not _ref_ok(ref):
            continue
        # ref-filter.c gates with `if (max_count && ...)`, so a 0 count is falsy =
        # UNLIMITED. Only a positive count caps the output.
        if args.count:
            if emitted >= args.count:
                break
        line = _fer_expand(repo, ref, all_refs[ref], args.format, head_sym, quote=args.quote)
        if args.omit_empty and line == "":
            continue
        _print(line)
        emitted += 1
    return 0


def _indent_text(s: str, indent: int, indent2: int) -> str:
    """Port of utf8.c strbuf_add_indented_text (the width<=0 wrap fallback)."""
    if indent < 0:
        indent = 0
    out: list[str] = []
    i, n = 0, len(s)
    while i < n:
        eol = s.find("\n", i)
        eol = n if eol < 0 else eol + 1
        out.append(" " * indent)
        out.append(s[i:eol])
        i = eol
        indent = indent2
    return "".join(out)


def _wrap_text(s: str, indent1: int, indent2: int, width: int) -> str:
    """Port of utf8.c strbuf_add_wrapped_text for ASCII text (1 col per byte)."""
    if width <= 0:
        return _indent_text(s, indent1, indent2)
    out: list[str] = []
    n = len(s)
    text = bol = 0
    w = indent = indent1
    space: Optional[int] = None
    if indent < 0:
        w = -indent
        space = 0
    while True:
        c = s[text] if text < n else "\0"
        if c == "\0" or c.isspace():
            new_line = False
            if w <= width or space is None:
                start = bol
                if c == "\0" and text == start:
                    break
                if space is not None:
                    start = space
                else:
                    out.append(" " * indent)
                out.append(s[start:text])
                if c == "\0":
                    break
                space = text
                if c == "\t":
                    w |= 0x07
                    w += 1
                    text += 1
                elif c == "\n":
                    space += 1
                    nxt = s[space] if space < n else "\0"
                    if nxt == "\n":
                        out.append("\n")
                        new_line = True
                    elif not nxt.isalnum():
                        new_line = True
                    else:
                        out.append(" ")
                        w += 1
                        text += 1
                else:
                    w += 1
                    text += 1
            else:
                new_line = True
            if new_line:
                out.append("\n")
                sp = s[space] if space is not None and space < n else "\0"
                text = bol = space + (1 if sp.isspace() else 0)
                space = None
                w = indent = indent2
            continue
        w += 1
        text += 1
    return "".join(out)


def _parse_wrap_args(arg: Optional[str]) -> Optional[tuple[int, int, int]]:
    """Parse shortlog -w[<width>[,<i1>[,<i2>]]]; None on error (defaults 76,6,9)."""
    defaults = (76, 6, 9)
    if not arg:
        return defaults
    parts = arg.split(",")
    vals = list(defaults)
    for k in range(3):
        if k < len(parts) and parts[k] != "":
            try:
                vals[k] = int(parts[k])
            except ValueError:
                return None
    w, i1, i2 = vals
    if w < 0 or i1 < 0 or i2 < 0:
        return None
    if w and ((i1 and w <= i1) or (i2 and w <= i2)):
        return None
    return (w, i1, i2)


_SHORTLOG_STYLES = ("oneline", "short", "medium", "full", "fuller", "raw")


def cmd_shortlog(argv: list[str]) -> int:
    # -w, --pretty and --format take their argument only in the attached form
    # (PARSE_OPT_OPTARG / "--opt=val"), never from a following token, which would
    # otherwise be swallowed instead of being treated as the revision.
    wrap_lines = False
    wrap = (76, 6, 9)
    pretty_spec: Optional[str] = None
    format_spec: Optional[str] = None
    rest: list[str] = []
    for t in argv:
        if t == "-w":
            wrap_lines = True
        elif t.startswith("-w") and not t.startswith("--") and len(t) > 2:
            parsed = _parse_wrap_args(t[2:])
            if parsed is None:
                _err("error: -w[<width>[,<indent1>[,<indent2>]]]")
                return 129
            wrap_lines = True
            wrap = parsed
        elif t == "--pretty":
            pretty_spec = "medium"
        elif t.startswith("--pretty="):
            pretty_spec = t[len("--pretty="):]
        elif t.startswith("--format="):
            format_spec = t[len("--format="):]
        else:
            rest.append(t)

    ap = argparse.ArgumentParser(prog="pygit shortlog", add_help=False)
    ap.add_argument("-n", "--numbered", action="store_true")
    ap.add_argument("-s", "--summary", action="store_true")
    ap.add_argument("-e", "--email", action="store_true")
    ap.add_argument("-c", "--committer", action="store_true")
    ap.add_argument("rev", nargs="?", default="HEAD")
    args = ap.parse_args(rest)
    repo = _repo()

    # Record format: only CMIT_FMT_USERFORMAT changes the per-commit record.
    # The real builtin styles (oneline/short/medium/full/fuller/raw) fall back to
    # the subject ("%s"); `reference` is itself a userformat; a bare word that is
    # neither builtin nor a "%"/prefix format is rejected like C Git.
    record_fmt: Optional[str] = None
    record_date = "default"

    def _resolve_fmt(val: str) -> Optional[str]:
        nonlocal record_fmt, record_date
        if val in _SHORTLOG_STYLES:
            return None
        if val == "reference":
            record_fmt = "%h (%s, %ad)"
            record_date = "short"
            return None
        if val.startswith(("format:", "tformat:")):
            record_fmt = val.split(":", 1)[1]
            return None
        if "%" in val:
            record_fmt = val
            return None
        return f"fatal: invalid --pretty format: {val}"

    spec = format_spec if format_spec is not None else pretty_spec
    if spec is not None:
        err = _resolve_fmt(spec)
        if err is not None:
            _err(err)
            return 128

    head = refs_mod.rev_parse(repo, args.rev)
    if not head:
        return 128
    by_author: dict[str, list[str]] = {}
    seen: set[str] = set()
    stack = deque([head])
    while stack:
        s = stack.popleft()
        if s in seen:
            continue
        seen.add(s)
        try:
            c = objs.parse_commit(objs.read_object(repo, s)[1])
        except KeyError:
            continue
        ident = c.committer if args.committer else c.author
        who, _ts, _tz = _split_ident(ident)
        name, email = _parse_who(who)
        key = f"{name} <{email}>" if args.email else name
        if record_fmt is not None:
            record = _expand_commit_format(repo, s, c, record_fmt, {}, date_mode=record_date)
        else:
            record = c.message.splitlines()[0].rstrip() if c.message.strip() else ""
        by_author.setdefault(key, []).append(record if record else "<none>")
        stack.extend(c.parents)
    # git lists each author's commits oldest-first (we collected newest-first).
    for msgs in by_author.values():
        msgs.reverse()
    items = list(by_author.items())
    if args.numbered:
        items.sort(key=lambda x: -len(x[1]))
    else:
        items.sort()
    for author, msgs in items:
        if args.summary:
            _print(f"{len(msgs):>6}\t{author}")
        else:
            _print(f"{author} ({len(msgs)}):")
            for m in msgs:
                if wrap_lines:
                    sys.stdout.write(_wrap_text(m, wrap[1], wrap[2], wrap[0]) + "\n")
                else:
                    _print(f"      {m}")
            _print("")
    return 0


def _archive_entries(repo: Repository, tree: str, pathspec: list[str],
                     attrs: Optional["_ArchiveAttrs"] = None):
    """Yield archive entries in C Git's read_tree/queue_or_write order.

    Each yielded item is ``(relpath, mode_str, sha_or_None, kind)`` where kind
    is one of "dir", "file", "symlink", "gitlink".  Directory entries are
    emitted lazily — only just before the first matching entry beneath them —
    exactly like archive.c's queue_directory/write_directory mechanism.  When
    ``pathspec`` is empty, everything is included.

    Pathspec matching uses git's literal-prefix semantics: a file path matches
    a spec ``s`` when it equals ``s`` or lies under ``s + "/"``; a directory is
    descended when it equals a spec, lies under one, or is a prefix of one.

    When ``attrs`` is given, ``export-ignore`` is honored: a directory carrying
    that attribute drops its entire subtree (queue_or_write_archive_entry) and a
    file carrying it is skipped (write_archive_entry), exactly as archive.c does.
    """
    specs = [p.rstrip("/") for p in pathspec]

    def file_matches(path: str) -> bool:
        if not specs:
            return True
        return any(path == s or path.startswith(s + "/") for s in specs)

    def dir_descends(path: str) -> bool:
        if not specs:
            return True
        return any(path == s or path.startswith(s + "/") or s == path
                   or s.startswith(path + "/") for s in specs)

    # Pending (queued but not-yet-emitted) ancestor directories, deepest last.
    pending: list[tuple[str, str, str]] = []  # (path, mode, sha)

    def walk(tsha: str, prefix: str):
        _, td = objs.read_object(repo, tsha)
        for e in objs.parse_tree(td, repo.hash_len):
            path = prefix + e.name
            if e.is_dir():
                if not dir_descends(path):
                    continue
                # export-ignore on a directory drops the whole subtree.
                if attrs is not None and attrs.check(path + "/")[0]:
                    continue
                pending.append((path, e.mode, e.sha))
                yield from walk(e.sha, path + "/")
                # Drop the directory if nothing under it was emitted.
                if pending and pending[-1][0] == path:
                    pending.pop()
            else:
                if not file_matches(path):
                    continue
                # export-ignore on a file skips it.
                if attrs is not None and attrs.check(path)[0]:
                    continue
                # Flush queued ancestor directories that have not been emitted.
                while pending:
                    dpath, dmode, dsha = pending.pop(0)
                    yield (dpath, dmode, dsha, "dir")
                if e.mode == "120000":
                    yield (path, e.mode, e.sha, "symlink")
                elif e.is_gitlink():
                    yield (path, e.mode, e.sha, "gitlink")
                else:
                    yield (path, e.mode, e.sha, "file")

    yield from walk(tree, "")


def _archive_pathspec_matches(repo: Repository, tree: str, spec: str) -> bool:
    """True when ``spec`` matches at least one path in ``tree`` (path_exists)."""
    for _path, _mode, _sha, kind in _archive_entries(repo, tree, [spec]):
        if kind != "dir":
            return True
    return False


class _ArchiveAttrs:
    """Resolve ``export-ignore`` / ``export-subst`` for archive entries.

    Mirrors archive.c:get_archive_attrs, which consults the attribute stack via
    ``git_check_attr`` with GIT_ATTR_INDEX set (so .gitattributes are read from
    the tree being archived, not the working tree).  With --worktree-attributes
    the direction is unchanged but the working-tree .gitattributes are read
    instead (archive.c:parse_treeish_arg leaves GIT_ATTR_CHECKIN, the default).

    We support the per-directory .gitattributes stack plus $GIT_DIR/info/attributes,
    which is what the parity corpus exercises.  Each directory's rules are loaded
    lazily and cached.  Patterns are matched with the same _AttrRule machinery
    used by the convert layer.
    """

    def __init__(self, repo: Repository, tree: str, worktree: bool) -> None:
        from . import convert as _convert
        self._repo = repo
        self._tree = tree
        self._worktree = worktree
        self._convert = _convert
        # dir-path ("" for root, "sub", "sub/sub") -> list[_AttrRule]
        self._cache: dict[str, list] = {}
        # tree-sha cache so nested directory lookups don't re-parse.
        self._tree_at: dict[str, Optional[str]] = {"": tree}

    def _tree_sha_for_dir(self, dirpath: str) -> Optional[str]:
        if dirpath in self._tree_at:
            return self._tree_at[dirpath]
        parent, _, name = dirpath.rpartition("/")
        ptree = self._tree_sha_for_dir(parent)
        sha = None
        if ptree is not None:
            try:
                _, td = objs.read_object(self._repo, ptree)
                for e in objs.parse_tree(td, self._repo.hash_len):
                    if e.name == name and e.is_dir():
                        sha = e.sha
                        break
            except Exception:
                sha = None
        self._tree_at[dirpath] = sha
        return sha

    def _attr_text_for_dir(self, dirpath: str) -> Optional[bytes]:
        """Return the .gitattributes bytes for ``dirpath`` (or None)."""
        if self._worktree:
            base = self._repo.path if dirpath == "" else (self._repo.path / dirpath)
            ga = base / ".gitattributes"
            try:
                if ga.is_file():
                    return ga.read_bytes()
            except OSError:
                return None
            return None
        # Read from the tree being archived (index direction).
        tsha = self._tree_sha_for_dir(dirpath)
        if tsha is None:
            return None
        try:
            _, td = objs.read_object(self._repo, tsha)
            for e in objs.parse_tree(td, self._repo.hash_len):
                if e.name == ".gitattributes" and not e.is_dir():
                    _t, blob = objs.read_object(self._repo, e.sha)
                    return blob
        except Exception:
            return None
        return None

    def _rules_for_dir(self, dirpath: str) -> list:
        if dirpath in self._cache:
            return self._cache[dirpath]
        rules: list = []
        text = self._attr_text_for_dir(dirpath)
        if text is not None:
            rules = self._parse_rules(text.decode("utf-8", "replace"))
        self._cache[dirpath] = rules
        return rules

    def _info_rules(self) -> list:
        if "\0info" in self._cache:
            return self._cache["\0info"]
        rules: list = []
        try:
            info = self._repo.gitdir / "info" / "attributes"
            if info.is_file():
                rules = self._parse_rules(info.read_bytes().decode("utf-8", "replace"))
        except OSError:
            rules = []
        self._cache["\0info"] = rules
        return rules

    def _parse_rules(self, text: str) -> list:
        rules: list = []
        for line in text.splitlines():
            stripped = line.lstrip(" \t")
            if not stripped or stripped.startswith("#"):
                continue
            parts = stripped.split()
            pattern = parts[0]
            if pattern.startswith("!"):
                continue
            try:
                rules.append(self._convert._AttrRule(
                    pattern, self._convert._parse_attr_tokens(parts[1:])))
            except Exception:
                continue
        return rules

    def check(self, path: str) -> tuple[bool, bool]:
        """Return (export_ignore, export_subst) for archive path ``path``.

        ``path`` is relative to the archive root (no prefix), with a trailing
        slash for directories — exactly the value archive.c passes to
        git_check_attr.
        """
        wanted = ("export-ignore", "export-subst")
        out: dict[str, object] = {}
        # Per-directory stack: deepest .gitattributes first, then ancestors up
        # to the root, then info/attributes (highest priority -> checked last in
        # git's stack, but first-set-wins on a reverse scan).  git evaluates the
        # most specific (deepest) attributes file last so it overrides; within a
        # file later lines win.  We collect from deepest to shallowest and let
        # the first definite value win, matching attr.c:fill semantics for these
        # boolean attrs.
        clean = path.rstrip("/")
        segs = clean.split("/")
        dirs = [""]
        for i in range(1, len(segs)):
            dirs.append("/".join(segs[:i]))
        # info/attributes has the highest precedence in git's stack.
        stacks = [self._info_rules()]
        for d in reversed(dirs):
            stacks.append(self._rules_for_dir(d))
        # The pattern in a per-directory attributes file matches against the
        # path relative to that directory.
        rel_for_dir = {}
        for d in dirs:
            rel_for_dir[d] = clean[len(d) + 1:] if d else clean
        # Walk stacks: info first (highest), then deepest dir to root.
        dir_order = [None] + list(reversed(dirs))  # None marks info stack
        for idx, st in enumerate(stacks):
            if all(k in out for k in wanted):
                break
            d = dir_order[idx]
            rel = clean if d is None else rel_for_dir[d]
            for rule in reversed(st):
                if all(k in out for k in wanted):
                    break
                if not rule.matches(rel):
                    continue
                for k, v in rule.attrs.items():
                    if k in wanted and k not in out:
                        out[k] = v
        ei = out.get("export-ignore") is True
        es = out.get("export-subst") is True
        return ei, es


def _git_archive_tar(repo: Repository, tree: str, commit_sha: Optional[str], archive_time: int, prefix: str = "", verbose: bool = False, pathspec: Optional[list[str]] = None, extra_files: Optional[list[tuple[str, bytes, int]]] = None, attrs: Optional["_ArchiveAttrs"] = None, commit_obj=None) -> bytes:
    """Build a tar archive byte-for-byte identical to C Git's archive-tar.c.

    When ``verbose`` is set, each archived path is reported to stderr in the
    same order C Git's ``archive --verbose`` does (archive.c:write_archive_entry).
    ``pathspec`` restricts the entries; ``extra_files`` are ``(name, content,
    mode)`` tuples appended after the tree walk (--add-file).  ``attrs`` honors
    export-ignore/export-subst; ``commit_obj`` is the parsed commit used by
    export-subst's $Format:..$ expansion.
    """
    BLOCKSIZE = 512 * 20
    TAR_UMASK = 0o002
    out = bytearray()

    def report(name: str) -> None:
        if verbose:
            _err(name)

    def emit_header(name: str, mode: int, size: int, typeflag: str, linkname: str = "") -> None:
        h = bytearray(512)
        nb = name.encode("utf-8")
        h[0:len(nb)] = nb
        h[100:108] = b"%07o\0" % (mode & 0o7777)
        h[108:116] = b"0000000\0"
        h[116:124] = b"0000000\0"
        h[124:136] = b"%011o\0" % size
        h[136:148] = b"%011o\0" % archive_time
        h[148:156] = b" " * 8  # checksum placeholder (spaces)
        h[156] = ord(typeflag)
        if linkname:
            lb = linkname.encode("utf-8")
            h[157:157 + len(lb)] = lb
        h[257:263] = b"ustar\0"
        h[263:265] = b"00"
        h[265:269] = b"root"
        h[297:301] = b"root"
        h[329:337] = b"0000000\0"
        h[337:345] = b"0000000\0"
        h[148:156] = b"%07o\0" % sum(h)
        out.extend(h)

    def emit_content(data: bytes) -> None:
        out.extend(data)
        out.extend(b"\0" * ((-len(data)) % 512))

    if commit_sha:
        body = f" comment={commit_sha}\n"
        total = len(body)
        while len(str(total)) + len(body) != total:
            total = len(str(total)) + len(body)
        pax = f"{total}{body}".encode("utf-8")
        emit_header("pax_global_header", 0o100666, len(pax), "g")
        emit_content(pax)

    if prefix.endswith("/"):
        # git emits a single directory entry for the whole prefix; trailing
        # slashes are collapsed to one for the entry name (archive.c).
        plen = len(prefix)
        while plen > 1 and prefix[plen - 2] == "/":
            plen -= 1
        pdir = prefix[:plen]
        report(pdir)
        emit_header(pdir, (0o40000 | 0o777) & ~TAR_UMASK, 0, "5")

    for relpath, mode_str, esha, kind in _archive_entries(repo, tree, pathspec or [], attrs):
        name = prefix + relpath
        mode = int(mode_str, 8)
        if kind == "dir":
            report(name + "/")
            emit_header(name + "/", (mode | 0o777) & ~TAR_UMASK, 0, "5")
        elif kind == "symlink":
            report(name)
            _, target = objs.read_object(repo, esha)
            # Symlinks are not umask'd: archive-tar.c does `mode |= 0777`.
            emit_header(name, mode | 0o777, 0, "2", target.decode("utf-8", "replace"))
        elif kind == "gitlink":
            # C Git writes gitlinks as a directory entry (trailing slash) and
            # drops the recursion.
            report(name + "/")
            emit_header(name + "/", (mode | 0o777) & ~TAR_UMASK, 0, "5")
        else:
            report(name)
            _, blob = objs.read_object(repo, esha)
            if attrs is not None and commit_obj is not None and attrs.check(relpath)[1]:
                blob = _archive_format_subst(repo, commit_sha, commit_obj, blob)
            base = 0o777 if (mode & 0o100) else 0o666
            emit_header(name, (mode | base) & ~TAR_UMASK, len(blob), "0")
            emit_content(blob)

    # Extra files (--add-file / --add-virtual-file) appended after the tree
    # walk.  The name already carries any per-option --prefix base; the writer
    # does NOT re-prepend the archive prefix.  canon_mode(st_mode): regular
    # files become 0100644 or 0100755.
    for xname, xcontent, xmode in (extra_files or []):
        ename = xname
        report(ename)
        base = 0o777 if (xmode & 0o100) else 0o666
        emit_header(ename, (0o100000 | base) & ~TAR_UMASK, len(xcontent), "0")
        emit_content(xcontent)

    out.extend(b"\0" * 1024)  # end-of-archive trailer
    if len(out) % BLOCKSIZE:
        out.extend(b"\0" * (BLOCKSIZE - len(out) % BLOCKSIZE))
    return bytes(out)


def _zip_dos_time(ts: int) -> tuple[int, int]:
    """Port of archive-zip.c:dos_time (localtime_r; UTC under the parity env).

    Returns (dos_date, dos_time)."""
    import time as _t
    tm = _t.gmtime(ts)
    dos_date = tm.tm_mday + (tm.tm_mon) * 32 + (tm.tm_year - 1980) * 512
    dos_time = tm.tm_sec // 2 + tm.tm_min * 32 + tm.tm_hour * 2048
    return dos_date, dos_time


def _git_archive_zip(repo: Repository, tree: str, commit_sha: Optional[str], archive_time: int, prefix: str = "", verbose: bool = False, pathspec: Optional[list[str]] = None, extra_files: Optional[list[tuple[str, bytes, int]]] = None, compression_level: int = -1, attrs: Optional["_ArchiveAttrs"] = None, commit_obj=None) -> bytes:
    """Build a zip archive byte-for-byte identical to C Git's archive-zip.c.

    ``compression_level`` is the deflate level (-1 = Z_DEFAULT_COMPRESSION; 0
    forces STORE for every entry).  ``attrs``/``commit_obj`` honor
    export-ignore/export-subst as in archive.c.
    """
    import struct as _struct
    import zlib as _zlib
    zip_date, zip_time = _zip_dos_time(archive_time)

    out = bytearray()
    zip_dir = bytearray()
    zip_dir_entries = 0
    zip_offset = 0

    def report(name: str) -> None:
        if verbose:
            _err(name)

    def is_ascii(s: bytes) -> bool:
        return all(c < 0x80 for c in s)

    def is_utf8(b: bytes) -> bool:
        try:
            b.decode("utf-8")
            return True
        except UnicodeDecodeError:
            return False

    ZIP_UTF8 = 0x0800

    def write_entry(path: str, mode: int, kind: str, content: bytes) -> None:
        nonlocal zip_offset, zip_dir_entries
        pb = path.encode("utf-8", "surrogateescape")
        pathlen = len(pb)
        flags = 0
        if not is_ascii(pb):
            if is_utf8(pb):
                flags |= ZIP_UTF8
        creator_version = 0
        version_needed = 10
        is_binary = -1
        crc = 0

        if kind in ("dir", "gitlink"):
            method = 0  # STORE
            attr2 = 16
            data = b""
            compressed = b""
            size = 0
            compressed_size = 0
        else:
            # regular file or symlink
            method = 0
            if kind == "symlink":
                attr2 = (mode | 0o777) << 16
                creator_version = 0x0317
            elif mode & 0o111:
                attr2 = mode << 16
                creator_version = 0x0317
            else:
                attr2 = 0
            data = content
            size = len(data)
            crc = _zlib.crc32(data) & 0xFFFFFFFF
            is_binary = 1 if (b"\x00" in data[:8000]) else 0
            if kind == "file" and compression_level != 0 and size > 0:
                method = 8  # DEFLATE
            if method == 8:
                co = _zlib.compressobj(compression_level, _zlib.DEFLATED, -_zlib.MAX_WBITS)
                deflated = co.compress(data) + co.flush()
                if len(deflated) >= size:
                    method = 0
                    compressed = data
                    compressed_size = size
                else:
                    compressed = deflated
                    compressed_size = len(deflated)
            else:
                compressed = data
                compressed_size = size

        if creator_version > 0:
            pass  # max_creator_version tracking only affects zip64 trailer

        # extra mtime field (magic 0x5455, flags=1 mtime, 4-byte time)
        extra = (_struct.pack("<HH", 0x5455, 5) + bytes([1])
                 + _struct.pack("<I", archive_time & 0xFFFFFFFF))
        header_extra_size = len(extra)  # 9

        offset = zip_offset
        # local file header (30 bytes)
        out.extend(_struct.pack(
            "<IHHHHHIIIHH",
            0x04034b50, version_needed, flags, method, zip_time, zip_date,
            crc, compressed_size & 0xFFFFFFFF, size & 0xFFFFFFFF,
            pathlen, header_extra_size))
        zip_offset += 30
        out.extend(pb)
        zip_offset += pathlen
        out.extend(extra)
        zip_offset += header_extra_size
        if compressed_size > 0:
            out.extend(compressed)
            zip_offset += compressed_size

        # central directory record. internal_attributes = !is_binary, where C's
        # `!` yields 1 only when is_binary == 0 (so -1 and 1 both give 0).
        internal_attrs = 1 if is_binary == 0 else 0
        zip_dir.extend(_struct.pack(
            "<IHHHHHHIIIHHHHHII",
            0x02014b50, creator_version, version_needed, flags, method,
            zip_time, zip_date, crc, compressed_size & 0xFFFFFFFF,
            size & 0xFFFFFFFF, pathlen, header_extra_size, 0, 0,
            internal_attrs,
            attr2 & 0xFFFFFFFF, offset & 0xFFFFFFFF))
        zip_dir.extend(pb)
        zip_dir.extend(extra)
        zip_dir_entries += 1

    if prefix.endswith("/"):
        plen = len(prefix)
        while plen > 1 and prefix[plen - 2] == "/":
            plen -= 1
        pdir = prefix[:plen]
        report(pdir)
        # pdir already carries the single trailing slash (matches the tar path).
        write_entry(pdir, 0o40000, "dir", b"")

    for relpath, mode_str, esha, kind in _archive_entries(repo, tree, pathspec or [], attrs):
        name = prefix + relpath
        mode = int(mode_str, 8)
        if kind == "dir":
            report(name + "/")
            write_entry(name + "/", mode, "dir", b"")
        elif kind == "symlink":
            report(name)
            _, target = objs.read_object(repo, esha)
            write_entry(name, mode, "symlink", target)
        elif kind == "gitlink":
            report(name + "/")
            write_entry(name + "/", mode, "gitlink", b"")
        else:
            report(name)
            _, blob = objs.read_object(repo, esha)
            if attrs is not None and commit_obj is not None and attrs.check(relpath)[1]:
                blob = _archive_format_subst(repo, commit_sha, commit_obj, blob)
            write_entry(name, mode, "file", blob)

    for xname, xcontent, xmode in (extra_files or []):
        ename = xname
        report(ename)
        write_entry(ename, (0o100000 | (0o755 if xmode & 0o111 else 0o644)),
                    "file", xcontent)

    # end-of-central-directory record (no zip64 needed for our sizes)
    out.extend(zip_dir)
    comment_len = repo.hex_len if commit_sha else 0
    out.extend(_struct.pack(
        "<IHHHHIIH",
        0x06054b50, 0, 0, zip_dir_entries & 0xFFFF, zip_dir_entries & 0xFFFF,
        len(zip_dir) & 0xFFFFFFFF, zip_offset & 0xFFFFFFFF, comment_len))
    if commit_sha:
        out.extend(commit_sha.encode("ascii"))
    return bytes(out)


def _parse_virtual_file(arg: str) -> tuple[str, bytes]:
    """Parse a ``--add-virtual-file=<path>:<content>`` argument.

    Mirrors archive.c:add_file_cb's add-virtual-file branch: an unquoted path
    runs up to the first ':'; a C-quoted ("...") path is unquoted and the ':'
    must immediately follow.  The remainder after the colon is the content.
    Raises :class:`_ArchiveFatal` for the missing-colon / empty-name / unclosed-
    quote conditions, byte-exact with git's die() messages.
    """
    if arg.startswith('"'):
        # C-quoted name: unquote, then the next char must be ':'.
        try:
            path, rest = _c_unquote_prefix(arg)
        except ValueError:
            raise _ArchiveFatal("unclosed quote: '%s'" % arg)
        if not rest.startswith(":"):
            raise _ArchiveFatal("missing colon: '%s'" % arg)
        content = rest[1:]
        if path == "":
            raise _ArchiveFatal("empty file name: '%s'" % arg)
        return path, content.encode("utf-8", "surrogateescape")
    idx = arg.find(":")
    if idx < 0:
        raise _ArchiveFatal("missing colon: '%s'" % arg)
    if idx == 0:
        raise _ArchiveFatal("empty file name: '%s'" % arg)
    path = arg[:idx]
    content = arg[idx + 1:]
    return path, content.encode("utf-8", "surrogateescape")


def _c_unquote_prefix(s: str) -> tuple[str, str]:
    """Unquote a leading C-style ("...") token from ``s``.

    Returns (decoded_path, remainder_after_closing_quote).  Raises ValueError
    when the opening quote has no matching close.  Supports the standard escapes
    git's unquote_c_style understands (\\n \\t \\\\ \\" octal \\NNN).
    """
    assert s.startswith('"')
    out = bytearray()
    i = 1
    n = len(s)
    while i < n:
        ch = s[i]
        if ch == '"':
            return out.decode("utf-8", "surrogateescape"), s[i + 1:]
        if ch == "\\":
            i += 1
            if i >= n:
                break
            e = s[i]
            simple = {"a": 7, "b": 8, "t": 9, "n": 10, "v": 11, "f": 12,
                      "r": 13, '"': ord('"'), "\\": ord("\\")}
            if e in simple:
                out.append(simple[e])
                i += 1
                continue
            if e in "01234567":
                oct_digits = e
                i += 1
                while i < n and len(oct_digits) < 3 and s[i] in "01234567":
                    oct_digits += s[i]
                    i += 1
                out.append(int(oct_digits, 8) & 0xFF)
                continue
            out.append(ord(e))
            i += 1
            continue
        out.extend(ch.encode("utf-8", "surrogateescape"))
        i += 1
    raise ValueError("unclosed quote")


def _archive_format_subst(repo: Repository, commit_sha: Optional[str],
                          commit_obj, data: bytes) -> bytes:
    """Port of archive.c:format_subst.

    Replaces ``$Format:<pretty>$`` placeholders in ``data`` with the result of
    ``repo_format_commit_message`` for the archived commit.  Each placeholder's
    inner ``<pretty>`` string is expanded by the same pretty engine git uses, so
    e.g. ``$Format:%H$`` becomes the full commit hash.
    """
    if commit_obj is None or commit_sha is None:
        return data
    out = bytearray()
    src = data
    pos = 0
    n = len(src)
    while True:
        b = src.find(b"$Format:", pos)
        if b < 0:
            break
        c = src.find(b"$", b + 8)
        if c < 0:
            break
        fmt = src[b + 8:c]
        out += src[pos:b]
        try:
            expanded = _expand_commit_format(
                repo, commit_sha, commit_obj,
                fmt.decode("utf-8", "surrogateescape"), {})
            out += expanded.encode("utf-8", "surrogateescape")
        except Exception:
            # On any expansion failure, leave the placeholder bytes intact.
            out += src[b:c + 1]
        pos = c + 1
    out += src[pos:]
    return bytes(out)


class _ArchiveFatal(Exception):
    """Raised inside the archive core to signal a ``fatal:`` condition.

    The message carries no ``fatal: `` prefix; the local front-end prepends it
    when printing, while the upload-archive writer relays it verbatim (C Git's
    write_archive forwards die() output to the client on sideband band #2).
    """


class _ArchiveUsage(Exception):
    """Raised inside the archive core for a usage_with_options() condition.

    Carries the rendered archive usage+options block.  The local front-end and
    the upload-archive writer both emit it (to stderr / sideband band #2) and
    exit 129, mirroring parse_archive_args' usage_with_options(archive_usage).

    ``to_stdout`` is set for the "-h" help path (usage goes to stdout); ``lead``
    is the optional leading "error: unknown option `x'" line.
    """

    def __init__(self, lead: str = "", to_stdout: bool = False):
        super().__init__(lead)
        self.lead = lead
        self.to_stdout = to_stdout


# usage_with_options(archive_usage, opts) rendering, byte-for-byte (the OPT_*
# table in archive.c:parse_archive_args).  Printed on "-h", on a missing
# tree-ish, and via the unknown-option path.
_ARCHIVE_USAGE = (
    "usage: git archive [<options>] <tree-ish> [<path>...]\n"
    "   or: git archive --list\n"
    "   or: git archive --remote <repo> [--exec <cmd>] [<options>] <tree-ish> [<path>...]\n"
    "   or: git archive --remote <repo> [--exec <cmd>] --list\n"
    "\n"
    "    --[no-]format <fmt>   archive format\n"
    "    --[no-]prefix <prefix>\n"
    "                          prepend prefix to each pathname in the archive\n"
    "    --[no-]add-file <file>\n"
    "                          add untracked file to archive\n"
    "    --[no-]add-virtual-file <path:content>\n"
    "                          add untracked file to archive\n"
    "    -o, --[no-]output <file>\n"
    "                          write the archive to this file\n"
    "    --[no-]worktree-attributes\n"
    "                          read .gitattributes in working directory\n"
    "    -v, --[no-]verbose    report archived files on stderr\n"
    "    --mtime <time>        set modification time of archive entries\n"
    "    -NUM                  set compression level\n"
    "\n"
    "    -l, --[no-]list       list supported archive formats\n"
    "\n"
    "    --[no-]remote <repo>  retrieve the archive from remote repository <repo>\n"
    "    --[no-]exec <command> path to the remote git-upload-archive command\n"
    "\n")

# The long options known to archive.c's parse_archive_args (parse-options
# matches by long name; an unknown "--x" is "error: unknown option `x'").  Used
# to reject unknown long options before argparse would silently drop them.
_ARCHIVE_KNOWN_LONG = frozenset({
    "format", "prefix", "add-file", "add-virtual-file", "output",
    "worktree-attributes", "verbose", "mtime", "list", "remote", "exec",
    # parse-options auto-negation of the boolean/value options.
    "no-format", "no-prefix", "no-add-file", "no-add-virtual-file",
    "no-output", "no-worktree-attributes", "no-verbose", "no-list",
    "no-remote", "no-exec",
})

# Long options that consume the following token as their value when given in
# the space-separated form (OPTION_STRING / OPTION_FILENAME / OPTION_CALLBACK
# with an arg).  --mtime is included; its --no- form is rejected (PARSE_OPT_NONEG).
_ARCHIVE_VALUE_LONG = frozenset({
    "format", "prefix", "add-file", "add-virtual-file", "output", "mtime",
    "remote", "exec",
})
_ARCHIVE_VALUE_SHORT = frozenset({"o"})  # -o takes a value (space or attached)


def _archive_validate_options(argv: list[str]) -> None:
    """parse_archive_args option scan: reject unknown options and honour -h.

    Mirrors parse-options' token walk (archive.c uses the default flags so
    internal -h and unknown-option detection are active).  A space-form value
    option consumes its next token verbatim (even one that looks like an
    option); "--" ends option processing.  Raises :class:`_ArchiveUsage`.
    """
    i = 0
    n = len(argv)
    while i < n:
        tok = argv[i]
        if tok == "--":
            return  # rest are positionals
        if tok in ("-h", "--help", "--help-all"):
            raise _ArchiveUsage(to_stdout=True)
        if tok.startswith("--"):
            name = tok[2:]
            eq = name.find("=")
            base = name[:eq] if eq >= 0 else name
            if base not in _ARCHIVE_KNOWN_LONG:
                raise _ArchiveUsage(
                    lead="error: unknown option `%s'" % base)
            # Space-form value option consumes the next token verbatim.
            if eq < 0 and base in _ARCHIVE_VALUE_LONG:
                i += 2
                continue
            i += 1
            continue
        if tok.startswith("-") and tok != "-":
            # Short cluster.  -<digits> is the compression level (OPT_NUMBER).
            if tok[1:].isdigit():
                i += 1
                continue
            c = tok[1]
            if c == "h":
                raise _ArchiveUsage(to_stdout=True)
            if c in ("v", "l"):
                i += 1
                continue
            if c in _ARCHIVE_VALUE_SHORT:
                # -oFILE attached, or "-o FILE" with a separate value token.
                if len(tok) > 2:
                    i += 1
                else:
                    i += 2
                continue
            raise _ArchiveUsage(lead="error: unknown option `%s'" % tok[1:])
        # A non-option positional (tree-ish / path): option parsing continues
        # but this token is not validated here.
        i += 1


def _archive_format_from_filename(name: str) -> Optional[str]:
    """Mirror archive.c:archive_format_from_filename / match_extension.

    Returns the archiver name (tar / tgz / tar.gz / zip) whose registered
    extension matches the trailing component of ``name``; longest match wins
    (so "x.tar.gz" picks "tar.gz" over "gz" — though "gz" is not registered).
    """
    # Registered archivers in init_archivers() order, plus the tar aliases
    # ("tgz", "tar.gz") that the tar archiver registers.  match_extension only
    # matches at a "." boundary: filename must end with "." + ext.
    best = None
    for ext in ("tar", "tgz", "tar.gz", "zip"):
        if name == ext or name.endswith("." + ext):
            if best is None or len(ext) > len(best):
                best = ext
    return best


def _archive_core(argv: list[str], remote: bool) -> tuple[bytes, Optional[str]]:
    """Build an archive from ``argv`` (the tokens after "archive").

    Returns ``(blob, output_path)``.  ``output_path`` is the value of any -o
    captured here (only relevant on the local front-end; the writer passes
    NULL).  Raises :class:`_ArchiveFatal` on any fatal condition so the caller
    can route the message to stderr (local) or sideband band #2 (server).

    ``remote`` mirrors write_archive's ``remote`` argument: when set, a
    tree-ish that is not a real ref is rejected (archive.c:parse_treeish_arg's
    "remote && !remote_allow_unreachable" branch -> die("no such ref: %s")).
    """
    # parse_archive_args runs parse_options first: reject unknown options and
    # honour -h before any archiving work (argparse would silently drop them).
    _archive_validate_options(argv)
    # Pre-scan for the order-sensitive options that argparse cannot model:
    #   * -<digits> compression level (OPT_NUMBER_CALLBACK)
    #   * --add-file / --add-virtual-file (share one ordered string_list, and
    #     each captures the *current* --prefix value as its base at parse time)
    #   * --worktree-attributes (OPT_BOOL)
    # We strip these from argv before handing the remainder to argparse so the
    # numeric level is not mistaken for the tree-ish, and rebuild the extra-file
    # list in command-line order with the right per-option base.
    extra_specs: list[tuple[str, str, str]] = []  # (kind, arg, base)
    compression_level = -1
    worktree_attributes = False
    cur_base = ""  # most-recent --prefix value seen so far
    filtered: list[str] = []
    i = 0
    n_argv = len(argv)
    while i < n_argv:
        tok = argv[i]
        if tok == "--":
            filtered.extend(argv[i:])
            break
        if tok == "--prefix":
            if i + 1 < n_argv:
                cur_base = argv[i + 1]
                filtered.append(tok)
                filtered.append(argv[i + 1])
                i += 2
                continue
        elif tok.startswith("--prefix="):
            cur_base = tok[len("--prefix="):]
            filtered.append(tok)
            i += 1
            continue
        if tok == "--add-file" and i + 1 < n_argv:
            extra_specs.append(("file", argv[i + 1], cur_base))
            i += 2
            continue
        if tok.startswith("--add-file="):
            extra_specs.append(("file", tok[len("--add-file="):], cur_base))
            i += 1
            continue
        if tok == "--add-virtual-file" and i + 1 < n_argv:
            extra_specs.append(("virtual", argv[i + 1], cur_base))
            i += 2
            continue
        if tok.startswith("--add-virtual-file="):
            extra_specs.append(("virtual", tok[len("--add-virtual-file="):], cur_base))
            i += 1
            continue
        if tok in ("--worktree-attributes",):
            worktree_attributes = True
            i += 1
            continue
        if tok == "--no-worktree-attributes":
            worktree_attributes = False
            i += 1
            continue
        # -<digits> numeric compression level (parse_options consumes "-N").
        if len(tok) >= 2 and tok[0] == "-" and tok[1:].isdigit():
            compression_level = int(tok[1:], 10)
            i += 1
            continue
        filtered.append(tok)
        i += 1

    ap = argparse.ArgumentParser(prog="pygit archive", add_help=False)
    # --format is validated against the registered archivers AFTER the missing
    # tree-ish check (lookup_archiver), so it is parsed as a free-form string
    # here rather than constrained by argparse choices.
    ap.add_argument("--format", default=None)
    ap.add_argument("-l", "--list", dest="list_formats", action="store_true")
    ap.add_argument("-o", "--output", default=None)
    ap.add_argument("--prefix", default="")
    ap.add_argument("-v", "--verbose", action="store_true")
    ap.add_argument("--mtime", default=None)
    # --remote/--exec are consumed (and ignored) by the local writer so their
    # space-form values (e.g. `--exec foo`) are not mistaken for the tree-ish;
    # C Git silently ignores --exec when --remote is absent.
    ap.add_argument("--remote", default=None)
    ap.add_argument("--exec", dest="exec_cmd", default=None)
    # rev is the first positional; the rest are pathspecs (after an optional --).
    ap.add_argument("rev", nargs="?")
    ap.add_argument("paths", nargs="*")
    args, _unknown = ap.parse_known_args(filtered)

    if args.list_formats:
        # write_archive prints the registered format names to fd 1; over the
        # wire that is sideband band #1, so the client prints them on stdout.
        return b"tar\ntgz\ntar.gz\nzip\n", args.output

    fmt = args.format
    if fmt is None and args.output:
        fmt = _archive_format_from_filename(args.output)
    if fmt is None:
        fmt = "tar"

    repo = _repo()
    # parse_archive_args order: the missing tree-ish (usage_with_options, rc
    # 129) is checked BEFORE lookup_archiver (Unknown archive format, rc 128).
    if not args.rev:
        raise _ArchiveUsage()

    # lookup_archiver: an unknown --format is fatal once a tree-ish is present.
    if fmt not in ("tar", "tgz", "tar.gz", "zip"):
        raise _ArchiveFatal("Unknown archive format '%s'" % fmt)

    # Compression level validation (parse_archive_args).  Only zip and the
    # tar.gz/tgz filter archivers accept levels; tar (uncompressed) rejects any.
    # zip honors 0-9; the gzip filters additionally allow >9 (HIGH levels).
    if compression_level != -1:
        levels_ok = fmt in ("zip", "tgz", "tar.gz")
        high_ok = fmt in ("tgz", "tar.gz")
        if not (levels_ok and (compression_level <= 9 or high_ok)):
            raise _ArchiveFatal(
                "Argument not supported for format '%s': -%d"
                % (fmt, compression_level))

    # parse_treeish_arg: a remote may only fetch a *ref* (the substring before
    # an optional ":path").  repo_dwim_ref must succeed or it dies.
    name = args.rev
    if remote:
        refpart = name.split(":", 1)[0]
        if refs_mod.dwim_full_name(repo, refpart) is None:
            raise _ArchiveFatal("no such ref: %s" % refpart)

    sha = refs_mod.rev_parse(repo, name)
    if not sha:
        raise _ArchiveFatal("not a valid object name: %s" % name)
    t, data = objs.read_object(repo, sha)
    if t == "commit":
        commit = objs.parse_commit(data)
        tree = commit.tree
        _who, archive_time, _tz = _split_ident(commit.committer)
        commit_oid = sha
    else:
        tree = sha
        archive_time = 0
        commit_oid = None
    if archive_time is None:
        archive_time = 0

    if args.mtime is not None:
        # C Git: archive_time = approxidate(mtime_option).  approxidate never
        # fails — deterministic spellings parse exactly, and any relative /
        # unrecognised form (e.g. "now", "2 days ago", garbage) resolves to the
        # wall clock, matching git's rc 0.  The wall-clock value is inherently
        # non-reproducible, but it only reaches stdout for an mtime-to-stdout
        # archive; the common -o <file> form keeps stdout/stderr empty.
        parsed = objs._parse_date_env(args.mtime)
        if parsed is not None:
            archive_time = parsed[0]
        else:
            stripped = args.mtime.strip()
            try:
                archive_time = int(stripped)
            except ValueError:
                import time as _time
                archive_time = int(_time.time())

    # Trailing pathspecs restrict the archive; each must match at least one
    # path (archive.c:parse_pathspec_arg -> path_exists), else a fatal error.
    pathspec = list(args.paths)
    for ps in pathspec:
        if ps and not _archive_pathspec_matches(repo, tree, ps):
            raise _ArchiveFatal("pathspec '%s' did not match any files" % ps)

    # Extra files (--add-file / --add-virtual-file), in command-line order.
    # Each carries its final in-archive name (already resolved with the per-
    # option --prefix base), its content, and the canon-ized mode.  archive.c's
    # write_archive_entries appends these after the tree walk, in order.
    import stat as _stat
    extra_files: list[tuple[str, bytes, int]] = []
    for kind, arg, base in extra_specs:
        if kind == "file":
            # --add-file: name = base + basename(path); content read from disk.
            p = Path(arg)
            try:
                st = p.stat()
            except OSError:
                raise _ArchiveFatal("File not found: %s" % arg)
            if not _stat.S_ISREG(st.st_mode):
                raise _ArchiveFatal("Not a regular file: %s" % arg)
            name = (base or "") + p.name
            extra_files.append((name, p.read_bytes(), st.st_mode))
        else:
            # --add-virtual-file=<path>:<content> (path may be C-quoted).
            vpath, content = _parse_virtual_file(arg)
            # The virtual file does NOT take the --prefix base (archive.c uses
            # the bare path), and is always a regular 0644 file.
            extra_files.append((vpath, content,
                                _stat.S_IFREG | 0o644))

    # Build the export-ignore/export-subst attribute resolver. Only meaningful
    # when archiving a commit/tree that may carry .gitattributes.
    attrs = _ArchiveAttrs(repo, tree, worktree_attributes)
    commit_obj = commit if commit_oid else None

    if fmt == "tar":
        blob = _git_archive_tar(repo, tree, commit_oid, archive_time,
                                args.prefix, args.verbose, pathspec, extra_files,
                                attrs, commit_obj)
        return blob, args.output

    if fmt in ("tgz", "tar.gz"):
        import zlib, struct
        tar = _git_archive_tar(repo, tree, commit_oid, archive_time,
                               args.prefix, args.verbose, pathspec, extra_files,
                               attrs, commit_obj)
        # archive-tar.c:write_tar_filter_archive builds a gzip stream with a
        # gz_header_s of { .os = 3 } (Unix, "for reproducibility"), mtime 0, no
        # filename, and the requested level (Z_DEFAULT_COMPRESSION = level 6).
        # git_deflate_init_gzip calls deflateInit2(level); an out-of-range level
        # (>9) makes zlib return Z_STREAM_ERROR, which git reports via die().
        gz_level = 6 if compression_level == -1 else compression_level
        try:
            co = zlib.compressobj(gz_level, zlib.DEFLATED, -zlib.MAX_WBITS)
        except (ValueError, zlib.error):
            # zerr_to_string(Z_STREAM_ERROR) with a NULL strm->z.msg.
            raise _ArchiveFatal(
                "deflateInit2: stream consistency error (no message)")
        # XFL byte (offset 8): zlib's deflate sets it from the level —
        # level 9 -> 2 (best), level < 2 -> 4 (fastest), else 0.  Because we
        # build the gzip wrapper by hand (raw deflate body), replicate it.
        if gz_level == 9:
            xfl = 2
        elif gz_level < 2:
            xfl = 4
        else:
            xfl = 0
        header = b"\x1f\x8b\x08\x00" + struct.pack("<I", 0) + bytes([xfl, 3])
        body = co.compress(tar) + co.flush()
        trailer = struct.pack("<II", zlib.crc32(tar) & 0xffffffff,
                              len(tar) & 0xffffffff)
        return header + body + trailer, args.output

    blob = _git_archive_zip(repo, tree, commit_oid, archive_time,
                            args.prefix, args.verbose, pathspec, extra_files,
                            compression_level, attrs, commit_obj)
    return blob, args.output


def cmd_archive(argv: list[str]) -> int:
    # This front-end parse only routes --remote / --list; option validation and
    # unknown-format detection happen in _archive_core (parse_archive_args), so
    # --format is left unconstrained here.
    ap = argparse.ArgumentParser(prog="pygit archive", add_help=False)
    ap.add_argument("--format", default=None)
    ap.add_argument("-l", "--list", dest="list_formats", action="store_true")
    ap.add_argument("-o", "--output", default=None)
    ap.add_argument("--prefix", default="")
    ap.add_argument("-v", "--verbose", action="store_true")
    ap.add_argument("--mtime", default=None)
    # --remote=<repo> retrieves the archive from <repo> by speaking the
    # git-upload-archive protocol (pkt-line argument lines + sideband stream).
    # --exec=<cmd> names the remote upload-archive program; C Git silently
    # ignores it when --remote is absent, so we accept and ignore it there.
    ap.add_argument("--remote", default=None)
    ap.add_argument("--exec", dest="exec_cmd", default="git-upload-archive")
    ap.add_argument("rev", nargs="?")
    args, _unknown = ap.parse_known_args(argv)

    if args.remote is not None:
        return _run_remote_archiver(argv, args.remote, args.exec_cmd)

    if args.list_formats:
        for f in ("tar", "tgz", "tar.gz", "zip"):
            _print(f)
        return 0

    try:
        blob, output = _archive_core(argv, remote=False)
    except _ArchiveUsage as u:
        # usage_with_options: "-h" -> stdout rc 129; otherwise stderr rc 129,
        # optionally preceded by an "error: unknown option `x'" line.
        if u.to_stdout:
            sys.stdout.write(_ARCHIVE_USAGE)
        else:
            if u.lead:
                _err(u.lead)
            sys.stderr.write(_ARCHIVE_USAGE)
        return 129
    except _ArchiveFatal as e:
        _err("fatal: %s" % e)
        return 128

    # create_output_file opens -o verbatim (O_CREAT|O_WRONLY|O_TRUNC): "-" is a
    # literal filename on disk, not a stdout alias.
    if output:
        Path(output).write_bytes(blob)
    else:
        _write_stdout_bytes(blob)
    return 0


# --- git-upload-archive protocol: pkt-line + sideband -----------------------

def _pktline(payload: bytes) -> bytes:
    """Encode one pkt-line; payload must be < 65516 bytes."""
    return b"%04x" % (len(payload) + 4) + payload


def _pkt_read_line(rf) -> Optional[bytes]:
    """Read one pkt-line from binary stream ``rf``.

    Returns the payload bytes for a normal packet, or ``None`` for a flush
    (0000).  Raises EOFError on a truncated stream.
    """
    hdr = rf.read(4)
    if len(hdr) < 4:
        raise EOFError("unexpected EOF reading pkt-line length")
    n = int(hdr, 16)
    if n == 0:
        return None  # flush
    if n < 4:
        raise EOFError("invalid pkt-line length %04x" % n)
    body = rf.read(n - 4)
    if len(body) < n - 4:
        raise EOFError("unexpected EOF reading pkt-line body")
    return body


# send_sideband chunk size: upload-archive's process_input reads 16384 bytes
# at a time, so each data packet carries at most 16384 bytes (sideband.c uses
# LARGE_PACKET_MAX=65520, but the read buffer is the binding constraint).
_SIDEBAND_CHUNK = 16384


def _send_sideband(wf, band: int, data: bytes) -> None:
    """Multiplex ``data`` on ``band`` (1=data, 2=progress, 3=error)."""
    if not data:
        return
    i = 0
    while i < len(data):
        chunk = data[i:i + _SIDEBAND_CHUNK]
        hdr = b"%04x" % (len(chunk) + 5) + bytes([band])
        wf.write(hdr)
        wf.write(chunk)
        i += len(chunk)


def _enter_repo(path: str) -> Optional[Repository]:
    """Resolve a repository the way setup.c:enter_repo does for the writer.

    Tries the suffixes "/.git", "", ".git/.git", ".git" in order and returns a
    Repository bound to the first that is a real git directory, or None.
    """
    if not path:
        return None
    p = path
    while len(p) > 1 and p.endswith("/"):
        p = p[:-1]
    for suffix in ("/.git", "", ".git/.git", ".git"):
        cand = Path(p + suffix)
        try:
            if not cand.is_dir():
                continue
            if (cand / "HEAD").exists() and (cand / "objects").is_dir():
                return Repository(cand.parent if cand.name == ".git" else cand,
                                  gitdir=cand,
                                  bare=(cand.name != ".git"))
        except OSError:
            continue
    return None


def _recv_sideband(rf, out, on_error=None) -> int:
    """Client side: demux ``rf`` to ``out`` (data) / stderr (progress+error).

    Faithful to sideband.c:demultiplex_sideband with die_on_error=0 and a dumb
    (non-tty) terminal: band 1 -> ``out``; band 2 lines -> "remote: <line>" +
    8-space clear-suffix; band 3 -> accumulated "remote: <msg>" flushed with a
    trailing newline.  Returns the sideband_type (0 = clean primary stream end,
    nonzero = an error/flush terminal state), matching recv_sideband's return.

    ``on_error`` (if given) is invoked just before the band #3 (remote error)
    line is emitted; over the local transport the upload-archive front-end's
    "fatal: sent error to the client: ..." die lands there, interleaved between
    the band #2 message and the band #3 deadchild notice (git's ordering).
    """
    SUFFIX = b"        "  # DUMB_SUFFIX (stderr is not a tty under the harness)
    PREFIX = b"remote: "
    scratch = bytearray()
    err = sys.stderr.buffer
    while True:
        try:
            line = _pkt_read_line(rf)
        except EOFError:
            scratch += (b"\n" if scratch else b"") + b"archive: unexpected disconnect while reading sideband packet"
            if scratch:
                err.write(bytes(scratch) + b"\n")
                err.flush()
            return 5  # SIDEBAND_PROTOCOL_ERROR
        if line is None:
            # flush / delim -> SIDEBAND_FLUSH
            if scratch:
                err.write(bytes(scratch) + b"\n")
                err.flush()
            return 0
        if len(line) == 0:
            scratch += (b"\n" if scratch else b"") + b"archive: protocol error: missing sideband designator"
            err.write(bytes(scratch) + b"\n")
            err.flush()
            return 5
        band = line[0]
        payload = line[1:]
        if band == 1:
            out.write(payload)
        elif band == 2:
            b = payload
            # Append clear-to-eol suffix to each nonempty line; flush per line.
            while True:
                idx = _first_brk(b)
                if idx < 0:
                    break
                linelen = idx
                if scratch and linelen == 0:
                    scratch += SUFFIX
                if not scratch:
                    scratch += PREFIX
                if linelen > 0:
                    scratch += b[:linelen] + SUFFIX
                scratch += b[idx:idx + 1]
                err.write(bytes(scratch))
                err.flush()
                scratch = bytearray()
                b = b[idx + 1:]
            if b:
                if not scratch:
                    scratch += PREFIX
                scratch += b
        elif band == 3:
            if on_error is not None:
                # Local-transport interleaving: flush the complete band #2
                # message, emit the upload-archive front-end's die, then the
                # band #3 deadchild line (git's observed ordering).
                if scratch:
                    err.write(bytes(scratch) + b"\n")
                    err.flush()
                    scratch = bytearray()
                on_error()
                err.write(bytes(PREFIX + payload) + b"\n")
                err.flush()
                return 2  # SIDEBAND_REMOTE_ERROR
            scratch += (b"\n" if scratch else b"") + PREFIX + payload
            # flush remaining scratch and return error
            if scratch:
                err.write(bytes(scratch) + b"\n")
                err.flush()
            return 2  # SIDEBAND_REMOTE_ERROR
        else:
            scratch += (b"\n" if scratch else b"") + b"archive: protocol error: bad band #%d" % band
            err.write(bytes(scratch) + b"\n")
            err.flush()
            return 5


def _first_brk(b: bytes) -> int:
    """Index of the first '\\n' or '\\r' in ``b``, or -1 (strpbrk(b, "\\n\\r"))."""
    n = b.find(b"\n")
    r = b.find(b"\r")
    if n < 0:
        return r
    if r < 0:
        return n
    return min(n, r)


def _strip_client_only_opts(tokens: list[str]) -> list[str]:
    """Return ``tokens`` with -o/--output, --remote and --exec (and their
    values) removed, preserving order — mirrors what archive.c's parse_options
    consumes locally before forwarding the rest to the writer.
    """
    out: list[str] = []
    i = 0
    takes_value = {"-o", "--output", "--remote", "--exec"}
    while i < len(tokens):
        tok = tokens[i]
        if tok in takes_value:
            i += 2  # skip flag and its separate value
            continue
        if any(tok.startswith(f + "=") for f in ("--output", "--remote", "--exec")):
            i += 1
            continue
        if tok.startswith("-o") and len(tok) > 2 and not tok.startswith("-o="):
            # "-oFILE" attached form
            i += 1
            continue
        out.append(tok)
        i += 1
    return out


def _run_remote_archiver(argv: list[str], remote: str, exec_cmd: str) -> int:
    """Port of builtin/archive.c:run_remote_archiver for a local-path remote.

    Connects to ``remote`` by spawning the upload-archive command over a pipe,
    sends "argument <arg>" pkt-lines, expects ACK + flush, then streams the
    sideband-multiplexed archive to stdout (or the -o file).
    """
    import subprocess

    # Determine the -o output for create_output_file + name_hint.
    output = None
    i = 0
    while i < len(argv):
        t = argv[i]
        if t in ("-o", "--output"):
            output = argv[i + 1] if i + 1 < len(argv) else None
            i += 2
            continue
        if t.startswith("--output="):
            output = t[len("--output="):]
            i += 1
            continue
        if t.startswith("-o") and len(t) > 2:
            output = t[2:]
            i += 1
            continue
        i += 1

    out_fh = None
    if output and output != "-":
        out_fh = open(output, "wb")
    out = out_fh if out_fh is not None else sys.stdout.buffer

    # Spawn the remote upload-archive.  For the built-in default we run pygit's
    # own writer in-process style via a child python; an explicit --exec is run
    # through the shell exactly as git's local transport does
    # (sh -c "<exec> '<path>'"), so user-supplied servers (incl. real git)
    # round-trip.
    # The upload-archive front-end (our child) prints "fatal: sent error to the
    # client: ..." to its stderr only AFTER it has relayed the band #2/#3 error
    # over the pipe.  We capture that stderr and replay it after _recv_sideband
    # demuxes the "remote:" lines, so the client sees: band #2 line, band #3
    # deadchild, then the front-end die — matching git's interleaving.
    if exec_cmd in ("git-upload-archive", "git upload-archive"):
        cmd = [sys.executable, "-m", "pythongit", "upload-archive", remote]
        # Run the *same* pythongit package tree we are executing from, so the
        # round-trip never picks up a divergent installed copy.
        child_env = dict(os.environ)
        pkg_parent = str(Path(__file__).resolve().parent.parent)
        existing = child_env.get("PYTHONPATH", "")
        child_env["PYTHONPATH"] = (
            pkg_parent + (os.pathsep + existing if existing else ""))
        proc = subprocess.Popen(cmd, stdin=subprocess.PIPE,
                                stdout=subprocess.PIPE,
                                stderr=subprocess.PIPE, env=child_env)
    else:
        import shlex
        shell_cmd = "%s %s" % (exec_cmd, shlex.quote(remote))
        proc = subprocess.Popen(["sh", "-c", shell_cmd],
                                stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                stderr=subprocess.PIPE)

    wf = proc.stdin
    rf = proc.stdout

    # Inject a fake --format from the output filename so an explicit --format
    # can still override it (archive.c run_remote_archiver).
    if output:
        fmt = _archive_format_from_filename(output)
        if fmt:
            wf.write(_pktline(b"argument --format=%s\n" % fmt.encode()))
    for tok in _strip_client_only_opts(argv):
        wf.write(_pktline(b"argument %s\n" % tok.encode()))
    wf.write(b"0000")
    wf.flush()

    def _drain_child() -> None:
        # Avoid a deadlock on the captured stderr pipe before waiting.
        if proc.stderr is not None:
            try:
                proc.stderr.read()
            except Exception:  # noqa: BLE001
                pass
        proc.wait()

    # Expect ACK\n then a flush.
    try:
        first = _pkt_read_line(rf)
    except EOFError:
        first = b""
    if first is None:
        _err("fatal: git archive: expected ACK/NAK, got a flush packet")
        _drain_child()
        if out_fh:
            out_fh.close()
        return 128
    line = first.rstrip(b"\n")
    if line != b"ACK":
        if line.startswith(b"NACK "):
            _err("fatal: git archive: NACK %s" % line[5:].decode("utf-8", "replace"))
        else:
            _err("fatal: git archive: protocol error")
        _drain_child()
        if out_fh:
            out_fh.close()
        return 128
    flush = _pkt_read_line(rf)
    if flush is not None:
        _err("fatal: git archive: expected a flush")
        _drain_child()
        if out_fh:
            out_fh.close()
        return 128

    # On a remote error the upload-archive front-end's "fatal: sent error to the
    # client: ..." die is interleaved BETWEEN the band #2 message and the band
    # #3 deadchild notice.  We capture the child's stderr and replay it from the
    # sideband demux at exactly that point (see _recv_sideband's on_error).
    def _replay_front_end_die() -> None:
        if proc.stderr is None:
            return
        try:
            data = proc.stderr.read()
        except Exception:  # noqa: BLE001
            return
        if data:
            sys.stderr.buffer.write(data)
            sys.stderr.buffer.flush()

    rv = _recv_sideband(rf, out, on_error=_replay_front_end_die)
    out.flush()
    if out_fh:
        out_fh.close()
    proc.wait()
    return 1 if rv else 0


class _BundleUnknownRev(Exception):
    """An explicit `bundle create` rev did not resolve (setup_revisions die)."""


def _bundle_resolve_tips(repo: Repository, rev_args: list[str]
                         ) -> tuple[list[tuple[str, str]], list[str]]:
    """Resolve `bundle create` rev-list arguments into ordered (sha, refname)
    tips for the bundle header (write_bundle_refs / rev-list pending order) and
    the list of negative (^rev / --not) tip SHAs that exclude history.

    Supports the deterministic subset used in practice: explicit refs/revs plus
    the pseudo-refs --all, --branches, --tags, --remotes, and `^<rev>` / `--not`
    exclusions (which make the bundle incremental).  For --all, git lists every
    ref (sorted by for_each_ref) followed by HEAD.
    """
    tips: list[tuple[str, str]] = []
    seen_names: set[str] = set()
    negatives: list[str] = []

    def add(sha: str, display: str) -> None:
        if sha and display not in seen_names:
            seen_names.add(display)
            tips.append((sha, display))

    use_all = False
    use_branches = False
    use_tags = False
    use_remotes = False
    explicit: list[str] = []
    not_flag = False  # --not toggles the sense of following revs
    for a in rev_args:
        if a == "--all":
            use_all = True
        elif a == "--branches":
            use_branches = True
        elif a == "--tags":
            use_tags = True
        elif a == "--remotes":
            use_remotes = True
        elif a == "--not":
            not_flag = True
            continue
        elif a == "--no-not":
            not_flag = False
            continue
        elif a.startswith("^"):
            # Negative tip: exclude history reachable from this rev.
            rest = a[1:]
            sha = refs_mod.rev_parse(repo, rest)
            if not sha:
                raise _BundleUnknownRev(a)
            negatives.append(sha)
        elif a.startswith("-"):
            # Other rev-list options (e.g. --since) are accepted but not honored
            # for tip selection here.
            continue
        elif ".." in a and not a.startswith(".") and "..." not in a:
            # A..B range: include B, exclude A (setup_revisions).
            lo, _, hi = a.partition("..")
            lo = lo or "HEAD"
            hi = hi or "HEAD"
            lo_sha = refs_mod.rev_parse(repo, lo)
            if not lo_sha:
                raise _BundleUnknownRev(lo)
            negatives.append(lo_sha)
            explicit.append(hi)
        elif "..." in a:
            # A...B symmetric difference: include both A and B, exclude their
            # merge base(s).  setup_revisions adds A, B as positive and the
            # merge base(s) as negative.
            lo, _, hi = a.partition("...")
            lo = lo or "HEAD"
            hi = hi or "HEAD"
            lo_sha = refs_mod.rev_parse(repo, lo)
            hi_sha = refs_mod.rev_parse(repo, hi)
            if not lo_sha:
                raise _BundleUnknownRev(lo)
            if not hi_sha:
                raise _BundleUnknownRev(hi)
            explicit.append(lo)
            explicit.append(hi)
            try:
                from . import merge as _m
                for mb in _m.merge_bases(repo, lo_sha, hi_sha):
                    negatives.append(mb)
            except Exception:
                pass
        else:
            if not_flag:
                sha = refs_mod.rev_parse(repo, a)
                if not sha:
                    raise _BundleUnknownRev(a)
                negatives.append(sha)
            else:
                explicit.append(a)

    all_refs = _all_refs(repo)
    if use_all or use_branches or use_tags or use_remotes:
        for name in sorted(all_refs):
            if use_all:
                ok = (name.startswith("refs/heads/")
                      or name.startswith("refs/tags/")
                      or name.startswith("refs/remotes/"))
            else:
                ok = ((use_branches and name.startswith("refs/heads/"))
                      or (use_tags and name.startswith("refs/tags/"))
                      or (use_remotes and name.startswith("refs/remotes/")))
            if ok:
                add(all_refs[name], name)
        if use_all:
            _sym, head = refs_mod.read_head(repo)
            if head:
                add(head, "HEAD")

    for r in explicit:
        sha = refs_mod.rev_parse(repo, r)
        if not sha:
            # setup_revisions: an unknown rev is fatal.
            raise _BundleUnknownRev(r)
        # display ref: write_bundle_refs computes display_ref as
        #   (flag & REF_ISSYMREF) ? e->name : <dwim'd full ref>
        # so a symbolic-ref argument (e.g. HEAD) keeps its original spelling,
        # while a plain branch/tag name expands to its full refs/... form.
        display = r
        is_symref = False
        try:
            is_symref = refs_mod.read_symbolic(repo, r) is not None
        except Exception:
            is_symref = False
        if is_symref:
            display = r
        else:
            full = refs_mod.dwim_full_name(repo, r) if hasattr(refs_mod, "dwim_full_name") else None
            if full:
                display = full
            elif not r.startswith("refs/"):
                # bundle uses the dwim'd ref; fall back to refs/heads/<name>.
                if ("refs/heads/" + r) in all_refs:
                    display = "refs/heads/" + r
                elif ("refs/tags/" + r) in all_refs:
                    display = "refs/tags/" + r
        add(sha, display)
    return tips, negatives


def _bundle_boundary_prereqs(repo: Repository, positives: list[str],
                             negatives: list[str]) -> list[tuple[str, str]]:
    """Compute the bundle prerequisite (boundary) commits.

    Port of create_bundle's prerequisite pass (bundle.c:write_bundle_prerequisites
    with revs.boundary=1): a BOUNDARY commit is an UNINTERESTING commit that is a
    direct parent of an interesting (included) commit.  Each is recorded as
    "-<oid> <oneline-subject>" — the subject is the commit's CMIT_FMT_ONELINE
    pretty output, trimmed.

    Returns ordered (oid, subject) pairs.  The traversal/emit order matches git's
    date-ordered boundary walk: boundary commits are emitted in the same order
    traverse_commit_list visits them (most-recent first), de-duplicated.
    """
    if not negatives:
        return []
    # Set of commits reachable from the negative tips (uninteresting).
    uninteresting: set[str] = set()

    def commit_parents(sha: str) -> Optional[list[str]]:
        try:
            t, data = objs.read_object(repo, sha)
        except Exception:
            return None
        if t == "tag":
            for line in data.decode("utf-8", "replace").splitlines():
                if line.startswith("object "):
                    return commit_parents(line[len("object "):].strip())
            return None
        if t != "commit":
            return None
        return list(objs.parse_commit(data).parents)

    # Walk uninteresting commit history.
    stack = list(negatives)
    while stack:
        sha = stack.pop()
        if sha in uninteresting:
            continue
        parents = commit_parents(sha)
        if parents is None:
            continue
        uninteresting.add(sha)
        stack.extend(parents)

    # Walk interesting history (reachable from positives, not uninteresting) and
    # record boundary commits (uninteresting parents of interesting commits).
    # Use date ordering so the emission order matches git's commit_list.
    interesting_seen: set[str] = set()
    boundary_order: list[str] = []
    boundary_seen: set[str] = set()

    # Resolve positives to commits (peel tags).
    def peel_to_commit(sha: str) -> Optional[str]:
        seen_local: set[str] = set()
        cur = sha
        while cur and cur not in seen_local:
            seen_local.add(cur)
            try:
                t, data = objs.read_object(repo, cur)
            except Exception:
                return None
            if t == "commit":
                return cur
            if t == "tag":
                nxt = None
                for line in data.decode("utf-8", "replace").splitlines():
                    if line.startswith("object "):
                        nxt = line[len("object "):].strip()
                        break
                cur = nxt
                continue
            return None
        return None

    # Date-ordered priority walk (mirrors the commit-date heap git uses).
    import heapq
    counter = 0
    heap: list[tuple[int, int, str]] = []

    def commit_date(sha: str) -> int:
        try:
            _t, data = objs.read_object(repo, sha)
            c = objs.parse_commit(data)
            _who, ts, _tz = _split_ident(c.committer)
            return ts or 0
        except Exception:
            return 0

    for p in positives:
        cm = peel_to_commit(p)
        if cm and cm not in uninteresting:
            heapq.heappush(heap, (-commit_date(cm), counter, cm))
            counter += 1
    while heap:
        _negdate, _ord, sha = heapq.heappop(heap)
        if sha in interesting_seen:
            continue
        interesting_seen.add(sha)
        parents = commit_parents(sha)
        if parents is None:
            continue
        for par in parents:
            if par in uninteresting:
                if par not in boundary_seen:
                    boundary_seen.add(par)
                    boundary_order.append(par)
            elif par not in interesting_seen:
                heapq.heappush(heap, (-commit_date(par), counter, par))
                counter += 1

    out: list[tuple[str, str]] = []
    for bsha in boundary_order:
        subj = _bundle_oneline_subject(repo, bsha)
        out.append((bsha, subj))
    return out


def _bundle_oneline_subject(repo: Repository, sha: str) -> str:
    """The CMIT_FMT_ONELINE subject for a commit, trimmed (bundle prereq line)."""
    try:
        _t, data = objs.read_object(repo, sha)
        c = objs.parse_commit(data)
    except Exception:
        return ""
    msg = c.message
    # CMIT_FMT_ONELINE: the first paragraph collapsed to one line; in practice
    # the subject is the first line, trimmed of surrounding whitespace.
    first = msg.splitlines()[0] if msg.strip() else ""
    return first.strip()


def _bundle_parse_header(raw: bytes) -> tuple[Optional[str], list[tuple[str, str]], list[tuple[str, str]], int]:
    """Parse a v2/v3 bundle header.

    Returns (hash_algo, prerequisites, references, body_offset) where
    prerequisites/references are lists of (oid, name) and body_offset is the
    byte offset of the pack data.  hash_algo is None for v2 (sha1).
    """
    if raw.startswith(b"# v2 git bundle\n"):
        hash_algo = None
        pos = len(b"# v2 git bundle\n")
    elif raw.startswith(b"# v3 git bundle\n"):
        hash_algo = "sha1"
        pos = len(b"# v3 git bundle\n")
    else:
        raise ValueError("not a git bundle")
    prereqs: list[tuple[str, str]] = []
    refs: list[tuple[str, str]] = []
    while pos < len(raw):
        nl = raw.find(b"\n", pos)
        if nl < 0:
            break
        line = raw[pos:nl]
        pos = nl + 1
        if line == b"":
            break  # end of header
        text = line.decode("utf-8", "surrogateescape")
        if text.startswith("@"):
            if text.startswith("@object-format="):
                hash_algo = text[len("@object-format="):]
            continue
        if text.startswith("-"):
            rest = text[1:]
            # bundle.c:read_bundle_header_fd parses the prerequisite OID and
            # DISCARDS the trailing subject — it stores "" as the name.  verify
            # then prints "error: <oid> " (empty subject, trailing space) even
            # though the bundle file records a subject.
            oid, _, _subj = rest.partition(" ")
            prereqs.append((oid, ""))
        else:
            oid, _, name = text.partition(" ")
            refs.append((oid, name))
    return hash_algo, prereqs, refs, pos


# --- bundle usage blocks (mirror builtin/bundle.c) --------------------------
# The four subcommand usage lines (BUILTIN_BUNDLE_*_USAGE) joined into the
# top-level usage and reused per-subcommand below.
_BUNDLE_CREATE_USAGE = (
    "git bundle create [-q | --quiet | --progress]\n"
    "                  [--version=<version>] <file> <git-rev-list-args>")
_BUNDLE_VERIFY_USAGE = "git bundle verify [-q | --quiet] <file>"
_BUNDLE_LIST_HEADS_USAGE = "git bundle list-heads <file> [<refname>...]"
_BUNDLE_UNBUNDLE_USAGE = "git bundle unbundle [--progress] <file> [<refname>...]"


# parse-options renders multi-line usagestr entries with "usage: " on the first
# line and "   or: " on the following ones.  A continuation line within one
# entry is padded by usage_len = strlen("usage: ") = 7 spaces (usage_continued
# "%*s%s" in parse-options.c:usage_with_options_internal).
def _bundle_usagestr(*entries: str) -> str:
    out = []
    for i, e in enumerate(entries):
        lead = "usage: " if i == 0 else "   or: "
        lines = e.split("\n")
        out.append(lead + lines[0])
        for cont in lines[1:]:
            out.append(" " * 7 + cont)
    return "\n".join(out) + "\n"


# usage_with_options always finishes with a trailing blank line (the final
# fputc('\n')); when an options table is present it is preceded by a blank line
# (need_newline) before the first option entry.
_BUNDLE_TOP_USAGE = _bundle_usagestr(
    _BUNDLE_CREATE_USAGE, _BUNDLE_VERIFY_USAGE,
    _BUNDLE_LIST_HEADS_USAGE, _BUNDLE_UNBUNDLE_USAGE) + "\n"

# Per-subcommand usage + option blocks, exactly as usage_with_options renders
# the OPT_* tables (parse-options.c).  Used for "-h", missing <file>, and
# unknown-option errors.
_BUNDLE_CREATE_HELP = _bundle_usagestr(_BUNDLE_CREATE_USAGE) + (
    "\n"
    "    -q, --[no-]quiet      do not show progress meter\n"
    "    --[no-]progress       show progress meter\n"
    "    --[no-]version <n>    specify bundle format version\n"
    "\n")
_BUNDLE_VERIFY_HELP = _bundle_usagestr(_BUNDLE_VERIFY_USAGE) + (
    "\n"
    "    -q, --[no-]quiet      do not show bundle details\n"
    "\n")
_BUNDLE_LIST_HEADS_HELP = _bundle_usagestr(_BUNDLE_LIST_HEADS_USAGE) + "\n"
_BUNDLE_UNBUNDLE_HELP = _bundle_usagestr(_BUNDLE_UNBUNDLE_USAGE) + (
    "\n"
    "    --[no-]progress       show progress meter\n"
    "\n")


class _BundleUsageError(Exception):
    """A bundle subcommand parse error: emit ``lead`` then ``help_block`` and
    exit ``rc`` (mirrors usage_msg_opt / the unknown-option path).

    ``blank`` reproduces usage_msg_opt's die_message("%s\\n", msg) which inserts
    a blank line between the leading fatal and the usage; the parse-options
    unknown-option path emits no such blank line.
    """

    def __init__(self, help_block: str, lead: str = "", rc: int = 129,
                 blank: bool = False):
        super().__init__(lead)
        self.help_block = help_block
        self.lead = lead
        self.rc = rc
        self.blank = blank


def _bundle_emit_usage_error(exc: "_BundleUsageError") -> int:
    """Emit a bundle parse error (leading line + optional blank + usage)."""
    if exc.lead:
        _err(exc.lead)
    if exc.blank:
        _err("")
    sys.stderr.write(exc.help_block)
    return exc.rc


def _bundle_parse_subcmd(rest: list[str], help_block: str,
                         bool_flags: dict, value_flags: dict):
    """parse_options_cmd_bundle: PARSE_OPT_STOP_AT_NON_OPTION.

    Parses options out of ``rest`` until the first non-option (the <file>).
    ``bool_flags`` maps a recognised flag spelling to a key set True; negation
    ``--no-<long>`` is accepted.  ``value_flags`` maps "--name" to a key for
    OPT_INTEGER-style options (``--name <v>`` / ``--name=<v>``).  Returns
    ``(opts, argv_after_options)`` where argv[0] is the <file>.  Raises
    :class:`_BundleUsageError` for an unknown option (rc 129 + help) and for a
    missing <file> (fatal "need a <file> argument" + help, rc 129).
    """
    opts: dict = {}
    i = 0
    n = len(rest)
    while i < n:
        a = rest[i]
        if a == "--":
            i += 1
            break
        if not a.startswith("-") or a == "-":
            break  # first non-option: stop (STOP_AT_NON_OPTION)
        matched = False
        # boolean flags (and their --no- form)
        if a in bool_flags:
            opts[bool_flags[a]] = True
            matched = True
        elif a.startswith("--no-") and ("--" + a[len("--no-"):]) in bool_flags:
            opts[bool_flags["--" + a[len("--no-"):]]] = False
            matched = True
        else:
            # value (OPT_INTEGER) flags: --name <v> or --name=<v>
            for name, key in value_flags.items():
                if a == name:
                    if i + 1 >= n:
                        raise _BundleUsageError(
                            help_block,
                            "error: option `%s' requires a value"
                            % name.lstrip("-"))
                    opts[key] = rest[i + 1]
                    i += 1
                    matched = True
                    break
                if a.startswith(name + "="):
                    opts[key] = a[len(name) + 1:]
                    matched = True
                    break
        if not matched:
            # parse-options "unknown option `<name>'": strip the leading dashes.
            nm = a[2:] if a.startswith("--") else a[1:]
            raise _BundleUsageError(
                help_block, "error: unknown option `%s'" % nm)
        i += 1
    argv_after = rest[i:]
    if not argv_after:
        raise _BundleUsageError(
            help_block, "fatal: need a <file> argument", blank=True)
    return opts, argv_after


def cmd_bundle(argv: list[str]) -> int:
    # Hand-rolled dispatch: create/verify/list-heads/unbundle all take a bundle
    # file plus extra arguments (rev-list args for create, ref filters for
    # list-heads/unbundle), so we avoid argparse subparsers that would reject
    # rev-list options like --all.
    #
    # OPT_SUBCOMMAND (cmd_bundle): a bare "bundle" needs a subcommand and a
    # top-level "-h" prints the combined usage to stdout (rc 129).  An unknown
    # subcommand is rejected with a backtick-quoted message + usage (rc 129).
    if argv and argv[0] in ("-h", "--help"):
        sys.stdout.write(_BUNDLE_TOP_USAGE)
        return 129
    if not argv:
        sys.stderr.write("error: need a subcommand\n")
        sys.stderr.write(_BUNDLE_TOP_USAGE)
        return 129
    action = argv[0]
    rest = argv[1:]
    if action not in ("create", "verify", "list-heads", "unbundle"):
        sys.stderr.write("error: unknown subcommand: `%s'\n" % action)
        sys.stderr.write(_BUNDLE_TOP_USAGE)
        return 129

    # Per-subcommand "-h" prints that subcommand's usage+options to stdout.
    _sub_help = {
        "create": _BUNDLE_CREATE_HELP,
        "verify": _BUNDLE_VERIFY_HELP,
        "list-heads": _BUNDLE_LIST_HEADS_HELP,
        "unbundle": _BUNDLE_UNBUNDLE_HELP,
    }
    if rest and rest[0] in ("-h", "--help"):
        sys.stdout.write(_sub_help[action])
        return 129

    repo = _repo()

    if action == "create":
        # parse_options_cmd_bundle: STOP_AT_NON_OPTION parses the create flags
        # only until the <file>; anything after it is handed to setup_revisions
        # as a rev-list arg.  A create flag placed AFTER the <file> is therefore
        # an "unrecognized argument" (create_bundle's argc>1 check), not a flag.
        try:
            opts, toks = _bundle_parse_subcmd(
                rest, _BUNDLE_CREATE_HELP,
                bool_flags={
                    "-q": "quiet", "--quiet": "quiet",
                    "--progress": "progress",
                    "--all-progress": "all_progress",
                    "--all-progress-implied": "all_progress_implied",
                },
                value_flags={"--version": "version"})
        except _BundleUsageError as exc:
            return _bundle_emit_usage_error(exc)
        version = -1
        if "version" in opts:
            try:
                version = int(opts["version"])
            except (ValueError, TypeError):
                version = -1
        path = toks[0]
        rev_args = toks[1:]
        # setup_revisions rejects create-only flags (and any unknown rev-list
        # option) that appear after the <file>: "error: unrecognized argument".
        for ra in rev_args:
            base = ra.split("=", 1)[0]
            if (ra in ("-q", "--quiet", "--progress", "--all-progress",
                       "--all-progress-implied")
                    or base == "--version"):
                _err("error: unrecognized argument: %s" % ra)
                return 1
        try:
            tips, negatives = _bundle_resolve_tips(repo, rev_args)
        except _BundleUnknownRev as exc:
            _err("fatal: ambiguous argument '%s': unknown revision or path "
                 "not in the working tree." % exc.args[0])
            _err("Use '--' to separate paths from revisions, like this:")
            _err("'git <command> [<revision>...] -- [<file>...]'")
            return 128
        # create_bundle: version defaults to min_version (2, or 3 for sha256 /
        # object filters) then is validated.  Any explicit version outside
        # {2,3} is fatal — checked before write_bundle_refs (i.e. before the
        # empty-bundle die).
        min_version = 3 if repo.object_format() == "sha256" else 2
        if version == -1:
            version = min_version
        if version < 2 or version > 3:
            _err("fatal: unsupported bundle version %d" % version)
            return 128
        if version < min_version:
            _err("fatal: cannot write bundle version %d with algorithm %s"
                 % (version, repo.object_format()))
            return 128

        # write_bundle_refs only writes a ref whose tip commit survives the
        # exclusion: a tip fully reachable from a negative (^rev / --not) tip is
        # UNINTERESTING and dropped, so an all-excluded ref set yields ref_count
        # 0 -> "Refusing to create empty bundle".
        if negatives:
            bundle_excluded: set[str] = set()
            _nstack = list(negatives)
            while _nstack:
                _ns = _nstack.pop()
                if _ns in bundle_excluded:
                    continue
                bundle_excluded.add(_ns)
                try:
                    _nc = objs.parse_commit(objs.read_object(repo, _ns)[1])
                except Exception:  # noqa: BLE001
                    continue
                _nstack.extend(_nc.parents)

            def _tip_kept(sha: str) -> bool:
                cm = refs_mod._peel_to_commit(repo, sha) or sha
                return cm not in bundle_excluded
            tips = [(s, n) for (s, n) in tips if _tip_kept(s)]

        if not tips:
            _err("fatal: Refusing to create empty bundle.")
            return 128

        # Negative tips (^rev / --not) make the bundle incremental: the pack
        # excludes everything reachable from them, and the boundary commits
        # (uninteresting commits that are direct parents of included history)
        # become prerequisites recorded as "-<oid> <oneline-subject>" lines.
        prereqs = _bundle_boundary_prereqs(repo, [s for s, _ in tips], negatives)

        if repo.object_format() == "sha256":
            header = bytearray(b"# v3 git bundle\n@object-format=sha256\n")
        elif prereqs:
            # bundle.c writes a v3 header only when capabilities are needed; a
            # plain prerequisite list still uses v2 (min_version stays 2).
            header = bytearray(b"# v2 git bundle\n")
        else:
            header = bytearray(b"# v2 git bundle\n")
        # Prerequisite lines precede the ref lines (write order in create_bundle:
        # prerequisites first via write_bundle_prerequisites, then refs).
        for psha, psubj in prereqs:
            header += ("-%s %s\n" % (psha, psubj)).encode("utf-8", "surrogateescape")
        for sha, name in tips:
            header += ("%s %s\n" % (sha, name)).encode("utf-8", "surrogateescape")
        header += b"\n"

        from . import pack as _pack_mod
        from .protocol import _collect_objects
        # The excluded object set is everything reachable from the negative
        # tips (commits, trees, blobs).
        excluded: set[str] = set()
        for nsha in negatives:
            for o in _collect_objects(repo, nsha, set()):
                excluded.add(o)
        objs_list: list[str] = []
        seen: set[str] = set()
        for sha, _ in tips:
            for o in _collect_objects(repo, sha, excluded):
                if o not in seen and o not in excluded:
                    seen.add(o)
                    objs_list.append(o)
        out = sys.stdout.buffer if path == "-" else None
        if out is not None:
            out.write(bytes(header))
            _pack_mod.write_pack_stream_to(repo, objs_list, out.write, collect_entries=False)
            out.flush()
        else:
            with Path(path).open("wb") as fh:
                fh.write(bytes(header))
                _pack_mod.write_pack_stream_to(repo, objs_list, fh.write, collect_entries=False)
        # git's bundle create prints nothing to stdout on success.
        return 0

    if action == "verify":
        # STOP_AT_NON_OPTION: -q/--quiet are honoured only before the <file>;
        # tokens after it become list_bundle_refs filters (verify ignores them),
        # so a trailing "-q" does NOT suppress output.
        try:
            opts, toks = _bundle_parse_subcmd(
                rest, _BUNDLE_VERIFY_HELP,
                bool_flags={"-q": "quiet", "--quiet": "quiet"},
                value_flags={})
        except _BundleUsageError as exc:
            return _bundle_emit_usage_error(exc)
        quiet = bool(opts.get("quiet", False))
        path = toks[0]
        try:
            raw = Path(path).read_bytes()
        except OSError:
            # open_bundle -> read_bundle_header: error(), rc 1.
            _err("error: could not open '%s'" % path)
            return 1
        try:
            hash_algo, prereqs, refs, _off = _bundle_parse_header(raw)
        except ValueError:
            _err("error: '%s' does not look like a v2 or v3 bundle file" % path)
            return 1
        # Prerequisite commits must exist in the local object store.
        missing = [(o, n) for (o, n) in prereqs
                   if _bundle_object_missing(repo, o)]
        if missing:
            _err("error: Repository lacks these prerequisite commits:")
            for o, n in missing:
                _err("error: %s %s" % (o, n))
            return 1
        if not quiet:
            n = len(refs)
            if n == 1:
                _print("The bundle contains this ref:")
            else:
                _print("The bundle contains these %d refs:" % n)
            for o, name in refs:
                _print("%s %s" % (o, name))
            if not prereqs:
                _print("The bundle records a complete history.")
            else:
                pn = len(prereqs)
                if pn == 1:
                    _print("The bundle requires this ref:")
                else:
                    _print("The bundle requires these %d refs:" % pn)
                for o, name in prereqs:
                    _print("%s %s" % (o, name))
            _print("The bundle uses this hash algorithm: %s"
                   % (hash_algo or "sha1"))
        _err("%s is okay" % path)
        return 0

    if action in ("list-heads", "unbundle"):
        # list-heads has no options; unbundle accepts --progress (a NOARG bool).
        # STOP_AT_NON_OPTION: options apply only before the <file>; tokens after
        # it are list_bundle_refs filters.
        help_block = (_BUNDLE_LIST_HEADS_HELP if action == "list-heads"
                      else _BUNDLE_UNBUNDLE_HELP)
        bf = {} if action == "list-heads" else {"--progress": "progress"}
        try:
            _opts, toks = _bundle_parse_subcmd(
                rest, help_block, bool_flags=bf, value_flags={})
        except _BundleUsageError as exc:
            return _bundle_emit_usage_error(exc)
        path = toks[0]
        ref_filter = toks[1:]
        try:
            raw = Path(path).read_bytes()
        except OSError:
            # open_bundle -> read_bundle_header: error(), rc 1.
            _err("error: could not open '%s'" % path)
            return 1
        try:
            _hash_algo, _prereqs, refs, body_off = _bundle_parse_header(raw)
        except ValueError:
            _err("error: '%s' does not look like a v2 or v3 bundle file" % path)
            return 1

        if action == "unbundle":
            # Import the pack (index-pack --fix-thin --stdin), then list refs.
            from . import pack as _pack_mod
            import io as _io
            try:
                _pack_mod.unpack_pack_stream(repo, _io.BytesIO(raw[body_off:]))
            except Exception as exc:  # noqa: BLE001
                _err("fatal: %s" % exc)
                return 128

        for o, name in refs:
            if ref_filter and name not in ref_filter:
                continue
            _print("%s %s" % (o, name))
        return 0

    # Unreachable: action validated against the subcommand set above.
    return 1


def _bundle_object_missing(repo: Repository, oid: str) -> bool:
    try:
        objs.read_object(repo, oid)
        return False
    except Exception:  # noqa: BLE001
        return True


def _enumerate_refs(repo: Repository) -> list[tuple[str, str]]:
    """All refs under refs/ (loose + packed) as (refname, sha), sorted by name."""
    if refs_mod.uses_reftable(repo):
        return sorted((n, s) for n, s in refs_mod.iter_all_refs(repo).items()
                      if n.startswith("refs/"))
    refs: dict[str, str] = {}
    for name, sha in refs_mod.read_packed_refs(repo).items():
        if name.startswith("refs/"):
            refs[name] = sha
    root = repo.gitdir / "refs"
    if root.exists():
        for f in sorted(root.rglob("*")):
            if f.is_file():
                rel = str(f.relative_to(repo.gitdir)).replace(os.sep, "/")
                s = refs_mod.read_ref(repo, rel)
                if s:
                    refs[rel] = s
    return sorted(refs.items())


def _clamp_abbrev(s: str) -> int:
    """C Git's parse_opt_abbrev_cb: 0 stays 0 (full), else clamp to [4, 40]."""
    try:
        v = int(s)
    except ValueError:
        return 7
    if v == 0:
        return 0
    return min(40, max(4, v))


def _refname_is_safe(ref: str) -> bool:
    """Port of refs.c refname_is_safe: refs/<normalized> or an all-uppercase /
    underscore pseudo-ref (HEAD, MERGE_HEAD, ...)."""
    if ref.startswith("refs/"):
        rest = ref[len("refs/"):]
        if not rest or rest.startswith("/") or rest.endswith("/"):
            return False
        return all(c and c not in (".", "..") for c in rest.split("/"))
    return bool(ref) and all(c.isupper() or c == "_" for c in ref)


def _check_refname_invalid(ref: str) -> bool:
    """True when ref fails check_refname_format(ref, 0) (no one-level refs)."""
    if not ref or ref == "@" or "@{" in ref or ".." in ref or "//" in ref:
        return True
    comps = ref.split("/")
    if len(comps) < 2:
        return True
    bad = set("\\ ~^:?*[")
    for c in comps:
        if not c or c.startswith(".") or c.endswith(".lock") or c.endswith("."):
            return True
        if any(ord(ch) < 0x20 or ord(ch) == 0x7F or ch in bad for ch in c):
            return True
    return False


def _show_ref_exclude_existing(repo: Repository, pattern: Optional[str]) -> int:
    """show-ref --exclude-existing: filter stdin refnames, emitting those that
    are well-formed and absent from the local ref store (port of C Git)."""
    existing = {name for name, _ in _enumerate_refs(repo)}
    plen = len(pattern) if pattern else 0
    for raw in sys.stdin:
        line = raw[:-1] if raw.endswith("\n") else raw
        if len(line) >= 3 and line.endswith("^{}"):
            line = line[:-3]
        ref = line
        for i in range(len(line) - 1, -1, -1):
            if line[i].isspace():
                ref = line[i + 1:]
                break
        if pattern is not None and (len(ref) < plen or ref[:plen] != pattern):
            continue
        if _check_refname_invalid(ref):
            _err(f"warning: ref '{ref}' ignored")
            continue
        if ref not in existing:
            _print(line)
    return 0


def cmd_show_ref(argv: list[str]) -> int:
    # -s/--hash, --abbrev and --exclude-existing take optional arguments only in
    # the attached (=value) form — a following token is never consumed (C Git's
    # PARSE_OPT_OPTARG). Pre-scan them so argparse's nargs="?" can't grab a token.
    abbrev = 0  # 0 == full hash
    hash_only = False
    exclude_enabled = False
    exclude_pattern: Optional[str] = None
    rest: list[str] = []
    for t in argv:
        if t in ("-s", "--hash"):
            hash_only = True
        elif t.startswith("-s") and not t.startswith("--") and len(t) > 2:
            hash_only = True
            abbrev = _clamp_abbrev(t[2:])
        elif t.startswith("--hash="):
            hash_only = True
            abbrev = _clamp_abbrev(t[len("--hash="):])
        elif t == "--abbrev":
            abbrev = 7
        elif t.startswith("--abbrev="):
            abbrev = _clamp_abbrev(t[len("--abbrev="):])
        elif t == "--exclude-existing":
            exclude_enabled = True
        elif t.startswith("--exclude-existing="):
            exclude_enabled = True
            exclude_pattern = t[len("--exclude-existing="):]
        else:
            rest.append(t)

    ap = argparse.ArgumentParser(prog="pygit show-ref", add_help=False)
    ap.add_argument("-h", "--head", dest="head", action="store_true")
    ap.add_argument("--tags", action="store_true")
    ap.add_argument("--heads", dest="branches", action="store_true")
    ap.add_argument("--branches", dest="branches", action="store_true")
    ap.add_argument("--verify", action="store_true")
    ap.add_argument("--exists", action="store_true")
    ap.add_argument("-d", "--dereference", action="store_true")
    ap.add_argument("-q", "--quiet", action="store_true")
    ap.add_argument("patterns", nargs="*")
    args = ap.parse_args(rest)
    repo = _repo()

    def _abbr(s: str) -> str:
        return s if abbrev == 0 else s[:abbrev]

    def show_one(sha: str, name: str) -> None:
        if args.quiet:
            return
        _print(_abbr(sha) if hash_only else f"{_abbr(sha)} {name}")
        if args.dereference:
            try:
                if objs.read_object(repo, sha)[0] == "tag":
                    peeled = refs_mod.rev_parse(repo, name + "^{}")
                    if peeled:
                        _print(f"{_abbr(peeled)} {name}^{{}}" if not hash_only else _abbr(peeled))
            except (KeyError, ValueError):
                pass

    if exclude_enabled:
        return _show_ref_exclude_existing(repo, exclude_pattern)

    if args.verify:
        if not args.patterns:
            _err("fatal: --verify requires a reference")
            return 128
        for ref in args.patterns:
            sha = (refs_mod.read_ref(repo, ref)
                   if (ref.startswith("refs/") or _refname_is_safe(ref)) else None)
            if sha is not None:
                show_one(sha, ref)
            elif not args.quiet:
                _err(f"fatal: '{ref}' - not a valid ref")
                return 128
            else:
                return 1
        return 0

    if args.exists:
        if not args.patterns:
            _err("fatal: --exists requires a reference")
            return 128
        if len(args.patterns) > 1:
            _err("fatal: --exists requires exactly one reference")
            return 128
        ref = args.patterns[0]
        if refs_mod.uses_reftable(repo):
            exists = refs_mod.read_raw_ref_exists(repo, ref)
        else:
            exists = ((repo.gitdir / ref).is_file()
                      or ref in refs_mod.read_packed_refs(repo))
        if exists:
            return 0
        _err("error: reference does not exist")
        return 2

    def matches(refname: str) -> bool:
        if not args.patterns:
            return True
        for m in args.patterns:
            if len(m) > len(refname):
                continue
            if refname[len(refname) - len(m):] != m:
                continue
            if len(m) == len(refname) or refname[len(refname) - len(m) - 1] == "/":
                return True
        return False

    if args.branches or args.tags:
        refs_iter: list[tuple[str, str]] = []
        if args.branches:
            refs_iter += sorted((n, s) for n, s in _enumerate_refs(repo)
                                if n.startswith("refs/heads/"))
        if args.tags:
            refs_iter += sorted((n, s) for n, s in _enumerate_refs(repo)
                                if n.startswith("refs/tags/"))
    else:
        refs_iter = sorted(_enumerate_refs(repo))

    found = 0
    if args.head:
        _, headsha = refs_mod.read_head(repo)
        if headsha:
            show_one(headsha, "HEAD")
            found += 1
    for refname, sha in refs_iter:
        if not matches(refname):
            continue
        show_one(sha, refname)
        found += 1
    return 0 if found else 1


def _unquote_c_style(s: str) -> str:
    """Decode a C-quoted path (`"..."`) as git's unquote_c_style does."""
    if not (len(s) >= 2 and s[0] == '"'):
        return s
    simple = {"a": 7, "b": 8, "t": 9, "n": 10, "v": 11, "f": 12, "r": 13,
              '"': 34, "\\": 92}
    out = bytearray()
    i = 1
    while i < len(s):
        c = s[i]
        if c == '"':
            return out.decode("utf-8", "replace")
        if c == "\\":
            i += 1
            if i >= len(s):
                raise ValueError("invalid quoting")
            n = s[i]
            if n in simple:
                out.append(simple[n]); i += 1
            elif n in "01234567":
                val = j = 0
                while j < 3 and i + j < len(s) and s[i + j] in "01234567":
                    val = val * 8 + int(s[i + j]); j += 1
                out.append(val & 0xFF); i += j
            else:
                raise ValueError("invalid quoting")
        else:
            out.append(ord(c)); i += 1
    raise ValueError("invalid quoting")


def cmd_mktree(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit mktree", add_help=False)
    ap.add_argument("-z", dest="nul", action="store_true")
    ap.add_argument("--missing", dest="allow_missing", action="store_true")
    ap.add_argument("--batch", dest="batch", action="store_true")
    args = ap.parse_args(argv)
    repo = _repo()

    def parse_line(line: str, entries: list) -> Optional[str]:
        # Non-recursive ls-tree format: "mode SP type SP sha TAB name".
        mode_s, sp, rest = line.partition(" ")
        if not sp:
            return f"input format error: {line}"
        try:
            mode = int(mode_s, 8)
        except ValueError:
            return f"input format error: {line}"
        type_s, sp2, rest2 = rest.partition(" ")
        sha, tab, name = rest2.partition("\t")
        if not sp2 or not tab:
            return f"input format error: {line}"
        if len(sha) != repo.hex_len or any(c not in "0123456789abcdefABCDEF" for c in sha):
            return f"input format error: {line}"
        sha = sha.lower()
        if not args.nul and name.startswith('"'):
            try:
                name = _unquote_c_style(name)
            except ValueError:
                return "invalid quoting"
        if type_s not in ("blob", "tree", "commit", "tag"):
            return f'invalid object type "{type_s}"'
        fmt = mode & 0o170000
        mode_type = "tree" if fmt == 0o040000 else ("commit" if mode == 0o160000 else "blob")
        if mode_type != type_s:
            return (f"entry '{name}' object type ({type_s}) doesn't match "
                    f"mode type ({mode_type})")
        # Submodule (gitlink) commits are normally absent, so treat as missing-ok.
        allow_missing = args.allow_missing or mode == 0o160000
        try:
            actual_type = objs.read_object(repo, sha)[0]
        except (KeyError, ValueError, FileNotFoundError):
            actual_type = None
        if actual_type is None:
            if not allow_missing:
                return f"entry '{name}' object {sha} is unavailable"
        elif actual_type != mode_type:
            return (f"entry '{name}' object {sha} is a {actual_type} "
                    f"but specified type was ({mode_type})")
        entries.append(objs.TreeEntry(format(mode, "o"), name, sha))
        return None

    sep = "\0" if args.nul else "\n"
    parts = sys.stdin.buffer.read().decode("utf-8", "replace").split(sep)
    if parts and parts[-1] == "":
        parts.pop()  # trailing terminator is EOF, not an empty line

    out: list[str] = []
    entries: list = []
    idx, n = 0, len(parts)
    while True:
        hit_eof = True
        while idx < n:
            line = parts[idx]
            idx += 1
            if line == "":
                if args.batch:
                    hit_eof = False
                    break
                _err("fatal: input format error: (blank line only valid in batch mode)")
                return 128
            err = parse_line(line, entries)
            if err is not None:
                _err(f"fatal: {err}")
                return 128
        # In batch mode a trailing newline after the last entry yields no final
        # (empty) tree; otherwise write the accumulated entries.
        if not (args.batch and hit_eof and not entries):
            out.append(objs.write_object(repo, "tree", objs.encode_tree(entries)))
        entries = []
        if hit_eof:
            break
    for o in out:
        _print(o)
    return 0


def _unmerge_index_entry(idx, path: str, rec: dict) -> None:
    """Replace the stage-0 entry for *path* (if any) with the conflicted stage
    1/2/3 entries from a resolve-undo record. Mirrors C git's
    unmerge_index_entry(): an already-unmerged path is left untouched."""
    from .index import IndexEntry
    stages = {e.stage for e in idx.entries if e.path == path}
    if stages and stages != {0}:
        # already unmerged — nothing to do
        return
    idx.remove(path, stage=0)
    for stage in (1, 2, 3):
        mode, sha = rec.get(stage, (0, ""))
        if not mode:
            continue
        e = IndexEntry(mode=mode, sha=sha, path=path)
        e.stage = stage
        idx.upsert(e)


def _update_index_refresh(repo, idx, really: bool, quiet: bool) -> bool:
    """Port of refresh_index() for update-index --refresh/--really-refresh.

    For each stage-0 entry: stat the worktree file; if the stored stat matches,
    the entry is up to date. If the stat differs, re-hash the content -- when the
    content still matches, silently refresh the entry's stat info (so a later
    refresh is a no-op); when it differs (or the file is missing), print
    "<path>: needs update" (unless quiet) and flag an error. Unmerged (stage!=0)
    entries print "<path>: needs merge". Returns True if any error was reported
    (the caller maps that to exit code 1)."""
    from .index import stat_to_entry, write_index
    import stat as _stat
    has_errors = False
    changed = False
    # Group entries by path to detect unmerged (multi-stage) entries.
    stages: dict[str, list] = {}
    order: list[str] = []
    for e in idx.entries:
        if e.path not in stages:
            order.append(e.path)
        stages.setdefault(e.path, []).append(e)
    for name in order:
        ents = stages[name]
        # Unmerged path: any non-zero stage entry.
        if any(e.stage != 0 for e in ents):
            if not quiet:
                _print(f"{name}: needs merge")
            has_errors = True
            continue
        e = ents[0]
        # skip-worktree / assume-valid entries are trusted unless --really.
        if not really and (e.skip_worktree or (e.flags & 0x8000)):
            continue
        full = repo.path / name
        try:
            st = os.lstat(full)
        except OSError:
            # deleted from the worktree. quiet suppresses both the message and
            # the error flag (refresh_index: "if (quiet) continue;" runs before
            # has_errors = 1).
            if quiet:
                continue
            _print(f"{name}: needs update")
            has_errors = True
            continue
        fmt = e.mode & 0o170000
        if fmt == 0o120000:
            data = workdir._blob_data(full)
        elif _stat.S_ISDIR(st.st_mode):
            # gitlink / submodule directory; leave unchanged.
            continue
        else:
            data = workdir._blob_data(full)
        fresh = stat_to_entry(name, st, e.sha, e.mode)
        stat_same = (
            (e.mtime_s & 0xFFFFFFFF) == (fresh.mtime_s & 0xFFFFFFFF)
            and (e.mtime_n & 0xFFFFFFFF) == (fresh.mtime_n & 0xFFFFFFFF)
            and (e.ctime_s & 0xFFFFFFFF) == (fresh.ctime_s & 0xFFFFFFFF)
            and (e.ctime_n & 0xFFFFFFFF) == (fresh.ctime_n & 0xFFFFFFFF)
            and (e.ino & 0xFFFFFFFF) == (fresh.ino & 0xFFFFFFFF)
            and (e.dev & 0xFFFFFFFF) == (fresh.dev & 0xFFFFFFFF)
            and (e.uid & 0xFFFFFFFF) == (fresh.uid & 0xFFFFFFFF)
            and (e.gid & 0xFFFFFFFF) == (fresh.gid & 0xFFFFFFFF)
            and (e.size & 0xFFFFFFFF) == (fresh.size & 0xFFFFFFFF)
            and (e.mode & 0o100) == (st.st_mode & 0o100)
        )
        if stat_same and not really:
            continue  # ie_match_stat: unchanged, in-core CE_UPTODATE only
        # Stat differs (or --really forces a content check): re-hash and compare.
        new_sha = objs.hash_bytes("blob", data, repo)[0]
        if new_sha == e.sha:
            # Only stat info changed: refresh the entry (do not report).
            fresh.flags = e.flags
            fresh.extended_flags = e.extended_flags
            idx.upsert(fresh)
            changed = True
            continue
        # Content differs. quiet suppresses both the message and the error flag.
        if quiet:
            continue
        _print(f"{name}: needs update")
        has_errors = True
    if changed:
        write_index(repo, idx)
    return has_errors


def cmd_update_index(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit update-index", add_help=False)
    ap.add_argument("--add", action="store_true")
    ap.add_argument("--replace", action="store_true")
    ap.add_argument("--remove", action="store_true")
    ap.add_argument("--force-remove", dest="force_remove", action="store_true")
    ap.add_argument("--verbose", action="store_true")
    ap.add_argument("--refresh", action="store_true")
    ap.add_argument("--really-refresh", dest="really_refresh", action="store_true")
    ap.add_argument("-q", dest="quiet", action="store_true")
    ap.add_argument("--chmod", choices=["+x", "-x"], default=None)
    ap.add_argument("--cacheinfo", nargs=3, metavar=("MODE", "SHA", "PATH"))
    ap.add_argument("--assume-unchanged", dest="assume_unchanged", action="store_true")
    ap.add_argument("--no-assume-unchanged", dest="no_assume_unchanged", action="store_true")
    ap.add_argument("--skip-worktree", dest="skip_worktree", action="store_true")
    ap.add_argument("--no-skip-worktree", dest="no_skip_worktree", action="store_true")
    ap.add_argument("--stdin", action="store_true")
    ap.add_argument("-z", dest="nul", action="store_true")
    ap.add_argument("--index-info", dest="index_info", action="store_true")
    ap.add_argument("--show-index-version", dest="show_index_version", action="store_true")
    ap.add_argument("-g", "--again", dest="again", action="store_true")
    ap.add_argument("--unresolve", dest="unresolve", action="store_true")
    ap.add_argument("--clear-resolve-undo", dest="clear_resolve_undo", action="store_true")
    ap.add_argument("--fsmonitor-valid", dest="fsmonitor_valid", action="store_true")
    ap.add_argument("--no-fsmonitor-valid", dest="no_fsmonitor_valid", action="store_true")
    # Refresh-flag no-ops (builtin/update-index.c OPT_BIT into refresh_args.flags
    # / OPT_SET_INT info_only / OPT_BOOL ignore_skip_worktree_entries): accepted
    # and idempotent in pygit (they only tune --refresh diagnostics).
    ap.add_argument("--unmerged", dest="unmerged", action="store_true")
    ap.add_argument("--ignore-missing", dest="ignore_missing", action="store_true")
    ap.add_argument("--ignore-submodules", dest="ignore_submodules", action="store_true")
    ap.add_argument("--info-only", dest="info_only", action="store_true")
    ap.add_argument("--ignore-skip-worktree-entries", dest="ignore_skip_worktree_entries",
                    action="store_true")
    # Index-extension toggles (builtin/update-index.c). pygit never writes the
    # split-index / untracked-cache extensions, so these are accepted and only
    # emit the matching verbose report (and --test-untracked-cache's stderr).
    ap.add_argument("--split-index", dest="split_index", action="store_true", default=None)
    ap.add_argument("--no-split-index", dest="split_index", action="store_false")
    ap.add_argument("--untracked-cache", dest="untracked_cache", action="store_const", const="enable")
    ap.add_argument("--no-untracked-cache", dest="untracked_cache", action="store_const", const="disable")
    ap.add_argument("--test-untracked-cache", dest="untracked_cache", action="store_const", const="test")
    ap.add_argument("--force-untracked-cache", dest="untracked_cache", action="store_const", const="force")
    ap.add_argument("--force-write-index", dest="force_write_index", action="store_true")
    ap.add_argument("--index-version", dest="index_version", type=int, default=None)
    # OPT_BOOL fsmonitor (distinct from --fsmonitor-valid): warns when
    # core.fsmonitor is unset and (verbose) reports "fsmonitor enabled".
    ap.add_argument("--fsmonitor", dest="fsmonitor", action="store_true", default=None)
    ap.add_argument("--no-fsmonitor", dest="fsmonitor", action="store_false")
    ap.add_argument("paths", nargs="*")
    # --cacheinfo accepts a new-style single "<mode>,<oid>,<path>" argument as
    # well as the three-token form (parse_new_style_cacheinfo). Expand the comma
    # form to three tokens so the nargs=3 option matches either spelling.
    norm_argv: list[str] = []
    _i = 0
    while _i < len(argv):
        tok = argv[_i]
        if tok == "--cacheinfo" and _i + 1 < len(argv):
            nxt = argv[_i + 1]
            parts = nxt.split(",")
            if len(parts) == 3 and parts[0] and parts[1] and parts[2]:
                norm_argv.append(tok)
                norm_argv.extend(parts)
                _i += 2
                continue
        norm_argv.append(tok)
        _i += 1
    argv = norm_argv
    # builtin/update-index.c processes options left-to-right; --refresh and
    # --really-refresh are callbacks that run *during* option parsing, so the
    # REFRESH_QUIET (-q) flag only applies when -q precedes them on the command
    # line. Capture that ordering before argparse discards it.
    refresh_quiet = False
    for tok in argv:
        if tok == "-q":
            refresh_quiet = True
        elif tok in ("--refresh", "--really-refresh"):
            break
    args = ap.parse_args(argv)
    repo = _repo()
    from .index import IndexEntry, read_index, write_index
    idx = read_index(repo)
    if args.show_index_version:
        _print(str(getattr(idx, "version", 2) or 2))
        return 0
    # --index-version <n> (builtin/update-index.c): range-validate here (a die
    # that precedes stdin/path processing); the report + version-set are deferred
    # to the end so per-path "add" reports print first (matching C's ordering).
    index_version_changed = False
    if args.index_version is not None:
        if args.index_version < 2 or args.index_version > 4:
            _err(f"fatal: index-version {args.index_version} not in range: 2..4")
            return 128
    # --index-info: read `mode SP sha [SP stage] TAB path` records from stdin.
    if args.index_info:
        data = sys.stdin.buffer.read().decode("utf-8")
        sep = "\0" if args.nul else "\n"
        for rec in data.split(sep):
            if not rec:
                continue
            meta, _, path = rec.partition("\t")
            fields = meta.split()
            mode_s, sha = fields[0], fields[1]
            stage = int(fields[2]) if len(fields) > 2 else 0
            if int(mode_s, 8) == 0 or sha == repo.null_oid():
                idx.remove(path, stage=stage)
            else:
                e = IndexEntry(mode=int(mode_s, 8), sha=sha, path=path)
                e.stage = stage  # IndexEntry.stage setter packs into flags
                idx.upsert(e)
        write_index(repo, idx)
        return 0
    if args.again:
        # -g/--again: re-run update on stage-0 entries whose index state already
        # differs from HEAD (by mode or object id). Mirrors do_reupdate(): paths
        # in conflict (stage != 0) and paths still identical to HEAD are skipped.
        # A path whose worktree file has vanished is a fatal error and aborts the
        # whole operation before the index is written (C git's update_one die()).
        # The pathspec comes only from the command line — --again never reads
        # stdin (its callback consumes the post-flag argv, not --stdin input).
        _, head_sha = refs_mod.read_head(repo)
        has_head = bool(head_sha)
        head_map: dict[str, tuple[int, str]] = {}
        if has_head:
            try:
                _t, _d = objs.read_object(repo, head_sha)
                if _t == "commit":
                    _tree = objs.parse_commit(_d).tree
                    for hp, hm, hs in workdir.iter_tree_files(repo, _tree):
                        head_map[hp] = (int(hm, 8), hs)
            except KeyError:
                has_head = False
        prefixes = list(args.paths)

        def _again_match(path: str) -> bool:
            if not prefixes:
                return True
            for pre in prefixes:
                if path == pre or path.startswith(pre.rstrip("/") + "/"):
                    return True
            return False

        changed: list[str] = []
        for entry in sorted(idx.entries, key=lambda e: (e.path, e.stage)):
            if entry.stage != 0:
                continue
            if not _again_match(entry.path):
                continue
            old = head_map.get(entry.path) if has_head else None
            if old is not None and old[0] == entry.mode and old[1] == entry.sha:
                continue  # unchanged from HEAD
            changed.append(entry.path)
        # Validate all targets exist in the worktree before mutating the index,
        # matching C git's behaviour of dying (no write) on the first missing one.
        for path in changed:
            full = repo.path / path
            if not full.exists() and not full.is_symlink():
                _err(f"error: {path}: does not exist and --remove not passed")
                _err(f"fatal: Unable to process path {path}")
                return 128
        if changed:
            workdir.add_paths(repo, changed, update_only=True)
        return 0
    # --unresolve <path>...: restore the stage 1/2/3 entries recorded in
    # resolve-undo for each path (consuming the record), mirroring C git's
    # do_unresolve(). Paths come from the command line only (not --stdin).
    if args.unresolve:
        changed = False
        for p in args.paths:
            rec = idx.resolve_undo.get(p)
            if rec is None:
                continue  # no resolve-undo record for the path
            _unmerge_index_entry(idx, p, rec)
            del idx.resolve_undo[p]
            changed = True
        if changed:
            write_index(repo, idx)
        return 0
    # --clear-resolve-undo: drop all resolve-undo records.
    if args.clear_resolve_undo and not args.paths:
        if idx.resolve_undo:
            idx.resolve_undo = {}
            write_index(repo, idx)
        return 0
    # Gather target paths from the command line and/or stdin (-z → NUL).
    paths = list(args.paths)
    if args.stdin:
        sdata = sys.stdin.buffer.read().decode("utf-8")
        sep = "\0" if args.nul else "\n"
        paths += [p for p in sdata.split(sep) if p]
    # --assume-unchanged / --no-assume-unchanged toggle the CE_VALID bit.
    if args.assume_unchanged or args.no_assume_unchanged:
        by_path = idx.by_path()
        for p in paths:
            e = by_path.get(p)
            if e is None:
                _err(f"fatal: Unable to mark file {p}")
                return 128
            if args.assume_unchanged:
                e.flags |= 0x8000
            else:
                e.flags &= ~0x8000
            idx.upsert(e)
        write_index(repo, idx)
        return 0
    if args.skip_worktree or args.no_skip_worktree:
        by_path = idx.by_path()
        for p in paths:
            e = by_path.get(p)
            if e is None:
                _err(f"fatal: Unable to mark file {p}")
                return 128
            e.skip_worktree = bool(args.skip_worktree)
            idx.upsert(e)
        write_index(repo, idx)
        return 0
    # --fsmonitor-valid / --no-fsmonitor-valid toggle the in-core
    # CE_FSMONITOR_VALID bit. That bit is NOT part of CE_EXTENDED_FLAGS, so it
    # is never serialized to the on-disk index; the only externally visible
    # effects are the success/no-op exit and the die() on a path that has no
    # index entry. We still rewrite the index to match git's cache_changed path.
    if args.fsmonitor_valid or args.no_fsmonitor_valid:
        by_path = idx.by_path()
        for p in paths:
            if by_path.get(p) is None:
                _err(f"fatal: Unable to mark file {p}")
                return 128
        write_index(repo, idx)
        return 0
    args.paths = paths
    if args.cacheinfo:
        mode_s, sha, path = args.cacheinfo
        # add_cacheinfo(): without --add (ADD_CACHE_OK_TO_ADD) a brand-new path
        # cannot be introduced -> "cannot add to the index - missing --add
        # option?" then the caller dies "--cacheinfo cannot add <path>".
        existing = idx.by_path().get(path)
        if existing is None and not args.add:
            _err(f"error: {path}: cannot add to the index - missing --add option?")
            _err(f"fatal: git update-index: --cacheinfo cannot add {path}")
            return 128
        idx.upsert(IndexEntry(mode=int(mode_s, 8), sha=sha, path=path))
        # do_write_index() rejects an entry whose object id is null (unless
        # GIT_ALLOW_NULL_SHA1): "cache entry has null sha1: <path>" then the
        # caller dies "Unable to write new index file".
        if int(sha, 16) == 0:
            _err(f"error: cache entry has null sha1: {path}")
            _err("fatal: Unable to write new index file")
            return 128
        write_index(repo, idx)
        return 0
    if args.chmod is not None and not args.paths:
        # --chmod with no path is a no-op success in C (set_executable_bit is
        # only consulted after a path is processed).
        return 0
    if args.refresh or args.really_refresh:
        has_errors = _update_index_refresh(
            repo, idx, args.really_refresh, refresh_quiet,
        )
        return 1 if has_errors else 0
    # Per-path processing, porting builtin/update-index.c update_one(). Defaults:
    # allow_add/allow_remove/allow_replace all start false; --add/--remove/
    # --replace enable them. --force-remove drops the entry unconditionally.
    allow_add = args.add
    allow_remove = args.remove
    by_path = idx.by_path()
    reports: list[str] = []
    changed = False
    # --chmod is applied per path *after* update_one(path); if update_one dies
    # (e.g. a new path without --add) the chmod never runs.
    chmod_exec = None if args.chmod is None else (args.chmod == "+x")

    def _index_path_blob(rel: str):
        full = repo.path / rel
        data = workdir._blob_data(full)
        sha = objs.write_object(repo, "blob", data)
        return sha, workdir._mode_for(full)

    def _chmod_one(rel: str) -> int | None:
        """chmod_path(): the path must be a stage-0 index entry, else die.
        Returns 128 on failure (caller returns it), None on success."""
        nonlocal changed
        entry = by_path.get(rel)
        if entry is None:
            flip = "+" if chmod_exec else "-"
            _err(f"fatal: git update-index: cannot chmod {flip}x '{rel}'")
            return 128
        new_mode = 0o100755 if chmod_exec else 0o100644
        if entry.mode != new_mode:
            entry.mode = new_mode
            idx.upsert(entry)
            changed = True
        flip = "+" if chmod_exec else "-"
        reports.append(f"chmod {flip}x '{rel}'")
        return None

    for p in args.paths:
        rel = workdir._norm(p)
        full = repo.path / rel
        if args.force_remove:
            if rel in by_path:
                idx.remove(rel)
                del by_path[rel]
                changed = True
            reports.append(f"remove '{rel}'")
            if chmod_exec is not None:
                rc = _chmod_one(rel)
                if rc is not None:
                    return rc
            continue
        present = full.exists() or full.is_symlink()
        if not present:
            # process_lstat_error -> remove_one_path
            if allow_remove:
                if rel in by_path:
                    idx.remove(rel)
                    del by_path[rel]
                    changed = True
                if chmod_exec is not None:
                    rc = _chmod_one(rel)
                    if rc is not None:
                        return rc
                continue
            _err(f"error: {rel}: does not exist and --remove not passed")
            _err(f"fatal: Unable to process path {rel}")
            return 128
        if full.is_dir() and not full.is_symlink():
            # process_directory: exact file match -> remove_one_path; a
            # subdirectory match (entries under rel/) -> "add individual files
            # instead"; otherwise "add files inside instead".
            if rel in by_path:
                if allow_remove:
                    idx.remove(rel)
                    del by_path[rel]
                    changed = True
                    if chmod_exec is not None:
                        rc = _chmod_one(rel)
                        if rc is not None:
                            return rc
                    continue
                _err(f"error: {rel}: does not exist and --remove not passed")
                _err(f"fatal: Unable to process path {rel}")
                return 128
            if any(k.startswith(rel + "/") for k in by_path):
                _err(f"error: {rel}: is a directory - add individual files instead")
            else:
                _err(f"error: {rel}: is a directory - add files inside instead")
            _err(f"fatal: Unable to process path {rel}")
            return 128
        # add_one_path: update an existing entry, or add a new one only with --add.
        old = by_path.get(rel)
        if old is not None:
            sha, mode = _index_path_blob(rel)
            if old.sha == sha and old.mode == mode:
                # already up-to-date (ie_match_stat short-circuit)
                reports.append(f"add '{rel}'")
            else:
                from .index import stat_to_entry
                st = full.lstat()
                entry = stat_to_entry(rel, st, sha, mode)
                idx.upsert(entry)
                by_path[rel] = entry
                changed = True
                reports.append(f"add '{rel}'")
            if chmod_exec is not None:
                rc = _chmod_one(rel)
                if rc is not None:
                    return rc
            continue
        if not allow_add:
            _err(f"error: {rel}: cannot add to the index - missing --add option?")
            _err(f"fatal: Unable to process path {rel}")
            return 128
        sha, mode = _index_path_blob(rel)
        from .index import stat_to_entry
        st = full.lstat()
        entry = stat_to_entry(rel, st, sha, mode)
        idx.upsert(entry)
        by_path[rel] = entry
        changed = True
        reports.append(f"add '{rel}'")
        if chmod_exec is not None:
            rc = _chmod_one(rel)
            if rc is not None:
                return rc
    # Per-path "add '<x>'" / "remove '<x>'" reports print first (C: emitted by
    # update_one() during option parsing), THEN the deferred index-version report
    # (C: after parse_options_end), THEN the index-extension reports.
    if args.verbose:
        for line in reports:
            _print(line)
    if args.index_version is not None:
        cur = getattr(idx, "version", 2) or 2
        if args.verbose:
            _print(f"index-version: was {cur}, set to {args.index_version}")
        # pygit's writer emits v2 (or v3 when extended flags are present); it
        # cannot produce v4 path-compression, so only persist a version the
        # writer supports (avoids writing a v2 index that claims to be v4).
        if args.index_version in (2, 3) and cur != args.index_version:
            idx.version = args.index_version
            index_version_changed = True
    if changed or index_version_changed:
        write_index(repo, idx)
    # Index-extension toggles and fsmonitor (builtin/update-index.c, run after
    # per-path processing). pygit does not write the split-index / untracked-cache
    # extensions, so the observable effects are just the verbose reports and the
    # always-on stderr lines.
    if args.untracked_cache == "test":
        # UC_TEST: print the probe line and return supported-state (OK -> rc 0).
        _err(f"Testing mtime in '{os.getcwd()}' ...... OK")
        return 0
    if args.untracked_cache in ("enable", "force"):
        if args.verbose:
            _print(f"Untracked cache enabled for '{repo.path}'")
    elif args.untracked_cache == "disable":
        if args.verbose:
            _print("Untracked cache disabled")
    if args.fsmonitor:
        # core.fsmonitor is unset under the parity env -> always warn.
        _err("warning: core.fsmonitor is unset; set it if you really want to "
             "enable fsmonitor")
        if args.verbose:
            _print("fsmonitor enabled")
    return 0


_CHECK_IGNORE_USAGE = (
    "usage: git check-ignore [<options>] <pathname>...\n"
    "   or: git check-ignore [<options>] --stdin\n"
)


def cmd_check_ignore(argv: list[str]) -> int:
    quiet = 0
    verbose = 0
    stdin_paths = False
    nul_term_line = False
    show_non_matching = False
    no_index = False
    paths: list[str] = []
    i = 0
    n = len(argv)
    while i < n:
        a = argv[i]
        if a == "--":
            i += 1
            while i < n:
                paths.append(argv[i])
                i += 1
            break
        if a in ("-h", "--help"):
            sys.stdout.write(_CHECK_IGNORE_USAGE)
            return 129
        if a in ("-q", "--quiet"):
            quiet = 1
        elif a == "--no-quiet":
            quiet = 0
        elif a in ("-v", "--verbose"):
            verbose = 1
        elif a == "--no-verbose":
            verbose = 0
        elif a == "--stdin":
            stdin_paths = True
        elif a == "--no-stdin":
            stdin_paths = False
        elif a == "-z":
            nul_term_line = True
        elif a in ("-n", "--non-matching"):
            show_non_matching = True
        elif a == "--no-non-matching":
            show_non_matching = False
        elif a == "--no-index":
            no_index = True
        elif a.startswith("-") and a != "-":
            _err(_CHECK_IGNORE_USAGE.rstrip("\n"))
            return 129
        else:
            paths.append(a)
        i += 1

    # Validation (mirrors cmd_check_ignore order).
    if stdin_paths:
        if paths:
            _err("fatal: cannot specify pathnames with --stdin")
            return 128
    else:
        if nul_term_line:
            _err("fatal: -z only makes sense with --stdin")
            return 128
        if not paths:
            _err("fatal: no path specified")
            return 128
    if quiet:
        if len(paths) > 1:
            _err("fatal: --quiet is only valid with a single pathname")
            return 128
        if verbose:
            _err("fatal: cannot have both --quiet and --verbose")
            return 128
    if show_non_matching and not verbose:
        _err("fatal: --non-matching is only valid with --verbose")
        return 128

    repo = _repo()
    from . import ignore as _ig
    ig = _ig.load(repo.path)

    indexed_paths: set[str] = set()
    if not no_index:
        from .index import read_index
        try:
            idx = read_index(repo)
            for e in idx.entries:
                if e.stage == 0 and not e.skip_worktree:
                    indexed_paths.add(e.path)
        except Exception:
            pass

    out = sys.stdout.buffer

    def in_index(match_path: str) -> bool:
        if match_path in indexed_paths:
            return True
        prefix = match_path.rstrip("/") + "/"
        return any(p.startswith(prefix) for p in indexed_paths)

    def emit(pattern, original: str) -> None:
        # output_pattern: pattern text is bang + pattern + slash (rule.raw is the
        # verbatim line, which equals that reconstruction for these forms).
        if not nul_term_line:
            if not verbose:
                out.write(_mt_quote_c_style(original) + b"\n")
            else:
                if pattern is not None:
                    out.write(_mt_quote_c_style(pattern.source)
                              + (":%d:%s\t" % (pattern.lineno, pattern.raw)).encode())
                else:
                    out.write(b"::\t")
                out.write(_mt_quote_c_style(original) + b"\n")
        else:
            if not verbose:
                out.write(original.encode("utf-8", "surrogateescape") + b"\0")
            else:
                if pattern is not None:
                    out.write(pattern.source.encode("utf-8", "surrogateescape") + b"\0"
                              + str(pattern.lineno).encode() + b"\0"
                              + pattern.raw.encode("utf-8", "surrogateescape") + b"\0"
                              + original.encode("utf-8", "surrogateescape") + b"\0")
                else:
                    out.write(b"\0\0\0" + original.encode("utf-8", "surrogateescape") + b"\0")

    def check_one(original: str) -> bool:
        match_path = original.replace(os.sep, "/")
        pattern = None
        if not in_index(match_path):
            is_dir = match_path.endswith("/") or (repo.path / original).is_dir()
            if verbose:
                pattern = ig.last_matching_rule(match_path, is_dir=is_dir)
            else:
                # last_matching_pattern, then null negative patterns.
                pattern = ig.last_matching_rule(match_path, is_dir=is_dir)
                if pattern is not None and pattern.negate:
                    pattern = None
        ignored = pattern is not None
        if not quiet and (pattern is not None or show_non_matching):
            emit(pattern, original)
        return ignored

    num_ignored = 0
    if stdin_paths:
        term = b"\0" if nul_term_line else b"\n"
        data = sys.stdin.buffer.read()
        if data:
            records = data.split(term)
            if records and records[-1] == b"":
                records = records[:-1]
            for rec in records:
                line = rec.decode("utf-8", "surrogateescape")
                if not nul_term_line and line.startswith('"'):
                    line = _unquote_c_style(line)
                if check_one(line):
                    num_ignored += 1
                out.flush()
    else:
        for p in paths:
            if check_one(p):
                num_ignored += 1
        out.flush()
    return 0 if num_ignored else 1


def _register_phase3() -> None:
    _COMMANDS["apply"] = cmd_apply
    _COMMANDS["format-patch"] = cmd_format_patch
    _COMMANDS["am"] = cmd_am
    _COMMANDS["clean"] = cmd_clean
    _COMMANDS["describe"] = cmd_describe
    _COMMANDS["blame"] = cmd_blame
    _COMMANDS["for-each-ref"] = cmd_for_each_ref
    _COMMANDS["shortlog"] = cmd_shortlog
