# Long pack-objects options that take an integer-ish value validated by git.
#   "int"  -> OPT_INTEGER (integer + k/m/g)
#   "uint" -> OPT_MAGNITUDE (non-negative integer + k/m/g)
_PACK_OBJECTS_VALUE_OPTS = {
    "window": "int",
    "depth": "int",
    "threads": "int",
    "window-memory": "uint",
    "max-pack-size": "uint",
    "name-hash-version": "int",
    # string-valued options (no numeric validation): bare form -> "requires a
    # value" + usage rc 129, matching git's parse-options.
    "keep-pack": "str",
    "filter": "str",
    "missing": "str",
}


def cmd_pack_objects(argv: list[str]) -> int:
    # Parse the flags we honor; collect any remaining non-flag tokens as
    # positional <base-name> candidates (git only allows one).  Many rev-list
    # options are accepted for argument parity and imply --revs.
    # git's parse_options prints the usage block to STDOUT for -h (rc 129) when
    # the -h is reached without an earlier error.
    stdout = False
    rev_list_all = False
    use_internal_rev_list = False
    write_bitmap_index = False
    no_write_bitmap_index = False
    non_empty = False
    index_version = None
    positionals: list[str] = []
    i = 0
    n = len(argv)
    while i < n:
        arg = argv[i]
        if arg == "-h":
            sys.stdout.write(_PACK_OBJECTS_USAGE)
            return 129
        if arg == "--stdout":
            stdout = True
        elif arg == "--all":
            rev_list_all = True
            use_internal_rev_list = True
        elif arg == "--revs":
            use_internal_rev_list = True
        elif arg in ("--unpacked", "--reflog", "--indexed-objects",
                     "--branches", "--tags", "--remotes"):
            use_internal_rev_list = True
        elif arg == "--write-bitmap-index":
            write_bitmap_index = True
        elif arg == "--no-write-bitmap-index":
            no_write_bitmap_index = True
        elif arg == "--non-empty":
            non_empty = True
        elif arg == "--no-non-empty":
            non_empty = False
        elif arg in ("-q", "--quiet", "--progress", "--all-progress",
                     "--all-progress-implied", "--no-reuse-delta",
                     "--no-reuse-object", "--delta-base-offset", "--local",
                     "--incremental", "--sparse", "--no-sparse",
                     "--keep-true-parents", "--thin", "--honor-pack-keep",
                     "--include-tag", "--delta-islands"):
            pass
        elif arg == "--index-version" or arg.startswith("--index-version="):
            # OPT_CALLBACK parsing "<version>[,<offset>]"; git dies rc 128 on a
            # bad version.
            if arg == "--index-version":
                i += 1
                if i >= n:
                    _err("error: option `index-version' requires a value")
                    return 129
                val = argv[i]
            else:
                val = arg[len("--index-version="):]
            vpart = val.split(",", 1)[0]
            if not vpart.isdigit() or int(vpart) not in (1, 2):
                _err(f"fatal: bad index version '{val}'")
                return 128
            index_version = int(vpart)
        elif arg.split("=", 1)[0][2:] in _PACK_OBJECTS_VALUE_OPTS and arg.startswith("--"):
            name = arg.split("=", 1)[0][2:]
            kind = _PACK_OBJECTS_VALUE_OPTS[name]
            if "=" in arg:
                val = arg.split("=", 1)[1]
            else:
                i += 1
                if i >= n:
                    # git parse-options prints ONLY the error line (no usage
                    # block) when a value option is missing its argument.
                    _err(f"error: option `{name}' requires a value")
                    return 129
                val = argv[i]
            from . import repack as _repack
            try:
                if kind == "uint":
                    _repack._parse_uint(name, val)
                elif kind == "int":
                    _repack._parse_int(name, val)
                # kind == "str": git accepts any value (filter spec, pack name,
                # missing-action) — no numeric validation here.
            except _repack.UsageError as exc:
                if exc.message:
                    _err(exc.message)
                return 129
        elif arg.startswith(("--cruft-expiration=", "--uri-protocol=",
                             "--unpack-unreachable=")):
            pass
        elif arg in ("--keep-unreachable", "--pack-loose-unreachable",
                     "--cruft", "--use-bitmap-index", "--no-use-bitmap-index",
                     "--shallow", "--exclude-promisor-objects",
                     "--exclude-promisor-objects-best-effort",
                     # --path-walk is OPT_BOOL; --cruft-expiration is
                     # PARSE_OPT_OPTARG so its bare form is accepted (then the
                     # missing object-list falls through to the usage block).
                     "--path-walk", "--cruft-expiration"):
            pass
        elif arg == "--":
            positionals.extend(argv[i + 1:])
            break
        elif arg.startswith("--"):
            _err(f"error: unknown option `{arg[2:]}'")
            sys.stderr.write(_PACK_OBJECTS_USAGE)
            return 129
        elif arg.startswith("-") and arg != "-":
            _err(f"error: unknown switch `{arg[1]}'")
            sys.stderr.write(_PACK_OBJECTS_USAGE)
            return 129
        else:
            positionals.append(arg)
        i += 1

    base = positionals[0] if positionals else None
    extra = len(positionals) > 1
    # git: "if (pack_to_stdout != !base_name || argc)" -> usage error.
    if (stdout != (base is None)) or extra:
        sys.stderr.write(_PACK_OBJECTS_USAGE)
        return 129

    repo = _repo()
    from . import pack as _p
    if use_internal_rev_list:
        if rev_list_all:
            shas = sorted(_reachable(repo))
        else:
            shas = sorted(_reachable(repo))
    else:
        # read_object_list_from_stdin: each line is "<oid>[ <path>]"; a leading
        # '-' marks an edge (preferred-base) object which is excluded.
        shas = []
        for line in sys.stdin.read().splitlines():
            if not line:
                continue
            if line[0] == "-":
                continue
            oid = line[:40]
            shas.append(oid)
    # --non-empty: when the resulting pack would hold no objects, write nothing
    # at all (pack-objects.c: `if (non_empty && !nr_result) goto cleanup`).
    if non_empty and not shas:
        return 0
    if stdout:
        _p.write_pack_stream_to(repo, shas, sys.stdout.buffer.write, collect_entries=False)
        return 0
    try:
        pack_sha, pack_path, entries = _write_pack_files_at(repo, shas, base)
    except FileNotFoundError as exc:
        # git: open() of the dir-prefixed pack fails -> error: + fatal rename.
        bad = exc.filename or ""
        _err(f"error: unable to write file {bad}: No such file or directory")
        _err(f"fatal: unable to rename temporary file to '{bad}'")
        return 128
    if write_bitmap_index and not no_write_bitmap_index:
        _p.write_pack_bitmap(repo, pack_path, entries)
    _print(pack_sha)
    return 0


def _write_pack_files_at(
    repo: Repository,
    shas: list[str],
    base: str,
) -> tuple[str, Path, list[tuple[str, int, int]]]:
    """Write `<base>-<sha>.{pack,idx,rev}` where ``base`` is resolved relative
    to the CURRENT WORKING DIRECTORY (git pack-objects <base-name> semantics),
    not the object store."""
    from . import pack as _p

    base_path = Path(base)
    parent = base_path.parent  # "." for a bare name
    stem = base_path.name
    # git writes the temp pack into the object store, then renames each
    # component to the requested base path (relative to CWD).
    pack_dir = repo.gitdir / "objects" / "pack"
    pack_dir.mkdir(parents=True, exist_ok=True)
    _p.clear_pack_cache(repo)
    tmp = pack_dir / f".tmp-{stem}-{os.getpid()}-{time.time_ns()}.pack"
    try:
        pack_sha, entries = _p.write_pack_stream(repo, shas, tmp)
        idx_bytes = _p.write_idx_v2_from_checksum(
            bytes.fromhex(pack_sha), entries, repo.object_format())
        rev_bytes = _p.write_rev_file_bytes(
            bytes.fromhex(pack_sha), entries, repo.object_format())
        pack_path = parent / f"{stem}-{pack_sha}.pack"
        # Renaming into a missing directory raises FileNotFoundError; surface
        # the *final* pack path name (matching git's error text).
        try:
            os.replace(tmp, pack_path)
        except FileNotFoundError as exc:
            exc.filename = pack_path.as_posix()
            raise
    finally:
        tmp.unlink(missing_ok=True)
    (parent / f"{stem}-{pack_sha}.idx").write_bytes(idx_bytes)
    (parent / f"{stem}-{pack_sha}.rev").write_bytes(rev_bytes)
    return pack_sha, pack_path, entries


_UNPACK_OBJECTS_USAGE = "git unpack-objects [-n] [-q] [-r] [--strict]"


def cmd_unpack_objects(argv: list[str]) -> int:
    # show_usage_if_asked: only when -h / --help-all is the sole argument; this
    # runs before repository discovery (matches git's cmd_main ordering).
    if len(argv) == 1 and argv[0] in ("-h", "--help-all"):
        sys.stdout.write("usage: " + _UNPACK_OBJECTS_USAGE + "\n")
        return 129

    # git discovers the repository (repo_config) before parsing options, so a
    # missing repo dies with rc 128 even for otherwise-invalid arguments.
    repo = _repo()

    dry_run = False
    recover = False
    max_input_size = 0
    # quiet/recover/strict are parsed for argument-acceptance parity; strict's
    # fsck reachability enforcement is intentionally not implemented (DEFER).
    for arg in argv:
        if arg and arg[0] == "-":
            if arg == "-n":
                dry_run = True
                continue
            if arg == "-q":
                continue
            if arg == "-r":
                recover = True
                continue
            if arg == "--strict":
                continue
            if arg.startswith("--strict="):
                continue
            if arg.startswith("--pack_header="):
                continue
            if arg.startswith("--max-input-size="):
                # OPT_MAGNITUDE; git's strtoumax stops at the first non-digit.
                raw = arg[len("--max-input-size="):]
                digits = ""
                for ch in raw:
                    if ch.isdigit():
                        digits += ch
                    else:
                        break
                max_input_size = int(digits) if digits else 0
                continue
            sys.stderr.write("usage: " + _UNPACK_OBJECTS_USAGE + "\n")
            return 129
        # We don't take any non-flag arguments.
        sys.stderr.write("usage: " + _UNPACK_OBJECTS_USAGE + "\n")
        return 129

    from . import pack as _p
    buf = sys.stdin.buffer.read()
    try:
        return _p.unpack_objects_stream(
            repo, buf, dry_run=dry_run, recover=recover,
            max_input_size=max_input_size, write_err=_err)
    except _p.UnpackDie as exc:
        _err("fatal: %s" % exc)
        return 128
    except _p.UnpackExit as exc:
        return exc.code


_INDEX_PACK_USAGE = (
    "usage: git index-pack [-v] [-o <index-file>] [--keep | --keep=<msg>] "
    "[--[no-]rev-index] [--verify] [--strict[=<msg-id>=<severity>...]] "
    "[--fsck-objects[=<msg-id>=<severity>...]] (<pack-file> | --stdin "
    "[--fix-thin] [<pack-file>])\n"
)


def cmd_index_pack(argv: list[str]) -> int:
    # Port of builtin/index-pack.c argument handling. The bare positional form
    # (`index-pack my.pack`) indexes a pack on disk; `--stdin` reads the pack
    # from stdin and installs it under objects/pack.
    if argv and argv[0] == "-h":
        sys.stdout.write(_INDEX_PACK_USAGE)
        return 129

    from_stdin = False
    keep = False
    keep_msg = ""
    verify = False
    fix_thin = False
    verbose = False
    object_format = None
    max_input_size = 0
    output_index = None
    positionals: list[str] = []
    i = 0
    n = len(argv)
    while i < n:
        a = argv[i]
        if a == "--stdin":
            from_stdin = True
        elif a == "--keep":
            keep = True
        elif a.startswith("--keep="):
            keep = True
            keep_msg = a[len("--keep="):]
        elif a == "--verify":
            verify = True
        elif a == "--fix-thin":
            fix_thin = True
        elif a in ("-v", "--verbose"):
            verbose = True
        elif a in ("--rev-index", "--no-rev-index"):
            pass
        elif a in ("--strict", "--fsck-objects") or a.startswith(("--strict=", "--fsck-objects=")):
            pass
        elif a == "-o":
            i += 1
            if i >= n:
                _err("error: option `o' requires a value")
                sys.stderr.write(_INDEX_PACK_USAGE)
                return 129
            output_index = argv[i]
        elif a == "--object-format" or a.startswith("--object-format="):
            if a == "--object-format":
                i += 1
                if i >= n:
                    _err("error: option `object-format' requires a value")
                    sys.stderr.write(_INDEX_PACK_USAGE)
                    return 129
                object_format = argv[i]
            else:
                object_format = a[len("--object-format="):]
        elif a == "--max-input-size" or a.startswith("--max-input-size="):
            if a == "--max-input-size":
                i += 1
                val = argv[i] if i < n else ""
            else:
                val = a[len("--max-input-size="):]
            digits = ""
            for ch in val:
                if ch.isdigit():
                    digits += ch
                else:
                    break
            max_input_size = int(digits) if digits else 0
        elif a == "-h":
            # index-pack's in-loop usage() goes to STDERR (the bare-first -h,
            # handled above, goes to stdout via show_usage_if_asked).
            sys.stderr.write(_INDEX_PACK_USAGE)
            return 129
        elif a == "--":
            positionals.extend(argv[i + 1:])
            break
        elif a.startswith("-") and a != "-":
            _err(f"error: unknown option `{a.lstrip('-')}'")
            sys.stderr.write(_INDEX_PACK_USAGE)
            return 129
        else:
            positionals.append(a)
        i += 1

    # --object-format and --stdin are mutually exclusive (index-pack.c).
    if object_format is not None and from_stdin:
        _err("fatal: options '--object-format' and '--stdin' cannot be used together")
        return 128
    if object_format is not None and object_format not in ("sha1", "sha256"):
        _err(f"fatal: unknown hash algorithm '{object_format}'")
        return 128

    repo = _repo()
    from . import pack as _p

    if verify:
        # Verify an existing pack; a missing pack dies naming the derived .idx.
        pkfile = positionals[0] if positionals else None
        if pkfile is None:
            sys.stderr.write(_INDEX_PACK_USAGE)
            return 129
        path = Path(pkfile)
        if path.suffix == ".pack":
            idx_path = path.with_suffix(".idx")
        elif path.suffix == ".idx":
            idx_path = path
            path = path.with_suffix(".pack")
        else:
            idx_path = path.with_name(path.name + ".idx")
        if not path.exists():
            _err(f"fatal: Cannot open existing pack file '{idx_path.as_posix()}'")
            return 128
        try:
            _p.index_pack_file(repo, path)
        except Exception as exc:
            _err(f"fatal: {exc}")
            return 128
        return 0

    if from_stdin:
        buf = sys.stdin.buffer.read()
        if max_input_size and len(buf) > max_input_size:
            human = _humanise_bytes(max_input_size)
            _err(f"fatal: pack exceeds maximum allowed size ({human})")
            return 128
        import tempfile
        pack_dir = repo.gitdir / "objects" / "pack"
        pack_dir.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile(prefix="tmp_pack_", dir=str(pack_dir),
                                         suffix=".pack", delete=False) as tf:
            tf.write(buf)
            tmp_pack = Path(tf.name)
        try:
            pack_sha, dest_pack, _cnt = _p.install_pack_file(
                repo, tmp_pack, fix_thin=fix_thin)
        except Exception as exc:
            tmp_pack.unlink(missing_ok=True)
            _err(f"fatal: {exc}")
            return 128
        if keep:
            keep_path = dest_pack.with_suffix(".keep")
            keep_path.write_text(keep_msg)
        if verbose:
            _index_pack_progress(repo, dest_pack)
        _print(f"{'keep' if keep else 'pack'}\t{pack_sha}")
        return 0

    # Bare positional form: index a pack already on disk.
    pkfile = positionals[0] if positionals else None
    if pkfile is None:
        sys.stderr.write(_INDEX_PACK_USAGE)
        return 129
    path = Path(pkfile)
    if max_input_size:
        try:
            if path.stat().st_size > max_input_size:
                human = _humanise_bytes(max_input_size)
                _err(f"fatal: pack exceeds maximum allowed size ({human})")
                return 128
        except OSError:
            pass
    try:
        pack_sha, _entries = _p.index_pack_file(repo, path)
    except Exception as exc:
        _err(str(exc))
        return 1
    if verbose:
        _index_pack_progress(repo, path)
    if keep:
        keep_path = path.with_suffix(".keep")
        keep_path.write_text(keep_msg)
        _print(f"keep\t{pack_sha}")
    else:
        _print(pack_sha)
    return 0


def _index_pack_progress(repo: Repository, pack_path: Path) -> None:
    """Emit index-pack's `Receiving objects` (and `Resolving deltas`) meters on
    stderr for -v. Port of the deterministic, non-throughput case (the parity
    harness uses small packs where no throughput rate is shown)."""
    from . import pack as _p
    try:
        data = pack_path.read_bytes()
    except OSError:
        return
    if len(data) < 12 or data[:4] != b"PACK":
        return
    nr_objects = int.from_bytes(data[8:12], "big")
    if not nr_objects:
        return
    # Count deltas by parsing the pack metadata.
    n_deltas = 0
    try:
        _c, _exp, metas, _offs, _rb = _p._parse_pack_metadata(repo, data)
        for m in metas.values():
            if m.base_offset is not None or m.base_sha is not None:
                n_deltas += 1
    except Exception:
        n_deltas = 0
    recv = _GitProgress("Receiving objects", nr_objects)
    for k in range(1, nr_objects + 1):
        recv.update(k)
    recv.stop("done")
    if n_deltas:
        res = _GitProgress("Resolving deltas", n_deltas, sparse=True)
        res.update(0)
        for k in range(1, n_deltas + 1):
            res.update(k)
        res.stop("done")


_VERIFY_PACK_USAGE = (
    "usage: git verify-pack [-v | --verbose] [-s | --stat-only] [--] <pack>.idx...\n"
    "\n"
    "    -v, --[no-]verbose    verbose\n"
    "    -s, --[no-]stat-only  show statistics only\n"
    "    --[no-]object-format <hash>\n"
    "                          specify the hash algorithm to use\n"
    "\n"
)


class _VerifyPackArgs:
    v = False
    stat_only = False
    object_format = None
    packs: list[str] = []


def cmd_verify_pack(argv: list[str]) -> int:
    # Port of builtin/verify-pack.c parse_options.
    args = _VerifyPackArgs()
    args.packs = []
    i = 0
    saw_dashdash = False
    while i < len(argv):
        a = argv[i]
        if saw_dashdash:
            args.packs.append(a)
            i += 1
            continue
        if a == "--":
            saw_dashdash = True
        elif a == "-h":
            sys.stdout.write(_VERIFY_PACK_USAGE)
            return 129
        elif a in ("-v", "--verbose"):
            args.v = True
        elif a == "--no-verbose":
            args.v = False
        elif a in ("-s", "--stat-only"):
            args.stat_only = True
        elif a == "--no-stat-only":
            args.stat_only = False
        elif a == "--object-format" or a.startswith("--object-format="):
            if a == "--object-format":
                i += 1
                if i >= len(argv):
                    _err("error: option `object-format' requires a value")
                    sys.stderr.write(_VERIFY_PACK_USAGE)
                    return 129
                args.object_format = argv[i]
            else:
                args.object_format = a[len("--object-format="):]
        elif a.startswith("--"):
            _err(f"error: unknown option `{a[2:]}'")
            sys.stderr.write(_VERIFY_PACK_USAGE)
            return 129
        elif a.startswith("-") and a != "-":
            _err(f"error: unknown switch `{a[1]}'")
            sys.stderr.write(_VERIFY_PACK_USAGE)
            return 129
        else:
            args.packs.append(a)
        i += 1
    # An explicit --object-format is validated via hash_algo_by_name.
    if args.object_format is not None and args.object_format not in ("sha1", "sha256"):
        _err(f"fatal: unknown hash algorithm '{args.object_format}'")
        return 1
    # No pack argument -> usage (rc 129).
    if not args.packs:
        sys.stderr.write(_VERIFY_PACK_USAGE)
        return 129
    repo = _repo()
    from . import pack as _p
    rc = 0
    for p in args.packs:
        path = Path(p)
        # verify-pack normalises foo/foo.idx -> foo.pack (builtin/verify-pack.c),
        # then index-pack --verify re-derives the .idx for its error messages.
        if path.suffix == ".idx":
            path = path.with_suffix(".pack")
        elif path.suffix != ".pack":
            path = path.with_name(path.name + ".pack")
        idx_path = path.with_suffix(".idx")
        # index-pack opens the pack file first; a missing pack dies with rc 128
        # while naming the derived .idx path (read_idx_option/add_packed_git).
        # verify-pack -v/-s would additionally print "<pack>.idx: bad", but the
        # bare form just propagates index-pack's exit status (1 to the shell).
        if not path.exists():
            _err(f"fatal: Cannot open existing pack file '{idx_path.as_posix()}'")
            rc = 1
            # verify_one_pack prints "<pack>.pack: bad" on error when -v/-s.
            if args.v or args.stat_only:
                _print(f"{path.as_posix()}: bad")
            continue
        pk = _p.Pack(path, repo.object_format())
        try:
            err = _verify_one_pack(repo, pk, args.v, args.stat_only)
            if err:
                rc = 1
        except Exception as e:
            _err(f"verify failed: {e}")
            rc = 1
        finally:
            pk.close()
    return rc


def _verify_one_pack(repo: Repository, pk, verbose: bool, stat_only: bool) -> bool:
    """Replicate index-pack --verify[-stat]'s per-object output for one pack.

    Mirrors builtin/index-pack.c show_pack_info: objects are listed in pack
    (offset) order as `<oid> <type-padded-6> <size> <size-in-pack> <offset>`
    (with ` <chain-depth> <base-oid>` appended for delta objects), followed by
    `non delta: N objects`, then a `chain length = N: M objects` histogram, and
    finally (builtin/verify-pack.c) `<pack>.pack: ok`."""
    from . import pack as _p

    # Map oid -> offset, then order by offset (pack order).
    shas = list(pk.shas)
    off_of = {s: pk.offset_of(s) for s in shas}
    ordered = sorted(shas, key=lambda s: off_of[s])
    offsets_sorted = sorted(off_of[s] for s in shas)
    # End of the object region = pack file size minus the trailing hash; this
    # bounds the in-pack size of the last object.
    pk._load()  # populate the mmap
    pack_end = len(pk._mm) - pk.hash_len  # type: ignore[arg-type]
    # next-offset boundary for each offset (for the in-pack byte count).
    next_off: dict[int, int] = {}
    for i, o in enumerate(offsets_sorted):
        next_off[o] = offsets_sorted[i + 1] if i + 1 < len(offsets_sorted) else pack_end

    err = False
    base_objects = 0
    chain_histogram: dict[int, int] = {}

    def _header_size(sha: str) -> int:
        """The size encoded in the pack object header (index-pack obj->size).

        For a non-delta object this is the inflated size; for a delta it is the
        uncompressed delta-instruction length, which is what verify-pack -v
        prints in the size column for delta objects."""
        obj_type, size, _pos = _p._read_var_size(pk._mm, off_of[sha])  # type: ignore[arg-type]
        return size

    def _chain_depth_and_base(sha: str):
        """For a delta object return (depth, base_oid); for a base, (0, None)."""
        off = off_of[sha]
        depth = 0
        cur_off = off
        base_oid = None
        seen_offs: set[int] = set()
        while True:
            data = pk._mm  # type: ignore[assignment]
            obj_type, _size, pos = _p._read_var_size(data, cur_off)
            if obj_type == _p.OBJ_OFS_DELTA:
                neg, _pos = _p._read_offset(data, pos)
                cur_off = cur_off - neg
                depth += 1
                if depth == 1:
                    base_oid = _off_to_oid.get(cur_off)
            elif obj_type == _p.OBJ_REF_DELTA:
                b = data[pos:pos + pk.hash_len].hex()
                depth += 1
                if depth == 1:
                    base_oid = b
                # follow ref-delta base within this pack if present
                nb_off = off_of.get(b)
                if nb_off is None or nb_off in seen_offs:
                    break
                seen_offs.add(nb_off)
                cur_off = nb_off
                continue
            else:
                break
            if cur_off in seen_offs:
                break
            seen_offs.add(cur_off)
        return depth, base_oid

    _off_to_oid = {off_of[s]: s for s in shas}

    lines: list[str] = []
    for sha in ordered:
        t, data = pk.get(sha)  # type: ignore[misc]
        actual, _ = objs.hash_bytes(t, data, repo)
        if actual != sha:
            _err(f"error: bad object {sha}")
            err = True
        off = off_of[sha]
        in_pack = next_off[off] - off
        depth, base_oid = _chain_depth_and_base(sha)
        if depth:
            chain_histogram[depth] = chain_histogram.get(depth, 0) + 1
        else:
            base_objects += 1
        if verbose and not stat_only:
            line = f"{sha} {t:<6} {_header_size(sha)} {in_pack} {off}"
            if depth:
                line += f" {depth} {base_oid}"
            lines.append(line)
    if verbose and not stat_only:
        for line in lines:
            _print(line)
    if verbose or stat_only:
        if base_objects:
            noun = "object" if base_objects == 1 else "objects"
            _print(f"non delta: {base_objects} {noun}")
        for depth in sorted(chain_histogram):
            cnt = chain_histogram[depth]
            noun = "object" if cnt == 1 else "objects"
            _print(f"chain length = {depth}: {cnt} {noun}")
        if not stat_only:
            _print(f"{pk.pack_path}: {'bad' if err else 'ok'}")
    return err


def _loose_disk_bytes(repo: Repository) -> int:
    """Loose-object disk usage in bytes, matching C Git's on_disk_bytes (the
    du-style ``st_blocks * 512`` accounting used by count-objects)."""
    total_blocks = 0
    objects = repo.gitdir / "objects"
    if objects.exists():
        for sub in objects.iterdir():
            if len(sub.name) == 2 and sub.is_dir():
                for obj in sub.iterdir():
                    try:
                        total_blocks += obj.stat().st_blocks
                    except (OSError, AttributeError):
                        pass
    return total_blocks * 512


def _loose_disk_kib(repo: Repository) -> int:
    """Loose-object disk usage in KiB, matching C Git's du-style accounting."""
    return _loose_disk_bytes(repo) // 1024


def _humanise_bytes(n: int) -> str:
    """Port of git's strbuf_humanise_bytes: bytes -> '<N> bytes' / 'X.XX KiB' /
    'MiB' / 'GiB' / 'TiB'."""
    if n < 1024:
        return f"{n} bytes"
    units = ["KiB", "MiB", "GiB", "TiB"]
    val = float(n)
    for u in units:
        val /= 1024.0
        if val < 1024.0 or u == units[-1]:
            return f"{val:.2f} {u}"
    return f"{val:.2f} TiB"


_COUNT_OBJECTS_USAGE = (
    "usage: git count-objects [-v] [-H | --human-readable]\n"
    "\n"
    "    -v, --[no-]verbose    be verbose\n"
    "    -H, --[no-]human-readable\n"
    "                          print sizes in human readable format\n"
    "\n"
)


class _CountArgs:
    v = False
    human = False


def cmd_count_objects(argv: list[str]) -> int:
    # Port of builtin/count-objects.c parse_options (verbose + human-readable).
    args = _CountArgs()
    i = 0
    saw_dashdash = False
    extra = False
    while i < len(argv):
        a = argv[i]
        if saw_dashdash:
            extra = True
            i += 1
            continue
        if a == "--":
            saw_dashdash = True
        elif a == "-h":
            sys.stdout.write(_COUNT_OBJECTS_USAGE)
            return 129
        elif a in ("-v", "--verbose"):
            args.v = True
        elif a == "--no-verbose":
            args.v = False
        elif a in ("-H", "--human-readable"):
            args.human = True
        elif a == "--no-human-readable":
            args.human = False
        elif a.startswith("--"):
            _err(f"error: unknown option `{a[2:]}'")
            sys.stderr.write(_COUNT_OBJECTS_USAGE)
            return 129
        elif a.startswith("-") and a != "-":
            _err(f"error: unknown switch `{a[1]}'")
            sys.stderr.write(_COUNT_OBJECTS_USAGE)
            return 129
        else:
            extra = True
        i += 1
    # count-objects takes no positional arguments; any leftover -> usage (rc 129).
    if extra:
        sys.stderr.write(_COUNT_OBJECTS_USAGE)
        return 129
    repo = _repo()
    loose_count, _bytes = _loose_count_and_size(repo)
    loose_size = _loose_disk_bytes(repo)
    if args.human and not args.v:
        _print(f"{loose_count} objects, {_humanise_bytes(loose_size)}")
        return 0
    if args.v:
        from . import pack as _p
        packed_set: set = set()
        midx = _p.read_midx(repo)
        if midx is not None:
            pack_count = len(midx.pack_names)
            pack_objs = len(midx.shas)
            packed_set.update(midx.shas)
        else:
            pack_count = 0
            pack_objs = 0
            for pk in _p._iter_packs(repo):
                pack_count += 1
                pack_objs += len(pk.shas)
                packed_set.update(pk.shas)
        # C count-objects (-v) sums p->pack_size + p->index_size for each local
        # pack; the .rev/.bitmap files are not counted.
        pack_dir = repo.gitdir / "objects" / "pack"
        size_pack = 0
        if pack_dir.is_dir():
            for pk in pack_dir.glob("*.pack"):
                size_pack += pk.stat().st_size
                idxp = pk.with_suffix(".idx")
                if idxp.exists():
                    size_pack += idxp.stat().st_size
        # prune-packable: loose objects that are ALSO present in a pack (what
        # `git prune-packed` would remove), per builtin/count-objects.c.
        prune_packable = 0
        objects_root = repo.gitdir / "objects"
        if objects_root.is_dir() and packed_set:
            for d in objects_root.iterdir():
                if len(d.name) == 2 and all(c in "0123456789abcdef" for c in d.name) and d.is_dir():
                    for f in d.iterdir():
                        oid = d.name + f.name
                        if len(oid) == repo.hex_len and f.is_file() and oid in packed_set:
                            prune_packable += 1
        # In verbose mode the non-human size fields are raw bytes / 1024 (floor);
        # -H humanises the raw byte counts instead (builtin/count-objects.c).
        if args.human:
            size_str = _humanise_bytes(loose_size)
            size_pack_str = _humanise_bytes(size_pack)
            size_garbage_str = _humanise_bytes(0)
        else:
            size_str = str(loose_size // 1024)
            size_pack_str = str(size_pack // 1024)
            size_garbage_str = "0"
        _print(f"count: {loose_count}")
        _print(f"size: {size_str}")
        _print(f"in-pack: {pack_objs}")
        _print(f"packs: {pack_count}")
        _print(f"size-pack: {size_pack_str}")
        _print(f"prune-packable: {prune_packable}")
        _print("garbage: 0")
        _print(f"size-garbage: {size_garbage_str}")
    else:
        _print(f"{loose_count} objects, {loose_size // 1024} kilobytes")
    return 0


def cmd_repack(argv: list[str]) -> int:
    from . import repack as _repack

    opts = _repack.Options()
    try:
        _repack.parse_options(argv, opts)
    except _repack.HelpRequested:
        # git's parse_options() prints usage to stdout for -h with rc 129.
        sys.stdout.write(_repack._USAGE)
        return 129
    except _repack.UsageError as exc:
        if exc.message:
            _err(exc.message)
        if exc.show_usage:
            sys.stderr.write(_repack._USAGE)
        return 129

    repo = _repo()
    try:
        return _repack.run(repo, opts, _print, _err)
    except _repack.FatalError as exc:
        _err(f"fatal: {exc.message}")
        return 128


_TIME_MAX = (1 << 63) - 1

_PRUNE_USAGE = (
    "usage: git prune [-n] [-v] [--progress] [--expire <time>] [--] [<head>...]\n"
    "\n"
    "    -n, --[no-]dry-run    do not remove, show only\n"
    "    -v, --[no-]verbose    report pruned objects\n"
    "    --[no-]progress       show progress\n"
    "    --[no-]expire <expiry-date>\n"
    "                          expire objects older than <time>\n"
    "    --[no-]exclude-promisor-objects\n"
    "                          limit traversal to objects outside promisor packfiles\n"
    "\n"
)


def _parse_expiry_date(value: str) -> int:
    """Parse a --expire <time> argument into a unix timestamp.

    Mirrors git's OPT_EXPIRY_DATE / parse_expiry_date for the deterministic
    cases. Returns the timestamp; raises ValueError for malformed input so the
    caller can emit git's "malformed expiration date" fatal.
    """
    import calendar
    import datetime as _dt

    v = value.strip()
    if v == "":
        raise ValueError(value)
    low = v.lower()
    if low == "never":
        return 0
    if low in ("now", "all"):
        return int(time.time())
    # @<epoch> or bare integer epoch.
    epoch = v[1:] if v.startswith("@") else v
    if epoch and (epoch.lstrip("+-")).isdigit():
        try:
            return int(epoch)
        except ValueError:
            raise ValueError(value)
    # Absolute ISO-ish dates (interpreted in UTC under TZ=UTC parity env).
    for fmt in (
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%d",
        "%Y/%m/%d %H:%M:%S",
        "%Y/%m/%d",
    ):
        try:
            dt = _dt.datetime.strptime(v, fmt)
        except ValueError:
            continue
        return calendar.timegm(dt.timetuple())
    raise ValueError(value)


def cmd_prune(argv: list[str]) -> int:
    # parse_options handles -h when reached, printing usage to STDOUT (rc 129).
    show_only = False
    verbose = False
    expire = _TIME_MAX
    heads: list[str] = []
    i = 0
    saw_dashdash = False
    while i < len(argv):
        a = argv[i]
        if saw_dashdash:
            heads.append(a)
            i += 1
            continue
        if a == "--":
            saw_dashdash = True
        elif a == "-h":
            sys.stdout.write(_PRUNE_USAGE)
            return 129
        elif a in ("-n", "--dry-run"):
            show_only = True
        elif a == "--no-dry-run":
            show_only = False
        elif a in ("-v", "--verbose"):
            verbose = True
        elif a == "--no-verbose":
            verbose = False
        elif a in ("--progress", "--no-progress"):
            # Connectivity progress is a delayed meter on stderr; under the
            # parity env (never a tty) it produces no output either way.
            pass
        elif a == "--expire" or a.startswith("--expire="):
            if a.startswith("--expire="):
                val = a[len("--expire="):]
            else:
                i += 1
                if i >= len(argv):
                    _err("error: option `expire' requires a value")
                    return 129
                val = argv[i]
            try:
                expire = _parse_expiry_date(val)
            except ValueError:
                _err(f"fatal: malformed expiration date '{val}'")
                return 128
        elif a == "--no-expire":
            expire = 0
        elif a in ("--exclude-promisor-objects", "--no-exclude-promisor-objects"):
            pass
        elif a.startswith("--"):
            _err(f"error: unknown option `{a[2:]}'")
            sys.stderr.write(_PRUNE_USAGE)
            return 129
        elif a.startswith("-") and a != "-":
            _err(f"error: unknown switch `{a[1]}'")
            sys.stderr.write(_PRUNE_USAGE)
            return 129
        else:
            heads.append(a)
        i += 1

    repo = _repo()

    extra_roots: list[str] = []
    for name in heads:
        try:
            sha = refs_mod.rev_parse(repo, name)
        except (OSError, ValueError):
            sha = None
        if not sha:
            _err(f"fatal: unrecognized argument: {name}")
            return 128
        extra_roots.append(sha)

    reach = _reachable(repo, extra_roots) if extra_roots else _reachable(repo)
    objects_dir = repo.gitdir / "objects"
    for sha in _iter_loose_shas(repo):
        if sha in reach:
            continue
        p = objects_dir / sha[:2] / sha[2:]
        try:
            # git compares st_mtime (whole seconds) against the expiry.
            mtime = int(p.stat().st_mtime)
        except OSError:
            continue
        if mtime > expire:
            continue
        if show_only or verbose:
            import zlib as _zlib
            from . import objects as _o

            try:
                otype, _ = _o.read_object(repo, sha)
            except (OSError, KeyError, ValueError, _zlib.error):
                otype = "unknown"
            _print(f"{sha} {otype}")
        if not show_only:
            p.unlink(missing_ok=True)
    return 0


def _parse_mail_headers(text: str) -> tuple[dict[str, str], str]:
    headers: dict[str, str] = {}
    lines = text.splitlines()
    i = 0
    last = None
    while i < len(lines):
        line = lines[i]
        if line == "":
            i += 1
            break
        if line[:1] in (" ", "\t") and last:
            headers[last] += " " + line.strip()
        else:
            k, _, v = line.partition(":")
            headers[k.strip()] = v.strip()
            last = k.strip()
        i += 1
    body = "\n".join(lines[i:])
    return headers, body


_MAILSPLIT_USAGE = (
    "git mailsplit [-d<prec>] [-f<n>] [-b] [--keep-cr] "
    "-o<directory> [(<mbox>|<Maildir>)...]")


def cmd_mailsplit(argv: list[str]) -> int:
    """Port of builtin/mailsplit.c: split mbox(es)/Maildir(s) into numbered
    files, printing the count of messages written."""
    from . import am as _am
    nr = 0
    nr_prec = 4
    allow_bare = False
    out_dir: Optional[str] = None
    keep_cr = False
    mboxrd = False
    files: list[str] = []
    i = 0
    saw_dd = False
    while i < len(argv):
        arg = argv[i]
        if saw_dd or not arg.startswith("-") or arg == "-":
            files.append(arg)
            i += 1
            continue
        if arg == "-h" or arg == "--help":
            _print("usage: " + _MAILSPLIT_USAGE)
            return 129
        if arg[1] == "d":
            try:
                nr_prec = int(arg[2:])
            except ValueError:
                nr_prec = 0
            if nr_prec < 3 or 10 <= nr_prec:
                _err("usage: " + _MAILSPLIT_USAGE)
                return 129
        elif arg[1] == "f":
            try:
                nr = int(arg[2:])
            except ValueError:
                nr = 0
        elif arg[1] == "b" and len(arg) == 2:
            allow_bare = True
        elif arg == "--keep-cr":
            keep_cr = True
        elif arg[1] == "o" and len(arg) > 2:
            out_dir = arg[2:]
        elif arg == "--mboxrd":
            mboxrd = True
        elif arg == "--":
            saw_dd = True
        else:
            _err(f"fatal: unknown option: {arg}")
            return 128
        i += 1

    stdin_only = ["-"]
    if out_dir is None:
        rest = files
        if len(rest) == 1:
            out_dir = rest[0]
            files = stdin_only
        elif len(rest) == 2:
            stdin_only[0] = rest[0]
            out_dir = rest[1]
            files = stdin_only
        else:
            _err("usage: " + _MAILSPLIT_USAGE)
            return 129
    else:
        if not files:
            files = stdin_only

    out = Path(out_dir)
    # git does NOT create the output directory; it opens each <dir>/NNNN with
    # O_CREAT|O_EXCL and dies "unable to create '<path>': <strerror>" if the
    # directory is missing.  Mirror that instead of auto-creating the dir.
    num = 0
    for arg in files:
        is_stdin = (arg == "-")
        try:
            if is_stdin:
                data = _stdin_bytes()
                ns, err = _am.split_mbox(data, out, allow_bare, nr_prec, nr, keep_cr,
                                         mboxrd, True)
            elif Path(arg).is_dir():
                ns, err = _am.split_maildir(Path(arg), out, nr_prec, nr, keep_cr, mboxrd)
            else:
                try:
                    data = Path(arg).read_bytes()
                except OSError:
                    _err(f"error: cannot stat {arg}: No such file or directory")
                    return 1
                ns, err = _am.split_mbox(data, out, allow_bare, nr_prec, nr, keep_cr,
                                         mboxrd, False)
        except OSError as exc:
            import os as _os
            _err(f"fatal: unable to create '{exc.filename}': "
                 f"{_os.strerror(exc.errno)}")
            return 128
        if err == "empty":
            _err(f"error: empty mbox: '{arg}'")
            return 1
        if err == "corrupt":
            # builtin/mailsplit.c split_one(): a bare (non-"From ") first line
            # without -b prints exactly "corrupt mailbox" and exit(1).
            _err("corrupt mailbox")
            return 1
        if err or ns < 0:
            _err(f"error: cannot split patches from {arg}")
            return 1
        num += (ns - nr)
        nr = ns
    _print(str(num))
    return 0


_MAILINFO_USAGE = (
    "usage: git mailinfo [<options>] <msg> <patch> < mail >info\n"
    "\n"
    "    -k                    keep subject\n"
    "    -b                    keep non patch brackets in subject\n"
    "    -m, --[no-]message-id copy Message-ID to the end of commit message\n"
    "    -u                    re-code metadata to i18n.commitEncoding\n"
    "    -n                    disable charset re-coding of metadata\n"
    "    --encoding <encoding> re-code metadata to this encoding\n"
    "    --[no-]scissors       use scissors\n"
    "    --quoted-cr <action>  action when quoted CR is found\n"
    "\n"
)


def cmd_mailinfo(argv: list[str]) -> int:
    """Port of builtin/mailinfo.c entry: extract authorship + message + patch
    from a single mail on stdin, writing <msg> and <patch> and printing the
    info block."""
    from . import am as _am
    mi = _am.Mailinfo()
    # meta_charset.policy: 0=DEFAULT, 1=NO_REENCODE, 2=EXPLICIT (mirror mailinfo.c)
    charset_policy = 0
    charset_explicit = None
    msg_file = patch_file = None
    i = 0
    positional: list[str] = []
    n = len(argv)

    def qcr_action(val):
        return {"nowarn": _am.QCR_NOWARN, "warn": _am.QCR_WARN,
                "strip": _am.QCR_STRIP}.get(val)

    def usage_with_options(stream) -> None:
        stream.write(_MAILINFO_USAGE)

    # Port of parse_options() for mailinfo's option table: clustered short flags,
    # --long[=value], the auto --no- negations (only for negatable bools) and the
    # unknown-option / unknown-switch / -h handling.
    saw_dd = False
    while i < n:
        arg = argv[i]
        if not saw_dd and arg == "--":
            # The "--" separator: subsequent args are all positional.
            saw_dd = True
            i += 1
            continue
        if saw_dd or not arg.startswith("-") or arg == "-":
            positional.append(arg)
            i += 1
            continue
        if arg == "-h" or arg == "--help":
            # parse_options -h prints the usage to STDOUT and exits 129.
            usage_with_options(sys.stdout)
            return 129
        if arg.startswith("--"):
            body = arg[2:]
            name, eq, val = body.partition("=")
            has_val = bool(eq)
            negated = name.startswith("no-")
            base = name[3:] if negated else name
            # Unique-prefix abbreviation (parse-options): resolve a partial long
            # option name to its full spelling. Negatable bools also match their
            # "no-" forms; ambiguous prefixes error.
            _long_opts = ["message-id", "scissors", "encoding", "quoted-cr",
                          "inbody-headers"]
            if base and base not in _long_opts:
                matches = [o for o in _long_opts if o.startswith(base)]
                if len(matches) == 1:
                    base = matches[0]
                elif len(matches) > 1:
                    # Exact-prefix that is itself a full option wins; else error.
                    _err(f"error: ambiguous option: {name} "
                         f"(could be {' or '.join('--' + m for m in matches)})")
                    return 129
            # Long options (negation allowed only where parse-options would).
            if base == "message-id" and not has_val:
                mi.add_message_id = 0 if negated else 1
            elif base == "scissors" and not has_val:
                mi.use_scissors = 0 if negated else 1
            elif base == "inbody-headers" and not has_val:
                mi.use_inbody_headers = 0 if negated else 1
            elif base == "encoding" and not negated:
                if has_val:
                    charset_policy = 2
                    charset_explicit = val
                else:
                    i += 1
                    if i >= n:
                        _err("error: option `encoding' requires a value")
                        return 129
                    charset_policy = 2
                    charset_explicit = argv[i]
            elif base == "quoted-cr" and not negated:
                if has_val:
                    qval = val
                else:
                    i += 1
                    if i >= n:
                        _err("error: option `quoted-cr' requires a value")
                        return 129
                    qval = argv[i]
                act = qcr_action(qval)
                if act is None:
                    # A callback error() exits 129 WITHOUT the usage block.
                    _err(f"error: bad action '{qval}' for '--quoted-cr'")
                    return 129
                mi.quoted_cr = act
            else:
                # NONEG options reject their --no- form; everything else is an
                # unknown option. parse-options reports the name without "--".
                _err(f"error: unknown option `{body}'")
                usage_with_options(sys.stderr)
                return 129
            i += 1
            continue
        # Clustered short options: process each character of the token in turn.
        j = 1
        consumed_next = False
        bad = None
        while j < len(arg):
            c = arg[j]
            if c == "k":
                mi.keep_subject = 1
            elif c == "b":
                mi.keep_non_patch_brackets_in_subject = 1
            elif c == "m":
                mi.add_message_id = 1
            elif c == "u":
                charset_policy = 0
            elif c == "n":
                charset_policy = 1
            else:
                bad = c
                break
            j += 1
        if bad is not None:
            _err(f"error: unknown switch `{bad}'")
            usage_with_options(sys.stderr)
            return 129
        i += 1
    if len(positional) != 2:
        usage_with_options(sys.stderr)
        return 129
    # Resolve meta_charset policy (mailinfo.c cmd_mailinfo switch).
    #   CHARSET_DEFAULT    -> get_commit_output_encoding() == "UTF-8"
    #   CHARSET_NO_REENCODE-> NULL
    #   CHARSET_EXPLICIT   -> the switch's `break` leaves mi.metainfo_charset
    #                         at its setup_mailinfo() memset value (NULL); the
    #                         parsed charset is stored only in the local
    #                         meta_charset struct and never copied into mi.  So
    #                         an explicit --encoding=<X> disables re-coding (same
    #                         observable effect as -n), regardless of <X>.
    if charset_policy == 0:        # CHARSET_DEFAULT
        mi.metainfo_charset = "UTF-8"
    elif charset_policy == 1:      # CHARSET_NO_REENCODE
        mi.metainfo_charset = None
    else:                          # CHARSET_EXPLICIT
        del charset_explicit
        mi.metainfo_charset = None
    msg_file, patch_file = positional[0], positional[1]
    data = _stdin_bytes()
    msg_b, patch_b, info_b = _am.run_mailinfo(mi, data)
    if msg_b is None:
        _err(f"error: empty patch: '{patch_file}'")
        return 1
    Path(msg_file).write_bytes(msg_b)
    Path(patch_file).write_bytes(patch_b)
    sys.stdout.flush()
    sys.stdout.buffer.write(info_b)
    sys.stdout.buffer.flush()
    if mi._warn_quoted_cr:
        _err("warning: quoted CRLF detected")
    if getattr(mi, "format_flowed", 0):
        _err("warning: Patch sent with format=flowed; "
             "space at the end of lines might be lost.")
    if mi.input_error:
        return 1
    return 0


def _notes_ref(name: str) -> str:
    return name if name.startswith("refs/notes/") else f"refs/notes/{name}"


_NOTES_SUBCOMMANDS = {"add", "append", "copy", "edit", "show", "list", "remove",
                      "prune", "get-ref", "merge"}


def _notes_write(repo: Repository, ref: str, notes_map: dict, base_sha, verb: str) -> None:
    """Rebuild the notes tree from ``notes_map`` and commit it onto ``ref``."""
    from .index import Index, IndexEntry, REG_MODE, write_index, read_index
    saved_idx = read_index(repo) if (repo.gitdir / "index").exists() else None
    idx = Index()
    for p, s in sorted(notes_map.items()):
        idx.entries.append(IndexEntry(mode=REG_MODE, sha=s, path=p))
    write_index(repo, idx)
    new_tree = workdir.write_tree(repo)
    if saved_idx is not None:
        write_index(repo, saved_idx)
    else:
        (repo.gitdir / "index").unlink(missing_ok=True)
    name, email = repo.user()
    sig = objs.format_signature(name, email, when=int(time.time()))
    parents = [base_sha] if base_sha else []
    c = objs.Commit(tree=new_tree, parents=parents, author=sig, committer=sig,
                    message=f"Notes {verb} by 'git notes'\n")
    sha = objs.write_object(repo, "commit", c.encode())
    refs_mod.update_ref(repo, ref, sha, message=f"notes: {verb}")


_NOTES_USAGE_LINES = [
    "git notes [--ref <notes-ref>] [list [<object>]]",
    "git notes [--ref <notes-ref>] add [-f] [--allow-empty] "
    "[--[no-]separator|--separator=<paragraph-break>] [--[no-]stripspace] "
    "[-m <msg> | -F <file> | (-c | -C) <object>] [<object>] [-e]",
    "git notes [--ref <notes-ref>] copy [-f] <from-object> <to-object>",
    "git notes [--ref <notes-ref>] append [--allow-empty] "
    "[--[no-]separator|--separator=<paragraph-break>] [--[no-]stripspace] "
    "[-m <msg> | -F <file> | (-c | -C) <object>] [<object>] [-e]",
    "git notes [--ref <notes-ref>] edit [--allow-empty] [<object>]",
    "git notes [--ref <notes-ref>] show [<object>]",
    "git notes [--ref <notes-ref>] merge [-v | -q] [-s <strategy>] <notes-ref>",
    "git notes merge --commit [-v | -q]",
    "git notes merge --abort [-v | -q]",
    "git notes [--ref <notes-ref>] remove [<object>...]",
    "git notes [--ref <notes-ref>] prune [-n] [-v]",
    "git notes [--ref <notes-ref>] get-ref",
]


def _notes_main_usage_err(prefix_err: Optional[str]) -> int:
    opts = [_PoOpt()]
    opts[0].long_name = "ref"
    opts[0].argh = "notes-ref"
    opts[0].help = "use notes from <notes-ref>"
    if prefix_err is not None:
        _err(prefix_err)
    sys.stderr.write(_po_render_usage(_NOTES_USAGE_LINES, opts, False, True))
    return 129


def _notes_prune_usage_err(prefix_err: Optional[str]) -> int:
    def O(short, long, help):
        o = _PoOpt()
        o.short_name = short
        o.long_name = long
        o.flags = _PARSEOPT_NOARG
        o.help = help
        return o
    opts = [O('n', 'dry-run', "do not remove, show only"),
            O('v', 'verbose', "report pruned notes")]
    if prefix_err is not None:
        _err(prefix_err)
    sys.stderr.write(_po_render_usage(["git notes prune [<options>]"], opts, False, True))
    return 129


def _notes_getref_usage_err(prefix_err: Optional[str]) -> int:
    if prefix_err is not None:
        _err(prefix_err)
    sys.stderr.write(_po_render_usage(["git notes get-ref"], [], False, True))
    return 129


def cmd_notes(argv: list[str]) -> int:
    repo = _repo()
    # Extract the global --ref[=<ref>] (may appear before the subcommand).
    ref_name = "commits"
    rest: list[str] = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--ref":
            if i + 1 >= len(argv):
                # OPT_STRING(0,"ref"): a value is required.
                _err("error: option `ref' requires a value")
                return 129
            ref_name = argv[i + 1]
            i += 2
            continue
        if a.startswith("--ref="):
            ref_name = a.split("=", 1)[1]
            i += 1
            continue
        rest.append(a)
        i += 1
    ref = _notes_ref(ref_name)

    # PARSE_OPT_SUBCOMMAND_OPTIONAL: the first non-option token must be a known
    # subcommand; an unknown one is "unknown subcommand" + the full usage block.
    action = "list"
    if rest and not rest[0].startswith("-"):
        if rest[0] in _NOTES_SUBCOMMANDS:
            action = rest[0]
            rest = rest[1:]
        else:
            return _notes_main_usage_err(f"error: unknown subcommand: `{rest[0]}'")

    if action == "get-ref":
        # get-ref has an empty option table: any option is "unknown option"; any
        # positional is "too many arguments". Both dump the get-ref usage rc 129.
        for tok in rest:
            if tok.startswith("--") and tok != "--":
                return _notes_getref_usage_err(f"error: unknown option `{tok[2:]}'")
            if tok.startswith("-") and tok != "-" and tok != "--":
                return _notes_getref_usage_err(f"error: unknown switch `{tok[1:]}'")
        if rest:
            return _notes_getref_usage_err("error: too many arguments")
        _print(ref)
        return 0

    notes_tree_sha = refs_mod.read_ref(repo, ref)
    notes_map: dict[str, str] = {}
    if notes_tree_sha:
        nc = objs.parse_commit(objs.read_object(repo, notes_tree_sha)[1])
        notes_map = {path: sha for path, _mode, sha in workdir.iter_tree_files(repo, nc.tree)}

    def _key(oid: str) -> str:
        return oid[:2] + "/" + oid[2:]

    if action == "list":
        if rest:
            t = refs_mod.rev_parse(repo, rest[0])
            if t and _key(t) in notes_map:
                _print(notes_map[_key(t)])
                return 0
            _err(f"error: no note found for object {t or rest[0]}.")
            return 1
        for path, blob_sha in sorted(notes_map.items()):
            _print(f"{blob_sha} {path.replace('/', '')}")
        return 0

    if action == "prune":
        # prune takes only -n/-v options; any positional is "too many arguments".
        prune_positionals = [t for t in rest if not t.startswith("-")]
        if prune_positionals:
            return _notes_prune_usage_err("error: too many arguments")
        dry = "-n" in rest or "--dry-run" in rest
        pruned = []
        for path in list(notes_map):
            oid = path.replace("/", "")
            if not objs.object_exists(repo, oid):
                pruned.append(oid)
                if not dry:
                    del notes_map[path]
        for oid in pruned:
            _print(oid)
        if pruned and not dry:
            _notes_write(repo, ref, notes_map, notes_tree_sha, "removed")
        return 0

    if action in ("add", "append", "edit"):
        mp = argparse.ArgumentParser(prog="pygit notes", add_help=False)
        mp.add_argument("-m", "--message", action="append", default=None)
        mp.add_argument("-F", "--file", action="append", default=None)
        mp.add_argument("-c", dest="reuse_edit", action="append", default=None)
        mp.add_argument("-C", "--reuse-message", dest="reuse", action="append", default=None)
        mp.add_argument("--separator", default=None)
        mp.add_argument("--no-separator", dest="no_separator", action="store_true")
        mp.add_argument("--stripspace", dest="stripspace", action="store_true")
        mp.add_argument("--no-stripspace", dest="no_stripspace", action="store_true")
        mp.add_argument("-f", "--force", action="store_true")
        mp.add_argument("--allow-empty", dest="allow_empty", action="store_true")
        mp.add_argument("-e", "--edit", action="store_true")
        mp.add_argument("object", nargs="?", default="HEAD")
        a = mp.parse_args(rest)
        # builtin/notes.c append_edit: with the 'edit' subcommand, -m/-F/-c/-C are
        # deprecated and emit a notice to stderr.
        if action == "edit" and (a.message or a.file or a.reuse or a.reuse_edit):
            _err("The -m/-F/-c/-C options have been deprecated for the 'edit' "
                 "subcommand.\nPlease use 'git notes add -f -m/-F/-c/-C' instead.")
        target = refs_mod.rev_parse(repo, a.object)
        if not target:
            _err(f"error: Failed to resolve '{a.object}' as a valid ref.")
            return 128
        key = _key(target)
        parts: list[str] = []
        if action == "append" and key in notes_map:
            parts.append(objs.read_object(repo, notes_map[key])[1].decode("utf-8", "replace"))
        for m in (a.message or []):
            parts.append(m)
        for f in (a.file or []):
            parts.append(sys.stdin.read() if f == "-" else open(f, encoding="utf-8").read())
        for o in (a.reuse or []) + (a.reuse_edit or []):
            s = refs_mod.rev_parse(repo, o)
            if s:
                parts.append(objs.read_object(repo, s)[1].decode("utf-8", "replace"))
        sep = "\n" if a.no_separator else (f"\n{a.separator}\n" if a.separator is not None else "\n\n")
        body = sep.join(p.rstrip("\n") for p in parts)
        if not body and not a.allow_empty and action != "edit":
            _err("fatal: please supply the note contents using either -m or -F option")
            return 128
        if action == "add" and key in notes_map and not a.force:
            _err(f"error: Cannot add notes. Found existing notes for object {target}. "
                 "Use '-f' to overwrite existing notes")
            return 1
        if action == "add" and key in notes_map and a.force:
            _err(f"Overwriting existing notes for object {target}")
        blob = objs.write_object(repo, "blob", (body + "\n").encode("utf-8") if body else b"")
        notes_map[key] = blob
        _notes_write(repo, ref, notes_map, notes_tree_sha, "added")
        return 0

    if action == "copy":
        cp = argparse.ArgumentParser(prog="pygit notes", add_help=False)
        cp.add_argument("-f", "--force", action="store_true")
        cp.add_argument("--stdin", dest="from_stdin", action="store_true")
        cp.add_argument("--for-rewrite", dest="for_rewrite", default=None)
        cp.add_argument("from_obj", nargs="?", default=None)
        cp.add_argument("to_obj", nargs="?", default=None)
        a = cp.parse_args(rest)
        # notes_copy_from_stdin (builtin/notes.c): bulk "<from> <to>" lines on
        # stdin. With --stdin (and no rewrite cmd) the positional from/to are
        # ignored ("too many arguments" only if both given).
        if a.from_stdin:
            if a.from_obj is not None and a.to_obj is not None:
                _err("error: too many arguments")
                return 129
            changed = False
            for line in _stdin_bytes().decode("utf-8", "replace").splitlines():
                parts = line.split()
                if len(parts) < 2:
                    if not parts:
                        continue
                    _err(f"fatal: malformed input line: '{line}'.")
                    return 128
                fsha = refs_mod.rev_parse(repo, parts[0])
                tsha = refs_mod.rev_parse(repo, parts[1])
                if not fsha:
                    _err(f"fatal: failed to resolve '{parts[0]}' as a valid ref.")
                    return 128
                if not tsha:
                    _err(f"fatal: failed to resolve '{parts[1]}' as a valid ref.")
                    return 128
                if _key(fsha) not in notes_map:
                    _err(f"error: failed to copy notes from '{parts[0]}' to '{parts[1]}'")
                    continue
                if _key(tsha) in notes_map and not a.force:
                    continue
                notes_map[_key(tsha)] = notes_map[_key(fsha)]
                changed = True
            if changed:
                _notes_write(repo, ref, notes_map, notes_tree_sha, "added")
            return 0
        if a.from_obj is None or a.to_obj is None:
            return _notes_main_usage_err(None)
        src = refs_mod.rev_parse(repo, a.from_obj)
        dst = refs_mod.rev_parse(repo, a.to_obj)
        if not src:
            _err(f"fatal: failed to resolve '{a.from_obj}' as a valid ref.")
            return 128
        if not dst:
            _err(f"fatal: failed to resolve '{a.to_obj}' as a valid ref.")
            return 128
        # builtin/notes.c copy(): the destination note is checked FIRST (existing
        # dest without -f fails; with -f, warns "Overwriting"), then the source.
        if _key(dst) in notes_map:
            if not a.force:
                _err(f"error: Cannot copy notes. Found existing notes for object {dst}. "
                     "Use '-f' to overwrite existing notes")
                return 1
            _err(f"Overwriting existing notes for object {dst}")
        if _key(src) not in notes_map:
            _err(f"error: missing notes on source object {src}. Cannot copy.")
            return 1
        notes_map[_key(dst)] = notes_map[_key(src)]
        _notes_write(repo, ref, notes_map, notes_tree_sha, "added")
        return 0

    if action == "show":
        obj = rest[-1] if rest and not rest[-1].startswith("-") else "HEAD"
        target = refs_mod.rev_parse(repo, obj)
        if not target:
            return 128
        if _key(target) not in notes_map:
            _err(f"error: no note found for object {target}.")
            return 1
        sys.stdout.buffer.write(objs.read_object(repo, notes_map[_key(target)])[1])
        return 0

    if action == "remove":
        rp = argparse.ArgumentParser(prog="pygit notes", add_help=False)
        rp.add_argument("--ignore-missing", dest="ignore_missing", action="store_true")
        rp.add_argument("--stdin", dest="from_stdin", action="store_true")
        rp.add_argument("objects", nargs="*", default=None)
        a = rp.parse_args(rest)
        # remove_one_note (builtin/notes.c): a missing note prints "Object <n> has
        # no note" and (without --ignore-missing) makes retval non-zero; a present
        # one prints "Removing note for object <n>". The transaction is only
        # committed when retval==0.
        objs_list = list(a.objects) if a.objects else (
            [] if a.from_stdin else ["HEAD"])
        if a.from_stdin:
            for line in _stdin_bytes().decode("utf-8", "replace").splitlines():
                objs_list.append(line.strip())
        retval = 0
        changed = False
        for o in objs_list:
            target = refs_mod.rev_parse(repo, o)
            if not target:
                _err(f"error: Failed to resolve '{o}' as a valid ref.")
                retval = 1
                continue
            if _key(target) in notes_map:
                _err(f"Removing note for object {o}")
                del notes_map[_key(target)]
                changed = True
            else:
                _err(f"Object {o} has no note")
                if not a.ignore_missing:
                    retval = 1
        if retval == 0 and changed:
            _notes_write(repo, ref, notes_map, notes_tree_sha, "removed")
        return retval
    return 0


def cmd_bisect(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit bisect")
    sub = ap.add_subparsers(dest="action", required=True)
    p_start = sub.add_parser("start")
    p_start.add_argument("bad", nargs="?")
    p_start.add_argument("good", nargs="?")
    p_bad = sub.add_parser("bad")
    p_bad.add_argument("rev", nargs="?", default="HEAD")
    p_good = sub.add_parser("good")
    p_good.add_argument("rev", nargs="?", default="HEAD")
    sub.add_parser("reset")
    sub.add_parser("log")
    args = ap.parse_args(argv)
    repo = _repo()
    state_dir = repo.gitdir / "BISECT"
    state_dir.mkdir(exist_ok=True)
    bads_path = state_dir / "bad"
    goods_path = state_dir / "good"

    def load(p):
        return p.read_text(encoding="utf-8").splitlines() if p.exists() else []

    def add(p, sha):
        with p.open("a", encoding="utf-8") as f:
            f.write(sha + "\n")

    def bisect_step():
        bads = load(bads_path)
        goods = load(goods_path)
        if not bads or not goods:
            _print("status: need at least one good and one bad")
            return 0
        graph = _graph_for_repo(repo)

        def commit_parents(sha: str) -> tuple[str, ...]:
            info = _commit_tree_parents(repo, sha, graph)
            return info[1] if info is not None else tuple()

        # candidates: ancestors of any bad, minus ancestors of any good and bads themselves
        anc_bad: set[str] = set()
        stack = list(bads)
        seen: set[str] = set()
        while stack:
            s = stack.pop()
            if s in seen:
                continue
            seen.add(s)
            anc_bad.add(s)
            stack.extend(commit_parents(s))
        for g in goods:
            seen2: set[str] = set()
            stack = [g]
            while stack:
                s = stack.pop()
                if s in seen2:
                    continue
                seen2.add(s)
                anc_bad.discard(s)
                stack.extend(commit_parents(s))
        candidates = anc_bad - set(bads)
        if not candidates:
            _print(f"{bads[0]} is the first bad commit")
            return 0
        # weight[c] = number of candidates reachable from c (including c)
        # best = argmax(min(weight, n - weight)) - matches git/bisect.c best_bisection
        parents_map: dict[str, list[str]] = {}
        for c_sha in candidates:
            parents_map[c_sha] = [p for p in commit_parents(c_sha) if p in candidates]
        n = len(candidates)
        best, best_distance = _best_bisection_candidate(candidates, parents_map)
        _print(f"Bisecting: {n // 2} revisions left to test after this (roughly {best_distance} steps)")
        _print(f"[{best}] candidate")
        t, d = objs.read_object(repo, best)
        tree = objs.parse_commit(d).tree
        workdir.checkout_tree(repo, tree)
        refs_mod.set_head(repo, best)
        return 0

    if args.action == "start":
        bads_path.unlink(missing_ok=True)
        goods_path.unlink(missing_ok=True)
        if args.bad:
            s = refs_mod.rev_parse(repo, args.bad)
            if s:
                add(bads_path, s)
        if args.good:
            s = refs_mod.rev_parse(repo, args.good)
            if s:
                add(goods_path, s)
        return bisect_step()
    if args.action == "bad":
        s = refs_mod.rev_parse(repo, args.rev)
        if s:
            add(bads_path, s)
        return bisect_step()
    if args.action == "good":
        s = refs_mod.rev_parse(repo, args.rev)
        if s:
            add(goods_path, s)
        return bisect_step()
    if args.action == "log":
        for line in load(bads_path):
            _print(f"# bad: {line}")
        for line in load(goods_path):
            _print(f"# good: {line}")
        return 0
    if args.action == "reset":
        import shutil as _sh
        _sh.rmtree(state_dir, ignore_errors=True)
        return 0
    return 1


def cmd_worktree(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit worktree")
    sub = ap.add_subparsers(dest="action", required=True)
    p_add = sub.add_parser("add")
    p_add.add_argument("path")
    p_add.add_argument("rev", nargs="?", default="HEAD")
    p_list = sub.add_parser("list")
    p_list.add_argument("--porcelain", action="store_true")
    p_remove = sub.add_parser("remove")
    p_remove.add_argument("path")
    args = ap.parse_args(argv)
    repo = _repo()
    worktrees_dir = repo.gitdir / "worktrees"
    if args.action == "add":
        wt_name = Path(args.path).name
        wt_dir = worktrees_dir / wt_name
        wt_dir.mkdir(parents=True, exist_ok=True)
        sha = refs_mod.rev_parse(repo, args.rev)
        if not sha:
            return 128
        (wt_dir / "HEAD").write_text(sha + "\n", encoding="utf-8")
        (wt_dir / "commondir").write_text(str(repo.gitdir) + "\n", encoding="utf-8")
        target_dir = Path(args.path).resolve()
        target_dir.mkdir(parents=True, exist_ok=True)
        (wt_dir / "gitdir").write_text(str(target_dir / ".git") + "\n", encoding="utf-8")
        (target_dir / ".git").write_text(f"gitdir: {wt_dir}\n", encoding="utf-8")
        t, data = objs.read_object(repo, sha)
        tree = objs.parse_commit(data).tree if t == "commit" else sha
        for path, _mode, bsha in workdir.iter_tree_files(repo, tree):
            _, blob = objs.read_object(repo, bsha)
            full = target_dir / path
            full.parent.mkdir(parents=True, exist_ok=True)
            full.write_bytes(blob)
        _print(f"Worktree added at {target_dir}")
        return 0
    if args.action == "list":
        head = refs_mod.rev_parse(repo, "HEAD") or ""
        head_sym, _ = refs_mod.read_head(repo)
        full_branch = head_sym if head_sym and head_sym.startswith("refs/heads/") else None
        branch = full_branch[len("refs/heads/"):] if full_branch else None
        if getattr(args, "porcelain", False):
            _print(f"worktree {repo.path}")
            _print(f"HEAD {head}")
            _print(f"branch {full_branch}" if full_branch else "detached")
            _print("")
            if worktrees_dir.exists():
                for d in sorted(worktrees_dir.iterdir()):
                    gitdir_file, head_file = d / "gitdir", d / "HEAD"
                    if d.is_dir() and gitdir_file.exists() and head_file.exists():
                        wt_path = Path(gitdir_file.read_text().strip()).parent
                        _print(f"worktree {wt_path}")
                        _print(f"HEAD {head_file.read_text().strip()}")
                        _print("")
            return 0
        label = f"[{branch}]" if branch else "(detached HEAD)"
        _print(f"{repo.path} {head[:7]} {label}")
        if worktrees_dir.exists():
            for d in worktrees_dir.iterdir():
                if d.is_dir():
                    gitdir_file = d / "gitdir"
                    head_file = d / "HEAD"
                    if gitdir_file.exists() and head_file.exists():
                        wt_path = Path(gitdir_file.read_text().strip()).parent
                        wt_head = head_file.read_text().strip()
                        _print(f"{wt_path} {wt_head[:7]} [{d.name}]")
        return 0
    if args.action == "remove":
        import shutil as _sh
        wt_name = Path(args.path).name
        wt_dir = worktrees_dir / wt_name
        if wt_dir.exists():
            _sh.rmtree(wt_dir, ignore_errors=True)
        target = Path(args.path)
        if target.exists():
            _sh.rmtree(target, ignore_errors=True)
        return 0
    return 1


def _register_phase4() -> None:
    _COMMANDS["pack-objects"] = cmd_pack_objects
    _COMMANDS["unpack-objects"] = cmd_unpack_objects
    _COMMANDS["index-pack"] = cmd_index_pack
    _COMMANDS["verify-pack"] = cmd_verify_pack
    _COMMANDS["count-objects"] = cmd_count_objects
    _COMMANDS["repack"] = cmd_repack
    _COMMANDS["prune"] = cmd_prune
    _COMMANDS["mailsplit"] = cmd_mailsplit
    _COMMANDS["mailinfo"] = cmd_mailinfo
    _COMMANDS["notes"] = cmd_notes
    _COMMANDS["bisect"] = cmd_bisect
    _COMMANDS["worktree"] = cmd_worktree


_register_phase4()


# ---------------------------------------------------------------------------
# Phase 5 — pull / grep / show-branch / whatchanged / mktag / name-rev /
#           var / stripspace / update-server-info / replace / cherry /
#           range-diff


def cmd_pull(argv: list[str]) -> int:
    repo = _repo()
    from . import gitconfig

    # Split pull options into fetch-side and merge/rebase-side, mirroring
    # builtin/pull.c run_merge()/run_rebase() option forwarding.
    verbosity = 0
    opt_rebase = None        # None=unspecified, False, True
    opt_ff = None            # None, "--ff", "--no-ff", "--ff-only"
    no_commit = False
    no_stat = False
    squash = False
    verify_signatures = False
    dry_run = False
    strategies: list[str] = []
    strategy_opts: list[str] = []
    fetch_opts: list[str] = []   # forwarded to the fetch step
    gpg_sign = None              # None=unset, ""=sign default key, "<keyid>"
    no_gpg_sign = False
    positional: list[str] = []

    i = 0
    n = len(argv)

    def need(arg):
        nonlocal i
        i += 1
        if i >= n:
            _err("error: option requires a value")
            sys.exit(129)
        return argv[i]

    while i < n:
        a = argv[i]
        if a == "--":
            positional.extend(argv[i + 1:]); break
        elif a in ("-v", "--verbose"):
            verbosity += 1; fetch_opts.append("-v")
        elif a in ("-q", "--quiet"):
            verbosity = -1; fetch_opts.append("-q")
        elif a in ("-r", "--rebase"):
            opt_rebase = True
        elif a == "--no-rebase":
            opt_rebase = False
        elif a == "--ff":
            opt_ff = "--ff"
        elif a == "--no-ff":
            opt_ff = "--no-ff"
        elif a == "--ff-only":
            opt_ff = "--ff-only"
        elif a in ("-n", "--no-stat"):
            no_stat = True
        elif a == "--stat":
            no_stat = False
        elif a == "--no-commit":
            no_commit = True
        elif a == "--commit":
            no_commit = False
        elif a == "--squash":
            squash = True
        elif a == "--no-squash":
            squash = False
        elif a == "--verify-signatures":
            verify_signatures = True
        elif a == "--no-verify-signatures":
            verify_signatures = False
        elif a == "--dry-run":
            dry_run = True; fetch_opts.append("--dry-run")
        elif a == "--no-dry-run":
            dry_run = False
        elif a == "--all":
            fetch_opts.append("--all")
        elif a in ("-e", "--edit", "--no-edit"):
            pass
        elif a in ("--autostash", "--no-autostash",
                   "--allow-unrelated-histories", "--signoff", "--no-signoff",
                   "--progress", "--no-progress", "--no-verify", "--verify",
                   "--compact-summary", "--no-compact-summary",
                   "--summary", "--no-summary"):
            pass
        elif a in ("--log", "--no-log") or a.startswith("--log="):
            pass
        elif a == "--cleanup":
            need(a)
        elif a.startswith("--cleanup="):
            pass
        elif a == "--set-upstream":
            fetch_opts.append("--set-upstream")
        elif a in ("--depth", "--shallow-since", "--shallow-exclude", "--deepen",
                   "--negotiation-tip", "--upload-pack"):
            fetch_opts.append(a); fetch_opts.append(need(a))
        elif (a.startswith("--depth=") or a.startswith("--shallow-since=")
              or a.startswith("--shallow-exclude=") or a.startswith("--deepen=")
              or a.startswith("--negotiation-tip=") or a.startswith("--upload-pack=")):
            fetch_opts.append(a)
        elif a in ("--update-shallow", "--no-update-shallow",
                   "--show-forced-updates", "--no-show-forced-updates"):
            fetch_opts.append(a)
        elif a in ("--recurse-submodules", "--no-recurse-submodules"):
            pass
        elif a.startswith("--recurse-submodules="):
            pass
        elif a in ("-s", "--strategy"):
            strategies.append(need(a))
        elif a.startswith("--strategy="):
            strategies.append(a.split("=", 1)[1])
        elif a in ("-X", "--strategy-option"):
            strategy_opts.append(need(a))
        elif a.startswith("--strategy-option="):
            strategy_opts.append(a.split("=", 1)[1])
        elif a.startswith("-X"):
            strategy_opts.append(a[2:])
        elif a in ("-a", "--append", "-f", "--force", "-t", "--tags",
                   "-p", "--prune", "-k", "--keep", "--unshallow", "--refetch",
                   "--no-tags"):
            fetch_opts.append(a)
        elif a in ("-j", "--jobs"):
            fetch_opts.append(a); fetch_opts.append(need(a))
        elif a in ("-o", "--server-option"):
            fetch_opts.append(a); fetch_opts.append(need(a))
        elif a == "--refmap":
            fetch_opts.append(a); fetch_opts.append(need(a))
        elif a.startswith("--refmap="):
            fetch_opts.append(a)
        elif a in ("--ipv4", "-4", "--ipv6", "-6"):
            fetch_opts.append(a)
        elif a in ("-S", "--gpg-sign"):
            # PARSE_OPT_OPTARG: bare -S signs with the default key.
            gpg_sign = ""
        elif a.startswith("--gpg-sign="):
            gpg_sign = a.split("=", 1)[1]
        elif a.startswith("-S"):
            gpg_sign = a[2:]
        elif a == "--no-gpg-sign":
            no_gpg_sign = True
        elif a.startswith("-") and a != "-":
            # parse-options error wording: long -> "unknown option", short ->
            # "unknown switch", followed by the full usage block (builtin/pull.c).
            from ._transport_usage import PULL_USAGE
            if a.startswith("--"):
                _err(f"error: unknown option `{a[2:]}'")
            else:
                _err(f"error: unknown switch `{a[1]}'")
            sys.stderr.write(PULL_USAGE)
            return 129
        else:
            positional.append(a)
        i += 1

    repo_arg = positional[0] if positional else None
    refspecs = positional[1:] if len(positional) > 1 else []

    # 1. Fetch.
    fetch_argv = list(fetch_opts)
    if repo_arg is not None:
        fetch_argv.append(repo_arg)
        fetch_argv.extend(refspecs)
    fetch_rc = _cmd_fetch_impl(fetch_argv)
    if fetch_rc != 0:
        return fetch_rc

    # builtin/pull.c: --dry-run forwards a dry-run fetch then stops (the merge
    # step is never reached).
    if dry_run:
        return 0

    # 2. Gather merge heads from FETCH_HEAD (entries not marked not-for-merge).
    merge_heads = _read_merge_heads(repo)
    if not merge_heads:
        return _pull_no_merge_candidates(repo, repo_arg, refspecs, opt_rebase)

    head_sym, orig_head = refs_mod.read_head(repo)

    # Empty head: behave like a checkout of the single merge head.
    if orig_head is None:
        target = merge_heads[0]
        if head_sym:
            refs_mod.update_ref(repo, head_sym, target, message="initial pull")
        else:
            refs_mod.set_head(repo, target)
        commit = objs.parse_commit(objs.read_object(repo, target)[1])
        workdir.checkout_tree(repo, commit.tree)
        return 0

    if len(merge_heads) > 1:
        if opt_rebase:
            _err("fatal: Cannot rebase onto multiple branches.")
            return 128
        if opt_ff == "--ff-only":
            _err("fatal: Cannot fast-forward to multiple branches.")
            return 128

    # Determine divergence (builtin/pull.c get_can_ff / already_up_to_date).
    can_ff = all(orig_head == mh or _is_fast_forward(repo, repo, orig_head, mh)
                 for mh in merge_heads)
    up_to_date = all(mh == orig_head or _is_fast_forward(repo, repo, mh, orig_head)
                     for mh in merge_heads)
    divergent = (not can_ff) and (not up_to_date)

    # ff-only takes precedence over rebase.
    if opt_ff == "--ff-only":
        if divergent:
            return _pull_die_ff_impossible()
        opt_rebase = False
    # No action specified and we can't fast-forward -> require a choice.
    if opt_ff is None and opt_rebase is None and divergent:
        _err(_advice_lines(_PULL_NONFF_ADVICE))
        _err("fatal: Need to specify how to reconcile divergent branches.")
        return 128

    # 3. Merge or rebase.
    merge_argv = []
    if verbosity < 0:
        merge_argv.append("-q")
    elif verbosity > 0:
        merge_argv.append("-v")
    for s in strategies:
        merge_argv.extend(["-s", s])
    for x in strategy_opts:
        merge_argv.extend(["-X", x])
    if no_commit:
        merge_argv.append("--no-commit")
    if no_stat:
        merge_argv.append("--no-stat")
    if squash:
        merge_argv.append("--squash")
    if verify_signatures:
        merge_argv.append("--verify-signatures")
    # Forward GPG signing to the merge step (builtin/pull.c OPT_PASSTHRU).
    if no_gpg_sign:
        merge_argv.append("--no-gpg-sign")
    elif gpg_sign is not None:
        merge_argv.append("-S" + gpg_sign)

    if opt_rebase:
        if can_ff:
            return cmd_merge(merge_argv + ["--ff-only"] + merge_heads)
        return cmd_rebase([merge_heads[0]])

    if opt_ff:
        merge_argv.append(opt_ff)
    # A non-ff merge needs git's fmt-merge-msg title ("Merge branch 'x' of url").
    msg = _pull_merge_title(repo)
    if msg and not can_ff:
        merge_argv.extend(["-m", msg])
    merge_argv.extend(merge_heads)
    return cmd_merge(merge_argv)


def _pull_merge_title(repo) -> Optional[str]:
    """builtin/merge.c + fmt-merge-msg.c default merge title from FETCH_HEAD.

    Groups the for-merge FETCH_HEAD entries by source URL and kind, producing
    e.g. "Merge branch 'main' of <url>".  The "into <branch>" suffix is omitted
    for the default branches main/master (the built-in suppress-dest patterns).
    """
    path = repo.gitdir / "FETCH_HEAD"
    if not path.exists():
        return None
    # Per source: lists of branch/tag/remote/generic names.
    from collections import OrderedDict
    srcs = OrderedDict()
    for line in path.read_text(encoding="utf-8").splitlines():
        if not line.strip():
            continue
        parts = line.split("\t")
        if len(parts) < 3:
            continue
        if parts[1].strip() == "not-for-merge":
            continue
        note = parts[2]
        kind, name, url = _parse_fetch_head_note(note)
        entry = srcs.setdefault(url, dict(branch=[], tag=[], r_branch=[], generic=[]))
        entry[kind].append(name)
    if not srcs:
        return None

    def join(sing, plur, names):
        if len(names) == 1:
            return sing + "'" + names[0] + "'"
        quoted = ", ".join("'" + n + "'" for n in names[:-1])
        return plur + quoted + " and '" + names[-1] + "'"

    pieces = []
    for url, e in srcs.items():
        sub = []
        if e["branch"]:
            sub.append(join("branch ", "branches ", e["branch"]))
        if e["r_branch"]:
            sub.append(join("remote-tracking branch ", "remote-tracking branches ", e["r_branch"]))
        if e["tag"]:
            sub.append(join("tag ", "tags ", e["tag"]))
        if e["generic"]:
            sub.append(join("commit ", "commits ", e["generic"]))
        piece = ", ".join(sub)
        if url and url != ".":
            piece += f" of {url}"
        pieces.append(piece)
    title = "Merge " + "; ".join(pieces)

    head_sym, _ = refs_mod.read_head(repo)
    if head_sym and head_sym.startswith("refs/heads/"):
        dest = head_sym[len("refs/heads/"):]
        if dest not in ("main", "master"):
            title += f" into {dest}"
    return title


def _parse_fetch_head_note(note: str) -> "tuple[str, str, str]":
    """Parse a FETCH_HEAD note into (kind, name, url).

    Notes look like "branch 'main' of <url>", "tag 'v1' of <url>",
    "'HEAD' of <url>", or "remote-tracking branch 'x' of <url>".
    """
    url = ""
    body = note
    # split " of <url>" off the end (url may contain spaces only rarely).
    idx = note.rfind("' of ")
    if idx != -1:
        body = note[:idx + 1]
        url = note[idx + 5:]
    kind = "generic"
    if body.startswith("branch "):
        kind = "branch"; rest = body[len("branch "):]
    elif body.startswith("tag "):
        kind = "tag"; rest = body[len("tag "):]
    elif body.startswith("remote-tracking branch "):
        kind = "r_branch"; rest = body[len("remote-tracking branch "):]
    else:
        rest = body
    name = rest.strip()
    if name.startswith("'") and name.endswith("'"):
        name = name[1:-1]
    return kind, name, url


_PULL_NONFF_ADVICE = (
    "You have divergent branches and need to specify how to reconcile them.\n"
    "You can do so by running one of the following commands sometime before\n"
    "your next pull:\n"
    "\n"
    "  git config pull.rebase false  # merge\n"
    "  git config pull.rebase true   # rebase\n"
    "  git config pull.ff only       # fast-forward only\n"
    "\n"
    "You can replace \"git config\" with \"git config --global\" to set a default\n"
    "preference for all repositories. You can also pass --rebase, --no-rebase,\n"
    "or --ff-only on the command line to override the configured default per\n"
    "invocation.\n")


def _pull_die_ff_impossible() -> int:
    # advise_if_enabled(ADVICE_DIVERGING, ...) appends the standard "Disable
    # this message" hint keyed by the advice name.
    _err(_advice_lines(
        "Diverging branches can't be fast-forwarded, you need to either:\n"
        "\n"
        "\tgit merge --no-ff\n"
        "\n"
        "or:\n"
        "\n"
        "\tgit rebase\n"
        "\n"
        'Disable this message with "git config set advice.diverging false"'))
    _err("fatal: Not possible to fast-forward, aborting.")
    return 128


def _read_merge_heads(repo: Repository) -> list[str]:
    """builtin/pull.c get_merge_heads(): FETCH_HEAD entries not 'not-for-merge'."""
    path = repo.gitdir / "FETCH_HEAD"
    if not path.exists():
        return []
    heads = []
    for line in path.read_text(encoding="utf-8").splitlines():
        if not line.strip():
            continue
        parts = line.split("\t")
        if len(parts) < 2:
            continue
        oid = parts[0].strip()
        marker = parts[1].strip()
        if marker == "not-for-merge":
            continue
        heads.append(oid)
    return heads


def _pull_no_merge_candidates(repo, repo_arg, refspecs, opt_rebase) -> int:
    from . import gitconfig
    head_sym, _ = refs_mod.read_head(repo)
    curr_branch = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else None
    remote = gitconfig.get(repo, f"branch.{curr_branch}.remote") if curr_branch else None
    rebase_word = "rebase against" if opt_rebase else "merge with"

    if refspecs:
        if opt_rebase:
            sys.stderr.write("There is no candidate for rebasing against among the refs that you just fetched.\n")
        else:
            sys.stderr.write("There are no candidates for merging among the refs that you just fetched.\n")
        sys.stderr.write("Generally this means that you provided a wildcard refspec which had no\n"
                         "matches on the remote end.\n")
        return 1
    if repo_arg and curr_branch and (not remote or repo_arg != remote):
        sys.stderr.write(
            f"You asked to pull from the remote '{repo_arg}', but did not specify\n"
            "a branch. Because this is not the default configured remote\n"
            "for your current branch, you must specify a branch on the command line.\n")
        return 1
    if not curr_branch:
        sys.stderr.write("You are not currently on a branch.\n")
        sys.stderr.write(f"Please specify which branch you want to {rebase_word}.\n")
        sys.stderr.write("See git-pull(1) for details.\n\n")
        sys.stderr.write("    git pull <remote> <branch>\n\n")
        return 1
    # No tracking information for the branch.
    only_remote = _only_remote_name(repo) or "<remote>"
    sys.stderr.write("There is no tracking information for the current branch.\n")
    sys.stderr.write(f"Please specify which branch you want to {rebase_word}.\n")
    sys.stderr.write("See git-pull(1) for details.\n\n")
    sys.stderr.write("    git pull <remote> <branch>\n\n")
    sys.stderr.write("If you wish to set tracking information for this branch you can do so with:\n\n")
    sys.stderr.write(f"    git branch --set-upstream-to={only_remote}/<branch> {curr_branch}\n\n")
    return 1


def _only_remote_name(repo: Repository):
    names = _all_remote_names(repo)
    return names[0] if len(names) == 1 else None


def _grep_bre_to_python(pattern: str) -> str:
    """Translate a POSIX Basic Regular Expression (glibc, as used by `git grep`
    in its default mode) to an equivalent Python `re` (ERE-style) pattern.

    In BRE: '+', '?', '{', '}', '(', ')', '|' are LITERAL; their backslashed
    forms ('\\+', '\\?', '\\{', '\\}', '\\(', '\\)', '\\|') are the special
    operators. '*' is literal at the very start or just after '(' / '|'."""
    out = []
    i = 0
    n = len(pattern)
    # Track whether '*' would be literal: true at start-of-(sub)expression.
    at_start = True
    while i < n:
        c = pattern[i]
        if c == "\\" and i + 1 < n:
            nxt = pattern[i + 1]
            if nxt in "(){}|+?":
                # Backslashed BRE operator -> ERE operator.
                out.append(nxt)
                at_start = nxt in "(|"
                i += 2
                continue
            if nxt == "<":
                out.append(r"\b(?=\w)")
                at_start = False
                i += 2
                continue
            if nxt == ">":
                out.append(r"\b(?<=\w)")
                at_start = False
                i += 2
                continue
            # Other escapes (\. \\ \1 \w \b ...) pass through verbatim.
            out.append("\\" + nxt)
            at_start = False
            i += 2
            continue
        if c in "(){}|+?":
            # Bare metachar -> literal in BRE.
            out.append("\\" + c)
            at_start = False
            i += 1
            continue
        if c == "*":
            if at_start:
                out.append("\\*")  # literal '*' at start of expression
            else:
                out.append("*")
            at_start = False
            i += 1
            continue
        if c == "[":
            # Bracket expression: copy verbatim to the matching ']'.
            j = i + 1
            if j < n and pattern[j] in "^":
                j += 1
            if j < n and pattern[j] == "]":
                j += 1
            while j < n and pattern[j] != "]":
                j += 1
            if j < n:
                out.append(pattern[i:j + 1])
                i = j + 1
            else:
                out.append("\\[")
                i += 1
            at_start = False
            continue
        if c == "^":
            out.append("^")
            # '^' keeps at_start so a following '*' is literal too.
            i += 1
            continue
        out.append(c)
        at_start = False
        i += 1
    return "".join(out)


def _grep_parse_bool_expr(argv: list[str]):
    """Parse a boolean grep expression (--and/--or/--not and grouping with
    ( )) the way grep.c compile_pattern_* does.

    Returns one of:
      * ('error', rc)  — a fatal was printed; cmd_grep returns rc.
      * ('none', None)  — no boolean operators present; use the normal path.
      * ('tree', node, atom_strs) — a structurally valid boolean expression;
        ``node`` is a nested ('atom', s) / ('not', x) / ('and', x, y) /
        ('or', x, y) tree and ``atom_strs`` lists the atom pattern strings.
    """
    OPS = {"--and", "--or", "--not", "(", ")"}
    if not any(t in OPS for t in argv):
        return ("none", None)
    toks = []  # ('AND'|'OR'|'NOT'|'OPEN'|'CLOSE', payload) or ('ATOM', pattern)
    i = 0
    n = len(argv)
    while i < n:
        t = argv[i]
        if t == "--":
            break
        if t == "--and":
            toks.append(("AND", t))
        elif t == "--or":
            # grep.c: --or is a no-op flag; OR is implicit between two adjacent
            # pattern expressions (compile_pattern_or recursion).
            pass
        elif t == "--not":
            toks.append(("NOT", t))
        elif t == "(":
            toks.append(("OPEN", t))
        elif t == ")":
            toks.append(("CLOSE", t))
        elif t == "-e":
            i += 1
            if i < n:
                toks.append(("ATOM", argv[i]))
        elif t.startswith("-e") and not t.startswith("--") and len(t) > 2:
            toks.append(("ATOM", t[2:]))
        elif t.startswith("-"):
            pass  # other options don't participate in the expression
        else:
            toks.append(("ATOM", t))
        i += 1

    pos = [0]
    atom_strs: list[str] = []

    class _Die(Exception):
        def __init__(self, msg):
            self.msg = msg

    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None

    def advance():
        pos[0] += 1

    def atom():
        p = peek()
        if p is None:
            return None
        if p[0] == "ATOM":
            advance()
            atom_strs.append(p[1])
            return ("atom", p[1])
        if p[0] == "OPEN":
            advance()
            x = pat_or()
            q = peek()
            if q is None or q[0] != "CLOSE":
                raise _Die("unmatched ( for expression group")
            advance()
            return x
        return None

    def pat_not():
        p = peek()
        if p is not None and p[0] == "NOT":
            if pos[0] + 1 >= len(toks):
                raise _Die("--not not followed by pattern expression")
            advance()
            x = pat_not()
            if not x:
                raise _Die("--not followed by non pattern expression")
            return ("not", x)
        return atom()

    def pat_and():
        x = pat_not()
        p = peek()
        if p is not None and p[0] == "AND":
            if not x:
                raise _Die("--and not preceded by pattern expression")
            if pos[0] + 1 >= len(toks):
                raise _Die("--and not followed by pattern expression")
            advance()
            y = pat_and()
            if not y:
                raise _Die("--and not followed by pattern expression")
            return ("and", x, y)
        return x

    def pat_or():
        x = pat_and()
        p = peek()
        if x and p is not None and p[0] != "CLOSE":
            y = pat_or()
            if not y:
                raise _Die(f"not a pattern expression {p[1]}")
            return ("or", x, y)
        return x

    try:
        tree = pat_or()
        leftover = peek()
        if leftover is not None:
            raise _Die(f"incomplete pattern expression group: {leftover[1]}")
        if not tree:
            return ("none", None)
    except _Die as d:
        _err("fatal: " + d.msg)
        return ("error", 128)
    return ("tree", tree, atom_strs)


def cmd_grep(argv: list[str]) -> int:
    import re
    ap = argparse.ArgumentParser(prog="pygit grep", add_help=False)
    ap.add_argument("-i", "--ignore-case", dest="ignore_case", action="store_true")
    ap.add_argument("-n", "--line-number", dest="line_number", action="store_true")
    ap.add_argument("--column", dest="columnnum", action="store_true")
    # -l/--name-only set name_only; -L sets unmatch_name_only (it wins).
    ap.add_argument("-l", "--files-with-matches", "--name-only", dest="name_only", action="store_true")
    ap.add_argument("-L", "--files-without-match", dest="unmatch_name_only", action="store_true")
    ap.add_argument("-c", "--count", action="store_true")
    ap.add_argument("-o", "--only-matching", dest="only_matching", action="store_true")
    ap.add_argument("-w", "--word-regexp", dest="word_regexp", action="store_true")
    ap.add_argument("-v", "--invert-match", dest="invert", action="store_true")
    ap.add_argument("-F", "--fixed-strings", dest="fixed", action="store_true")
    ap.add_argument("-E", "--extended-regexp", dest="extended", action="store_true")
    ap.add_argument("-G", "--basic-regexp", dest="basic", action="store_true")
    ap.add_argument("-P", "--perl-regexp", dest="perl", action="store_true")
    # -a/--text, -I (don't match binary), --max-depth, --threads, --untracked,
    # --recurse-submodules, --textconv: accepted; mostly no-ops on tracked text.
    ap.add_argument("-a", "--text", dest="text", action="store_true")
    ap.add_argument("-I", dest="no_match_binary", action="store_true")
    ap.add_argument("--max-depth", dest="max_depth", type=int, default=-1)
    ap.add_argument("--threads", dest="threads", type=int, default=None)
    ap.add_argument("--untracked", dest="untracked", action="store_true")
    ap.add_argument("--recurse-submodules", dest="recurse_submodules", action="store_true")
    ap.add_argument("--textconv", dest="textconv", action="store_true")
    ap.add_argument("--no-textconv", dest="no_textconv", action="store_true")
    ap.add_argument("--exclude-standard", dest="exclude_standard", action="store_true")
    ap.add_argument("-q", "--quiet", action="store_true")
    # -h clears the filename flag (NEGBIT), -H sets it (BIT); default shows it.
    ap.add_argument("-H", dest="with_filename", action="store_true")
    ap.add_argument("-h", dest="no_filename", action="store_true")
    ap.add_argument("--full-name", dest="full_name", action="store_true")
    ap.add_argument("-z", "--null", dest="nul", action="store_true")
    ap.add_argument("-e", dest="patterns", action="append", default=[])
    ap.add_argument("-A", "--after-context", dest="after", type=int, default=0)
    ap.add_argument("-B", "--before-context", dest="before", type=int, default=0)
    ap.add_argument("-C", "--context", dest="context", type=int, default=0)
    ap.add_argument("-m", "--max-count", dest="max_count", type=int, default=None)
    ap.add_argument("--heading", action="store_true")
    ap.add_argument("--break", dest="file_break", action="store_true")
    ap.add_argument("--all-match", dest="all_match", action="store_true")
    ap.add_argument("--color", nargs="?", const="always", default=None)  # ignored
    ap.add_argument("--no-color", action="store_true")
    ap.add_argument("--cached", action="store_true")
    # -r/--recursive is the default-on recursive flag (no-op); --no-recursive
    # would limit depth, but is accepted here for parity. --no-index searches
    # files directly, working outside a repository.
    ap.add_argument("-r", "--recursive", dest="recursive", action="store_true")
    ap.add_argument("--no-index", dest="no_index", action="store_true")
    # -p/--show-function prints the enclosing function line ('='); -W/--function-
    # context shows the whole enclosing function (grep.c funcname/funcbody).
    ap.add_argument("-p", "--show-function", dest="show_function", action="store_true")
    ap.add_argument("-W", "--function-context", dest="function_context", action="store_true")
    # Normalize attached short-option values (-A2, -B3, -C1, -m5, -e<pat>) into
    # the "-X value" form argparse expects.
    norm_argv: list[str] = []
    after_dd = False
    for a in argv:
        if after_dd or a == "--":
            if a == "--":
                after_dd = True
            norm_argv.append(a)
            continue
        if (len(a) > 2 and a[0] == "-" and a[1] in "ABCme" and a[2] != "-"
                and not a.startswith("--")):
            norm_argv.append(a[:2])
            norm_argv.append(a[2:])
        else:
            norm_argv.append(a)
    # Boolean grep expressions (--and/--or/--not and grouping with ( )): parse
    # and validate the way grep.c does. A misplaced operator is fatal; a valid
    # expression yields a tree evaluated per line.
    bkind = _grep_parse_bool_expr(norm_argv)
    bool_tree = None
    if bkind[0] == "error":
        return bkind[1]
    if bkind[0] == "tree":
        bool_tree = bkind[1]
        # Strip the boolean operator/paren tokens before argparse sees them.
        norm_argv = [t for t in norm_argv if t not in ("--and", "--or", "--not", "(", ")")]

    args, rest = ap.parse_known_args(norm_argv)
    # -P with no PCRE support is fatal (this build is not linked with libpcre).
    if args.perl:
        _err("fatal: cannot use Perl-compatible regexes when not compiled with USE_LIBPCRE")
        return 128
    # -C<n> sets both before/after; explicit -A/-B override that side.
    before = args.before or args.context
    after = args.after or args.context
    # --no-index searches the filesystem and does not require a repository.
    repo = None if args.no_index else _repo()
    # --exclude-standard / --untracked are only valid with --no-index or
    # --untracked; on tracked contents git dies.
    if args.exclude_standard and not (args.no_index or args.untracked):
        _err("fatal: --[no-]exclude-standard cannot be used for tracked contents")
        return 128

    paths: list[str] = []
    if "--" in rest:
        idx = rest.index("--")
        pre, paths = rest[:idx], rest[idx + 1:]
    else:
        pre = rest
    # With explicit -e patterns, every leftover positional is a rev or path; the
    # first leftover is only the pattern when no -e was given.
    pattern_list = list(args.patterns)
    rev_args: list[str] = []
    leftover = list(pre)
    if not pattern_list:
        if not leftover:
            _err("fatal: no pattern given")
            return 128
        pattern_list = [leftover.pop(0)]
    # After the pattern(s), a positional resolving to a rev is a tree to search;
    # anything else is a pathspec (git's heuristic without an explicit --).
    for tok in leftover:
        if repo is not None and refs_mod.rev_parse(repo, tok):
            rev_args.append(tok)
        else:
            paths.append(tok)

    flags = re.IGNORECASE if args.ignore_case else 0
    # Pattern-type selection (grep.c): -F fixed, -E ERE, otherwise (or -G) BRE.
    # ERE maps directly onto Python's regex engine; BRE needs translation.
    compiled = []
    for p in pattern_list:
        if args.fixed:
            needle = re.escape(p)
        elif args.extended and not args.basic:
            needle = p
        else:
            needle = _grep_bre_to_python(p)
        if args.word_regexp:
            needle = r"\b(?:" + needle + r")\b"
        compiled.append(re.compile(needle, flags))

    def _compile_atom(s: str):
        if args.fixed:
            needle = re.escape(s)
        elif args.extended and not args.basic:
            needle = s
        else:
            needle = _grep_bre_to_python(s)
        if args.word_regexp:
            needle = r"\b(?:" + needle + r")\b"
        return re.compile(needle, flags)

    atom_cache: dict[str, "re.Pattern"] = {}

    def _eval_tree(node, line: str) -> bool:
        kind = node[0]
        if kind == "atom":
            pat = atom_cache.get(node[1])
            if pat is None:
                pat = atom_cache[node[1]] = _compile_atom(node[1])
            return pat.search(line) is not None
        if kind == "not":
            return not _eval_tree(node[1], line)
        if kind == "and":
            return _eval_tree(node[1], line) and _eval_tree(node[2], line)
        if kind == "or":
            return _eval_tree(node[1], line) or _eval_tree(node[2], line)
        return False

    def line_matches(line: str) -> bool:
        if bool_tree is not None:
            m = _eval_tree(bool_tree, line)
        else:
            m = any(pat.search(line) for pat in compiled)
        return m != args.invert

    def iter_match_spans(line: str):
        # Yield (start, end) of every match across all patterns, left-to-right,
        # for -o / --column (git scans all patterns and reports leftmost).
        spans = []
        for pat in compiled:
            for m in pat.finditer(line):
                if m.end() > m.start():
                    spans.append((m.start(), m.end()))
        spans.sort()
        return spans

    def want(path: str) -> bool:
        return not paths or any(path == p or path.startswith(p.rstrip("/") + "/") for p in paths)

    # Resolve the filename display flag: default on, -h off, -H on (last/strongest
    # mirrors git's NEGBIT/BIT — -H always shows even after -h).
    show_name = True
    for tok in argv:
        if tok == "--":
            break
        if tok.startswith("-") and not tok.startswith("--") and len(tok) > 1:
            if "H" in tok[1:]:
                show_name = True
            elif "h" in tok[1:]:
                show_name = False
    name_only = args.name_only
    unmatch_name_only = args.unmatch_name_only
    # With -z/--null every header separator (filename, line-number, column) is a
    # NUL instead of ':' (grep.c output_sep); line/count text keeps its '\n'.
    sep = "\0" if args.nul else ":"

    rc = 1
    out: list[str] = []  # already-terminated output fragments

    # --heading prints the filename once on its own line; --break separates
    # files' output with a blank line. They track cross-file state.
    shown_any_file = [False]

    def _line_header(disp: str, i: int, line: str, ctx: bool) -> str:
        s = sep if not ctx else ("\0" if args.nul else "-")
        prefix = ""
        if show_name and not args.heading:
            prefix += disp + s
        if args.line_number:
            prefix += f"{i}{s}"
        if args.columnnum and not ctx:
            spans = iter_match_spans(line)
            col = (spans[0][0] + 1) if spans else 1
            prefix += f"{col}{s}"
        return prefix

    def emit(disp: str, text: str) -> None:
        nonlocal rc
        cnt = 0
        any_m = False
        lines = text.split("\n")
        # A trailing newline yields a final empty element git doesn't scan.
        if text.endswith("\n"):
            lines = lines[:-1]
        matched_idx = [i for i, ln in enumerate(lines) if line_matches(ln)]
        # --all-match: a file is only reported when every -e pattern matched it.
        if args.all_match and compiled and not args.invert:
            if not all(any(pat.search(ln) for ln in lines) for pat in compiled):
                matched_idx = []
        any_m = bool(matched_idx)

        # Counting / name-only / quiet modes don't print individual lines.
        name_term = "\0" if args.nul else "\n"
        if unmatch_name_only:
            if not any_m:
                rc = 0
                if not args.quiet:
                    out.append(disp + name_term)
            return
        if name_only:
            if any_m:
                rc = 0
                if not args.quiet:
                    out.append(disp + name_term)
            return
        if args.quiet:
            if any_m:
                rc = 0
            return
        if args.count:
            if args.only_matching:
                cnt = sum(len(iter_match_spans(lines[i])) for i in matched_idx)
            else:
                cnt = len(matched_idx)
            if cnt:
                rc = 0
                row = (disp + sep) if show_name else ""
                out.append(f"{row}{cnt}\n")
            return

        if not matched_idx:
            return
        # --max-count limits matches shown per file.
        if args.max_count is not None and args.max_count >= 0:
            matched_idx = matched_idx[:args.max_count]
        if not matched_idx:
            return
        rc = 0

        # Build the set of context line indices, grouped into contiguous hunks
        # so '--' separates non-adjacent groups (grep.c show_line hunk marks).
        wanted: dict[int, bool] = {}  # idx -> is_match
        for mi in matched_idx:
            for j in range(max(0, mi - before), min(len(lines), mi + after + 1)):
                wanted.setdefault(j, False)
            wanted[mi] = True

        # -p (show_function) / -W (function-context): a funcname line is one whose
        # first character is alpha / '_' / '$' (grep.c match_funcname's default,
        # no userdiff driver). funcname_lines maps a shown idx -> True for the '='
        # sign; for -W the whole enclosing function body is added as context.
        funcname_lines: set[int] = set()
        if args.show_function or args.function_context:
            def _is_funcname(i: int) -> bool:
                ln = lines[i]
                return bool(ln) and (ln[0].isalpha() or ln[0] in "_$")
            for mi in list(matched_idx):
                # nearest preceding funcname line
                fn = None
                k = mi - 1 if not _is_funcname(mi) else mi
                while k >= 0:
                    if _is_funcname(k):
                        fn = k
                        break
                    k -= 1
                if fn is None:
                    continue
                if args.function_context:
                    # body runs from the funcname line to the line before the next
                    # funcname line (or EOF).
                    end = fn + 1
                    while end < len(lines) and not _is_funcname(end):
                        end += 1
                    for j in range(fn, end):
                        wanted.setdefault(j, False)
                else:
                    wanted.setdefault(fn, False)
                funcname_lines.add(fn)
        ordered = sorted(wanted)

        if args.file_break and shown_any_file[0]:
            out.append("\n")
        # '--' hunk separator appears whenever pre/post-context or funcbody (-W)
        # is active (grep.c: pre_context || post_context || funcbody), between
        # non-adjacent hunks within a file and between different files. -p alone
        # (funcname, not funcbody) never emits a hunk mark. --break uses a blank
        # line between files instead.
        ctx_active = bool(before or after or args.function_context)
        if ctx_active and shown_any_file[0] and not args.file_break:
            out.append("--\n")
        if args.heading:
            out.append(disp + "\n")
        shown_any_file[0] = True

        prev = None
        for j in ordered:
            is_match = wanted[j]
            if ctx_active and prev is not None and j > prev + 1:
                out.append("--\n")
            prev = j
            if args.only_matching and is_match:
                for (st, en) in iter_match_spans(lines[j]):
                    prefix = ""
                    if show_name and not args.heading:
                        prefix += disp + sep
                    if args.line_number:
                        prefix += f"{j + 1}{sep}"
                    if args.columnnum:
                        prefix += f"{st + 1}{sep}"
                    out.append(prefix + lines[j][st:en] + "\n")
            elif j in funcname_lines and not is_match:
                # funcname line: '=' separator for both the filename and lineno.
                eq = "\0" if args.nul else "="
                prefix = ""
                if show_name and not args.heading:
                    prefix += disp + eq
                if args.line_number:
                    prefix += f"{j + 1}{eq}"
                out.append(prefix + lines[j] + "\n")
            else:
                out.append(_line_header(disp, j + 1, lines[j], ctx=not is_match) + lines[j] + "\n")

    from .index import read_index
    files: list[tuple[str, str]] = []  # (display, text)
    if args.no_index:
        # --no-index: walk the filesystem (cwd, or the given pathspecs) directly,
        # skipping the .git directory. Names are shown relative to the cwd.
        roots = paths if paths else ["."]
        collected: list[str] = []
        for root in roots:
            if os.path.isfile(root):
                collected.append(root)
            elif os.path.isdir(root):
                for dp, dns, fns in os.walk(root):
                    dns[:] = [d for d in dns if d != ".git"]
                    dns.sort()
                    for fn in sorted(fns):
                        fp = os.path.join(dp, fn)
                        rel = os.path.relpath(fp, ".")
                        collected.append(rel.replace(os.sep, "/"))
        for disp in collected:
            try:
                with open(disp, "rb") as fh:
                    data = fh.read()
            except OSError:
                continue
            if b"\x00" in data[:8000]:
                continue  # binary files are skipped without -a
            files.append((disp, data.decode("utf-8", errors="replace")))
    elif rev_args:
        for rv in rev_args:
            s = refs_mod.rev_parse(repo, rv)
            if not s:
                continue
            tree = refs_mod._peel_to_type(repo, s, "tree") or s
            for path, _mode, bsha in sorted(workdir.iter_tree_files(repo, tree)):
                if not want(path):
                    continue
                try:
                    text = objs.read_object(repo, bsha)[1].decode("utf-8", errors="replace")
                except Exception:
                    continue
                files.append((f"{rv}:{path}", text))
    else:
        for e in read_index(repo).entries:
            if not want(e.path):
                continue
            if args.cached:
                try:
                    text = objs.read_object(repo, e.sha)[1].decode("utf-8", errors="replace")
                except Exception:
                    continue
            else:
                full = repo.path / e.path
                if not full.exists():
                    continue
                text = full.read_text(encoding="utf-8", errors="replace")
            files.append((e.path, text))

    for disp, text in files:
        emit(disp, text)
        if args.quiet and rc == 0:
            return 0

    # Fragments are already terminated (line/count with '\n', names per -z).
    for frag in out:
        sys.stdout.write(frag)
    return rc


def _show_branch_name_commits(repo: Repository, ordered: list[str],
                              revs: list[str], ref_names: list[str]) -> dict[str, tuple[str, int]]:
    """Port of show-branch.c:name_commits — assign each commit a (head_name,
    generation) so the matrix can render [name], [name^], [name~N], [name^N]."""
    names: dict[str, tuple[str, int]] = {}

    def parents_of(s):
        info = _commit_tree_parents(repo, s)
        return list(info[1]) if info else []

    # 1) name the given tips (first matching rev wins).
    for s in ordered:
        if s in names:
            continue
        for i, r in enumerate(revs):
            if r == s:
                names[s] = (ref_names[i], 0)
                break

    def name_parent(c, p):
        cn = names.get(c)
        if cn is None:
            return False
        pn = names.get(p)
        if pn is None or cn[1] + 1 < pn[1]:
            names[p] = (cn[0], cn[1] + 1)
            return True
        return False

    def name_first_parent_chain(c):
        i = 0
        while c is not None:
            if c not in names:
                break
            ps = parents_of(c)
            if not ps:
                break
            p = ps[0]
            if p not in names:
                name_parent(c, p)
                i += 1
            else:
                break
            c = p
        return i

    # 2) first-parent ancestry chains.
    while True:
        i = 0
        for s in ordered:
            i += name_first_parent_chain(s)
        if not i:
            break

    # 3) remaining (non-first-parent / merge) parents.
    def disp(n):
        head, gen = n
        if gen == 0:
            return head
        if gen == 1:
            return head + "^"
        return f"{head}~{gen}"

    while True:
        i = 0
        for s in ordered:
            n = names.get(s)
            if n is None:
                continue
            nth = 0
            for p in parents_of(s):
                nth += 1
                if p in names:
                    continue
                newname = disp(n)
                newname += "^" if nth == 1 else f"^{nth}"
                names[p] = (newname, 0)
                i += 1
                name_first_parent_chain(p)
        if not i:
            break
    return names


def cmd_show_branch(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit show-branch", add_help=False)
    ap.add_argument("-a", "--all", action="store_true")
    ap.add_argument("-r", "--remotes", action="store_true")
    ap.add_argument("--sparse", action="store_true")
    ap.add_argument("--merge-base", dest="merge_base", action="store_true")
    ap.add_argument("--independent", action="store_true")
    ap.add_argument("--topo-order", dest="topo_order", action="store_true")
    ap.add_argument("--date-order", dest="date_order", action="store_true")
    ap.add_argument("--current", action="store_true")
    ap.add_argument("--topics", action="store_true")
    ap.add_argument("--list", action="store_true")
    ap.add_argument("--more", type=int, default=0)
    ap.add_argument("--name", dest="name", action="store_true")
    ap.add_argument("--no-name", dest="no_name", action="store_true")
    ap.add_argument("--sha1-name", dest="sha1_name", action="store_true")
    ap.add_argument("--color", nargs="?", const="always", default="never")
    ap.add_argument("--no-color", dest="no_color", action="store_true")
    ap.add_argument("revs", nargs="*")
    # `--reflog[=<n>]`/`-g[<n>]` only takes a value when attached; a bare flag
    # leaves the following token as the positional <ref>. argparse's nargs="?"
    # would wrongly consume that token, so pull the option out of argv first.
    # `--color` / `--more` similarly take only an attached value.
    reflog_val = None
    rest_argv = []
    for a in argv:
        if a in ("--reflog", "-g"):
            reflog_val = ""
        elif a.startswith("--reflog="):
            reflog_val = a.split("=", 1)[1]
        elif a.startswith("-g") and len(a) > 2 and a[2:].isdigit():
            reflog_val = a[2:]
        elif a == "--color":
            # OPT__COLOR defval is "always": bare --color = color on always.
            rest_argv.append("--color=always")
        elif a == "--more":
            rest_argv.append("--more=1")
        else:
            rest_argv.append(a)
    args = ap.parse_args(rest_argv)
    color_on = (not args.no_color) and (
        args.color == "always" or (args.color == "auto" and sys.stdout.isatty()))
    # column-indexed marker palette (C Git's column_colors_ansi).
    _SB_COLORS = ["\033[31m", "\033[32m", "\033[33m", "\033[34m", "\033[35m", "\033[36m"]

    def _col(ch: str, i: int) -> str:
        if not color_on or ch == " ":
            return ch
        return f"{_SB_COLORS[i % len(_SB_COLORS)]}{ch}\033[m"
    repo = _repo()
    head_sym, head_oid = refs_mod.read_head(repo)
    cur = head_sym[len("refs/heads/"):] if head_sym and head_sym.startswith("refs/heads/") else None

    # Determine the revs (and their display names). Explicit args win; otherwise
    # default to all local heads (and remotes with -r/--all), in ref name order.
    ref_names: list[str] = []
    revs: list[str] = []
    reflog_msgs: list[str] = []  # only populated in --reflog mode
    if reflog_val is not None:
        # --reflog[=<n>] [<ref>]: each of the ref's last <n> reflog entries
        # (default 4) becomes a column "<ref>@{i}".
        count = int(reflog_val) if reflog_val else 4
        if args.revs:
            disp = args.revs[0]
            full = refs_mod.dwim_full_name(repo, disp) or f"refs/heads/{disp}"
        else:
            # Default: HEAD resolved to the full branch ref it points at.
            head_sym2, _ = refs_mod.read_head(repo)
            full = head_sym2 or "HEAD"
            disp = full
        from . import reflog as _rl
        entries = _rl.read(repo, full if full == "HEAD" else
                           (full if full.startswith("refs/") else f"refs/heads/{full}"))
        for i, (_old, new, ident, msg) in enumerate(reversed(entries)):
            if i >= count:
                break
            ref_names.append(f"{disp}@{{{i}}}")
            revs.append(new)
            reldate = _format_date(ident, "relative")
            reflog_msgs.append(f"({reldate}) {msg}")
        if not revs:
            _err("No revs to be shown.")
            return 0
    elif args.revs:
        for rv in args.revs:
            s = refs_mod.rev_parse(repo, rv + "^{commit}") or refs_mod.rev_parse(repo, rv)
            if not s:
                _err(f"fatal: '{rv}' is not a valid ref.")
                return 128
            ref_names.append(rv)
            revs.append(s)
    else:
        if not args.remotes or args.all:
            for b in refs_mod.list_branches(repo):
                s = refs_mod.read_ref(repo, f"refs/heads/{b}")
                if s:
                    ref_names.append(b)
                    revs.append(s)
        if args.remotes or args.all:
            for b in _remote_branches(repo):
                s = refs_mod.read_ref(repo, f"refs/remotes/{b}")
                if s:
                    ref_names.append(b)
                    revs.append(s)
    # --current appends the current branch as an extra column when not already
    # listed (e.g. alongside explicit revs).
    if args.current and reflog_val is None and cur and cur not in ref_names:
        s = refs_mod.read_ref(repo, f"refs/heads/{cur}")
        if s:
            ref_names.append(cur)
            revs.append(s)
    if not revs:
        _err("No revs to be shown.")
        return 0
    num_rev = len(revs)

    def _sb_subject(s):
        try:
            c = objs.parse_commit(objs.read_object(repo, s)[1])
            return c.message.splitlines()[0] if c.message.strip() else ""
        except (KeyError, IndexError):
            return ""

    # --list: just the ref headers (current marked with '*'), no matrix.
    if args.list:
        for i in range(num_rev):
            is_head = (reflog_val is None) and ref_names[i] == cur and revs[i] == head_oid
            mark = _col("*", i) if is_head else " "
            sub_i = reflog_msgs[i] if reflog_val is not None else _sb_subject(revs[i])
            _print(f"{mark} [{ref_names[i]}] {sub_i}")
        return 0

    def subject(s):
        try:
            c = objs.parse_commit(objs.read_object(repo, s)[1])
            return c.message.splitlines()[0] if c.message.strip() else ""
        except (KeyError, IndexError):
            return ""

    def parents_of(s):
        info = _commit_tree_parents(repo, s)
        return list(info[1]) if info else []

    # Reachability mask: bit i set when rev[i]'s tip can reach the commit.
    reach: list[set[str]] = []
    for tip in revs:
        seen: set[str] = set()
        stack = [tip]
        while stack:
            x = stack.pop()
            if x in seen:
                continue
            seen.add(x)
            stack.extend(parents_of(x))
        reach.append(seen)

    def mask(s):
        m = 0
        for i, rs in enumerate(reach):
            if s in rs:
                m |= (1 << i)
        return m

    all_mask = (1 << num_rev) - 1

    # --merge-base: print the common ancestor(s) of all the revs (octopus
    # reduction), one full oid per line — like `git merge-base`.
    if args.merge_base:
        from . import merge as _m
        bases = [revs[0]]
        for other in revs[1:]:
            merged: list[str] = []
            for b in bases:
                merged.extend(_m.merge_bases(repo, b, other))
            seen_b: set[str] = set()
            bases = [x for x in merged if not (x in seen_b or seen_b.add(x))]
        if not bases:
            return 1
        for b in bases:
            _print(b)
        return 0

    # --independent: print the tips not reachable from any other tip
    # (builtin/show-branch.c show_independent). rev_mask[i] snapshots a tip's
    # bits including every other tip that names the SAME commit, so duplicate
    # tips collapse to one line: the first i prints and marks the commit
    # UNINTERESTING, and later identical tips no longer compare equal.
    if args.independent:
        # rev_mask[i] = OR of bits j whose tip is the same commit as rev[i].
        rev_mask = []
        for i in range(num_rev):
            m = 0
            for j in range(num_rev):
                if revs[j] == revs[i]:
                    m |= (1 << j)
            rev_mask.append(m)
        uninteresting: set[str] = set()
        for i in range(num_rev):
            commit = revs[i]
            if commit in uninteresting:
                continue
            if mask(commit) == rev_mask[i]:
                _print(commit)
            uninteresting.add(commit)
        return 0

    # Build the reachable union in rev-input order, then order it like git's
    # topo sort (REV_SORT_IN_GRAPH_ORDER over the date-stable seen list).
    # Build git's `seen` list exactly (builtin/show-branch.c): mark_seen
    # PREPENDS, so the list head is the most-recently-seen commit. Tips are
    # seeded in command-line order (duplicates collapse: only the first occurrence
    # of a given commit is inserted), then a date-priority BFS over parents
    # inserts the rest. This `seen` order drives both the topo sort's tie-breaking
    # and the first-parent naming pass.
    import heapq as _heapq
    seen_list: list[str] = []
    seen_set: set[str] = set()

    def _sb_mark_seen(c: str) -> bool:
        if c not in seen_set:
            seen_set.add(c)
            seen_list.insert(0, c)
            return True
        return False

    _sb_heap: list[tuple] = []
    _sb_ctr = 0
    _sb_queued: set[str] = set()
    for tip in revs:
        if _sb_mark_seen(tip) and tip not in _sb_queued:
            _heapq.heappush(_sb_heap, (-_commit_date(repo, tip), _sb_ctr, tip))
            _sb_queued.add(tip)
            _sb_ctr += 1
    while _sb_heap:
        _d, _c, commit = _heapq.heappop(_sb_heap)
        for p in parents_of(commit):
            _sb_mark_seen(p)
            if p not in _sb_queued:
                _heapq.heappush(_sb_heap, (-_commit_date(repo, p), _sb_ctr, p))
                _sb_queued.add(p)
                _sb_ctr += 1
    # commit_list_sort_by_date (stable, newer first) then sort_in_topological_order.
    union = sorted(seen_list, key=lambda c: -_commit_date(repo, c))
    ordered = _topo_order(repo, union, by_date=args.date_order)

    names = _show_branch_name_commits(repo, ordered, revs, ref_names)

    def disp_name(s):
        if args.sha1_name:
            return s[:7]
        n = names.get(s)
        if not n:
            return s[:7]
        head, gen = n
        if gen == 0:
            return head
        if gen == 1:
            return head + "^"
        return f"{head}~{gen}"

    def body(s):
        # --no-name suppresses the "[<name>] " prefix, leaving the bare subject.
        return subject(s) if args.no_name else f"[{disp_name(s)}] {subject(s)}"

    # head_at: column of the current branch (used for the '*' marker).
    head_at = -1
    if num_rev > 1:
        for i in range(num_rev):
            is_head = (reflog_val is None) and ref_names[i] == cur and revs[i] == head_oid
            mark = _col("*" if is_head else "!", i)
            line = " " * i + mark
            text = reflog_msgs[i] if reflog_val is not None else subject(revs[i])
            _print(f"{line} [{ref_names[i]}] {text}")
            if is_head:
                head_at = i
        _print("-" * num_rev)

    def omit_in_dense(s, m):
        # Skip a merge reachable from only one tip (and not itself a tip).
        if s in revs:
            return False
        if len(parents_of(s)) > 1 and bin(m).count("1") == 1:
            return True
        return False

    shown_merge_point = False
    extra = 0  # commits emitted past the first merge point (for --more)
    for s in ordered:
        m = mask(s)
        is_merge_point = (m == all_mask)
        is_merge = len(parents_of(s)) > 1
        # --topics: omit commits that are on the first branch but not a common
        # point (i.e. reachable from rev[0] yet not from every rev).
        if args.topics and (m & 1) and m != all_mask:
            continue
        if num_rev > 1 and not args.sparse and is_merge and omit_in_dense(s, m):
            continue
        # Stop after the merge point unless --more=<n> asks for n more rows.
        if shown_merge_point:
            if extra >= args.more:
                break
            extra += 1
        if num_rev > 1:
            marks = []
            for i in range(num_rev):
                if not (m & (1 << i)):
                    marks.append(" ")
                elif is_merge:
                    marks.append(_col("-", i))
                elif i == head_at:
                    marks.append(_col("*", i))
                else:
                    marks.append(_col("+", i))
            _print(f"{''.join(marks)} {body(s)}")
        else:
            _print(body(s))
        if is_merge_point and not shown_merge_point:
            shown_merge_point = True
            if args.more <= 0:
                break
    return 0


_WHATCHANGED_DEPRECATION = (
    "'git whatchanged' is nominated for removal.\n"
    "\n"
    "hint: You can replace 'git whatchanged <opts>' with:\n"
    "hint:\tgit log <opts> --raw --no-merges\n"
    "hint: Or make an alias:\n"
    "hint:\tgit config set --global alias.whatchanged 'log --raw --no-merges'\n"
    "\n"
    "If you still use this command, here's what you can do:\n"
    "\n"
    "- read https://git-scm.com/docs/BreakingChanges.html\n"
    "- check if anyone has discussed this on the mailing\n"
    "  list and if they came up with something that can\n"
    "  help you: https://lore.kernel.org/git/?q=git%20whatchanged\n"
    "- send an email to <git@vger.kernel.org> to let us\n"
    "  know that you still use this command and were unable\n"
    "  to determine a suitable replacement\n"
    "\n"
)


def cmd_whatchanged(argv: list[str]) -> int:
    # As of Git 2.54 this command refuses to run without an explicit opt-in.
    if "--i-still-use-this" not in argv:
        sys.stderr.write(_WHATCHANGED_DEPRECATION)
        _err("fatal: refusing to run without --i-still-use-this")
        return 128
    argv = [a for a in argv if a != "--i-still-use-this"]
    # 'whatchanged' is 'log --no-merges' whose default diff format is --raw
    # rather than a patch (this is exactly the suggested replacement command).
    if not any(a in ("-p", "--patch", "--stat", "--raw", "--name-only", "--name-status") for a in argv):
        argv = ["--raw", *argv]
    return cmd_log(["--no-merges", *argv])


_MKTAG_USAGE = (
    "usage: git mktag\n"
    "\n"
    "    --[no-]strict         enable more strict checking\n"
    "\n"
)


# Final fsck severity (after FSCK_OPTIONS_STRICT WARN->ERROR promotion and the
# report() FATAL->ERROR / INFO->WARN mapping, plus mktag's explicit
# extraHeaderEntry=WARN). "warn" ids become errors under mktag's default
# --strict, warnings under --no-strict; "error" ids always fail.
_MKTAG_WARN_IDS = {"badTagName", "missingTaggerEntry", "extraHeaderEntry"}


class _MktagFsckFail(Exception):
    pass


def _fsck_ident(data: bytes, pos: int, report) -> int:
    """Port of fsck.c:fsck_ident. `pos` points at the start of the ident value
    (just past "tagger "). Returns the index just past the ident line, or raises
    _MktagFsckFail if report() signalled a hard error."""
    end = len(data)
    nl = data.find(b"\n", pos)
    # verify_headers guarantees a newline exists.
    after = nl + 1
    p = pos
    if p < end and data[p:p + 1] == b"<":
        report("missingNameBeforeEmail",
               "invalid author/committer line - missing space before email")
        return after
    while True:
        if p >= end or data[p:p + 1] == b"\n":
            report("missingEmail", "invalid author/committer line - missing email")
            return after
        if data[p:p + 1] == b">":
            report("badName", "invalid author/committer line - bad name")
            return after
        if data[p:p + 1] == b"<":
            break
        p += 1
    if data[p - 1:p] != b" ":
        report("missingSpaceBeforeEmail",
               "invalid author/committer line - missing space before email")
        return after
    p += 1
    while True:
        if p >= end or data[p:p + 1] in (b"<", b"\n"):
            report("badEmail", "invalid author/committer line - bad email")
            return after
        if data[p:p + 1] == b">":
            break
        p += 1
    p += 1
    if data[p:p + 1] != b" ":
        report("missingSpaceBeforeDate",
               "invalid author/committer line - missing space before date")
        return after
    p += 1
    while data[p:p + 1] in (b" ", b"\t"):
        p += 1
    if not (p < end and data[p:p + 1].isdigit()):
        report("badDate", "invalid author/committer line - bad date")
        return after
    if data[p:p + 1] == b"0" and data[p + 1:p + 2] != b" ":
        report("zeroPaddedDate", "invalid author/committer line - zero-padded date")
        return after
    while p < end and data[p:p + 1].isdigit():
        p += 1
    if data[p:p + 1] != b" ":
        report("badDate", "invalid author/committer line - bad date")
        return after
    p += 1
    if (data[p:p + 1] not in (b"+", b"-")
            or not data[p + 1:p + 2].isdigit()
            or not data[p + 2:p + 3].isdigit()
            or not data[p + 3:p + 4].isdigit()
            or not data[p + 4:p + 5].isdigit()
            or data[p + 5:p + 6] != b"\n"):
        report("badTimezone", "invalid author/committer line - bad time zone")
        return after
    p += 6
    return p


def _fsck_tag_standalone(data: bytes, report):
    """Port of fsck.c:fsck_tag_standalone. Calls report(id, msg) on each
    problem (report decides whether to raise _MktagFsckFail). Returns
    (tagged_oid_hex, tagged_type) for the verify_object_in_tag step."""
    size = len(data)
    # verify_headers: find "\n\n" or a NUL; else require a trailing newline.
    ok = False
    for i in range(size):
        b = data[i]
        if b == 0:
            report("nulInHeader", "unterminated header: NUL at offset %d" % i)
            return None, None
        if b == 0x0A and i + 1 < size and data[i + 1] == 0x0A:
            ok = True
            break
    if not ok:
        if not (size and data[size - 1] == 0x0A):
            report("unterminatedHeader", "unterminated header")
            return None, None

    pos = 0
    if not (pos < size and data[pos:].startswith(b"object ")):
        report("missingObject", "invalid format - expected 'object' line")
        return None, None
    pos += len("object ")
    nl = data.find(b"\n", pos)
    oid_field = data[pos:nl] if nl != -1 else data[pos:]
    if (len(oid_field) != 40
            or any(c not in b"0123456789abcdef" for c in oid_field)):
        report("badObjectSha1", "invalid 'object' line format - bad sha1")
    tagged_oid = oid_field.decode("ascii", "replace")
    pos = nl + 1

    if not (pos < size and data[pos:].startswith(b"type ")):
        report("missingTypeEntry", "invalid format - expected 'type' line")
        return None, None
    pos += len("type ")
    eol = data.find(b"\n", pos)
    if eol == -1:
        report("missingType", "invalid format - unexpected end after 'type' line")
        return None, None
    type_val = data[pos:eol].decode("ascii", "replace")
    if type_val not in ("commit", "tree", "blob", "tag"):
        report("badType", "invalid 'type' value")
    pos = eol + 1

    if not (pos < size and data[pos:].startswith(b"tag ")):
        report("missingTagEntry", "invalid format - expected 'tag' line")
        return None, None
    pos += len("tag ")
    eol = data.find(b"\n", pos)
    if eol == -1:
        report("missingTag", "invalid format - unexpected end after 'type' line")
        return None, None
    tag_name = data[pos:eol].decode("utf-8", "replace")
    if _check_refname_invalid("refs/tags/" + tag_name):
        report("badTagName", "invalid 'tag' name: %s" % tag_name)
    pos = eol + 1

    if not (pos < size and data[pos:].startswith(b"tagger ")):
        report("missingTaggerEntry", "invalid format - expected 'tagger' line")
    else:
        pos = _fsck_ident(data, pos + len("tagger "), report)

    # gpgsig / gpgsig-sha256 headers and their continuation lines.
    for sig in (b"gpgsig ", b"gpgsig-sha256 "):
        if pos < size and data[pos:].startswith(sig):
            eol = data.find(b"\n", pos)
            if eol == -1:
                report("badGpgsig", "invalid format - unexpected end after "
                       "'gpgsig' or 'gpgsig-sha256' line")
                return tagged_oid, type_val
            pos = eol + 1
            while pos < size and data[pos:pos + 1] == b" ":
                eol = data.find(b"\n", pos)
                if eol == -1:
                    report("badHeaderContinuation",
                           "invalid format - unexpected end in 'gpgsig' or "
                           "'gpgsig-sha256' continuation line")
                    return tagged_oid, type_val
                pos = eol + 1
            break

    if pos < size and not data[pos:].startswith(b"\n"):
        report("extraHeaderEntry", "invalid format - extra header(s) after 'tagger'")
    return tagged_oid, type_val


def cmd_mktag(argv: list[str]) -> int:
    option_strict = True
    for a in argv:
        if a in ("-h", "--help"):
            sys.stdout.write(_MKTAG_USAGE)
            return 129
        elif a == "--strict":
            option_strict = True
        elif a == "--no-strict":
            option_strict = False
        elif a.startswith("-") and a != "-":
            # parse-options: unknown option -> error + usage (rc 129).
            disp = a[2:] if a.startswith("--") else a[1:]
            kind = "option" if a.startswith("--") else "switch"
            _err("error: unknown %s `%s'" % (kind, disp))
            sys.stderr.write(_MKTAG_USAGE)
            return 129
        # bare positionals are ignored by cmd_mktag (it never reads argv).
    repo = _repo()
    data = _read_stdin_bytes()

    def report(msg_id: str, msg: str) -> None:
        is_warn = msg_id in _MKTAG_WARN_IDS
        if is_warn and not option_strict:
            _err("warning: tag input does not pass fsck: %s: %s" % (msg_id, msg))
            return
        _err("error: tag input does not pass fsck: %s: %s" % (msg_id, msg))
        raise _MktagFsckFail()

    try:
        tagged_oid, tagged_type = _fsck_tag_standalone(data, report)
    except _MktagFsckFail:
        _err("fatal: tag on stdin did not pass our strict fsck check")
        return 128

    # verify_object_in_tag: the tagged object must exist and have the named type.
    try:
        actual_type = objs.read_object(repo, tagged_oid)[0]
    except (KeyError, ValueError, FileNotFoundError):
        actual_type = None
    if actual_type is None:
        _err("fatal: could not read tagged object '%s'" % tagged_oid)
        return 128
    if actual_type != tagged_type:
        _err("fatal: object '%s' tagged as '%s', but is a '%s' type"
             % (tagged_oid, tagged_type, actual_type))
        return 128

    sha = objs.write_object(repo, "tag", data)
    _print(sha)
    return 0


def cmd_name_rev(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit name-rev", add_help=False)
    ap.add_argument("--all", action="store_true")
    ap.add_argument("--name-only", dest="name_only", action="store_true")
    ap.add_argument("--tags", action="store_true")
    ap.add_argument("--refs", action="append", default=None)
    ap.add_argument("--exclude", action="append", default=None)
    ap.add_argument("--stdin", action="store_true")
    ap.add_argument("--annotate-stdin", dest="annotate_stdin", action="store_true")
    # OPT_BOOL undefined (default true) + negation; OPT_BOOL always; hidden peel-tag.
    ap.add_argument("--undefined", dest="undefined", action="store_true", default=True)
    ap.add_argument("--no-undefined", dest="undefined", action="store_false")
    ap.add_argument("--always", action="store_true")
    ap.add_argument("--peel-tag", dest="peel_tag", action="store_true")
    ap.add_argument("rev", nargs="*")
    args = ap.parse_args(argv)
    repo = _repo()

    # --refs/--exclude filter which refs may seed tips (name-rev.c name_ref):
    # subpath_matches checks the full refname and each "/"-suffix against the
    # wildmatch pattern.
    import fnmatch as _fnm

    def _subpath_matches(path: str, pat: str) -> int:
        sub = path
        off = 0
        while True:
            if _fnm.fnmatch(sub, pat):
                return off
            idx = sub.find("/")
            if idx < 0:
                return -1
            off += idx + 1
            sub = sub[idx + 1:]

    def _ref_filter_ok(full_refname: str) -> bool:
        if args.exclude:
            for pat in args.exclude:
                if _subpath_matches(full_refname, pat) >= 0:
                    return False
        if args.refs:
            if not any(_subpath_matches(full_refname, pat) >= 0 for pat in args.refs):
                return False
        return True
    graph = _graph_for_repo(repo)
    MERGE_TRAVERSAL_WEIGHT = 65535
    TIME_MAX = 1 << 62

    # Per-commit best name record, porting builtin/name-rev.c:rev_name.
    #   name_for[sha] = (tip_name, taggerdate, generation, distance, from_tag)
    name_for: dict[str, tuple] = {}

    def _eff_distance(distance: int, generation: int) -> int:
        return distance + (MERGE_TRAVERSAL_WEIGHT if generation > 0 else 0)

    def _is_better(cur: tuple, taggerdate: int, generation: int,
                   distance: int, from_tag: int) -> bool:
        # cur = (tip_name, taggerdate, generation, distance, from_tag)
        _cn, c_td, c_gen, c_dist, c_ft = cur
        c_eff = _eff_distance(c_dist, c_gen)
        n_eff = _eff_distance(distance, generation)
        if from_tag and c_ft:
            return c_eff > n_eff
        if c_ft != from_tag:
            return bool(from_tag)
        if c_eff != n_eff:
            return c_eff > n_eff
        if c_td != taggerdate:
            return c_td > taggerdate
        return False

    # Seed the tip table. Annotated tags are peeled to their commit (recorded as
    # deref so an exact match renders "<tag>^0"); taggerdate is the tag's date
    # for annotated tags, else the commit date.
    tips: list[dict] = []
    for tag in refs_mod.list_tags(repo):
        if not _ref_filter_ok(f"refs/tags/{tag}"):
            continue
        raw = refs_mod.read_ref(repo, f"refs/tags/{tag}")
        if not raw:
            continue
        peeled = refs_mod.rev_parse(repo, f"refs/tags/{tag}" + "^{commit}") or raw
        deref = peeled != raw
        taggerdate = None
        if deref:
            try:
                ot, data = objs.read_object(repo, raw)
                if ot == "tag":
                    for line in data.decode("utf-8", "replace").splitlines():
                        if line.startswith("tagger "):
                            parts = line.rsplit(" ", 2)
                            taggerdate = int(parts[-2])
                            break
            except Exception:
                taggerdate = None
        if taggerdate is None:
            taggerdate = _commit_date(repo, peeled)
        tips.append({"label": f"tags/{tag}", "commit": peeled, "deref": deref,
                     "from_tag": 1, "taggerdate": taggerdate})
    if not args.tags:
        for b in refs_mod.list_branches(repo):
            if not _ref_filter_ok(f"refs/heads/{b}"):
                continue
            s = refs_mod.read_ref(repo, f"refs/heads/{b}")
            if s:
                tips.append({"label": b, "commit": s, "deref": False,
                             "from_tag": 0, "taggerdate": _commit_date(repo, s)})

    # name_tips: process better tips first (tags before non-tags; older first)
    # so worse names spread less.
    tips.sort(key=lambda e: (-e["from_tag"], e["taggerdate"]))

    def _name_rev_walk(start: str, tip_name: str, taggerdate: int,
                       from_tag: int, deref: bool) -> None:
        cur = name_for.get(start)
        if cur is not None and not _is_better(cur, taggerdate, 0, 0, from_tag):
            return
        label = f"{tip_name}^0" if deref else tip_name
        name_for[start] = (label, taggerdate, 0, 0, from_tag)
        stack = [start]
        while stack:
            commit = stack.pop()
            cname = name_for[commit]
            base_label, _td, base_gen, base_dist, _ft = cname
            info = _commit_tree_parents(repo, commit, graph)
            if info is None:
                continue
            parents = info[1]
            to_queue = []
            for parent_number, parent in enumerate(parents, start=1):
                if parent_number > 1:
                    generation = 0
                    distance = base_dist + MERGE_TRAVERSAL_WEIGHT
                else:
                    generation = base_gen + 1
                    distance = base_dist + 1
                p_cur = name_for.get(parent)
                if p_cur is not None and not _is_better(
                        p_cur, taggerdate, generation, distance, from_tag):
                    continue
                if parent_number > 1:
                    # get_parent_name: compose from the *current* commit's name,
                    # using its generation, then the parent starts a fresh chain
                    # (generation reset to 0 above).
                    pure = base_label[:-2] if base_label.endswith("^0") else base_label
                    if base_gen > 0:
                        p_label = f"{pure}~{base_gen}^{parent_number}"
                    else:
                        p_label = f"{pure}^{parent_number}"
                else:
                    # First parent inherits the tip_name verbatim.
                    p_label = base_label
                name_for[parent] = (p_label, taggerdate, generation, distance, from_tag)
                to_queue.append(parent)
            for parent in reversed(to_queue):
                stack.append(parent)

    for e in tips:
        _name_rev_walk(e["commit"], e["label"], e["taggerdate"],
                       e["from_tag"], e["deref"])

    def _render(sha: str) -> Optional[str]:
        # Port of name-rev.c:get_rev_name. The stored tip_name carries any "^0"
        # / merge "^N" suffixes; generation is added at display time.
        rec = name_for.get(sha)
        if rec is None:
            return None
        tip_name, _td, generation, _dist, _ft = rec
        if generation == 0:
            return tip_name
        base = tip_name[:-2] if tip_name.endswith("^0") else tip_name
        return f"{base}~{generation}"

    def _display(name: str) -> str:
        # With --name-only, --tags strips the "tags/" prefix from tag names.
        if args.name_only and args.tags and name.startswith("tags/"):
            return name[len("tags/"):]
        return name

    if args.stdin or args.annotate_stdin:
        # Annotate each full oid token on stdin in place with " (<name>)".
        if args.stdin:
            _err("warning: --stdin is deprecated. Please use --annotate-stdin instead, "
                 "which is functionally equivalent.")
            _err("This option will be removed in a future release.")
        import re as _re2

        def _annot(line: str) -> str:
            def repl(m):
                tok = m.group(0)
                s = refs_mod.rev_parse(repo, tok)
                rendered = _render(s) if s else None
                if rendered is not None:
                    return f"{tok} ({_display(rendered)})"
                return tok
            return _re2.sub(r"[0-9a-f]{40}", repl, line)
        for line in sys.stdin:
            sys.stdout.write(_annot(line.rstrip("\n")) + "\n")
        return 0

    if args.all:
        for sha in sorted(name_for):
            rendered = _render(sha)
            if args.name_only:
                _print(_display(rendered))
            else:
                _print(f"{sha} {_display(rendered)}")
        return 0
    rc = 0
    for one in args.rev:
        s = refs_mod.rev_parse(repo, one)
        # builtin/name-rev.c: an arg that resolves to a full oid but whose object
        # is absent yields "Could not get object for ...", while one that cannot
        # be parsed to an oid at all yields "Could not get sha1 for ...". pygit's
        # rev_parse returns a 40-hex string verbatim for an unknown full sha, so
        # distinguish by checking the object exists.
        if not s:
            _err(f"Could not get sha1 for {one}. Skipping.")
            continue
        try:
            objs.read_object(repo, s)
            exists = True
        except Exception:
            exists = False
        if not exists:
            _err(f"Could not get object for {s}. Skipping.")
            continue
        rendered = _render(s)
        if rendered is not None:
            name = rendered
        elif args.undefined:
            name = "undefined"
        elif args.always:
            # find_unique_abbrev fallback (DEFAULT_ABBREV).
            name = s[:7]
        else:
            _err(f"fatal: cannot describe '{s}'")
            return 128
        if args.name_only:
            _print(_display(name))
        else:
            _print(f"{one} {name}")
    return rc


def _var_ident(repo: Optional[Repository], role: str) -> str:
    if repo is not None:
        return objs.build_signature(repo, role)
    env = os.environ
    sys_name, sys_email = objs._system_ident()
    if role == "author":
        name = env.get("GIT_AUTHOR_NAME") or sys_name
        email = env.get("GIT_AUTHOR_EMAIL") or env.get("EMAIL") or sys_email
        date = env.get("GIT_AUTHOR_DATE")
    else:
        name = env.get("GIT_COMMITTER_NAME") or sys_name
        email = env.get("GIT_COMMITTER_EMAIL") or env.get("EMAIL") or sys_email
        date = env.get("GIT_COMMITTER_DATE")
    parsed = objs._parse_date_env(date) if date else None
    if parsed is not None:
        secs, tzmin = parsed
    else:
        secs = int(time.time())
        tzmin = objs._local_tz_minutes(secs)
    return objs.format_signature(name, email, when=secs, tz_minutes=tzmin)


def _git_env_bool(name: str, default: bool) -> bool:
    """Port of config.c:git_env_bool(): parse the env var as a git bool."""
    val = os.environ.get(name)
    if val is None:
        return default
    v = val.strip().lower()
    if v in ("", "0", "false", "no", "off"):
        return False
    if v in ("1", "true", "yes", "on"):
        return True
    try:
        return int(v) != 0
    except ValueError:
        return True


def _xdg_config_home(filename: str) -> Optional[str]:
    """Port of path.c:xdg_config_home_for("git", filename)."""
    config_home = os.environ.get("XDG_CONFIG_HOME")
    if config_home:
        return f"{config_home}/git/{filename}"
    home = os.environ.get("HOME")
    if home:
        return f"{home}/.config/git/{filename}"
    return None


def _var_attr_global(repo) -> Optional[str]:
    # attr.c:git_attr_global_file -> core.attributesFile or xdg("attributes").
    if repo is not None:
        from . import gitconfig
        try:
            cfg = gitconfig.get(repo, "core.attributesFile")
        except Exception:
            cfg = None
        if cfg:
            return os.path.normpath(os.path.expanduser(cfg))
    path = _xdg_config_home("attributes")
    return os.path.normpath(path) if path else None


def _var_config_system(repo) -> Optional[str]:
    # config.c:git_config_system() = !GIT_CONFIG_NOSYSTEM; returns the path only
    # when system config is enabled (else var returns NULL -> rc 1).
    if _git_env_bool("GIT_CONFIG_NOSYSTEM", False):
        return None
    sysc = os.environ.get("GIT_CONFIG_SYSTEM") or "/etc/gitconfig"
    return os.path.normpath(sysc)


def _var_config_global(repo) -> Optional[str]:
    # config.c:git_config_val_global: xdg config then ~/.gitconfig (or
    # GIT_CONFIG_GLOBAL alone), each normalized, joined by '\n' (multivalued).
    gcg = os.environ.get("GIT_CONFIG_GLOBAL")
    parts = []
    if gcg is not None:
        if gcg:
            parts.append(os.path.normpath(gcg))
    else:
        xdg = _xdg_config_home("config")
        if xdg:
            parts.append(os.path.normpath(xdg))
        home = os.environ.get("HOME")
        if home:
            parts.append(os.path.normpath(f"{home}/.gitconfig"))
    return "\n".join(parts) if parts else None


# Logical git vars in builtin/var.c order. Each entry: (name, reader, multivalued).
def _var_readers():
    return [
        ("GIT_COMMITTER_IDENT", lambda r: _var_ident(r, "committer"), False),
        ("GIT_AUTHOR_IDENT", lambda r: _var_ident(r, "author"), False),
        ("GIT_EDITOR", lambda r: (os.environ.get("GIT_EDITOR")
                                  or os.environ.get("VISUAL")
                                  or os.environ.get("EDITOR") or "vi"), False),
        ("GIT_SEQUENCE_EDITOR", lambda r: (os.environ.get("GIT_SEQUENCE_EDITOR")
                                           or _var_value(r, "GIT_EDITOR")), False),
        ("GIT_PAGER", lambda r: (os.environ.get("GIT_PAGER")
                                 or os.environ.get("PAGER") or "less"), False),
        ("GIT_DEFAULT_BRANCH", lambda r: _var_default_branch(r), False),
        ("GIT_SHELL_PATH", lambda r: "/bin/sh", False),
        ("GIT_ATTR_SYSTEM", lambda r: _var_attr_system(r), False),
        ("GIT_ATTR_GLOBAL", lambda r: _var_attr_global(r), False),
        ("GIT_CONFIG_SYSTEM", lambda r: _var_config_system(r), False),
        ("GIT_CONFIG_GLOBAL", lambda r: _var_config_global(r), True),
    ]


def _var_attr_system(repo) -> Optional[str]:
    # attr.c:git_attr_val_system -> system_path(ETC_GITATTRIBUTES) when enabled.
    # The install-prefix path is build-specific; best effort default.
    if _git_env_bool("GIT_ATTR_NOSYSTEM", False):
        return None
    return "/etc/gitattributes"


def _var_default_branch(repo) -> str:
    if repo is not None:
        cp = repo.config()
        if cp.has_section("init"):
            val = cp.get("init", "defaultbranch", fallback=None)
            if val:
                return val
    return "master"


def _var_value(repo: Optional[Repository], name: str) -> Optional[str]:
    for n, reader, _multi in _var_readers():
        if n == name:
            return reader(repo)
    return None


def cmd_var(argv: list[str]) -> int:
    repo = None
    try:
        repo = _repo()
    except Exception:
        pass
    # show_usage_if_asked: -h prints usage to stdout, rc 129.
    if len(argv) == 1 and argv[0] in ("-h", "--help"):
        _print("usage: git var (-l | <variable>)")
        return 129
    if len(argv) != 1:
        _err("usage: git var (-l | <variable>)")
        return 129
    name = argv[0]
    if name == "-l":
        for key, value in _config_list_pairs(repo):
            _print(f"{key}={value}")
        for n, reader, multi in _var_readers():
            val = reader(repo)
            if val is None:
                continue
            if multi and val:
                for piece in val.split("\n"):
                    _print(f"{n}={piece}")
            else:
                _print(f"{n}={val}")
        return 0
    known = {n for n, _r, _m in _var_readers()}
    if name not in known:
        _err("usage: git var (-l | <variable>)")
        return 129
    value = _var_value(repo, name)
    if value is None:
        # A known var whose reader returned NULL -> rc 1, no output.
        return 1
    _print(value)
    return 0


def _read_stdin_bytes() -> bytes:
    """Read all of stdin as bytes, tolerating text-only test doubles that lack
    a ``.buffer`` attribute (some unit tests replace ``sys.stdin``)."""
    buf = getattr(sys.stdin, "buffer", None)
    if buf is not None:
        return buf.read()
    data = sys.stdin.read()
    return data.encode("utf-8") if isinstance(data, str) else data


_STRIPSPACE_USAGE = (
    "usage: git stripspace [-s | --strip-comments]\n"
    "   or: git stripspace [-c | --comment-lines]\n"
    "\n"
    "    -s, --strip-comments  skip and remove all lines starting with comment "
    "character\n"
    "    -c, --comment-lines   prepend comment character and space to each line\n"
    "\n"
)

# isspace() in the C locale: space, \t, \n, \v, \f, \r.
_C_ISSPACE = b" \t\n\x0b\x0c\r"


def _ss_cleanup(line: bytes) -> bytes:
    """Port of strbuf.c:cleanup(): trim trailing isspace() bytes."""
    n = len(line)
    while n and line[n - 1] in _C_ISSPACE:
        n -= 1
    return line[:n]


def _ss_strbuf_stripspace(buf: bytes, comment_prefix: Optional[bytes]) -> bytes:
    """Port of strbuf.c:strbuf_stripspace() (byte-level, for `git stripspace`)."""
    out = bytearray()
    empties = 0
    i = 0
    n = len(buf)
    while i < n:
        eol = buf.find(b"\n", i)
        if eol != -1:
            length = eol - i + 1
        else:
            length = n - i
        line = buf[i:i + length]
        # NOTE: starts_with checks the RAW line (no lstrip) -- an indented
        # "   # comment" does NOT start with the comment prefix and is kept.
        if comment_prefix and length and line.startswith(comment_prefix):
            i += length
            continue
        cleaned = _ss_cleanup(line)
        if cleaned:
            if empties > 0 and len(out) > 0:
                out += b"\n"
            empties = 0
            out += cleaned
            out += b"\n"
        else:
            empties += 1
        i += length
    return bytes(out)


def _ss_comment_lines(buf: bytes, comment_prefix: bytes) -> bytes:
    """Port of strbuf.c:add_lines() with space_after_prefix=1 + complete_line."""
    out = bytearray()
    i = 0
    n = len(buf)
    while i < n:
        nxt = buf.find(b"\n", i)
        nxt = (nxt + 1) if nxt != -1 else n
        out += comment_prefix
        if buf[i:i + 1] not in (b"\n", b"\t"):
            out += b" "
        out += buf[i:nxt]
        i = nxt
    # strbuf_complete_line: ensure a trailing newline on a non-empty buffer.
    if out and out[-1:] != b"\n":
        out += b"\n"
    return bytes(out)


def cmd_stripspace(argv: list[str]) -> int:
    # -s/-c are OPT_CMDMODE (mutually exclusive); leftover positionals are a
    # usage error (rc 129). Hand-roll parse_options so the exclusivity message,
    # core.commentChar handling, and byte-exact strip/comment logic all match.
    mode = None  # 's' or 'c'
    extra = []
    i, n = 0, len(argv)
    saw_ddash = False
    while i < n:
        a = argv[i]
        if saw_ddash:
            extra.append(a)
            i += 1
            continue
        if a == "--":
            saw_ddash = True
        elif a in ("-h", "--help"):
            sys.stdout.write(_STRIPSPACE_USAGE)
            return 129
        elif a in ("-s", "--strip-comments"):
            if mode is not None and mode != "s":
                _err("error: options '-s' and '-c' cannot be used together")
                return 129
            mode = "s"
        elif a in ("-c", "--comment-lines"):
            if mode is not None and mode != "c":
                _err("error: options '-c' and '-s' cannot be used together")
                return 129
            mode = "c"
        elif a == "-" or not a.startswith("-"):
            extra.append(a)
        else:
            disp = a[2:] if a.startswith("--") else a[1:]
            kind = "option" if a.startswith("--") else "switch"
            _err("error: unknown %s `%s'" % (kind, disp))
            sys.stderr.write(_STRIPSPACE_USAGE)
            return 129
        i += 1
    if extra:
        sys.stderr.write(_STRIPSPACE_USAGE)
        return 129

    # comment char is consulted only in -s / -c modes.
    comment_prefix = b"#"
    if mode is not None:
        try:
            repo = _repo()
        except Exception:
            repo = None
        if repo is not None:
            try:
                from . import gitconfig
                cc = gitconfig.get(repo, "core.commentChar")
                if cc and cc != "auto":
                    comment_prefix = cc.encode("utf-8")
            except Exception:
                pass

    data = _read_stdin_bytes()
    if mode == "c":
        result = _ss_comment_lines(data, comment_prefix)
    elif mode == "s":
        result = _ss_strbuf_stripspace(data, comment_prefix)
    else:
        result = _ss_strbuf_stripspace(data, None)
    sys.stdout.buffer.write(result)
    return 0


def _all_refs(repo: Repository) -> dict[str, str]:
    """Collect every ref (loose + packed) as name -> sha, like for_each_ref."""
    if refs_mod.uses_reftable(repo):
        return dict(refs_mod.iter_all_refs(repo))
    all_refs: dict[str, str] = {}
    refs_root = repo.gitdir / "refs"
    if refs_root.exists():
        for f in refs_root.rglob("*"):
            if f.is_file():
                rel = str(f.relative_to(repo.gitdir)).replace(os.sep, "/")
                s = refs_mod.read_ref(repo, rel)
                if s:
                    all_refs[rel] = s
    for ref, s in refs_mod.read_packed_refs(repo).items():
        all_refs.setdefault(ref, s)
    return all_refs


def _tag_chain(repo: Repository, obj_sha: str) -> list[tuple[str, str]]:
    """Walk the chain of annotated tag objects starting at `obj_sha`, returning
    `(tag_sha, tag_header_name)` for each tag until a non-tag object is reached.

    Port of revision.c handle_commit: prepare_revision_walk rebuilds `pending`
    via add_pending_object(object, tag->tag), so every tag's displayed name is
    its own `tag` header (not how it was referenced)."""
    out: list[tuple[str, str]] = []
    seen: set[str] = set()
    cur = obj_sha
    while cur and cur not in seen:
        seen.add(cur)
        try:
            t, data = objs.read_object(repo, cur)
        except Exception:  # noqa: BLE001 - missing/corrupt object
            break
        if t != "tag":
            break
        target = None
        tagname = ""
        hdr = data.split(b"\n\n", 1)[0]
        for raw in hdr.split(b"\n"):
            if raw.startswith(b"object "):
                target = raw[len(b"object "):].decode("ascii", "replace").strip()
            elif raw.startswith(b"tag "):
                tagname = raw[len(b"tag "):].decode("utf-8", "surrogateescape")
        out.append((cur, tagname))
        cur = target
    return out


def _rev_object_sha(repo: Repository, name: str) -> Optional[str]:
    """Resolve a rev-ish to the SHA of the object it directly names, WITHOUT
    peeling annotated tags (unlike rev_parse, which peels to a commit). Used to
    discover tag objects for `rev-list --objects`."""
    name = name.strip()
    if not name:
        return None
    # A bare object id (full or abbreviated) names that object directly.
    low = name.lower()
    if 4 <= len(low) <= repo.hex_len * 2 and all(c in "0123456789abcdef" for c in low):
        full = refs_mod.rev_parse(repo, name)
        # rev_parse on a tag SHA peels; recover the original object if it was a
        # complete id, otherwise trust the (possibly abbreviated) resolution.
        if len(low) == repo.hex_len * 2 and objs.object_exists(repo, low):
            return low
        # Abbreviated: find the unique object with this prefix.
        if full is not None:
            for cand in _all_object_shas(repo):
                if cand.startswith(low):
                    return cand
        return full
    # A ref name (tag/branch/HEAD): return the object the ref points at.
    full_ref = refs_mod.dwim_full_name(repo, name)
    if full_ref is not None:
        for refname, refsha in _enumerate_refs(repo):
            if refname == full_ref:
                return refsha
    # Fall back to the peeled resolution (handles ^{}, ~, etc.).
    return refs_mod.rev_parse(repo, name)


def _peel_to_non_tag(repo: Repository, sha: str) -> Optional[str]:
    """Follow tag objects until a non-tag object is reached; return its sha."""
    seen: set[str] = set()
    cur = sha
    while cur and cur not in seen:
        seen.add(cur)
        try:
            t, data = objs.read_object(repo, cur)
        except (KeyError, Exception):  # noqa: BLE001 - missing/corrupt object
            return None
        if t != "tag":
            return cur
        target = None
        for raw in data.split(b"\n"):
            if raw.startswith(b"object "):
                target = raw[len(b"object "):].decode("ascii", "replace").strip()
                break
            if raw == b"":
                break
        if not target:
            return None
        cur = target
    return None


def cmd_update_server_info(argv: list[str]) -> int:
    # -f / --force only controls whether files are rewritten from scratch; the
    # resulting content is identical either way, so it is accepted as a no-op
    # with respect to output (matching C git's behaviour for our purposes).
    ap = argparse.ArgumentParser(prog="pygit update-server-info", add_help=False)
    ap.add_argument("-f", "--force", dest="force", action="store_true", default=False)
    ap.add_argument("--no-force", dest="force", action="store_false")
    args = ap.parse_args(argv)
    _ = args.force
    repo = _repo()

    # info/refs: every ref, sorted by name, with peeled lines for tag objects.
    info_dir = repo.gitdir / "info"
    info_dir.mkdir(parents=True, exist_ok=True)
    all_refs = _all_refs(repo)
    out: list[str] = []
    for name in sorted(all_refs):
        sha = all_refs[name]
        out.append(f"{sha}\t{name}\n")
        try:
            t, _data = objs.read_object(repo, sha)
        except (KeyError, Exception):  # noqa: BLE001
            t = None
        if t == "tag":
            peeled = _peel_to_non_tag(repo, sha)
            if peeled:
                out.append(f"{peeled}\t{name}^{{}}\n")
    (info_dir / "refs").write_text("".join(out), encoding="utf-8")

    # objects/info/packs: "P <name>\n" per local pack, then a trailing blank line.
    pack_dir = repo.gitdir / "objects" / "pack"
    pack_info_dir = repo.gitdir / "objects" / "info"
    pack_info_dir.mkdir(parents=True, exist_ok=True)
    pack_lines: list[str] = []
    if pack_dir.exists():
        for f in sorted(pack_dir.glob("pack-*.pack")):
            pack_lines.append(f"P {f.name}\n")
    (pack_info_dir / "packs").write_text("".join(pack_lines) + "\n", encoding="utf-8")
    return 0


_REPLACE_USAGE = (
    "usage: git replace [-f] <object> <replacement>\n"
    "   or: git replace [-f] --edit <object>\n"
    "   or: git replace [-f] --graft <commit> [<parent>...]\n"
    "   or: git replace [-f] --convert-graft-file\n"
    "   or: git replace -d <object>...\n"
    "   or: git replace [--format=<format>] [-l [<pattern>]]\n"
    "\n"
    "    -l, --list            list replace refs\n"
    "    -d, --delete          delete replace refs\n"
    "    -e, --edit            edit existing object\n"
    "    -g, --graft           change a commit's parents\n"
    "    --convert-graft-file  convert existing graft file\n"
    "    -f, --[no-]force      replace the ref if it exists\n"
    "    --[no-]raw            do not pretty-print contents for --edit\n"
    "    --[no-]format <format>\n"
    "                          use this format\n"
)


def _replace_usage_opt(msg: str) -> int:
    sys.stderr.write(f"fatal: {msg}\n\n{_REPLACE_USAGE}\n")
    return 129


def cmd_replace(argv: list[str]) -> int:
    # Hand-rolled option parsing to match git's exact error formats. git's
    # replace builtin always resolves the *real* objects (disable_replace_refs).
    force = False
    raw = False
    fmt: Optional[str] = None
    # cmdmode tracks the single selected mode; conflicting modes error like
    # parse-options' OPT_CMDMODE: "options 'X' and 'Y' cannot be used together".
    cmdmode: Optional[str] = None
    mode_opt: dict[str, str] = {}  # mode -> option spelling that selected it
    rest: list[str] = []

    def set_mode(name: str, opt: str) -> Optional[int]:
        nonlocal cmdmode
        if cmdmode is not None and cmdmode != name:
            sys.stderr.write(
                f"error: options '{opt}' and '{mode_opt[cmdmode]}' "
                "cannot be used together\n"
            )
            return 129
        cmdmode = name
        mode_opt[name] = opt
        return None

    i = 0
    parsing = True
    while i < len(argv):
        a = argv[i]
        if parsing and a == "--":
            parsing = False
            i += 1
            continue
        if parsing and a.startswith("-") and a != "-":
            if a in ("-l", "--list"):
                rc = set_mode("list", "-l" if a == "-l" else "--list")
                if rc is not None:
                    return rc
            elif a in ("-d", "--delete"):
                rc = set_mode("delete", "-d" if a == "-d" else "--delete")
                if rc is not None:
                    return rc
            elif a in ("-e", "--edit"):
                rc = set_mode("edit", "-e" if a == "-e" else "--edit")
                if rc is not None:
                    return rc
            elif a in ("-g", "--graft"):
                rc = set_mode("graft", "-g" if a == "-g" else "--graft")
                if rc is not None:
                    return rc
            elif a == "--convert-graft-file":
                rc = set_mode("convert", "--convert-graft-file")
                if rc is not None:
                    return rc
            elif a in ("-f", "--force"):
                force = True
            elif a == "--no-force":
                force = False
            elif a == "--raw":
                raw = True
            elif a == "--no-raw":
                raw = False
            elif a == "--format":
                if i + 1 >= len(argv):
                    return _replace_usage_opt("option `format' requires a value")
                fmt = argv[i + 1]
                i += 1
            elif a.startswith("--format="):
                fmt = a[len("--format="):]
            else:
                sys.stderr.write(f"error: unknown switch `{a.lstrip('-')[0]}'\n"
                                 if not a.startswith("--")
                                 else f"error: unknown option `{a[2:]}'\n")
                # parse-options.c: the error line is followed directly by the
                # usage block (no blank line between) and a trailing blank line.
                sys.stderr.write(_REPLACE_USAGE + "\n")
                return 129
            i += 1
            continue
        rest.append(a)
        i += 1

    if cmdmode is None:
        cmdmode = "replace" if rest else "list"

    if fmt is not None and cmdmode != "list":
        return _replace_usage_opt("--format cannot be used when not listing")
    if force and cmdmode not in ("replace", "edit", "graft", "convert"):
        return _replace_usage_opt("-f only makes sense when writing a replacement")
    if raw and cmdmode != "edit":
        return _replace_usage_opt("--raw only makes sense with --edit")

    repo = _repo()

    if cmdmode == "edit":
        # Requires an interactive editor; cannot be reproduced byte-exact.
        sys.stderr.write("error: 'git replace --edit' is not supported\n")
        return 128

    if cmdmode == "list":
        if len(rest) > 1:
            return _replace_usage_opt("only one pattern can be given with -l")
        return _replace_list(repo, rest[0] if rest else None, fmt)

    if cmdmode == "delete":
        if len(rest) < 1:
            return _replace_usage_opt("-d needs at least one argument")
        return _replace_delete(repo, rest)

    if cmdmode == "replace":
        if len(rest) != 2:
            return _replace_usage_opt("bad number of arguments")
        return _replace_object(repo, rest[0], rest[1], force)

    if cmdmode == "graft":
        if len(rest) < 1:
            return _replace_usage_opt("-g needs at least one argument")
        return _replace_create_graft(repo, rest, force, gentle=False, graft_state={})

    if cmdmode == "convert":
        if len(rest) != 0:
            return _replace_usage_opt("--convert-graft-file takes no argument")
        return 1 if _replace_convert_graft_file(repo, force) else 0

    return 1


def _replace_type(repo: Repository, sha: str) -> str:
    return objs.read_object(repo, sha)[0]


def _replace_list(repo: Repository, pattern: Optional[str], fmt: Optional[str]) -> int:
    if fmt is None or fmt == "" or fmt == "short":
        mode = "short"
    elif fmt == "medium":
        mode = "medium"
    elif fmt == "long":
        mode = "long"
    else:
        _err(f"error: invalid replace format '{fmt}'\n"
             "valid formats are 'short', 'medium' and 'long'")
        return 255
    if pattern is None:
        pattern = "*"
    import fnmatch
    # gather replace refs (loose + packed), keyed by the hex name suffix.
    entries: dict[str, str] = {}
    packed = refs_mod.read_packed_refs(repo)
    for full, val in packed.items():
        if full.startswith("refs/replace/"):
            entries[full[len("refs/replace/"):]] = val
    root = repo.gitdir / "refs" / "replace"
    if root.exists():
        for f in root.rglob("*"):
            if f.is_file():
                name = str(f.relative_to(root)).replace(os.sep, "/")
                entries[name] = f.read_text(encoding="utf-8").strip()
    for name in sorted(entries):
        if not fnmatch.fnmatchcase(name, pattern):
            continue
        repl = entries[name]
        if mode == "short":
            _print(name)
        elif mode == "medium":
            _print(f"{name} -> {repl}")
        else:
            try:
                obj_type = _replace_type(repo, name)
            except (KeyError, ValueError):
                _err(f"error: failed to resolve '{name}' as a valid ref")
                return 255
            repl_type = _replace_type(repo, repl)
            _print(f"{name} ({obj_type}) -> {repl} ({repl_type})")
    return 0


def _replace_delete_ref(repo: Repository, ref: str) -> None:
    """Delete a ref that may live loose and/or in packed-refs."""
    p = repo.gitdir / ref
    if p.exists():
        p.unlink()
    ppath = repo.gitdir / "packed-refs"
    if not ppath.exists():
        return
    lines = ppath.read_text(encoding="utf-8").splitlines()
    if not any(line.partition(" ")[2] == ref for line in lines
               if line and not line.startswith(("#", "^"))):
        return
    out: list[str] = []
    skip_peel = False
    for line in lines:
        if line.startswith("^"):
            if skip_peel:
                skip_peel = False
                continue
            out.append(line)
            continue
        skip_peel = False
        if line and not line.startswith("#") and line.partition(" ")[2] == ref:
            skip_peel = True  # drop a following peel line, if any
            continue
        out.append(line)
    ppath.write_text("\n".join(out) + ("\n" if out else ""), encoding="utf-8")


def _replace_delete(repo: Repository, args: list[str]) -> int:
    had_error = False
    for spec in args:
        oid = refs_mod.rev_parse(repo, spec)
        if not oid:
            _err(f"error: failed to resolve '{spec}' as a valid ref")
            had_error = True
            continue
        ref = f"refs/replace/{oid}"
        if refs_mod.read_ref(repo, ref) is None:
            _err(f"error: replace ref '{oid}' not found")
            had_error = True
            continue
        _replace_delete_ref(repo, ref)
        _print(f"Deleted replace ref '{oid}'")
    return 1 if had_error else 0


def _replace_write_ref(repo: Repository, oid: str, repl: str, force: bool) -> int:
    ref = f"refs/replace/{oid}"
    if refs_mod.read_ref(repo, ref) is not None and not force:
        _err(f"error: replace ref '{ref}' already exists")
        return 255
    refs_mod.update_ref(repo, ref, repl)
    return 0


def _replace_object(repo: Repository, object_ref: str, replace_ref: str, force: bool) -> int:
    oid = refs_mod.rev_parse(repo, object_ref)
    if not oid:
        _err(f"error: failed to resolve '{object_ref}' as a valid ref")
        return 255
    repl = refs_mod.rev_parse(repo, replace_ref)
    if not repl:
        _err(f"error: failed to resolve '{replace_ref}' as a valid ref")
        return 255
    obj_type = _replace_type(repo, oid)
    repl_type = _replace_type(repo, repl)
    if not force and obj_type != repl_type:
        _err("error: Objects must be of the same type.\n"
             f"'{object_ref}' points to a replaced object of type '{obj_type}'\n"
             f"while '{replace_ref}' points to a replacement object of "
             f"type '{repl_type}'.")
        return 255
    return _replace_write_ref(repo, oid, repl, force)


def _replace_could_not_read(repo: Repository, oid: str, wrote: Optional[list]) -> None:
    """Once a replacement object has been written in this process, C git's object
    lookup reports 'Could not read <oid>' for a syntactically valid but missing
    full-length hex before the higher-level parse error. Mirror that ordering."""
    if (wrote and wrote[0] and len(oid) == repo.hex_len
            and all(c in "0123456789abcdef" for c in oid)
            and not objs.object_exists(repo, oid)):
        _err(f"error: Could not read {oid}")


_GRAFT_DEPRECATED_HINT = (
    "hint: Support for <GIT_DIR>/info/grafts is deprecated\n"
    "hint: and will be removed in a future Git version.\n"
    "hint:\n"
    "hint: Please use \"git replace --convert-graft-file\"\n"
    "hint: to convert the grafts into replace refs.\n"
    "hint:\n"
    "hint: Turn this message off by running\n"
    "hint: \"git config set advice.graftFileDeprecated false\"\n"
)


def _replace_prepare_grafts(repo: Repository, state: Optional[dict]) -> None:
    """Mirror C git's lazy prepare_commit_graft: the first time a commit is
    parsed, the whole info/grafts file is read. If it exists, a deprecation
    hint is shown (unless suppressed, e.g. by --convert-graft-file, or disabled
    via advice.graftFileDeprecated), and every malformed line (a line whose
    whitespace-separated tokens are not all full-length lowercase hex) emits
    'error: bad graft data: <line>'. This happens exactly once."""
    if state is None or state.get("prepared"):
        return
    state["prepared"] = True
    graft_file = repo.gitdir / "info" / "grafts"
    try:
        text = graft_file.read_text(encoding="utf-8", errors="replace")
    except FileNotFoundError:
        return
    if not state.get("suppress_hint"):
        from . import gitconfig
        advice = (gitconfig.get(repo, "advice.graftfiledeprecated") or "").lower()
        if advice not in ("false", "0", "no", "off"):
            sys.stderr.write(_GRAFT_DEPRECATED_HINT)
    for raw_line in text.split("\n"):
        line = raw_line.rstrip()
        if not line or line[0] == "#":
            continue
        tokens = line.split()
        ok = all(len(t) == repo.hex_len
                 and all(c in "0123456789abcdef" for c in t) for t in tokens)
        # parse_oid_hex also requires the separators between tokens to be a
        # single space; any token failing full-hex parse triggers the error.
        if not ok:
            _err(f"error: bad graft data: {line}")


def _replace_create_graft(repo: Repository, args: list[str], force: bool, gentle: bool,
                          wrote: Optional[list] = None,
                          graft_state: Optional[dict] = None) -> int:
    old_ref = args[0]
    old_oid = refs_mod.rev_parse(repo, old_ref)
    if not old_oid:
        _err(f"error: not a valid object name: '{old_ref}'")
        return 255
    # The commit parse below is what triggers C git's one-shot graft-table load.
    _replace_prepare_grafts(repo, graft_state)
    try:
        obj_type, data = objs.read_object(repo, old_oid)
    except (KeyError, ValueError):
        _replace_could_not_read(repo, old_oid, wrote)
        _err(f"error: could not parse {old_ref}")
        return 255
    if obj_type != "commit":
        _err(f"error: object {old_oid} is a {obj_type}, not a commit")
        _err(f"error: could not parse {old_ref}")
        return 255

    # Build new commit buffer: keep "tree" line, replace the parent block.
    hexsz = repo.hex_len
    # parents start after "tree <hex>\n" (5 + hexsz + 1)
    parent_start = 5 + hexsz + 1
    parent_end = parent_start
    while data[parent_end:parent_end + 7] == b"parent ":
        parent_end += 7 + hexsz + 1  # "parent " + hex + "\n"

    new_parents = b""
    for p in args[1:]:
        poid = refs_mod.rev_parse(repo, p)
        if not poid:
            _err(f"error: not a valid object name: '{p}'")
            return 255
        try:
            ptype = objs.read_object(repo, poid)[0]
        except (KeyError, ValueError):
            _replace_could_not_read(repo, poid, wrote)
            _err(f"error: could not parse {p} as a commit")
            return 255
        if ptype != "commit":
            _err(f"error: object {poid} is a {ptype}, not a commit")
            _err(f"error: could not parse {p} as a commit")
            return 255
        new_parents += b"parent " + poid.encode() + b"\n"

    buf = data[:parent_start] + new_parents + data[parent_end:]

    # Drop any gpg signature (gpgsig header) -> warn.
    buf, had_sig = _replace_remove_signature(buf, hexsz)
    if had_sig:
        _err(f"warning: the original commit '{old_ref}' has a gpg signature")
        _err("warning: the signature will be removed in the replacement commit!")

    # Mergetag check: a discarded mergetag whose tagged commit is not among the
    # new parents is an error directing the user to --edit.
    rc = _replace_check_mergetags(repo, data, args, hexsz)
    if rc is not None:
        return rc

    new_oid = objs.write_object(repo, "commit", buf)
    if wrote is not None:
        wrote[0] = True

    if new_oid == old_oid:
        if gentle:
            _err(f"warning: graft for '{old_oid}' unnecessary")
            return 0
        _err(f"error: new commit is the same as the old one: '{old_oid}'")
        return 255

    return _replace_write_ref(repo, old_oid, new_oid, force)


def _replace_remove_signature(buf: bytes, hexsz: int) -> tuple[bytes, bool]:
    """Strip a 'gpgsig' header (and continuation lines) from a commit buffer.
    Returns (new_buf, had_signature)."""
    # Header section ends at the first blank line.
    sep = buf.find(b"\n\n")
    header = buf if sep < 0 else buf[:sep]
    body = b"" if sep < 0 else buf[sep:]
    out_lines: list[bytes] = []
    had = False
    skipping = False
    for line in header.split(b"\n"):
        if skipping:
            if line.startswith(b" "):
                continue  # folded continuation of the signature
            skipping = False
        if line.startswith(b"gpgsig ") or line.startswith(b"gpgsig-sha256 "):
            had = True
            skipping = True
            continue
        out_lines.append(line)
    return b"\n".join(out_lines) + body, had


def _replace_check_mergetags(repo: Repository, data: bytes, args: list[str], hexsz: int) -> Optional[int]:
    """Mirror builtin/replace.c check_mergetags: for each mergetag header in the
    original commit, the tagged commit must be among the new parents."""
    sep = data.find(b"\n\n")
    header = data if sep < 0 else data[:sep]
    lines = header.split(b"\n")
    # Collect mergetag blocks (header line + folded continuation lines).
    idx = 0
    new_parent_oids: Optional[set[str]] = None
    while idx < len(lines):
        line = lines[idx]
        if line.startswith(b"mergetag "):
            block = [line[len(b"mergetag "):]]
            idx += 1
            while idx < len(lines) and lines[idx].startswith(b" "):
                block.append(lines[idx][1:])
                idx += 1
            tag_payload = b"\n".join(block) + b"\n"
            import hashlib
            tag_oid = hashlib.sha1(
                b"tag " + str(len(tag_payload)).encode() + b"\0" + tag_payload
            ).hexdigest()
            # Find the tagged object's oid from the tag payload.
            tagged = None
            for tl in tag_payload.split(b"\n"):
                if tl.startswith(b"object "):
                    tagged = tl[len(b"object "):].decode()
                    break
            if new_parent_oids is None:
                new_parent_oids = set()
                for p in args[1:]:
                    poid = refs_mod.rev_parse(repo, p)
                    if not poid:
                        _err(f"error: not a valid object name: '{p}'")
                        return 255
                    new_parent_oids.add(poid)
            if tagged not in new_parent_oids:
                _err(f"error: original commit '{args[0]}' contains mergetag "
                     f"'{tag_oid}' that is discarded; use --edit instead of --graft")
                return 255
        else:
            idx += 1
    return None


def _replace_convert_graft_file(repo: Repository, force: bool) -> bool:
    """Convert .git/info/grafts into replace refs. Returns True on error."""
    graft_file = repo.gitdir / "info" / "grafts"
    try:
        text = graft_file.read_text(encoding="utf-8", errors="replace")
    except FileNotFoundError:
        return True
    errs: list[str] = []
    wrote = [False]
    graft_state: dict = {"suppress_hint": True}
    for raw_line in text.splitlines():
        if raw_line.startswith("#"):
            continue
        parts = raw_line.split()
        if not parts:
            continue
        rc = _replace_create_graft(repo, parts, force, gentle=True,
                                   wrote=wrote, graft_state=graft_state)
        if rc:
            errs.append(raw_line)
    if not errs:
        try:
            graft_file.unlink()
        except FileNotFoundError:
            pass
        return False
    _err("warning: could not convert the following graft(s):\n"
         + "".join("\n\t" + e for e in errs))
    return True


def cmd_cherry(argv: list[str]) -> int:
    """Find commits in <head> that are not in <upstream> based on patch-id."""
    ap = argparse.ArgumentParser(prog="pygit cherry", add_help=False)
    ap.add_argument("-v", "--verbose", action="store_true")
    ap.add_argument("upstream")
    ap.add_argument("head", nargs="?", default="HEAD")
    args = ap.parse_args(argv)
    repo = _repo()
    up = refs_mod.rev_parse(repo, args.upstream)
    head = refs_mod.rev_parse(repo, args.head)
    if not up or not head:
        return 128

    def collect(tip: str, stop: str) -> list[str]:
        out = []
        seen: set[str] = set()
        stack = [tip]
        # mark all ancestors of stop
        anc_stop: set[str] = set()
        st2 = [stop]
        seen2: set[str] = set()
        while st2:
            s = st2.pop()
            if s in seen2:
                continue
            seen2.add(s)
            anc_stop.add(s)
            try:
                c = objs.parse_commit(objs.read_object(repo, s)[1])
                st2.extend(c.parents)
            except KeyError:
                pass
        while stack:
            s = stack.pop()
            if s in seen or s in anc_stop:
                continue
            seen.add(s)
            out.append(s)
            try:
                c = objs.parse_commit(objs.read_object(repo, s)[1])
                stack.extend(c.parents)
            except KeyError:
                pass
        return out

    def patch_id(sha: str) -> str:
        import hashlib
        c = objs.parse_commit(objs.read_object(repo, sha)[1])
        if not c.parents:
            return hashlib.sha1(c.tree.encode()).hexdigest()
        parent_tree = objs.parse_commit(objs.read_object(repo, c.parents[0])[1]).tree
        from . import diff as _d
        h = hashlib.sha1()
        for p, a_entry, b_entry in workdir.iter_tree_changes(repo, parent_tree, c.tree):
            a_sha = a_entry.sha if a_entry else None
            b_sha = b_entry.sha if b_entry else None
            if a_sha == b_sha:
                continue
            at = bt = ""
            if a_sha:
                at = objs.read_object(repo, a_sha)[1].decode("utf-8", errors="replace")
            if b_sha:
                bt = objs.read_object(repo, b_sha)[1].decode("utf-8", errors="replace")
            h.update(_d.unified_diff(at, bt, p, p).encode("utf-8", errors="replace"))
        return h.hexdigest()

    head_commits = collect(head, up)
    up_commits = collect(up, head)
    up_patches = {patch_id(s) for s in up_commits}
    for s in head_commits:
        pid = patch_id(s)
        mark = "-" if pid in up_patches else "+"
        if args.verbose:
            c = objs.parse_commit(objs.read_object(repo, s)[1])
            subject = c.message.splitlines()[0] if c.message.strip() else ""
            _print(f"{mark} {s} {subject}")
        else:
            _print(f"{mark} {s}")
    return 0


def _rd_format(repo: Repository, sha: str) -> tuple[str, str]:
    """Reformat a commit into git range-diff's internal patch text (## headers),
    returning (full_patch, diff_only). Mirrors range-diff.c:read_patches."""
    c = objs.parse_commit(objs.read_object(repo, sha)[1])
    lines = [" ## Metadata ##", f"Author: {_split_ident(c.author)[0]}", "",
             " ## Commit message ##"]
    for ml in c.message.split("\n"):
        if ml.strip() == "":
            continue
        lines.append(("    " + ml).rstrip())
    diff_lines: list[str] = []
    parent_tree = None
    if c.parents:
        parent_tree = objs.parse_commit(objs.read_object(repo, c.parents[0])[1]).tree
    for path, a, b in _tree_changes(repo, parent_tree, c.tree):
        if not a.present:
            sec = f"{path} (new)"
        elif not b.present:
            sec = f"{path} (deleted)"
        else:
            sec = path
        if a.present and b.present and a.mode != b.mode:
            sec += f" (mode change {a.mode} => {b.mode})"
        diff_lines.append(f" ## {sec} ##")
        a_text = (a.data or b"").decode("utf-8", "replace")
        b_text = (b.data or b"").decode("utf-8", "replace")
        for hl in diff_mod.format_hunks(a_text.splitlines(), b_text.splitlines(), 3):
            if hl.startswith("@@ "):
                # "@@ -a,b +c,d @@ section" -> "@@ <file>: section" / "@@"
                rest = hl[3:]
                idx = rest.find("@@")
                tail = rest[idx + 2:] if idx >= 0 else ""
                diff_lines.append(f"@@ {path}:{tail}" if tail else "@@")
            else:
                diff_lines.append(hl)
    full = "\n".join(lines + ([""] if diff_lines else []) + diff_lines) + "\n"
    diff_only = ("\n".join(diff_lines) + "\n") if diff_lines else ""
    return full, diff_only


def _rd_diffsize(a: str, b: str) -> int:
    """git range-diff cost: number of diff hunks + body lines between a and b.
    Newline-terminated text has no phantom trailing line (matching xdiff)."""
    al = a.split("\n")
    bl = b.split("\n")
    if al and al[-1] == "":
        al = al[:-1]
    if bl and bl[-1] == "":
        bl = bl[:-1]
    spans = diff_mod._group_hunks(diff_mod.diff_lines(al, bl), 3)
    count = len(spans)
    for start, end in spans:
        count += end - start
    return count


def _rd_assign(a_list: list, b_list: list, exact: dict, creation_factor: int = 60) -> dict:
    """Return {a_index: b_index} matching, combining exact matches with a
    min-cost assignment of the rest (greedy approximation of git's Hungarian)."""
    na, nb = len(a_list), len(b_list)
    matched_a = dict(exact)              # a_idx -> b_idx (exact)
    used_b = set(exact.values())
    # Candidate costs for remaining pairs.
    rem_a = [i for i in range(na) if i not in matched_a]
    rem_b = [j for j in range(nb) if j not in used_b]
    crea_a = {i: _rd_diffsize(a_list[i][1], "") * creation_factor // 100 for i in rem_a}
    crea_b = {j: _rd_diffsize(b_list[j][1], "") * creation_factor // 100 for j in rem_b}
    pairs = []
    for i in rem_a:
        for j in rem_b:
            pairs.append((_rd_diffsize(a_list[i][1], b_list[j][1]), i, j))
    pairs.sort()
    for cost, i, j in pairs:
        if i in matched_a or j in used_b:
            continue
        # Match when keeping the pair is cheaper than creating both separately
        # (git's cost-matrix assignment with the creation-factor weighting).
        if cost < crea_a[i] + crea_b[j]:
            matched_a[i] = j
            used_b.add(j)
    return matched_a


def cmd_range_diff(argv: list[str]) -> int:
    """range-diff A..B C..D — match commits and show the diff of diffs."""
    ap = argparse.ArgumentParser(prog="pygit range-diff", add_help=False)
    ap.add_argument("range1")
    ap.add_argument("range2")
    args = ap.parse_args(argv)
    repo = _repo()

    def expand(rng: str) -> list[str]:
        if ".." not in rng:
            return [refs_mod.rev_parse(repo, rng) or ""]
        a, b = rng.split("..", 1)
        a_sha = refs_mod.rev_parse(repo, a) if a else None
        b_sha = refs_mod.rev_parse(repo, b or "HEAD")
        if not b_sha:
            return []
        out, seen = [], set()
        stack = [b_sha]
        anc_a: set[str] = set()
        if a_sha:
            st = [a_sha]
            seen_a: set[str] = set()
            while st:
                s = st.pop()
                if s in seen_a:
                    continue
                seen_a.add(s)
                anc_a.add(s)
                try:
                    c = objs.parse_commit(objs.read_object(repo, s)[1])
                    st.extend(c.parents)
                except KeyError:
                    pass
        while stack:
            s = stack.pop()
            if s in seen or s in anc_a:
                continue
            seen.add(s)
            out.append(s)
            try:
                c = objs.parse_commit(objs.read_object(repo, s)[1])
                stack.extend(c.parents)
            except KeyError:
                pass
        out.reverse()
        return out

    a_shas = expand(args.range1)
    b_shas = expand(args.range2)
    # (sha, full_patch, diff_only, subject) per side.
    def build(shas):
        out = []
        for s in shas:
            full, diff = _rd_format(repo, s)
            c = objs.parse_commit(objs.read_object(repo, s)[1])
            subj = c.message.splitlines()[0] if c.message.strip() else ""
            out.append((s, full, diff, subj))
        return out
    A = build(a_shas)
    B = build(b_shas)
    # `_list` entries used by the matcher are (full, diff).
    a_pf = [(x[1], x[2]) for x in A]
    b_pf = [(x[1], x[2]) for x in B]
    # Exact matches: identical diff text.
    exact: dict[int, int] = {}
    b_by_diff: dict[str, int] = {}
    for j, (_f, d) in enumerate(b_pf):
        b_by_diff.setdefault(d, j)
    used_b_exact = set()
    for i, (_f, d) in enumerate(a_pf):
        j = b_by_diff.get(d)
        if j is not None and j not in used_b_exact:
            exact[i] = j
            used_b_exact.add(j)
    a2b = _rd_assign(a_pf, b_pf, exact)
    b2a = {j: i for i, j in a2b.items()}

    width = len(str(max(len(A), len(B)) or 1))
    dashes = "-" * 7

    def header(a_idx, b_idx):
        if a_idx is None:
            left = f"{'-':>{width}}:  {dashes}"
            status = ">"
        elif b_idx is None:
            left = f"{a_idx + 1:>{width}}:  {A[a_idx][0][:7]}"
            status = "<"
        else:
            af, bf = A[a_idx][1], B[b_idx][1]
            status = "=" if af == bf else "!"
            left = f"{a_idx + 1:>{width}}:  {A[a_idx][0][:7]}"
        if b_idx is None:
            right = f"{'-':>{width}}:  {dashes}"
        else:
            right = f"{b_idx + 1:>{width}}:  {B[b_idx][0][:7]}"
        subj = (A[a_idx] if a_idx is not None else B[b_idx])[3]
        _print(f"{left} {status} {right} {subj}")
        return status

    import re as _re
    sec_re = _re.compile(r" ## (.*) ##$")

    def emit_body(a_idx, b_idx):
        # Inter-diff of the two reformatted patch texts. Hunk headers carry no
        # line counts; the section name comes from the nearest preceding
        # " ## X ##" line (git's section-header diff driver). Each line is
        # prefixed with four spaces.
        al = A[a_idx][1].split("\n")
        bl = B[b_idx][1].split("\n")
        if al and al[-1] == "":
            al = al[:-1]
        if bl and bl[-1] == "":
            bl = bl[:-1]
        ops = diff_mod.diff_lines(al, bl)
        for start, end in diff_mod._group_hunks(ops, 3):
            hunk = ops[start:end]
            a_idxs = [ai for k, ai, _ in hunk if k in ("eq", "del")]
            first_a = a_idxs[0] if a_idxs else 0
            section = ""
            for k in range(first_a, -1, -1):
                m = sec_re.match(al[k])
                if m:
                    section = m.group(1)
                    break
            _print("    @@" + (" " + section if section else ""))
            for kind, ai, bi in hunk:
                if kind == "eq":
                    _print("     " + al[ai])
                elif kind == "del":
                    _print("    -" + al[ai])
                else:
                    _print("    +" + bl[bi])

    shown_a = set()
    i = j = 0
    while i < len(A) or j < len(B):
        while i < len(A) and i in shown_a:
            i += 1
        if i < len(A) and i not in a2b:
            header(i, None)
            i += 1
            continue
        while j < len(B) and j not in b2a:
            header(None, j)
            j += 1
        if j < len(B):
            ai = b2a[j]
            st = header(ai, j)
            if st == "!":
                emit_body(ai, j)
            shown_a.add(ai)
            j += 1
    return 0


def _register_phase5() -> None:
    _COMMANDS["pull"] = cmd_pull
    _COMMANDS["grep"] = cmd_grep
    _COMMANDS["show-branch"] = cmd_show_branch
    _COMMANDS["whatchanged"] = cmd_whatchanged
    _COMMANDS["mktag"] = cmd_mktag
    _COMMANDS["name-rev"] = cmd_name_rev
    _COMMANDS["var"] = cmd_var
    _COMMANDS["stripspace"] = cmd_stripspace
    _COMMANDS["update-server-info"] = cmd_update_server_info
    _COMMANDS["replace"] = cmd_replace
    _COMMANDS["cherry"] = cmd_cherry
    _COMMANDS["range-diff"] = cmd_range_diff


_register_phase5()


# ---------------------------------------------------------------------------
# Phase 6 — submodule / sparse-checkout / pack-refs / merge-file /
#           fast-export / fast-import / interpret-trailers /
#           verify-commit / verify-tag / commit-graph / rerere / column


def _log2u(n: int) -> int:
    """C Git's log2u: floor(log2(n)) for n>=1, else 0."""
    return n.bit_length() - 1 if n >= 1 else 0


_PACK_REFS_USAGE_LINE = (
    "git pack-refs [--all] [--no-prune] [--auto] [--include <pattern>] "
    "[--exclude <pattern>]")


def _pack_refs_options() -> list["_PoOpt"]:
    NOARG = _PARSEOPT_NOARG

    def O(long, argh, flags, help):
        o = _PoOpt()
        o.long_name = long
        o.argh = argh
        o.flags = flags
        o.help = help
        return o

    return [
        O('all', None, NOARG, "pack everything"),
        O('prune', None, NOARG, "prune loose refs (default)"),
        O('auto', None, NOARG, "auto-pack refs as needed"),
        O('include', 'pattern', 0, "references to include"),
        O('exclude', 'pattern', 0, "references to exclude"),
    ]


def _pack_refs_usage_err(prefix_err: Optional[str]) -> int:
    if prefix_err is not None:
        _err(prefix_err)
    sys.stderr.write(_po_render_usage([_PACK_REFS_USAGE_LINE],
                                      _pack_refs_options(), False, True))
    return 129


def cmd_pack_refs(argv: list[str]) -> int:
    import fnmatch
    # pack-refs takes no positionals; any extra arg or unknown option dumps the
    # usage block rc 129. Known long options of pack-refs:
    _PR_KNOWN = {"--all", "--prune", "--no-prune", "--auto", "--no-auto",
                 "--no-all", "--include", "--exclude", "--no-include", "--no-exclude"}
    i = 0
    while i < len(argv):
        t = argv[i]
        if t == "--":
            break
        if t.startswith("--"):
            base = t.split("=", 1)[0]
            if base not in _PR_KNOWN:
                return _pack_refs_usage_err(f"error: unknown option `{t[2:]}'")
            if base in ("--include", "--exclude") and "=" not in t:
                i += 2
                continue
            i += 1
            continue
        if t.startswith("-") and t != "-":
            return _pack_refs_usage_err(f"error: unknown switch `{t[1:]}'")
        # A non-option positional: pack-refs accepts none.
        return _pack_refs_usage_err(None)
    ap = argparse.ArgumentParser(prog="pygit pack-refs", add_help=False)
    ap.add_argument("--all", action="store_true")
    ap.add_argument("--prune", dest="prune", action="store_true", default=None)
    ap.add_argument("--no-prune", dest="prune", action="store_false")
    ap.add_argument("--auto", action="store_true")
    ap.add_argument("--include", action="append", default=[])
    ap.add_argument("--exclude", action="append", default=[])
    args = ap.parse_args(argv)
    repo = _repo()
    prune = True if args.prune is None else args.prune  # prune is the default

    # Ref selection mirrors pack-refs.c: --include patterns (or "*" for --all)
    # form the set; the "refs/tags/*" default applies only when none are given.
    includes = list(args.include)
    if args.all:
        includes.append("*")
    if not includes:
        includes.append("refs/tags/*")
    excludes = list(args.exclude)

    def _peeled(sha: str) -> Optional[str]:
        """Recursively peel a tag to its non-tag object; None if not a tag."""
        cur, peeled_any = sha, False
        while True:
            try:
                t, data = objs.read_object(repo, cur)
            except (KeyError, ValueError):
                return None
            if t != "tag":
                return cur if peeled_any else None
            peeled_any = True
            obj = None
            for line in data.split(b"\n"):
                if line.startswith(b"object "):
                    obj = line[len(b"object "):].decode("ascii", "replace").strip()
                    break
                if line == b"":
                    break
            if not obj:
                return None
            cur = obj

    def should_pack(name: str) -> bool:
        if any(fnmatch.fnmatch(name, p) for p in excludes):
            return False
        return any(fnmatch.fnmatch(name, p) for p in includes)

    # Collect loose refs under refs/ (skipping symbolic and broken ones).
    loose: list[tuple[str, str]] = []
    refs_root = repo.gitdir / "refs"
    if refs_root.exists():
        for f in sorted(refs_root.rglob("*")):
            if not f.is_file():
                continue
            name = str(f.relative_to(repo.gitdir)).replace(os.sep, "/")
            try:
                raw = f.read_text(encoding="utf-8").strip()
            except OSError:
                continue
            if raw.startswith("ref: "):
                continue  # symbolic ref — never packed
            if len(raw) != repo.hex_len or any(ch not in "0123456789abcdef" for ch in raw):
                continue  # broken / not an object id
            loose.append((name, raw))

    to_pack = [(n, s) for n, s in loose if should_pack(n)]

    # --auto packs only when the loose-in-set count crosses the size-scaled limit.
    if args.auto:
        ppath = repo.gitdir / "packed-refs"
        packed_size = ppath.stat().st_size if ppath.exists() else 0
        limit = max(16, _log2u(packed_size // 100) * 5)
        if len(to_pack) < limit:
            return 0

    # Merge into any existing packed-refs (existing packed entries are kept).
    merged = dict(refs_mod.read_packed_refs(repo))
    for name, sha in to_pack:
        merged[name] = sha

    lines = ["# pack-refs with: peeled fully-peeled sorted "]
    for name in sorted(merged):
        sha = merged[name]
        lines.append(f"{sha} {name}")
        peel = _peeled(sha)
        if peel is not None:
            lines.append(f"^{peel}")
    (repo.gitdir / "packed-refs").write_text("\n".join(lines) + "\n", encoding="utf-8")

    if prune:
        for name, _sha in to_pack:
            p = repo.gitdir / name
            if p.is_file():
                p.unlink()
    return 0


def cmd_merge_file(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit merge-file")
    ap.add_argument("-p", "--stdout", action="store_true")
    ap.add_argument("ours")
    ap.add_argument("base")
    ap.add_argument("theirs")
    args = ap.parse_args(argv)
    from . import merge as _m
    base = Path(args.base).read_bytes()
    ours = Path(args.ours).read_bytes()
    theirs = Path(args.theirs).read_bytes()
    merged, conflict = _m.merge_blob(base, ours, theirs)
    if args.stdout:
        sys.stdout.buffer.write(merged)
    else:
        Path(args.ours).write_bytes(merged)
    return 1 if conflict else 0


class _FEAnonymizer:
    """Port of builtin/fast-export.c's anonymization machinery.

    Mirrors the C implementation closely: each "kind" of token (paths, refs,
    object ids, identities, tag messages) keeps its own cache plus a private
    monotonically increasing counter, and ``anonymize_str`` consults the
    user-supplied ``--anonymize-map`` seeds first so that seeded tokens never
    consume a generated counter.
    """

    def __init__(self) -> None:
        # User-configured seeds from --anonymize-map (checked first).
        self.seeds: dict[str, str] = {}
        # Per-kind caches (anonymize_str's "map" argument).
        self._paths: dict[str, str] = {}
        self._refs: dict[str, str] = {}
        self._objs: dict[str, str] = {}
        self._idents: dict[str, str] = {}
        self._tags: dict[str, str] = {}
        # Per-kind counters, each a one-element list so closures can mutate.
        self._path_ctr = 0
        self._ref_ctr = 0
        self._ident_ctr = 0
        self._tag_ctr = 0
        self._blob_ctr = 0
        self._msg_ctr = 0
        self._oid_ctr = 1  # avoid the null oid (matches generate_fake_oid)

    # -- seed handling --------------------------------------------------
    def add_seed(self, key: str, value: str) -> None:
        # add_anonymized_entry: last write wins for a duplicate key.
        self.seeds[key] = value

    # -- generators -----------------------------------------------------
    def _gen_path(self) -> str:
        out = f"path{self._path_ctr}"
        self._path_ctr += 1
        return out

    def _gen_ref(self) -> str:
        out = f"ref{self._ref_ctr}"
        self._ref_ctr += 1
        return out

    def _gen_ident(self) -> str:
        n = self._ident_ctr
        self._ident_ctr += 1
        return f"User {n} <user{n}@example.com>"

    def _gen_tag(self) -> str:
        out = f"tag message {self._tag_ctr}"
        self._tag_ctr += 1
        return out

    def _gen_oid(self) -> str:
        # generate_fake_oid: null oid with a big-endian counter in the last
        # 4 bytes of the raw hash (20 bytes for sha1, 32 for sha256).
        rawsz = self._rawsz
        raw = bytearray(rawsz)
        raw[rawsz - 4 : rawsz] = self._oid_ctr.to_bytes(4, "big")
        self._oid_ctr += 1
        return raw.hex()

    def set_rawsz(self, rawsz: int) -> None:
        self._rawsz = rawsz

    # -- core cache lookup (anonymize_str) ------------------------------
    def _anon_str(self, cache: dict[str, str], generate, orig: str) -> str:
        # First: a manually configured token...
        if orig in self.seeds:
            return self.seeds[orig]
        # ...otherwise an already-seen token in this context...
        if orig in cache:
            return cache[orig]
        # ...and finally a freshly generated mapping.
        val = generate()
        cache[orig] = val
        return val

    # -- public, kind-specific entry points -----------------------------
    def anon_path(self, path: str) -> str:
        # Component-wise so that a/b and a/c share a common root.
        return self._anon_path_with(path, self._paths, self._gen_path)

    def anon_refname(self, refname: str) -> str:
        prefixes = ("refs/heads/", "refs/tags/", "refs/remotes/", "refs/")
        anon = ""
        rest = refname
        for pfx in prefixes:
            if refname.startswith(pfx):
                anon = pfx
                rest = refname[len(pfx):]
                break
        return anon + self._anon_path_with(rest, self._refs, self._gen_ref)

    def _anon_path_with(self, path: str, cache: dict[str, str], generate) -> str:
        out = []
        i = 0
        n = len(path)
        while i < n:
            j = path.find("/", i)
            if j == -1:
                j = n
            comp = path[i:j]
            out.append(self._anon_str(cache, generate, comp))
            i = j
            if i < n:
                out.append(path[i])
                i += 1
        return "".join(out)

    def anon_oid(self, oid_hex: str) -> str:
        return self._anon_str(self._objs, self._gen_oid, oid_hex)

    def anon_blob(self) -> bytes:
        # anonymize_blob: arbitrary content, not cached (blobs are cached by
        # marks instead). Counter increments per exported blob.
        out = f"anonymous blob {self._blob_ctr}".encode("utf-8")
        self._blob_ctr += 1
        return out

    def anon_commit_message(self) -> bytes:
        # anonymize_commit_message: never cached.
        out = f"subject {self._msg_ctr}\n\nbody\n".encode("utf-8")
        self._msg_ctr += 1
        return out

    def anon_tag_message(self, message: str) -> str:
        return self._anon_str(self._tags, self._gen_tag, message)

    def anon_ident_line(self, line: str) -> str:
        """Anonymize a 'header Name <mail> <date> <tz>' ident line.

        Mirrors anonymize_ident_line: keep the header word and the timestamp,
        replace the name+mail with a generated identity (cached).
        """
        sp = line.find(" ")
        if sp == -1:
            # BUG path in C; should not happen for valid headers.
            return line
        header = line[: sp + 1]
        rest = line[sp + 1:]
        split = _fe_split_ident_line(rest)
        if split is not None and split[4] is not None:
            name_begin, _name_end, _mail_begin, mail_end, date_begin, tz_end = split
            key = rest[name_begin:mail_end]
            ident = self._anon_str(self._idents, self._gen_ident, key)
            date = rest[date_begin:tz_end]
            return f"{header}{ident} {date}"
        return f"{header}Malformed Ident <malformed@example.com> 0 -0000"


def _fe_split_ident_line(line: str):
    """Port of split_ident_line() returning offsets within ``line``.

    Returns (name_begin, name_end, mail_begin, mail_end, date_begin, tz_end)
    or None if there is no mail section. date_begin/tz_end are None when the
    timestamp is missing/malformed (the "person_only" path).
    """
    n = len(line)
    name_begin = 0
    mail_begin = None
    for cp in range(0, n):
        if line[cp] == "<":
            mail_begin = cp + 1
            break
    if mail_begin is None:
        return None
    name_end = None
    cp = mail_begin - 2
    while cp >= 0:
        if not _it_isspace(line[cp]):
            name_end = cp + 1
            break
        cp -= 1
    if name_end is None:
        name_end = name_begin
    mail_end = None
    cp = mail_begin
    while cp < n:
        if line[cp] == ">":
            mail_end = cp
            break
        cp += 1
    if mail_end is None:
        return None
    # Find the trailing '>' from the end (broken-ident tolerant).
    cp = n - 1
    while cp >= 0 and line[cp] != ">":
        cp -= 1
    cp += 1
    while cp < n and _it_isspace(line[cp]):
        cp += 1
    if n <= cp:
        return (name_begin, name_end, mail_begin, mail_end, None, None)
    date_begin = cp
    span = 0
    while cp + span < n and line[cp + span].isdigit() and line[cp + span] in "0123456789":
        span += 1
    if span == 0:
        return (name_begin, name_end, mail_begin, mail_end, None, None)
    date_end = date_begin + span
    cp = date_end
    while cp < n and _it_isspace(line[cp]):
        cp += 1
    if n <= cp or (line[cp] != "+" and line[cp] != "-"):
        return (name_begin, name_end, mail_begin, mail_end, None, None)
    tz_begin = cp
    span = 0
    cp = tz_begin + 1
    while cp + span < n and line[cp + span] in "0123456789":
        span += 1
    if span == 0:
        return (name_begin, name_end, mail_begin, mail_end, None, None)
    tz_end = tz_begin + 1 + span
    return (name_begin, name_end, mail_begin, mail_end, date_begin, tz_end)


def _fe_depth_first_sort(items):
    """Stable sort of (path, status) entries by fast-export's depth_first.

    Mirrors depth_first() in builtin/fast-export.c: compare the two names with
    memcmp over the shorter byte length; on an all-equal prefix the longer name
    sorts first (so 'd/e' precedes 'd'); ties are broken by moving 'R' (rename)
    entries last so a file is referenced before it is renamed.
    """
    import functools

    def cmp(a, b):
        na, sa = a
        nb, sb = b
        ba = na.encode("utf-8", "surrogateescape")
        bb = nb.encode("utf-8", "surrogateescape")
        common = min(len(ba), len(bb))
        c = (ba[:common] > bb[:common]) - (ba[:common] < bb[:common])
        if c:
            return c
        # len_b - len_a: the longer (deeper) path comes first.
        c = len(bb) - len(ba)
        if c:
            return -1 if c < 0 else 1
        # equal names: rename ('R') last.
        return (1 if sa == "R" else 0) - (1 if sb == "R" else 0)

    return sorted(items, key=functools.cmp_to_key(cmp))


