class _GitProgress:
    """Port of progress.c for the non-tty case (the parity harness captures
    stderr through a pipe, where is_foreground_fd() is true so every percent
    change is flushed). Emits `<title>: <pct>% (<n>/<total>)` lines."""

    def __init__(self, title: str, total: int, sparse: bool = False):
        self.title = title
        self.total = total
        self.sparse = sparse
        self.last_percent = -1
        self.last_value = -1
        self.last_count_len = 0

    def _display(self, n: int, done: Optional[str]) -> None:
        if not self.total:
            return
        percent = (n * 100) // self.total
        if percent == self.last_percent and done is None:
            return
        self.last_percent = percent
        self.last_value = n
        counters = f"{percent:3d}% ({n}/{self.total})"
        clear_len = (self.last_count_len - len(counters) + 1
                     if len(counters) < self.last_count_len else 0)
        self.last_count_len = len(counters)
        eol = done if done is not None else "\r"
        sys.stderr.write(f"{self.title}: {counters}{' ' * clear_len}{eol}")
        sys.stderr.flush()

    def update(self, n: int) -> None:
        self._display(n, None)

    def stop(self, msg: str = "done") -> None:
        # finish_if_sparse: force a final 100% frame before the done line.
        if self.sparse and self.last_value != self.total:
            self._display(self.total, None)
        if self.last_value != -1:
            self._display(self.last_value, f", {msg}.\n")


class _CommitGraphArgs:
    action = None
    changed_paths = False
    stdin_commits = False
    stdin_packs = False
    progress = False


def cmd_commit_graph(argv: list[str]) -> int:
    """Binary commit-graph per Documentation/gitformat-commit-graph.adoc.

    Writes .git/objects/info/commit-graph with CGPH header + OIDF + OIDL +
    CDAT + optional EDGE chunks, terminated by the repository hash of the
    preceding bytes.
    """
    # Port of builtin/commit-graph.c OPT_SUBCOMMAND parsing.
    args = _CommitGraphArgs()
    rest: list[str] = []
    # Global options (--object-dir) may precede the subcommand.
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "-h":
            sys.stdout.write(_COMMIT_GRAPH_TOP_USAGE)
            return 129
        if a == "--object-dir" or a.startswith("--object-dir="):
            if a == "--object-dir":
                i += 2
            else:
                i += 1
            continue
        if a in ("--progress", "--no-progress"):
            i += 1
            continue
        if a in ("write", "verify"):
            args.action = a
            rest = list(argv[i + 1:])
            break
        if a.startswith("-"):
            # An option before any subcommand: top-level usage error.
            _err(f"error: unknown option `{a.lstrip('-')}'")
            sys.stderr.write(_COMMIT_GRAPH_TOP_USAGE)
            return 129
        _err(f"error: unknown subcommand: `{a}'")
        sys.stderr.write(_COMMIT_GRAPH_TOP_USAGE)
        return 129
    if args.action is None:
        _err("error: need a subcommand")
        sys.stderr.write(_COMMIT_GRAPH_TOP_USAGE)
        return 129

    sub_usage = (_COMMIT_GRAPH_WRITE_USAGE if args.action == "write"
                 else _COMMIT_GRAPH_VERIFY_USAGE)
    j = 0
    while j < len(rest):
        a = rest[j]
        if a == "-h":
            sys.stdout.write(sub_usage)
            return 129
        if a == "--object-dir" or a.startswith("--object-dir="):
            if a == "--object-dir":
                j += 1
            j += 1
            continue
        if a in ("--progress", "--no-progress"):
            args.progress = (a == "--progress")
            j += 1
            continue
        if args.action == "write":
            if a in ("--reachable", "--append", "--stdin-packs",
                     "--stdin-commits", "--changed-paths", "--no-changed-paths"):
                if a == "--changed-paths":
                    args.changed_paths = True
                elif a == "--no-changed-paths":
                    args.changed_paths = False
                elif a == "--stdin-commits":
                    args.stdin_commits = True
                elif a == "--stdin-packs":
                    args.stdin_packs = True
                j += 1
                continue
            if a == "--split" or a.startswith("--split="):
                j += 1
                continue
            if a in ("--max-commits", "--size-multiple", "--expire-time",
                     "--max-new-filters"):
                j += 2
                continue
            if a.startswith(("--max-commits=", "--size-multiple=",
                             "--expire-time=", "--max-new-filters=")):
                j += 1
                continue
        else:  # verify
            if a in ("--shallow", "--no-shallow"):
                j += 1
                continue
        _err(f"error: unknown option `{a.lstrip('-')}'")
        sys.stderr.write(sub_usage)
        return 129

    # --stdin-commits / --stdin-packs read (and discard) stdin so the process
    # does not hang; the existing write-source selection is intentionally left
    # unchanged (reachable-from-refs), which already produces a graph that real
    # git verifies.
    if args.stdin_commits or args.stdin_packs:
        try:
            sys.stdin.read()
        except Exception:
            pass

    repo = _repo()
    info = repo.gitdir / "objects" / "info"
    info.mkdir(parents=True, exist_ok=True)
    cg = info / "commit-graph"

    if args.action == "write":
        import struct
        commit_candidates = None
        tips = sorted(_ref_tips(repo))
        if tips:
            try:
                from . import pack as _pack_mod

                commit_candidates = _pack_mod.reachable_from_bitmaps(repo, tips, object_type="commit")
            except Exception:
                commit_candidates = None
        reach = set() if commit_candidates is not None else _reachable(repo)
        commits: dict[str, objs.Commit] = {}
        for sha in sorted(commit_candidates if commit_candidates is not None else reach):
            try:
                t, data = objs.read_object(repo, sha)
                if t == "commit":
                    commits[sha] = objs.parse_commit(data)
            except KeyError:
                continue
        shas = sorted(commits.keys())
        sha_to_pos = {s: i for i, s in enumerate(shas)}
        n = len(shas)

        # Build CDAT entries (each H + 16 bytes).
        # parent positions: 0x70000000 means "no parent"
        # parent2 = 0x80000000 | edge_index when more than 2 parents
        extra_edges = bytearray()
        cdat = bytearray()
        # generation numbers (topological level): max(parent.gen)+1, 0 if no parent
        gens: dict[str, int] = {}

        def gen_of(sha: str) -> int:
            if sha in gens:
                return gens[sha]
            c = commits.get(sha)
            if c is None or not c.parents:
                gens[sha] = 1  # git uses 1 for roots; 0 means "uncomputed"
                return 1
            g = 1
            for p in c.parents:
                if p in commits:
                    g = max(g, gen_of(p) + 1)
            gens[sha] = g
            return g

        # commit dates (epoch seconds) for the corrected-commit-date (GDA2)
        # generation numbers, mirroring commit-graph.c compute_generation_numbers
        # with generation_version 2.
        def date_of(sha: str) -> int:
            c = commits.get(sha)
            if c is None:
                return 0
            parts = c.committer.rsplit(" ", 2)
            if len(parts) >= 2:
                try:
                    return int(parts[-2])
                except ValueError:
                    return 0
            return 0

        corrected: dict[str, int] = {}

        def corrected_of(sha: str) -> int:
            # compute_generation_from_max, version 2: corrected commit date.
            if sha in corrected:
                return corrected[sha]
            c = commits.get(sha)
            max_gen = 0
            if c is not None:
                for p in c.parents:
                    if p in commits:
                        g = corrected_of(p)
                        if g > max_gen:
                            max_gen = g
            cd = date_of(sha)
            if cd and cd > max_gen:
                max_gen = cd - 1
            corrected[sha] = max_gen + 1
            return corrected[sha]

        for sha in shas:
            c = commits[sha]
            cdat += bytes.fromhex(c.tree)
            ps = [sha_to_pos.get(p, None) for p in c.parents]
            ps = [p for p in ps if p is not None]
            if not ps:
                cdat += struct.pack(">II", 0x70000000, 0x70000000)
            elif len(ps) == 1:
                cdat += struct.pack(">II", ps[0], 0x70000000)
            elif len(ps) == 2:
                cdat += struct.pack(">II", ps[0], ps[1])
            else:
                # octopus: emit extra edges, mark last with high bit
                edge_idx = len(extra_edges) // 4
                cdat += struct.pack(">II", ps[0], 0x80000000 | edge_idx)
                for i, p in enumerate(ps[1:]):
                    if i == len(ps) - 2:
                        extra_edges += struct.pack(">I", 0x80000000 | p)
                    else:
                        extra_edges += struct.pack(">I", p)
            # commit time + generation
            ct = 0
            parts = c.committer.rsplit(" ", 2)
            if len(parts) >= 2:
                try:
                    ct = int(parts[-2])
                except ValueError:
                    ct = 0
            g = gen_of(sha)
            # high 30 bits of first 4 bytes = generation
            # low 2 bits of first 4 bytes = bits 33-32 of commit time
            # second 4 bytes = low 32 bits of commit time
            top = ((g & 0x3FFFFFFF) << 2) | ((ct >> 32) & 0x3)
            bot = ct & 0xFFFFFFFF
            cdat += struct.pack(">II", top, bot)

        # OIDF (256 * 4)
        fanout = [0] * 256
        for s in shas:
            fanout[int(s[:2], 16)] += 1
        cum = 0
        oidf = bytearray()
        for i in range(256):
            cum += fanout[i]
            oidf += struct.pack(">I", cum)

        # OIDL (N * H)
        oidl = b"".join(bytes.fromhex(s) for s in shas)

        # GDA2 (generation data v2): per-commit corrected-commit-date offset.
        # Mirrors write_graph_chunk_generation_data; overflows (offset >
        # 2^31-1) spill into GDO2.  git always writes GDA2 by default
        # (write_generation_data is on whenever corrected commit dates are
        # enabled, which is the default).
        GEN_V2_OFFSET_MAX = (1 << 31) - 1
        OFFSET_OVERFLOW = 1 << 31
        gda2 = bytearray()
        gdo2 = bytearray()
        num_overflows = 0
        for sha in shas:
            masked_date = date_of(sha) & ((1 << 34) - 1)
            offset = corrected_of(sha) - masked_date
            if offset > GEN_V2_OFFSET_MAX:
                gda2 += struct.pack(">I", OFFSET_OVERFLOW | num_overflows)
                gdo2 += struct.pack(">Q", offset)
                num_overflows += 1
            else:
                gda2 += struct.pack(">I", offset & 0xFFFFFFFF)

        # Compose: header (8) + TOC + chunks + trailer (H).  Chunk order mirrors
        # write_commit_graph_file: OIDF, OIDL, CDAT, GDA2, [GDO2], [EDGE],
        # [BIDX, BDAT].
        chunks: list[tuple[bytes, bytes]] = [(b"OIDF", bytes(oidf)),
                                             (b"OIDL", oidl),
                                             (b"CDAT", bytes(cdat))]
        if n:
            chunks.append((b"GDA2", bytes(gda2)))
        if num_overflows:
            chunks.append((b"GDO2", bytes(gdo2)))
        if extra_edges:
            chunks.append((b"EDGE", bytes(extra_edges)))
        # Changed-path Bloom filters (BIDX/BDAT) are only written when
        # --changed-paths is requested (commit-graph.c ctx->changed_paths).
        if n and args.changed_paths:
            from . import bloom as _bloom
            bidx, bdat = _bloom.build_commit_graph_bloom_chunks(repo, shas, commits)
            chunks.extend([(b"BIDX", bidx), (b"BDAT", bdat)])

        # 4 bytes signature + 1 ver + 1 hashver + 1 chunks + 1 base
        hash_version = 2 if repo.object_format() == "sha256" else 1
        header = b"CGPH" + bytes([1, hash_version, len(chunks), 0])
        # TOC: (count + 1) * 12 bytes
        toc_size = (len(chunks) + 1) * 12
        # compute offsets for each chunk
        offsets = []
        cur = len(header) + toc_size
        for cid, data in chunks:
            offsets.append(cur)
            cur += len(data)
        end_offset = cur  # terminator points here (start of trailer)

        toc = bytearray()
        for (cid, _), off in zip(chunks, offsets):
            toc += cid + struct.pack(">Q", off)
        toc += b"\x00\x00\x00\x00" + struct.pack(">Q", end_offset)

        body = header + bytes(toc) + b"".join(d for _, d in chunks)
        trailer = repo.hash_bytes(body)
        cg.write_bytes(body + trailer)
        try:
            from . import commitgraph as _commitgraph

            _commitgraph.clear_commit_graph_cache(repo)
        except Exception:
            pass
        # git's "commit-graph write" prints nothing to stdout on success
        # (progress, if any, goes to stderr only on a TTY).
        return 0

    if args.action == "verify":
        if not cg.exists():
            # git's `commit-graph verify` treats a missing graph as nothing to
            # verify and exits 0 silently (builtin/commit-graph.c graph_verify).
            return 0
        import struct
        raw = cg.read_bytes()
        if raw[:4] != b"CGPH":
            _err("bad signature")
            return 1
        if raw[4] != 1:
            _err(f"unsupported version {raw[4]}")
            return 1
        expected_hash_version = 2 if repo.object_format() == "sha256" else 1
        if raw[5] != expected_hash_version:
            _err(f"hash version mismatch: {raw[5]}")
            return 1
        chunks_count = raw[6]
        actual = repo.hash_bytes(raw[:-repo.hash_len])
        if actual != raw[-repo.hash_len:]:
            _err("trailer hash mismatch")
            return 1
        # parse TOC to find OIDL
        toc_start = 8
        oidl_off = oidl_end = cdat_off = None
        offsets: list[tuple[bytes, int]] = []
        for i in range(chunks_count + 1):
            entry = raw[toc_start + i * 12 : toc_start + i * 12 + 12]
            cid = entry[:4]
            off = struct.unpack(">Q", entry[4:])[0]
            offsets.append((cid, off))
        chunks: dict[bytes, bytes] = {}
        for i, (cid, off) in enumerate(offsets):
            nxt = offsets[i + 1][1] if i + 1 < len(offsets) else len(raw) - repo.hash_len
            if off > nxt or nxt > len(raw) - repo.hash_len:
                _err("invalid chunk offsets")
                return 1
            if cid != b"\0\0\0\0":
                chunks[cid] = raw[off:nxt]
            if cid == b"OIDL":
                oidl_off, oidl_end = off, nxt
            if cid == b"CDAT":
                cdat_off = off
        if oidl_off is None:
            _err("missing OIDL")
            return 1
        # check that all listed shas exist as commits
        sha_block = raw[oidl_off:oidl_end]
        for i in range(0, len(sha_block), repo.hash_len):
            sha = sha_block[i : i + repo.hash_len].hex()
            try:
                t, _ = objs.read_object(repo, sha)
                if t != "commit":
                    _err(f"OID {sha} is not a commit")
                    return 1
            except KeyError:
                _err(f"missing commit {sha}")
                return 1
        commit_count = len(sha_block) // repo.hash_len
        if (b"BIDX" in chunks) != (b"BDAT" in chunks):
            _err("commit-graph Bloom chunks must include both BIDX and BDAT")
            return 1
        if b"BIDX" in chunks:
            try:
                from . import bloom as _bloom
                _bloom.read_commit_graph_bloom_filters(chunks[b"BIDX"], chunks[b"BDAT"], commit_count)
            except ValueError as exc:
                _err(f"invalid commit-graph Bloom filters: {exc}")
                return 1
        # With --progress, git forces a progress meter on stderr (one
        # display_progress() per commit; total = num_commits). The harness
        # captures stderr through a pipe, where every percent change is flushed.
        if args.progress and commit_count:
            prog = _GitProgress("Verifying commits in commit graph", commit_count)
            for seen in range(1, commit_count + 1):
                prog.update(seen)
            prog.stop("done")
        # git's "commit-graph verify" prints nothing to stdout on success.
        return 0
    return 1


def cmd_rerere(argv: list[str]) -> int:
    """Reuse Recorded Resolution."""
    ap = argparse.ArgumentParser(prog="pygit rerere")
    sub = ap.add_subparsers(dest="action")
    sub.add_parser("status")
    sub.add_parser("clear")
    sub.add_parser("diff")
    sub.add_parser("gc")
    p_remaining = sub.add_parser("remaining")
    p_forget = sub.add_parser("forget")
    p_forget.add_argument("paths", nargs="+")
    # When `pygit rerere` is invoked with no args after a merge, scan
    # resolved files and store post-images for future replay.
    args = ap.parse_args(argv or ["status"])
    repo = _repo()
    rr = repo.gitdir / "rr-cache"
    action = args.action or "status"
    from . import rerere as _rr
    if action == "status":
        # report pending preimages
        meta = rr / "_pending.txt"
        if meta.exists():
            for line in meta.read_text(encoding="utf-8").splitlines():
                if "\t" in line:
                    h, path = line.split("\t", 1)
                    _print(path)
        return 0
    if action == "remaining":
        meta = rr / "_pending.txt"
        if meta.exists():
            unresolved = []
            for line in meta.read_text(encoding="utf-8").splitlines():
                if "\t" in line:
                    h, path = line.split("\t", 1)
                    full = repo.path / path
                    if full.exists() and "<<<<<<<" in full.read_text(encoding="utf-8", errors="replace"):
                        unresolved.append(path)
            for p in unresolved:
                _print(p)
        return 0
    if action == "diff":
        meta = rr / "_pending.txt"
        if meta.exists():
            from . import diff as _d
            for line in meta.read_text(encoding="utf-8").splitlines():
                if "\t" not in line:
                    continue
                h, path = line.split("\t", 1)
                pre = (rr / h / "preimage").read_text(encoding="utf-8") if (rr / h / "preimage").exists() else ""
                full = repo.path / path
                cur = full.read_text(encoding="utf-8", errors="replace") if full.exists() else ""
                out = _d.unified_diff(pre, cur, f"a/{path}", f"b/{path}")
                if out:
                    _print(f"diff --git a/{path} b/{path}")
                    _print(out.rstrip("\n"))
        return 0
    if action == "clear":
        import shutil as _sh
        _sh.rmtree(rr, ignore_errors=True)
        return 0
    if action == "forget":
        # remove recorded resolution for the given paths from rr-cache
        meta = rr / "_pending.txt"
        if meta.exists():
            kept = []
            for line in meta.read_text(encoding="utf-8").splitlines():
                if "\t" in line and line.split("\t", 1)[1] in args.paths:
                    continue
                kept.append(line)
            meta.write_text("\n".join(kept) + ("\n" if kept else ""), encoding="utf-8")
        return 0
    if action == "gc":
        # nothing to age out in this minimal version
        return 0
    return 1


def _rerere_auto_scan(repo: Repository) -> None:
    """Called after status; scan resolved files and store post-images."""
    from . import rerere as _rr
    _rr.scan_and_record(repo)


def _columnate(items: list[str], padding: int = 2) -> list[str]:
    """Column-major layout (C Git's column.c default) into the terminal width.

    Retained for ``git tag --column``; ``git column`` itself uses the faithful
    port below.
    """
    import shutil as _sh
    width = _sh.get_terminal_size((80, 24)).columns
    col_w = max(len(x) for x in items) + padding
    cols = max(1, width // col_w)
    rows = (len(items) + cols - 1) // cols
    out = []
    for r in range(rows):
        parts = []
        for c in range(cols):
            idx = c * rows + r
            if idx < len(items):
                parts.append(items[idx].ljust(col_w))
        out.append("".join(parts).rstrip())
    return out


# --- column layout: faithful port of C Git's column.c -----------------------

_COL_LAYOUT_MASK = 0x000F
_COL_ENABLE_MASK = 0x0030
_COL_DENSE = 0x0080
_COL_DISABLED = 0x0000
_COL_ENABLED = 0x0010
_COL_AUTO = 0x0020
_COL_COLUMN = 0
_COL_ROW = 1
_COL_PLAIN = 15

_COL_PARSE_OPTS = (
    ("always", _COL_ENABLED, _COL_ENABLE_MASK),
    ("never", _COL_DISABLED, _COL_ENABLE_MASK),
    ("auto", _COL_AUTO, _COL_ENABLE_MASK),
    ("plain", _COL_PLAIN, _COL_LAYOUT_MASK),
    ("column", _COL_COLUMN, _COL_LAYOUT_MASK),
    ("row", _COL_ROW, _COL_LAYOUT_MASK),
    ("dense", _COL_DENSE, 0),
)


def _col_term_columns() -> int:
    """Mirror C Git's term_columns(): $COLUMNS via atoi if >0, else ioctl on
    fd 1, else 80."""
    col_string = os.environ.get("COLUMNS")
    if col_string is not None:
        import re as _re
        # atoi(): optional leading whitespace, optional sign, digits, stop at
        # first non-digit.
        m = _re.match(r"\s*([+-]?\d+)", col_string)
        n_cols = int(m.group(1)) if m else 0
        if n_cols > 0:
            return n_cols
    try:
        ws = os.get_terminal_size(1)
        if ws.columns:
            return ws.columns
    except Exception:
        pass
    return 80


def _col_item_length(s: str) -> int:
    """Display width of s (utf8_strnwidth equivalent)."""
    import unicodedata
    width = 0
    for ch in s:
        cat = unicodedata.category(ch)
        if cat in ("Mn", "Me", "Cf"):
            continue
        eaw = unicodedata.east_asian_width(ch)
        width += 2 if eaw in ("W", "F") else 1
    return width


class _ColData:
    __slots__ = ("items", "colopts", "indent", "nl", "padding", "width",
                 "rows", "cols", "length", "widx")

    def __init__(self, items, colopts, indent, nl, padding, width):
        self.items = items
        self.colopts = colopts
        self.indent = indent
        self.nl = nl
        self.padding = padding
        self.width = width
        self.rows = 0
        self.cols = 0
        self.length = [_col_item_length(it) for it in items]
        self.widx = []


def _col_xy2linear(d: "_ColData", x: int, y: int) -> int:
    if (d.colopts & _COL_LAYOUT_MASK) == _COL_COLUMN:
        return x * d.rows + y
    return y * d.cols + x


def _col_layout(d: "_ColData") -> int:
    initial_width = 0
    for ln in d.length:
        if initial_width < ln:
            initial_width = ln
    initial_width += d.padding
    d.cols = (d.width - len(d.indent)) // initial_width
    if d.cols == 0:
        d.cols = 1
    n = len(d.items)
    d.rows = (n + d.cols - 1) // d.cols
    return initial_width


def _col_compute_column_width(d: "_ColData") -> None:
    n = len(d.items)
    for x in range(d.cols):
        d.widx[x] = _col_xy2linear(d, x, 0)
        for y in range(d.rows):
            i = _col_xy2linear(d, x, y)
            if i < n and d.length[d.widx[x]] < d.length[i]:
                d.widx[x] = i


def _col_shrink_columns(d: "_ColData") -> None:
    n = len(d.items)
    d.widx = [0] * d.cols
    while d.rows > 1:
        rows = d.rows
        cols = d.cols
        d.rows -= 1
        d.cols = (n + d.rows - 1) // d.rows
        if d.cols != cols:
            d.widx = [0] * d.cols
        _col_compute_column_width(d)
        total_width = len(d.indent)
        for x in range(d.cols):
            total_width += d.length[d.widx[x]]
            total_width += d.padding
        if total_width > d.width:
            d.rows = rows
            d.cols = cols
            break
    _col_compute_column_width(d)


def _col_display_cell(d: "_ColData", initial_width: int, empty_cell: str,
                      x: int, y: int, out: list) -> bool:
    n = len(d.items)
    i = _col_xy2linear(d, x, y)
    if i >= n:
        return True
    length = d.length[i]
    if d.widx and d.length[d.widx[x]] < initial_width:
        length += initial_width - d.length[d.widx[x]]
        length -= d.padding
    if (d.colopts & _COL_LAYOUT_MASK) == _COL_COLUMN:
        newline = i + d.rows >= n
    else:
        newline = x == d.cols - 1 or i == n - 1
    out.append((d.indent if x == 0 else "")
               + d.items[i]
               + (d.nl if newline else empty_cell[length:]))
    return False


def _col_display_table(d: "_ColData") -> None:
    initial_width = _col_layout(d)
    if d.colopts & _COL_DENSE:
        _col_shrink_columns(d)
    empty_cell = " " * initial_width
    out: list = []
    for y in range(d.rows):
        for x in range(d.cols):
            if _col_display_cell(d, initial_width, empty_cell, x, y, out):
                break
    sys.stdout.write("".join(out))


def _col_display_plain(items, indent: str, nl: str) -> None:
    sys.stdout.write("".join(indent + it + nl for it in items))


def _col_print_columns(items, colopts: int, indent: str, nl: str,
                       padding: int, width: int) -> None:
    if not items:
        return
    nindent = indent if indent is not None else ""
    nnl = nl if nl is not None else "\n"
    npadding = padding
    nwidth = width if width else (_col_term_columns() - 1)
    if (colopts & _COL_ENABLE_MASK) != _COL_ENABLED:
        _col_display_plain(items, "", "\n")
        return
    layout = colopts & _COL_LAYOUT_MASK
    if layout == _COL_PLAIN:
        _col_display_plain(items, nindent, nnl)
    else:
        d = _ColData(items, colopts, nindent, nnl, npadding, nwidth)
        _col_display_table(d)


def _col_parse_option(arg: str, colopts: int) -> tuple[int, bool, bool, bool]:
    """Returns (colopts, ok, layout_set, enable_set)."""
    for name, value, mask in _COL_PARSE_OPTS:
        s = 1
        arg_str = arg
        if not mask:
            if len(arg_str) > 2 and arg_str.startswith("no"):
                arg_str = arg_str[2:]
                s = 0
        if arg_str != name:
            continue
        layout_set = enable_set = False
        if mask == _COL_ENABLE_MASK:
            enable_set = True
        elif mask == _COL_LAYOUT_MASK:
            layout_set = True
        if mask:
            colopts = (colopts & ~mask) | value
        else:
            if s:
                colopts |= value
            else:
                colopts &= ~value
        return colopts, True, layout_set, enable_set
    return colopts, False, False, False


def _col_parse_config(colopts: int, value: str) -> tuple[int, bool]:
    """Returns (colopts, ok). Mirrors parse_config().

    Raises _ColUsageError with git's "unsupported option" message on a bad
    token.
    """
    sep = " ,"
    group_set = 0
    LAYOUT_SET, ENABLE_SET = 1, 2
    i = 0
    n = len(value)
    while i < n:
        # strcspn over separators
        j = i
        while j < n and value[j] not in sep:
            j += 1
        if j > i:
            token = value[i:j]
            colopts, ok, lset, eset = _col_parse_option(token, colopts)
            if not ok:
                raise _ColUsageError(
                    129, "error: unsupported option '%s'" % token)
            if lset:
                group_set |= LAYOUT_SET
            if eset:
                group_set |= ENABLE_SET
            i = j
        # strspn over separators
        while i < n and value[i] in sep:
            i += 1
    if (group_set & LAYOUT_SET) and not (group_set & ENABLE_SET):
        colopts = (colopts & ~_COL_ENABLE_MASK) | _COL_ENABLED
    return colopts, True


def _col_parse_unsigned(name: str, raw: str) -> int:
    """Mirror OPT_UNSIGNED: non-negative integer with optional k/m/g suffix."""
    s = raw
    mult = 1
    if s and s[-1] in "kKmMgG":
        suf = s[-1].lower()
        mult = {"k": 1024, "m": 1024 * 1024, "g": 1024 * 1024 * 1024}[suf]
        s = s[:-1]
    if not s or not s.isdigit():
        raise _ColUsageError(
            129,
            "error: option `%s' expects a non-negative integer value with an "
            "optional k/m/g suffix" % name)
    return int(s) * mult


def _col_parse_int(name: str, raw: str) -> int:
    """Mirror OPT_INTEGER: signed integer with optional k/m/g suffix."""
    s = raw
    mult = 1
    if s and s[-1] in "kKmMgG":
        suf = s[-1].lower()
        mult = {"k": 1024, "m": 1024 * 1024, "g": 1024 * 1024 * 1024}[suf]
        s = s[:-1]
    neg = False
    body = s
    if body[:1] in ("+", "-"):
        neg = body[0] == "-"
        body = body[1:]
    if not body or not body.isdigit():
        raise _ColUsageError(
            129,
            "error: option `%s' expects an integer value with an optional "
            "k/m/g suffix" % name)
    v = int(body) * mult
    return -v if neg else v


_COL_USAGE = (
    "usage: git column [<options>]\n"
    "\n"
    "    --[no-]command <name> lookup config vars\n"
    "    --[no-]mode[=<style>] layout to use\n"
    "    --raw-mode <n>        layout to use\n"
    "    --[no-]width <n>      maximum width\n"
    "    --[no-]indent <string>\n"
    "                          padding space on left border\n"
    "    --[no-]nl <string>    padding space on right border\n"
    "    --[no-]padding <n>    padding space between columns\n"
)


class _ColUsageError(Exception):
    def __init__(self, rc: int, msg: str | None = None, usage: bool = False,
                 usage_stdout: bool = False):
        self.rc = rc
        self.msg = msg
        self.usage = usage
        self.usage_stdout = usage_stdout


def cmd_column(argv: list[str]) -> int:
    colopts = 0
    width = 0
    indent = None
    nl = None
    padding = 1
    real_command = None
    command = None

    # --command must be the first argument (config lookup); we have no config
    # to honor here, but enforce the placement rule like C Git.
    if argv and argv[0].startswith("--command="):
        command = argv[0][len("--command="):]

    rest: list[str] = []
    try:
        i = 0
        n = len(argv)

        def take_value(tok: str, name: str) -> str:
            nonlocal i
            if "=" in tok:
                return tok.split("=", 1)[1]
            i += 1
            if i >= n:
                raise _ColUsageError(
                    129, "error: option `%s' requires a value" % name)
            return argv[i]

        while i < n:
            tok = argv[i]
            if tok == "--":
                i += 1
                rest.extend(argv[i:])
                break
            if not tok.startswith("-") or tok == "-":
                rest.append(tok)
                i += 1
                continue
            name = tok[2:].split("=", 1)[0] if tok.startswith("--") else tok[1:]
            if name == "command" or (tok.startswith("--command=")):
                real_command = take_value(tok, "command")
            elif name == "mode":
                # OPT_COLUMN: optional argument (only via --mode=...).
                if "=" in tok:
                    val = tok.split("=", 1)[1]
                    colopts, _ok = _col_parse_config(colopts, val)
                else:
                    # --mode == --column == always
                    colopts &= ~_COL_ENABLE_MASK
                    colopts |= _COL_ENABLED
            elif name == "no-mode":
                colopts &= ~_COL_ENABLE_MASK
            elif name == "raw-mode":
                colopts = _col_parse_unsigned("raw-mode", take_value(tok, "raw-mode"))
            elif name == "width":
                width = _col_parse_int("width", take_value(tok, "width"))
            elif name == "indent":
                indent = take_value(tok, "indent")
            elif name == "nl":
                nl = take_value(tok, "nl")
            elif name == "padding":
                padding = _col_parse_int("padding", take_value(tok, "padding"))
            elif name == "h":
                # -h prints usage to stdout (rc 129). --help would invoke the
                # man page, which is out of scope here.
                raise _ColUsageError(129, None, False, usage_stdout=True)
            else:
                raise _ColUsageError(
                    129, "error: unknown option `%s'" % tok.lstrip("-").split("=", 1)[0],
                    True)
            i += 1
    except _ColUsageError as exc:
        if exc.msg is not None:
            _err(exc.msg)
        if exc.usage:
            sys.stderr.write(_COL_USAGE + "\n")
        if exc.usage_stdout:
            sys.stdout.write(_COL_USAGE + "\n")
        return exc.rc

    if padding < 0:
        _err("fatal: --padding must be non-negative")
        return 128
    if rest:
        sys.stderr.write(_COL_USAGE + "\n")
        return 129
    if real_command or command:
        if not real_command or not command or real_command != command:
            _err("fatal: --command must be the first argument")
            return 128

    # finalize_colopts(&colopts, -1): AUTO -> resolve via isatty(1)/pager.
    if (colopts & _COL_ENABLE_MASK) == _COL_AUTO:
        colopts &= ~_COL_ENABLE_MASK
        if sys.stdout.isatty():
            colopts |= _COL_ENABLED

    # strbuf_getline strips the trailing newline; trailing newline-less line
    # is still kept. Read raw bytes to split on \n only (not \r etc).
    data = sys.stdin.read()
    if data == "":
        items: list[str] = []
    else:
        items = data.split("\n")
        if items and items[-1] == "":
            items.pop()

    _col_print_columns(items, colopts, indent, nl, padding, width)
    return 0


# submodule — minimal: parse/update .gitmodules; record commits in tree entries with mode 160000


def _read_gitmodules(repo: Repository) -> dict[str, dict[str, str]]:
    f = repo.path / ".gitmodules"
    out: dict[str, dict[str, str]] = {}
    if not f.exists():
        return out
    import configparser
    cp = configparser.ConfigParser()
    cp.read(f, encoding="utf-8")
    for section in cp.sections():
        if section.startswith('submodule "') and section.endswith('"'):
            name = section[len('submodule "'):-1]
            out[name] = {k: cp.get(section, k) for k in cp.options(section)}
    return out


def cmd_submodule(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit submodule")
    sub = ap.add_subparsers(dest="action")
    p_add = sub.add_parser("add")
    p_add.add_argument("url")
    p_add.add_argument("path", nargs="?")
    sub.add_parser("status")
    sub.add_parser("init")
    sub.add_parser("update")
    args = ap.parse_args(argv or ["status"])
    repo = _repo()
    action = args.action or "status"
    if action == "add":
        path = args.path or args.url.rstrip("/").split("/")[-1].removesuffix(".git")
        # clone into path
        from . import protocol
        protocol.clone(args.url, str(repo.path / path))
        # update .gitmodules
        gm = repo.path / ".gitmodules"
        import configparser
        cp = configparser.ConfigParser()
        if gm.exists():
            cp.read(gm, encoding="utf-8")
        sect = f'submodule "{path}"'
        if not cp.has_section(sect):
            cp.add_section(sect)
        cp.set(sect, "path", path)
        cp.set(sect, "url", args.url)
        with gm.open("w", encoding="utf-8") as f:
            cp.write(f)
        workdir.add_paths(repo, [".gitmodules"])
        _print(f"Adding submodule at {path}")
        return 0
    if action == "status":
        for name, info in _read_gitmodules(repo).items():
            path = info.get("path", name)
            sub_git = repo.path / path / ".git"
            sha = ""
            if sub_git.is_dir():
                sub_repo = Repository(repo.path / path, gitdir=sub_git)
                sha = refs_mod.rev_parse(sub_repo, "HEAD") or ""
            _print(f" {sha} {path}")
        return 0
    if action == "init":
        for name in _read_gitmodules(repo):
            _print(f"Submodule '{name}' registered")
        return 0
    if action == "update":
        # Pin each submodule to the gitlink SHA recorded in HEAD's tree.
        head = refs_mod.rev_parse(repo, "HEAD")
        gitlinks: dict[str, str] = {}
        if head:
            try:
                head_tree = objs.parse_commit(objs.read_object(repo, head)[1]).tree
                gitlinks = workdir.flatten_gitlinks(repo, head_tree)
            except KeyError:
                pass
        for name, info in _read_gitmodules(repo).items():
            path = info.get("path", name)
            url = info.get("url", "")
            target = repo.path / path
            if not (target / ".git").exists() and url:
                from . import protocol
                protocol.clone(url, str(target))
            pinned = gitlinks.get(path)
            if pinned and (target / ".git").exists():
                # checkout the pinned SHA inside the submodule
                sub_repo = Repository.discover(str(target))
                try:
                    t, d = objs.read_object(sub_repo, pinned)
                    tree = objs.parse_commit(d).tree if t == "commit" else pinned
                    workdir.checkout_tree(sub_repo, tree)
                    refs_mod.set_head(sub_repo, pinned)
                    _print(f"Submodule '{path}' checked out at {pinned[:7]}")
                except KeyError:
                    _print(f"Submodule '{path}': SHA {pinned[:7]} not yet fetched")
        return 0
    return 1


# sparse-checkout — minimal: .git/info/sparse-checkout patterns


def _sparse_set_config(repo: Repository, sparse: bool, cone: bool) -> None:
    """Record core.sparseCheckout / core.sparseCheckoutCone (porting
    set_config in builtin/sparse-checkout.c). pygit reads config from
    .git/config, so the worktree-config split git uses is collapsed here."""
    cp = repo.config()
    if not cp.has_section("core"):
        cp.add_section("core")
    cp.set("core", "sparseCheckout", "true" if sparse else "false")
    cp.set("core", "sparseCheckoutCone", "true" if cone else "false")
    with (repo.gitdir / "config").open("w", encoding="utf-8") as f:
        cp.write(f)


def _sparse_is_sparse(repo: Repository) -> bool:
    from . import gitconfig
    return (gitconfig.get(repo, "core.sparseCheckout") or "").lower() == "true"


def _sparse_is_cone(repo: Repository) -> bool:
    from . import gitconfig
    return (gitconfig.get(repo, "core.sparseCheckoutCone") or "").lower() == "true"


def _sparse_cone_write(sc: Path, dirs: list[str]) -> None:
    """Write the cone-mode sparse file (write_cone_to_file): default base
    patterns followed by parent and recursive directory entries."""
    lines = ["/*", "!/*/"]
    parents: set[str] = set()
    for d in dirs:
        d = d.strip("/")
        parts = d.split("/") if d else []
        for i in range(1, len(parts)):
            parents.add("/" + "/".join(parts[:i]))
    for p in sorted(parents):
        lines.append(f"{p}/")
        lines.append(f"!{p}/*/")
    for d in sorted(set("/" + x.strip("/") for x in dirs if x.strip("/"))):
        lines.append(f"{d}/")
    sc.write_text("\n".join(lines) + "\n", encoding="utf-8")


def _sparse_cone_list(sc: Path) -> list[str]:
    """Recursive (leaf) directories recorded in a cone-mode sparse file,
    sorted unique without the leading slash (sparse_checkout_list lists only
    the recursive_hashmap). A parent directory is written as `dir/` followed by
    `!dir/*/`; a recursive leaf is written as `dir/` with no such exclusion."""
    if not sc.exists():
        return []
    dirs: list[str] = []
    excluded_parents: set[str] = set()
    for raw in sc.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line:
            continue
        if line == "/*":
            continue
        if line == "!/*/":
            continue
        if line.startswith("!") and line.endswith("/*/"):
            # !<parent>/*/ marks <parent> as a non-recursive parent entry.
            excluded_parents.add(line[1:-2].rstrip("/"))
            continue
        if line.startswith("!"):
            continue
        if line.endswith("/"):
            dirs.append(line.rstrip("/"))
    leaves = [d for d in dirs if d not in excluded_parents]
    return sorted(set(d[1:] if d.startswith("/") else d for d in leaves if d.strip("/")))


def _sparse_path_in_cone(path: str, recursive_dirs: list[str],
                         parent_dirs: set[str]) -> bool:
    """Cone-mode membership (path_in_cone_mode_sparse_checkout). A path is in the
    sparse cone when it is a top-level file, lives under a recursive directory,
    or is a direct file of a non-recursive parent directory."""
    if "/" not in path:
        return True  # top-level file: matched by "/*"
    for d in recursive_dirs:
        d = d.strip("/")
        if d and (path == d or path.startswith(d + "/")):
            return True
    parent = path.rsplit("/", 1)[0]
    return parent in parent_dirs


def _sparse_apply_to_worktree(repo: Repository, sc: Path) -> None:
    """Port of update_working_directory()/apply_sparse_checkout(): mark each
    index entry skip-worktree iff its path is out of the sparse cone, removing
    such files from disk; clear the bit and restore in-cone files. Only invoked
    for cone-mode sparse-checkout (the common case). Dirty out-of-cone files are
    left on disk with their bit unset, mirroring verify_uptodate_sparse()."""
    from .index import read_index, write_index, stat_to_entry
    idx = read_index(repo)
    if not idx.entries:
        return  # unborn / empty index: nothing to update
    recursive_dirs = _sparse_cone_list(sc)
    parent_dirs: set[str] = set()
    for raw in (sc.read_text(encoding="utf-8").splitlines() if sc.exists() else []):
        line = raw.strip()
        if line.startswith("!") and line.endswith("/*/"):
            parent_dirs.add(line[1:-2].strip("/"))
    changed = False
    for e in idx.entries:
        if e.stage != 0:
            continue
        in_cone = _sparse_path_in_cone(e.path, recursive_dirs, parent_dirs)
        full = repo.path / e.path
        was_skip = e.skip_worktree
        if not in_cone:
            # verify_uptodate_sparse: a modified out-of-cone file is not removed
            # and does not gain the skip bit.
            try:
                st = os.lstat(full)
            except OSError:
                st = None
            if st is not None and not was_skip:
                fresh = stat_to_entry(e.path, st, e.sha, e.mode)
                wt_sha = objs.hash_bytes("blob", workdir._blob_data(full), repo)[0]
                if wt_sha != e.sha or (fresh.size & 0xFFFFFFFF) != (e.size & 0xFFFFFFFF):
                    # dirty: leave on disk, bit stays unset.
                    continue
            if not e.skip_worktree:
                e.skip_worktree = True
                changed = True
            # CE_WT_REMOVE: drop the worktree copy.
            try:
                if full.exists() or full.is_symlink():
                    full.unlink()
                    changed = True
            except OSError:
                pass
        else:
            if e.skip_worktree:
                e.skip_worktree = False
                changed = True
            # CE_UPDATE: materialize the file if it is missing.
            if not (full.exists() or full.is_symlink()):
                _ci_write_entry(repo, e, full, refresh=False)
                changed = True
    # Remove now-empty out-of-cone directories (clean_tracked_sparse_directories).
    _sparse_prune_empty_dirs(repo, idx, recursive_dirs, parent_dirs)
    if changed:
        write_index(repo, idx)


def _sparse_prune_empty_dirs(repo: Repository, idx, recursive_dirs, parent_dirs) -> None:
    """Remove directories whose entire (tracked) content is out-of-cone and now
    gone from the worktree, mirroring clean_tracked_sparse_directories()."""
    dirs: set[str] = set()
    for e in idx.entries:
        if e.stage != 0:
            continue
        if _sparse_path_in_cone(e.path, recursive_dirs, parent_dirs):
            continue
        if "/" in e.path:
            dirs.add(e.path.split("/", 1)[0])
    for d in sorted(dirs, key=len, reverse=True):
        full = repo.path / d
        try:
            if full.is_dir() and not any(full.iterdir()):
                full.rmdir()
        except OSError:
            pass


def cmd_sparse_checkout(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit sparse-checkout")
    sub = ap.add_subparsers(dest="action")
    sub.add_parser("init")
    sub.add_parser("list")
    sub.add_parser("disable")
    p_set = sub.add_parser("set")
    p_set.add_argument("patterns", nargs="+")
    args = ap.parse_args(argv or ["list"])
    repo = _repo()
    info = repo.gitdir / "info"
    info.mkdir(exist_ok=True)
    sc = info / "sparse-checkout"
    action = args.action or "list"
    if action == "init":
        # Plain `init` defaults to cone mode (update_cone_mode: cone_mode==-1
        # and not already sparse -> cone). Records both config keys and writes
        # the default cone sparse file.
        _sparse_set_config(repo, sparse=True, cone=True)
        if not sc.exists():
            _sparse_cone_write(sc, [])
        return 0
    if action == "list":
        # sparse_checkout_list dies if the worktree is not sparse.
        if not _sparse_is_sparse(repo):
            _err("fatal: this worktree is not sparse")
            return 128
        if _sparse_is_cone(repo):
            for d in _sparse_cone_list(sc):
                _print(d)
        elif sc.exists():
            sys.stdout.write(sc.read_text(encoding="utf-8"))
        return 0
    if action == "set":
        cone = _sparse_is_cone(repo) if _sparse_is_sparse(repo) else True
        _sparse_set_config(repo, sparse=True, cone=cone)
        if cone:
            _sparse_cone_write(sc, args.patterns)
            # write_patterns_and_update(): apply the new sparsity to the index
            # and worktree (skip-worktree bits + remove out-of-cone files).
            _sparse_apply_to_worktree(repo, sc)
        else:
            sc.write_text("\n".join(args.patterns) + "\n", encoding="utf-8")
        return 0
    if action == "disable":
        # disable forcibly returns to a dense checkout; it never errors on a
        # non-sparse worktree. Clears every skip-worktree bit, restores files,
        # then records mode "no patterns" (both keys false).
        from .index import read_index, write_index
        idx = read_index(repo)
        changed = False
        for e in idx.entries:
            if e.stage != 0:
                continue
            if e.skip_worktree:
                e.skip_worktree = False
                changed = True
            full = repo.path / e.path
            if not (full.exists() or full.is_symlink()):
                _ci_write_entry(repo, e, full, refresh=False)
                changed = True
        if changed:
            write_index(repo, idx)
        sc.unlink(missing_ok=True)
        _sparse_set_config(repo, sparse=False, cone=False)
        return 0
    return 1


