# Phase 7 — diff-tree / diff-files / diff-index / check-attr /
#           check-ref-format / check-mailmap / show-index / unpack-file /
#           merge-index / get-tar-commit-id / hook / credential


def _diff_tree_changes_with_dirs(repo: Repository, a_tree, b_tree, prefix: str = "", recurse: bool = True):
    """Like workdir.iter_tree_changes but also yields changed directory (tree)
    nodes (parent before children). With recurse=False, yields only the
    top-level changed entries (dirs shown as tree nodes) — git's diff-tree
    default without -r; recurse=True is the `diff-tree -t -r` form."""
    if a_tree == b_tree:
        return
    from . import workdir as _wd
    a_entries = {e.name: e for e in _wd._tree_entries(repo, a_tree)} if a_tree else {}
    b_entries = {e.name: e for e in _wd._tree_entries(repo, b_tree)} if b_tree else {}
    for name in sorted(set(a_entries) | set(b_entries)):
        a = a_entries.get(name)
        b = b_entries.get(name)
        path = f"{prefix}{name}"
        if a is not None and b is not None and a.sha == b.sha and a.mode == b.mode:
            continue
        a_dir = a is not None and a.is_dir()
        b_dir = b is not None and b.is_dir()
        if not recurse:
            yield path, a, b
            continue
        if a_dir and b_dir:
            yield path, a, b
            yield from _diff_tree_changes_with_dirs(repo, a.sha, b.sha, path + "/")
        elif b_dir and a is None:
            yield path, None, b
            yield from _diff_tree_changes_with_dirs(repo, None, b.sha, path + "/")
        elif a_dir and b is None:
            yield path, a, None
            yield from _diff_tree_changes_with_dirs(repo, a.sha, None, path + "/")
        else:
            yield path, a, b


def _raw_diff_status(a_mode: str, b_mode: str, a_sha: Optional[str], b_sha: Optional[str], path: str) -> str:
    """Emit a 'raw diff' format line: ':MODE_A MODE_B SHA_A SHA_B STATUS\\tpath'."""
    null_oid = "0" * max(len(a_sha or ""), len(b_sha or ""), 40)
    if a_sha is None:
        return f":000000 {b_mode} {null_oid} {b_sha} A\t{path}"
    if b_sha is None:
        return f":{a_mode} 000000 {a_sha} {null_oid} D\t{path}"
    if a_sha == b_sha and a_mode == b_mode:
        return ""
    return f":{a_mode} {b_mode} {a_sha} {b_sha} M\t{path}"


def cmd_diff_tree(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit diff-tree", add_help=False)
    ap.add_argument("-r", action="store_true", help="recurse")
    ap.add_argument("-t", dest="show_trees", action="store_true")
    ap.add_argument("-p", "--patch", action="store_true")
    ap.add_argument("-U", "--unified", type=int, default=3)
    ap.add_argument("--inter-hunk-context", dest="inter_hunk_context", type=int, default=0)
    ap.add_argument("--root", action="store_true")
    ap.add_argument("--no-commit-id", dest="no_commit_id", action="store_true")
    ap.add_argument("--name-only", action="store_true")
    ap.add_argument("--name-status", action="store_true")
    ap.add_argument("rev1")
    ap.add_argument("rev2", nargs="?")
    ap.add_argument("paths", nargs="*")
    args = ap.parse_args([a for a in argv if a != "--"])
    repo = _repo()

    def _resolve_to_tree(name: str) -> Optional[str]:
        s = refs_mod.rev_parse(repo, name)
        if not s:
            return None
        t, data = objs.read_object(repo, s)
        if t == "commit":
            return objs.parse_commit(data).tree
        if t == "tag":
            for line in data.decode(errors="replace").splitlines():
                if line.startswith("object "):
                    return _resolve_to_tree(line[len("object "):].strip())
        return s  # already a tree

    if args.rev2 is None:
        # treat rev1 as commit; diff against its first parent
        s = refs_mod.rev_parse(repo, args.rev1)
        if not s:
            return 128
        c = objs.parse_commit(objs.read_object(repo, s)[1])
        # A merge has only a combined diff, which is empty for a clean merge and
        # suppressed by default — git emits nothing at all (not even the id).
        if len(c.parents) > 1:
            return 0
        b_tree = c.tree
        a_tree = (objs.parse_commit(objs.read_object(repo, c.parents[0])[1]).tree
                  if c.parents else None)
        if not args.no_commit_id:
            _print(s)
    else:
        a_tree = _resolve_to_tree(args.rev1)
        b_tree = _resolve_to_tree(args.rev2)
    if not b_tree:
        return 128
    if args.show_trees:
        # -t recurses into changed trees (even without -r), showing tree nodes.
        changes = list(_diff_tree_changes_with_dirs(repo, a_tree, b_tree, recurse=True))
    elif not args.r:
        # Without -r, diff-tree lists only the top-level changed entries
        # (directories shown as tree nodes), not their contents.
        changes = list(_diff_tree_changes_with_dirs(repo, a_tree, b_tree, recurse=False))
    else:
        changes = list(workdir.iter_tree_changes(repo, a_tree, b_tree))
    for p, a_entry, b_entry in changes:
        a_sha = a_entry.sha if a_entry else None
        b_sha = b_entry.sha if b_entry else None
        a_mode = (a_entry.mode if a_entry else "100644").zfill(6)
        b_mode = (b_entry.mode if b_entry else "100644").zfill(6)
        if a_sha == b_sha and a_mode == b_mode:
            continue
        if args.name_only:
            _print(p)
        elif args.name_status:
            if a_sha is None:
                _print(f"A\t{p}")
            elif b_sha is None:
                _print(f"D\t{p}")
            else:
                _print(f"M\t{p}")
        elif not args.patch:
            ln = _raw_diff_status(a_mode, b_mode, a_sha, b_sha, p)
            if ln:
                _print(ln)
    if args.patch:
        sel = changes
        if args.paths:
            wanted = set(args.paths)
            sel = [(p, a, b) for (p, a, b) in changes
                   if p in wanted or any(p.startswith(w.rstrip("/") + "/") for w in args.paths)]
        for p, a_entry, b_entry in sel:
            a_side = _side_from_object(repo, a_entry.mode, a_entry.sha) if a_entry else _ABSENT
            b_side = _side_from_object(repo, b_entry.mode, b_entry.sha) if b_entry else _ABSENT
            _emit_file_diff(p, a_side, b_side, context=args.unified,
                            inter_hunk_context=args.inter_hunk_context)
    return 0


class _DFPair:
    """A diff-files filepair (index side `one`, worktree side `two`). For a
    rename/copy the two sides have different paths; ``score`` carries the
    rename/copy/break similarity (0 = none); ``status`` is the resolved letter."""
    __slots__ = ("a_path", "b_path", "one", "two", "status", "score", "broken",
                 "two_oid_valid")

    def __init__(self, a_path, b_path, one, two, status, score=0, broken=False):
        self.a_path = a_path
        self.b_path = b_path
        self.one = one          # _Side (index/source)
        self.two = two          # _Side (worktree/dest)
        self.status = status    # 'M','A','D','R','C','T'
        self.score = score
        self.broken = broken
        # When rename/copy detection runs, every destination filespec is hashed
        # (find_exact_renames), so its worktree oid becomes valid and is shown
        # in raw output even for an unmatched addition.
        self.two_oid_valid = False


def _df_extract_value(argv, i, opt):
    """Helper for parsing diff-files options that take a separate-or-attached
    value (-S/-G/-O). Returns (value, next_index) or raises on missing."""
    a = argv[i]
    if len(a) > len(opt):
        return a[len(opt):], i + 1
    if i + 1 < len(argv):
        return argv[i + 1], i + 2
    return None, i + 1


def _emit_combined_unmerged(buf, repo, path, parent_oids, parent_modes, present,
                            dense, fmt_patch, fmt_raw, name_only, name_status,
                            full_index, abbrev, nul, context=3,
                            combined_all_paths=False):
    """Render one unmerged path's combined diff (show_combined_diff dispatch).

    RAW/NAME/NAME-STATUS take precedence over PATCH (combine-diff.c). The result
    oid is always null (worktree result), parents are stages #2/#3."""
    from . import combine
    num_parent = len(parent_oids)
    if fmt_raw or name_only or name_status:
        # show_raw_diff: combined raw line / name / name-status.
        raw_width = 40 if (full_index or abbrev is None) else max(4, abbrev)
        result_mode = combine._canon_mode_from_content(repo, path) if present else 0
        line_term = b"\0" if nul else b"\n"
        rfmt = "name" if name_only else ("name-status" if name_status else "raw")
        combine.show_raw_combined(
            buf, path, parent_oids, parent_modes, ["M"] * num_parent,
            "0" * 40, result_mode, num_parent, raw_width,
            fmt=rfmt, line_term=line_term,
            combined_all_paths=combined_all_paths)
        return
    if fmt_patch:
        result_content = None
        if present:
            full = repo.path / path
            if full.is_symlink():
                result_content = os.readlink(full).encode("utf-8", "surrogateescape")
            else:
                try:
                    result_content = full.read_bytes()
                except OSError:
                    result_content = None
        header_abbrev = 40 if full_index else 7
        combine.show_patch_diff_files(
            buf, repo, path, parent_oids, parent_modes,
            result_content if result_content is not None else b"",
            present and result_content is not None,
            dense, header_abbrev, context=context,
            combined_all_paths=combined_all_paths)
        return
    # stat/numstat/shortstat: show_combined_diff emits nothing for these.
    return


def cmd_diff_files(argv: list[str]) -> int:
    """Show the diff between the index and the working tree (plumbing)."""
    import io
    ap = argparse.ArgumentParser(prog="pygit diff-files", add_help=False)
    ap.add_argument("--name-only", dest="name_only", action="store_true")
    ap.add_argument("--name-status", dest="name_status", action="store_true")
    ap.add_argument("--raw", dest="raw", action="store_true")
    ap.add_argument("--stat", action="store_true")
    ap.add_argument("--numstat", action="store_true")
    ap.add_argument("--shortstat", action="store_true")
    ap.add_argument("-p", "-u", "--patch", dest="patch", action="store_true")
    ap.add_argument("--patch-with-raw", dest="patch_with_raw", action="store_true")
    ap.add_argument("--patch-with-stat", dest="patch_with_stat", action="store_true")
    ap.add_argument("-R", dest="reverse", action="store_true")
    ap.add_argument("-z", dest="nul", action="store_true")
    ap.add_argument("--abbrev", nargs="?", const=7, type=int, default=None)
    ap.add_argument("--full-index", dest="full_index", action="store_true")
    ap.add_argument("-a", "--text", dest="text", action="store_true")
    ap.add_argument("-q", "--quiet", action="store_true")
    ap.add_argument("-U", "--unified", type=int, default=3)
    ap.add_argument("--inter-hunk-context", dest="inter_hunk_context", type=int, default=0)
    # rename/copy/break/pickaxe/order/limit options
    ap.add_argument("--no-renames", dest="no_renames", action="store_true")
    ap.add_argument("--find-copies-harder", dest="find_copies_harder", action="store_true")
    ap.add_argument("--pickaxe-all", dest="pickaxe_all", action="store_true")
    ap.add_argument("--pickaxe-regex", dest="pickaxe_regex", action="store_true")
    ap.add_argument("paths", nargs="*")

    from . import diffcore
    argv = ["--abbrev=7" if a == "--abbrev" else a for a in argv]
    # Pre-scan to peel off the diffcore-style flags whose value semantics differ
    # from argparse (attached -M50/-Sneedle, separate -S needle / -O file, etc.).
    rest: list[str] = []
    detect_rename = None        # None=off, 'M'=renames, 'C'=copies
    rename_score = 0            # 0 = default threshold
    break_opt = None            # None = no -B
    pickaxe = None
    pickaxe_kind = None         # 'S' or 'G'
    orderfile = None
    rename_limit = -1           # OPT_INTEGER default before diff std sets 1000
    # Combined-diff / stage-selection flags (combine-diff.c + builtin/diff-files.c).
    # combine_merges/dense mirror -c/--cc; max_count is the stage to diff against
    # (-1 = unset -> defaults to 2; --base/--ours/--theirs = 1/2/3).
    combine_merges = False
    dense_combined = False
    combined_all_paths = False
    max_count = -1
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "-c":
            combine_merges, dense_combined = True, False
            i += 1
            continue
        if a == "--combined-all-paths":
            combined_all_paths = True
            i += 1
            continue
        if a == "--cc":
            combine_merges, dense_combined = True, True
            i += 1
            continue
        if a in ("-0", "-1", "-2", "-3"):
            max_count = int(a[1:])
            i += 1
            continue
        if a == "--base":
            max_count = 1
            i += 1
            continue
        if a == "--ours":
            max_count = 2
            i += 1
            continue
        if a == "--theirs":
            max_count = 3
            i += 1
            continue
        if a == "-M" or a == "--find-renames" or a.startswith("-M") or a.startswith("--find-renames="):
            if a.startswith("--find-renames="):
                val = a.split("=", 1)[1]
            elif a == "-M" or a == "--find-renames":
                val = None
            else:
                val = a[2:]
            sc, err = diffcore.parse_rename_score(val)
            if sc is None:
                _err("error: invalid argument to find-renames")
                return 129
            detect_rename = "M"
            rename_score = sc
            i += 1
            continue
        if a == "-C" or a == "--find-copies" or a.startswith("-C") or a.startswith("--find-copies="):
            if a.startswith("--find-copies="):
                val = a.split("=", 1)[1]
            elif a == "-C" or a == "--find-copies":
                val = None
            else:
                val = a[2:]
            sc, err = diffcore.parse_rename_score(val)
            if sc is None:
                _err("error: invalid argument to find-copies")
                return 129
            detect_rename = "C"
            rename_score = sc
            i += 1
            continue
        if a == "-B" or a == "--break-rewrites" or a.startswith("-B") or a.startswith("--break-rewrites="):
            if a.startswith("--break-rewrites="):
                val = a.split("=", 1)[1]
            elif a == "-B" or a == "--break-rewrites":
                val = None
            else:
                val = a[2:]
            bo, err = diffcore.parse_break_opt(val)
            if bo is None:
                _err(f"error: {err}")
                return 129
            break_opt = bo
            i += 1
            continue
        if a == "-S" or a.startswith("-S"):
            val, ni = _df_extract_value(argv, i, "-S")
            if val is None:
                _err("error: switch `S' requires a value")
                return 129
            pickaxe, pickaxe_kind = val, "S"
            i = ni
            continue
        if a == "-G" or a.startswith("-G"):
            val, ni = _df_extract_value(argv, i, "-G")
            if val is None:
                _err("error: switch `G' requires a value")
                return 129
            pickaxe, pickaxe_kind = val, "G"
            i = ni
            continue
        if a == "-O" or a.startswith("-O"):
            val, ni = _df_extract_value(argv, i, "-O")
            if val is None:
                _err("error: switch `O' requires a value")
                return 129
            orderfile = val
            i = ni
            continue
        if a == "-l" or a.startswith("-l"):
            if len(a) > 2:
                lv = a[2:]
                i += 1
            elif i + 1 < len(argv):
                lv = argv[i + 1]
                i += 2
            else:
                _err("error: switch `l' requires a value")
                return 129
            try:
                rename_limit = int(lv)
            except ValueError:
                _err("error: switch `l' expects an integer value with an "
                     "optional k/m/g suffix")
                return 129
            continue
        rest.append(a)
        i += 1

    args = ap.parse_args(rest)
    if args.no_renames:
        detect_rename = None
    repo = _repo()
    from .index import read_index
    idx = read_index(repo)

    # Determine the effective output format (combine-diff dispatch order mirrors
    # show_combined_diff: RAW/NAME/NAME-STATUS take precedence over PATCH). For
    # a bare `-c`/`--cc` (no explicit format) the merge implies a patch.
    fmt_patch = bool(args.patch or args.patch_with_raw or args.patch_with_stat)
    explicit_fmt = (args.raw or args.name_only or args.name_status or args.stat or
                    args.numstat or args.shortstat or fmt_patch)
    fmt_raw = (args.raw or not explicit_fmt)
    if combine_merges and not explicit_fmt:
        # `-c`/`--cc` with no explicit format implies a (combined) patch.
        fmt_patch = True
        fmt_raw = False
    # --combined-all-paths requires -c/--cc. This is checked in
    # diff_merges_setup_revs (BEFORE the patch densify below), so an implicit
    # densified `-p` does not satisfy it.
    if combined_all_paths and not combine_merges:
        _err("fatal: --combined-all-paths makes no sense without -c or --cc")
        return 128
    # "diff-files -p" on unmerged paths densifies to --cc unless -c/--cc given
    # explicitly (builtin/diff-files.c:diff_merges_set_dense_combined_if_unset).
    if (max_count == -1 and fmt_patch and not combine_merges):
        combine_merges = True
        dense_combined = True

    # Build index-vs-worktree filepairs. Intent-to-add entries are treated as
    # new files (ita_invisible_in_index), so their index side is absent.
    pairs: list[_DFPair] = []
    all_index: dict[str, tuple[int, str]] = {}   # path -> (mode, sha) for copy sources
    # Combined diffs for unmerged paths are written immediately (during the
    # cache walk in run_diff_files), before any queued regular pairs are flushed.
    combined_buf = io.BytesIO()
    diff_unmerged_stage = max_count if max_count >= 0 else 2
    # ce_path_match (run_diff_files line 147): a cache entry whose path is not
    # matched by the pathspec is skipped entirely (no combined diff / U pair).
    _ps = list(args.paths)
    def _ce_path_match(p):
        if not _ps:
            return True
        return (p in _ps or
                any(p.startswith(w.rstrip("/") + "/") for w in _ps))
    entries = idx.entries
    n_entries = len(entries)
    ei = 0
    while ei < n_entries:
        e = entries[ei]
        if getattr(e, "stage", 0) != 0:
            # Gather all consecutive stage entries for this path.
            path = e.path
            stage_entries: dict[int, "object"] = {}
            ce = e  # entry selected for the worktree comparison (default stage 2)
            full = repo.path / path
            present = full.exists() or full.is_symlink()
            wt_mode = _wt_mode(full) if present else "000000"
            num_compare_stages = 0
            while ei < n_entries and entries[ei].path == path and entries[ei].stage != 0:
                nce = entries[ei]
                st = nce.stage
                stage_entries[st] = nce
                if st >= 2:
                    num_compare_stages += 1
                if st == diff_unmerged_stage:
                    ce = nce
                ei += 1
            if not _ce_path_match(path):
                continue
            if combine_merges and num_compare_stages == 2:
                # show_combined_diff(dpath, 2): parents are stages #2 (ours) and
                # #3 (theirs); the result is the working-tree file.
                p_oids = [stage_entries[2].sha, stage_entries[3].sha]
                p_modes = [int(stage_entries[2].mode_str(), 8),
                           int(stage_entries[3].mode_str(), 8)]
                _emit_combined_unmerged(
                    combined_buf, repo, path, p_oids, p_modes, present,
                    dense_combined, fmt_patch, fmt_raw, args.name_only,
                    args.name_status, args.full_index, args.abbrev, args.nul,
                    context=args.unified, combined_all_paths=combined_all_paths)
                continue
            # Non-combined: queue the unmerge ('U') pair, then optionally the
            # worktree-vs-selected-stage comparison pair.
            two = _Side(wt_mode if present else None, "0" * 40, None,
                        worktree=True) if present else _Side(None, "0" * 40, None)
            upair = _DFPair(path, path, _ABSENT, two, "U")
            pairs.append(upair)
            if ce.stage != diff_unmerged_stage:
                continue
            # Compare the selected stage's blob against the worktree. An unmerged
            # cache entry has zeroed stat data, so run_diff_files always treats it
            # as changed: the raw line is shown unconditionally (worktree oid is
            # null), while the patch is empty when the content is identical
            # (builtin_diff emits no header). A removed worktree file -> 'D'.
            a = _side_from_object(repo, ce.mode_str(), ce.sha)
            b = _side_from_worktree(repo, path) if present else _ABSENT
            status = "A" if not a.present else ("D" if not b.present else "M")
            pairs.append(_DFPair(path, path, a, b, status))
            continue
        full = repo.path / e.path
        present = full.exists() or full.is_symlink()
        ita = getattr(e, "intent_to_add", False)
        a = _ABSENT if ita else _side_from_object(repo, e.mode_str(), e.sha)
        b = _side_from_worktree(repo, e.path) if present else _ABSENT
        if not ita:
            all_index[e.path] = (int(e.mode_str(), 8), e.sha)
        ei += 1
        if a.sha == b.sha and a.mode == b.mode:
            continue
        status = "A" if not a.present else ("D" if not b.present else "M")
        pairs.append(_DFPair(e.path, e.path, a, b, status))

    # -R reverses the diff: each pair's two sides are swapped BEFORE diffcore
    # runs (diff.c applies reverse_diff at queue-build time), so rename/copy/
    # break detection sees the reversed source/destination roles.
    if args.reverse:
        for p in pairs:
            if p.status == "U":
                continue  # an unmerged pair has no direction to reverse
            p.one, p.two = p.two, p.one
            p.status = "A" if not p.one.present else ("D" if not p.two.present else "M")

    # --- diffcore pipeline: break -> rename/copy -> merge_broken -> pickaxe
    #     -> order ---
    if break_opt is not None:
        pairs = _df_break(repo, pairs, break_opt)
    if detect_rename is not None:
        pairs = _df_detect_renames(repo, pairs, all_index, detect_rename,
                                   rename_score, rename_limit,
                                   args.find_copies_harder)
    if break_opt is not None:
        pairs = _df_merge_broken(pairs)
    if pickaxe is not None:
        pairs = _df_pickaxe(repo, pairs, pickaxe, pickaxe_kind,
                            args.pickaxe_all, args.pickaxe_regex, args.text,
                            args.unified)
    if orderfile is not None:
        rc = _df_order(pairs, orderfile)
        if rc is not None:
            return rc

    if args.paths:
        wanted = set(args.paths)
        def _match(p):
            return (p.b_path in wanted or p.a_path in wanted or
                    any(p.b_path.startswith(w.rstrip("/") + "/") or
                        p.a_path.startswith(w.rstrip("/") + "/") for w in args.paths))
        pairs = [p for p in pairs if _match(p)]
    # -q is a no-op in diff-files (it is not --quiet); output is unaffected.

    # Separate rename/copy pairs (they render as 'src => dst' in stat output)
    # from plain (path, a, b) changes used by the stat helpers. Broken (-B)
    # complete-rewrite M pairs (score>0) count as full file delete+add.
    rn = [(p.a_path, p.b_path, int(p.score * 100 / 60000.0), p.one, p.two)
          for p in pairs if p.status in ("R", "C")]
    cr = {id(p): (_count_lines(p.two.data or b""), _count_lines(p.one.data or b""))
          for p in pairs if p.status == "M" and p.score}
    # Unmerged ('U') pairs are excluded from the plain-change set: they render as
    # "<path> | Unmerged" in --stat (never counted), "0\t0\t<path>" in --numstat,
    # and are dropped from --shortstat totals (diff.c builtin_diffstat/show_*).
    changes = [(p.b_path, p.one, p.two) for p in pairs
               if p.status not in ("R", "C", "U")]
    um_paths = [p.b_path for p in pairs if p.status == "U"]
    cr_counts = {p.b_path: cr[id(p)] for p in pairs if id(p) in cr}
    # Stat output applies diffcore_skip_stat_unmatch: a pair that is dirty only by
    # stat (both sides valid, one oid unknown, same mode, identical content) is
    # dropped from --stat/--numstat/--shortstat (but kept in raw/patch). The only
    # such pairs here are unmerged comparison pairs whose worktree matches the
    # selected stage; stage-0 pairs are already content-filtered.
    def _stat_unmatch(p):
        # Binary pairs are always shown in --stat ("Bin") even when identical, so
        # only non-binary stat-only-dirty pairs are dropped.
        return (p.status == "M" and p.one.present and p.two.present and
                p.two.worktree and p.one.sha == p.two.sha and
                p.one.mode == p.two.mode and
                not _is_binary(p.one.data) and not _is_binary(p.two.data))
    stat_changes = [(p.b_path, p.one, p.two) for p in pairs
                    if p.status not in ("R", "C", "U") and not _stat_unmatch(p)]
    # Queue order (by destination path) so stat/numstat interleave renames and
    # plain changes the way the diff queue does.
    order = {p.b_path: i for i, p in enumerate(pairs)}

    # Immediate combined diffs (written during the cache walk in C) precede all
    # queued regular pairs. They carry their own format, so flush the buffer
    # before the format dispatch below.
    combined_bytes = combined_buf.getvalue()

    # Sides are already oriented for -R (pre-swapped), so the stat helpers see
    # the correct direction and naturally flip insertions/deletions. Unmerged
    # ('U') pairs render as "<path> | Unmerged" and never count toward totals.
    if args.stat or args.patch_with_stat:
        if combined_bytes:
            sys.stdout.flush()
            sys.stdout.buffer.write(combined_bytes)
        _diff_stat(stat_changes, rn, cr_counts, order=order,
                   unmerged=[(order.get(p, len(order)), p) for p in um_paths])
        if not args.patch_with_stat:
            return 0
    if args.numstat:
        _diff_numstat(stat_changes, rn, nul=args.nul, complete=cr_counts, order=order,
                      unmerged=[(order.get(p, len(order)), p) for p in um_paths])
        return 0
    if args.shortstat:
        _diff_shortstat(stat_changes, rn, complete=cr_counts, n_unmerged=len(um_paths))
        return 0
    sep = "\0" if args.nul else "\t"
    term = "\0" if args.nul else "\n"
    if combined_bytes:
        sys.stdout.flush()
        sys.stdout.buffer.write(combined_bytes)
        sys.stdout.buffer.flush()
    if args.name_only:
        for p in pairs:
            sys.stdout.write(p.b_path + term)
        return 0
    if args.name_status:
        for p in pairs:
            sys.stdout.write(_df_name_status(p, sep, args.reverse) + term)
        return 0
    # fmt_patch is also set when `-c`/`--cc` (or densified `-p`) implies a patch
    # without an explicit -p. When BOTH raw and patch bits are present (e.g.
    # `--raw -p`), diff_flush emits the raw block, a blank line, then the patch
    # (the --patch-with-raw layout). fmt_raw alone -> raw only; fmt_patch alone
    # -> patch only.
    if fmt_patch:
        if (fmt_raw or args.patch_with_raw) and pairs:
            for p in pairs:
                sys.stdout.write(_df_raw_line(p, args.abbrev, args.full_index, args.reverse, sep))
            _print("")
        for p in pairs:
            _df_emit_patch(p, args.reverse, args.unified, args.inter_hunk_context)
        return 0
    # Default: the raw diff line per change.
    for p in pairs:
        sys.stdout.write(_df_raw_line(p, args.abbrev, args.full_index, args.reverse, sep))
    return 0


def _df_break(repo: Repository, pairs: list["_DFPair"], break_opt: int) -> list["_DFPair"]:
    """Port of diffcore_break: split in-place edits that are complete rewrites
    into delete+create broken pairs (score below merge_score is zeroed)."""
    from . import diffcore
    merge_score = (break_opt >> 16) & 0xFFFF or diffcore.DEFAULT_MERGE_SCORE
    break_score = (break_opt & 0xFFFF) or diffcore.DEFAULT_BREAK_SCORE
    out: list[_DFPair] = []
    for p in pairs:
        if (p.one.present and p.two.present and p.a_path == p.b_path and
                p.status == "M"):
            # Supply data directly: the worktree side's oid is not in the store.
            src = diffcore.Filespec(repo, p.a_path, p.one.sha, int(p.one.mode, 8),
                                    data=p.one.data if p.one.worktree else None)
            dst = diffcore.Filespec(repo, p.b_path, p.two.sha, int(p.two.mode, 8),
                                    data=p.two.data if p.two.worktree else None)
            do_break, score = diffcore.should_break(repo, src, dst, break_score)
            if do_break:
                if score < merge_score:
                    score = 0
                # deletion of one
                out.append(_DFPair(p.a_path, p.a_path, p.one, _ABSENT, "D",
                                   score=score, broken=True))
                # creation of two
                out.append(_DFPair(p.b_path, p.b_path, _ABSENT, p.two, "A",
                                   score=score, broken=True))
                continue
        out.append(p)
    return out


def _df_merge_broken(pairs: list["_DFPair"]) -> list["_DFPair"]:
    """Port of diffcore_merge_broken: a broken delete+create pair that survived
    rename/copy with its peer still present (same path) merges back to one M."""
    out: list[_DFPair] = []
    used = [False] * len(pairs)
    for i, p in enumerate(pairs):
        if used[i]:
            continue
        if p.broken and p.a_path == p.b_path:
            peer = -1
            for j in range(i + 1, len(pairs)):
                q = pairs[j]
                if used[j]:
                    continue
                if q.broken and q.a_path == q.b_path and q.b_path == p.a_path:
                    peer = j
                    break
            if peer >= 0:
                q = pairs[peer]
                # one is the delete half (one valid), other is create half.
                d = p if p.one.present else q
                c = q if p.one.present else p
                merged = _DFPair(d.a_path, c.b_path, d.one, c.two, "M",
                                 score=p.score, broken=True)
                out.append(merged)
                used[peer] = True
                continue
        out.append(p)
    return out


def _df_detect_renames(repo: Repository, pairs: list["_DFPair"], all_index: dict,
                       mode: str, rename_score: int, rename_limit: int,
                       find_copies_harder: bool) -> list["_DFPair"]:
    """Run rename/copy detection over the broken/plain pairs and rewrite matched
    deletions+additions into R/C pairs. Emits the rename-limit warning when the
    inexact matrix is skipped."""
    from . import diffcore
    src_map: dict[str, tuple[int, str]] = {}
    dst_map: dict[str, tuple[int, str]] = {}
    by_dst: dict[str, _DFPair] = {}
    by_src: dict[str, _DFPair] = {}
    src_side_map: dict[str, _Side] = {}     # path -> source-side _Side
    data_map: dict[str, bytes] = {}         # worktree blob content by path
    for p in pairs:
        if p.status == "U":
            continue  # unmerged pairs are inert in diffcore-rename
        if p.one.present and not p.two.present:
            src_map[p.a_path] = (int(p.one.mode, 8), p.one.sha)
            by_src[p.a_path] = p
            src_side_map[p.a_path] = p.one
            # A worktree-side source (under -R) has an unstored oid; supply its
            # content so similarity estimation can read it.
            if p.one.worktree:
                data_map[p.a_path] = p.one.data or b""
        elif p.two.present and not p.one.present:
            dst_map[p.b_path] = (int(p.two.mode, 8), p.two.sha)
            by_dst[p.b_path] = p
            data_map[p.b_path] = p.two.data or b""
    if not dst_map:
        return pairs

    copy_sources: dict[str, tuple[int, str]] = {}
    if mode == "C":
        # Copy sources = modified entries (their index/original blob). With
        # --find-copies-harder, every unmodified index entry is a source too.
        for p in pairs:
            if p.one.present and p.two.present and p.a_path == p.b_path:
                copy_sources[p.a_path] = (int(p.one.mode, 8), p.one.sha)
                src_side_map[p.a_path] = p.one
        if find_copies_harder:
            modified = {p.a_path for p in pairs}
            for path, (m, sha) in all_index.items():
                if path not in modified and path not in src_map:
                    copy_sources[path] = (m, sha)
                    src_side_map[path] = _side_from_object(repo, f"{m:06o}", sha)

    eff_limit = 1000 if rename_limit < 0 else rename_limit
    detect_copies = (mode == "C")
    # If detection has any source to consider, every destination filespec gets
    # hashed (find_exact_renames), so its worktree oid is shown in raw output.
    has_sources = bool(src_map) or (detect_copies and bool(copy_sources))
    if has_sources:
        for dp in by_dst.values():
            dp.two_oid_valid = True
    detected, needed = diffcore.detect_renames_copies(
        repo, src_map, dst_map,
        copy_sources=copy_sources if detect_copies else None,
        data_map=data_map, want_copies=detect_copies,
        rename_limit=eff_limit, minimum_score=rename_score)

    if needed > 0:
        _err("warning: exhaustive rename detection was skipped due to too many files.")
        _err("warning: you may want to set your diff.renameLimit variable to at "
             f"least {needed} and retry the command.")

    # Map each matched destination path to its resolved rename/copy pair, and
    # collect consumed source paths (renames drop their deletion record).
    rename_by_dst: dict[str, _DFPair] = {}
    matched_src: set[str] = set()
    for rp in detected:
        sp = rp.src.path
        dp = rp.dst.path
        src_side = src_side_map.get(
            sp, _side_from_object(repo, f"{rp.src.mode:06o}", rp.src.oid))
        dst_side = by_dst[dp].two if dp in by_dst else _ABSENT
        status = "C" if rp.is_copy else "R"
        rename_by_dst[dp] = _DFPair(sp, dp, src_side, dst_side, status,
                                    score=rp.score)
        if not rp.is_copy:
            matched_src.add(sp)

    # Write back in the original queue order: a creation that became a
    # rename/copy destination is replaced in place; a deletion consumed as a
    # rename source is dropped (diffcore-rename.c write-back).
    out: list[_DFPair] = []
    for p in pairs:
        if p.two.present and not p.one.present and p.b_path in rename_by_dst:
            out.append(rename_by_dst[p.b_path])
            continue
        if p.one.present and not p.two.present and p.a_path in matched_src:
            continue
        out.append(p)
    return out


def _df_pickaxe(repo: Repository, pairs: list["_DFPair"], needle: str, kind: str,
                pickaxe_all: bool, pickaxe_regex: bool, text: bool,
                context: int) -> list["_DFPair"]:
    """Port of diffcore_pickaxe: keep only pairs where the needle changes count
    (-S) or matches a +/- line (-G). --pickaxe-all shows the whole set if any
    pair matches."""
    import re as _re
    regexp = None
    if kind == "G" or pickaxe_regex:
        regexp = _re.compile(needle.encode("utf-8", "replace"), _re.MULTILINE)

    def _contains(data: bytes) -> int:
        if not data:
            return 0
        if regexp is not None:
            cnt = 0
            pos = 0
            while pos <= len(data):
                m = regexp.search(data, pos)
                if not m:
                    break
                cnt += 1
                if m.end() == m.start():
                    pos = m.end() + 1
                else:
                    pos = m.end()
            return cnt
        nd = needle.encode("utf-8", "replace")
        if not nd:
            return 0
        cnt = 0
        pos = 0
        while True:
            k = data.find(nd, pos)
            if k < 0:
                break
            cnt += 1
            pos = k + len(nd)
        return cnt

    def _has_changes(a: _Side, b: _Side) -> bool:
        c1 = _contains(a.data or b"") if a.present else 0
        c2 = _contains(b.data or b"") if b.present else 0
        return c1 != c2

    def _diff_grep(a: _Side, b: _Side) -> bool:
        if (not text and ((a.present and _is_binary(a.data)) or
                          (b.present and _is_binary(b.data)))):
            return False
        a_text = (a.data or b"").decode("utf-8", "replace") if a.present else ""
        b_text = (b.data or b"").decode("utf-8", "replace") if b.present else ""
        a_lines = a_text.splitlines()
        b_lines = b_text.splitlines()
        for kind2, ai, bi in diff_mod.diff_lines(a_lines, b_lines):
            if kind2 == "ins":
                if regexp.search(b_lines[bi].encode("utf-8", "replace")):
                    return True
            elif kind2 == "del":
                if regexp.search(a_lines[ai].encode("utf-8", "replace")):
                    return True
        return False

    def _match(p: _DFPair) -> bool:
        if p.status == "U":
            return True  # unmerged pairs are always kept by diffcore-pickaxe
        if not p.one.present and not p.two.present:
            return False
        # unmodified pair (same content) never matches
        if (p.one.present and p.two.present and p.one.sha == p.two.sha):
            return False
        if kind == "G":
            if (not text and ((p.one.present and _is_binary(p.one.data)) or
                              (p.two.present and _is_binary(p.two.data)))):
                return False
            return _diff_grep(p.one, p.two)
        return _has_changes(p.one, p.two)

    if pickaxe_all:
        for p in pairs:
            if _match(p):
                return pairs
        return []
    return [p for p in pairs if _match(p)]


def _df_order(pairs: list["_DFPair"], orderfile: str):
    """Port of diffcore_order: reorder pairs by orderfile pattern match against
    the destination path (stable within an order index)."""
    import fnmatch
    try:
        with open(orderfile, "rb") as f:
            raw = f.read()
    except IsADirectoryError:
        _err(f"fatal: failed to read orderfile '{orderfile}': Is a directory")
        return 128
    except FileNotFoundError:
        _err(f"fatal: failed to read orderfile '{orderfile}': No such file or directory")
        return 128
    except OSError as e:
        _err(f"fatal: failed to read orderfile '{orderfile}': {e.strerror}")
        return 128
    patterns: list[str] = []
    for line in raw.decode("utf-8", "replace").split("\n"):
        if line == "" or line.startswith("#"):
            continue
        patterns.append(line)

    def _wildmatch(pat: str, path: str) -> bool:
        # git wildmatch: '*' does not cross '/', but diffcore-order also tries
        # successive leading-directory strips. Use fnmatch on each strip.
        p = path
        while p:
            if fnmatch.fnmatch(p, pat):
                return True
            k = p.rfind("/")
            if k < 0:
                break
            p = p[:k]
        return False

    def _match_order(path: str) -> int:
        for idx, pat in enumerate(patterns):
            if _wildmatch(pat, path):
                return idx
        return len(patterns)

    decorated = [(_match_order(p.b_path), orig, p) for orig, p in enumerate(pairs)]
    decorated.sort(key=lambda t: (t[0], t[1]))
    pairs[:] = [t[2] for t in decorated]
    return None


def _df_name_status(p: "_DFPair", sep: str, reverse: bool) -> str:
    # Sides are pre-swapped for -R, so the status letter is already correct.
    if p.status in ("R", "C"):
        sim = int(p.score * 100 / 60000.0)
        return f"{p.status}{sim:03d}{sep}{p.a_path}{sep}{p.b_path}"
    st = p.status
    if p.score:
        st = f"{st}{int(p.score * 100 / 60000.0):03d}"
    return st + sep + p.b_path


def _df_raw_id(side: "_Side", width: int, oid_valid: bool) -> str:
    """The raw-output object id for one side: the working-tree side reads zero
    unless its oid was made valid by rename/copy detection."""
    zero = "0" * width
    if not side.present or side.sha is None:
        return zero
    if side.worktree and not oid_valid:
        return zero
    return side.sha if width >= 40 else side.sha[:width]


def _df_raw_line(p: "_DFPair", abbrev: Optional[int], full_index: bool,
                 reverse: bool, sep: str) -> str:
    """Render a diff-files raw line ':MODE MODE ID ID STATUS<sep>path[...]'.
    The working-tree side id is zero unless rename/copy detection hashed it."""
    width = 40 if (full_index or abbrev is None) else max(4, abbrev)
    a_mode = p.one.mode if p.one.present else "000000"
    b_mode = p.two.mode if p.two.present else "000000"
    term = "\0" if sep == "\0" else "\n"
    if p.status in ("R", "C"):
        # Both sides of a rename/copy are hashed during detection, so their
        # real (possibly worktree-computed) oids are always shown.
        a_id = _df_raw_id(p.one, width, True)
        b_id = _df_raw_id(p.two, width, True)
        sim = int(p.score * 100 / 60000.0)
        return (f":{a_mode} {b_mode} {a_id} {b_id} {p.status}{sim:03d}"
                f"{sep}{p.a_path}{sep}{p.b_path}{term}")
    a_id = _df_raw_id(p.one, width, p.two_oid_valid)
    b_id = _df_raw_id(p.two, width, p.two_oid_valid)
    st = p.status
    if p.score:
        st = f"{st}{int(p.score * 100 / 60000.0):03d}"
    return f":{a_mode} {b_mode} {a_id} {b_id} {st}{sep}{p.b_path}{term}"


def _df_emit_patch(p: "_DFPair", reverse: bool, context: int,
                   inter_hunk_context: int = 0) -> None:
    """Emit a diff-files patch for one pair, including rename/copy headers and
    the -B 'dissimilarity index' header. Sides are pre-swapped for -R, so only
    the a/b prefix labels are flipped here."""
    pa, pb = ("b", "a") if reverse else ("a", "b")
    if p.status == "U":
        # An unmerged pair in patch format (run_diff -> DIFF_PAIR_UNMERGED).
        _print(f"* Unmerged path {p.b_path}")
        return
    if p.status in ("R", "C"):
        src, dst = p.a_path, p.b_path
        sim = int(p.score * 100 / 60000.0)
        _print(f"diff --git {pa}/{src} {pb}/{dst}")
        verb = "copy" if p.status == "C" else "rename"
        _print(f"similarity index {sim}%")
        _print(f"{verb} from {src}")
        _print(f"{verb} to {dst}")
        a_side, b_side = p.one, p.two
        if a_side.sha == b_side.sha and a_side.mode == b_side.mode:
            return
        a_abbrev = (a_side.sha or "0" * 40)[:7]
        b_abbrev = (b_side.sha or "0" * 40)[:7]
        suffix = f" {b_side.mode}" if a_side.mode == b_side.mode else ""
        _print(f"index {a_abbrev}..{b_abbrev}{suffix}")
        if _is_binary(a_side.data) or _is_binary(b_side.data):
            _print(f"Binary files {pa}/{src} and {pb}/{dst} differ")
            return
        a_text = (a_side.data or b"").decode("utf-8", "replace")
        b_text = (b_side.data or b"").decode("utf-8", "replace")
        _print(f"--- {pa}/{src}")
        _print(f"+++ {pb}/{dst}")
        for line in diff_mod.format_hunks_ex(
                a_text.splitlines(), b_text.splitlines(), context,
                a_no_newline=bool(a_text) and not a_text.endswith("\n"),
                b_no_newline=bool(b_text) and not b_text.endswith("\n"),
                inter_hunk_context=inter_hunk_context):
            _print(line)
        return
    # M/A/D, possibly broken (-B) with a dissimilarity index.
    if p.score and p.status == "M":
        _df_emit_dissimilar(p, pa, pb, context)
        return
    # Plain change: sides already oriented; pass prefixes, no further reverse.
    _emit_file_diff(p.b_path, p.one, p.two, False, context,
                    a_prefix=pa, b_prefix=pb,
                    inter_hunk_context=inter_hunk_context)


def _count_lines(data: bytes) -> int:
    """Port of diff.c count_lines: count newlines, +1 for a final line lacking a
    trailing newline; 0 for completely empty content."""
    if not data:
        return 0
    count = data.count(b"\n")
    if not data.endswith(b"\n"):
        count += 1
    return count


def _add_line_count(count: int) -> str:
    if count == 0:
        return "0,0"
    if count == 1:
        return "1"
    return f"1,{count}"


def _df_emit_dissimilar(p: "_DFPair", pa: str, pb: str, context: int) -> None:
    """Emit a -B broken (complete-rewrite) M patch: a 'dissimilarity index' line
    and a single hunk deleting the whole old file and adding the whole new file
    (diff.c emit_rewrite_diff)."""
    a, b = p.one, p.two
    path = p.b_path
    sim = int(p.score * 100 / 60000.0)
    _print(f"diff --git {pa}/{path} {pb}/{path}")
    _print(f"dissimilarity index {sim}%")
    a_abbrev = (a.sha or "0" * 40)[:7]
    b_abbrev = (b.sha or "0" * 40)[:7]
    suffix = f" {a.mode}" if a.mode == b.mode else ""
    _print(f"index {a_abbrev}..{b_abbrev}{suffix}")
    if _is_binary(a.data) or _is_binary(b.data):
        _print(f"Binary files {pa}/{path} and {pb}/{path} differ")
        return
    a_data = a.data or b""
    b_data = b.data or b""
    lc_a = _count_lines(a_data)
    lc_b = _count_lines(b_data)
    _print(f"--- {pa}/{path}")
    _print(f"+++ {pb}/{path}")
    _print(f"@@ -{_add_line_count(lc_a)} +{_add_line_count(lc_b)} @@")
    a_text = a_data.decode("utf-8", "replace")
    b_text = b_data.decode("utf-8", "replace")
    if lc_a:
        for ln in a_text.splitlines():
            _print(f"-{ln}")
        if a_text and not a_text.endswith("\n"):
            _print("\\ No newline at end of file")
    if lc_b:
        for ln in b_text.splitlines():
            _print(f"+{ln}")
        if b_text and not b_text.endswith("\n"):
            _print("\\ No newline at end of file")


def cmd_diff_index(argv: list[str]) -> int:
    """Show diff between a tree and the index (--cached) or the working tree."""
    ap = argparse.ArgumentParser(prog="pygit diff-index")
    ap.add_argument("--cached", action="store_true")
    ap.add_argument("--name-only", action="store_true")
    ap.add_argument("tree")
    args = ap.parse_args(argv)
    repo = _repo()
    tsha = refs_mod.rev_parse(repo, args.tree)
    if not tsha:
        return 128
    t, data = objs.read_object(repo, tsha)
    if t == "commit":
        tsha = objs.parse_commit(data).tree
    a_map = _tree_map_full(repo, tsha)
    from .index import read_index
    idx = read_index(repo).by_path()
    zero = "0" * 40
    for p in sorted(set(a_map) | set(idx)):
        a = _side_from_object(repo, *a_map[p]) if p in a_map else _ABSENT
        # The "b" side comes from the index. Without --cached, its blob id is
        # zeroed when the working tree is dirty relative to the index (matching
        # git, which can't name an uncommitted worktree blob).
        b_present = p in idx
        b_mode = idx[p].mode_str() if b_present else None
        b_sha = idx[p].sha if b_present else None
        b_dirty = False
        if b_present and not args.cached:
            wt = _side_from_worktree(repo, p)
            if not wt.present:
                b_present, b_mode, b_sha = False, None, None
            else:
                b_dirty = wt.sha != idx[p].sha
        if a.present and b_present and a.sha == b_sha and not b_dirty and a.mode == b_mode:
            continue
        if not a.present and not b_present:
            continue
        if args.name_only:
            _print(p)
            continue
        status = "A" if not a.present else ("D" if not b_present else "M")
        out_a = a.sha if a.present else zero
        out_b = zero if (b_dirty or not b_present) else b_sha
        _print(f":{(a.mode or '000000')} {(b_mode or '000000')} {out_a} {out_b} {status}\t{p}")
    return 0


# ---- check-attr: a focused port of git's attr.c ----------------------------
# Attribute value sentinels (attr.c ATTR__TRUE/FALSE/UNSET/UNKNOWN).
_ATTR_TRUE = object()
_ATTR_FALSE = object()
_ATTR_UNSET = object()
_ATTR_UNKNOWN = object()

# builtin_attr[] from attr.c (bottom of the attribute stack).
_BUILTIN_ATTR = ["[attr]binary -diff -merge -text"]


def _attr_name_valid(name: str) -> bool:
    """Port of attr.c attr_name_valid: non-empty, not starting with '-',
    characters limited to [-A-Za-z0-9_.]."""
    if not name or name[0] == "-":
        return False
    for ch in name:
        if not (ch == "-" or ch == "." or ch == "_"
                or "0" <= ch <= "9" or "a" <= ch <= "z" or "A" <= ch <= "Z"):
            return False
    return True


def _attr_name_reserved(name: str) -> bool:
    return name.startswith("builtin_")


class _AttrState:
    __slots__ = ("attr", "setto")

    def __init__(self, attr: str, setto):
        self.attr = attr
        self.setto = setto


class _MatchAttr:
    __slots__ = ("is_macro", "macro_name", "pattern", "regex", "nodir",
                 "mustbedir", "states")

    def __init__(self):
        self.is_macro = False
        self.macro_name = None
        self.pattern = None
        self.regex = None
        self.nodir = False
        self.mustbedir = False
        self.states = []


def _attr_intern(name: str, order: list[str]) -> None:
    """Record first-seen attribute registration order (attr_nr)."""
    if name not in order:
        order.append(name)


def _parse_attr_token(tok: str):
    """Parse one whitespace-delimited attr state token. Returns (name, setto)
    or None if the name is invalid."""
    if tok.startswith("-"):
        name, setto = tok[1:], _ATTR_FALSE
    elif tok.startswith("!"):
        name, setto = tok[1:], _ATTR_UNSET
    elif "=" in tok:
        name, _, val = tok.partition("=")
        setto = val
    else:
        name, setto = tok, _ATTR_TRUE
    if not _attr_name_valid(name) or _attr_name_reserved(name):
        return None
    return name, setto


def _parse_attr_line(line: str, order: list[str]):
    """Port of attr.c parse_attr_line (with READ_ATTR_MACRO_OK). Returns a
    _MatchAttr, or None for blank/comment/invalid lines."""
    s = line
    stripped = s.lstrip(" \t\r\n")
    if not stripped or stripped[0] == "#":
        return None
    ma = _MatchAttr()
    rest = stripped
    # Pattern token (quoted patterns are uncommon; handle the simple case).
    if rest.startswith('"'):
        try:
            name = _unquote_c_style(rest)
            states = ""
        except Exception:
            name = rest.split()[0]
            states = rest[len(name):]
    else:
        name = rest.split(None, 1)[0]
        states = rest[len(name):]
    macro_prefix = "[attr]"
    if name.startswith(macro_prefix) and len(name) > len(macro_prefix):
        ma.is_macro = True
        mname = name[len(macro_prefix):].strip()
        # macro name is the first whitespace-delimited token
        mname = mname.split()[0] if mname.split() else mname
        if not _attr_name_valid(mname) or _attr_name_reserved(mname):
            return None
        ma.macro_name = mname
        _attr_intern(mname, order)
    else:
        ma.pattern = name
        # Parse the pattern flags (subset of dir.c parse_path_pattern).
        p = name
        if p.endswith("/"):
            ma.mustbedir = True
            p = p[:-1]
        ma.nodir = ("/" not in p)
        from .ignore import _wildmatch_to_regex
        import re as _re
        ma.regex = _re.compile("^" + _wildmatch_to_regex(p) + "$")
    # Parse the attribute state tokens.
    for tok in states.split():
        parsed = _parse_attr_token(tok)
        if parsed is None:
            return None  # invalid attr name in line -> whole line dropped
        nm, setto = parsed
        _attr_intern(nm, order)
        ma.states.append(_AttrState(nm, setto))
    return ma


def _attr_path_matches(ma: "_MatchAttr", path: str) -> bool:
    """Port of attr.c path_matches for a non-directory path (check-attr never
    queries directories), top-level .gitattributes (base = "")."""
    if ma.mustbedir:
        return False  # the queried path is treated as a file
    if ma.nodir:
        base = path.rsplit("/", 1)[-1]
        return ma.regex.match(base) is not None
    return ma.regex.match(path) is not None


def _load_attr_stack(repo: Repository) -> tuple[list["_MatchAttr"], list[str]]:
    """Build the effective attribute stack for top-level paths, in fill() order
    (innermost first): info/attributes, root .gitattributes, builtin macros.
    Returns (frames_in_fill_order, registration_order)."""
    order: list[str] = []

    def read_lines(lines):
        frame = []
        for line in lines:
            ma = _parse_attr_line(line, order)
            if ma is not None:
                frame.append(ma)
        return frame

    # Bottom of stack first (so registration order matches attr_nr): builtin,
    # then root .gitattributes, then info/attributes.
    builtin_frame = read_lines(_BUILTIN_ATTR)
    root_lines = []
    ga = repo.path / ".gitattributes"
    if ga.exists() and not ga.is_symlink():
        root_lines = ga.read_text(encoding="utf-8", errors="replace").splitlines()
    root_frame = read_lines(root_lines)
    info_lines = []
    info = repo.gitdir / "info" / "attributes"
    if info.exists():
        info_lines = info.read_text(encoding="utf-8", errors="replace").splitlines()
    info_frame = read_lines(info_lines)
    # fill() processes top-of-stack first: info, root, builtin.
    return [info_frame, root_frame, builtin_frame], order


def _attr_collect(frames, order, macros, path: str, names):
    """Port of attr.c collect_some_attrs/fill. Returns {attr_name: value}
    (value is one of the _ATTR_* sentinels or a string) for the given names
    (or all registered attributes when names is None)."""
    values = {n: _ATTR_UNKNOWN for n in order}

    def fill_one(ma: "_MatchAttr"):
        todo = list(reversed(ma.states))
        while todo:
            st = todo.pop()
            n = st.attr
            if values.get(n, _ATTR_UNKNOWN) is _ATTR_UNKNOWN:
                values[n] = st.setto
                # macro expansion: when an attr is a TRUE macro, push its states.
                if st.setto is _ATTR_TRUE and n in macros:
                    todo.extend(reversed(macros[n].states))

    for frame in frames:
        for ma in reversed(frame):
            if ma.is_macro:
                continue
            if _attr_path_matches(ma, path):
                fill_one(ma)
    return values


def _attr_value_str(value) -> str:
    if value is _ATTR_TRUE:
        return "set"
    if value is _ATTR_FALSE:
        return "unset"
    if value is _ATTR_UNSET or value is _ATTR_UNKNOWN:
        return "unspecified"
    return value


def _check_attr_error_with_usage(msg: str) -> int:
    _err(f"error: {msg}")
    _err(_CHECK_ATTR_USAGE)
    return 129


_CHECK_ATTR_USAGE = (
    "usage: git check-attr [--source <tree-ish>] [-a | --all | <attr>...] [--] <pathname>...\n"
    "   or: git check-attr --stdin [-z] [--source <tree-ish>] [-a | --all | <attr>...]\n"
    "\n"
    "    -a, --[no-]all        report all attributes set on file\n"
    "    --[no-]cached         use .gitattributes only from the index\n"
    "    --[no-]stdin          read file names from stdin\n"
    "    -z                    terminate input and output records by a NUL character\n"
    "    --[no-]source <tree-ish>\n"
    "                          which tree-ish to check attributes at\n"
    "\n"
)


def cmd_check_attr(argv: list[str]) -> int:
    # parse_options with PARSE_OPT_KEEP_DASHDASH: scan flags up to the first
    # non-option, keeping '--' in the remaining args.
    all_attrs = False
    cached_attrs = False
    stdin_paths = False
    nul_term_line = False
    source = None
    rest: list[str] = []
    i = 0
    n = len(argv)
    seen_dd = False
    while i < n:
        a = argv[i]
        if seen_dd:
            rest.append(a)
            i += 1
            continue
        if a == "--":
            rest.append(a)  # KEEP_DASHDASH
            seen_dd = True
            i += 1
            continue
        if a in ("-h", "--help"):
            sys.stdout.write(_CHECK_ATTR_USAGE)
            return 129
        if a in ("-a", "--all"):
            all_attrs = True
        elif a == "--no-all":
            all_attrs = False
        elif a == "--cached":
            cached_attrs = True
        elif a == "--no-cached":
            cached_attrs = False
        elif a == "--stdin":
            stdin_paths = True
        elif a == "--no-stdin":
            stdin_paths = False
        elif a == "-z":
            nul_term_line = True
        elif a == "--source":
            i += 1
            if i >= n:
                _err("error: option `source' requires a value")
                _err(_CHECK_ATTR_USAGE)
                return 129
            source = argv[i]
        elif a.startswith("--source="):
            source = a[len("--source="):]
        elif a.startswith("-") and a != "-":
            _err(f"error: unknown switch `{a.lstrip('-')[:1]}'" if not a.startswith("--")
                 else f"error: unknown option `{a[2:]}'")
            _err(_CHECK_ATTR_USAGE)
            return 129
        else:
            # First non-option: the rest are positionals.
            rest.append(a)
            i += 1
            while i < n:
                rest.append(argv[i])
                i += 1
            break
        i += 1

    args = rest
    argc = len(args)

    # Locate the first '--'.
    doubledash = -1
    for k in range(argc):
        if args[k] == "--":
            doubledash = k
            break

    if all_attrs:
        if doubledash >= 1:
            return _check_attr_error_with_usage("Attributes and --all both specified")
        cnt = 0
        filei = doubledash + 1
    elif doubledash == 0:
        return _check_attr_error_with_usage("No attribute specified")
    elif doubledash < 0:
        if argc == 0:
            return _check_attr_error_with_usage("No attribute specified")
        if stdin_paths:
            cnt = argc
            filei = argc
        else:
            cnt = 1
            filei = 1
    else:
        cnt = doubledash
        filei = doubledash + 1

    if stdin_paths:
        if filei < argc:
            return _check_attr_error_with_usage("Can't specify files with --stdin")
    else:
        if filei >= argc:
            return _check_attr_error_with_usage("No file specified")

    repo = _repo()

    attr_names = None
    if not all_attrs:
        attr_names = []
        for k in range(cnt):
            nm = args[k]
            if not _attr_name_valid(nm):
                _err(f"error: {nm}: not a valid attribute name")
                return 255
            attr_names.append(nm)

    # --source <tree-ish>: validate it peels to a tree; not otherwise modeled
    # here (the audit only exercises the no-commit error path).
    if source is not None:
        sha = refs_mod.rev_parse(repo, source)
        tree_ok = False
        if sha:
            try:
                typ, _data = objs.read_object(repo, sha)
                tree_ok = typ in ("tree", "commit", "tag")
            except Exception:
                tree_ok = False
        if not tree_ok:
            _err(f"fatal: {source}: not a valid tree-ish source")
            return 128

    frames, order = _load_attr_stack(repo)
    macros = {}
    for frame in frames:
        for ma in frame:
            if ma.is_macro and ma.macro_name not in macros:
                macros[ma.macro_name] = ma

    out = sys.stdout.buffer

    def emit(file: str) -> None:
        values = _attr_collect(frames, order, macros, file, attr_names)
        if all_attrs:
            keys = [k for k in order
                    if values.get(k, _ATTR_UNKNOWN) not in (_ATTR_UNSET, _ATTR_UNKNOWN)]
        else:
            keys = attr_names
        for k in keys:
            v = _attr_value_str(values.get(k, _ATTR_UNKNOWN))
            if nul_term_line:
                out.write(file.encode("utf-8", "surrogateescape") + b"\0"
                          + k.encode() + b"\0" + v.encode() + b"\0")
            else:
                out.write(_mt_quote_c_style(file)
                          + b": " + k.encode() + b": " + v.encode() + b"\n")

    if stdin_paths:
        getline_term = b"\0" if nul_term_line else b"\n"
        data = sys.stdin.buffer.read()
        if data:
            records = data.split(getline_term)
            if records and records[-1] == b"":
                records = records[:-1]
            for rec in records:
                line = rec.decode("utf-8", "surrogateescape")
                if not nul_term_line and line.startswith('"'):
                    line = _unquote_c_style(line)
                emit(line)
                out.flush()
    else:
        for k in range(filei, argc):
            emit(args[k])
        out.flush()
    return 0


# check-ref-format flags (refs.h).
_REFNAME_ALLOW_ONELEVEL = 0x01
_REFNAME_REFSPEC_PATTERN = 0x02

_CHECK_REF_FORMAT_USAGE = (
    "usage: git check-ref-format [--normalize] [<options>] <refname>\n"
    "   or: git check-ref-format --branch <branchname-shorthand>"
)


def _check_refname_component(refname: str, idx: int, flags: int):
    """Port of refs.c check_refname_component (validation mode).

    Returns (component_len, new_flags) starting at ``refname[idx]``, or
    (-1, flags) if the component is illegal. A component ends at '/' or EOS.
    """
    cp = idx
    last = ""
    n = len(refname)
    # refname_disposition: forbidden chars and special handling.
    forbidden = set("\x7f")  # DEL
    for c in range(0x20):
        forbidden.add(chr(c))  # ASCII control chars
    for c in ':?[\\^~ \t':
        forbidden.add(c)
    while cp < n:
        ch = refname[cp]
        if ch == "/":
            break  # end-of-component (disposition 1)
        if ch == ".":  # disposition 2
            if last == ".":
                return -1, flags  # "..": reject
        elif ch == "{":  # disposition 3
            if last == "@":
                return -1, flags  # "@{": reject
        elif ch == "*":  # disposition 5
            if not (flags & _REFNAME_REFSPEC_PATTERN):
                return -1, flags
            # Only accept a single '*' for one refspec side.
            flags &= ~_REFNAME_REFSPEC_PATTERN
        elif ch in forbidden:  # disposition 4
            return -1, flags
        last = ch
        cp += 1
    comp_len = cp - idx
    if comp_len == 0:
        return 0, flags  # zero-length component
    if refname[idx] == ".":  # component starts with '.'
        return -1, flags
    if comp_len >= 5 and refname[cp - 5:cp] == ".lock":  # ends with .lock
        return -1, flags
    return comp_len, flags


def _check_refname_format(refname: str, flags: int) -> int:
    """Port of refs.c check_or_sanitize_refname (validation mode).

    Returns 0 if the refname is legal, -1 otherwise.
    """
    if refname == "@":
        return -1
    component_count = 0
    idx = 0
    component_len = 0
    while True:
        component_len, flags = _check_refname_component(refname, idx, flags)
        if component_len <= 0:
            return -1
        component_count += 1
        # refname[component_len] == '\0' -> we consumed the whole string.
        if idx + component_len == len(refname):
            break
        # Skip the '/' separator to the next component.
        idx += component_len + 1
    # C: refname[component_len - 1] == '.' (last component's final char).
    last_component_end = idx + component_len
    if last_component_end >= 1 and refname[last_component_end - 1] == ".":
        return -1  # refname ends with '.'
    if not (flags & _REFNAME_ALLOW_ONELEVEL) and component_count < 2:
        return -1  # only one component
    return 0


def _check_ref_format_branch(arg: str) -> int:
    """Port of builtin/check-ref-format.c check_ref_format_branch."""
    try:
        repo = _repo()
    except RepositoryError:
        repo = None
    # copy_branchname(sb, name, INTERPRET_BRANCH_LOCAL): expand the leading
    # branch shorthand (@{-N}, '-'), else keep the literal name. Any other
    # @{...} form or a failed shorthand makes the name invalid.
    name = arg
    if arg == "-" or arg.startswith("@{"):
        prev = _switch_prev_branch(repo) if repo is not None else None
        if prev is None or arg not in ("-", "@{-1}"):
            _err(f"fatal: '{arg}' is not a valid branch name")
            return 128
        name = prev
        if name.startswith("refs/heads/"):
            name = name[len("refs/heads/"):]
    sb = "refs/heads/" + name
    if arg[:1] == "-" or sb == "refs/heads/HEAD":
        _err(f"fatal: '{arg}' is not a valid branch name")
        return 128
    if _check_refname_format(sb, 0) != 0 or not sb.startswith("refs/heads/"):
        _err(f"fatal: '{arg}' is not a valid branch name")
        return 128
    _print(sb[len("refs/heads/"):])
    return 0


def _collapse_slashes(refname: str) -> str:
    """Port of builtin/check-ref-format.c collapse_slashes: strip leading
    slashes and collapse runs of adjacent slashes to a single slash."""
    out = []
    prev = "/"
    for ch in refname:
        if prev == "/" and ch == "/":
            continue
        out.append(ch)
        prev = ch
    return "".join(out)


def cmd_check_ref_format(argv: list[str]) -> int:
    # show_usage_if_asked: -h / --help anywhere prints usage on stdout (rc 129).
    for a in argv:
        if a in ("-h", "--help"):
            sys.stdout.write(_CHECK_REF_FORMAT_USAGE + "\n")
            return 129
    # Manual scanner (mirrors builtin/check-ref-format.c). argc includes argv[0].
    full_argv = ["git"] + list(argv)
    argc = len(full_argv)
    if argc == 3 and full_argv[1] == "--branch":
        return _check_ref_format_branch(full_argv[2])
    normalize = False
    flags = 0
    i = 1
    while i < argc and full_argv[i][:1] == "-":
        a = full_argv[i]
        if a in ("--normalize", "--print"):
            normalize = True
        elif a == "--allow-onelevel":
            flags |= _REFNAME_ALLOW_ONELEVEL
        elif a == "--no-allow-onelevel":
            flags &= ~_REFNAME_ALLOW_ONELEVEL
        elif a == "--refspec-pattern":
            flags |= _REFNAME_REFSPEC_PATTERN
        else:
            _err(_CHECK_REF_FORMAT_USAGE)
            return 129
        i += 1
    if not (i == argc - 1):
        _err(_CHECK_REF_FORMAT_USAGE)
        return 129
    refname = full_argv[i]
    if normalize:
        refname = _collapse_slashes(refname)
    if _check_refname_format(refname, flags) != 0:
        return 1
    if normalize:
        _print(refname)
    return 0


def _mailmap_split_contact(contact: str) -> tuple[str, str]:
    """Port of ident.c split_ident_line for check-mailmap's needs.

    Returns (name, mail). When the contact has no '<', C check-mailmap sets
    name="" and treats the entire string as the mail address."""
    line = contact
    n = len(line)
    # Find the first '<' -> mail_begin (index just after it).
    mail_begin = -1
    for i in range(n):
        if line[i] == "<":
            mail_begin = i + 1
            break
    if mail_begin < 0:
        return "", contact  # split failed: whole string is the mail
    # name_end: scan back from mail_begin-2 for the last non-space char.
    name_end = 0  # default to name_begin (0) if no human-readable name
    cp = mail_begin - 2
    while cp >= 0:
        if not line[cp].isspace():
            name_end = cp + 1
            break
        cp -= 1
    # mail_end: first '>' at or after mail_begin.
    mail_end = -1
    for i in range(mail_begin, n):
        if line[i] == ">":
            mail_end = i
            break
    if mail_end < 0:
        return "", contact  # split failed: whole string is the mail
    name = line[0:name_end]
    mail = line[mail_begin:mail_end]
    return name, mail


def cmd_check_mailmap(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="pygit check-mailmap", add_help=False)
    ap.add_argument("--stdin", action="store_true")
    ap.add_argument("--mailmap-file", dest="mailmap_file", default=None)
    ap.add_argument("--mailmap-blob", dest="mailmap_blob", default=None)
    ap.add_argument("contacts", nargs="*")
    args = ap.parse_args(argv)
    if not args.contacts and not args.stdin:
        _err("fatal: no contacts specified")
        return 128
    repo = _repo()
    from . import mailmap as _mailmap
    mm = _mailmap.load(repo)
    # Additional sources, in C order: --mailmap-blob then --mailmap-file.
    if args.mailmap_blob:
        _mailmap._read_blob_into(mm, repo, args.mailmap_blob)
    if args.mailmap_file:
        _mailmap._read_file_into(mm, args.mailmap_file)

    def emit(c: str) -> None:
        name, email = _mailmap_split_contact(c)
        mn, me = mm.resolve(name, email)
        # C: prints "<name> " only when namelen != 0, then "<mail>".
        if mn:
            _print(f"{mn} <{me}>")
        else:
            _print(f"<{me}>")

    for c in args.contacts:
        emit(c)
    if args.stdin:
        for line in sys.stdin:
            emit(line.rstrip("\n"))
    return 0


_SHOW_INDEX_USAGE = (
    "usage: git show-index [--object-format=<hash-algorithm>] < <pack-idx-file>\n"
    "\n"
    "    --[no-]object-format <hash-algorithm>\n"
    "                          specify the hash algorithm to use\n"
    "\n"
)


def cmd_show_index(argv: list[str]) -> int:
    """Port of builtin/show-index.c: read a pack .idx from STDIN and print
    `<offset> <oid> (<crc32>)` per entry in idx (OID) order."""
    import struct as _struct

    object_format = None
    i = 0
    saw_dashdash = False
    while i < len(argv):
        a = argv[i]
        if not saw_dashdash and a == "-h":
            sys.stdout.write(_SHOW_INDEX_USAGE)
            return 129
        if saw_dashdash:
            pass  # positional; git ignores all positionals (reads stdin only)
        elif a == "--":
            saw_dashdash = True
        elif a == "--object-format" or a.startswith("--object-format="):
            if a == "--object-format":
                i += 1
                if i >= len(argv):
                    _err("error: option `object-format' requires a value")
                    sys.stderr.write(_SHOW_INDEX_USAGE)
                    return 129
                object_format = argv[i]
            else:
                object_format = a[len("--object-format="):]
        elif a.startswith("--"):
            _err(f"error: unknown option `{a[2:]}'")
            sys.stderr.write(_SHOW_INDEX_USAGE)
            return 129
        elif a.startswith("-") and a != "-":
            _err(f"error: unknown switch `{a[1]}'")
            sys.stderr.write(_SHOW_INDEX_USAGE)
            return 129
        # else: positional path -> ignored (git reads stdin regardless)
        i += 1

    if object_format is not None:
        if object_format not in ("sha1", "sha256"):
            _err("fatal: Unknown hash algorithm")
            return 128
        hashsz = 32 if object_format == "sha256" else 20
    else:
        try:
            hashsz = _repo().hash_len
        except RepositoryError:
            hashsz = 20

    data = sys.stdin.buffer.read()

    def die(msg: str) -> int:
        _err(f"fatal: {msg}")
        return 128

    pos = 0
    if len(data) < 8:
        return die("unable to read header")
    sig = data[0:4]
    if sig == b"\xfftOc":
        version = _struct.unpack(">I", data[4:8])[0]
        if version != 2:
            return die("unknown index version")
        pos = 8
        if len(data) < pos + 256 * 4:
            return die("unable to read index")
        top = [_struct.unpack(">I", data[pos + j * 4: pos + j * 4 + 4])[0] for j in range(256)]
        pos += 256 * 4
    else:
        version = 1
        # v1: first two words already consumed are top_index[0..1]; read 254 more
        if len(data) < 1024:
            return die("unable to read index")
        top = [_struct.unpack(">I", data[j * 4: j * 4 + 4])[0] for j in range(256)]
        pos = 1024

    nr = 0
    for n in top:
        if n < nr:
            return die("corrupt index file")
        nr = n

    if version == 1:
        for k in range(nr):
            if len(data) < pos + 4 + hashsz:
                return die(f"unable to read entry {k}/{nr}")
            offset = _struct.unpack(">I", data[pos:pos + 4])[0]
            oid = data[pos + 4:pos + 4 + hashsz].hex()
            pos += 4 + hashsz
            _print(f"{offset} {oid}")
        return 0

    # v2: oid table, then crc table, then 32-bit offset table, then 64-bit table.
    oids: list[str] = []
    for k in range(nr):
        if len(data) < pos + hashsz:
            return die(f"unable to read sha1 {k}/{nr}")
        oids.append(data[pos:pos + hashsz].hex())
        pos += hashsz
    crcs: list[int] = []
    for k in range(nr):
        if len(data) < pos + 4:
            return die(f"unable to read crc {k}/{nr}")
        crcs.append(_struct.unpack(">I", data[pos:pos + 4])[0])
        pos += 4
    off32: list[int] = []
    for k in range(nr):
        if len(data) < pos + 4:
            return die(f"unable to read 32b offset {k}/{nr}")
        off32.append(_struct.unpack(">I", data[pos:pos + 4])[0])
        pos += 4
    off64_nr = 0
    for k in range(nr):
        off = off32[k]
        if not (off & 0x80000000):
            offset = off
        else:
            if (off & 0x7FFFFFFF) != off64_nr:
                return die("inconsistent 64b offset index")
            if len(data) < pos + 8:
                return die(f"unable to read 64b offset {off64_nr}")
            offset = _struct.unpack(">Q", data[pos:pos + 8])[0]
            pos += 8
            off64_nr += 1
        _print(f"{offset} {oids[k]} ({crcs[k]:08x})")
    return 0


def cmd_unpack_file(argv: list[str]) -> int:
    """Write a blob to a temp file and print its path (like real git)."""
    ap = argparse.ArgumentParser(prog="pygit unpack-file")
    ap.add_argument("blob")
    args = ap.parse_args(argv)
    repo = _repo()
    sha = refs_mod.rev_parse(repo, args.blob)
    if not sha:
        return 128
    t, data = objs.read_object(repo, sha)
    if t != "blob":
        _err("not a blob")
        return 1
    import tempfile
    fd, path = tempfile.mkstemp(prefix=".merge_file_", dir=str(repo.path))
    with os.fdopen(fd, "wb") as f:
        f.write(data)
    _print(os.path.basename(path))
    return 0


def cmd_merge_index(argv: list[str]) -> int:
    """Run a merge driver program for each conflicted index entry.

    Invokes:  <driver> <path> <base-tempfile> <ours-tempfile> <theirs-tempfile>
    The driver may rewrite <path> in the worktree to commit a resolution.
    """
    ap = argparse.ArgumentParser(prog="pygit merge-index")
    ap.add_argument("-o", action="store_true",
                    help="continue past errors (mimics git's -o)")
    ap.add_argument("-a", "--all", action="store_true")
    ap.add_argument("driver")
    ap.add_argument("paths", nargs="*")
    args = ap.parse_args(argv)
    repo = _repo()
    from .index import read_index
    idx = read_index(repo)
    stages = idx.by_path_all_stages()
    targets = args.paths if args.paths else (idx.conflicted_paths() if args.all else [])
    if not targets:
        return 0

    import tempfile, subprocess
    rc = 0
    for p in targets:
        s = stages.get(p, {})
        if not any(k in (1, 2, 3) for k in s):
            continue
        tmps = []
        for stage in (1, 2, 3):
            if stage in s:
                _, data = objs.read_object(repo, s[stage].sha)
                fd, tmp = tempfile.mkstemp(prefix=f".{stage}.")
                with os.fdopen(fd, "wb") as f:
                    f.write(data)
                tmps.append(tmp)
            else:
                tmps.append("")
        try:
            r = subprocess.call([args.driver, p, *tmps])
            if r != 0:
                rc = r
                if not args.o:
                    return rc
        finally:
            for tmp in tmps:
                if tmp and os.path.exists(tmp):
                    os.unlink(tmp)
    return rc


def cmd_get_tar_commit_id(argv: list[str]) -> int:
    """Port of builtin/get-tar-commit-id.c.

    Reads exactly HEADERSIZE=1024 bytes (2 ustar records); fewer bytes is an EOF
    error (rc 128).  Then it requires a pax global-extended-header record
    (typeflag 'g' at offset 156) and parses a "<len> comment=<hash>\\n" record.
    """
    # show_usage_if_asked: -h prints usage to stdout (rc 129). git's cmd takes
    # argc==1 (just the command name), so ANY user argument is "too many" ->
    # usage(...) to stderr (rc 129).
    if argv and argv[0] in ("-h", "--help"):
        _print("usage: git get-tar-commit-id")
        return 129
    if argv:
        _err("usage: git get-tar-commit-id")
        return 129

    RECORDSIZE = 512
    HEADERSIZE = 2 * RECORDSIZE
    stdin_buf = getattr(sys.stdin, "buffer", None)
    if stdin_buf is not None:
        buffer = stdin_buf.read(HEADERSIZE)
    else:
        raw = sys.stdin.read()
        if isinstance(raw, str):
            raw = raw.encode("utf-8")
        buffer = raw[:HEADERSIZE]
    if len(buffer) != HEADERSIZE:
        # read_in_full short read leaves errno 0 -> die_errno appends ": Success".
        _err("fatal: git get-tar-commit-id: EOF before reading tar header: %s"
             % os.strerror(0))
        return 128
    if buffer[156:157] != b"g":  # TYPEFLAG_GLOBAL_HEADER
        return 1
    content = buffer[RECORDSIZE:]
    # strtol(content, &end, 10): parse a leading decimal, skipping leading ws.
    import re
    m = re.match(rb"\s*([+-]?\d+)", content)
    if not m:
        return 1
    try:
        length = int(m.group(1))
    except ValueError:
        return 1
    if length < 0:
        return 1
    end = m.end()
    if not content[end:].startswith(b" comment="):
        return 1
    comment_off = end + len(b" comment=")
    length -= comment_off
    # len must be >=1, odd, and (len-1)/2 must be a known hash raw size (20/32).
    if length < 1 or (length % 2) == 0 or ((length - 1) // 2) not in (20, 32):
        return 1
    sys.stdout.buffer.write(content[comment_off:comment_off + length])
    return 0


def cmd_hook(argv: list[str]) -> int:
    """Run or list git hooks under .git/hooks/."""
    ap = argparse.ArgumentParser(prog="pygit hook")
    sub = ap.add_subparsers(dest="action", required=True)
    p_run = sub.add_parser("run")
    p_run.add_argument("name")
    p_run.add_argument("hook_args", nargs="*")
    sub.add_parser("list")
    args = ap.parse_args(argv)
    repo = _repo()
    hooks_dir = repo.gitdir / "hooks"
    if args.action == "list":
        if hooks_dir.exists():
            for h in sorted(hooks_dir.iterdir()):
                if h.is_file() and os.access(h, os.X_OK):
                    _print(h.name)
        return 0
    if args.action == "run":
        hook = hooks_dir / args.name
        if not hook.exists() or not os.access(hook, os.X_OK):
            return 0  # silently succeed when hook absent — matches git
        import subprocess
        return subprocess.call([str(hook), *args.hook_args])
    return 1


def cmd_credential(argv: list[str]) -> int:
    """Minimal credential helper: read description from stdin and resolve credentials."""
    ap = argparse.ArgumentParser(prog="pygit credential")
    ap.add_argument("op", choices=["fill", "approve", "reject"])
    args = ap.parse_args(argv)
    fields: dict[str, str] = {}
    for line in sys.stdin.read().splitlines():
        if "=" in line:
            k, _, v = line.partition("=")
            fields[k] = v
    if args.op == "fill":
        from . import bridges
        fields = bridges.credential_fill(fields, use_external=False)
        for k in ("protocol", "host", "path", "username", "password"):
            if k in fields:
                _print(f"{k}={fields[k]}")
        return 0
    # approve / reject: no-op for the stub helper
    return 0


def _register_phase7() -> None:
    _COMMANDS["diff-tree"] = cmd_diff_tree
    _COMMANDS["diff-files"] = cmd_diff_files
    _COMMANDS["diff-index"] = cmd_diff_index
    _COMMANDS["check-attr"] = cmd_check_attr
    _COMMANDS["check-ref-format"] = cmd_check_ref_format
    _COMMANDS["check-mailmap"] = cmd_check_mailmap
    _COMMANDS["show-index"] = cmd_show_index
    _COMMANDS["unpack-file"] = cmd_unpack_file
    _COMMANDS["merge-index"] = cmd_merge_index
    _COMMANDS["get-tar-commit-id"] = cmd_get_tar_commit_id
    _COMMANDS["hook"] = cmd_hook
    _COMMANDS["credential"] = cmd_credential


_register_phase7()


